    loadAgents()
    initializeShowcaseDemos()
  }, [])

  const loadAgents = async () => {
    try {
      const allAgents = await agentOrchestrator.getAgents()
      const enabledAgents = allAgents.filter(a => a.isEnabled)
      setAgents(enabledAgents)

      // Calculate stats
      const totalCapabilities = enabledAgents.reduce((sum, agent) => sum + agent.capabilities.length, 0)
      setStats({
        totalAgents: enabledAgents.length,
        totalCapabilities,
        activeDemos: liveDemos.filter(d => d.status === 'running').length,
        successRate: liveDemos.length > 0 
          ? (liveDemos.filter(d => d.status === 'success').length / liveDemos.length) * 100 
