                      />

                      <div className="relative z-10">
                        <div className="flex items-start justify-between mb-3">
                          <div className={`w-10 h-10 rounded-lg bg-gradient-to-br ${category.color} flex items-center justify-center`}>
                            <i className={`${category.icon} text-xl text-white`}></i>
                          </div>
                          <span className="px-2 py-1 bg-green-500/20 text-green-400 text-xs rounded-lg">
                            Active
                          </span>
                        </div>

                        <h3 className="text-lg font-bold text-white mb-2">{agent.name}</h3>
                        <p className="text-sm text-white/70 mb-4 line-clamp-2">{agent.description}</p>

                        <div className="space-y-2">
                          <div className="flex items-center justify-between text-xs">
                            <span className="text-white/60">Capabilities</span>
                            <span className="text-cyan-400 font-semibold">{agent.capabilities.length}</span>
                          </div>
                          <div className="flex flex-wrap gap-1">
                            {agent.capabilities.slice(0, 3).map((cap) => (
                              <span
                                key={cap.id}
                                className="px-2 py-1 bg-white/10 text-white/70 text-xs rounded"
