              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div className="bg-white/5 rounded-xl p-4">
                  <p className="text-sm text-white/60 mb-1">Type</p>
                  <p className="text-white font-semibold">{selectedAgent.type}</p>
                </div>
                <div className="bg-white/5 rounded-xl p-4">
                  <p className="text-sm text-white/60 mb-1">Model</p>
                  <p className="text-white font-semibold">{selectedAgent.model || 'gpt-4o-mini'}</p>
