      case 'HIGH': return 'bg-orange-100 text-orange-800 border-orange-500'
      case 'MEDIUM': return 'bg-yellow-100 text-yellow-800 border-yellow-500'
      case 'LOW': return 'bg-blue-100 text-blue-800 border-blue-500'
