// Check if demo mode
function isDemoMode(): boolean {
  return process.env.NODE_ENV === 'development' || process.env.ENABLE_DEMO_DATA === 'true'
}

export async function GET(request: NextRequest) {
  try {
    // Clear previous tracking for fresh data
    dataSourceTracker.clear()

    const { searchParams } = new URL(request.url)
    const tenantId = searchParams.get('tenantId') || 'default-tenant'
    const includeDetails = searchParams.get('includeDetails') === 'true'

    const db = await getPrisma()
    const isDemo = isDemoMode()

    // Check database health first
    const dbHealth = await checkDatabaseHealth()
    const dbConnected = dbHealth.connected

    // ========================================================================
    // 1. INFRASTRUCTURE MONITORING
    // ========================================================================
    // Get async values first
    const redisCache = await (async () => {
      const redis = await getRedisService()
      const isConnected = redis.isConnected ? await redis.isConnected().catch(() => false) : false
      const stats = redis.getStats ? await redis.getStats().catch(() => ({ hitRate: 0, memoryUsage: '0 MB', keys: 0 })) : { hitRate: 0, memoryUsage: '0 MB', keys: 0 }

      // Track Redis data source
      dataSourceTracker.registerService('redis', isConnected)
      const redisSource = determineDataSource(isDemo, isConnected, stats.keys > 0)
      dataSourceTracker.trackMetric('infrastructure.redis', {
        source: redisSource,
        freshness: determineFreshness(new Date()),
        lastUpdated: new Date(),
        reliability: calculateReliability(redisSource, determineFreshness(new Date()), isConnected),
        notes: isConnected ? 'Redis connected' : 'Redis disconnected - using fallback',
      })

      return {
        status: isConnected ? 'connected' : 'disconnected',
        hitRate: isDemo ? 87.5 : stats.hitRate || 0,
        memoryUsage: isDemo ? '512 MB / 1 GB' : stats.memoryUsage || '0 MB',
        keys: isDemo ? 1250 : stats.keys || 0,
        _dataSource: redisSource,
      }
    })()

    const eventBusStats = await (async () => {
      const bus = await getEventBus()
      const stats = bus.getStats ? bus.getStats() : { totalEvents: 0, events24h: 0, subscribers: 0, throughput: 0 }
      const busConnected = stats.totalEvents > 0 || !isDemo

      // Track Event Bus data source
      dataSourceTracker.registerService('eventBus', busConnected)
      const busSource = determineDataSource(isDemo, busConnected, stats.totalEvents > 0)
      dataSourceTracker.trackMetric('infrastructure.eventBus', {
        source: busSource,
        freshness: determineFreshness(new Date()),
        lastUpdated: new Date(),
        reliability: calculateReliability(busSource, determineFreshness(new Date()), busConnected),
        notes: busConnected ? 'Event Bus active' : 'Event Bus inactive - using fallback',
      })

      return {
        totalEvents: isDemo ? 12500 : stats.totalEvents || 0,
        events24h: isDemo ? 850 : stats.events24h || 0,
        subscribers: isDemo ? 45 : stats.subscribers || 0,
        throughput: isDemo ? 125 : stats.throughput || 0,
        _dataSource: busSource,
      }
    })()

    // Get job queue stats with data source tracking
    const jobQueueStats = await (async () => {
      try {
        const total = await db.job.count({ where: { tenantId } }).catch(() => 0)
        const pending = await db.job.count({ where: { tenantId, status: 'PENDING' } }).catch(() => 0)
        const processing = await db.job.count({ where: { tenantId, status: 'PROCESSING' } }).catch(() => 0)
        const completed = await db.job.count({ where: { tenantId, status: 'COMPLETED' } }).catch(() => 0)
        const failed = await db.job.count({ where: { tenantId, status: 'FAILED' } }).catch(() => 0)
        const hasData = total > 0 || pending > 0 || processing > 0 || completed > 0

        const jobSource = determineDataSource(isDemo, dbConnected, hasData)
        dataSourceTracker.trackMetric('infrastructure.jobQueue', {
          source: jobSource,
          freshness: determineFreshness(new Date()),
          lastUpdated: new Date(),
          reliability: calculateReliability(jobSource, determineFreshness(new Date()), dbConnected),
          notes: hasData ? 'Job queue has data' : 'Job queue empty',
        })

        return {
          total: isDemo ? 45 : total,
          pending: isDemo ? 12 : pending,
          processing: isDemo ? 8 : processing,
          completed: isDemo ? 1250 : completed,
          failed: isDemo ? 3 : failed,
          avgProcessingTime: isDemo ? 1250 : 0,
          _dataSource: jobSource,
        }
      } catch (error) {
        const jobSource = determineDataSource(isDemo, false, false)
        return {
          total: isDemo ? 45 : 0,
          pending: isDemo ? 12 : 0,
          processing: isDemo ? 8 : 0,
          completed: isDemo ? 1250 : 0,
          failed: isDemo ? 3 : 0,
          avgProcessingTime: isDemo ? 1250 : 0,
          _dataSource: jobSource,
        }
      }
    })()

    // Track database metrics
    const dbSource = determineDataSource(isDemo, dbConnected, true)
    dataSourceTracker.trackMetric('infrastructure.database', {
      source: dbSource,
      freshness: determineFreshness(dbHealth.lastChecked),
      lastUpdated: dbHealth.lastChecked,
      reliability: calculateReliability(dbSource, determineFreshness(dbHealth.lastChecked), dbConnected),
      notes: dbConnected ? `Database connected (${dbHealth.connectionTime}ms)` : (dbHealth.error || 'Database disconnected'),
    })

    const infrastructure = {
      system: {
        nodeVersion: process.version,
        platform: process.platform,
        uptime: process.uptime(),
        memoryUsage: {
          rss: process.memoryUsage().rss,
          heapTotal: process.memoryUsage().heapTotal,
          heapUsed: process.memoryUsage().heapUsed,
          external: process.memoryUsage().external,
          arrayBuffers: process.memoryUsage().arrayBuffers,
        },
        cpuUsage: process.cpuUsage(),
        _dataSource: 'real' as const, // System metrics are always real
      },
      database: {
        status: dbConnected ? 'healthy' : 'disconnected',
        connectionPool: dbHealth.poolStatus || { active: 10, idle: 5, total: 15 },
        queryPerformance: {
          avgResponseTime: isDemo ? 45 : (dbHealth.queryPerformance?.avgResponseTime || 0),
          slowQueries: isDemo ? 2 : 0,
          totalQueries: isDemo ? 1250 : 0,
        },
        size: isDemo ? { total: '2.5 GB', growth: '+125 MB (24h)' } : { total: '0 GB', growth: '0 MB' },
        health: dbHealth,
        _dataSource: dbSource,
      },
      cache: {
        redis: redisCache,
      },
      jobQueue: jobQueueStats,
      eventBus: eventBusStats,
    }

    // ========================================================================
    // 2. MODULE DEEP DIVE (All 31+ Modules)
    // ========================================================================
    const modules = moduleRegistry.getEnabledModules()
    const moduleHealth = await Promise.allSettled(
      modules.map(async (module) => {
        try {
          const healthPromise = moduleManager.getModuleHealth(module.id)
          const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 2000))
          const health = await Promise.race([healthPromise, timeoutPromise]) as any
          return {
            moduleId: module.id,
            moduleName: module.name,
            description: module.description,
            status: health?.status || 'healthy',
            uptime: health?.uptime || 100,
            lastHealthCheck: health?.lastHealthCheck || new Date(),
            issues: health?.issues || [],
            metrics: health?.metrics || {
              responseTime: isDemo ? Math.random() * 100 + 20 : 0,
              errorRate: isDemo ? Math.random() * 2 : 0,
              requestCount: isDemo ? Math.floor(Math.random() * 1000) + 100 : 0,
            },
            routes: module.routes?.length || 0,
            dependencies: module.dependencies || [],
            dependents: modules.filter(m => m.dependencies?.includes(module.id)).map(m => m.id),
            category: module.category || 'general',
            features: module.routes?.map(r => r.title || r.path) || [],
            apiEndpoints: module.routes?.length || 0,
            components: module.components?.length || 0,
            services: module.services?.length || 0,
          }
        } catch (error) {
          return {
            moduleId: module.id,
            moduleName: module.name,
            description: module.description,
            status: 'healthy' as const,
            uptime: 100,
            lastHealthCheck: new Date(),
            issues: [],
            metrics: {
              responseTime: isDemo ? Math.random() * 100 + 20 : 0,
              errorRate: isDemo ? Math.random() * 2 : 0,
              requestCount: isDemo ? Math.floor(Math.random() * 500) + 50 : 0,
            },
            routes: module.routes?.length || 0,
            dependencies: module.dependencies || [],
            dependents: modules.filter(m => m.dependencies?.includes(module.id)).map(m => m.id),
            category: module.category || 'general',
            features: module.routes?.map(r => r.title || r.path) || [],
            apiEndpoints: module.routes?.length || 0,
            components: module.components?.length || 0,
            services: module.services?.length || 0,
          }
        }
      })
    ).then(results => results.map(r => r.status === 'fulfilled' ? r.value : null).filter(Boolean))

    // Module categories summary
    const moduleCategories = moduleHealth.reduce((acc, module) => {
      const category = module.category || 'other'
      if (!acc[category]) acc[category] = { total: 0, healthy: 0, degraded: 0, unhealthy: 0, modules: [] }
      acc[category].total++
      acc[category].modules.push(module.moduleId)
      if (module.status === 'healthy') acc[category].healthy++
      else if (module.status === 'degraded') acc[category].degraded++
      else if (module.status === 'unhealthy') acc[category].unhealthy++
      return acc
    }, {} as Record<string, { total: number; healthy: number; degraded: number; unhealthy: number; modules: string[] }>)

    // ========================================================================
    // 3. USERS & SESSIONS
    // ========================================================================
    const userStats = await db.user.groupBy({ by: ['role', 'status'], _count: { id: true }, where: { tenantId } }).catch(() => [])
    const totalUsers = await db.user.count({ where: { tenantId } }).catch(() => isDemo ? 125 : 0)
    const activeUsers = await db.user.count({ where: { tenantId, status: 'ACTIVE' } }).catch(() => isDemo ? 98 : 0)
    const recentLogins = await db.user.count({ where: { tenantId, lastLogin: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } } }).catch(() => isDemo ? 45 : 0)
    const activeSessions = await db.session.count({ where: { tenantId, expiresAt: { gt: new Date() } } }).catch(() => isDemo ? 32 : 0)
    const sessions = await db.session.findMany({ where: { tenantId, expiresAt: { gt: new Date() } }, take: 20, orderBy: { createdAt: 'desc' } }).catch(() => [])

    // Track users data source
    const usersHasData = totalUsers > 0 || activeUsers > 0
    const usersSource = determineDataSource(isDemo, dbConnected, usersHasData)
    dataSourceTracker.trackMetric('users', {
      source: usersSource,
      freshness: determineFreshness(new Date()),
      lastUpdated: new Date(),
      reliability: calculateReliability(usersSource, determineFreshness(new Date()), dbConnected),
      notes: usersHasData ? `Found ${totalUsers} users` : 'No users found',
    })

    const users = {
      total: totalUsers,
      active: activeUsers,
      recentLogins,
      activeSessions,
      byRole: userStats.reduce((acc, stat) => { acc[stat.role] = (acc[stat.role] || 0) + stat._count.id; return acc }, {} as Record<string, number>),
      byStatus: userStats.reduce((acc, stat) => { acc[stat.status] = (acc[stat.status] || 0) + stat._count.id; return acc }, {} as Record<string, number>),
      recentSessions: sessions.map(s => ({
        userId: s.userId,
        ipAddress: s.ipAddress,
        userAgent: s.userAgent,
        createdAt: s.createdAt,
        expiresAt: s.expiresAt,
      })),
      _dataSource: usersSource,
    }

    // ========================================================================
    // 4. SECURITY & COMPLIANCE
    // ========================================================================
    const apiKeys = await db.aPIKey.count({ where: { tenantId, revoked: false } }).catch(() => isDemo ? 15 : 0)
    const auditLogs24h = await db.auditLog.count({ where: { tenantId, createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } } }).catch(() => isDemo ? 1250 : 0)
    const securityEvents = await db.auditLog.count({ where: { tenantId, action: { contains: 'SECURITY' }, createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } } }).catch(() => isDemo ? 12 : 0)
    const failedLogins = await db.auditLog.count({ where: { tenantId, action: { contains: 'LOGIN_FAILED' }, createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } } }).catch(() => isDemo ? 3 : 0)

    const security = {
      activeSessions,
      apiKeys,
      securityEvents24h: securityEvents,
