interface Approval {
  id: string
  type: 'CAPA' | 'NCR' | 'Document' | 'Risk' | 'Training'
  title: string
  submittedBy: string
  submittedDate: string
  priority: 'Low' | 'Medium' | 'High' | 'Critical'
  status: 'pending' | 'approved' | 'rejected' | 'more_info_requested'
