  const [reviewNotes, setReviewNotes] = useState('')
  const [filterType, setFilterType] = useState('all')

  useEffect(() => {
    fetchApprovals()
  }, [])

  const fetchApprovals = async () => {
    try {
      // Fetch pending approvals from various modules
      const [capas, ncrs, documents] = await Promise.all([
        fetch('/api/erpnext/capas').then(r => r.json()).catch(() => ({ data: [] })),
        fetch('/api/erpnext/ncrs').then(r => r.json()).catch(() => ({ data: [] })),
        fetch('/api/erpnext/documents').then(r => r.json()).catch(() => ({ documents: [] }))
      ])

      const pendingApprovals: Approval[] = []

      // CAPAs pending approval
      if (capas.data) {
        capas.data
          .filter((c: any) => c.status === 'Under Review' || c.status === 'Open')
          .forEach((capa: any) => {
            pendingApprovals.push({
              id: capa.name,
              type: 'CAPA',
              title: capa.subject,
              submittedBy: capa.owner || 'System',
              submittedDate: capa.creation || new Date().toISOString(),
              priority: (capa.priority || 'Medium') as Approval['priority'],
              status: 'pending',
              moduleUrl: '/capa-management'
            })
          })
      }

      // NCRs pending approval
      if (ncrs.data) {
        ncrs.data
          .filter((n: any) => n.status === 'Open' || n.status === 'Under Investigation')
          .forEach((ncr: any) => {
            pendingApprovals.push({
              id: ncr.name,
              type: 'NCR',
              title: ncr.subject,
              submittedBy: ncr.reported_by || 'System',
              submittedDate: ncr.creation || new Date().toISOString(),
              priority: (ncr.priority || 'Medium') as Approval['priority'],
              status: 'pending',
              moduleUrl: '/ncr-management'
            })
          })
      }

      setApprovals(pendingApprovals.length > 0 ? pendingApprovals : generateMockApprovals())
