          )}

          {activeTab === 'analytics' && (
            <motion.div
              key="analytics"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
            >
              <ChemicalAnalyticsTab chemicals={chemicals} />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </PageTemplate>
  )
}

