        <>
          {selectedCount && selectedItem ? (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              <RealTimeCountingInterface
                item={selectedItem}
                onCountEntered={(qty) => {
                  handleEnterCount(selectedItem, qty)
                  // Update selectedItem with the latest data
                  const updatedCount = counts.find(c => c.id === selectedCount.id)
                  if (updatedCount) {
                    const updatedItem = updatedCount.items.find(i => i.id === selectedItem.id)
                    if (updatedItem) {
                      setSelectedItem(updatedItem)
                    }
                  }
                }}
                onComplete={() => {
                  const updatedCount = counts.find(c => c.id === selectedCount.id)
                  if (!updatedCount) return

                  const nextItem = updatedCount.items.find(item =>
                    item.status === 'PENDING' || item.status === 'COUNTING'
                  )
                  if (nextItem) {
                    setSelectedItem(nextItem)
                    setSelectedCount(updatedCount)
                  } else {
                    handleCompleteCount(updatedCount)
                    setViewMode('table')
                    setSelectedCount(null)
                    setSelectedItem(null)
                  }
                }}
                onSkip={() => {
                  const updatedCount = counts.find(c => c.id === selectedCount.id)
                  if (!updatedCount) return

                  const nextItem = updatedCount.items.find(item =>
                    item.status === 'PENDING' || item.status === 'COUNTING'
                  )
                  if (nextItem) {
                    setSelectedItem(nextItem)
                    setSelectedCount(updatedCount)
                  }
                }}
                blindCount={selectedCount.parameters.blindCount}
              />
              <VarianceAnalysis
                item={selectedItem}
                rootCauseAnalysis={selectedCount.rootCauseAnalysis?.find(rca => rca.itemId === selectedItem.id)}
                onAnalyze={() => {
                  handleAnalyzeRootCause(selectedItem)
                  // Refresh selectedCount after analysis
                  const updatedCount = counts.find(c => c.id === selectedCount.id)
                  if (updatedCount) {
                    setSelectedCount(updatedCount)
                  }
                }}
              />
            </div>
          ) : (
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-12 text-center">
              <i className="ri-scanner-line text-6xl text-[#9ca3af] mb-4"></i>
              <h3 className="text-xl font-semibold text-white mb-2">No Count Selected</h3>
              <p className="text-[#9ca3af] mb-6">Select a count from the table or grid view to start counting</p>
              <button
                onClick={() => setViewMode('table')}
                className="bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white px-6 py-3 rounded-lg font-medium transition-colors"
              >
                <i className="ri-table-line mr-2"></i>
                Go to Table View
              </button>
            </div>
          )}
        </>
      )}

      {viewMode === 'grid' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredCounts.map((count, index) => (
            <motion.div
              key={count.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
              onClick={() => setSelectedCount(count)}
              className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 hover:border-cyan-500/50 hover:shadow-lg hover:shadow-cyan-500/20 transition-all cursor-pointer"
            >
              <div className="flex items-start justify-between mb-4">
                <div>
                  <div className="text-lg font-semibold text-white font-mono mb-1">{count.countNumber}</div>
                  <div className="text-xs text-cyan-400 font-medium">{count.countType.replace('_', ' ')}</div>
                </div>
                <span className={`px-2 py-1 rounded text-xs font-medium ${count.status === 'COMPLETED' || count.status === 'ADJUSTED'
                  ? 'bg-green-500/20 text-green-400 border border-green-500/30'
                  : count.status === 'IN_PROGRESS'
                    ? 'bg-blue-500/20 text-blue-400 border border-blue-500/30'
                    : count.status === 'ASSIGNED'
                      ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/30'
                      : 'bg-gray-500/20 text-gray-400 border border-gray-500/30'
                  }`}>
                  {count.status}
                </span>
              </div>

              <div className="space-y-3 mb-4">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-[#9ca3af]">Items</span>
                  <span className="text-xs text-white font-medium">{count.countedItems}/{count.totalItems}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-[#9ca3af]">Accuracy</span>
                  <span className="text-xs text-green-400 font-medium">{count.results.accuracyRate.toFixed(1)}%</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-[#9ca3af]">Variance</span>
                  <span className={`text-xs font-medium ${Math.abs(count.results.averageVariance) <= 1 ? 'text-green-400' :
                    Math.abs(count.results.averageVariance) <= 5 ? 'text-yellow-400' :
                      'text-red-400'
                    }`}>
                    {count.results.averageVariance > 0 ? '+' : ''}{count.results.averageVariance.toFixed(2)}%
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs text-[#9ca3af]">Assigned To</span>
                  <span className="text-xs text-white">{count.assignedToName || 'N/A'}</span>
                </div>
              </div>

              <div className="mb-4">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs text-[#9ca3af]">Progress</span>
                  <span className="text-xs text-white font-medium">{count.completionPercentage.toFixed(0)}%</span>
                </div>
                <div className="w-full bg-white/10 rounded-full h-2">
                  <div
                    className="bg-gradient-to-r from-cyan-500 to-blue-600 h-2 rounded-full transition-all"
                    style={{ width: `${count.completionPercentage}%` }}
                  ></div>
                </div>
              </div>

              {count.results.itemsWithVariance > 0 && (
                <div className="pt-4 border-t border-white/10">
