            </motion.div>
          </div>

          {/* Sentiment Flow */}
          <div className="bg-white/5 backdrop-blur-xl rounded-xl p-6 border border-white/10">
            <h3 className="text-lg font-semibold text-white mb-4">Sentiment Flow</h3>
            <SentimentFlow
              data={data.sentimentFlowData}
              showPredictions={true}
              realTime={true}
            />
          </div>

          {/* Top Predictions */}
          <div className="bg-white/5 backdrop-blur-xl rounded-xl p-6 border border-white/10">
            <h3 className="text-lg font-semibold text-white mb-4">Top Predictions</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {data.predictions.slice(0, 4).map((prediction, idx) => (
                <BehavioralPredictionCard
                  key={idx}
                  prediction={prediction}
                  onActionClick={action => {
                    console.log('Action clicked:', action)
