/**
 * Visual Facility Mapping Page
 * Interactive floor plans with container placement and 3D visualization
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import FacilityMap from '@/components/facility/FacilityMap'
import FloorPlanEditor from '@/components/facility/FloorPlanEditor'
import Modal from '@/components/Modal'
import { Facility, Floor, Zone, ContainerPlacement } from '@/lib/services/facility/facilityMappingService'
import { facilityMappingService } from '@/lib/services/facility/facilityMappingService'
import { containerService } from '@/lib/services/chemical/containerService'

type ViewMode = '2d' | '3d' | 'satellite'
type TabType = 'map' | 'floors' | 'zones' | 'containers' | 'emergency'

export default function FacilityMappingPage() {
  const [facilities, setFacilities] = useState<Facility[]>([])
  const [selectedFacility, setSelectedFacility] = useState<Facility | null>(null)
  const [selectedFloor, setSelectedFloor] = useState<Floor | null>(null)
  const [viewMode, setViewMode] = useState<ViewMode>('2d')
  const [activeTab, setActiveTab] = useState<TabType>('map')
  const [showCreateFacility, setShowCreateFacility] = useState(false)
  const [showEditFloor, setShowEditFloor] = useState(false)
  const [selectedContainer, setSelectedContainer] = useState<ContainerPlacement | null>(null)
  const [selectedZone, setSelectedZone] = useState<Zone | null>(null)
  const [emergencyMap, setEmergencyMap] = useState<any>(null)

  useEffect(() => {
    loadFacilities()
  }, [])

  useEffect(() => {
    if (selectedFacility && selectedFacility.floors.length > 0) {
      setSelectedFloor(selectedFacility.floors[0])
    }
  }, [selectedFacility])

  useEffect(() => {
    if (selectedFacility && selectedFloor) {
      loadEmergencyMap()
    }
  }, [selectedFacility, selectedFloor])

  const loadFacilities = async () => {
    try {
      const result = await facilityMappingService.getAllFacilities()
      setFacilities(result)
      if (result.length > 0 && !selectedFacility) {
        setSelectedFacility(result[0])
      }
    } catch (error) {
      console.error('Error loading facilities:', error)
    }
  }

  const loadEmergencyMap = async () => {
    if (!selectedFacility || !selectedFloor) return

    try {
      const map = await facilityMappingService.generateEmergencyMap(
        selectedFacility.id,
        selectedFloor.id
      )
      setEmergencyMap(map)
    } catch (error) {
      console.error('Error loading emergency map:', error)
    }
  }

  const handleContainerPlace = async (containerId: string, coordinates: { x: number; y: number }) => {
    if (!selectedFacility || !selectedFloor) return

    try {
      const container = selectedFloor.containers.find(c => c.containerId === containerId)
      if (!container) return

      await facilityMappingService.placeContainer(selectedFacility.id, selectedFloor.id, {
        ...container,
        coordinates,
        status: 'placed',
        placedAt: new Date(),
        placedBy: 'current-user', // TODO: Get from auth
      })

      // Reload facility
      const updated = await facilityMappingService.getFacility(selectedFacility.id)
      if (updated) {
        setSelectedFacility(updated)
        setSelectedFloor(updated.floors.find(f => f.id === selectedFloor.id) || updated.floors[0])
      }
    } catch (error) {
      console.error('Error placing container:', error)
    }
  }

  const tabs = [
    { id: 'map' as TabType, label: 'Map View', icon: 'ri-map-line' },
    { id: 'floors' as TabType, label: 'Floors', icon: 'ri-building-line' },
    { id: 'zones' as TabType, label: 'Zones', icon: 'ri-layout-grid-line' },
    { id: 'containers' as TabType, label: 'Containers', icon: 'ri-box-line' },
    { id: 'emergency' as TabType, label: 'Emergency', icon: 'ri-alert-line' },
  ]

  return (
    <PageTemplate
      title="Facility Mapping"
      description="Interactive floor plans with container placement and emergency response"
      icon="ri-map-2-line"
    >
      <div className="space-y-6">
        {/* Facility Selector */}
        <div className="bg-gray-800 rounded-xl p-6 border border-gray-700">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-white">Facilities</h3>
            <button
              onClick={() => setShowCreateFacility(true)}
              className="px-4 py-2 rounded-lg bg-cyan-500 hover:bg-cyan-600 text-white font-semibold transition flex items-center gap-2"
            >
              <i className="ri-add-line"></i>
              New Facility
            </button>
          </div>
          <div className="flex flex-wrap gap-2">
            {facilities.map(facility => (
              <button
                key={facility.id}
                onClick={() => setSelectedFacility(facility)}
                className={`px-4 py-2 rounded-lg transition ${
                  selectedFacility?.id === facility.id
                    ? 'bg-cyan-500 text-white'
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                {facility.name}
              </button>
            ))}
          </div>
        </div>

        {selectedFacility && (
          <>
            {/* Floor Selector */}
            <div className="bg-gray-800 rounded-xl p-4 border border-gray-700">
              <div className="flex items-center gap-2">
                <span className="text-sm text-gray-400">Floor:</span>
                {selectedFacility.floors.map(floor => (
                  <button
                    key={floor.id}
                    onClick={() => setSelectedFloor(floor)}
                    className={`px-4 py-2 rounded-lg transition ${
                      selectedFloor?.id === floor.id
                        ? 'bg-cyan-500 text-white'
                        : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                    }`}
                  >
                    {floor.name}
                  </button>
                ))}
                <button
                  onClick={() => setShowEditFloor(true)}
                  className="ml-auto px-4 py-2 rounded-lg bg-gray-700 hover:bg-gray-600 text-white transition"
                >
                  <i className="ri-edit-line"></i>
                </button>
              </div>
            </div>

            {/* View Mode Toggle */}
            <div className="flex items-center justify-end gap-2">
              <button
                onClick={() => setViewMode('2d')}
                className={`px-4 py-2 rounded-lg transition ${
                  viewMode === '2d'
                    ? 'bg-cyan-500 text-white'
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                2D
              </button>
              <button
                onClick={() => setViewMode('3d')}
                className={`px-4 py-2 rounded-lg transition ${
                  viewMode === '3d'
                    ? 'bg-cyan-500 text-white'
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                3D
              </button>
            </div>

            {/* Tabs */}
            <div className="flex items-center gap-2 border-b border-gray-700">
              {tabs.map(tab => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`px-4 py-3 flex items-center gap-2 font-medium transition ${
                    activeTab === tab.id
                      ? 'text-cyan-400 border-b-2 border-cyan-400'
                      : 'text-gray-400 hover:text-gray-300'
                  }`}
                >
                  <i className={tab.icon}></i>
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Tab Content */}
            <AnimatePresence mode="wait">
              {activeTab === 'map' && selectedFloor && (
                <motion.div
                  key="map"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  className="bg-gray-800 rounded-xl p-6 border border-gray-700"
                >
                  <div className="h-[600px]">
                    <FacilityMap
                      facility={selectedFacility}
                      floor={selectedFloor}
                      onContainerClick={setSelectedContainer}
                      onZoneClick={setSelectedZone}
                      onContainerPlace={handleContainerPlace}
                      viewMode={viewMode}
                      interactive={true}
                    />
                  </div>
                </motion.div>
              )}

              {activeTab === 'zones' && selectedFloor && (
                <motion.div
                  key="zones"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  className="space-y-4"
                >
                  {selectedFloor.zones.map(zone => (
                    <div
                      key={zone.id}
                      className="bg-gray-800 rounded-xl p-6 border border-gray-700"
                    >
                      <div className="flex items-start justify-between mb-4">
                        <div>
                          <h4 className="text-lg font-semibold text-white">{zone.name}</h4>
                          <p className="text-sm text-gray-400">{zone.type}</p>
                        </div>
                        <div
                          className="w-8 h-8 rounded"
                          style={{ backgroundColor: zone.color }}
                        />
                      </div>
                      <div className="grid md:grid-cols-3 gap-4">
                        <div>
                          <p className="text-sm text-gray-400">Capacity</p>
                          <p className="text-lg font-semibold text-white">
                            {zone.currentOccupancy} / {zone.capacity}
                          </p>
                        </div>
                        <div>
                          <p className="text-sm text-gray-400">Location</p>
                          <p className="text-lg font-semibold text-white">
                            ({zone.coordinates.x}, {zone.coordinates.y})
                          </p>
                        </div>
                        <div>
                          <p className="text-sm text-gray-400">Size</p>
                          <p className="text-lg font-semibold text-white">
                            {zone.coordinates.width}m × {zone.coordinates.height}m
                          </p>
                        </div>
                      </div>
                    </div>
                  ))}
                </motion.div>
              )}

              {activeTab === 'emergency' && emergencyMap && (
                <motion.div
                  key="emergency"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  className="space-y-6"
                >
                  <div className="bg-red-900/20 border border-red-500/30 rounded-xl p-6">
                    <h3 className="text-lg font-semibold text-red-400 mb-4 flex items-center gap-2">
                      <i className="ri-alert-line"></i>
                      Emergency Response Map
                    </h3>
                    <div className="grid md:grid-cols-2 gap-4">
                      <div>
                        <h4 className="font-semibold text-white mb-2">Emergency Exits</h4>
                        <ul className="space-y-1">
                          {emergencyMap.emergencyExits.map((exit: any, idx: number) => (
                            <li key={idx} className="text-sm text-gray-300">
                              {exit.label}: ({exit.x}, {exit.y})
                            </li>
                          ))}
                        </ul>
                      </div>
                      <div>
                        <h4 className="font-semibold text-white mb-2">Assembly Points</h4>
                        <ul className="space-y-1">
                          {emergencyMap.assemblyPoints.map((point: any, idx: number) => (
                            <li key={idx} className="text-sm text-gray-300">
                              {point.label}: ({point.x}, {point.y})
                            </li>
                          ))}
                        </ul>
                      </div>
                      <div>
                        <h4 className="font-semibold text-white mb-2">Fire Extinguishers</h4>
                        <ul className="space-y-1">
                          {emergencyMap.fireExtinguishers.map((ext: any, idx: number) => (
                            <li key={idx} className="text-sm text-gray-300">
                              {ext.type} at ({ext.x}, {ext.y})
                            </li>
                          ))}
                        </ul>
                      </div>
                      <div>
                        <h4 className="font-semibold text-white mb-2">Hazardous Areas</h4>
                        <ul className="space-y-1">
                          {emergencyMap.hazardousAreas.map((zone: Zone, idx: number) => (
                            <li key={idx} className="text-sm text-gray-300">
                              {zone.name}
                            </li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </>
        )}

        {/* Edit Floor Modal */}
        {showEditFloor && selectedFloor && (
          <Modal
            isOpen={showEditFloor}
            onClose={() => setShowEditFloor(false)}
            title="Edit Floor Plan"
            size="xl"
          >
            <FloorPlanEditor
              floor={selectedFloor}
              onSave={async (updatedFloor) => {
                if (selectedFacility) {
                  const updatedFloors = selectedFacility.floors.map(f =>
                    f.id === updatedFloor.id ? updatedFloor : f
                  )
                  await facilityMappingService.saveFacility({
                    ...selectedFacility,
                    floors: updatedFloors,
                  })
                  await loadFacilities()
                  setShowEditFloor(false)
                }
              }}
              onCancel={() => setShowEditFloor(false)}
            />
          </Modal>
        )}
      </div>
    </PageTemplate>
  )
}

/**
 * Feature Registry Dashboard
 * View and manage all registered features
 */

'use client';

import { useState, useEffect } from 'react';
import { FeatureDefinition, FeatureDomain, FeatureStatus } from '@/lib/feature-registry/types';

export default function FeatureRegistryPage() {
  const [features, setFeatures] = useState<FeatureDefinition[]>([]);
  const [completeness, setCompleteness] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(true);
  const [selectedDomain, setSelectedDomain] = useState<FeatureDomain | 'all'>('all');
  const [selectedStatus, setSelectedStatus] = useState<FeatureStatus | 'all'>('all');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    loadFeatures();
  }, [selectedDomain, selectedStatus, searchQuery]);

  async function loadFeatures() {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (selectedDomain !== 'all') params.append('domain', selectedDomain);
      if (selectedStatus !== 'all') params.append('status', selectedStatus);
      if (searchQuery) params.append('search', searchQuery);

      const response = await fetch(`/api/feature-registry?${params.toString()}`);
      const data = await response.json();
      
      setFeatures(data.features || []);
      setCompleteness(data.completeness || {});
    } catch (error) {
      console.error('Error loading features:', error);
    } finally {
      setLoading(false);
    }
  }

  const domains: FeatureDomain[] = [
    'wms', 'tms', 'qhse', 'procurement', 'trade-compliance', 'truth-engine',
    'hazalyze', 'maas', 'compliance', 'finance', 'crm', 'digital-signature',
    'marketplace', 'warehouse-network', 'facility-management', 'project-management',
    'proposals-rfq', 'hr', 'iot', 'business-intelligence', 'communication', 'platform', 'other'
  ];

  const statuses: FeatureStatus[] = ['implemented', 'partial', 'stub', 'missing', 'planned'];

  return (
    <div className="min-h-screen bg-black text-white p-6">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-3xl font-bold mb-6">Feature Registry</h1>
        <p className="text-gray-400 mb-8">
          Single source of truth for all features in BlueDXP platform
        </p>

        {/* Filters */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <div>
            <label className="block text-sm font-medium mb-2">Domain</label>
            <select
              value={selectedDomain}
              onChange={(e) => setSelectedDomain(e.target.value as FeatureDomain | 'all')}
              className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2 text-white"
            >
              <option value="all">All Domains</option>
              {domains.map(domain => (
                <option key={domain} value={domain}>{domain.toUpperCase()}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Status</label>
            <select
              value={selectedStatus}
              onChange={(e) => setSelectedStatus(e.target.value as FeatureStatus | 'all')}
              className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2 text-white"
            >
              <option value="all">All Statuses</option>
              {statuses.map(status => (
                <option key={status} value={status}>{status}</option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Search</label>
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search features..."
              className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2 text-white"
            />
          </div>
        </div>

        {/* Completeness Stats */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {Object.entries(completeness).slice(0, 8).map(([domain, stats]: [string, any]) => (
            <div key={domain} className="bg-white/5 border border-white/10 rounded-lg p-4">
              <div className="text-sm text-gray-400 mb-1">{domain.toUpperCase()}</div>
              <div className="text-2xl font-bold">{stats.implemented}/{stats.total}</div>
              <div className="text-xs text-gray-500">{stats.percentage.toFixed(1)}% complete</div>
            </div>
          ))}
        </div>

        {/* Features List */}
        {loading ? (
          <div className="text-center py-12">Loading features...</div>
        ) : (
          <div className="space-y-4">
            {features.length === 0 ? (
              <div className="text-center py-12 text-gray-400">
                No features found. Run auto-discovery to register features.
              </div>
            ) : (
              features.map(feature => (
                <div
                  key={feature.id}
                  className="bg-white/5 border border-white/10 rounded-lg p-6 hover:border-cyan-400/50 transition-colors"
                >
                  <div className="flex items-start justify-between mb-4">
                    <div>
                      <h3 className="text-xl font-semibold mb-2">{feature.name}</h3>
                      <p className="text-gray-400 text-sm">{feature.description}</p>
                    </div>
                    <div className="flex gap-2">
                      <span className={`px-3 py-1 rounded-full text-xs ${
                        feature.status === 'implemented' ? 'bg-green-500/20 text-green-400' :
                        feature.status === 'partial' ? 'bg-yellow-500/20 text-yellow-400' :
                        feature.status === 'missing' ? 'bg-red-500/20 text-red-400' :
                        'bg-gray-500/20 text-gray-400'
                      }`}>
                        {feature.status}
                      </span>
                      <span className="px-3 py-1 rounded-full text-xs bg-cyan-500/20 text-cyan-400">
                        {feature.domain}
                      </span>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                    {feature.apis && feature.apis.length > 0 && (
                      <div>
                        <div className="text-gray-400 mb-1">APIs</div>
                        <div className="text-white">{feature.apis.length}</div>
                      </div>
                    )}
                    {feature.uiSurfaces && feature.uiSurfaces.length > 0 && (
                      <div>
                        <div className="text-gray-400 mb-1">UI Surfaces</div>
                        <div className="text-white">{feature.uiSurfaces.length}</div>
                      </div>
                    )}
                    {feature.entities && feature.entities.length > 0 && (
                      <div>
                        <div className="text-gray-400 mb-1">Entities</div>
                        <div className="text-white">{feature.entities.length}</div>
                      </div>
                    )}
                    {feature.tests && feature.tests.length > 0 && (
                      <div>
                        <div className="text-gray-400 mb-1">Tests</div>
                        <div className="text-white">{feature.tests.length}</div>
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Financial Reports Page
 * Professional financial reporting with P&L, Balance Sheet, Cash Flow
 */

'use client'

import { useEffect, useState } from 'react'
import { RiFileChartLine, RiFileDownloadLine, RiPrinterLine } from 'react-icons/ri'

export default function FinancialReportsPage() {
  const [selectedReport, setSelectedReport] = useState<string>('profit_loss')
  const [reportData, setReportData] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [period, setPeriod] = useState({
    startDate: new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0],
  })

  const fetchReport = async (reportType: string) => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        tenantId: 'default',
        type: reportType,
        startDate: period.startDate,
        endDate: period.endDate,
      })
      const response = await fetch(`/api/finance/reports?${params}`)
      const data = await response.json()
      if (data.success) {
        setReportData(data.data)
      }
    } catch (error) {
      console.error('Error fetching report:', error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (selectedReport) {
      fetchReport(selectedReport)
    }
  }, [selectedReport, period])

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-SA', {
      style: 'currency',
      currency: 'SAR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 2,
    }).format(amount)
  }

  const reportTypes = [
    { id: 'profit_loss', name: 'Profit & Loss Statement', icon: '📊' },
    { id: 'balance_sheet', name: 'Balance Sheet', icon: '📋' },
    { id: 'cash_flow', name: 'Cash Flow Statement', icon: '💸' },
    { id: 'trial_balance', name: 'Trial Balance', icon: '⚖️' },
    { id: 'aging', name: 'Aging Reports', icon: '⏰' },
  ]

  return (
    <div className="min-h-screen bg-black text-white p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-3">
              <RiFileChartLine className="text-cyan-400" />
              Financial Reports
            </h1>
            <p className="text-gray-400 mt-1">Comprehensive financial reporting</p>
          </div>
          <div className="flex items-center gap-2">
            <button className="p-3 bg-white/5 rounded-xl border border-white/10 hover:border-cyan-400/50 transition-all">
              <RiPrinterLine className="text-xl" />
            </button>
            <button className="p-3 bg-white/5 rounded-xl border border-white/10 hover:border-cyan-400/50 transition-all">
              <RiFileDownloadLine className="text-xl" />
            </button>
          </div>
        </div>

        {/* Report Type Selector */}
        <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10">
          <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
            {reportTypes.map((type) => (
              <button
                key={type.id}
                onClick={() => setSelectedReport(type.id)}
                className={`p-4 rounded-xl border transition-all text-left ${
                  selectedReport === type.id
                    ? 'border-cyan-400 bg-cyan-400/10'
                    : 'border-white/10 hover:border-cyan-400/50'
                }`}
              >
                <div className="text-2xl mb-2">{type.icon}</div>
                <p className="text-sm font-semibold">{type.name}</p>
              </button>
            ))}
          </div>
        </div>

        {/* Period Selector */}
        <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-sm text-gray-400 mb-2 block">Start Date</label>
              <input
                type="date"
                value={period.startDate}
                onChange={(e) => setPeriod({ ...period, startDate: e.target.value })}
                className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-xl focus:border-cyan-400 focus:outline-none"
              />
            </div>
            <div>
              <label className="text-sm text-gray-400 mb-2 block">End Date</label>
              <input
                type="date"
                value={period.endDate}
                onChange={(e) => setPeriod({ ...period, endDate: e.target.value })}
                className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-xl focus:border-cyan-400 focus:outline-none"
              />
            </div>
          </div>
        </div>

        {/* Report Display */}
        {loading ? (
          <div className="p-12 text-center">
            <div className="animate-pulse text-gray-400">Generating report...</div>
          </div>
        ) : reportData ? (
          <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10">
            <h2 className="text-xl font-bold mb-6">
              {reportTypes.find((t) => t.id === selectedReport)?.name}
            </h2>
            <div className="space-y-4">
              {selectedReport === 'profit_loss' && reportData.revenue && (
                <div>
                  <h3 className="text-lg font-semibold mb-2">Revenue</h3>
                  <p className="text-2xl font-bold text-green-400">
                    {formatCurrency(reportData.revenue.total)}
                  </p>
                  <h3 className="text-lg font-semibold mb-2 mt-4">Expenses</h3>
                  <p className="text-2xl font-bold text-red-400">
                    {formatCurrency(reportData.operatingExpenses.total + reportData.costOfGoodsSold.total)}
                  </p>
                  <h3 className="text-lg font-semibold mb-2 mt-4">Net Income</h3>
                  <p
                    className={`text-3xl font-bold ${
                      reportData.netIncome >= 0 ? 'text-green-400' : 'text-red-400'
                    }`}
                  >
                    {formatCurrency(reportData.netIncome)}
                  </p>
                </div>
              )}
              {selectedReport === 'balance_sheet' && reportData.assets && (
                <div className="space-y-4">
                  <div>
                    <h3 className="text-lg font-semibold mb-2">Total Assets</h3>
                    <p className="text-2xl font-bold">{formatCurrency(reportData.assets.total)}</p>
                  </div>
                  <div>
                    <h3 className="text-lg font-semibold mb-2">Total Liabilities</h3>
                    <p className="text-2xl font-bold">{formatCurrency(reportData.liabilities.total)}</p>
                  </div>
                  <div>
                    <h3 className="text-lg font-semibold mb-2">Total Equity</h3>
                    <p className="text-2xl font-bold">{formatCurrency(reportData.equity.total)}</p>
                  </div>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="p-12 text-center">
            <p className="text-gray-400">Select a report type to generate</p>
          </div>
        )}
      </div>
    </div>
  )
}

/**
 * Incident Report - Enhanced
 * ISO Incident Reporting & Investigation (ISO 9001, ISO 14001, ISO 45001)
 * Fully functional with ERPNext integration
 * 
 * Migrated from chemcheck-ai/pages/incident-report.tsx
 * Adapted for BlueDXP Platform (App Router)
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import ModuleLinks from '@/components/ModuleLinks'
import { getISOIMSLinks } from '@/utils/moduleInterconnectivity'
import UserSelector from '@/components/ims/UserSelector'
import DocumentUploadModal from '@/components/ims/DocumentUploadModal'
import AdvancedSmartDetectionForm from '@/components/forms/AdvancedSmartDetectionForm'
import IncidentReportVisionIntegration from '@/components/vision/IncidentReportVisionIntegration'

type AdvancedDetectionContext = any

interface Incident {
  id: string
  incidentNumber: string
