 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import ModuleLinks from '@/components/ModuleLinks'
import { getISOIMSLinks } from '@/utils/moduleInterconnectivity'
import UserSelector from '@/components/ims/UserSelector'
import AdvancedSmartDetectionForm from '@/components/forms/AdvancedSmartDetectionForm'
import UniversalQRGenerator from '@/components/qr/UniversalQRGenerator'
import QRCodeBadge from '@/components/qr/QRCodeBadge'

type AdvancedDetectionContext = any

interface ChecklistItem {
  id: string
  question: string
  category: string
  requirement: string
  status: 'Pass' | 'Fail' | 'N/A' | 'Not Checked'
  notes?: string
  evidence?: string[]
}

interface Inspection {
  id: string
  inspectionNumber: string
  title: string
  type: 'Internal Audit' | 'External Audit' | 'Safety Inspection' | 'Quality Inspection' | 'Environmental Inspection'
  status: 'Scheduled' | 'In Progress' | 'Completed' | 'Cancelled'
  scheduledDate: string
  completedDate?: string
  inspector: string
  location: string
  checklist: ChecklistItem[]
  findings?: string
  recommendations?: string
  score?: number
}

export default function InspectionChecklistPage() {
  const [inspections, setInspections] = useState<Inspection[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [showDetailModal, setShowDetailModal] = useState(false)
  const [selectedInspection, setSelectedInspection] = useState<Inspection | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [filterType, setFilterType] = useState('all')
  const [filterStatus, setFilterStatus] = useState('all')
  const [newInspection, setNewInspection] = useState({
    title: '',
    type: 'Internal Audit' as Inspection['type'],
    scheduledDate: '',
    inspector: '',
    location: ''
  })

  useEffect(() => {
    fetchInspections()
  }, [])

  const fetchInspections = async () => {
    try {
      // Try to fetch from ERPNext API (if route exists)
      const response = await fetch('/api/erpnext/inspections').catch(() => null)
      if (response?.ok) {
        const data = await response.json()
        const transformedInspections = (data.inspections || data.data || []).map((insp: any) => ({
          id: insp.name || insp.id,
          inspectionNumber: insp.name || `INS-${Date.now()}`,
          title: insp.subject || insp.title,
          type: insp.type || 'Internal Audit',
          status: insp.status || 'Scheduled',
          scheduledDate: insp.starts_on || insp.scheduled_date || new Date().toISOString(),
          completedDate: insp.ends_on || insp.completed_date,
          inspector: insp.inspector || insp.owner || '',
          location: insp.location || '',
          checklist: insp.checklist || [],
          findings: insp.findings || '',
          recommendations: insp.recommendations || '',
          score: insp.score
        }))
        setInspections(transformedInspections)
      } else {
        // Use mock data
        setInspections(generateMockInspections())
      }
    } catch (error) {
      console.error('Error fetching inspections:', error)
      setInspections(generateMockInspections())
    } finally {
      setLoading(false)
    }
  }

  const generateMockInspections = (): Inspection[] => {
    const defaultChecklist: ChecklistItem[] = [
      {
        id: 'item-1',
        question: 'Are all safety procedures documented and accessible?',
        category: 'Safety',
        requirement: 'ISO 45001:2018 Clause 8.1',
        status: 'Not Checked'
      },
      {
        id: 'item-2',
        question: 'Are employees trained on safety procedures?',
        category: 'Training',
        requirement: 'ISO 9001:2015 Clause 7.2',
        status: 'Not Checked'
      },
      {
        id: 'item-3',
        question: 'Are quality control measures in place?',
        category: 'Quality',
        requirement: 'ISO 9001:2015 Clause 8.5',
        status: 'Not Checked'
      }
    ]

    return [
      {
        id: 'ins-001',
        inspectionNumber: 'INS-2025-001',
        title: 'Monthly Safety Inspection - Warehouse A',
        type: 'Safety Inspection',
        status: 'In Progress',
        scheduledDate: new Date().toISOString(),
        inspector: 'b.albayaty@scsflex.com',
        location: 'Warehouse A',
        checklist: defaultChecklist,
        score: 0
      },
      {
        id: 'ins-002',
        inspectionNumber: 'INS-2025-002',
        title: 'Quarterly Quality Audit',
        type: 'Internal Audit',
        status: 'Completed',
        scheduledDate: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
        completedDate: new Date(Date.now() - 1 * 24 * 60 * 60 * 1000).toISOString(),
        inspector: 'quality.manager@scsflex.com',
        location: 'All Facilities',
        checklist: defaultChecklist.map(item => ({ ...item, status: 'Pass' as const })),
        findings: 'All procedures are in compliance',
        recommendations: 'Continue current practices',
        score: 95
      }
    ]
  }

  const handleCreateInspection = async (formData?: Record<string, any>) => {
    try {
      const defaultChecklist: ChecklistItem[] = [
        {
          id: 'item-1',
          question: 'Are all safety procedures documented and accessible?',
          category: 'Safety',
          requirement: 'ISO 45001:2018 Clause 8.1',
          status: 'Not Checked'
        },
        {
          id: 'item-2',
          question: 'Are employees trained on safety procedures?',
          category: 'Training',
          requirement: 'ISO 9001:2015 Clause 7.2',
          status: 'Not Checked'
        }
      ]

      // Use form data from smart detection if provided, otherwise use state
      const inspectionData: Inspection = {
        id: `ins-${Date.now()}`,
        inspectionNumber: `INS-${new Date().getFullYear()}-${String(inspections.length + 1).padStart(3, '0')}`,
        title: formData?.title || newInspection.title,
        type: (formData?.type || newInspection.type) as Inspection['type'],
        status: 'Scheduled',
        scheduledDate: formData?.scheduledDate || newInspection.scheduledDate,
        inspector: formData?.inspector || newInspection.inspector || localStorage.getItem('user_email') || 'b.albayaty@scsflex.com',
        location: formData?.location || newInspection.location,
        checklist: defaultChecklist,
        score: 0
      }

      setInspections([inspectionData, ...inspections])
      setShowCreateModal(false)
      setNewInspection({
        title: '',
        type: 'Internal Audit',
        scheduledDate: '',
        inspector: '',
        location: ''
      })
    } catch (error) {
      console.error('Error creating inspection:', error)
    }
  }

  const handleUpdateChecklistItem = (inspectionId: string, itemId: string, updates: Partial<ChecklistItem>) => {
    setInspections(inspections.map(insp => {
      if (insp.id === inspectionId) {
        return {
          ...insp,
          checklist: insp.checklist.map(item => 
            item.id === itemId ? { ...item, ...updates } : item
          )
        }
      }
      return insp
    }))
  }

  const calculateScore = (checklist: ChecklistItem[]): number => {
    const checkedItems = checklist.filter(item => item.status !== 'Not Checked')
    if (checkedItems.length === 0) return 0

    const passedItems = checkedItems.filter(item => item.status === 'Pass').length
    return Math.round((passedItems / checkedItems.length) * 100)
  }

  const filteredInspections = inspections.filter(inspection => {
    const matchesSearch = 
      inspection.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      inspection.inspectionNumber.toLowerCase().includes(searchQuery.toLowerCase())

    const matchesType = filterType === 'all' || inspection.type === filterType
    const matchesStatus = filterStatus === 'all' || inspection.status === filterStatus

    return matchesSearch && matchesType && matchesStatus
  })

  const statusColors = {
    Scheduled: 'bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200',
    'In Progress': 'bg-yellow-100 dark:bg-yellow-900 text-yellow-800 dark:text-yellow-200',
    Completed: 'bg-green-100 dark:bg-green-900 text-green-800 dark:text-green-200',
    Cancelled: 'bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-200'
  }

  return (
    <PageTemplate
      title="Inspection Checklist"
      description="Create, manage, and track inspection checklists for audits, safety inspections, and quality checks."
      icon="ri-file-list-line"
      stats={[
        {
          label: 'Total Inspections',
          value: inspections.length,
          icon: 'ri-file-list-line'
        },
        {
          label: 'In Progress',
          value: inspections.filter(i => i.status === 'In Progress').length,
          icon: 'ri-time-line'
        },
        {
          label: 'Completed',
          value: inspections.filter(i => i.status === 'Completed').length,
          icon: 'ri-checkbox-circle-line'
        }
      ]}
      actions={
        <button
          onClick={() => setShowCreateModal(true)}
          className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition-colors flex items-center gap-2"
        >
          <i className="ri-add-line"></i>
          New Inspection
        </button>
      }
    >
      <ModuleLinks links={getISOIMSLinks()} />

      {/* Search and Filters */}
      <div className="mb-6 flex flex-col sm:flex-row gap-4">
        <div className="flex-1 relative">
          <i className="ri-search-line absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
          <input
            type="text"
            placeholder="Search inspections..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
          />
        </div>
        <select
          value={filterType}
          onChange={(e) => setFilterType(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
        >
          <option value="all">All Types</option>
          <option value="Internal Audit">Internal Audit</option>
          <option value="External Audit">External Audit</option>
          <option value="Safety Inspection">Safety Inspection</option>
          <option value="Quality Inspection">Quality Inspection</option>
          <option value="Environmental Inspection">Environmental Inspection</option>
        </select>
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
        >
          <option value="all">All Status</option>
          <option value="Scheduled">Scheduled</option>
          <option value="In Progress">In Progress</option>
          <option value="Completed">Completed</option>
          <option value="Cancelled">Cancelled</option>
        </select>
      </div>

      {/* Inspections List */}
      {loading ? (
        <div className="text-center py-12">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-green-600"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">Loading inspections...</p>
        </div>
      ) : filteredInspections.length === 0 ? (
        <div className="text-center py-12">
          <i className="ri-file-list-line text-6xl text-gray-300 dark:text-gray-600 mb-4"></i>
          <p className="text-gray-600 dark:text-gray-400">No inspections found</p>
        </div>
      ) : (
        <div className="space-y-4">
          {filteredInspections.map((inspection) => {
            const currentScore = inspection.score !== undefined ? inspection.score : calculateScore(inspection.checklist)
            return (
              <motion.div
                key={inspection.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 hover:shadow-lg transition-shadow cursor-pointer"
                onClick={() => {
                  setSelectedInspection(inspection)
                  setShowDetailModal(true)
                }}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                        {inspection.title}
                      </h3>
                      <span className={`px-2 py-1 text-xs font-medium rounded-full ${statusColors[inspection.status]}`}>
                        {inspection.status}
                      </span>
                      {inspection.status === 'Completed' && (
                        <span className="px-2 py-1 text-xs font-medium rounded-full bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200">
                          Score: {currentScore}%
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-4 text-sm text-gray-600 dark:text-gray-400 mb-2">
                      <span className="flex items-center gap-1">
                        <i className="ri-file-text-line"></i>
                        {inspection.inspectionNumber}
                      </span>
                      <span className="flex items-center gap-1">
                        <i className="ri-map-pin-line"></i>
                        {inspection.location}
                      </span>
                      <span className="flex items-center gap-1">
                        <i className="ri-calendar-line"></i>
                        {new Date(inspection.scheduledDate).toLocaleDateString()}
                      </span>
                      <span className="flex items-center gap-1">
                        <i className="ri-user-line"></i>
                        {inspection.inspector}
                      </span>
                    </div>
                    <div className="flex items-center gap-4 text-sm">
                      <span className="text-gray-600 dark:text-gray-400">
                        Checklist Items: {inspection.checklist.length}
                      </span>
                      <span className="text-gray-600 dark:text-gray-400">
                        Checked: {inspection.checklist.filter(item => item.status !== 'Not Checked').length}
                      </span>
                      <span className="text-gray-600 dark:text-gray-400">
                        Passed: {inspection.checklist.filter(item => item.status === 'Pass').length}
                      </span>
                    </div>
                  </div>
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      setSelectedInspection(inspection)
                      setShowDetailModal(true)
                    }}
                    className="text-green-600 hover:text-green-900 dark:text-green-400"
                  >
                    <i className="ri-arrow-right-line text-xl"></i>
                  </button>
                </div>
              </motion.div>
            )
          })}
        </div>
      )}

      {/* Create Inspection Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-2xl w-full p-6"
          >
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Create New Inspection</h3>
              <button
                onClick={() => setShowCreateModal(false)}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <i className="ri-close-line text-xl"></i>
              </button>
            </div>
            <AdvancedSmartDetectionForm
              formId={`inspection-form-${Date.now()}`}
              fields={[
                {
                  id: 'title',
                  name: 'title',
                  type: 'text',
                  label: 'Inspection Title',
                  value: newInspection.title,
                  required: true,
                  placeholder: 'e.g., Monthly Safety Inspection - Warehouse A',
                },
                {
                  id: 'type',
                  name: 'type',
                  type: 'select',
                  label: 'Inspection Type',
                  value: newInspection.type,
                  required: true,
                  options: [
                    { label: 'Internal Audit', value: 'Internal Audit' },
                    { label: 'External Audit', value: 'External Audit' },
                    { label: 'Safety Inspection', value: 'Safety Inspection' },
                    { label: 'Quality Inspection', value: 'Quality Inspection' },
                    { label: 'Environmental Inspection', value: 'Environmental Inspection' },
                  ],
                },
                {
                  id: 'scheduledDate',
                  name: 'scheduledDate',
                  type: 'date',
                  label: 'Scheduled Date',
                  value: newInspection.scheduledDate,
                  required: true,
                },
                {
                  id: 'inspector',
                  name: 'inspector',
                  type: 'email',
                  label: 'Inspector',
                  value: newInspection.inspector,
                  placeholder: 'Select inspector...',
                },
                {
                  id: 'location',
                  name: 'location',
                  type: 'text',
                  label: 'Location',
                  value: newInspection.location,
                  required: true,
                  placeholder: 'Where will the inspection take place?',
                },
              ]}
              context={{
                formType: 'INSPECTION',
                moduleId: 'iso-ims',
                previousForms: inspections.map(i => ({
                  title: i.title,
                  type: i.type,
                  scheduledDate: i.scheduledDate,
                  inspector: i.inspector,
                  location: i.location,
                })),
                userRole: 'USER',
                tenantId: 'default-tenant',
              }}
              onSubmit={handleCreateInspection}
              onCancel={() => setShowCreateModal(false)}
              title="Create New Inspection"
            />
          </motion.div>
        </div>
      )}

      {/* Inspection Detail Modal */}
      {showDetailModal && selectedInspection && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 overflow-y-auto">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-4xl w-full p-6 my-8"
          >
            <div className="flex justify-between items-center mb-4">
              <div className="flex items-center gap-2">
                <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">{selectedInspection.title}</h3>
                <QRCodeBadge
                  entityId={selectedInspection.id}
                  entityType="document"
                  entityName={selectedInspection.inspectionNumber}
                  documentType="report"
                  documentUrl={`/inspection-checklist?id=${selectedInspection.id}`}
                  module="iso-ims"
                  size="sm"
                />
              </div>
              <button
                onClick={() => {
                  setShowDetailModal(false)
                  setSelectedInspection(null)
                }}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <i className="ri-close-line text-xl"></i>
              </button>
            </div>

            {/* QR Code Section */}
            <div className="mb-6 bg-blue-50 dark:bg-blue-900/20 rounded-lg p-4 border border-blue-200 dark:border-blue-800">
              <UniversalQRGenerator
                entityId={selectedInspection.id}
                entityType="document"
                entityName={selectedInspection.inspectionNumber}
                documentType="report"
                documentUrl={`/inspection-checklist?id=${selectedInspection.id}`}
                module="iso-ims"
                showAdvancedOptions={false}
              />
            </div>

            <div className="mb-6">
              <div className="grid grid-cols-2 gap-4 mb-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Inspection Number</label>
                  <p className="text-gray-900 dark:text-gray-100">{selectedInspection.inspectionNumber}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Status</label>
                  <span className={`px-2 py-1 text-xs font-medium rounded-full ${statusColors[selectedInspection.status]}`}>
                    {selectedInspection.status}
                  </span>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Type</label>
                  <p className="text-gray-900 dark:text-gray-100">{selectedInspection.type}</p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Scheduled Date</label>
                  <p className="text-gray-900 dark:text-gray-100">{new Date(selectedInspection.scheduledDate).toLocaleString()}</p>
                </div>
              </div>
            </div>

            <div className="mb-6">
              <h4 className="text-md font-semibold text-gray-900 dark:text-gray-100 mb-4">Checklist Items</h4>
              <div className="space-y-3">
                {selectedInspection.checklist.map((item) => (
                  <div key={item.id} className="border border-gray-200 dark:border-gray-700 rounded-lg p-4">
                    <div className="flex items-start justify-between mb-2">
                      <div className="flex-1">
                        <p className="font-medium text-gray-900 dark:text-gray-100">{item.question}</p>
                        <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                          {item.category} • {item.requirement}
                        </p>
                      </div>
                      <select
                        value={item.status}
                        onChange={(e) => handleUpdateChecklistItem(selectedInspection.id, item.id, { 
                          status: e.target.value as ChecklistItem['status'] 
                        })}
                        className="ml-4 px-3 py-1 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100 text-sm"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <option value="Not Checked">Not Checked</option>
                        <option value="Pass">Pass</option>
                        <option value="Fail">Fail</option>
                        <option value="N/A">N/A</option>
                      </select>
                    </div>
                    {item.notes && (
                      <p className="text-sm text-gray-600 dark:text-gray-400 mt-2">{item.notes}</p>
                    )}
                  </div>
                ))}
              </div>
              {selectedInspection.status === 'Completed' && (
                <div className="mt-4 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                  <p className="text-sm font-medium text-gray-900 dark:text-gray-100">
                    Final Score: {calculateScore(selectedInspection.checklist)}%
                  </p>
                </div>
              )}
            </div>

            {selectedInspection.findings && (
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Findings</label>
                <p className="text-gray-900 dark:text-gray-100 whitespace-pre-wrap">{selectedInspection.findings}</p>
              </div>
            )}

            {selectedInspection.recommendations && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Recommendations</label>
                <p className="text-gray-900 dark:text-gray-100 whitespace-pre-wrap">{selectedInspection.recommendations}</p>
              </div>
            )}
          </motion.div>
        </div>
      )}
    </PageTemplate>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { motion } from 'framer-motion'
import { useRouter, useSearchParams } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import Tooltip from '@/components/Tooltip'
import Modal from '@/components/Modal'
import ModuleLinks from '@/components/ModuleLinks'
import { generateInspectionLots } from '@/utils/mockDataGenerators'
import { format } from 'date-fns'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer, LineChart, Line, ComposedChart } from 'recharts'

interface InspectionLot {
  id: string
  inspectionLotNumber: string
  materialNumber: string
  materialDescription: string
  batchNumber: string
  quantity: number
  unit: string
  status: 'CREATED' | 'IN_PROGRESS' | 'PASSED' | 'FAILED' | 'RELEASED' | 'QUARANTINED'
  inspectionType: string
  qualityStandard: string
  inspector: string
  inspectionDate: Date | string
  result: 'PASSED' | 'FAILED' | 'IN_PROGRESS'
  stages: Array<{
    stageName: string
    sequence: number
    status: string
    passed: boolean | null
    inspector: string
    inspectionDate: Date | string | null
    notes: string | null
  }>
  certificateNumber?: string
  ncrNumber?: string
  vendorNumber: string
  vendorName: string
  poNumber: string
  grNumber: string
  location: string
  quarantineLocation?: string
  qualityScore: number
  defectsFound: number
  defectsDescription?: string
  requiresReinspection: boolean
  reinspectionDate?: Date | string
  releasedDate?: Date | string
  releasedBy?: string
  createdAt: Date | string
  updatedAt: Date | string
}

export default function InspectionLots() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const batchFilter = searchParams.get('batch')
  const materialFilter = searchParams.get('material')

  const [lots, setLots] = useState<InspectionLot[]>(() => generateInspectionLots(50) as InspectionLot[])
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedStatus, setSelectedStatus] = useState<string>('ALL')
  const [selectedType, setSelectedType] = useState<string>('ALL')
  const [selectedStandard, setSelectedStandard] = useState<string>('ALL')
  const [viewMode, setViewMode] = useState<'table' | 'analytics' | 'workflow'>('table')
  const [showViewModal, setShowViewModal] = useState(false)
  const [showStageModal, setShowStageModal] = useState(false)
  const [selectedLot, setSelectedLot] = useState<InspectionLot | null>(null)
  const [selectedStage, setSelectedStage] = useState<any>(null)

  const filteredLots = useMemo(() => {
    return lots.filter((lot) => {
      const matchesSearch =
        lot.inspectionLotNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lot.materialNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lot.batchNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lot.vendorName.toLowerCase().includes(searchQuery.toLowerCase())
      const matchesStatus = selectedStatus === 'ALL' || lot.status === selectedStatus
      const matchesType = selectedType === 'ALL' || lot.inspectionType === selectedType
      const matchesStandard = selectedStandard === 'ALL' || lot.qualityStandard === selectedStandard
      const matchesBatch = !batchFilter || lot.batchNumber === batchFilter
      const matchesMaterial = !materialFilter || lot.materialNumber === materialFilter
      return matchesSearch && matchesStatus && matchesType && matchesStandard && matchesBatch && matchesMaterial
    })
  }, [lots, searchQuery, selectedStatus, selectedType, selectedStandard, batchFilter, materialFilter])

  const statusStats = useMemo(() => {
    const stats: Record<string, number> = {}
    lots.forEach(lot => {
      stats[lot.status] = (stats[lot.status] || 0) + 1
    })
    return Object.entries(stats).map(([status, count]) => ({ status, count }))
  }, [lots])

  const resultStats = useMemo(() => {
    const passed = lots.filter(l => l.result === 'PASSED').length
    const failed = lots.filter(l => l.result === 'FAILED').length
    const inProgress = lots.filter(l => l.result === 'IN_PROGRESS').length
    return [
      { name: 'Passed', value: passed, color: '#10b981' },
      { name: 'Failed', value: failed, color: '#ef4444' },
      { name: 'In Progress', value: inProgress, color: '#f59e0b' },
    ]
  }, [lots])

  const qualityScoreTrend = useMemo(() => {
    return lots
      .filter(l => l.status === 'RELEASED' || l.status === 'PASSED')
      .slice(-15)
      .map((lot, idx) => ({
        lot: lot.inspectionLotNumber.substring(0, 10),
        score: lot.qualityScore,
        defects: lot.defectsFound,
      }))
  }, [lots])

  const standardDistribution = useMemo(() => {
    const stats: Record<string, number> = {}
    lots.forEach(lot => {
      stats[lot.qualityStandard] = (stats[lot.qualityStandard] || 0) + 1
    })
    return Object.entries(stats).map(([standard, count]) => ({ standard, count }))
  }, [lots])

  const stats = [
    {
      label: 'Total Inspections',
      value: lots.length,
      icon: 'ri-file-search-line',
      tooltip: 'Total inspection lots',
      trend: 'up' as const,
    },
    {
      label: 'Passed',
      value: lots.filter(l => l.result === 'PASSED').length,
      icon: 'ri-checkbox-circle-line',
      tooltip: 'Passed inspections',
      trend: 'up' as const,
    },
    {
      label: 'Failed',
      value: lots.filter(l => l.result === 'FAILED').length,
      icon: 'ri-close-circle-line',
      tooltip: 'Failed inspections',
      trend: 'neutral' as const,
    },
    {
      label: 'Avg Quality Score',
      value: `${(lots.reduce((sum, l) => sum + l.qualityScore, 0) / lots.length).toFixed(1)}%`,
      icon: 'ri-star-line',
      tooltip: 'Average quality score',
      trend: 'up' as const,
    },
  ]

  const handleView = (lot: InspectionLot) => {
    setSelectedLot(lot)
    setShowViewModal(true)
  }

  const handleViewStage = (lot: InspectionLot, stage: any) => {
    setSelectedLot(lot)
    setSelectedStage(stage)
    setShowStageModal(true)
  }

  const handleNavigateToBatch = (lot: InspectionLot) => {
    router.push(`/batches?batch=${lot.batchNumber}`)
  }

  const handleNavigateToMaterial = (lot: InspectionLot) => {
    router.push(`/materials?material=${lot.materialNumber}`)
  }

