    totalDeliveries: webhooks.reduce((sum, w) => sum + w.totalDeliveries, 0),
    successRate: webhooks.length > 0
      ? Math.round((webhooks.reduce((sum, w) => sum + w.successfulDeliveries, 0) / webhooks.reduce((sum, w) => sum + w.totalDeliveries, 0)) * 100)
      : 0,
  }

  const handleCreateWebhook = async () => {
    if (!newWebhook.name || !newWebhook.url || newWebhook.events.length === 0) {
      notifications.warning(
        'Validation Error',
        'Please fill in all required fields',
        { duration: 4000 }
      )
      return
    }

    setLoading(true)
    try {
      const response = await fetch('/api/webhooks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: newWebhook.name,
          url: newWebhook.url,
          events: newWebhook.events,
          verifySSL: newWebhook.verifySSL,
        }),
      })

      if (response.ok) {
        notifications.success(
          NotificationPatterns.saveSuccess('Webhook').title,
          'Webhook created successfully',
          { duration: 4000 }
        )
        setShowCreateModal(false)
        setNewWebhook({ name: '', url: '', events: [], verifySSL: true })
        loadWebhooks()
      } else {
        const error = await response.json()
        notifications.error(
          'Failed to Create Webhook',
          error.error || 'Please try again',
          { duration: 6000 }
        )
      }
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error))
      logger.error('Error creating webhook', err, {
        module: 'integration',
        service: 'webhooks',
      })
      errorTrackingService.captureException(err, {
        module: 'integration',
        service: 'webhooks',
      })
      notifications.error(
        'Failed to Create Webhook',
        err.message || 'Unknown error',
        { duration: 6000 }
      )
    } finally {
      setLoading(false)
    }
  }

  const handleToggleWebhook = async (webhookId: string, newStatus: 'ACTIVE' | 'PAUSED' | 'INACTIVE') => {
    try {
      const response = await fetch(`/api/webhooks/${webhookId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })

      if (response.ok) {
        notifications.success(
          'Webhook Updated',
          `Webhook ${newStatus === 'ACTIVE' ? 'activated' : newStatus === 'PAUSED' ? 'paused' : 'deactivated'}`,
          { duration: 4000 }
        )
        loadWebhooks()
      } else {
        const error = await response.json()
        notifications.error(
          'Failed to Update Webhook',
          error.error || 'Please try again',
          { duration: 6000 }
        )
      }
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error))
      logger.error('Error updating webhook', err, {
        module: 'integration',
        service: 'webhooks',
      })
      errorTrackingService.captureException(err, {
        module: 'integration',
        service: 'webhooks',
      })
      notifications.error(
        'Failed to Update Webhook',
        err.message || 'Please try again',
        { duration: 6000 }
      )
    }
