                  <div className="grid md:grid-cols-3 gap-4 mb-4">
                    <div>
                      <div className="text-xs text-[#9ca3af] mb-1">Root Causes</div>
                      <div className="text-sm font-medium text-white">{rca.rootCauses.length}</div>
                    </div>
                    <div>
                      <div className="text-xs text-[#9ca3af] mb-1">Evidence</div>
                      <div className="text-sm font-medium text-white">{rca.evidence.length}</div>
