                    <div className="mb-3 flex flex-wrap gap-2">
                      {audit.isoStandards.slice(0, 2).map((standard, idx) => (
                        <span key={idx} className="px-2 py-1 rounded-lg text-xs font-medium bg-purple-500/20 text-purple-300 border border-purple-500/30">
                          {standard}
                        </span>
                      ))}
                      {audit.isoStandards.length > 2 && (
                        <span className="px-2 py-1 rounded-lg text-xs font-medium bg-gray-500/20 text-gray-300 border border-gray-500/30">
                          +{audit.isoStandards.length - 2}
                        </span>
