/**
 * ISO-IMS CAPA Management Page
 * Corrective and Preventive Actions Management
 * World-class UI/UX with glassmorphism and animations
 */

'use client'

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useRouter } from 'next/navigation'
import { FiPlus, FiSearch, FiFilter, FiDownload, FiCheckCircle, FiClock, FiAlertCircle, FiTrendingUp, FiLink2 } from 'react-icons/fi'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { PremiumLoader } from '@/components/loading'
import PageTemplate from '@/components/PageTemplate'

interface CAPA {
  id: string
  capaNumber: string
  subject: string
  status: string
  priority: string
  capaType: string
  assignedTo?: string
  targetDate?: string
  createdAt: string
}

function CAPAPageContent() {
  const router = useRouter()
  const [capas, setCapas] = useState<CAPA[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState<string>('all')
  const [priorityFilter, setPriorityFilter] = useState<string>('all')

  useEffect(() => {
    fetchCAPAs()
  }, [statusFilter, priorityFilter])

  const fetchCAPAs = async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams()
      params.append('tenantId', 'default-tenant')
      if (statusFilter !== 'all') params.append('status', statusFilter)
      if (priorityFilter !== 'all') params.append('priority', priorityFilter)

      const response = await fetch(`/api/iso-ims/capa?${params.toString()}`)
      const data = await response.json()

      if (data.success) {
        let filtered = data.data || []

        if (searchQuery) {
          filtered = filtered.filter((capa: CAPA) =>
            capa.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
            capa.capaNumber.toLowerCase().includes(searchQuery.toLowerCase())
          )
        }

        if (statusFilter !== 'all') {
          filtered = filtered.filter((capa: CAPA) => capa.status === statusFilter)
        }

        if (priorityFilter !== 'all') {
          filtered = filtered.filter((capa: CAPA) => capa.priority === priorityFilter)
        }

        setCapas(filtered)
      }
    } catch (error) {
      console.error('Error fetching CAPAs:', error)
    } finally {
      setLoading(false)
    }
  }

  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      'OPEN': 'from-blue-500/20 to-cyan-500/20 border-blue-500/30 text-blue-400',
      'IN_PROGRESS': 'from-orange-500/20 to-amber-500/20 border-orange-500/30 text-orange-400',
      'COMPLETED': 'from-green-500/20 to-emerald-500/20 border-green-500/30 text-green-400',
      'CLOSED': 'from-gray-500/20 to-slate-500/20 border-gray-500/30 text-gray-400',
    }
    return colors[status] || colors['OPEN']
  }

  const getPriorityColor = (priority: string) => {
    const colors: Record<string, string> = {
      'CRITICAL': 'bg-red-500/20 text-red-400 border-red-500/30',
      'HIGH': 'bg-orange-500/20 text-orange-400 border-orange-500/30',
      'MEDIUM': 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
      'LOW': 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    }
    return colors[priority] || colors['MEDIUM']
  }

  return (
    <PageTemplate
      title="CAPA Management"
      description="Corrective and Preventive Actions • AI-Powered Insights • Real-time Tracking"
      icon="ri-check-double-line"
    >
      {/* Header Actions */}
      <div className="mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex-1 min-w-[300px]">
          <div className="relative">
            <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search CAPAs..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-white/5 backdrop-blur-sm border border-white/10 rounded-xl text-white placeholder-gray-400 focus:outline-none focus:border-cyan-500/50 focus:ring-1 focus:ring-cyan-500/50 transition-all"
            />
          </div>
        </div>

        <div className="flex gap-3 flex-wrap">
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-4 py-2.5 bg-white/5 backdrop-blur-sm border border-white/10 rounded-xl text-white focus:outline-none focus:border-cyan-500/50"
          >
            <option value="all">All Status</option>
            <option value="OPEN">Open</option>
            <option value="IN_PROGRESS">In Progress</option>
            <option value="COMPLETED">Completed</option>
            <option value="CLOSED">Closed</option>
          </select>

          <select
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value)}
            className="px-4 py-2.5 bg-white/5 backdrop-blur-sm border border-white/10 rounded-xl text-white focus:outline-none focus:border-cyan-500/50"
          >
            <option value="all">All Priorities</option>
            <option value="CRITICAL">Critical</option>
            <option value="HIGH">High</option>
            <option value="MEDIUM">Medium</option>
            <option value="LOW">Low</option>
          </select>

          <motion.button
            onClick={() => router.push('/iso-ims/capa/new')}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="relative overflow-hidden px-6 py-2.5 bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white rounded-xl font-medium transition-all duration-300 flex items-center gap-2 shadow-lg shadow-cyan-500/30 hover:shadow-cyan-500/50 group"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/20 to-white/0 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000" />
            <FiPlus className="w-5 h-5 relative z-10" />
            <span className="relative z-10">New CAPA</span>
          </motion.button>
        </div>
      </div>

      {/* CAPA Cards Grid */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <PremiumLoader message="Loading CAPAs..." size="lg" />
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <AnimatePresence>
            {capas.map((capa, index) => (
              <motion.div
                key={capa.id}
                initial={{ opacity: 0, y: 20, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ delay: index * 0.05, type: "spring", stiffness: 300 }}
                whileHover={{ scale: 1.02, y: -4 }}
                onClick={() => router.push(`/iso-ims/capa/${capa.id}`)}
                className="relative overflow-hidden bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10 shadow-xl hover:border-cyan-500/40 transition-all duration-300 cursor-pointer group"
              >
                {/* Animated gradient background */}
                <div className={`absolute inset-0 bg-gradient-to-br ${getStatusColor(capa.status)} opacity-0 group-hover:opacity-100 transition-opacity duration-500`} />

                <div className="relative z-10">
                  <div className="flex items-start justify-between mb-4">
                    <div>
                      <h3 className="text-lg font-semibold text-white mb-1">{capa.subject}</h3>
                      <p className="text-sm text-gray-400">{capa.capaNumber}</p>
                    </div>
                    <span className={`px-3 py-1 rounded-lg text-xs font-medium border ${getPriorityColor(capa.priority)}`}>
                      {capa.priority}
                    </span>
                  </div>

                  <div className="flex items-center justify-between text-sm">
                    <span className={`px-3 py-1 rounded-lg text-xs font-medium border ${getStatusColor(capa.status)}`}>
                      {capa.status.replace('_', ' ')}
                    </span>
                    {capa.targetDate && (
                      <div className="flex items-center gap-1 text-gray-400">
                        <FiClock className="w-4 h-4" />
                        <span>{new Date(capa.targetDate).toLocaleDateString()}</span>
                      </div>
                    )}
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {!loading && capas.length === 0 && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-center py-20"
        >
          <FiCheckCircle className="w-16 h-16 text-gray-600 mx-auto mb-4" />
          <p className="text-gray-400 text-lg">No CAPAs found</p>
          <motion.button
            onClick={() => router.push('/iso-ims/capa/new')}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="mt-4 px-6 py-2.5 bg-gradient-to-r from-cyan-500 to-blue-600 text-white rounded-xl font-medium"
          >
            Create First CAPA
          </motion.button>
        </motion.div>
      )}
    </PageTemplate>
  )
}

export default function CAPAPage() {
  return (
    <ErrorBoundary>
      <CAPAPageContent />
    </ErrorBoundary>
  )
}

/**
 * ISO IMS Intelligence Dashboard - Mind-Blowing AI-Powered Insights
 * 
 * Features:
 * - Real-time AI insights
 * - Pattern detection visualization
 * - Predictive analytics
 * - Smart recommendations
 * - Deep drill-down capabilities
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import ComplianceScoreCard from '@/components/iso-ims/ComplianceScoreCard'
import PatternDetectionVisualization from '@/components/iso-ims/PatternDetectionVisualization'
import type { ComplianceScore } from '@/lib/services/iso-ims/complianceEngine'
import type { NCRPattern, SmartRecommendation } from '@/lib/services/iso-ims/intelligenceService'

export default function ISOIMSIntelligencePage() {
  const [loading, setLoading] = useState(true)
  const [complianceScore, setComplianceScore] = useState<ComplianceScore | null>(null)
  const [patterns, setPatterns] = useState<NCRPattern[]>([])
  const [recommendations, setRecommendations] = useState<SmartRecommendation[]>([])
  const [predictions, setPredictions] = useState<any[]>([])
  const [selectedTimeRange, setSelectedTimeRange] = useState<'7D' | '30D' | '90D' | '1Y'>('30D')

  useEffect(() => {
    fetchIntelligence()
  }, [selectedTimeRange])

  const fetchIntelligence = async () => {
    try {
      setLoading(true)
      
      const [complianceRes, patternsRes, recommendationsRes, predictionsRes] = await Promise.all([
        fetch('/api/iso-ims/compliance?type=score'),
        fetch('/api/iso-ims/intelligence', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'detect-patterns',
            tenantId: 'default-tenant',
            entityType: 'NCR',
          }),
        }),
        fetch('/api/iso-ims/intelligence', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'generate-recommendations',
            tenantId: 'default-tenant',
          }),
        }),
        fetch('/api/iso-ims/intelligence', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'predict-compliance',
            tenantId: 'default-tenant',
            timeframe: selectedTimeRange,
          }),
        }),
      ])

      if (complianceRes.ok) {
        const score = await complianceRes.json()
        setComplianceScore(score)
      }

      if (patternsRes.ok) {
        const patternsData = await patternsRes.json()
        setPatterns(patternsData || [])
      }

      if (recommendationsRes.ok) {
        const recs = await recommendationsRes.json()
        setRecommendations(recs || [])
      }

      if (predictionsRes.ok) {
        const preds = await predictionsRes.json()
        setPredictions(preds || [])
      }
    } catch (error) {
      console.error('Error fetching intelligence:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <PageTemplate
      title="ISO IMS Intelligence Dashboard"
      description="AI-Powered Compliance Intelligence • Pattern Detection • Predictive Analytics"
      icon="ri-ai-generate-line"
    >
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
        </div>
      ) : (
        <>
          {/* Compliance Score Card */}
          {complianceScore && (
            <div className="mb-8">
              <ComplianceScoreCard
                score={complianceScore}
                showTrends={true}
                showBreakdown={true}
                onDrillDown={(standard) => {
                  console.log('Drill down to:', standard)
                }}
              />
            </div>
          )}

          {/* Pattern Detection */}
          {patterns.length > 0 && (
            <div className="mb-8">
              <PatternDetectionVisualization
                patterns={patterns}
                onPatternClick={(patternId) => {
                  console.log('Pattern clicked:', patternId)
                }}
              />
            </div>
          )}

          {/* Smart Recommendations */}
          {recommendations.length > 0 && (
            <div className="mb-8">
              <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                <i className="ri-lightbulb-flash-line text-yellow-400"></i>
                AI-Powered Recommendations
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {recommendations.map((rec) => (
                  <motion.div
                    key={rec.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="p-4 rounded-lg bg-gradient-to-br from-purple-900/30 to-blue-900/30 border border-purple-500/30"
                  >
                    <div className="flex items-start gap-3">
                      <i className="ri-lightbulb-line text-2xl text-purple-400"></i>
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-2">
                          <h4 className="font-semibold text-white">{rec.title}</h4>
                          <span className={`px-2 py-1 rounded text-xs font-medium ${
                            rec.priority === 'CRITICAL' ? 'bg-red-900/30 text-red-400' :
                            rec.priority === 'HIGH' ? 'bg-orange-900/30 text-orange-400' :
                            rec.priority === 'MEDIUM' ? 'bg-yellow-900/30 text-yellow-400' :
                            'bg-gray-700 text-gray-400'
                          }`}>
                            {rec.priority}
                          </span>
                        </div>
                        <p className="text-sm text-gray-300 mb-2">{rec.description}</p>
                        <div className="flex items-center justify-between text-xs text-gray-400">
                          <span>Confidence: {rec.confidence}%</span>
                          <span>Impact: {rec.estimatedImpact}</span>
                        </div>
                        {rec.actionUrl && (
                          <button
                            onClick={() => window.location.href = rec.actionUrl!}
                            className="mt-3 w-full px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-sm font-medium transition-colors"
                          >
                            Take Action
                          </button>
                        )}
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          )}

          {/* Predictive Analytics */}
          {predictions.length > 0 && (
            <div className="mb-8">
              <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                <i className="ri-line-chart-line text-blue-400"></i>
                Predictive Analytics
              </h3>
              <div className="bg-gray-800 border border-gray-700 rounded-xl p-6">
                <div className="flex items-center gap-4 mb-4">
                  <span className="text-sm text-gray-400">Time Range:</span>
                  {['7D', '30D', '90D', '1Y'].map((range) => (
                    <button
                      key={range}
                      onClick={() => setSelectedTimeRange(range as any)}
                      className={`px-3 py-1 rounded text-sm font-medium transition-colors ${
                        selectedTimeRange === range
                          ? 'bg-blue-600 text-white'
                          : 'bg-gray-700 text-gray-400 hover:bg-gray-600'
                      }`}
                    >
                      {range}
                    </button>
                  ))}
                </div>
                <div className="h-64 flex items-end justify-between gap-2">
                  {predictions.map((pred, i) => (
                    <motion.div
                      key={i}
                      initial={{ height: 0 }}
                      animate={{ height: `${(pred.predictedScore / 100) * 100}%` }}
                      transition={{ duration: 0.5, delay: i * 0.05 }}
                      className="flex-1 bg-gradient-to-t from-blue-600 to-blue-400 rounded-t hover:from-blue-500 hover:to-blue-300 transition-colors cursor-pointer group relative"
                      title={`${new Date(pred.date).toLocaleDateString()}: ${pred.predictedScore.toFixed(1)}%`}
                    >
                      <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <div className="bg-gray-900 text-white text-xs px-2 py-1 rounded whitespace-nowrap">
                          {pred.predictedScore.toFixed(1)}%
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </>
      )}
    </PageTemplate>
  )
}

/**
 * ISO-IMS NCR Management Page
 * Non-Conformance Reports Management
 * World-class UI/UX with glassmorphism and animations
 */

'use client'

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useRouter } from 'next/navigation'
import { FiPlus, FiSearch, FiFilter, FiAlertTriangle, FiClock, FiTrendingUp, FiLink2 } from 'react-icons/fi'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { PremiumLoader } from '@/components/loading'
import PageTemplate from '@/components/PageTemplate'

interface NCR {
  id: string
  ncrNumber: string
  subject: string
  status: string
  priority: string
  severity: string
  ncType: string
  reportedBy: string
  reportedDate: string
  assignedTo?: string
}

function NCRPageContent() {
  const router = useRouter()
  const [ncrs, setNCRs] = useState<NCR[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState<string>('all')
  const [severityFilter, setSeverityFilter] = useState<string>('all')

  useEffect(() => {
    fetchNCRs()
  }, [statusFilter, severityFilter])

  const fetchNCRs = async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams()
      params.append('tenantId', 'default-tenant')
      if (statusFilter !== 'all') params.append('status', statusFilter)
      if (severityFilter !== 'all') params.append('severity', severityFilter)

      const response = await fetch(`/api/iso-ims/ncr?${params.toString()}`)
      const data = await response.json()

      if (data.success) {
        let filtered = data.data || []

        if (searchQuery) {
          filtered = filtered.filter((ncr: NCR) =>
            ncr.subject.toLowerCase().includes(searchQuery.toLowerCase()) ||
            ncr.ncrNumber.toLowerCase().includes(searchQuery.toLowerCase())
          )
        }

        if (statusFilter !== 'all') {
          filtered = filtered.filter((ncr: NCR) => ncr.status === statusFilter)
        }

        if (severityFilter !== 'all') {
          filtered = filtered.filter((ncr: NCR) => ncr.severity === severityFilter)
        }

        setNCRs(filtered)
      }
    } catch (error) {
      console.error('Error fetching NCRs:', error)
    } finally {
      setLoading(false)
    }
  }

  const getSeverityColor = (severity: string) => {
    const colors: Record<string, string> = {
      'CRITICAL': 'from-red-500/20 to-pink-500/20 border-red-500/30 text-red-400',
      'HIGH': 'from-orange-500/20 to-amber-500/20 border-orange-500/30 text-orange-400',
      'MEDIUM': 'from-yellow-500/20 to-yellow-500/20 border-yellow-500/30 text-yellow-400',
      'MINOR': 'from-blue-500/20 to-cyan-500/20 border-blue-500/30 text-blue-400',
    }
    return colors[severity] || colors['MEDIUM']
  }

  return (
    <PageTemplate
      title="NCR Management"
      description="Non-Conformance Reports • Root Cause Analysis • AI-Powered Insights"
      icon="ri-alarm-warning-line"
    >
      {/* Header Actions */}
      <div className="mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex-1 min-w-[300px]">
          <div className="relative">
            <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search NCRs..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-white/5 backdrop-blur-sm border border-white/10 rounded-xl text-white placeholder-gray-400 focus:outline-none focus:border-red-500/50 focus:ring-1 focus:ring-red-500/50 transition-all"
            />
          </div>
        </div>

        <div className="flex gap-3 flex-wrap">
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-4 py-2.5 bg-white/5 backdrop-blur-sm border border-white/10 rounded-xl text-white focus:outline-none focus:border-red-500/50"
          >
            <option value="all">All Status</option>
            <option value="OPEN">Open</option>
            <option value="IN_PROGRESS">In Progress</option>
            <option value="CLOSED">Closed</option>
          </select>

          <select
            value={severityFilter}
            onChange={(e) => setSeverityFilter(e.target.value)}
            className="px-4 py-2.5 bg-white/5 backdrop-blur-sm border border-white/10 rounded-xl text-white focus:outline-none focus:border-red-500/50"
          >
            <option value="all">All Severities</option>
            <option value="CRITICAL">Critical</option>
            <option value="HIGH">High</option>
            <option value="MEDIUM">Medium</option>
            <option value="MINOR">Minor</option>
          </select>

          <motion.button
            onClick={() => router.push('/iso-ims/ncr/new')}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="relative overflow-hidden px-6 py-2.5 bg-gradient-to-r from-red-500 to-pink-600 hover:from-red-600 hover:to-pink-700 text-white rounded-xl font-medium transition-all duration-300 flex items-center gap-2 shadow-lg shadow-red-500/30 hover:shadow-red-500/50 group"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/20 to-white/0 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000" />
            <FiPlus className="w-5 h-5 relative z-10" />
            <span className="relative z-10">New NCR</span>
          </motion.button>
        </div>
      </div>

      {/* NCR Cards Grid */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <PremiumLoader message="Loading NCRs..." size="lg" />
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <AnimatePresence>
            {ncrs.map((ncr, index) => (
              <motion.div
                key={ncr.id}
                initial={{ opacity: 0, y: 20, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ delay: index * 0.05, type: "spring", stiffness: 300 }}
                whileHover={{ scale: 1.02, y: -4 }}
                onClick={() => router.push(`/iso-ims/ncr/${ncr.id}`)}
                className="relative overflow-hidden bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10 shadow-xl hover:border-red-500/40 transition-all duration-300 cursor-pointer group"
              >
                {/* Animated gradient background */}
                <div className={`absolute inset-0 bg-gradient-to-br ${getSeverityColor(ncr.severity)} opacity-0 group-hover:opacity-100 transition-opacity duration-500`} />

                {/* Pulse indicator for critical NCRs */}
                {ncr.severity === 'CRITICAL' && (
                  <motion.div
                    className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full"
                    animate={{ scale: [1, 1.5, 1], opacity: [1, 0.5, 1] }}
                    transition={{ duration: 2, repeat: Infinity }}
                  />
                )}

                <div className="relative z-10">
                  <div className="flex items-start justify-between mb-4">
                    <div>
                      <h3 className="text-lg font-semibold text-white mb-1">{ncr.subject}</h3>
                      <p className="text-sm text-gray-400">{ncr.ncrNumber}</p>
                    </div>
                    <FiAlertTriangle className={`w-6 h-6 ${ncr.severity === 'CRITICAL' ? 'text-red-400' : ncr.severity === 'HIGH' ? 'text-orange-400' : 'text-yellow-400'}`} />
                  </div>

                  <div className="flex items-center justify-between text-sm">
                    <span className={`px-3 py-1 rounded-lg text-xs font-medium border ${getSeverityColor(ncr.severity)}`}>
                      {ncr.severity}
                    </span>
                    <div className="flex items-center gap-1 text-gray-400">
                      <FiClock className="w-4 h-4" />
                      <span>{new Date(ncr.reportedDate).toLocaleDateString()}</span>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}

      {!loading && ncrs.length === 0 && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-center py-20"
        >
          <FiAlertTriangle className="w-16 h-16 text-gray-600 mx-auto mb-4" />
          <p className="text-gray-400 text-lg">No NCRs found</p>
          <motion.button
            onClick={() => router.push('/iso-ims/ncr/new')}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="mt-4 px-6 py-2.5 bg-gradient-to-r from-red-500 to-pink-600 text-white rounded-xl font-medium"
          >
            Create First NCR
          </motion.button>
        </motion.div>
      )}
    </PageTemplate>
  )
}

export default function NCRPage() {
  return (
    <ErrorBoundary>
      <NCRPageContent />
    </ErrorBoundary>
  )
}

