'use client'

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { useRouter } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { PremiumLoader } from '@/components/loading'
import {
  Users,
  TrendingUp,
  DollarSign,
  Activity,
  Building2,
  Search,
  Filter,
  Plus,
  Eye,
  BarChart3,
} from 'lucide-react'
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts'

interface Tenant {
  id: string
  name: string
  utilization: number
  revenue: number
  status: 'active' | 'inactive' | 'pending'
  pillars: number
  createdAt: string
  health: 'excellent' | 'good' | 'fair' | 'poor'
}

function MaasTenantsPageContent() {
  const router = useRouter()
  const [loading, setLoading] = useState(true)
  const [tenants, setTenants] = useState<Tenant[]>([])
  const [searchQuery, setSearchQuery] = useState('')
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'inactive' | 'pending'>('all')

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true)
        const response = await fetch('/api/maas/tenants')
        if (response.ok) {
          const result = await response.json()
          setTenants(result.tenants || result.data || [])
        } else {
          // Generate sample data
          setTenants(generateSampleTenants())
        }
      } catch (error) {
        console.error('Error fetching tenants:', error)
        setTenants(generateSampleTenants())
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [])

  const generateSampleTenants = (): Tenant[] => {
    const names = [
      'Manufacturing Co. Ltd.',
      'Tech Industries Inc.',
      'Global Manufacturing',
      'Industrial Corp',
      'Advanced Solutions',
      'Precision Manufacturing',
      'Smart Factory Group',
      'Innovation Labs',
    ]

    return names.map((name, index) => ({
      id: `tenant-${index + 1}`,
      name,
      utilization: Math.random() * 40 + 50,
      revenue: Math.random() * 200000 + 80000,
      status: Math.random() > 0.2 ? 'active' : 'pending' as const,
      pillars: Math.floor(Math.random() * 8) + 4,
      createdAt: new Date(Date.now() - Math.random() * 365 * 24 * 60 * 60 * 1000).toISOString(),
      health: (['excellent', 'good', 'fair', 'poor'] as const)[Math.floor(Math.random() * 4)],
    }))
  }

  const filteredTenants = tenants.filter((tenant) => {
    const matchesSearch = tenant.name.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesFilter = filterStatus === 'all' || tenant.status === filterStatus
    return matchesSearch && matchesFilter
  })

  const totalRevenue = tenants.reduce((sum, t) => sum + t.revenue, 0)
  const avgUtilization = tenants.reduce((sum, t) => sum + t.utilization, 0) / tenants.length
  const activeTenants = tenants.filter((t) => t.status === 'active').length

  const chartData = filteredTenants.slice(0, 8).map((t) => ({
    name: t.name.substring(0, 15),
    revenue: t.revenue,
    utilization: t.utilization,
  }))

  if (loading) {
    return (
      <PageTemplate 
        title="MaaS Tenants" 
        description="Tenant Management - Manufacturing as a Service"
        icon="ri-group-line"
      >
        <div className="flex items-center justify-center min-h-[400px]">
          <PremiumLoader 
            message="Loading tenants..." 
            size="lg" 
            variant="default"
          />
        </div>
      </PageTemplate>
    )
  }

  return (
    <PageTemplate 
      title="MaaS Tenants" 
      description="Tenant Management - Manufacturing as a Service"
      icon="ri-group-line"
    >
      <div className="space-y-6">
        {/* Summary Metrics */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10"
          >
            <div className="flex items-center gap-3 mb-2">
              <Users className="w-5 h-5 text-blue-400" />
              <h3 className="text-sm text-gray-400">Total Tenants</h3>
            </div>
            <p className="text-3xl font-bold text-white">{tenants.length}</p>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10"
          >
            <div className="flex items-center gap-3 mb-2">
              <Activity className="w-5 h-5 text-green-400" />
              <h3 className="text-sm text-gray-400">Avg Utilization</h3>
            </div>
            <p className="text-3xl font-bold text-white">{avgUtilization.toFixed(1)}%</p>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10"
          >
            <div className="flex items-center gap-3 mb-2">
              <DollarSign className="w-5 h-5 text-emerald-400" />
              <h3 className="text-sm text-gray-400">Total Revenue</h3>
            </div>
            <p className="text-3xl font-bold text-white">
              {totalRevenue.toLocaleString('en-US', {
                style: 'currency',
                currency: 'SAR',
                minimumFractionDigits: 0,
              })}
            </p>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-white/10"
          >
            <div className="flex items-center gap-3 mb-2">
              <Building2 className="w-5 h-5 text-purple-400" />
              <h3 className="text-sm text-gray-400">Active</h3>
            </div>
            <p className="text-3xl font-bold text-white">{activeTenants}</p>
          </motion.div>
        </div>

        {/* Search and Filter */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Search tenants..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
