  if (!booking) {
    return (
      <PageTemplate
        title="Booking Not Found"
        description="The booking you're looking for doesn't exist"
        icon="ri-error-warning-line"
      >
        <div className="bg-white rounded-xl shadow-lg p-12 text-center">
          <h3 className="text-xl font-semibold text-slate-800 mb-2">Booking not found</h3>
          <p className="text-slate-500 mb-6">The booking you're looking for doesn't exist</p>
          <button
