                  {booking.pricing.total.toLocaleString()} {booking.pricing.currency}
                </span>
              </div>
            </div>

            <div className="pt-6 border-t border-slate-200">
              <p className="text-xs text-slate-500 mb-1">Booking Created</p>
              <p className="text-sm font-semibold text-slate-800">
                {new Date(booking.createdAt).toLocaleDateString()}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Chat Modal */}
      {showChat && conversationId && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-4xl h-[80vh]">
            <ChatWindow
              conversationId={conversationId}
              currentUserId={currentUserId}
              onClose={() => {
                setShowChat(false)
                setConversationId(null)
              }}
            />
          </div>
        </div>
      )}
    </PageTemplate>
  )
}

