'use client'

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import { Star, MapPin, Clock, DollarSign, CheckCircle, AlertCircle, Building2, Phone, Mail } from 'lucide-react'
import { marketplaceService } from '@/lib/services/marketplace'
import FavoriteButton from '@/components/marketplace/FavoriteButton'
import RealTimeIndicator from '@/components/marketplace/RealTimeIndicator'
import VerificationBadge from '@/components/marketplace/VerificationBadge'
import SustainabilityBadge from '@/components/marketplace/SustainabilityBadge'
import type { MarketplaceServiceListing, MarketplaceReview } from '@/types/marketplace'

export default function ListingDetailPage() {
  const params = useParams()
  const router = useRouter()
  const listingId = params.id as string

  const [listing, setListing] = useState<MarketplaceServiceListing | null>(null)
  const [reviews, setReviews] = useState<MarketplaceReview[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (listingId) {
      loadListing()
      loadReviews()
    }
  }, [listingId])

  const loadListing = async () => {
    try {
      const response = await fetch(`/api/marketplace/listings/${listingId}`)
      const result = await response.json()
      if (result.success) {
        setListing(result.data)
      }
    } catch (error) {
      console.error('Failed to load listing:', error)
    } finally {
      setLoading(false)
    }
  }

  const loadReviews = async () => {
    try {
      const serviceReviews = await marketplaceService.getServiceReviews(listingId)
      setReviews(serviceReviews)
    } catch (error) {
      console.error('Failed to load reviews:', error)
    }
  }

  const handleBook = () => {
    router.push(`/marketplace/bookings/new?serviceId=${listingId}`)
  }

  if (loading) {
    return (
      <PageTemplate
        title="Service Details"
        description="View service listing details"
        icon="ri-file-list-line"
      >
        <div className="bg-white rounded-xl shadow-lg p-12 text-center">
          <p className="text-slate-500">Loading service details...</p>
        </div>
      </PageTemplate>
    )
  }

  if (!listing) {
    return (
      <PageTemplate
        title="Service Not Found"
        description="The service you're looking for doesn't exist"
        icon="ri-error-warning-line"
      >
        <div className="bg-white rounded-xl shadow-lg p-12 text-center">
          <h3 className="text-xl font-semibold text-slate-800 mb-2">Service not found</h3>
          <p className="text-slate-500 mb-6">The service listing you're looking for doesn't exist</p>
          <button
            onClick={() => router.push('/marketplace/search')}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
          >
            Browse Services
          </button>
        </div>
      </PageTemplate>
    )
  }

  const getPrice = () => {
    if ('pricing' in listing) {
      const pricing = listing.pricing as any
      return {
        amount: pricing.basePrice || 0,
        currency: pricing.currency || 'SAR',
        model: pricing.model || 'FIXED',
      }
    }
    return { amount: 0, currency: 'SAR', model: 'FIXED' }
  }

  const getLocation = () => {
    if ('location' in listing) {
      const location = listing.location as any
      return {
        address: location.address || '',
        city: location.city || '',
        country: location.country || '',
        coordinates: location.coordinates,
      }
    }
    return { address: '', city: '', country: '', coordinates: undefined }
  }

  const price = getPrice()
  const location = getLocation()

  return (
    <PageTemplate
      title="Service Details"
      description={listing.providerName}
      icon="ri-file-list-line"
    >
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Service Overview */}
          <div className="bg-white rounded-xl shadow-lg p-6">
            <div className="flex items-start justify-between mb-4">
              <div className="flex-1">
                <div className="flex items-start justify-between mb-2">
                  <h2 className="text-2xl font-bold text-slate-800 mb-2">{listing.title || listing.providerName}</h2>
                  <FavoriteButton userId="default-user" listingId={listing.id} size="md" />
                </div>
                <p className="text-slate-500 mb-2">
                  {((listing as any).serviceCategory || 'Logistics Service').replace(/_/g, ' ')}
                </p>
                <div className="flex items-center space-x-2 mb-2">
                  <VerificationBadge verified={true} level="STANDARD" rating={listing.rating} />
                </div>
                <RealTimeIndicator listingId={listing.id} showViewerCount={true} />
              </div>
              <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                listing.availability === 'AVAILABLE'
                  ? 'bg-green-100 text-green-700'
                  : listing.availability === 'LIMITED'
                  ? 'bg-yellow-100 text-yellow-700'
                  : 'bg-red-100 text-red-700'
              }`}>
                {listing.availability}
              </span>
            </div>

            {/* Rating */}
            <div className="flex items-center space-x-4 mb-4">
              <div className="flex items-center">
                <Star className="w-5 h-5 text-yellow-500 fill-yellow-500" />
                <span className="ml-2 text-xl font-bold text-slate-800">{listing.rating.toFixed(1)}</span>
              </div>
              <span className="text-slate-500">
                ({listing.totalBookings} bookings)
              </span>
            </div>

            {/* Location */}
            {location.city && (
              <div className="flex items-center space-x-2 mb-4 text-slate-600">
                <MapPin className="w-5 h-5" />
                <span>{location.city}, {location.country}</span>
              </div>
            )}

            {/* Service Details */}
            {('serviceType' in listing) && (
              <div className="mb-4">
                <p className="text-sm text-slate-500 mb-1">Service Type</p>
                <p className="font-semibold text-slate-800">
                  {(listing as any).serviceType?.replace(/_/g, ' ') || 'Standard'}
                </p>
              </div>
            )}

            {/* Features */}
            {('features' in listing) && (listing as any).features && (
              <div className="mb-4">
                <p className="text-sm text-slate-500 mb-2">Features</p>
                <div className="flex flex-wrap gap-2">
                  {(listing as any).features.map((feature: string, idx: number) => (
                    <span
                      key={idx}
                      className="px-3 py-1 bg-blue-50 text-blue-700 text-sm rounded-full"
                    >
                      {feature}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {/* Capabilities */}
            {('capabilities' in listing) && (
              <div className="mb-4">
                <p className="text-sm text-slate-500 mb-2">Capabilities</p>
                <div className="grid grid-cols-2 gap-2">
                  {Object.entries((listing as any).capabilities || {}).map(([key, value]) => (
                    value && (
                      <div key={key} className="flex items-center space-x-2">
                        <CheckCircle className="w-4 h-4 text-green-600" />
                        <span className="text-sm text-slate-700">
                          {key.replace(/([A-Z])/g, ' $1').trim()}
                        </span>
                      </div>
                    )
                  ))}
                </div>
              </div>
            )}

            {/* Certifications */}
            {('certifications' in listing) && (listing as any).certifications && (listing as any).certifications.length > 0 && (
              <div>
                <p className="text-sm text-slate-500 mb-2">Certifications</p>
                <div className="flex flex-wrap gap-2">
                  {(listing as any).certifications.map((cert: string, idx: number) => (
                    <span
                      key={idx}
                      className="px-3 py-1 bg-green-50 text-green-700 text-sm rounded-full"
                    >
                      {cert}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Reviews */}
          <div className="bg-white rounded-xl shadow-lg p-6">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">Reviews ({reviews.length})</h3>
            {reviews.length === 0 ? (
              <p className="text-slate-500 text-center py-8">No reviews yet</p>
            ) : (
              <div className="space-y-4">
                {reviews.map((review) => (
                  <div key={review.id} className="border-b border-slate-200 pb-4 last:border-0">
                    <div className="flex items-start justify-between mb-2">
                      <div>
                        <p className="font-semibold text-slate-800">{review.customerName}</p>
                        <p className="text-xs text-slate-500">
                          {new Date(review.createdAt).toLocaleDateString()}
                        </p>
                      </div>
                      <div className="flex items-center">
                        <Star className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                        <span className="ml-1 font-semibold">{review.rating}</span>
                      </div>
                    </div>
                    <p className="text-slate-700">{review.review}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Sidebar */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-xl shadow-lg p-6 sticky top-6">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">Pricing</h3>

            <div className="space-y-4 mb-6">
              <div>
                <p className="text-sm text-slate-500 mb-1">Base Price</p>
                <p className="text-2xl font-bold text-slate-800">
                  {price.amount.toLocaleString()} {price.currency}
                </p>
                <p className="text-xs text-slate-400 mt-1">
                  {price.model?.replace(/_/g, ' ') || 'FIXED'}
                </p>
              </div>
            </div>

            <button
              onClick={handleBook}
              disabled={listing.availability === 'FULL'}
              className="w-full px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition font-semibold disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {listing.availability === 'FULL' ? 'Not Available' : 'Book Now'}
            </button>

            <div className="mt-6 pt-6 border-t border-slate-200">
              <h4 className="font-semibold text-slate-800 mb-3">Provider Contact</h4>
              <div className="space-y-2 text-sm">
                <div className="flex items-center space-x-2 text-slate-600">
                  <Building2 className="w-4 h-4" />
                  <span>{listing.providerName}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </PageTemplate>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import { CreditCard, Lock, CheckCircle, AlertCircle } from 'lucide-react'

export default function PaymentPage() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const bookingId = searchParams.get('bookingId')
  const [paymentMethod, setPaymentMethod] = useState<'MADA' | 'VISA' | 'MASTERCARD' | 'APPLE_PAY' | 'GOOGLE_PAY'>('MADA')
  const [processing, setProcessing] = useState(false)
  const [paymentIntent, setPaymentIntent] = useState<any>(null)

  useEffect(() => {
    if (bookingId) {
      createPaymentIntent()
    }
  }, [bookingId])

  const createPaymentIntent = async () => {
    try {
      const response = await fetch('/api/marketplace/payments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'create_intent',
          bookingId,
          amount: 5000, // Would get from booking
          currency: 'SAR',
          paymentMethod: 'MADA',
        }),
      })
      const result = await response.json()
      if (result.success) {
        setPaymentIntent(result.data)
      }
    } catch (error) {
      console.error('Failed to create payment intent:', error)
    }
  }

  const handlePayment = async () => {
    if (!paymentIntent) return

    setProcessing(true)
    try {
      const response = await fetch('/api/marketplace/payments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'process_payment',
          paymentIntentId: paymentIntent.id,
          paymentMethod,
        }),
      })
      const result = await response.json()
      if (result.success) {
        router.push(`/marketplace/bookings/${bookingId}?payment=success`)
      } else {
        alert('Payment failed. Please try again.')
      }
    } catch (error) {
      console.error('Payment failed:', error)
      alert('Payment failed. Please try again.')
    } finally {
      setProcessing(false)
    }
  }

  return (
    <PageTemplate
      title="Secure Payment"
      description="Complete your booking payment"
      icon="ri-bank-card-line"
    >
      <div className="max-w-2xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg p-6 space-y-6">
          {/* Security Badge */}
          <div className="flex items-center justify-center space-x-2 text-green-600 mb-4">
            <Lock className="w-5 h-5" />
            <span className="font-semibold">Secure Payment - SSL Encrypted</span>
          </div>

          {/* Payment Amount */}
          <div className="text-center py-6 border-b border-slate-200">
            <p className="text-sm text-slate-500 mb-2">Total Amount</p>
            <p className="text-4xl font-bold text-slate-800">
              {paymentIntent?.amount?.toLocaleString() || '5,000'} SAR
            </p>
          </div>

          {/* Payment Methods */}
          <div>
            <h3 className="font-semibold text-slate-800 mb-4">Select Payment Method</h3>
            <div className="grid grid-cols-2 gap-4">
              {(['MADA', 'VISA', 'MASTERCARD', 'APPLE_PAY', 'GOOGLE_PAY'] as const).map((method) => (
                <button
                  key={method}
                  onClick={() => setPaymentMethod(method)}
                  className={`p-4 border-2 rounded-lg transition ${
                    paymentMethod === method
                      ? 'border-blue-600 bg-blue-50'
                      : 'border-slate-200 hover:border-slate-300'
                  }`}
                >
                  <CreditCard className="w-6 h-6 mx-auto mb-2 text-slate-600" />
                  <span className="text-sm font-semibold text-slate-800">{method.replace('_', ' ')}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Payment Form */}
          {paymentMethod !== 'APPLE_PAY' && paymentMethod !== 'GOOGLE_PAY' && (
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Card Number</label>
                <input
                  type="text"
                  placeholder="1234 5678 9012 3456"
                  className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Expiry Date</label>
                  <input
                    type="text"
                    placeholder="MM/YY"
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">CVV</label>
                  <input
                    type="text"
                    placeholder="123"
                    className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Cardholder Name</label>
                <input
                  type="text"
                  placeholder="John Doe"
                  className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>
          )}

          {/* Terms */}
          <div className="flex items-start space-x-2 text-sm text-slate-600">
            <input type="checkbox" id="terms" className="mt-1" />
            <label htmlFor="terms">
              I agree to the terms and conditions and privacy policy. This payment is secure and encrypted.
            </label>
          </div>

          {/* Submit Button */}
          <button
            onClick={handlePayment}
            disabled={processing}
            className="w-full py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition font-semibold disabled:opacity-50 flex items-center justify-center space-x-2"
          >
            {processing ? (
              <>
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                <span>Processing...</span>
              </>
            ) : (
              <>
                <Lock className="w-5 h-5" />
                <span>Pay Securely</span>
              </>
            )}
          </button>

          {/* Security Info */}
          <div className="text-center text-xs text-slate-500 space-y-1">
            <p>🔒 Your payment is secured with 256-bit SSL encryption</p>
            <p>✅ ZATCA-compliant invoicing included</p>
            <p>🛡️ Protected by our payment guarantee</p>
          </div>
        </div>
      </div>
    </PageTemplate>
  )
}

/**
 * Predictive Pricing Dashboard
 * Comprehensive pricing analysis with AI recommendations
 * World-class UX with full drill-downs
 */

'use client'

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { motion } from 'framer-motion'
import {
  TrendingUp, TrendingDown, DollarSign, BarChart3, Target,
  AlertCircle, CheckCircle2, Info, Sparkles, ArrowLeft,
  Download, Share2, RefreshCw
} from 'lucide-react'
import { predictivePricingService } from '@/lib/services/marketplace/predictivePricingService'
import { LineChart, Line, BarChart, Bar, AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts'

export default function PredictivePricingPage() {
  const params = useParams()
  const router = useRouter()
  const listingId = params.listingId as string
  const [recommendation, setRecommendation] = useState<any>(null)
  const [marketAnalysis, setMarketAnalysis] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [selectedAlternative, setSelectedAlternative] = useState<number | null>(null)

  useEffect(() => {
    loadData()
  }, [listingId])

  const loadData = async () => {
    try {
      const [rec, analysis] = await Promise.all([
        predictivePricingService.getPricingRecommendation(listingId),
        predictivePricingService.analyzeMarket('STORAGE' as any), // Would get from listing
      ])
      setRecommendation(rec)
      setMarketAnalysis(analysis)
    } catch (error) {
      console.error('Failed to load pricing data:', error)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return <LoadingState />
  }

  if (!recommendation) {
    return <EmptyState />
  }

  const priceChange = ((recommendation.recommendedPrice - recommendation.currentPrice) / recommendation.currentPrice) * 100

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900">
      <div className="max-w-7xl mx-auto p-4 md:p-8">
        {/* Header */}
        <HeaderSection onBack={() => router.back()} />

        {/* Main Recommendation Card */}
        <MainRecommendationCard recommendation={recommendation} priceChange={priceChange} />

        {/* Market Analysis */}
        <MarketAnalysisSection analysis={marketAnalysis} />

        {/* Expected Impact */}
        <ExpectedImpactSection impact={recommendation.expectedImpact} />

        {/* Price Alternatives */}
        <PriceAlternativesSection
          alternatives={recommendation.alternatives}
          selected={selectedAlternative}
          onSelect={setSelectedAlternative}
        />

        {/* Factors Analysis */}
        <FactorsAnalysisSection factors={recommendation.factors} />

        {/* Reasoning */}
        <ReasoningSection reasoning={recommendation.reasoning} />
      </div>
    </div>
  )
}

function HeaderSection({ onBack }: { onBack: () => void }) {
  return (
    <motion.div
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      className="mb-8 flex items-center justify-between"
    >
      <div className="flex items-center gap-4">
        <button
          onClick={onBack}
          className="p-2 hover:bg-white dark:hover:bg-slate-800 rounded-lg transition-colors"
        >
          <ArrowLeft className="w-5 h-5" />
        </button>
        <div>
          <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">
            AI Pricing Recommendations
          </h1>
          <p className="text-slate-600 dark:text-slate-400 mt-1">
            Intelligent pricing optimization based on market analysis
          </p>
        </div>
      </div>
      <div className="flex gap-3">
        <button className="px-4 py-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors flex items-center gap-2">
          <Download className="w-4 h-4" />
          Export
        </button>
        <button className="px-4 py-2 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors flex items-center gap-2">
          <Share2 className="w-4 h-4" />
          Share
        </button>
      </div>
    </motion.div>
  )
}

function MainRecommendationCard({ recommendation, priceChange }: any) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="mb-6 bg-gradient-to-br from-blue-600 to-indigo-600 rounded-2xl shadow-2xl p-8 text-white"
    >
      <div className="flex items-start justify-between mb-6">
        <div>
          <div className="flex items-center gap-3 mb-4">
            <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-sm">
              <Sparkles className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-2xl font-bold">AI Recommendation</h2>
              <p className="text-blue-100">Confidence: {recommendation.confidence}%</p>
            </div>
          </div>
        </div>
        <div className="text-right">
          <div className="text-sm text-blue-100 mb-1">Current Price</div>
          <div className="text-2xl font-bold line-through opacity-75">
            SAR {recommendation.currentPrice.toLocaleString()}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
        <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
          <div className="text-sm text-blue-100 mb-2">Recommended Price</div>
          <div className="text-4xl font-bold mb-2">
            SAR {recommendation.recommendedPrice.toLocaleString()}
          </div>
          <div className={`flex items-center gap-2 text-sm ${
            priceChange >= 0 ? 'text-green-300' : 'text-red-300'
          }`}>
            {priceChange >= 0 ? <TrendingUp className="w-4 h-4" /> : <TrendingDown className="w-4 h-4" />}
            {Math.abs(priceChange).toFixed(1)}% {priceChange >= 0 ? 'increase' : 'decrease'}
          </div>
        </div>

        <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
          <div className="text-sm text-blue-100 mb-2">Expected Bookings Change</div>
          <div className={`text-4xl font-bold mb-2 ${
            (recommendation.expectedImpact.bookingsChange || 0) >= 0 ? 'text-green-300' : 'text-red-300'
          }`}>
            {recommendation.expectedImpact.bookingsChange >= 0 ? '+' : ''}
            {recommendation.expectedImpact.bookingsChange?.toFixed(1)}%
          </div>
          <div className="text-sm text-blue-100">Based on price elasticity</div>
        </div>

        <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
          <div className="text-sm text-blue-100 mb-2">Expected Revenue Change</div>
          <div className={`text-4xl font-bold mb-2 ${
            (recommendation.expectedImpact.revenueChange || 0) >= 0 ? 'text-green-300' : 'text-red-300'
          }`}>
            {recommendation.expectedImpact.revenueChange >= 0 ? '+' : ''}
            {recommendation.expectedImpact.revenueChange?.toFixed(1)}%
          </div>
          <div className="text-sm text-blue-100">Projected impact</div>
        </div>
      </div>

      <button className="w-full py-4 bg-white text-blue-600 rounded-xl font-semibold hover:bg-blue-50 transition-colors text-lg">
        Apply Recommended Price
      </button>
    </motion.div>
  )
}

function MarketAnalysisSection({ analysis }: any) {
  if (!analysis) return null

  const chartData = [
    { name: 'Min', value: analysis.priceRange.min },
    { name: 'Q1', value: analysis.priceRange.q1 },
    { name: 'Median', value: analysis.priceRange.median },
    { name: 'Q3', value: analysis.priceRange.q3 },
    { name: 'Max', value: analysis.priceRange.max },
  ]

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="mb-6 bg-white dark:bg-slate-800 rounded-2xl shadow-xl p-6 border border-slate-200 dark:border-slate-700"
    >
      <h3 className="text-2xl font-bold mb-6 flex items-center gap-3">
        <BarChart3 className="w-6 h-6 text-blue-600" />
        Market Analysis
      </h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <div className="mb-4">
            <div className="text-sm text-slate-500 dark:text-slate-400 mb-1">Market Average</div>
            <div className="text-3xl font-bold">SAR {analysis.marketAverage.toLocaleString()}</div>
          </div>
          <div className="mb-4">
            <div className="text-sm text-slate-500 dark:text-slate-400 mb-1">Price Range</div>
            <div className="text-lg font-semibold">
              SAR {analysis.priceRange.min.toLocaleString()} - {analysis.priceRange.max.toLocaleString()}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {analysis.trends.direction === 'UP' ? (
              <TrendingUp className="w-5 h-5 text-green-500" />
            ) : analysis.trends.direction === 'DOWN' ? (
              <TrendingDown className="w-5 h-5 text-red-500" />
            ) : (
              <Target className="w-5 h-5 text-blue-500" />
            )}
            <span className="text-sm font-medium">
              {analysis.trends.direction} {Math.abs(analysis.trends.changePercent).toFixed(1)}%
            </span>
          </div>
        </div>
        <div>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="value" fill="#3b82f6" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </motion.div>
  )
}

function ExpectedImpactSection({ impact }: any) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="mb-6 bg-white dark:bg-slate-800 rounded-2xl shadow-xl p-6 border border-slate-200 dark:border-slate-700"
    >
      <h3 className="text-2xl font-bold mb-6">Expected Impact</h3>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <ImpactCard
          title="Bookings"
          value={impact.bookingsChange}
          unit="%"
          positive={impact.bookingsChange >= 0}
        />
        <ImpactCard
          title="Revenue"
          value={impact.revenueChange}
          unit="%"
          positive={impact.revenueChange >= 0}
        />
        <ImpactCard
          title="Conversion"
          value={impact.conversionChange}
          unit="%"
          positive={impact.conversionChange >= 0}
        />
      </div>
    </motion.div>
  )
}

function ImpactCard({ title, value, unit, positive }: any) {
  return (
    <div className={`p-6 rounded-xl border-2 ${
      positive
        ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800'
        : 'bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800'
