/**
 * Enhanced Intelligent Search Interface
 * Semantic search with intent understanding and entity extraction
 * World-class UX with real-time suggestions and results
 */

'use client'

import { useState, useEffect, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Search, Sparkles, Filter, TrendingUp, MapPin, DollarSign,
  Clock, CheckCircle2, AlertCircle, ArrowRight, X, Lightbulb,
  Target, Zap, Globe, Package, Truck, Building2
} from 'lucide-react'
import { intelligentSearchService } from '@/lib/services/marketplace/intelligentSearchService'
import { marketplaceService } from '@/lib/services/marketplace/marketplaceService'

export default function IntelligentSearchPage() {
  const router = useRouter()
  const [query, setQuery] = useState('')
  const [searchResults, setSearchResults] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [intent, setIntent] = useState<any>(null)
  const [entities, setEntities] = useState<any>(null)
  const [suggestions, setSuggestions] = useState<string[]>([])
  const [showFilters, setShowFilters] = useState(false)
  const [filters, setFilters] = useState<any>({})

  useEffect(() => {
    if (query.length > 2) {
      performSearch()
    } else {
      setSearchResults(null)
      setIntent(null)
      setEntities(null)
    }
  }, [query, filters])

  const performSearch = async () => {
    setLoading(true)
    try {
      const result = await intelligentSearchService.search({
        query,
        filters,
      })
      setSearchResults(result)
      setIntent(result.intent)
      setEntities(result.entities)
      setSuggestions(result.suggestions || [])
    } catch (error) {
      console.error('Search failed:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSearch = (searchQuery: string) => {
    setQuery(searchQuery)
  }

  const intentIcon = useMemo(() => {
    if (!intent) return Search
    const icons: Record<string, any> = {
      FIND_SERVICE: Search,
      COMPARE: TrendingUp,
      GET_QUOTE: DollarSign,
      LEARN_MORE: Lightbulb,
      BOOK_NOW: CheckCircle2,
    }
    return icons[intent.type] || Search
  }, [intent])

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900">
      <div className="max-w-7xl mx-auto p-4 md:p-8">
        {/* Header */}
        <HeaderSection />

        {/* Search Bar */}
        <SearchBarSection
          query={query}
          onQueryChange={setQuery}
          onSearch={handleSearch}
          loading={loading}
          suggestions={suggestions}
        />

        {/* Intent & Entities */}
        {(intent || entities) && (
          <IntentEntitiesSection intent={intent} entities={entities} intentIcon={intentIcon} />
        )}

        {/* Filters */}
        <FiltersSection
          show={showFilters}
          filters={filters}
          onFiltersChange={setFilters}
          onToggle={() => setShowFilters(!showFilters)}
        />

        {/* Search Results */}
        <SearchResultsSection
          results={searchResults}
          loading={loading}
          onResultClick={(id) => router.push(`/marketplace/listings/${id}`)}
        />

        {/* Related Categories */}
        {searchResults?.relatedCategories && (
          <RelatedCategoriesSection categories={searchResults.relatedCategories} />
        )}
      </div>
    </div>
  )
}

function HeaderSection() {
  return (
    <motion.div
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      className="mb-8 text-center"
    >
      <h1 className="text-4xl font-bold text-slate-900 dark:text-white flex items-center justify-center gap-3 mb-2">
        <Sparkles className="w-10 h-10 text-blue-600" />
        Intelligent Search
      </h1>
      <p className="text-slate-600 dark:text-slate-400">
        AI-powered semantic search with intent understanding
      </p>
    </motion.div>
  )
}

function SearchBarSection({
  query,
  onQueryChange,
  onSearch,
  loading,
  suggestions,
}: {
  query: string
  onQueryChange: (q: string) => void
  onSearch: (q: string) => void
