                >
                  <Search className="w-4 h-4 text-slate-400" />
                  <span className="text-slate-700 dark:text-slate-300">{suggestion}</span>
                </button>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  )
}

