  // Poll active batch job status (multi-tenant safe via apiFetch headers)
  useEffect(() => {
    // Poll active job if exists, otherwise poll last job once to show final state
    const jobIdToPoll = activeJobId || lastJobId
    if (!jobIdToPoll) {
      // Clear localStorage if no job IDs
      try {
        if (typeof window !== 'undefined') {
          window.localStorage.removeItem('msds_active_job_id')
          window.localStorage.removeItem('msds_last_job_id')
        }
      } catch {
        // ignore
      }
      return
    }

    try {
      if (activeJobId && typeof window !== 'undefined') window.localStorage.setItem('msds_active_job_id', activeJobId)
    } catch {
      // ignore
    }
    let cancelled = false
    let hasPolledLastJob = false
    let pollCount = 0
    const MAX_POLLS = 300 // 10 minutes max (300 * 2 seconds)
    const STUCK_JOB_TIMEOUT = 10 * 60 * 1000 // 10 minutes in milliseconds
    const jobStartTime = activeJobId ? Date.now() : null

    const tick = async () => {
      // If polling lastJobId (not active), only poll once
      if (!activeJobId && lastJobId && hasPolledLastJob) {
        cancelled = true
        return
      }

      pollCount++

      // Timeout detection: if job has been running for too long, mark as potentially stuck
      if (activeJobId && jobStartTime && (Date.now() - jobStartTime) > STUCK_JOB_TIMEOUT) {
        console.warn('[msds] Job appears stuck, timeout exceeded:', jobIdToPoll)
        setNotification({
          show: true,
          type: 'warning',
          title: 'Processing Taking Longer Than Expected',
          message: 'The job is still running. This may indicate a slow LLM response or network issue. Check your API keys in Settings.'
        })
      }

      // Safety: stop polling after max attempts
      if (pollCount > MAX_POLLS) {
        console.warn('[msds] Max poll attempts reached, stopping:', jobIdToPoll)
        cancelled = true
        setActiveJobId(null)
        setNotification({
          show: true,
          type: 'warning',
          title: 'Polling Timeout',
          message: 'Job status polling stopped after maximum attempts. The job may still be processing.'
        })
        return
      }

      try {
        const res = await apiFetch(`/api/chemical/msds/jobs/${jobIdToPoll}`)
        if (!res.ok) {
          // If job not found and we've polled a few times, stop
          if (res.status === 404 && pollCount > 3) {
            console.warn('[msds] Job not found after multiple attempts:', jobIdToPoll)
            cancelled = true
            setActiveJobId(null)
            setLastJobId(null)
            setJobSnapshot(null)
            setLastJobSummary(null)
            setJobNotFound(true)
            // Clear from localStorage
            try {
              if (typeof window !== 'undefined') {
                window.localStorage.removeItem('msds_active_job_id')
                window.localStorage.removeItem('msds_last_job_id')
              }
            } catch {
              // ignore
            }
            return
          }
          throw new Error(`HTTP ${res.status}`)
        }

        const json = await res.json()
        if (!json?.success || !json?.job) {
          // If job doesn't exist after initial polls, stop
          if (pollCount > 3) {
            cancelled = true
            setActiveJobId(null)
            setLastJobId(null)
            setJobSnapshot(null)
            setLastJobSummary(null)
            setJobNotFound(true)
            // Clear from localStorage
            try {
              if (typeof window !== 'undefined') {
                window.localStorage.removeItem('msds_active_job_id')
                window.localStorage.removeItem('msds_last_job_id')
              }
            } catch {
              // ignore
            }
          }
          return
        }

        // Job found, clear not found state
        setJobNotFound(false)

        const job = json.job
        setJobSnapshot(job)

        if (cancelled) return

        // Only update batch processing state for active jobs
        if (activeJobId) {
          setBatchProcessing(job.status === 'queued' || job.status === 'running')
          setBatchProgress(Number(job.progress || 0))
        } else if (lastJobId) {
          // For last job, just set progress once
          setBatchProgress(Number(job.progress || 0))
          hasPolledLastJob = true
        }

        // Update matching submissions (by filename) - only for active jobs
        if (activeJobId) {
          setSubmissions(prev => prev.map(s => {
          const item = (job.items || []).find((it: any) => it.filename === s.file.name)
          if (!item) return s

          if (item.status === 'queued') {
            return { ...s, status: 'uploading' }
          }
          if (item.status === 'running') {
            return { ...s, status: 'analyzing' }
          }
          if (item.status === 'failed') {
            const minimal = mapExtractedToUi({}, s.file.name)
            return {
              ...s,
              status: 'review',
              extractedData: minimal,
              parsingIssues: {
                isProtected: false,
                isImageOnly: false,
                lowConfidence: true,
                message: item.error || 'Batch analysis failed for this file'
              }
            }
          }
          if (item.status === 'completed') {
            const extracted = item.result?.extractedData || {}
            const uiData = mapExtractedToUi(extracted, s.file.name)
            const issues = Array.isArray(item.result?.issues) ? item.result.issues : []
            const lowConfidence = Number(item.result?.confidence || 0) < 50
            const issueMsg = issues
              .filter((i: any) => i?.severity === 'error' || i?.severity === 'warning' || i?.code === 'LOW_COMPLETENESS')
              .map((i: any) => i?.message)
              .filter(Boolean)
              .join('; ')

            return {
              ...s,
              status: 'review',
              extractedData: uiData,
              parsingIssues: (lowConfidence || issueMsg)
                ? {
                    isProtected: false,
                    isImageOnly: false,
                    lowConfidence,
                    message: issueMsg || 'Low confidence extraction. Manual review required.'
                  }
                : undefined
            }
          }
          return s
          }))
        }

        // Completed?
        if (job.status === 'completed' || job.status === 'failed') {
          const successful = (job.items || []).filter((i: any) => i.status === 'completed').length
          const failed = (job.items || []).filter((i: any) => i.status === 'failed').length
          const summary = {
            successful,
            failed,
            details: (job.items || []).map((i: any) => ({
              fileName: i.filename,
              status: i.status === 'completed' ? 'success' : 'failed',
              error: i.error
            }))
          }
          setBatchResults(summary)
          setLastJobId(String(job.id))
          setLastJobSummary(summary)
          try {
            if (typeof window !== 'undefined') {
              window.localStorage.setItem('msds_last_job_id', String(job.id))
              window.localStorage.setItem('msds_last_job_summary', JSON.stringify(summary))
            }
          } catch {
            // ignore
          }
          setActiveJobId(null)
          try {
            if (typeof window !== 'undefined') window.localStorage.removeItem('msds_active_job_id')
          } catch {
            // ignore
          }
          setNotification({
            show: true,
            type: failed > 0 ? 'error' : 'success',
            title: 'Batch Processing Complete',
            message: `${successful} successful, ${failed} failed`
          })
        }
      } catch (error) {
        // Log polling errors for debugging
        console.error('[msds] Polling error:', error)
        // If we've polled multiple times and still getting errors, stop
        if (pollCount > 10) {
          cancelled = true
          setActiveJobId(null)
          setNotification({
            show: true,
            type: 'error',
            title: 'Job Status Error',
            message: 'Unable to fetch job status. The job may have failed or been cancelled.'
          })
        }
      }
    }

    tick()
    // Poll every 2 seconds for active jobs, or once for last job
    const pollInterval = activeJobId ? 2000 : 5000
    const interval = setInterval(() => {
      if (!cancelled) tick()
    }, pollInterval)
    return () => {
      cancelled = true
      clearInterval(interval)
    }
  }, [activeJobId, lastJobId, mapExtractedToUi])

