                  <label
                    key={option}
                    className="flex items-start gap-3 p-3 rounded-lg bg-gray-800 hover:bg-gray-700 cursor-pointer transition border border-gray-700 hover:border-orange-500/30"
                  >
                    <input
                      type="checkbox"
                      checked={requestedInfo.includes(option)}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setRequestedInfo([...requestedInfo, option])
                        } else {
                          setRequestedInfo(requestedInfo.filter(i => i !== option))
                        }
                      }}
                      className="mt-1 w-4 h-4 rounded border-gray-600 text-orange-500 focus:ring-orange-500"
                    />
                    <span className="text-sm text-gray-300">{option}</span>
                  </label>
                ))}
              </div>

              {/* Custom Request */}
              <div>
                <label className="block text-sm font-medium mb-2 text-gray-300">
                  Custom Request (Optional)
                </label>
                <textarea
                  value={customRequest}
                  onChange={(e) => setCustomRequest(e.target.value)}
                  placeholder="Specify any other information you need..."
                  className="w-full px-4 py-3 rounded-lg bg-gray-800 border border-gray-700 focus:border-orange-500/50 outline-none transition text-white resize-none"
                  rows={4}
                />
              </div>

              {/* Actions */}
              <div className="flex gap-3">
                <button
                  onClick={async () => {
                    if (requestedInfo.length === 0 && !customRequest.trim()) {
                      setNotification({
                        show: true,
                        type: 'error',
                        title: 'No Information Selected',
                        message: 'Please select at least one item or add a custom request'
                      })
                      return
                    }

                    try {
                      const requestList = [...requestedInfo]
                      if (customRequest.trim()) {
                        requestList.push(`Custom: ${customRequest.trim()}`)
                      }

                      await apiFetch('/api/erpnext/send-email', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                          to: selectedSubmission.customerEmail || 'customer@example.com',
                          subject: `Additional Information Required: ${selectedSubmission.extractedData?.productName}`,
                          message: `
                            <h2>Additional Information Needed for MSDS Review</h2>
                            <p><strong>Product:</strong> ${selectedSubmission.extractedData?.productName}</p>
                            <p><strong>CAS Number:</strong> ${selectedSubmission.extractedData?.casNumber}</p>
                            <p><strong>Manufacturer:</strong> ${selectedSubmission.extractedData?.manufacturer}</p>

                            <h3>Please provide the following information:</h3>
                            <ul>
                              ${requestList.map(item => `<li>${item}</li>`).join('')}
                            </ul>

                            ${selectedSubmission.manualNotes ? `<p><strong>Reviewer Notes:</strong> ${selectedSubmission.manualNotes}</p>` : ''}

                            <p>Please respond with this information to complete your MSDS review.</p>
                            <p><strong>Reference:</strong> ${selectedSubmission.id}</p>
                          `,
                          reference_doctype: 'Communication'
                        })
                      })

                      setShowRequestInfoModal(false)
                      setNotification({
                        show: true,
                        type: 'success',
                        title: 'Request Sent',
                        message: `Email sent to customer with ${requestList.length} information requests`
                      })
                    } catch (error) {
                      setNotification({
                        show: true,
                        type: 'error',
                        title: 'Send Failed',
                        message: 'Could not send email request'
                      })
                    }
                  }}
                  className="flex-1 px-6 py-3 rounded-xl bg-gradient-to-r from-orange-500 to-amber-600 font-bold hover:shadow-lg hover:shadow-orange-500/50 transition"
                >
                  Send Request ({requestedInfo.length + (customRequest.trim() ? 1 : 0)} items)
                </button>

                <button
                  onClick={() => setShowRequestInfoModal(false)}
                  className="px-6 py-3 rounded-lg bg-gray-700 border border-gray-600 hover:border-gray-500 transition font-medium"
                >
                  Cancel
                </button>
              </div>
            </div>
          </Modal>
        )}
      </AnimatePresence>

      {/* Enhanced Notification with Intelligent Auto-Dismiss */}
      <AnimatePresence>
        {notification.show && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -20, scale: 0.95, transition: { duration: 0.3 } }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            onMouseEnter={() => setIsNotificationPaused(true)}
            onMouseLeave={() => setIsNotificationPaused(false)}
            className={`fixed bottom-4 right-4 p-4 rounded-lg border backdrop-blur-sm shadow-2xl ${
              notification.type === 'success' ? 'bg-green-500/10 border-green-500/30 text-green-400' :
              notification.type === 'error' ? 'bg-red-500/10 border-red-500/30 text-red-400' :
              'bg-blue-500/10 border-blue-500/30 text-blue-400'
            } z-50 max-w-md overflow-hidden`}
          >
            {/* Progress Bar */}
            <motion.div
              className={`absolute top-0 left-0 h-1 ${
                notification.type === 'success' ? 'bg-green-400' :
                notification.type === 'error' ? 'bg-red-400' :
                'bg-blue-400'
              }`}
              style={{ width: `${notificationProgress}%` }}
              transition={{ duration: 0.1, ease: 'linear' }}
            />

            <div className="flex items-start gap-3 relative">
              <motion.i
                className={`${
                  notification.type === 'success' ? 'ri-checkbox-circle-line' :
                  notification.type === 'error' ? 'ri-close-circle-line' :
                  'ri-information-line'
                } text-xl`}
                animate={notification.type === 'success' ? {
                  scale: [1, 1.2, 1],
                  rotate: [0, 10, -10, 0]
                } : {}}
                transition={{ duration: 0.5, delay: 0.2 }}
              />
              <div className="flex-1">
                <h4 className="font-bold mb-1">{notification.title}</h4>
                <p className="text-sm opacity-90">{notification.message}</p>
              </div>
              <motion.button
                onClick={() => setNotification({ ...notification, show: false })}
                className="text-gray-400 hover:text-white transition-colors p-1 rounded hover:bg-white/10"
                whileHover={{ scale: 1.1, rotate: 90 }}
                whileTap={{ scale: 0.9 }}
                title="Dismiss"
              >
                <i className="ri-close-line"></i>
              </motion.button>
            </div>

            {/* Pause indicator when hovering */}
            {isNotificationPaused && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="absolute top-2 right-2 text-xs text-gray-400 flex items-center gap-1"
              >
                <i className="ri-pause-line"></i>
                <span>Paused</span>
              </motion.div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* PDF Viewer */}
      <AnimatePresence>
        {showPDFViewer && pdfViewerFile && (
          <PDFViewer
            fileUrl={pdfViewerFile}
            fileName={pdfViewerFileName}
            onClose={() => {
              setShowPDFViewer(false)
              setPdfViewerFile(null)
              setPdfViewerFileName('')
            }}
            readOnly={false}
          />
        )}
      </AnimatePresence>

      {/* Bulk Action Modal */}
      <AnimatePresence>
        {bulkAction && (
          <Modal
            isOpen={!!bulkAction}
            onClose={() => {
              setBulkAction(null)
              setBulkReason('')
            }}
            title={bulkAction === 'approve' ? 'Bulk Approve MSDS' : 'Bulk Reject MSDS'}
            size="md"
          >
            <div className="space-y-4">
              <p className="text-sm text-gray-300">
                {bulkAction === 'approve' 
                  ? `You are about to approve ${selectedIds.size} MSDS document(s).`
                  : `You are about to reject ${selectedIds.size} MSDS document(s). Please provide a reason.`
                }
              </p>

              {bulkAction === 'reject' && (
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-2">
                    Rejection Reason *
                  </label>
                  <textarea
                    value={bulkReason}
                    onChange={(e) => setBulkReason(e.target.value)}
                    placeholder="Enter reason for rejection..."
                    className="w-full px-4 py-3 rounded-lg bg-gray-800 border border-gray-700 focus:border-red-500/50 outline-none text-white resize-none"
                    rows={4}
                    required
                  />
                </div>
              )}

              <div className="flex gap-3">
                <button
                  onClick={async () => {
                    if (bulkAction === 'reject' && !bulkReason.trim()) {
                      setNotification({
                        show: true,
                        type: 'error',
                        title: 'Reason Required',
                        message: 'Please provide a rejection reason'
                      })
                      return
                    }

                    setProcessing(true)
                    try {
                      const response = await apiFetch(
                        bulkAction === 'approve' 
                          ? '/api/chemical/msds/bulk-approve'
                          : '/api/chemical/msds/bulk-reject',
                        {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({
                            msdsIds: Array.from(selectedIds),
                            reason: bulkReason,
                            comments: bulkAction === 'approve' ? 'Bulk approved' : undefined
                          })
                        }
                      )

                      const result = await response.json()

                      if (result.success) {
                        // Update submission statuses
                        setSubmissions(prev => prev.map(s => 
                          selectedIds.has(s.id) 
                            ? { ...s, status: bulkAction === 'approve' ? 'approved' : 'rejected' }
                            : s
                        ))

                        setSelectedIds(new Set())
                        setBulkAction(null)
                        setBulkReason('')

                        setNotification({
                          show: true,
                          type: 'success',
                          title: `Bulk ${bulkAction === 'approve' ? 'Approval' : 'Rejection'} Complete`,
                          message: `${result.result.successful} successful, ${result.result.failed} failed`
                        })
                      }
                    } catch (error) {
                      setNotification({
                        show: true,
                        type: 'error',
                        title: 'Bulk Action Failed',
                        message: error instanceof Error ? error.message : 'Unknown error'
                      })
                    } finally {
                      setProcessing(false)
                    }
                  }}
                  disabled={processing}
                  className={`flex-1 px-6 py-3 rounded-xl font-bold transition disabled:opacity-50 ${
                    bulkAction === 'approve'
                      ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700'
                      : 'bg-gradient-to-r from-red-500 to-rose-600 hover:from-red-600 hover:to-rose-700'
                  } text-white`}
                >
                  {bulkAction === 'approve' ? 'Approve All' : 'Reject All'}
                </button>
                <button
                  onClick={() => {
                    setBulkAction(null)
                    setBulkReason('')
                  }}
                  className="px-6 py-3 rounded-lg bg-gray-700 hover:bg-gray-600 text-gray-300 transition"
                >
                  Cancel
                </button>
              </div>
            </div>
          </Modal>
        )}
      </AnimatePresence>
    </PageTemplate>
  )
}

/**
 * My CAPA Workspace - Enhanced
 * Personal CAPA workspace for assigned corrective and preventive actions
 * Fully functional with ERPNext integration
 * 
 * Migrated from chemcheck-ai/pages/my-capa-workspace.tsx
 * Adapted for BlueDXP Platform (App Router)
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { useRouter } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import ModuleLinks from '@/components/ModuleLinks'
import { getISOIMSLinks, getCAPALinks } from '@/utils/moduleInterconnectivity'
import EditCAPAModal from '@/components/ims/EditCAPAModal'

interface CAPA {
  id: string
  capaNumber: string
  subject: string
  status: 'Open' | 'In Progress' | 'Under Review' | 'Completed' | 'Closed'
  priority: 'Low' | 'Medium' | 'High' | 'Critical'
  capaType: 'Corrective Action' | 'Preventive Action'
  capaSource: 'NCR' | 'Audit' | 'Risk' | 'Customer Complaint' | 'Management Review' | 'Other'
  assignedTo: string
  department: string
  targetDate: string
  completionDate?: string
  rootCause: string
  actionPlan: string
  effectivenessReview?: string
  linkedNCR?: string
  linkedMaterial?: string
  linkedOrder?: string
  linkedLocation?: string
  linkedCustomer?: string
  linkedSupplier?: string
  progress?: number
}

export default function MyCAPAWorkspacePage() {
  const router = useRouter()
  const [myCAPAs, setMyCAPAs] = useState<CAPA[]>([])
  const [loading, setLoading] = useState(true)
  const [showEditModal, setShowEditModal] = useState(false)
  const [selectedCAPA, setSelectedCAPA] = useState<CAPA | null>(null)
  const [filterStatus, setFilterStatus] = useState('all')
  const [filterPriority, setFilterPriority] = useState('all')
  const [currentUser, setCurrentUser] = useState('')

  useEffect(() => {
    const userEmail = localStorage.getItem('user_email') || 'b.albayaty@scsflex.com'
    setCurrentUser(userEmail)
    fetchMyCAPAs(userEmail)
  }, [])

  const fetchMyCAPAs = async (email: string) => {
    try {
      const response = await fetch(`/api/erpnext/capas?assigned_to=${encodeURIComponent(email)}`).catch(() => null)
      if (response?.ok) {
        const data = await response.json()
        const transformedCAPAs = (data.capas || data.data || []).map((capa: any) => ({
          id: capa.name || capa.id,
          capaNumber: capa.name || `CAPA-${Date.now()}`,
          subject: capa.subject || capa.title,
          status: capa.status || 'Open',
          priority: (capa.priority || 'Medium') as CAPA['priority'],
          capaType: capa.capa_type || 'Corrective Action',
          capaSource: capa.capa_source || 'Audit',
          assignedTo: capa.assigned_to || email,
          department: capa.department || '',
          targetDate: capa.exp_end_date || capa.target_date || '',
          completionDate: capa.completion_date,
          rootCause: capa.root_cause || '',
          actionPlan: capa.action_plan || capa.description || '',
          effectivenessReview: capa.effectiveness_review,
          linkedNCR: capa.linked_ncr,
          linkedMaterial: capa.linked_material,
          linkedOrder: capa.linked_order,
          linkedLocation: capa.linked_location,
          linkedCustomer: capa.linked_customer,
          linkedSupplier: capa.linked_supplier,
          progress: calculateProgress(capa)
        }))
        setMyCAPAs(transformedCAPAs)
      } else {
        // Use mock data
        setMyCAPAs(generateMockCAPAs(email))
      }
    } catch (error) {
      console.error('Error fetching my CAPAs:', error)
      setMyCAPAs(generateMockCAPAs(email))
    } finally {
      setLoading(false)
    }
  }

  const calculateProgress = (capa: any): number => {
    if (capa.status === 'Completed' || capa.status === 'Closed') return 100
    if (capa.status === 'Under Review') return 75
    if (capa.status === 'In Progress') return 50
    return 25
  }

  const generateMockCAPAs = (email: string): CAPA[] => {
    return [
      {
        id: 'capa-001',
        capaNumber: 'CAPA-2025-001',
        subject: 'Improve Chemical Storage Procedures',
        status: 'In Progress',
        priority: 'High',
        capaType: 'Corrective Action',
        capaSource: 'NCR',
        assignedTo: email,
        department: 'Warehouse',
        targetDate: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
        rootCause: 'Inadequate storage procedures led to chemical compatibility issues',
        actionPlan: '1. Review and update storage procedures\n2. Train staff on new procedures\n3. Implement segregation requirements',
        progress: 50,
        linkedNCR: 'NCR-2025-001'
      },
      {
        id: 'capa-002',
        capaNumber: 'CAPA-2025-002',
        subject: 'Enhance Quality Control Measures',
        status: 'Open',
        priority: 'Medium',
        capaType: 'Preventive Action',
        capaSource: 'Audit',
        assignedTo: email,
        department: 'Quality',
        targetDate: new Date(Date.now() + 60 * 24 * 60 * 60 * 1000).toISOString(),
        rootCause: 'Potential quality issues identified during audit',
        actionPlan: 'Implement additional quality checkpoints',
        progress: 25
      },
      {
        id: 'capa-003',
        capaNumber: 'CAPA-2025-003',
        subject: 'Update Safety Training Program',
        status: 'Under Review',
        priority: 'High',
        capaType: 'Corrective Action',
        capaSource: 'Risk',
        assignedTo: email,
        department: 'Safety',
        targetDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
        rootCause: 'Safety training program needs updating based on new regulations',
        actionPlan: '1. Review current training materials\n2. Update with new requirements\n3. Schedule training sessions',
        progress: 75
      }
    ]
  }

  const handleUpdateCAPA = async (updatedCAPA: CAPA) => {
    try {
      setMyCAPAs(myCAPAs.map(capa => 
        capa.id === updatedCAPA.id ? { ...updatedCAPA, progress: calculateProgress(updatedCAPA) } : capa
      ))
      setShowEditModal(false)
      setSelectedCAPA(null)
    } catch (error) {
      console.error('Error updating CAPA:', error)
    }
  }

  const filteredCAPAs = myCAPAs.filter(capa => {
    const matchesStatus = filterStatus === 'all' || capa.status === filterStatus
    const matchesPriority = filterPriority === 'all' || capa.priority === filterPriority
    return matchesStatus && matchesPriority
  })

  const priorityColors = {
    Low: 'bg-green-100 dark:bg-green-900 text-green-800 dark:text-green-200',
    Medium: 'bg-yellow-100 dark:bg-yellow-900 text-yellow-800 dark:text-yellow-200',
    High: 'bg-orange-100 dark:bg-orange-900 text-orange-800 dark:text-orange-200',
    Critical: 'bg-red-100 dark:bg-red-900 text-red-800 dark:text-red-200'
  }

  const statusColors = {
    Open: 'bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200',
    'In Progress': 'bg-yellow-100 dark:bg-yellow-900 text-yellow-800 dark:text-yellow-200',
    'Under Review': 'bg-purple-100 dark:bg-purple-900 text-purple-800 dark:text-purple-200',
    Completed: 'bg-green-100 dark:bg-green-900 text-green-800 dark:text-green-200',
    Closed: 'bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-200'
  }

  const getDaysRemaining = (targetDate: string): number => {
    const days = Math.ceil((new Date(targetDate).getTime() - Date.now()) / (24 * 60 * 60 * 1000))
    return days
  }

  return (
    <PageTemplate
      title="My CAPA Workspace"
      description="Manage your assigned Corrective and Preventive Actions. Track progress, update status, and complete actions."
      icon="ri-tools-line"
      stats={[
        {
          label: 'My CAPAs',
          value: myCAPAs.length,
          icon: 'ri-file-list-line'
        },
        {
          label: 'In Progress',
          value: myCAPAs.filter(c => c.status === 'In Progress').length,
          icon: 'ri-time-line'
        },
        {
          label: 'Due Soon',
          value: myCAPAs.filter(c => {
            const days = getDaysRemaining(c.targetDate)
            return days <= 7 && days > 0 && c.status !== 'Completed' && c.status !== 'Closed'
          }).length,
          icon: 'ri-alarm-line'
        }
      ]}
      actions={
        <button
          onClick={() => router.push('/capa-management?create=true')}
          className="px-4 py-2 bg-orange-600 hover:bg-orange-700 text-white rounded-lg transition-colors flex items-center gap-2"
        >
          <i className="ri-add-line"></i>
          New CAPA
        </button>
      }
    >
      <ModuleLinks links={[...getISOIMSLinks(), ...getCAPALinks()]} />

      {/* Filters */}
      <div className="mb-6 flex flex-col sm:flex-row gap-4">
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
        >
          <option value="all">All Status</option>
          <option value="Open">Open</option>
          <option value="In Progress">In Progress</option>
          <option value="Under Review">Under Review</option>
          <option value="Completed">Completed</option>
          <option value="Closed">Closed</option>
        </select>
        <select
          value={filterPriority}
          onChange={(e) => setFilterPriority(e.target.value)}
          className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
        >
          <option value="all">All Priorities</option>
          <option value="Low">Low</option>
          <option value="Medium">Medium</option>
          <option value="High">High</option>
          <option value="Critical">Critical</option>
        </select>
      </div>

      {/* CAPAs List */}
      {loading ? (
        <div className="text-center py-12">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-orange-600"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">Loading your CAPAs...</p>
        </div>
      ) : filteredCAPAs.length === 0 ? (
        <div className="text-center py-12">
          <i className="ri-tools-line text-6xl text-gray-300 dark:text-gray-600 mb-4"></i>
          <p className="text-gray-600 dark:text-gray-400">No CAPAs assigned to you</p>
        </div>
      ) : (
        <div className="space-y-4">
          {filteredCAPAs.map((capa) => {
            const daysRemaining = getDaysRemaining(capa.targetDate)
            const isOverdue = daysRemaining < 0 && capa.status !== 'Completed' && capa.status !== 'Closed'
            const isDueSoon = daysRemaining <= 7 && daysRemaining > 0 && capa.status !== 'Completed' && capa.status !== 'Closed'

            return (
              <motion.div
                key={capa.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 hover:shadow-lg transition-shadow"
              >
                <div className="flex items-start justify-between mb-4">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
                        {capa.subject}
                      </h3>
                      <span className={`px-2 py-1 text-xs font-medium rounded-full ${priorityColors[capa.priority]}`}>
                        {capa.priority}
                      </span>
                      <span className={`px-2 py-1 text-xs font-medium rounded-full ${statusColors[capa.status]}`}>
                        {capa.status}
                      </span>
                      {isOverdue && (
                        <span className="px-2 py-1 text-xs font-medium rounded-full bg-red-100 dark:bg-red-900 text-red-800 dark:text-red-200">
                          Overdue
                        </span>
                      )}
                      {isDueSoon && !isOverdue && (
                        <span className="px-2 py-1 text-xs font-medium rounded-full bg-orange-100 dark:bg-orange-900 text-orange-800 dark:text-orange-200">
                          Due Soon
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-4 text-sm text-gray-600 dark:text-gray-400 mb-3">
                      <span className="flex items-center gap-1">
                        <i className="ri-file-text-line"></i>
                        {capa.capaNumber}
                      </span>
                      <span className="flex items-center gap-1">
                        <i className="ri-calendar-line"></i>
                        Due: {new Date(capa.targetDate).toLocaleDateString()}
                        {isOverdue && <span className="text-red-600 dark:text-red-400">({Math.abs(daysRemaining)} days overdue)</span>}
                        {isDueSoon && !isOverdue && <span className="text-orange-600 dark:text-orange-400">({daysRemaining} days left)</span>}
                      </span>
                      <span className="flex items-center gap-1">
                        <i className="ri-folder-line"></i>
                        {capa.capaType}
                      </span>
                      {capa.linkedNCR && (
                        <button
                          onClick={() => router.push(`/ncr-management?ncr=${capa.linkedNCR}`)}
                          className="text-blue-600 hover:text-blue-900 dark:text-blue-400 flex items-center gap-1"
                        >
                          <i className="ri-link"></i>
                          Linked NCR
                        </button>
                      )}
                    </div>
                    <div className="mb-3">
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Progress</span>
                        <span className="text-sm text-gray-600 dark:text-gray-400">{capa.progress || 0}%</span>
                      </div>
                      <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                        <div
                          className="bg-blue-600 h-2 rounded-full transition-all"
                          style={{ width: `${capa.progress || 0}%` }}
                        ></div>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <div>
                        <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Root Cause: </span>
                        <span className="text-sm text-gray-600 dark:text-gray-400">{capa.rootCause || 'Not specified'}</span>
                      </div>
                      <div>
                        <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Action Plan: </span>
                        <span className="text-sm text-gray-600 dark:text-gray-400 line-clamp-2">{capa.actionPlan || 'Not specified'}</span>
                      </div>
                    </div>
                  </div>
                  <button
                    onClick={() => {
                      setSelectedCAPA(capa)
                      setShowEditModal(true)
                    }}
                    className="ml-4 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors flex items-center gap-2"
                  >
                    <i className="ri-edit-line"></i>
                    Update
                  </button>
                </div>
              </motion.div>
            )
          })}
        </div>
      )}

      {/* Edit CAPA Modal */}
      {showEditModal && selectedCAPA && (
        <EditCAPAModal
          capa={selectedCAPA}
          onClose={() => {
            setShowEditModal(false)
            setSelectedCAPA(null)
          }}
          onSave={handleUpdateCAPA}
          previousCAPAs={myCAPAs}
          useSmartDetection={true}
        />
      )}
    </PageTemplate>
  )
}

/**
 * My Tasks - Enhanced
 * Personal task dashboard showing all assigned items across ISO IMS
 * Fully functional with filtering and cross-module navigation
