                  />
                  <Line type="monotone" dataKey="efficiency" stroke="#10b981" strokeWidth={3} name="Efficiency %" />
                  <Line type="monotone" dataKey="instances" stroke="#3b82f6" strokeWidth={2} name="Instances" />
                  <Legend />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {/* Predictions View */}
        {viewMode === 'predictions' && (
          <div className="space-y-6">
            <div className="bg-gradient-to-r from-purple-500/10 to-blue-600/10 border border-purple-500/30 rounded-2xl p-6">
              <div className="flex items-center gap-3 mb-4">
                <i className="ri-ai-line text-purple-400 text-2xl"></i>
                <div>
                  <h3 className="text-lg font-semibold text-white">AI-Powered Predictions</h3>
                  <p className="text-sm text-[#9ca3af]">Machine learning predictions based on historical data</p>
                </div>
              </div>
              <div className="grid md:grid-cols-3 gap-4">
                {[
                  { title: 'SLA Breach Risk', value: '12%', trend: 'down', description: 'Predicted risk of SLA breaches in next 7 days' },
                  { title: 'Bottleneck Probability', value: '28%', trend: 'up', description: 'Likelihood of bottlenecks in PICKING stage' },
                  { title: 'Efficiency Forecast', value: '94%', trend: 'up', description: 'Predicted efficiency for next week' },
                ].map((prediction, idx) => (
                  <div key={idx} className="bg-white/5 rounded-lg p-4 border border-white/10">
                    <div className="text-sm text-[#9ca3af] mb-1">{prediction.title}</div>
                    <div className="flex items-center gap-2 mb-2">
                      <div className="text-2xl font-bold text-white">{prediction.value}</div>
                      <i className={`ri-arrow-${prediction.trend === 'up' ? 'up' : 'down'}-line text-${prediction.trend === 'up' ? 'green' : 'red'}-400`}></i>
                    </div>
                    <div className="text-xs text-[#9ca3af]">{prediction.description}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </ErrorBoundary>
  )
}

/**
 * Advanced Process Mining Dashboard
 * Deep process analysis, variant detection, and performance optimization
 */

'use client'

import { useState, useEffect, useMemo } from 'react'
import { motion } from 'framer-motion'
import { processMiningService, processAnalyticsService } from '@/lib/services/process-lifecycle'
import ErrorBoundary from '@/components/ErrorBoundary'
import {
  BarChart, Bar, LineChart, Line, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid,
  Tooltip as RechartsTooltip, Legend, ResponsiveContainer, ComposedChart, Area, AreaChart,
  Sankey, Treemap
} from 'recharts'

export default function ProcessMiningPage() {
  const [loading, setLoading] = useState(true)
  const [selectedProcessType, setSelectedProcessType] = useState<string>('SALES_ORDER')
  const [variants, setVariants] = useState<any[]>([])
  const [metrics, setMetrics] = useState<any>(null)
  const [deviations, setDeviations] = useState<any[]>([])
  const [viewMode, setViewMode] = useState<'overview' | 'variants' | 'deviations' | 'performance'>('overview')
  const [realTimeEnabled, setRealTimeEnabled] = useState(true)

  useEffect(() => {
    loadData()
    if (realTimeEnabled) {
      const interval = setInterval(loadData, 10000)
      return () => clearInterval(interval)
    }
  }, [selectedProcessType, realTimeEnabled])

  const loadData = async () => {
    try {
      setLoading(true)
      const [variantData, metricsData] = await Promise.all([
        processMiningService.analyzeVariants(selectedProcessType),
        processMiningService.getPerformanceMetrics(selectedProcessType),
      ])
      setVariants(variantData)
      setMetrics(metricsData)
      
      // Get deviations from all cases
      const allCases = await processMiningService.getAllCases(selectedProcessType)
      const allDeviations = allCases.flatMap(c => c.deviations || [])
      setDeviations(allDeviations)
    } catch (error) {
      console.error('Error loading process mining data:', error)
    } finally {
      setLoading(false)
    }
  }

  const variantChartData = useMemo(() => {
    return variants.slice(0, 10).map(v => ({
      name: v.variantId.substring(0, 20),
      frequency: v.frequency,
      avgDuration: Math.floor(v.averageDuration / 3600),
      efficiency: v.efficiency,
    }))
  }, [variants])

  const deviationByType = useMemo(() => {
    const counts: Record<string, number> = {}
    deviations.forEach(d => {
      counts[d.type] = (counts[d.type] || 0) + 1
    })
    return Object.entries(counts).map(([type, count]) => ({ type, count }))
  }, [deviations])

  if (loading && !metrics) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-yellow-500 mx-auto mb-4"></div>
          <div className="text-[#9ca3af]">Loading Process Mining Analysis...</div>
        </div>
      </div>
    )
  }

  return (
    <ErrorBoundary fallback={<div className="text-red-400 p-4">Error loading Process Mining</div>}>
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-3xl font-bold text-white mb-2 flex items-center gap-3">
                <i className="ri-bar-chart-box-line text-yellow-400"></i>
                Process Mining
              </h1>
              <p className="text-[#9ca3af]">Deep process analysis, variant detection, and optimization insights</p>
            </div>
            <div className="flex items-center gap-3">
              <select
                value={selectedProcessType}
                onChange={(e) => setSelectedProcessType(e.target.value)}
                className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-yellow-500/50"
              >
                <option value="SALES_ORDER">Sales Orders</option>
                <option value="PURCHASE_ORDER">Purchase Orders</option>
                <option value="ASN">ASNs</option>
                <option value="NCR">NCRs</option>
              </select>
              <button
                onClick={() => setRealTimeEnabled(!realTimeEnabled)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  realTimeEnabled
                    ? 'bg-green-500/20 text-green-400 border border-green-500/30'
                    : 'bg-white/5 text-[#9ca3af] border border-white/10'
                }`}
              >
                <i className={`ri-${realTimeEnabled ? 'pause' : 'play'}-line mr-2`}></i>
                {realTimeEnabled ? 'Live' : 'Paused'}
              </button>
            </div>
          </div>

          {/* View Mode Tabs */}
          <div className="flex items-center gap-2 bg-white/5 border border-white/10 rounded-lg p-1">
            {(['overview', 'variants', 'deviations', 'performance'] as const).map((mode) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`flex-1 px-4 py-2 rounded text-sm font-medium transition-colors ${
                  viewMode === mode
                    ? 'bg-yellow-500 text-white'
                    : 'text-[#9ca3af] hover:text-white'
                }`}
              >
                <i className={`ri-${mode === 'overview' ? 'dashboard-line' : mode === 'variants' ? 'git-branch-line' : mode === 'deviations' ? 'alert-line' : 'speed-line'} mr-2`}></i>
                {mode.charAt(0).toUpperCase() + mode.slice(1)}
              </button>
            ))}
          </div>
        </div>

        {/* Metrics Cards */}
        {viewMode === 'overview' && (
          <div className="grid md:grid-cols-4 gap-4 mb-6">
            {[
              { label: 'Total Cases', value: metrics?.totalCases || 0, icon: 'ri-file-list-line', color: 'blue' },
              { label: 'Variants', value: variants.length, icon: 'ri-git-branch-line', color: 'purple' },
              { label: 'Deviations', value: deviations.length, icon: 'ri-alert-line', color: 'red' },
              { label: 'Avg Efficiency', value: `${(metrics?.averageEfficiency || 0).toFixed(1)}%`, icon: 'ri-speed-line', color: 'green' },
            ].map((metric, idx) => (
              <motion.div
                key={metric.label}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.1 }}
                className={`bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6 hover:border-${metric.color}-500/30 transition-all`}
              >
                <div className="flex items-center justify-between mb-2">
                  <i className={`ri-${metric.icon} text-${metric.color}-400 text-xl`}></i>
                  {realTimeEnabled && (
                    <div className={`w-2 h-2 rounded-full bg-${metric.color}-400 animate-pulse`}></div>
                  )}
                </div>
                <div className="text-2xl font-bold text-white mb-1">{metric.value}</div>
                <div className="text-xs text-[#9ca3af]">{metric.label}</div>
              </motion.div>
            ))}
          </div>
        )}

        {/* Variants View */}
        {viewMode === 'variants' && (
          <div className="space-y-6">
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6">
              <h3 className="text-lg font-semibold text-white mb-4">Process Variants</h3>
              <ResponsiveContainer width="100%" height={400}>
                <ComposedChart data={variantChartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                  <XAxis dataKey="name" stroke="#9ca3af" fontSize={12} angle={-45} textAnchor="end" height={80} />
                  <YAxis yAxisId="left" stroke="#9ca3af" fontSize={12} />
                  <YAxis yAxisId="right" orientation="right" stroke="#9ca3af" fontSize={12} />
                  <RechartsTooltip
                    contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                    labelStyle={{ color: '#fff' }}
                  />
                  <Bar yAxisId="left" dataKey="frequency" fill="#3b82f6" name="Frequency" />
                  <Line yAxisId="right" type="monotone" dataKey="efficiency" stroke="#f59e0b" strokeWidth={2} name="Efficiency %" />
                  <Legend />
                </ComposedChart>
              </ResponsiveContainer>
            </div>

            <div className="grid md:grid-cols-2 gap-6">
              {variants.slice(0, 6).map((variant, idx) => (
                <motion.div
                  key={variant.variantId}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: idx * 0.1 }}
                  className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6"
                >
                  <div className="flex items-center justify-between mb-4">
                    <h4 className="text-sm font-semibold text-white">Variant {idx + 1}</h4>
                    <span className="px-2 py-1 bg-purple-500/20 text-purple-400 rounded text-xs font-medium">
                      {variant.frequency} cases
                    </span>
                  </div>
                  <div className="space-y-2 mb-4">
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-[#9ca3af]">Frequency:</span>
                      <span className="text-white font-medium">{variant.frequency}</span>
                    </div>
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-[#9ca3af]">Avg Duration:</span>
                      <span className="text-white font-medium">{Math.floor(variant.averageDuration / 3600)}h</span>
                    </div>
                    <div className="flex items-center justify-between text-xs">
                      <span className="text-[#9ca3af]">Efficiency:</span>
                      <span className="text-white font-medium">{variant.efficiency.toFixed(1)}%</span>
                    </div>
                  </div>
                  <div className="text-xs text-[#9ca3af]">
                    <div className="font-medium mb-1">Event Sequence:</div>
                    <div className="flex flex-wrap gap-1">
                      {variant.events.slice(0, 5).map((event: string, i: number) => (
                        <span key={i} className="px-2 py-1 bg-white/5 rounded text-[#9ca3af]">
                          {event}
                        </span>
                      ))}
                      {variant.events.length > 5 && (
                        <span className="px-2 py-1 bg-white/5 rounded text-[#9ca3af]">
                          +{variant.events.length - 5} more
                        </span>
                      )}
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
        )}

        {/* Deviations View */}
        {viewMode === 'deviations' && (
          <div className="space-y-6">
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6">
              <h3 className="text-lg font-semibold text-white mb-4">Deviation Analysis</h3>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={deviationByType}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                  <XAxis dataKey="type" stroke="#9ca3af" fontSize={12} />
                  <YAxis stroke="#9ca3af" fontSize={12} />
                  <RechartsTooltip
                    contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                  />
                  <Bar dataKey="count" fill="#ef4444" />
                </BarChart>
              </ResponsiveContainer>
            </div>

            <div className="space-y-3">
              {deviations.slice(0, 10).map((deviation, idx) => (
                <motion.div
                  key={deviation.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.05 }}
                  className={`bg-white/5 backdrop-blur-xl border rounded-xl p-4 ${
                    deviation.severity === 'CRITICAL' ? 'border-red-500/30 bg-red-500/10' :
                    deviation.severity === 'HIGH' ? 'border-orange-500/30 bg-orange-500/10' :
                    'border-yellow-500/30 bg-yellow-500/10'
                  }`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <span className={`px-2 py-1 rounded text-xs font-medium ${
                          deviation.severity === 'CRITICAL' ? 'bg-red-500/20 text-red-400' :
                          deviation.severity === 'HIGH' ? 'bg-orange-500/20 text-orange-400' :
                          'bg-yellow-500/20 text-yellow-400'
                        }`}>
                          {deviation.severity}
                        </span>
                        <span className="px-2 py-1 bg-white/5 rounded text-xs font-medium text-white">
                          {deviation.type}
                        </span>
                      </div>
                      <p className="text-sm text-white/80">{deviation.description}</p>
                      {deviation.impact && (
                        <div className="mt-2 text-xs text-[#9ca3af]">
                          Impact: {Math.floor(deviation.impact)} hours
                        </div>
                      )}
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
        )}

        {/* Performance View */}
        {viewMode === 'performance' && metrics && (
          <div className="grid md:grid-cols-2 gap-6">
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6">
              <h3 className="text-lg font-semibold text-white mb-4">Performance Metrics</h3>
              <div className="space-y-4">
                <div>
                  <div className="flex items-center justify-between text-sm mb-2">
                    <span className="text-[#9ca3af]">Average Duration</span>
                    <span className="text-white font-semibold">{Math.floor(metrics.averageDuration / 3600)}h</span>
                  </div>
                  <div className="w-full bg-white/10 rounded-full h-2">
                    <div
                      className="bg-blue-500 h-2 rounded-full"
                      style={{ width: `${Math.min(100, (metrics.averageDuration / 7200) * 100)}%` }}
                    />
                  </div>
                </div>
                <div>
                  <div className="flex items-center justify-between text-sm mb-2">
                    <span className="text-[#9ca3af]">Average Efficiency</span>
                    <span className="text-white font-semibold">{metrics.averageEfficiency.toFixed(1)}%</span>
                  </div>
                  <div className="w-full bg-white/10 rounded-full h-2">
                    <div
                      className="bg-green-500 h-2 rounded-full"
                      style={{ width: `${metrics.averageEfficiency}%` }}
                    />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4 pt-4 border-t border-white/10">
                  <div>
                    <div className="text-xs text-[#9ca3af] mb-1">Total Deviations</div>
                    <div className="text-xl font-bold text-white">{metrics.totalDeviations}</div>
                  </div>
                  <div>
                    <div className="text-xs text-[#9ca3af] mb-1">Critical</div>
                    <div className="text-xl font-bold text-red-400">{metrics.criticalDeviations}</div>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6">
              <h3 className="text-lg font-semibold text-white mb-4">Optimization Recommendations</h3>
              <div className="space-y-3">
                {[
                  { title: 'Reduce Variant Complexity', description: 'Standardize process flow to reduce variants', impact: 'High' },
                  { title: 'Address Critical Deviations', description: `${metrics.criticalDeviations} critical deviations need attention`, impact: 'Critical' },
                  { title: 'Improve Average Efficiency', description: `Current: ${metrics.averageEfficiency.toFixed(1)}%, Target: 95%`, impact: 'Medium' },
                ].map((rec, idx) => (
                  <div key={idx} className="bg-white/5 rounded-lg p-3 border border-white/10">
                    <div className="flex items-start justify-between mb-1">
                      <div className="text-sm font-semibold text-white">{rec.title}</div>
                      <span className={`px-2 py-0.5 rounded text-xs font-medium ${
                        rec.impact === 'Critical' ? 'bg-red-500/20 text-red-400' :
                        rec.impact === 'High' ? 'bg-orange-500/20 text-orange-400' :
                        'bg-yellow-500/20 text-yellow-400'
                      }`}>
                        {rec.impact}
                      </span>
                    </div>
                    <p className="text-xs text-[#9ca3af]">{rec.description}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </ErrorBoundary>
  )
}

/**
 * Unified Journey Dashboard
 * Revolutionary dual-dimensional view: Physical Journey + Business Journey
 * Shows both dimensions synchronized in real-time
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { dualJourneyOrchestrator } from '@/lib/services/dual-journey/dualJourneyOrchestrator'
import type { UnifiedJourney } from '@/lib/services/dual-journey/dualJourneyOrchestrator'
import type { JourneyAnalysis } from '@/types/journey-analysis'
import ErrorBoundary from '@/components/ErrorBoundary'
import dynamic from 'next/dynamic'

// Dynamic import for Journey Analysis components (don't modify them)
const InteractiveRouteMap = dynamic(
  () => import('@/components/proposals/InteractiveRouteMap'),
  { ssr: false }
)

const JourneyIntelligencePanel = dynamic(
  () => import('@/components/trade-compliance/JourneyIntelligencePanel'),
  { ssr: false }
)

export default function UnifiedJourneyPage() {
  const [entityId, setEntityId] = useState('ASN-2024-001')
  const [entityType, setEntityType] = useState<'ASN' | 'SHIPMENT' | 'PURCHASE_ORDER' | 'SALES_ORDER'>('ASN')
  const [unifiedJourney, setUnifiedJourney] = useState<UnifiedJourney | null>(null)
  const [loading, setLoading] = useState(false)
  const [viewMode, setViewMode] = useState<'unified' | 'physical' | 'business' | 'correlation'>('unified')

  useEffect(() => {
    loadUnifiedJourney()
  }, [entityId, entityType])

  const loadUnifiedJourney = async () => {
    setLoading(true)
    try {
      // In production, would fetch physical journey from Journey Analysis service
      // For now, using mock data structure
      const mockPhysicalJourney: JourneyAnalysis | null = null // Would be fetched
      
      const unified = await dualJourneyOrchestrator.getUnifiedJourney(
        entityId,
        entityType,
        mockPhysicalJourney,
        undefined // Business journey will be fetched automatically
      )
      
      setUnifiedJourney(unified)
    } catch (error) {
      console.error('Error loading unified journey:', error)
    } finally {
      setLoading(false)
    }
  }

  if (loading && !unifiedJourney) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-purple-500 mx-auto mb-4"></div>
          <div className="text-[#9ca3af]">Loading Unified Journey...</div>
        </div>
      </div>
    )
  }

  if (!unifiedJourney) {
    return (
      <ErrorBoundary fallback={<div className="text-red-400 p-4">Error loading Unified Journey</div>}>
        <div className="container mx-auto px-4 py-8">
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-12 text-center">
            <i className="ri-information-line text-4xl text-purple-400 mb-4"></i>
            <h3 className="text-xl font-semibold text-white mb-2">No Journey Data</h3>
            <p className="text-[#9ca3af] mb-6">
              Enter an entity ID to view its unified journey (physical + business dimensions)
            </p>
            <div className="flex gap-4 justify-center">
              <input
                type="text"
                value={entityId}
                onChange={(e) => setEntityId(e.target.value)}
                placeholder="Entity ID (e.g., ASN-2024-001)"
                className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-[#9ca3af] focus:outline-none focus:border-purple-500/50"
              />
              <select
                value={entityType}
                onChange={(e) => setEntityType(e.target.value as any)}
                className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-purple-500/50"
              >
                <option value="ASN">ASN</option>
                <option value="SHIPMENT">Shipment</option>
                <option value="PURCHASE_ORDER">Purchase Order</option>
                <option value="SALES_ORDER">Sales Order</option>
              </select>
              <button
                onClick={loadUnifiedJourney}
                className="px-6 py-2 bg-purple-500 hover:bg-purple-600 text-white rounded-lg font-medium transition-colors"
              >
                Load Journey
              </button>
            </div>
          </div>
        </div>
      </ErrorBoundary>
    )
  }

  return (
    <ErrorBoundary fallback={<div className="text-red-400 p-4">Error loading Unified Journey</div>}>
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="mb-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-4xl font-bold text-white mb-2 flex items-center gap-3">
                <i className="ri-global-line text-purple-400"></i>
                Unified Journey Intelligence
              </h1>
              <p className="text-[#9ca3af] text-lg">
                Dual-dimensional tracking: Physical Journey (WHERE) + Business Journey (WHAT)
              </p>
            </div>
            <div className="flex items-center gap-3">
              <input
                type="text"
                value={entityId}
                onChange={(e) => setEntityId(e.target.value)}
                placeholder="Entity ID"
                className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-[#9ca3af] focus:outline-none focus:border-purple-500/50"
              />
              <select
                value={entityType}
                onChange={(e) => setEntityType(e.target.value as any)}
                className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-purple-500/50"
              >
                <option value="ASN">ASN</option>
                <option value="SHIPMENT">Shipment</option>
                <option value="PURCHASE_ORDER">Purchase Order</option>
                <option value="SALES_ORDER">Sales Order</option>
              </select>
              <button
                onClick={loadUnifiedJourney}
                className="px-4 py-2 bg-purple-500 hover:bg-purple-600 text-white rounded-lg text-sm font-medium transition-colors"
              >
                <i className="ri-refresh-line mr-2"></i>
                Refresh
              </button>
            </div>
          </div>

          {/* View Mode Tabs */}
          <div className="flex items-center gap-2 bg-white/5 border border-white/10 rounded-lg p-1">
            {(['unified', 'physical', 'business', 'correlation'] as const).map((mode) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`flex-1 px-4 py-2 rounded text-sm font-medium transition-colors ${
                  viewMode === mode
                    ? 'bg-purple-500 text-white'
                    : 'text-[#9ca3af] hover:text-white'
                }`}
              >
                <i className={`ri-${mode === 'unified' ? 'dashboard-line' : mode === 'physical' ? 'map-pin-line' : mode === 'business' ? 'flow-chart-line' : 'git-branch-line'} mr-2`}></i>
                {mode.charAt(0).toUpperCase() + mode.slice(1)}
              </button>
            ))}
          </div>
        </div>

        {/* Unified Analytics Cards */}
        <div className="grid md:grid-cols-4 gap-4 mb-6">
          {[
            { 
              label: 'Total Journey Time', 
              value: `${unifiedJourney.unifiedIntelligence.analytics.totalJourneyTime.toFixed(1)}h`,
              icon: 'ri-time-line',
              color: 'blue',
            },
            { 
              label: 'Physical %', 
              value: `${unifiedJourney.unifiedIntelligence.analytics.physicalPercentage.toFixed(0)}%`,
              icon: 'ri-map-pin-line',
              color: 'green',
            },
            { 
              label: 'Business %', 
              value: `${unifiedJourney.unifiedIntelligence.analytics.businessPercentage.toFixed(0)}%`,
              icon: 'ri-flow-chart-line',
              color: 'purple',
            },
            { 
              label: 'Efficiency', 
              value: `${unifiedJourney.unifiedIntelligence.analytics.efficiency.toFixed(0)}%`,
              icon: 'ri-speed-line',
              color: 'yellow',
            },
            { 
              label: 'Bottlenecks', 
              value: unifiedJourney.unifiedIntelligence.analytics.bottleneckCount,
              icon: 'ri-alert-line',
              color: 'red',
            },
            { 
              label: 'Critical', 
              value: unifiedJourney.unifiedIntelligence.analytics.criticalBottlenecks,
              icon: 'ri-error-warning-line',
              color: 'orange',
            },
          ].map((stat, idx) => (
            <motion.div
              key={stat.label}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.1 }}
              className={`bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6 hover:border-${stat.color}-500/30 transition-all`}
            >
              <div className="flex items-center justify-between mb-2">
                <i className={`ri-${stat.icon} text-${stat.color}-400 text-xl`}></i>
              </div>
              <div className="text-2xl font-bold text-white mb-1">{stat.value}</div>
              <div className="text-xs text-[#9ca3af]">{stat.label}</div>
            </motion.div>
          ))}
        </div>

        {/* Unified View */}
        {viewMode === 'unified' && (
          <div className="grid md:grid-cols-2 gap-6 mb-6">
            {/* Physical Journey Panel */}
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
              <h2 className="text-xl font-semibold text-white mb-4 flex items-center gap-2">
                <i className="ri-map-pin-line text-green-400"></i>
                Physical Journey (WHERE)
              </h2>
              {unifiedJourney.physicalJourney.touchpoints.length > 0 ? (
                <div className="space-y-3">
                  {unifiedJourney.physicalJourney.touchpoints.map((tp, idx) => (
                    <div
                      key={idx}
                      className="bg-white/5 rounded-lg p-4 border border-white/10"
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-white font-medium">{tp.name}</span>
                        <span className={`px-2 py-1 rounded text-xs ${
                          tp.bottleneckRisk === 'CRITICAL' ? 'bg-red-500/20 text-red-400' :
                          tp.bottleneckRisk === 'HIGH' ? 'bg-orange-500/20 text-orange-400' :
                          tp.bottleneckRisk === 'MEDIUM' ? 'bg-yellow-500/20 text-yellow-400' :
                          'bg-green-500/20 text-green-400'
                        }`}>
                          {tp.bottleneckRisk}
                        </span>
                      </div>
                      <div className="text-sm text-[#9ca3af]">
                        {tp.avgHours}h avg • {tp.category}
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-[#9ca3af]">
                  <i className="ri-information-line text-3xl mb-2"></i>
                  <p>No physical journey data available</p>
                  <p className="text-xs mt-2">Physical journey data would come from Journey Analysis</p>
                </div>
              )}
            </div>

            {/* Business Journey Panel */}
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
              <h2 className="text-xl font-semibold text-white mb-4 flex items-center gap-2">
                <i className="ri-flow-chart-line text-purple-400"></i>
                Business Journey (WHAT)
              </h2>
              {unifiedJourney.businessJourney.stages.length > 0 ? (
                <div className="space-y-3">
                  {unifiedJourney.businessJourney.stages.map((stage, idx) => (
                    <div
                      key={idx}
                      className="bg-white/5 rounded-lg p-4 border border-white/10"
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-white font-medium">{stage.stageName}</span>
                        <span className={`px-2 py-1 rounded text-xs ${
                          stage.status === 'completed' ? 'bg-green-500/20 text-green-400' :
                          stage.status === 'active' ? 'bg-blue-500/20 text-blue-400' :
                          'bg-gray-500/20 text-gray-400'
                        }`}>
                          {stage.status}
                        </span>
                      </div>
                      {stage.startedAt && (
                        <div className="text-sm text-[#9ca3af]">
                          Started: {new Date(stage.startedAt).toLocaleString()}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-[#9ca3af]">
                  <i className="ri-information-line text-3xl mb-2"></i>
                  <p>No business journey data available</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Correlation View */}
        {viewMode === 'correlation' && (
          <div className="space-y-6">
            {/* Physical → Business Correlations */}
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
              <h3 className="text-lg font-semibold text-white mb-4">
                Physical → Business Correlations
              </h3>
              <div className="space-y-3">
                {unifiedJourney.unifiedIntelligence.correlation.physicalToBusiness.map((corr, idx) => (
                  <div key={idx} className="bg-white/5 rounded-lg p-4 border border-white/10">
                    <div className="flex items-center gap-3">
                      <div className="w-12 h-12 rounded-lg bg-green-500/20 flex items-center justify-center">
                        <i className="ri-map-pin-line text-green-400"></i>
                      </div>
                      <div className="flex-1">
                        <div className="text-white font-medium">{corr.touchpoint}</div>
                        <div className="text-sm text-[#9ca3af]">
                          Triggers: {corr.triggers.join(', ')}
                        </div>
                      </div>
                      <span className={`px-2 py-1 rounded text-xs ${
                        corr.impact === 'CRITICAL' ? 'bg-red-500/20 text-red-400' :
                        corr.impact === 'HIGH' ? 'bg-orange-500/20 text-orange-400' :
                        corr.impact === 'MEDIUM' ? 'bg-yellow-500/20 text-yellow-400' :
                        'bg-green-500/20 text-green-400'
                      }`}>
                        {corr.impact}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Business → Physical Correlations */}
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
              <h3 className="text-lg font-semibold text-white mb-4">
                Business → Physical Correlations
              </h3>
              <div className="space-y-3">
                {unifiedJourney.unifiedIntelligence.correlation.businessToPhysical.map((corr, idx) => (
                  <div key={idx} className="bg-white/5 rounded-lg p-4 border border-white/10">
                    <div className="flex items-center gap-3">
                      <div className="w-12 h-12 rounded-lg bg-purple-500/20 flex items-center justify-center">
                        <i className="ri-flow-chart-line text-purple-400"></i>
                      </div>
                      <div className="flex-1">
                        <div className="text-white font-medium">{corr.stage}</div>
                        <div className="text-sm text-[#9ca3af]">
                          Affects: {corr.affects.join(', ')}
                        </div>
                      </div>
                      <span className={`px-2 py-1 rounded text-xs ${
                        corr.impact === 'CRITICAL' ? 'bg-red-500/20 text-red-400' :
                        corr.impact === 'HIGH' ? 'bg-orange-500/20 text-orange-400' :
                        corr.impact === 'MEDIUM' ? 'bg-yellow-500/20 text-yellow-400' :
                        'bg-green-500/20 text-green-400'
                      }`}>
                        {corr.impact}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Cross-Impact Analysis */}
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
              <h3 className="text-lg font-semibold text-white mb-4">
                Cross-Dimensional Impact Analysis
              </h3>
              <div className="space-y-3">
                {unifiedJourney.unifiedIntelligence.correlation.crossImpact.map((impact, idx) => (
                  <div key={idx} className="bg-white/5 rounded-lg p-4 border border-white/10">
                    <div className="flex items-center gap-4">
                      <div className="flex-1">
                        <div className="text-white font-medium mb-1">{impact.physicalEvent}</div>
                        <div className="text-sm text-[#9ca3af]">→ {impact.businessEvent}</div>
                      </div>
                      <div className="text-right">
                        <div className="text-white font-semibold">
                          {(impact.correlation * 100).toFixed(0)}% correlation
                        </div>
                        <div className="text-xs text-[#9ca3af]">
                          {impact.delayPropagation.toFixed(1)}h propagation
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Predictions & Recommendations */}
        <div className="grid md:grid-cols-2 gap-6 mt-6">
          {/* Risk Factors */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
            <h3 className="text-lg font-semibold text-white mb-4">Risk Factors</h3>
            <div className="space-y-3">
              {unifiedJourney.unifiedIntelligence.predictions.riskFactors.map((risk, idx) => (
                <div key={idx} className="bg-white/5 rounded-lg p-3 border border-white/10">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-white text-sm font-medium">{risk.description}</span>
                    <span className={`px-2 py-1 rounded text-xs ${
                      risk.severity === 'CRITICAL' ? 'bg-red-500/20 text-red-400' :
                      risk.severity === 'HIGH' ? 'bg-orange-500/20 text-orange-400' :
                      risk.severity === 'MEDIUM' ? 'bg-yellow-500/20 text-yellow-400' :
                      'bg-green-500/20 text-green-400'
                    }`}>
                      {risk.severity}
                    </span>
                  </div>
                  <div className="text-xs text-[#9ca3af]">Source: {risk.source}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Optimization Opportunities */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
            <h3 className="text-lg font-semibold text-white mb-4">Optimization Opportunities</h3>
            <div className="space-y-3">
              {unifiedJourney.unifiedIntelligence.predictions.optimizationOpportunities.map((opp, idx) => (
                <div key={idx} className="bg-white/5 rounded-lg p-3 border border-white/10">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-white text-sm font-medium">{opp.title}</span>
                    <span className="text-green-400 text-sm font-semibold">
                      Save {opp.potentialSavings.toFixed(1)}h
                    </span>
                  </div>
                  <div className="text-xs text-[#9ca3af] mb-1">{opp.description}</div>
                  <div className="flex items-center gap-2">
                    <span className={`px-2 py-0.5 rounded text-xs ${
                      opp.type === 'PHYSICAL' ? 'bg-green-500/20 text-green-400' :
                      opp.type === 'BUSINESS' ? 'bg-purple-500/20 text-purple-400' :
                      'bg-blue-500/20 text-blue-400'
                    }`}>
                      {opp.type}
                    </span>
                    <span className={`px-2 py-0.5 rounded text-xs ${
                      opp.impact === 'CRITICAL' ? 'bg-red-500/20 text-red-400' :
                      opp.impact === 'HIGH' ? 'bg-orange-500/20 text-orange-400' :
                      'bg-yellow-500/20 text-yellow-400'
                    }`}>
                      {opp.impact} Impact
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </ErrorBoundary>
  )
}

/**
 * Workflow Details/View Page
 * View workflow details, executions, and analytics
 */

'use client'

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { motion } from 'framer-motion'
import Link from 'next/link'
import type { Workflow, WorkflowExecution } from '@/lib/services/process-lifecycle'
import { workflowService } from '@/lib/services/process-lifecycle'
import ErrorBoundary from '@/components/ErrorBoundary'
import ReactFlow, { Background, Controls, MiniMap, Node, Edge } from 'reactflow'
import 'reactflow/dist/style.css'

export default function WorkflowDetailsPage() {
  const params = useParams()
  const router = useRouter()
  const workflowId = params.workflowId as string

  const [workflow, setWorkflow] = useState<Workflow | null>(null)
  const [executions, setExecutions] = useState<WorkflowExecution[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<'details' | 'executions' | 'analytics'>('details')

  useEffect(() => {
    if (workflowId) {
      loadWorkflowData()
    }
  }, [workflowId])

  const loadWorkflowData = async () => {
    try {
      setLoading(true)
      setError(null)

      const [workflowData, executionsData] = await Promise.all([
        workflowService.getWorkflow(workflowId).catch(() => null),
        workflowService.getExecutionsForWorkflow(workflowId).catch(() => []),
      ])

      if (!workflowData) {
        setError('Workflow not found')
        return
      }

      setWorkflow(workflowData)
      setExecutions(executionsData)
    } catch (err) {
      console.error('Error loading workflow:', err)
      setError('Failed to load workflow')
    } finally {
      setLoading(false)
    }
  }

  const convertWorkflowToReactFlow = (workflow: Workflow) => {
    const nodes: Node[] = workflow.steps.map((step, index) => ({
      id: step.id,
      type: step.type,
      position: step.position || { x: index * 200, y: 100 },
      data: {
        label: step.name,
        config: step.config,
      },
    }))

    const edges: Edge[] = []
    workflow.steps.forEach((step) => {
      if (step.connections && step.connections.length > 0) {
        step.connections.forEach((targetId) => {
          edges.push({
            id: `${step.id}-${targetId}`,
            source: step.id,
            target: targetId,
          })
        })
      }
    })

    return { nodes, edges }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-[#111827]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-purple-500 mx-auto mb-4"></div>
          <div className="text-[#9ca3af]">Loading Workflow...</div>
        </div>
      </div>
    )
  }

  if (error || !workflow) {
    return (
      <div className="min-h-screen bg-[#111827] p-8">
        <div className="max-w-4xl mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-red-500/10 border border-red-500/30 rounded-xl p-6 text-center"
          >
            <i className="ri-error-warning-line text-4xl text-red-400 mb-4"></i>
            <h2 className="text-xl font-semibold text-white mb-2">Workflow Not Found</h2>
            <p className="text-[#9ca3af] mb-4">{error || 'The workflow you are looking for does not exist.'}</p>
            <Link
              href="/process-lifecycle/workflows"
              className="inline-block px-4 py-2 bg-purple-500 hover:bg-purple-600 text-white rounded-lg transition-colors"
            >
              Back to Workflows
            </Link>
          </motion.div>
        </div>
      </div>
    )
  }

  const { nodes, edges } = convertWorkflowToReactFlow(workflow)
  const activeExecutions = executions.filter((e) => e.status === 'running')
  const completedExecutions = executions.filter((e) => e.status === 'completed')
  const failedExecutions = executions.filter((e) => e.status === 'failed')

  return (
    <ErrorBoundary>
      <div className="min-h-screen bg-[#111827] p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto">
          {/* Header */}
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            className="mb-6"
          >
            <div className="flex items-center justify-between mb-4">
              <div>
                <Link
                  href="/process-lifecycle/workflows"
                  className="text-[#9ca3af] hover:text-white mb-2 inline-flex items-center gap-2"
                >
                  <i className="ri-arrow-left-line"></i>
                  Back to Workflows
                </Link>
                <h1 className="text-3xl font-bold text-white">{workflow.name}</h1>
                {workflow.description && (
                  <p className="text-[#9ca3af] mt-2">{workflow.description}</p>
                )}
              </div>
              <div className="flex gap-3">
                <Link
                  href={`/process-lifecycle/workflows/builder?id=${workflow.id}`}
                  className="px-4 py-2 bg-purple-500 hover:bg-purple-600 text-white rounded-lg font-medium transition-colors flex items-center gap-2"
                >
                  <i className="ri-edit-line"></i>
                  Edit
                </Link>
                <button
                  onClick={() => router.push('/process-lifecycle/workflows')}
                  className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white border border-white/10 rounded-lg font-medium transition-colors"
                >
                  Close
                </button>
              </div>
            </div>

            {/* Status Badge */}
            <div className="flex items-center gap-4 mt-4">
              <span
                className={`px-3 py-1 rounded-full text-sm font-medium ${
                  workflow.status === 'active'
                    ? 'bg-green-500/20 text-green-400 border border-green-500/30'
                    : workflow.status === 'draft'
                    ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/30'
                    : 'bg-gray-500/20 text-gray-400 border border-gray-500/30'
                }`}
              >
                {workflow.status.toUpperCase()}
              </span>
              <span className="text-[#9ca3af] text-sm">
                Created: {new Date(workflow.createdAt).toLocaleDateString()}
              </span>
              <span className="text-[#9ca3af] text-sm">
                Updated: {new Date(workflow.updatedAt).toLocaleDateString()}
              </span>
            </div>
          </motion.div>

          {/* Tabs */}
          <div className="flex gap-2 mb-6 border-b border-white/10">
            {(['details', 'executions', 'analytics'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-4 py-2 font-medium transition-colors border-b-2 ${
                  activeTab === tab
                    ? 'border-purple-500 text-purple-400'
                    : 'border-transparent text-[#9ca3af] hover:text-white'
                }`}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)}
              </button>
            ))}
          </div>

          {/* Tab Content */}
          {activeTab === 'details' && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="space-y-6"
            >
              {/* Workflow Visualization */}
              <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
                <h2 className="text-xl font-semibold text-white mb-4">Workflow Diagram</h2>
                <div className="h-[600px] bg-[#0a0a0a] rounded-lg">
                  <ReactFlow nodes={nodes} edges={edges} fitView>
                    <Background />
                    <Controls />
                    <MiniMap />
                  </ReactFlow>
                </div>
              </div>

              {/* Workflow Steps */}
              <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
                <h2 className="text-xl font-semibold text-white mb-4">Steps ({workflow.steps.length})</h2>
                <div className="space-y-3">
                  {workflow.steps.map((step, index) => (
                    <div
                      key={step.id}
                      className="bg-white/5 border border-white/10 rounded-lg p-4"
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-purple-500/20 border border-purple-500/30 flex items-center justify-center text-purple-400 font-medium">
                            {index + 1}
                          </div>
                          <div>
                            <h3 className="text-white font-medium">{step.name}</h3>
                            <p className="text-[#9ca3af] text-sm capitalize">{step.type}</p>
                          </div>
                        </div>
                        {step.connections && step.connections.length > 0 && (
                          <div className="text-[#9ca3af] text-sm">
                            → {step.connections.length} connection{step.connections.length > 1 ? 's' : ''}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </motion.div>
          )}

          {activeTab === 'executions' && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="space-y-6"
            >
              {/* Execution Stats */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
                  <div className="text-[#9ca3af] text-sm mb-2">Active Executions</div>
                  <div className="text-3xl font-bold text-cyan-400">{activeExecutions.length}</div>
                </div>
                <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
                  <div className="text-[#9ca3af] text-sm mb-2">Completed</div>
                  <div className="text-3xl font-bold text-green-400">{completedExecutions.length}</div>
                </div>
                <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
                  <div className="text-[#9ca3af] text-sm mb-2">Failed</div>
                  <div className="text-3xl font-bold text-red-400">{failedExecutions.length}</div>
                </div>
              </div>

              {/* Executions List */}
              <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
                <h2 className="text-xl font-semibold text-white mb-4">Recent Executions</h2>
                {executions.length === 0 ? (
                  <div className="text-center py-12 text-[#9ca3af]">
                    <i className="ri-inbox-line text-4xl mb-4"></i>
                    <p>No executions yet</p>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {executions.slice(0, 10).map((execution) => (
                      <div
                        key={execution.id}
                        className="bg-white/5 border border-white/10 rounded-lg p-4"
                      >
                        <div className="flex items-center justify-between">
                          <div>
                            <div className="text-white font-medium">Execution {execution.id.slice(0, 8)}</div>
                            <div className="text-[#9ca3af] text-sm">
                              Record: {execution.recordId} • Started: {new Date(execution.startedAt).toLocaleString()}
                            </div>
                          </div>
                          <span
                            className={`px-3 py-1 rounded-full text-sm font-medium ${
                              execution.status === 'completed'
                                ? 'bg-green-500/20 text-green-400 border border-green-500/30'
                                : execution.status === 'running'
                                ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                                : 'bg-red-500/20 text-red-400 border border-red-500/30'
                            }`}
                          >
                            {execution.status.toUpperCase()}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </motion.div>
          )}

          {activeTab === 'analytics' && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6"
            >
              <h2 className="text-xl font-semibold text-white mb-4">Workflow Analytics</h2>
              <div className="text-center py-12 text-[#9ca3af]">
                <i className="ri-bar-chart-line text-4xl mb-4"></i>
                <p>Analytics coming soon</p>
              </div>
            </motion.div>
          )}
        </div>
      </div>
    </ErrorBoundary>
  )
}

/**
 * Workflow Builder Page
 * Visual drag-and-drop workflow creation
 */

'use client'

import { useState, useEffect } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import WorkflowBuilder from '@/components/process-lifecycle/workflow/WorkflowBuilder'
import type { Workflow } from '@/lib/services/process-lifecycle'
import { workflowService } from '@/lib/services/process-lifecycle'
import ErrorBoundary from '@/components/ErrorBoundary'

export default function WorkflowBuilderPage() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const workflowId = searchParams.get('id')
  const [initialWorkflow, setInitialWorkflow] = useState<Partial<Workflow> | undefined>(undefined)
  const [loading, setLoading] = useState(!!workflowId)

  useEffect(() => {
    if (workflowId) {
      loadWorkflow()
    }
  }, [workflowId])

  const loadWorkflow = async () => {
    try {
      setLoading(true)
      const workflow = await workflowService.getWorkflow(workflowId!)
      if (workflow) {
        setInitialWorkflow(workflow)
      }
    } catch (error) {
      console.error('Error loading workflow:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async (workflow: Workflow) => {
    // Redirect to workflows page after save
    router.push(`/process-lifecycle/workflows`)
  }

  const handleCancel = () => {
    router.push('/process-lifecycle/workflows')
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-purple-500 mx-auto mb-4"></div>
          <div className="text-[#9ca3af]">Loading Workflow...</div>
        </div>
      </div>
    )
  }

  return (
    <ErrorBoundary fallback={<div className="text-red-400 p-4">Error loading Workflow Builder</div>}>
      <div className="h-screen flex flex-col">
        <WorkflowBuilder
          workflowId={workflowId || undefined}
          initialWorkflow={initialWorkflow}
          onSave={handleSave}
          onCancel={handleCancel}
        />
      </div>
    </ErrorBoundary>
  )
}

/**
 * Project Details Page
 * Professional project details with tabs
 */

'use client'

import { useEffect, useState } from 'react'
import { useParams } from 'next/navigation'
import { RiFolderLine, RiBarChartBoxLine, RiUserLine, RiMoneyDollarCircleLine, RiCheckboxLine } from 'react-icons/ri'
import type { UnifiedProjectData } from '@/types/project-management'

export default function ProjectDetailsPage() {
  const params = useParams()
  const projectId = params.id as string
  const [projectData, setProjectData] = useState<UnifiedProjectData | null>(null)
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'overview' | 'gantt' | 'resources' | 'budget' | 'tasks'>('overview')

  useEffect(() => {
    if (projectId) {
      fetchProjectData()
    }
  }, [projectId])

  const fetchProjectData = async () => {
    try {
      const response = await fetch(`/api/projects/${projectId}`)
      const data = await response.json()
      if (data.success) {
        setProjectData(data.data)
      }
    } catch (error) {
      console.error('Error fetching project:', error)
    } finally {
      setLoading(false)
    }
  }

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-SA', {
      style: 'currency',
      currency: 'SAR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 2,
    }).format(amount)
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-black text-white p-6">
        <div className="max-w-7xl mx-auto">
          <div className="animate-pulse text-gray-400">Loading project...</div>
        </div>
      </div>
    )
  }

  if (!projectData) {
    return (
      <div className="min-h-screen bg-black text-white p-6">
        <div className="max-w-7xl mx-auto">
          <p className="text-gray-400">Project not found</p>
        </div>
      </div>
    )
  }

  const tabs = [
    { id: 'overview', name: 'Overview', icon: RiFolderLine },
    { id: 'gantt', name: 'Gantt Chart', icon: RiBarChartBoxLine },
    { id: 'resources', name: 'Resources', icon: RiUserLine },
    { id: 'budget', name: 'Budget', icon: RiMoneyDollarCircleLine },
    { id: 'tasks', name: 'Tasks', icon: RiCheckboxLine },
  ]

  return (
    <div className="min-h-screen bg-black text-white p-6">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div>
          <h1 className="text-3xl font-bold flex items-center gap-3">
            <RiFolderLine className="text-orange-400" />
            {projectData.project.name}
          </h1>
          <p className="text-gray-400 mt-1">{projectData.project.description}</p>
        </div>

