          <ComparisonCard
            title="vs Industry Average"
            comparisons={benchmark.comparisons.vsIndustry}
          />
          <ComparisonCard
            title="vs Historical Performance"
            comparisons={benchmark.comparisons.vsHistorical}
          />
        </div>
      </div>
    </PageTemplate>
    </ProposalErrorBoundary>
  )
}

function MetricCard({ title, value, max, unit = '%', color, comparison, lowerIsBetter = false }: {
  title: string
  value: number
  max: number
  unit?: string
  color: string
  comparison: string
  lowerIsBetter?: boolean
}) {
  const percentage = lowerIsBetter ? ((max - value) / max) * 100 : (value / max) * 100
  const colorClasses = {
    blue: 'from-blue-500 to-blue-600',
    green: 'from-emerald-500 to-emerald-600',
    purple: 'from-purple-500 to-purple-600',
    amber: 'from-amber-500 to-amber-600',
  }

  const comparisonIcons: Record<string, string> = {
    'ABOVE': 'ri-arrow-up-line text-green-500',
    'AT': 'ri-check-line text-blue-500',
    'BELOW': 'ri-arrow-down-line text-red-500',
    'FASTER': 'ri-arrow-up-line text-green-500',
    'AVERAGE': 'ri-check-line text-blue-500',
    'SLOWER': 'ri-arrow-down-line text-red-500',
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700"
    >
      <div className="flex items-center justify-between mb-4">
        <h4 className="font-medium text-gray-900 dark:text-white">{title}</h4>
        <i className={comparisonIcons[comparison] || 'ri-check-line text-blue-500'} />
      </div>
      <div className="mb-4">
        <div className="flex items-baseline gap-2">
          <span className="text-3xl font-bold text-gray-900 dark:text-white">{value.toFixed(1)}</span>
          <span className="text-sm text-gray-500 dark:text-gray-400">{unit}</span>
        </div>
        <div className="mt-2 h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${percentage}%` }}
            transition={{ duration: 1, ease: 'easeOut' }}
            className={`h-full bg-gradient-to-r ${colorClasses[color as keyof typeof colorClasses]}`}
          />
        </div>
      </div>
      <p className="text-xs text-gray-500 dark:text-gray-400">
        {comparison === 'ABOVE' || comparison === 'FASTER' ? 'Above average' :
         comparison === 'BELOW' || comparison === 'SLOWER' ? 'Below average' : 'At average'}
      </p>
    </motion.div>
  )
}

function ComparisonCard({ title, comparisons }: { title: string; comparisons: any }) {
  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700">
      <h4 className="font-semibold text-gray-900 dark:text-white mb-4">{title}</h4>
      <div className="space-y-3">
        {Object.entries(comparisons).map(([key, value]: [string, any]) => (
          <div key={key} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
            <span className="text-sm text-gray-700 dark:text-gray-300 capitalize">{key.replace(/([A-Z])/g, ' $1').trim()}</span>
            <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${
              value === 'ABOVE' || value === 'FASTER'
                ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
                : value === 'BELOW' || value === 'SLOWER'
                ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
                : 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
            }`}>
              {value}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

/**
 * Enhanced Proposal Detail Page
 * World-class UI with all features integrated: Collaboration, Tracking, Rich Media, Interactive, A/B Testing, E-Signature
 */

'use client'

import { useState, useEffect } from 'react'
import { useParams, useRouter } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts'
import PageTemplate from '@/components/PageTemplate'
import ProposalErrorBoundary from '@/components/proposals/ProposalErrorBoundary'
import ProposalEvidenceLiabilityPanel from '@/components/proposals/ProposalEvidenceLiabilityPanel'
import ProposalComplianceStatus from '@/components/proposals/ProposalComplianceStatus'
import ProposalCollaborationPanel from '@/components/proposals/ProposalCollaborationPanel'
import ProposalInsightsWidget from '@/components/proposals/ProposalInsightsWidget'
import ProposalQuickActions from '@/components/proposals/ProposalQuickActions'
import ProposalExportButton from '@/components/proposals/ProposalExportButton'
import ContentBlockPicker from '@/components/proposals/ContentBlockPicker'
import ProposalEngagementHeatmap from '@/components/proposals/ProposalEngagementHeatmap'
import { useAuth } from '@/contexts/AuthContext'

export default function EnhancedProposalDetailPage() {
  const params = useParams()
  const router = useRouter()
  const { user, hasModuleAccess } = useAuth()
  const proposalId = params.id as string

  // Permission check
  const hasAccess = hasModuleAccess('proposals-rfq', 'read_only')

  const [proposal, setProposal] = useState<any>(null)
  const [tracking, setTracking] = useState<any>(null)
  const [collaboration, setCollaboration] = useState<any>(null)
  const [signature, setSignature] = useState<any>(null)
  const [richMedia, setRichMedia] = useState<any[]>([])
  const [interactive, setInteractive] = useState<any>(null)
  const [abTest, setAbTest] = useState<any>(null)
  const [followUps, setFollowUps] = useState<any[]>([])
  const [activeTab, setActiveTab] = useState<'overview' | 'content' | 'tracking' | 'collaboration' | 'signature' | 'analytics'>('overview')
  const [showCollaborationPanel, setShowCollaborationPanel] = useState(false)
  const [showContentBlockPicker, setShowContentBlockPicker] = useState(false)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!hasAccess) {
      setLoading(false)
      return
    }
    loadAllData()
  }, [proposalId, hasAccess])

  const loadAllData = async () => {
    setLoading(true)
    try {
      // Create a timeout promise to prevent infinite loading
      const timeoutPromise = new Promise<never>((_, reject) => 
        setTimeout(() => reject(new Error('Request timeout')), 30000)
      )

      // Try multiple API endpoints to find the proposal
      // ORDER MATTERS: Try direct database first (most reliable), then enhanced, then universal
      let proposalFound = false

      // Try 1: Direct database lookup (MOST RELIABLE - should always work for simple-create proposals)
      try {
        console.log('[Enhanced Proposal Page] Step 1: Trying direct database lookup...')
        const propRes = await Promise.race([
          fetch(`/api/proposals/${proposalId}`),
          timeoutPromise
        ])

        console.log('[Enhanced Proposal Page] Direct lookup response:', propRes.status, propRes.statusText)

        if (propRes.ok) {
          const propData = await propRes.json()
          console.log('[Enhanced Proposal Page] Direct lookup data:', propData)
          if (propData.success && propData.data) {
            setProposal(propData.data)
            proposalFound = true
            console.log('[Enhanced Proposal Page] ✅ Proposal found via direct lookup!')
          }
        }
      } catch (error) {
        console.warn('[Enhanced Proposal Page] Direct lookup failed, trying enhanced API:', error)
      }

      // Try 2: Enhanced proposals API (if direct didn't work)
      if (!proposalFound) {
        try {
          console.log('[Enhanced Proposal Page] Step 2: Trying enhanced API...')
          const propRes = await Promise.race([
            fetch(`/api/proposals/enhanced?proposalId=${proposalId}`),
            timeoutPromise
          ])

          if (propRes.ok) {
            const propData = await propRes.json()
            if (propData.success && propData.data) {
              setProposal(propData.data?.[0] || propData.data)
              proposalFound = true
              console.log('[Enhanced Proposal Page] ✅ Proposal found via enhanced API!')
            }
          }
        } catch (error) {
          console.warn('[Enhanced Proposal Page] Enhanced API failed, trying universal API:', error)
        }
      }

      // Try 3: Universal proposals API (if others didn't work)
      if (!proposalFound) {
        try {
          console.log('[Enhanced Proposal Page] Step 3: Trying universal API...')
          const propRes = await Promise.race([
            fetch(`/api/proposals/universal/${proposalId}`),
            timeoutPromise
          ])

          if (propRes.ok) {
            const propData = await propRes.json()
            if (propData.success && propData.proposal) {
              setProposal(propData.proposal)
              proposalFound = true
              console.log('[Enhanced Proposal Page] ✅ Proposal found via universal API!')
            }
          }
        } catch (error) {
          console.warn('[Enhanced Proposal Page] Universal API failed:', error)
        }
      }

      // Try 3: Direct database lookup via proposals API
      if (!proposalFound) {
        try {
          const propRes = await Promise.race([
            fetch(`/api/proposals/${proposalId}`),
            timeoutPromise
          ])

          if (propRes.ok) {
            const propData = await propRes.json()
            if (propData.success && propData.data) {
              setProposal(propData.data)
              proposalFound = true
            }
          }
        } catch (error) {
          console.error('[Enhanced Proposal Page] All API attempts failed:', error)
        }
      }

      if (!proposalFound) {
        console.error('[Enhanced Proposal Page] ❌ Proposal not found in any service')
        console.error('[Enhanced Proposal Page] Tried:')
        console.error('  1. /api/proposals/' + proposalId + ' (direct database)')
        console.error('  2. /api/proposals/enhanced?proposalId=' + proposalId)
        console.error('  3. /api/proposals/universal/' + proposalId)
        // Don't throw - allow page to show "not found" state
      } else {
        console.log('[Enhanced Proposal Page] ✅ Proposal loaded successfully!')
      }

      // Load other data in parallel (non-blocking)
      const loadPromises = [
        fetch(`/api/proposals/${proposalId}/tracking?heatmap=true`)
          .then(res => res.ok ? res.json() : null)
          .then(data => data?.success && setTracking(data.data))
          .catch(err => console.warn('Failed to load tracking:', err)),

        fetch(`/api/proposals/${proposalId}/collaboration`)
          .then(res => res.ok ? res.json() : null)
          .then(data => data?.success && setCollaboration(data.data))
          .catch(err => console.warn('Failed to load collaboration:', err)),

        fetch(`/api/proposals/${proposalId}/sign`)
          .then(res => res.ok ? res.json() : null)
          .then(data => data?.success && setSignature(data.data))
          .catch(err => console.warn('Failed to load signature:', err)),

        fetch(`/api/proposals/${proposalId}/rich-media`)
          .then(res => res.ok ? res.json() : null)
          .then(data => data?.success && setRichMedia(data.data || []))
          .catch(err => console.warn('Failed to load rich media:', err)),

        fetch(`/api/proposals/${proposalId}/interactive`)
          .then(res => res.ok ? res.json() : null)
          .then(data => data?.success && setInteractive(data.data))
          .catch(err => console.warn('Failed to load interactive:', err)),
      ]

      // Wait for all with timeout, but don't fail if some fail
      await Promise.allSettled(loadPromises)
    } catch (error) {
      console.error('Error loading proposal data:', error)
      // Set loading to false even on error so user sees the error state
    } finally {
      setLoading(false)
    }
  }

  const [preparingPDF, setPreparingPDF] = useState(false)
  const [pdfShareUrl, setPdfShareUrl] = useState<string | null>(null)

  const handlePreparePDF = async () => {
    if (!proposal) return

    setPreparingPDF(true)
    try {
      const res = await fetch(`/api/proposals/${proposalId}/sign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'prepare-pdf',
        }),
      })

      const data = await res.json()
      if (data.success) {
        setPdfShareUrl(data.data.shareUrl)
        setSignature(data.data.status)
        alert('✅ PDF prepared successfully! You can now share it with customers for review.')
      } else {
        alert(`Error: ${data.error || 'Failed to prepare PDF'}`)
      }
    } catch (error) {
      console.error('Error preparing PDF:', error)
      alert('Failed to prepare PDF. Please try again.')
    } finally {
      setPreparingPDF(false)
    }
  }

  const handleCopyShareUrl = () => {
    if (pdfShareUrl || signature?.pdfShareUrl) {
      const url = pdfShareUrl || signature?.pdfShareUrl
      const fullUrl = `${window.location.origin}${url}`
      navigator.clipboard.writeText(fullUrl)
      alert('✅ Share URL copied to clipboard!')
    }
  }

  const handleInitiateSignature = async () => {
    try {
      const res = await fetch(`/api/proposals/${proposalId}/sign`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'initiate',
          signers: [
            { email: 'customer@example.com', name: 'Customer', role: 'customer', signingOrder: 1 },
          ],
        }),
      })
      const data = await res.json()
      if (data.success) {
        setSignature(data.data.status)
        alert('Signature workflow initiated!')
      }
    } catch (error) {
      console.error('Error initiating signature:', error)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50 to-indigo-50 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-gray-600 dark:text-gray-400">Loading proposal...</p>
        </div>
      </div>
    )
  }

  if (!hasAccess) {
    return (
      <PageTemplate
        title="Access Denied"
        description="You do not have permission to view this proposal"
        icon="ri-error-warning-line"
      >
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="text-center max-w-md">
            <div className="w-16 h-16 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center mx-auto mb-4">
              <i className="ri-error-warning-fill text-3xl text-red-600 dark:text-red-400" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
              Access Denied
            </h3>
            <p className="text-gray-600 dark:text-gray-400">
              You do not have the required permissions to view proposals. Please contact your administrator.
            </p>
          </div>
        </div>
      </PageTemplate>
    )
  }

  if (!proposal) {
    return (
      <ProposalErrorBoundary>
        <PageTemplate 
          title="Proposal Not Found"
          description="The requested proposal could not be found"
          icon="ri-error-warning-line"
        >
        <div className="text-center py-12">
          <p className="text-gray-500 dark:text-gray-400 mb-4">Proposal not found</p>
          <button
            onClick={() => router.push('/proposals')}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
