                </button>
              </div>
            </div>
            <div className="p-6 space-y-6">
              {/* Active Users */}
              <div>
                <h3 className="text-sm font-semibold text-gray-900 dark:text-white mb-3">Active Users</h3>
                <div className="space-y-2">
                  {collaboration.activeUsers?.map((user: any) => (
                    <div key={user.userId} className="flex items-center gap-3 p-2 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
                      <div className="w-10 h-10 rounded-full bg-gradient-to-r from-blue-500 to-indigo-500 flex items-center justify-center text-white text-sm font-semibold">
                        {user.userName[0]}
                      </div>
                      <div className="flex-1">
                        <p className="text-sm font-medium text-gray-900 dark:text-white">{user.userName}</p>
                        <p className="text-xs text-gray-500">{user.status}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Comments */}
              <div>
                <h3 className="text-sm font-semibold text-gray-900 dark:text-white mb-3">Comments</h3>
                <div className="space-y-3">
                  {collaboration.comments?.map((comment: any) => (
                    <div key={comment.id} className="p-3 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
                      <div className="flex items-start gap-2 mb-2">
                        <div className="w-6 h-6 rounded-full bg-blue-500 flex items-center justify-center text-white text-xs">
                          {comment.userName[0]}
                        </div>
                        <div className="flex-1">
                          <p className="text-sm font-medium text-gray-900 dark:text-white">{comment.userName}</p>
                          <p className="text-xs text-gray-500">
                            {new Date(comment.createdAt).toLocaleString()}
                          </p>
                        </div>
                      </div>
                      <p className="text-sm text-gray-700 dark:text-gray-300">{comment.content}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
    </ProposalErrorBoundary>
  )
}

