    }
  ], [])

  // CO2 Emissions Data
  const emissionsData = useMemo(() => ({
    totalCO2: 2.45,
    bySegment: [
      { segment: 'Origin to Saudi Customs', co2: 1.35 },
      { segment: 'Border Crossing', co2: 0.15 },
      { segment: 'Kuwait to Destination', co2: 0.45 },
