import { PremiumLoader } from '@/components/loading'
import { useAuth } from '@/contexts/AuthContext'
import Link from 'next/link'
import type { RFI, RFIAnalysis } from '@/lib/services/proposals/RFIService'

export default function RFIDetailPage() {
  const params = useParams()
  const router = useRouter()
  const { user, tenant, hasModuleAccess, canPerformAction } = useAuth()
  const rfiId = params.id as string

  // Permission check
  const hasAccess = hasModuleAccess('proposals-rfq', 'read_only')
  const canCreateRFQ = canPerformAction('proposals-rfq', 'proposals-rfq.rfq', undefined, 'write')
  const canCreateProposal = canPerformAction('proposals-rfq', 'proposals-rfq.proposals', undefined, 'write')

  const [rfi, setRfi] = useState<RFI | null>(null)
  const [analysis, setAnalysis] = useState<RFIAnalysis | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<'overview' | 'analysis' | 'pipeline' | 'intelligence'>('overview')
  const [generatingRFQ, setGeneratingRFQ] = useState(false)
  const [generatingProposal, setGeneratingProposal] = useState(false)

  useEffect(() => {
    if (!hasAccess) {
      setError('You do not have permission to view RFIs')
      setLoading(false)
      return
    }

    if (rfiId) {
      loadRFIData()
    }
  }, [rfiId, hasAccess])

  const loadRFIData = async () => {
    setLoading(true)
    setError(null)
    try {
      const tenantId = tenant?.id || 'default'
      
      // Load RFI and analysis in parallel
      const [rfiRes, analysisRes] = await Promise.allSettled([
        fetch(`/api/rfi/${rfiId}`, {
          headers: {
            'x-tenant-id': tenantId,
          },
        }),
        fetch(`/api/rfi/${rfiId}/analyze`, {
          headers: {
            'x-tenant-id': tenantId,
          },
        }),
      ])

      if (rfiRes.status === 'fulfilled' && rfiRes.value.ok) {
        const rfiData = await rfiRes.value.json()
        if (rfiData.success) {
          setRfi(rfiData.data)
        } else {
          setError(rfiData.error || 'Failed to load RFI')
        }
      } else {
        setError('Failed to load RFI')
      }

      if (analysisRes.status === 'fulfilled' && analysisRes.value.ok) {
        const analysisData = await analysisRes.value.json()
        if (analysisData.success) {
          setAnalysis(analysisData.data)
        }
      }
    } catch (err) {
      console.error('Error loading RFI data:', err)
      setError(err instanceof Error ? err.message : 'Unknown error')
    } finally {
      setLoading(false)
    }
  }

  const handleGenerateRFQ = async () => {
    if (!rfi) return
    if (!canCreateRFQ) {
      alert('You do not have permission to create RFQs')
      return
    }
    setGeneratingRFQ(true)
    try {
      const tenantId = tenant?.id || 'default'
      const res = await fetch(`/api/rfi/${rfiId}/generate-rfq`, {
        method: 'POST',
        headers: {
          'x-tenant-id': tenantId,
          'Content-Type': 'application/json',
        },
      })
      const data = await res.json()
      if (data.success) {
        // Reload RFI to get updated status
        await loadRFIData()
        // Navigate to RFQ if generated
        if (data.data.rfqId) {
          router.push(`/proposals/rfq?rfqId=${data.data.rfqId}`)
        }
      } else {
        alert(data.error || 'Failed to generate RFQ')
      }
    } catch (err) {
      console.error('Error generating RFQ:', err)
      alert('An error occurred while generating RFQ')
    } finally {
      setGeneratingRFQ(false)
    }
  }

  const handleGenerateProposal = async () => {
    if (!rfi) return
    if (!canCreateProposal) {
      alert('You do not have permission to create proposals')
      return
    }
    setGeneratingProposal(true)
    try {
      const tenantId = tenant?.id || 'default'
      const res = await fetch(`/api/rfi/${rfiId}/generate-proposal`, {
        method: 'POST',
        headers: {
          'x-tenant-id': tenantId,
          'Content-Type': 'application/json',
        },
      })
      const data = await res.json()
      if (data.success) {
        // Reload RFI to get updated status
        await loadRFIData()
        // Navigate to proposal if generated
        if (data.data.proposalId) {
          router.push(`/proposals/${data.data.proposalId}/enhanced`)
        }
      } else {
        alert(data.error || 'Failed to generate proposal')
      }
    } catch (err) {
      console.error('Error generating proposal:', err)
      alert('An error occurred while generating proposal')
    } finally {
      setGeneratingProposal(false)
    }
  }

  const getBadgeColor = (badge: string) => {
    switch (badge) {
      case 'Green':
        return 'bg-green-500'
      case 'Amber':
        return 'bg-yellow-500'
      case 'Red':
        return 'bg-red-500'
      default:
        return 'bg-gray-500'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'SUBMITTED':
        return 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400'
      case 'RFQ_GENERATED':
        return 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400'
      case 'PROPOSAL_GENERATED':
        return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400'
      case 'COMPLETED':
        return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300'
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300'
    }
  }

  if (loading) {
    return (
      <PageTemplate
        title="Loading RFI"
        description="Loading RFI details..."
        icon="ri-file-search-line"
      >
        <div className="flex items-center justify-center min-h-[400px]">
          <PremiumLoader message="Loading RFI details..." />
        </div>
      </PageTemplate>
    )
  }

  if (error || !rfi) {
    return (
      <PageTemplate
        title="RFI Not Found"
        description="The requested RFI could not be loaded"
        icon="ri-error-warning-line"
      >
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="text-center max-w-md">
            <div className="w-16 h-16 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center mx-auto mb-4">
              <i className="ri-error-warning-fill text-3xl text-red-600 dark:text-red-400" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
              {error || 'RFI Not Found'}
            </h3>
            <p className="text-gray-600 dark:text-gray-400 mb-4">
              The RFI you're looking for doesn't exist or you don't have permission to view it.
            </p>
            <div className="flex gap-3 justify-center">
              <button
                onClick={() => router.push('/proposals/rfi')}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                Back to RFI Portal
              </button>
              <button
                onClick={loadRFIData}
                className="px-4 py-2 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors"
              >
                Try Again
              </button>
            </div>
          </div>
        </div>
      </PageTemplate>
    )
  }

  return (
    <ProposalErrorBoundary>
      <PageTemplate
        title={`RFI ${rfi.rfiNumber}`}
        description={`${rfi.companyName} - Intelligent Request for Information`}
        icon="ri-file-search-line"
        actions={
          <div className="flex items-center gap-3">
            <Link
              href="/proposals/rfi"
              className="px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
            >
              <i className="ri-arrow-left-line mr-2" />
              Back
            </Link>
            {rfi.status === 'SUBMITTED' && !rfi.generatedRFQId && (
              <button
                onClick={handleGenerateRFQ}
                disabled={generatingRFQ}
                className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {generatingRFQ ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent" />
                    Generating...
                  </>
                ) : (
                  <>
                    <i className="ri-questionnaire-line" />
                    Generate RFQ
                  </>
                )}
              </button>
            )}
            {rfi.status === 'SUBMITTED' && !rfi.generatedProposalId && (
              <button
                onClick={handleGenerateProposal}
                disabled={generatingProposal}
                className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {generatingProposal ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent" />
                    Generating...
                  </>
                ) : (
                  <>
                    <i className="ri-file-add-line" />
                    Generate Proposal
                  </>
                )}
              </button>
            )}
          </div>
        }
      >
        <div className="space-y-6">
          {/* Header Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl p-6 text-white shadow-lg"
            >
              <div className="text-sm opacity-90">Status</div>
              <div className="text-2xl font-bold mt-1">{rfi.status}</div>
            </motion.div>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="bg-gradient-to-br from-green-500 to-green-600 rounded-xl p-6 text-white shadow-lg"
            >
              <div className="text-sm opacity-90">Data Completeness</div>
              <div className="text-2xl font-bold mt-1">{rfi.dataCompleteness}%</div>
            </motion.div>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="bg-gradient-to-br from-purple-500 to-purple-600 rounded-xl p-6 text-white shadow-lg"
            >
              <div className="text-sm opacity-90">Pricing Readiness</div>
              <div className="text-2xl font-bold mt-1">{rfi.pricingReadiness}%</div>
            </motion.div>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="bg-gradient-to-br from-orange-500 to-orange-600 rounded-xl p-6 text-white shadow-lg"
            >
              <div className="text-sm opacity-90">Confidence</div>
              <div className="text-2xl font-bold mt-1">{rfi.pricingConfidence}</div>
            </motion.div>
          </div>

          {/* Tabs */}
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
            <div className="border-b border-gray-200 dark:border-gray-700">
              <div className="flex space-x-1 p-2">
                {(['overview', 'analysis', 'pipeline', 'intelligence'] as const).map((tab) => (
                  <button
                    key={tab}
                    onClick={() => setActiveTab(tab)}
                    className={`px-4 py-2 text-sm font-medium rounded-lg transition-colors ${
                      activeTab === tab
                        ? 'bg-blue-600 text-white'
                        : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
                    }`}
                  >
                    {tab.charAt(0).toUpperCase() + tab.slice(1)}
                  </button>
                ))}
              </div>
            </div>

            <div className="p-6">
              <AnimatePresence mode="wait">
                {activeTab === 'overview' && (
                  <motion.div
                    key="overview"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                  >
                    <div className="space-y-6">
                      {/* Company Information */}
                      <div>
                        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                          Company Information
                        </h3>
                        <div className="grid grid-cols-2 gap-4">
                          <div>
                            <label className="text-sm text-gray-600 dark:text-gray-400">Company Name</label>
                            <div className="text-gray-900 dark:text-white font-medium">{rfi.companyName}</div>
                          </div>
                          <div>
                            <label className="text-sm text-gray-600 dark:text-gray-400">Contact Person</label>
                            <div className="text-gray-900 dark:text-white font-medium">{rfi.contactPerson}</div>
                          </div>
                          <div>
                            <label className="text-sm text-gray-600 dark:text-gray-400">Email</label>
                            <div className="text-gray-900 dark:text-white font-medium">{rfi.email}</div>
                          </div>
                          <div>
                            <label className="text-sm text-gray-600 dark:text-gray-400">Phone</label>
                            <div className="text-gray-900 dark:text-white font-medium">{rfi.phone || 'N/A'}</div>
                          </div>
                        </div>
                      </div>

                      {/* Storage Details */}
                      {rfi.storage && (
                        <div>
                          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                            Storage Requirements
                          </h3>
                          <div className="grid grid-cols-3 gap-4">
                            {rfi.storage.storageSqm && (
                              <div>
                                <label className="text-sm text-gray-600 dark:text-gray-400">Storage (sqm)</label>
                                <div className="text-gray-900 dark:text-white font-medium">{rfi.storage.storageSqm}</div>
                              </div>
                            )}
                            {rfi.storage.storageCbm && (
                              <div>
                                <label className="text-sm text-gray-600 dark:text-gray-400">Storage (cbm)</label>
                                <div className="text-gray-900 dark:text-white font-medium">{rfi.storage.storageCbm}</div>
                              </div>
                            )}
                            {rfi.storage.palletPositions && (
                              <div>
                                <label className="text-sm text-gray-600 dark:text-gray-400">Pallet Positions</label>
                                <div className="text-gray-900 dark:text-white font-medium">{rfi.storage.palletPositions}</div>
                              </div>
                            )}
                          </div>
                        </div>
                      )}

                      {/* Pipeline Status */}
                      <div>
                        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                          Pipeline Status
                        </h3>
                        <div className="flex items-center gap-4">
                          <div className="flex items-center gap-2">
                            <div className={`w-3 h-3 rounded-full ${rfi.status === 'SUBMITTED' ? 'bg-blue-500' : 'bg-gray-300'}`} />
                            <span className="text-sm text-gray-600 dark:text-gray-400">RFI Submitted</span>
                          </div>
                          {rfi.generatedRFQId && (
                            <>
                              <i className="ri-arrow-right-line text-gray-400" />
                              <Link
                                href={`/proposals/rfq?rfqId=${rfi.generatedRFQId}`}
                                className="flex items-center gap-2 text-purple-600 dark:text-purple-400 hover:underline"
                              >
                                <div className="w-3 h-3 rounded-full bg-purple-500" />
                                <span className="text-sm font-medium">RFQ Generated</span>
                              </Link>
                            </>
                          )}
                          {rfi.generatedProposalId && (
                            <>
                              <i className="ri-arrow-right-line text-gray-400" />
                              <Link
                                href={`/proposals/${rfi.generatedProposalId}/enhanced`}
                                className="flex items-center gap-2 text-green-600 dark:text-green-400 hover:underline"
                              >
                                <div className="w-3 h-3 rounded-full bg-green-500" />
                                <span className="text-sm font-medium">Proposal Generated</span>
                              </Link>
                            </>
                          )}
                        </div>
                      </div>
                    </div>
                  </motion.div>
                )}

                {activeTab === 'analysis' && analysis && (
                  <motion.div
                    key="analysis"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                  >
                    <div className="space-y-6">
                      <div>
                        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                          Intelligence Analysis
                        </h3>
                        <div className="grid grid-cols-2 gap-4">
                          <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-4">
                            <div className="text-sm text-gray-600 dark:text-gray-400">Completeness</div>
                            <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">{analysis.completeness}%</div>
                          </div>
                          <div className="bg-purple-50 dark:bg-purple-900/20 rounded-lg p-4">
                            <div className="text-sm text-gray-600 dark:text-gray-400">Readiness</div>
                            <div className="text-2xl font-bold text-purple-600 dark:text-purple-400">{analysis.readiness}%</div>
                          </div>
                        </div>
                      </div>

                      {analysis.recommendations && analysis.recommendations.length > 0 && (
                        <div>
                          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                            Recommendations
                          </h3>
                          <ul className="space-y-2">
                            {analysis.recommendations.map((rec, idx) => (
                              <li key={idx} className="flex items-start gap-2">
                                <i className="ri-checkbox-circle-line text-green-500 mt-0.5" />
                                <span className="text-gray-700 dark:text-gray-300">{rec}</span>
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}

                      {analysis.riskFactors && analysis.riskFactors.length > 0 && (
                        <div>
                          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                            Risk Factors
                          </h3>
                          <ul className="space-y-2">
                            {analysis.riskFactors.map((risk, idx) => (
                              <li key={idx} className="flex items-start gap-2">
                                <i className="ri-alert-line text-orange-500 mt-0.5" />
                                <span className="text-gray-700 dark:text-gray-300">{risk}</span>
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}
                    </div>
                  </motion.div>
                )}

                {activeTab === 'pipeline' && (
                  <motion.div
                    key="pipeline"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                  >
                    <div className="space-y-6">
                      <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                        Automation Pipeline
                      </h3>
                      <div className="bg-gray-50 dark:bg-gray-700/50 rounded-lg p-6">
                        <div className="space-y-4">
                          <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                              <div className="w-10 h-10 rounded-full bg-blue-500 text-white flex items-center justify-center font-bold">
                                1
                              </div>
                              <div>
                                <div className="font-medium text-gray-900 dark:text-white">RFI Submitted</div>
                                <div className="text-sm text-gray-600 dark:text-gray-400">
                                  {rfi.submittedAt ? new Date(rfi.submittedAt).toLocaleDateString() : 'Not submitted'}
                                </div>
                              </div>
                            </div>
                            <div className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusColor(rfi.status)}`}>
                              {rfi.status}
                            </div>
                          </div>

                          {rfi.generatedRFQId && (
                            <>
                              <div className="flex items-center justify-center">
                                <i className="ri-arrow-down-line text-2xl text-gray-400" />
                              </div>
                              <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                  <div className="w-10 h-10 rounded-full bg-purple-500 text-white flex items-center justify-center font-bold">
                                    2
                                  </div>
                                  <div>
                                    <div className="font-medium text-gray-900 dark:text-white">RFQ Generated</div>
                                    <Link
                                      href={`/proposals/rfq?rfqId=${rfi.generatedRFQId}`}
                                      className="text-sm text-purple-600 dark:text-purple-400 hover:underline"
                                    >
                                      View RFQ
                                    </Link>
                                  </div>
                                </div>
                                <div className="px-3 py-1 rounded-full text-sm font-medium bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-400">
                                  Complete
                                </div>
                              </div>
                            </>
                          )}

                          {rfi.generatedProposalId && (
                            <>
                              <div className="flex items-center justify-center">
                                <i className="ri-arrow-down-line text-2xl text-gray-400" />
                              </div>
                              <div className="flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                  <div className="w-10 h-10 rounded-full bg-green-500 text-white flex items-center justify-center font-bold">
                                    3
                                  </div>
                                  <div>
                                    <div className="font-medium text-gray-900 dark:text-white">Proposal Generated</div>
                                    <Link
                                      href={`/proposals/${rfi.generatedProposalId}/enhanced`}
                                      className="text-sm text-green-600 dark:text-green-400 hover:underline"
                                    >
                                      View Proposal
                                    </Link>
                                  </div>
                                </div>
                                <div className="px-3 py-1 rounded-full text-sm font-medium bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400">
                                  Complete
                                </div>
                              </div>
                            </>
                          )}
                        </div>
                      </div>

                      {rfi.status === 'SUBMITTED' && !rfi.generatedRFQId && !rfi.generatedProposalId && (
                        <div className="flex gap-3">
                          <button
                            onClick={handleGenerateRFQ}
                            disabled={generatingRFQ}
                            className="flex-1 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                          >
                            {generatingRFQ ? (
                              <>
                                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent" />
                                Generating RFQ...
                              </>
                            ) : (
                              <>
                                <i className="ri-questionnaire-line" />
                                Generate RFQ
                              </>
                            )}
                          </button>
                          <button
                            onClick={handleGenerateProposal}
                            disabled={generatingProposal}
                            className="flex-1 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                          >
                            {generatingProposal ? (
                              <>
                                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent" />
                                Generating Proposal...
                              </>
                            ) : (
                              <>
                                <i className="ri-file-add-line" />
                                Generate Proposal
                              </>
                            )}
                          </button>
                        </div>
                      )}
                    </div>
                  </motion.div>
                )}

                {activeTab === 'intelligence' && analysis && (
                  <motion.div
                    key="intelligence"
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                  >
                    <div className="space-y-6">
                      <div>
                        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                          Key Drivers
                        </h3>
                        {rfi.keyDrivers && (
                          <div className="grid grid-cols-2 gap-4">
                            {Object.entries(rfi.keyDrivers).map(([key, value]) => (
                              <div key={key} className="bg-gray-50 dark:bg-gray-700/50 rounded-lg p-4">
                                <div className="text-sm text-gray-600 dark:text-gray-400 capitalize">
                                  {key.replace(/([A-Z])/g, ' $1').trim()}
                                </div>
                                <div className="text-gray-900 dark:text-white font-medium mt-1">{value}</div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>

                      {analysis.assumptions && analysis.assumptions.length > 0 && (
                        <div>
                          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                            Assumptions
                          </h3>
                          <ul className="space-y-2">
                            {analysis.assumptions.map((assumption, idx) => (
                              <li key={idx} className="flex items-start gap-2">
                                <i className="ri-information-line text-blue-500 mt-0.5" />
                                <span className="text-gray-700 dark:text-gray-300">{assumption}</span>
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}

                      {analysis.estimatedValue && (
                        <div>
                          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                            Estimated Value
                          </h3>
                          <div className="bg-gradient-to-br from-green-500 to-green-600 rounded-xl p-6 text-white">
                            <div className="text-sm opacity-90">Estimated Proposal Value</div>
                            <div className="text-3xl font-bold mt-1">
                              {new Intl.NumberFormat('en-US', {
                                style: 'currency',
                                currency: 'SAR',
                              }).format(analysis.estimatedValue)}
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </div>
      </PageTemplate>
    </ProposalErrorBoundary>
  )
}

/**
 * RFI Creation Page - Advanced Portal (Full Form)
 * Dark theme, collapsible sections, live intelligence sidebar
 * Based on Flex Logistics RFI Portal
 * 
 * NOTE: This is the advanced/full RFI creation form.
 * The wizard-style form is available at /proposals/rfi/new/wizard
 * 
 * Consolidated: Both forms create RFIs, but this one provides more detailed fields
 * and live intelligence. The wizard is simpler and recommended for most users.
 */

'use client'

import { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import PageTemplate from '@/components/PageTemplate'
import ProposalErrorBoundary from '@/components/proposals/ProposalErrorBoundary'
import { useAuth } from '@/contexts/AuthContext'

interface RFIData {
  companyName: string
  contactPerson: string
  email: string
  phone: string
  address: string
  flexRepresentative: string
  date: string
  storage: {
    storageSqm: string
    storageCbm: string
    palletPositions: string
    mixAmbient: string
    mixTemp: string
    mixYard: string
    tempRange: string
    storageType: string
    skuCount: string
    stockLevels: string
    invValue: string
    annualTurnover: string
    insuranceRequired: string
  }
  inbound: {
    inboundPalletsDaily: string
    inboundShipmentsDaily: string
    inboundTrucksDaily: string
    inboundPackaging: string
    inboundSplit: string
    packageSizesPerSku: string
    palletsPerShipmentAvg: string
    skusPerPalletAvg: string
    verifyPalletPct: string
    verifyCartonPct: string
    verifyPiecePct: string
    inboundInspection: string
  }
  outbound: {
    outboundPalletsDaily: string
    outboundShipmentsDaily: string
    outboundTrucksDaily: string
    rotationRule: string
    outboundType: string
    ordersDaily: string
    linesPerOrder: string
    cutoffTime: string
    outboundNotes: string
  }
  returns: {
    returnsRequired: string
    returnsNotes: string
  }
  vas: {
    vasRequired: string
    vasRepack: boolean
    vasKitting: boolean
    vasPalletize: boolean
    vasLabel: boolean
    vasBarcode: boolean
    vasShrink: boolean
    vasOtherDesc: string
    vasVolumes: string
  }
  systems: {
    wms: string
    systemReq: string
  }
  kpis: string
  additional: string
  certify: string
}

interface Analysis {
  completeness: number
  readiness: number
  confidence: 'Low' | 'Medium' | 'High'
  assumptions: string[]
  keyDrivers: {
    storage: string
    handling: string
    pick: string
    verify: string
    vas: string
  }
  badge: 'Green' | 'Amber' | 'Red'
}

export default function NewRFIPage() {
  const router = useRouter()
  const { hasModuleAccess, canPerformAction } = useAuth()
  const [rfiNumber] = useState(`FLX-RFI-${Math.floor(Math.random() * 900000) + 100000}`)
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [analysis, setAnalysis] = useState<Analysis | null>(null)
  const [intelligence, setIntelligence] = useState<any>(null)
  const [activeSection, setActiveSection] = useState<string>('I')
  const [attachments, setAttachments] = useState<Array<{ name: string; size: number; type: string }>>([])
  const [lastSaved, setLastSaved] = useState<Date | null>(null)

  // Permission check
  const hasAccess = hasModuleAccess('proposals-rfq', 'read_only')
  const canCreate = canPerformAction('proposals-rfq', 'proposals-rfq.rfi', undefined, 'write')

  const [formData, setFormData] = useState<RFIData>({
    companyName: '',
    contactPerson: '',
    email: '',
    phone: '',
    address: '',
    flexRepresentative: '',
    date: new Date().toISOString().split('T')[0],
    storage: {
      storageSqm: '',
      storageCbm: '',
      palletPositions: '',
      mixAmbient: '',
      mixTemp: '',
      mixYard: '',
      tempRange: '',
      storageType: '',
      skuCount: '',
      stockLevels: '',
      invValue: '',
      annualTurnover: '',
      insuranceRequired: '',
    },
    inbound: {
      inboundPalletsDaily: '',
      inboundShipmentsDaily: '',
      inboundTrucksDaily: '',
      inboundPackaging: '',
      inboundSplit: '',
      packageSizesPerSku: '',
      palletsPerShipmentAvg: '',
      skusPerPalletAvg: '',
      verifyPalletPct: '',
      verifyCartonPct: '',
      verifyPiecePct: '',
      inboundInspection: '',
    },
    outbound: {
      outboundPalletsDaily: '',
      outboundShipmentsDaily: '',
      outboundTrucksDaily: '',
      rotationRule: '',
      outboundType: '',
      ordersDaily: '',
      linesPerOrder: '',
      cutoffTime: '',
      outboundNotes: '',
    },
    returns: {
      returnsRequired: '',
      returnsNotes: '',
    },
    vas: {
      vasRequired: '',
      vasRepack: false,
      vasKitting: false,
      vasPalletize: false,
      vasLabel: false,
      vasBarcode: false,
      vasShrink: false,
      vasOtherDesc: '',
      vasVolumes: '',
    },
    systems: {
      wms: '',
      systemReq: '',
    },
    kpis: '',
    additional: '',
    certify: '',
  })

  const calculateLocalAnalysis = () => {
    // Simple local calculation
    const criticalFields = [
      formData.companyName,
      formData.contactPerson,
      formData.email,
      formData.storage.storageSqm,
      formData.storage.storageCbm,
      formData.storage.palletPositions,
      formData.inbound.inboundPalletsDaily,
      formData.outbound.outboundPalletsDaily,
      formData.outbound.ordersDaily,
    ]

    const filled = criticalFields.filter(f => f && f.trim()).length
    const completeness = Math.round((filled / criticalFields.length) * 100)

    const sizingOk = !!(formData.storage.storageSqm || formData.storage.storageCbm || formData.storage.palletPositions)
    const volumesOk = !!(formData.inbound.inboundPalletsDaily || formData.outbound.outboundPalletsDaily)
    const ordersOk = !!(formData.outbound.ordersDaily)

    let readiness = 0
    if (sizingOk) readiness += 25
    if (volumesOk) readiness += 25
    if (ordersOk) readiness += 25
    if (formData.inbound.inboundPackaging) readiness += 25

    let confidence: 'Low' | 'Medium' | 'High' = 'Low'
    if (readiness >= 82) confidence = 'High'
    else if (readiness >= 60) confidence = 'Medium'

    let badge: 'Green' | 'Amber' | 'Red' = 'Red'
    if (readiness >= 82) badge = 'Green'
    else if (readiness >= 60) badge = 'Amber'

    setAnalysis({
      completeness,
      readiness,
      confidence,
      assumptions: [],
      keyDrivers: {
        storage: sizingOk ? 'Sqm/CBM' : 'Missing',
        handling: '—',
        pick: formData.outbound.outboundType || '—',
        verify: '—',
        vas: formData.vas.vasRequired === 'Yes' ? 'Selected' : 'None',
      },
      badge,
    })
  }

  const analyzeForm = useCallback(async () => {
    try {
      // Create a temporary RFI for analysis
      const tempData = {
        tenantId: 'default',
        ...formData,
        createdBy: 'user',
      }

      // Call analysis API
      const [analysisResponse, intelligenceResponse] = await Promise.allSettled([
        fetch('/api/rfi/analyze-temp', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(tempData),
        }),
        fetch('/api/rfi/intelligence-temp', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(tempData),
        }),
      ])

      if (analysisResponse.status === 'fulfilled' && analysisResponse.value.ok) {
        const data = await analysisResponse.value.json()
        setAnalysis(data.data)
      } else {
        calculateLocalAnalysis()
      }

      if (intelligenceResponse.status === 'fulfilled' && intelligenceResponse.value.ok) {
        const intelData = await intelligenceResponse.value.json()
        setIntelligence(intelData.data)
      }
    } catch (error) {
      calculateLocalAnalysis()
    }
  }, [formData])

  // Auto-save functionality
  const autoSave = useCallback(async () => {
    if (!formData.companyName && !formData.contactPerson) return // Don't save empty forms
    
    setSaving(true)
    try {
      // Save to localStorage as draft
      const draft = {
        ...formData,
        attachments,
        rfiNumber,
        lastSaved: new Date().toISOString(),
      }
      localStorage.setItem(`rfi-draft-${rfiNumber}`, JSON.stringify(draft))
      setLastSaved(new Date())
    } catch (error) {
      console.error('Error auto-saving:', error)
    } finally {
      setSaving(false)
    }
  }, [formData, attachments, rfiNumber])

  // Load draft on mount
  useEffect(() => {
    const savedDraft = localStorage.getItem(`rfi-draft-${rfiNumber}`)
    if (savedDraft) {
      try {
        const draft = JSON.parse(savedDraft)
        setFormData(draft)
        if (draft.attachments) setAttachments(draft.attachments)
        if (draft.lastSaved) setLastSaved(new Date(draft.lastSaved))
      } catch (error) {
        console.error('Error loading draft:', error)
      }
    }
  }, [rfiNumber])

  // Auto-save on form changes (debounced)
  useEffect(() => {
    const timer = setTimeout(() => {
      autoSave()
    }, 2000) // Save 2 seconds after last change

    return () => clearTimeout(timer)
  }, [formData, autoSave])

  useEffect(() => {
    analyzeForm()
  }, [analyzeForm])

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files) return

    Array.from(files).forEach(file => {
      setAttachments(prev => [...prev, {
        name: file.name,
        size: file.size,
        type: file.type,
      }])
    })
  }

  const handleRemoveAttachment = (index: number) => {
    setAttachments(prev => prev.filter((_, i) => i !== index))
  }

  const handleSubmit = async () => {
    if (!formData.companyName || !formData.contactPerson || !formData.email) {
      alert('Please fill required fields: Company Name, Contact Person, Email.')
      return
    }

    setLoading(true)
    try {
      const response = await fetch('/api/rfi', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...formData,
          attachments,
          autoGenerateRFQ: analysis && analysis.readiness >= 60,
          autoGenerateProposal: analysis && analysis.readiness >= 82,
        }),
      })

      if (response.ok) {
        const data = await response.json()
        // Clear draft
        localStorage.removeItem(`rfi-draft-${rfiNumber}`)
        router.push(`/proposals/rfi/${data.data.id}`)
      } else {
        const error = await response.json()
        alert(error.error || 'Error creating RFI')
      }
    } catch (error) {
      console.error('Error submitting RFI:', error)
      alert('Error submitting RFI')
    } finally {
      setLoading(false)
    }
  }

  const updateField = (section: string, field: string, value: any) => {
    if (section === 'main') {
      setFormData(prev => ({ ...prev, [field]: value }))
    } else {
      setFormData(prev => ({
        ...prev,
        [section]: {
          ...prev[section as keyof typeof prev],
          [field]: value,
        },
      }))
    }
  }

  const getBadgeColor = (badge: string) => {
    switch (badge) {
      case 'Green':
        return 'bg-green-500'
      case 'Amber':
        return 'bg-yellow-500'
      case 'Red':
        return 'bg-red-500'
      default:
        return 'bg-gray-500'
    }
  }

  if (!hasAccess || !canCreate) {
    return (
      <ProposalErrorBoundary>
        <PageTemplate
          title="Access Denied"
          description="You do not have permission to create RFIs"
          icon="ri-error-warning-line"
        >
          <div className="flex items-center justify-center min-h-[400px]">
            <div className="text-center max-w-md">
              <div className="w-16 h-16 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center mx-auto mb-4">
                <i className="ri-error-warning-fill text-3xl text-red-600 dark:text-red-400" />
              </div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
                Access Denied
              </h3>
              <p className="text-gray-600 dark:text-gray-400">
                You do not have the required permissions to create RFIs. Please contact your administrator.
              </p>
            </div>
          </div>
        </PageTemplate>
      </ProposalErrorBoundary>
    )
  }

  return (
    <>

      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white p-6">
        <div className="max-w-7xl mx-auto">
          {/* Header */}
          <div className="mb-6 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 rounded-2xl bg-white/10 border border-white/20 flex items-center justify-center">
                <i className="ri-file-search-line text-2xl" />
              </div>
              <div>
                <h1 className="text-2xl font-bold">Flex Logistics — Smart RFI Portal</h1>
                <p className="text-gray-400 text-sm mt-1">
                  Built to capture pricing-critical inputs with minimal friction
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              {saving && (
                <span className="px-3 py-1 bg-blue-500/20 border border-blue-500/30 rounded-lg text-xs text-blue-300 flex items-center gap-2">
                  <i className="ri-save-line animate-pulse" />
                  Saving...
                </span>
              )}
              {lastSaved && !saving && (
                <span className="px-3 py-1 bg-green-500/20 border border-green-500/30 rounded-lg text-xs text-green-300 flex items-center gap-2">
                  <i className="ri-check-line" />
                  Saved {lastSaved.toLocaleTimeString()}
                </span>
              )}
              <Link
                href="/proposals/rfi/new/wizard"
                className="px-4 py-2 bg-white/10 border border-white/20 rounded-xl text-white hover:bg-white/20 transition-all text-sm flex items-center gap-2"
              >
                <i className="ri-magic-line" />
                Switch to Wizard
              </Link>
              <span className="px-4 py-2 bg-white/10 border border-white/20 rounded-full text-sm font-mono">
                Ref: {rfiNumber}
              </span>
              <button
                onClick={handleSubmit}
                disabled={loading}
                className="px-6 py-2 bg-gradient-to-r from-orange-500 to-blue-500 text-white rounded-xl font-semibold hover:opacity-90 transition-all disabled:opacity-50 flex items-center gap-2"
              >
                {loading ? (
                  <>
                    <i className="ri-loader-4-line animate-spin" />
                    Submitting...
                  </>
                ) : (
                  <>
                    <i className="ri-check-line" />
                    Submit RFI
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Section Navigation */}
          <div className="mb-6 flex items-center gap-2 overflow-x-auto pb-2">
            {['I', 'II', 'III', 'IV'].map((section) => (
              <button
                key={section}
                onClick={() => setActiveSection(section)}
                className={`px-4 py-2 rounded-xl text-sm font-semibold transition-all whitespace-nowrap ${
                  activeSection === section
                    ? 'bg-gradient-to-r from-orange-500 to-blue-500 text-white'
                    : 'bg-white/5 border border-white/20 text-gray-300 hover:bg-white/10'
                }`}
              >
                {section === 'I' && 'Contact Info'}
                {section === 'II' && 'Warehousing'}
                {section === 'III' && 'KPIs & Reporting'}
                {section === 'IV' && 'Additional & Attachments'}
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Main Form */}
            <div className="lg:col-span-2 space-y-4">
              {/* Section I: Contact Information */}
              <motion.details
                open={activeSection === 'I'}
                onToggle={(e) => setActiveSection(e.currentTarget.open ? 'I' : '')}
                className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden"
              >
                <summary className="p-4 cursor-pointer flex items-center justify-between hover:bg-white/5 transition-colors">
                  <div className="flex items-center gap-3">
                    <span className="px-3 py-1 bg-white/10 rounded-full text-xs font-mono">I</span>
                    <strong>Contact Information</strong>
                  </div>
                  <span className="text-xl">▾</span>
                </summary>
                <div className="p-4 pt-0 space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm text-gray-300 mb-2">
                        Company Name <span className="text-orange-400" title="Used for contract entity, invoicing, and reference matching.">ⓘ</span>
                      </label>
                      <input
                        type="text"
                        value={formData.companyName}
                        onChange={(e) => updateField('main', 'companyName', e.target.value)}
                        placeholder="Legal company name"
                        className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm text-gray-300 mb-2">
                        Contact Person <span className="text-orange-400" title="Who can validate assumptions and approve pricing.">ⓘ</span>
                      </label>
                      <input
                        type="text"
                        value={formData.contactPerson}
                        onChange={(e) => updateField('main', 'contactPerson', e.target.value)}
                        placeholder="Full name"
                        className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                        required
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm text-gray-300 mb-2">Email</label>
                      <input
                        type="email"
                        value={formData.email}
                        onChange={(e) => updateField('main', 'email', e.target.value)}
                        placeholder="name@company.com"
                        className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                        required
                      />
                    </div>
                    <div>
                      <label className="block text-sm text-gray-300 mb-2">
                        Phone / WhatsApp <span className="text-gray-500 text-xs">(optional)</span>
                      </label>
                      <input
                        type="tel"
                        value={formData.phone}
                        onChange={(e) => updateField('main', 'phone', e.target.value)}
                        placeholder="+966..."
                        className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm text-gray-300 mb-2">Address</label>
                      <input
                        type="text"
                        value={formData.address}
                        onChange={(e) => updateField('main', 'address', e.target.value)}
                        placeholder="City, district, facility address"
                        className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                      />
                    </div>
                    <div>
                      <label className="block text-sm text-gray-300 mb-2">Flex Representative / Date</label>
                      <div className="grid grid-cols-2 gap-2">
                        <input
                          type="text"
                          value={formData.flexRepresentative}
                          onChange={(e) => updateField('main', 'flexRepresentative', e.target.value)}
                          placeholder="Flex SCS representative"
                          className="px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                        />
                        <input
                          type="date"
                          value={formData.date}
                          onChange={(e) => updateField('main', 'date', e.target.value)}
                          className="px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white focus:border-blue-400 focus:outline-none"
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </motion.details>

              {/* Section II: Warehousing Details - This is a large section, I'll create it in parts */}
              <motion.details
                open={activeSection === 'II'}
                onToggle={(e) => setActiveSection(e.currentTarget.open ? 'II' : '')}
                className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden"
              >
                <summary className="p-4 cursor-pointer flex items-center justify-between hover:bg-white/5 transition-colors">
                  <div className="flex items-center gap-3">
                    <span className="px-3 py-1 bg-white/10 rounded-full text-xs font-mono">II</span>
                    <strong>Warehousing Details</strong>
                  </div>
                  <span className="text-xl">▾</span>
                </summary>
                <div className="p-4 pt-0 space-y-4">
                  {/* Storage Subsection */}
                  <details open className="bg-white/5 rounded-xl p-4">
                    <summary className="cursor-pointer flex items-center gap-2 mb-3">
                      <span className="px-2 py-1 bg-white/10 rounded text-xs font-mono">A</span>
                      <strong className="text-sm">Storage</strong>
                    </summary>
                    <div className="space-y-4 pt-2">
                      <div className="bg-orange-500/20 border border-orange-500/30 rounded-lg p-3 text-sm">
                        <strong>Fast-track rule:</strong> If you only fill 3 things, fill{' '}
                        <span className="px-2 py-1 bg-white/10 rounded text-xs">storage size</span>,{' '}
                        <span className="px-2 py-1 bg-white/10 rounded text-xs">daily inbound/outbound</span>, and{' '}
                        <span className="px-2 py-1 bg-white/10 rounded text-xs">orders & lines</span>.
                      </div>
                      <div className="grid grid-cols-3 gap-4">
                        <div>
                          <label className="block text-sm text-gray-300 mb-2">
                            Storage size (Sq. meters) <span className="text-orange-400">ⓘ</span>
                          </label>
                          <input
                            type="number"
                            min="0"
                            value={formData.storage.storageSqm}
                            onChange={(e) => updateField('storage', 'storageSqm', e.target.value)}
                            placeholder="e.g., 3,000"
                            className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
