                          className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white focus:border-blue-400 focus:outline-none"
                        >
                          <option value="">Select</option>
                          <option value="Yes">Yes</option>
                          <option value="No">No</option>
                          <option value="TBD">To be determined</option>
                        </select>
                      </div>
                      {formData.vas.vasRequired === 'Yes' && (
                        <>
                          <div className="bg-purple-500/20 border border-purple-500/30 rounded-lg p-3 text-sm mb-4">
                            <strong>Select VAS Services:</strong>
                          </div>
                          <div className="grid grid-cols-2 gap-3">
                            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white/5 rounded-lg hover:bg-white/10 transition-colors">
                              <input
                                type="checkbox"
                                checked={formData.vas.vasRepack}
                                onChange={(e) => updateField('vas', 'vasRepack', e.target.checked)}
                                className="w-4 h-4 rounded"
                              />
                              <span className="text-sm">Repack</span>
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white/5 rounded-lg hover:bg-white/10 transition-colors">
                              <input
                                type="checkbox"
                                checked={formData.vas.vasKitting}
                                onChange={(e) => updateField('vas', 'vasKitting', e.target.checked)}
                                className="w-4 h-4 rounded"
                              />
                              <span className="text-sm">Kitting</span>
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white/5 rounded-lg hover:bg-white/10 transition-colors">
                              <input
                                type="checkbox"
                                checked={formData.vas.vasPalletize}
                                onChange={(e) => updateField('vas', 'vasPalletize', e.target.checked)}
                                className="w-4 h-4 rounded"
                              />
                              <span className="text-sm">Palletize</span>
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white/5 rounded-lg hover:bg-white/10 transition-colors">
                              <input
                                type="checkbox"
                                checked={formData.vas.vasLabel}
                                onChange={(e) => updateField('vas', 'vasLabel', e.target.checked)}
                                className="w-4 h-4 rounded"
                              />
                              <span className="text-sm">Labeling</span>
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white/5 rounded-lg hover:bg-white/10 transition-colors">
                              <input
                                type="checkbox"
                                checked={formData.vas.vasBarcode}
                                onChange={(e) => updateField('vas', 'vasBarcode', e.target.checked)}
                                className="w-4 h-4 rounded"
                              />
                              <span className="text-sm">Barcode Printing</span>
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white/5 rounded-lg hover:bg-white/10 transition-colors">
                              <input
                                type="checkbox"
                                checked={formData.vas.vasShrink}
                                onChange={(e) => updateField('vas', 'vasShrink', e.target.checked)}
                                className="w-4 h-4 rounded"
                              />
                              <span className="text-sm">Shrink Wrapping</span>
                            </label>
                          </div>
                          <div className="mt-4">
                            <label className="block text-sm text-gray-300 mb-2">
                              Other VAS Description
                            </label>
                            <input
                              type="text"
                              value={formData.vas.vasOtherDesc}
                              onChange={(e) => updateField('vas', 'vasOtherDesc', e.target.value)}
                              placeholder="Describe other VAS requirements..."
                              className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                            />
                          </div>
                          <div>
                            <label className="block text-sm text-gray-300 mb-2">
                              VAS Volumes
                            </label>
                            <input
                              type="text"
                              value={formData.vas.vasVolumes}
                              onChange={(e) => updateField('vas', 'vasVolumes', e.target.value)}
                              placeholder="e.g., 100 units/day for repack, 50 kits/day..."
                              className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                            />
                          </div>
                        </>
                      )}
                    </div>
                  </details>

                  {/* Systems Subsection */}
                  <details open className="bg-white/5 rounded-xl p-4">
                    <summary className="cursor-pointer flex items-center gap-2 mb-3">
                      <span className="px-2 py-1 bg-white/10 rounded text-xs font-mono">F</span>
                      <strong className="text-sm">Systems & Integration</strong>
                    </summary>
                    <div className="space-y-4 pt-2">
                      <div>
                        <label className="block text-sm text-gray-300 mb-2">
                          WMS System
                        </label>
                        <select
                          value={formData.systems.wms}
                          onChange={(e) => updateField('systems', 'wms', e.target.value)}
                          className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white focus:border-blue-400 focus:outline-none"
                        >
                          <option value="">Select WMS</option>
                          <option value="Flex WMS">Flex WMS</option>
                          <option value="SAP WM">SAP WM</option>
                          <option value="Oracle WMS">Oracle WMS</option>
                          <option value="Manhattan">Manhattan</option>
                          <option value="HighJump">HighJump</option>
                          <option value="Other">Other</option>
                          <option value="None">None / Manual</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm text-gray-300 mb-2">
                          System Requirements
                        </label>
                        <textarea
                          value={formData.systems.systemReq}
                          onChange={(e) => updateField('systems', 'systemReq', e.target.value)}
                          placeholder="Describe any special system integration requirements, EDI needs, API requirements, etc..."
                          rows={4}
                          className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                        />
                      </div>
                    </div>
                  </details>
                </div>
              </motion.details>

              {/* Section III: KPIs & Reporting */}
              <motion.details
                open={activeSection === 'III'}
                onToggle={(e) => setActiveSection(e.currentTarget.open ? 'III' : '')}
                className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden"
              >
                <summary className="p-4 cursor-pointer flex items-center justify-between hover:bg-white/5 transition-colors">
                  <div className="flex items-center gap-3">
                    <span className="px-3 py-1 bg-white/10 rounded-full text-xs font-mono">III</span>
                    <strong>KPIs & Reporting Requirements</strong>
                  </div>
                  <span className="text-xl">▾</span>
                </summary>
                <div className="p-4 pt-0 space-y-4">
                  <div className="bg-green-500/20 border border-green-500/30 rounded-lg p-3 text-sm">
                    <strong>KPI Requirements:</strong> Specify what KPIs and reports you need. This helps us structure our service level agreements.
                  </div>
                  <div>
                    <label className="block text-sm text-gray-300 mb-2">
                      KPI & Reporting Requirements
                    </label>
                    <textarea
                      value={formData.kpis}
                      onChange={(e) => updateField('main', 'kpis', e.target.value)}
                      placeholder="Examples: On-time delivery %, Inventory accuracy %, Order fill rate %, Daily/Weekly/Monthly reports, Dashboard access, etc..."
                      rows={6}
                      className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                    />
                  </div>
                </div>
              </motion.details>

              {/* Section IV: Additional Requirements */}
              <motion.details
                open={activeSection === 'IV'}
                onToggle={(e) => setActiveSection(e.currentTarget.open ? 'IV' : '')}
                className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden"
              >
                <summary className="p-4 cursor-pointer flex items-center justify-between hover:bg-white/5 transition-colors">
                  <div className="flex items-center gap-3">
                    <span className="px-3 py-1 bg-white/10 rounded-full text-xs font-mono">IV</span>
                    <strong>Additional Requirements & Attachments</strong>
                  </div>
                  <span className="text-xl">▾</span>
                </summary>
                <div className="p-4 pt-0 space-y-4">
                  <div>
                    <label className="block text-sm text-gray-300 mb-2">
                      Additional Requirements
                    </label>
                    <textarea
                      value={formData.additional}
                      onChange={(e) => updateField('main', 'additional', e.target.value)}
                      placeholder="Any other requirements, special considerations, compliance needs, certifications required, etc..."
                      rows={5}
                      className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-sm text-gray-300 mb-2">
                      Certification & Compliance
                    </label>
                    <textarea
                      value={formData.certify}
                      onChange={(e) => updateField('main', 'certify', e.target.value)}
                      placeholder="Required certifications (ISO, HACCP, etc.), compliance requirements, audit requirements..."
                      rows={4}
                      className="w-full px-4 py-2 bg-gray-900/50 border border-white/20 rounded-xl text-white placeholder-gray-500 focus:border-blue-400 focus:outline-none"
                    />
                  </div>
                  
                  {/* File Attachments */}
                  <div className="bg-indigo-500/20 border border-indigo-500/30 rounded-xl p-4">
                    <div className="flex items-center justify-between mb-3">
                      <label className="block text-sm font-semibold text-gray-300">
                        Attachments
                      </label>
                      <label className="px-4 py-2 bg-indigo-500/30 border border-indigo-500/50 rounded-lg text-sm cursor-pointer hover:bg-indigo-500/40 transition-colors flex items-center gap-2">
                        <i className="ri-upload-line" />
                        Upload Files
                        <input
                          type="file"
                          multiple
                          onChange={handleFileUpload}
                          className="hidden"
                          accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png"
                        />
                      </label>
                    </div>
                    {attachments.length > 0 ? (
                      <div className="space-y-2">
                        {attachments.map((file, index) => (
                          <div key={index} className="flex items-center justify-between bg-white/5 rounded-lg p-2 text-sm">
                            <div className="flex items-center gap-2 flex-1 min-w-0">
                              <i className="ri-file-line text-gray-400" />
                              <span className="truncate text-gray-300">{file.name}</span>
                              <span className="text-xs text-gray-500">
                                ({(file.size / 1024).toFixed(1)} KB)
                              </span>
                            </div>
                            <button
                              onClick={() => handleRemoveAttachment(index)}
                              className="px-2 py-1 text-red-400 hover:text-red-300 transition-colors"
                            >
                              <i className="ri-close-line" />
                            </button>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="text-sm text-gray-400 text-center py-4">
                        No attachments yet. Click "Upload Files" to add documents.
                      </div>
                    )}
                  </div>
                </div>
              </motion.details>
            </div>

            {/* Live Intelligence Sidebar */}
            <div className="lg:col-span-1">
              <div className="sticky top-6 bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 space-y-6">
                <div>
                  <h2 className="text-lg font-bold mb-2">Live Pricing Intelligence</h2>
                  <p className="text-sm text-gray-400">
                    As you fill the form, the portal estimates readiness, assumptions, and key cost drivers.
                  </p>
                </div>

                {analysis && (
                  <>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-white/5 rounded-xl p-4">
                        <div className="text-xs text-gray-400 mb-1">Data completeness</div>
                        <div className="text-2xl font-bold">{analysis.completeness}%</div>
                      </div>
                      <div className="bg-white/5 rounded-xl p-4">
                        <div className="text-xs text-gray-400 mb-1">Pricing confidence</div>
                        <div className="text-lg font-semibold">{analysis.confidence}</div>
                      </div>
                    </div>

                    <div className="bg-orange-500/20 border border-orange-500/30 rounded-xl p-4">
                      <div className="flex items-center justify-between mb-2">
                        <strong>Readiness badge</strong>
                        <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getBadgeColor(analysis.badge)}`}>
                          {analysis.badge}
                        </span>
                      </div>
                      <div className="text-xs text-gray-300 mt-2">
                        <span className="text-green-400">Green</span> = price confidently •{' '}
                        <span className="text-yellow-400">Amber</span> = price with assumptions •{' '}
                        <span className="text-red-400">Red</span> = major gaps
                      </div>
                    </div>

                    <div>
                      <div className="text-sm font-semibold mb-3">Key drivers detected</div>
                      <div className="space-y-2 text-sm">
                        <div className="flex justify-between">
                          <span className="text-gray-400">Storage size basis</span>
                          <span className="font-mono">{analysis.keyDrivers.storage}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gray-400">Handling intensity</span>
                          <span className="font-mono">{analysis.keyDrivers.handling}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gray-400">Pick complexity</span>
                          <span className="font-mono">{analysis.keyDrivers.pick}</span>
                        </div>
                      </div>
                    </div>

                    <div>
                      <div className="text-sm font-semibold mb-2">Assumptions (auto-generated)</div>
                      <div className="text-xs text-gray-400 space-y-1 max-h-32 overflow-y-auto">
                        {analysis.assumptions.length > 0 ? (
                          analysis.assumptions.map((a, i) => <div key={i}>• {a}</div>)
                        ) : (
                          <div className="text-green-400">No major assumptions detected</div>
                        )}
                      </div>
                    </div>
                  </>
                )}

                {/* Intelligence Recommendations */}
                {intelligence && intelligence.recommendations && intelligence.recommendations.length > 0 && (
                  <div className="bg-purple-500/20 border border-purple-500/30 rounded-xl p-4">
                    <div className="text-sm font-semibold mb-3 flex items-center gap-2">
                      <i className="ri-lightbulb-flash-line" />
                      Smart Recommendations
                    </div>
                    <div className="space-y-2 max-h-64 overflow-y-auto">
                      {intelligence.recommendations.slice(0, 5).map((rec: any, i: number) => (
                        <div key={i} className="bg-white/5 rounded-lg p-2 text-xs">
                          <div className="flex items-start justify-between gap-2">
                            <div className="flex-1">
                              <div className="font-semibold text-white mb-1">{rec.title}</div>
                              <div className="text-gray-400">{rec.description}</div>
                              {rec.impact && (
                                <div className="text-purple-300 mt-1 text-[10px]">💡 {rec.impact}</div>
                              )}
                            </div>
                            <span className={`px-2 py-1 rounded text-[10px] ${
                              rec.priority === 'high' ? 'bg-red-500/30 text-red-300' :
                              rec.priority === 'medium' ? 'bg-yellow-500/30 text-yellow-300' :
                              'bg-blue-500/30 text-blue-300'
                            }`}>
                              {rec.priority}
                            </span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Risk Predictions */}
                {intelligence && intelligence.riskPredictions && intelligence.riskPredictions.length > 0 && (
                  <div className="bg-red-500/20 border border-red-500/30 rounded-xl p-4">
                    <div className="text-sm font-semibold mb-3 flex items-center gap-2">
                      <i className="ri-alert-line" />
                      Risk Factors
                    </div>
                    <div className="space-y-2">
                      {intelligence.riskPredictions.slice(0, 3).map((risk: any, i: number) => (
                        <div key={i} className="bg-white/5 rounded-lg p-2 text-xs">
                          <div className="font-semibold text-white mb-1">{risk.description}</div>
                          {risk.mitigation && risk.mitigation.length > 0 && (
                            <div className="text-gray-400 mt-1">
                              <div className="text-[10px] mb-1">Mitigation:</div>
                              {risk.mitigation.slice(0, 2).map((m: string, j: number) => (
                                <div key={j} className="text-[10px]">• {m}</div>
                              ))}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Estimated Value & Success Probability */}
                {intelligence && (
                  <div className="grid grid-cols-2 gap-4">
                    {intelligence.estimatedValue && (
                      <div className="bg-white/5 rounded-xl p-4">
                        <div className="text-xs text-gray-400 mb-1">Estimated Value</div>
                        <div className="text-lg font-bold">
                          {new Intl.NumberFormat('en-SA', { style: 'currency', currency: 'SAR', maximumFractionDigits: 0 }).format(intelligence.estimatedValue)}
                        </div>
                      </div>
                    )}
                    {intelligence.successProbability !== undefined && (
                      <div className="bg-white/5 rounded-xl p-4">
                        <div className="text-xs text-gray-400 mb-1">Success Probability</div>
                        <div className="text-lg font-bold">
                          {(intelligence.successProbability * 100).toFixed(0)}%
                        </div>
                      </div>
                    )}
                  </div>
                )}

                {/* Progress Bar */}
                <div>
                  <div className="text-sm text-gray-400 mb-2 flex items-center justify-between">
                    <span>Completion</span>
                    <span className="font-semibold">{analysis?.completeness || 0}%</span>
                  </div>
                  <div className="w-full h-3 bg-white/10 rounded-full overflow-hidden">
                    <motion.div
                      className="h-full bg-gradient-to-r from-orange-500 via-blue-400 to-purple-500"
                      initial={{ width: 0 }}
                      animate={{ width: `${analysis?.completeness || 0}%` }}
                      transition={{ duration: 0.5 }}
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

/**
 * RFI Creation - Wizard Style UI
 * Step-by-step guided form with progress tracking
 */

'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useRouter } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import ProposalErrorBoundary from '@/components/proposals/ProposalErrorBoundary'
import { useAuth } from '@/contexts/AuthContext'

const STEPS = [
  { id: 'contact', title: 'Contact Info', icon: 'ri-user-line' },
  { id: 'storage', title: 'Storage', icon: 'ri-building-4-line' },
  { id: 'inbound', title: 'Inbound', icon: 'ri-arrow-down-line' },
  { id: 'outbound', title: 'Outbound', icon: 'ri-arrow-up-line' },
  { id: 'services', title: 'Services', icon: 'ri-service-line' },
  { id: 'review', title: 'Review', icon: 'ri-check-line' },
]

export default function RFIWizardPage() {
  const router = useRouter()
  const { hasModuleAccess, canPerformAction } = useAuth()
  const [currentStep, setCurrentStep] = useState(0)
  const [formData, setFormData] = useState<any>({})

  // Permission check
  const hasAccess = hasModuleAccess('proposals-rfq', 'read_only')
  const canCreate = canPerformAction('proposals-rfq', 'proposals-rfq.rfi', undefined, 'write')

  const nextStep = () => {
    if (currentStep < STEPS.length - 1) {
      setCurrentStep(currentStep + 1)
    }
  }

  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1)
    }
  }

  const progress = ((currentStep + 1) / STEPS.length) * 100

  if (!hasAccess || !canCreate) {
    return (
      <PageTemplate
        title="Access Denied"
        description="You do not have permission to create RFIs"
        icon="ri-error-warning-line"
      >
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="text-center max-w-md">
            <div className="w-16 h-16 rounded-full bg-red-100 dark:bg-red-900/30 flex items-center justify-center mx-auto mb-4">
              <i className="ri-error-warning-fill text-3xl text-red-600 dark:text-red-400" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
              Access Denied
            </h3>
            <p className="text-gray-600 dark:text-gray-400">
              You do not have the required permissions to create RFIs. Please contact your administrator.
            </p>
          </div>
        </div>
      </PageTemplate>
    )
  }

  return (
    <ProposalErrorBoundary>
      <PageTemplate
        title="New RFI (Wizard)"
        description="Guided step-by-step RFI creation"
        icon="ri-file-add-line"
        actions={
          <Link
            href="/proposals/rfi/new"
            className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-all text-sm flex items-center gap-2"
          >
            <i className="ri-settings-3-line" />
            Advanced Mode
          </Link>
        }
      >
        <div className="max-w-4xl mx-auto">
        {/* Progress Bar */}
        <div className="mb-8">
          <div className="flex items-center justify-between mb-4">
            {STEPS.map((step, index) => (
              <div key={step.id} className="flex items-center flex-1">
                <div className="flex flex-col items-center flex-1">
                  <div
                    className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${
                      index <= currentStep
                        ? 'bg-blue-600 text-white'
                        : 'bg-gray-200 dark:bg-gray-700 text-gray-500'
                    }`}
                  >
                    <i className={`${step.icon} text-xl`} />
                  </div>
                  <span className="mt-2 text-sm font-medium text-gray-700 dark:text-gray-300">
                    {step.title}
                  </span>
                </div>
                {index < STEPS.length - 1 && (
                  <div
                    className={`h-1 flex-1 mx-2 transition-all ${
                      index < currentStep ? 'bg-blue-600' : 'bg-gray-200 dark:bg-gray-700'
                    }`}
                  />
                )}
              </div>
            ))}
          </div>
          <div className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
            <motion.div
              className="h-full bg-gradient-to-r from-blue-600 to-purple-600"
              initial={{ width: 0 }}
              animate={{ width: `${progress}%` }}
              transition={{ duration: 0.3 }}
            />
          </div>
        </div>

        {/* Step Content */}
        <AnimatePresence mode="wait">
          <motion.div
            key={currentStep}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-8"
          >
            <h2 className="text-2xl font-bold mb-6">{STEPS[currentStep].title}</h2>
            
            {/* Step-specific content would go here */}
            <div className="space-y-4">
              <p className="text-gray-600 dark:text-gray-400">
                Step {currentStep + 1} content for {STEPS[currentStep].title}
              </p>
            </div>

            {/* Navigation */}
            <div className="flex justify-between mt-8">
              <button
                onClick={prevStep}
                disabled={currentStep === 0}
                className="px-6 py-2 bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg disabled:opacity-50"
              >
                Previous
              </button>
              {currentStep < STEPS.length - 1 ? (
                <button
                  onClick={nextStep}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                >
                  Next
                </button>
              ) : (
                <button
                  onClick={() => router.push('/proposals/rfi')}
                  className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                >
                  Submit
                </button>
              )}
            </div>
          </motion.div>
        </AnimatePresence>
        </div>
      </PageTemplate>
    </ProposalErrorBoundary>
  )
}

