'use client'

import { useState, useEffect } from 'react'
import PageTemplate from '@/components/PageTemplate'
import type { LeaderboardEntry } from '@/types/pulse'

export default function PulseLeaderboardsPage() {
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([])
  const [loading, setLoading] = useState(true)
  const [scope, setScope] = useState<'team' | 'site' | 'company'>('team')
  const [period, setPeriod] = useState<'today' | 'week' | 'month'>('week')

  useEffect(() => {
    fetchLeaderboard()
  }, [scope, period])

  const fetchLeaderboard = async () => {
    try {
      const res = await fetch(`/api/pulse/leaderboard?scope=${scope}&period=${period}`, {
        credentials: 'include',
      })
      const data = await res.json()
      if (data.success) {
        setLeaderboard(data.data)
      }
    } catch (error) {
      console.error('Failed to fetch leaderboard:', error)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <PageTemplate
        title="Leaderboards"
        description="See how you rank against your team, site, or company"
        icon="ri-trophy-line"
      >
        <div className="flex items-center justify-center h-64">
          <div className="text-gray-500">Loading...</div>
        </div>
      </PageTemplate>
    )
  }

  return (
    <PageTemplate
      title="Leaderboards"
      description="See how you rank against your team, site, or company"
      icon="ri-trophy-line"
    >
      <div className="space-y-6">
        {/* Filters */}
        <div className="flex gap-4">
          <select
            value={scope}
            onChange={(e) => setScope(e.target.value as any)}
