                        <span className="text-sm">{entry.participationRate}%</span>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </PageTemplate>
  )
}

'use client'

import { useState, useMemo, useEffect } from 'react'
import { motion } from 'framer-motion'
import { useRouter } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import Tooltip from '@/components/Tooltip'
import Modal from '@/components/Modal'
import ModuleLinks from '@/components/ModuleLinks'
import { generatePurchaseOrders, generateVendorMaster } from '@/utils/mockDataGenerators'
import { getPurchaseOrderLinks } from '@/utils/moduleInterconnectivity'
import { format, differenceInDays } from 'date-fns'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer, LineChart, Line, ComposedChart, Area, AreaChart } from 'recharts'
import CurrencyDisplay from '@/components/CurrencyDisplay'
import { useCurrency } from '@/contexts/CurrencyContext'
import ExportButton from '@/components/ExportButton'
import { realtimeSimulator, simulateKPIUpdates } from '@/utils/realtimeDataSimulator'
import UniversalQRGenerator from '@/components/qr/UniversalQRGenerator'
import QRCodeBadge from '@/components/qr/QRCodeBadge'

interface PurchaseOrder {
  id: string
  poNumber: string
  vendorNumber: string
  vendorName: string
  orderDate: Date | string
  expectedDeliveryDate: Date | string
  status: 'CREATED' | 'PENDING_APPROVAL' | 'APPROVED' | 'CONFIRMED' | 'PARTIALLY_RECEIVED' | 'RECEIVED' | 'COMPLETED' | 'CANCELLED'
  totalValue: number
  currency: string
  totalItems: number
  totalQuantity: number
  items: Array<{
    materialNumber: string
    quantity: number
    unit: string
    price: number
  }>
  approvalStatus?: 'PENDING' | 'APPROVED' | 'REJECTED'
  approvedBy?: string
  approvedDate?: Date | string
  receivedQuantity?: number
  receivedValue?: number
}

export default function PurchaseOrders() {
  const router = useRouter()
  const { currencyInfo } = useCurrency()
  const [orders, setOrders] = useState<PurchaseOrder[]>(() => {
    const baseOrders = generatePurchaseOrders(60)
    return baseOrders.map(order => ({
      ...order,
      status: ['CREATED', 'PENDING_APPROVAL', 'APPROVED', 'CONFIRMED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'COMPLETED'][Math.floor(Math.random() * 7)] as PurchaseOrder['status'],
      approvalStatus: ['PENDING', 'APPROVED', 'REJECTED'][Math.floor(Math.random() * 3)] as 'PENDING' | 'APPROVED' | 'REJECTED',
      approvedBy: Math.random() > 0.5 ? 'Manager Name' : undefined,
      approvedDate: Math.random() > 0.5 ? new Date() : undefined,
      receivedQuantity: Math.random() * order.totalQuantity,
      receivedValue: Math.random() * order.totalValue,
    }))
  })
  const [vendors] = useState(() => generateVendorMaster(30))
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedStatus, setSelectedStatus] = useState<string>('ALL')
  const [selectedVendor, setSelectedVendor] = useState<string>('ALL')
  const [viewMode, setViewMode] = useState<'table' | 'analytics' | 'workflow'>('table')
  const [showViewModal, setShowViewModal] = useState(false)
  const [showApprovalModal, setShowApprovalModal] = useState(false)
  const [showReceiveModal, setShowReceiveModal] = useState(false)
  const [selectedOrder, setSelectedOrder] = useState<PurchaseOrder | null>(null)
  const [realTimeEnabled, setRealTimeEnabled] = useState(true)
  const [realTimeStats, setRealTimeStats] = useState({
    totalOrders: 0,
    pendingApproval: 0,
    overdue: 0,
    totalValue: 0,
  })

  const filteredOrders = useMemo(() => {
    return orders.filter((order) => {
      const matchesSearch =
        order.poNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
        order.vendorName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        order.vendorNumber.toLowerCase().includes(searchQuery.toLowerCase())
      const matchesStatus = selectedStatus === 'ALL' || order.status === selectedStatus
      const matchesVendor = selectedVendor === 'ALL' || order.vendorNumber === selectedVendor
      return matchesSearch && matchesStatus && matchesVendor
    })
  }, [orders, searchQuery, selectedStatus, selectedVendor])

  const statusDistribution = useMemo(() => {
    const statusCounts: Record<string, number> = {}
    orders.forEach(order => {
      statusCounts[order.status] = (statusCounts[order.status] || 0) + 1
    })
    return Object.entries(statusCounts).map(([status, count]) => ({ status, count }))
  }, [orders])

  const vendorPerformance = useMemo(() => {
    const vendorStats: Record<string, { orders: number; totalValue: number; avgDeliveryTime: number }> = {}
    orders.forEach(order => {
      if (!vendorStats[order.vendorNumber]) {
        vendorStats[order.vendorNumber] = { orders: 0, totalValue: 0, avgDeliveryTime: 0 }
      }
      vendorStats[order.vendorNumber].orders++
      vendorStats[order.vendorNumber].totalValue += order.totalValue
    })
    return Object.entries(vendorStats)
      .map(([vendor, stats]) => ({
        vendor: vendors.find(v => v.vendorNumber === vendor)?.vendorName || vendor,
        ...stats
      }))
      .sort((a, b) => b.totalValue - a.totalValue)
      .slice(0, 10)
  }, [orders, vendors])

  const pendingApprovals = useMemo(() => {
    return orders.filter(o => o.status === 'PENDING_APPROVAL' || o.approvalStatus === 'PENDING').length
  }, [orders])

  const overdueOrders = useMemo(() => {
    const now = new Date()
    return orders.filter(o => {
      if (!o.expectedDeliveryDate) return false
      return new Date(o.expectedDeliveryDate) < now && !['COMPLETED', 'CANCELLED'].includes(o.status)
    }).length
  }, [orders])

  const aggregateStats = useMemo(() => {
    return {
      totalOrders: orders.length,
      pendingApproval: pendingApprovals,
      overdue: overdueOrders,
      totalValue: orders.reduce((sum, o) => sum + o.totalValue, 0),
    }
  }, [orders.length, pendingApprovals, overdueOrders, orders])

  useEffect(() => {
    if (!realTimeEnabled) return

    const unsubscribe = realtimeSimulator.subscribe('purchase-orders-stats', (data: typeof realTimeStats) => {
      setRealTimeStats(data)
    })

    const stop = realtimeSimulator.start('purchase-orders-stats', () => ({
      totalOrders: aggregateStats.totalOrders,
      pendingApproval: simulateKPIUpdates(aggregateStats.pendingApproval, 0.1),
      overdue: simulateKPIUpdates(aggregateStats.overdue, 0.1),
      totalValue: simulateKPIUpdates(aggregateStats.totalValue, 0.02),
    }), 5000, true)

    return () => {
      unsubscribe()
      stop()
    }
  }, [realTimeEnabled, aggregateStats.totalOrders, aggregateStats.pendingApproval, aggregateStats.overdue, aggregateStats.totalValue])

  const stats = [
    {
      label: 'Total Orders',
      value: realTimeEnabled ? realTimeStats.totalOrders : aggregateStats.totalOrders,
      icon: 'ri-file-list-3-line',
      tooltip: 'Total purchase orders',
      trend: 'up' as const,
    },
    {
      label: 'Pending Approval',
      value: realTimeEnabled ? realTimeStats.pendingApproval : aggregateStats.pendingApproval,
      icon: 'ri-time-line',
      tooltip: 'Orders awaiting approval',
      trend: (realTimeEnabled ? realTimeStats.pendingApproval : aggregateStats.pendingApproval) > 0 ? 'down' as const : 'neutral' as const,
    },
    {
      label: 'Overdue',
      value: realTimeEnabled ? realTimeStats.overdue : aggregateStats.overdue,
      icon: 'ri-alarm-warning-line',
      tooltip: 'Overdue orders',
      trend: (realTimeEnabled ? realTimeStats.overdue : aggregateStats.overdue) > 0 ? 'down' as const : 'neutral' as const,
    },
    {
      label: 'Total Value',
      value: realTimeEnabled ? realTimeStats.totalValue : aggregateStats.totalValue,
      icon: 'ri-money-dollar-circle-line',
      tooltip: 'Total purchase order value',
      trend: 'up' as const,
      isCurrency: true,
    },
  ]

  const handleView = (order: PurchaseOrder) => {
    setSelectedOrder(order)
    setShowViewModal(true)
  }

  const handleApproval = (order: PurchaseOrder) => {
    setSelectedOrder(order)
    setShowApprovalModal(true)
  }

  const handleReceive = (order: PurchaseOrder) => {
    setSelectedOrder(order)
    setShowReceiveModal(true)
  }

  const handleNavigateToGR = (order: PurchaseOrder) => {
    router.push(`/goods-receipt?po=${order.poNumber}`)
  }

  const handleNavigateToVendor = (order: PurchaseOrder) => {
    router.push(`/vendors?vendor=${order.vendorNumber}`)
  }

  const approveOrder = () => {
    if (selectedOrder) {
      setOrders(prev => prev.map(o => 
        o.id === selectedOrder.id 
          ? { ...o, status: 'APPROVED', approvalStatus: 'APPROVED', approvedBy: 'Current User', approvedDate: new Date() }
          : o
      ))
      setShowApprovalModal(false)
      setSelectedOrder(null)
    }
  }

  return (
    <PageTemplate
      title="Purchase Orders"
      description="Purchase order management with full workflow - Create, approve, track, and receive purchase orders with vendor performance analytics"
      icon="ri-shopping-bag-3-line"
      systemInfo={{
        sap: 'ME21N - Create PO, ME22N - Change PO, ME23N - Display PO, ME29N - Approve PO',
        oracle: 'Purchase Order, PO Management, Requisition',
        manhattan: 'Purchase Order Management, Procurement',
      }}
      examples={[
        'Create purchase orders',
        'Approve/reject orders',
        'Track order status',
        'Receive goods against PO',
        'Monitor vendor performance',
        'Handle order changes',
        'GR integration',
      ]}
      stats={stats}
      actions={
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 sm:gap-3">
          <div className="flex items-center gap-1 sm:gap-2 bg-white/5 border border-white/10 rounded-lg p-1 sm:p-2">
            {(['table', 'analytics', 'workflow'] as const).map((mode) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`p-1.5 sm:p-2 rounded transition-colors ${
                  viewMode === mode
                    ? 'bg-cyan-500/20 text-cyan-400'
                    : 'text-[#9ca3af] hover:text-white'
                }`}
                title={`${mode.charAt(0).toUpperCase() + mode.slice(1)} View`}
              >
                <i className={`ri-${mode === 'table' ? 'table-line' : mode === 'analytics' ? 'bar-chart-line' : 'flow-chart-line'} text-sm sm:text-base`}></i>
              </button>
            ))}
          </div>
          <button
            onClick={() => setRealTimeEnabled(!realTimeEnabled)}
            className={`px-3 sm:px-4 py-2 rounded-lg text-xs sm:text-sm font-medium transition-colors ${
              realTimeEnabled
                ? 'bg-green-500/20 text-green-400 border border-green-500/30'
                : 'bg-white/5 text-[#9ca3af] border border-white/10'
            }`}
          >
            <i className={`ri-${realTimeEnabled ? 'radio-button-line' : 'checkbox-blank-circle-line'} mr-1`}></i>
            Real-time
          </button>
          <button className="bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white px-4 sm:px-6 py-2 sm:py-3 rounded-lg text-xs sm:text-sm font-medium transition-colors flex items-center gap-2 shadow-lg shadow-cyan-500/20">
            <i className="ri-add-line"></i>
            <span className="hidden sm:inline">Create PO</span>
          </button>
        </div>
      }
    >
      {/* Alerts */}
      {(pendingApprovals > 0 || overdueOrders > 0) && (
        <div className="mb-6 space-y-2">
          {pendingApprovals > 0 && (
            <div className="bg-yellow-500/20 border border-yellow-500/30 rounded-lg p-4 flex items-center gap-3">
              <i className="ri-time-line text-yellow-400 text-xl"></i>
              <div className="flex-1">
                <div className="text-yellow-400 font-medium">{pendingApprovals} Order{pendingApprovals > 1 ? 's' : ''} Pending Approval</div>
                <div className="text-yellow-300/80 text-sm">Requires immediate attention</div>
              </div>
            </div>
          )}
          {overdueOrders > 0 && (
            <div className="bg-red-500/20 border border-red-500/30 rounded-lg p-4 flex items-center gap-3">
              <i className="ri-alarm-warning-line text-red-400 text-xl"></i>
              <div className="flex-1">
                <div className="text-red-400 font-medium">{overdueOrders} Overdue Order{overdueOrders > 1 ? 's' : ''}</div>
                <div className="text-red-300/80 text-sm">Follow up with vendors required</div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Analytics View */}
      {viewMode === 'analytics' && (
        <div className="grid md:grid-cols-2 gap-6 mb-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6"
          >
            <h3 className="text-lg font-semibold text-white mb-4">Order Status Distribution</h3>
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={statusDistribution}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={({ status, count }) => `${status}: ${count}`}
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="count"
                >
                  {statusDistribution.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={['#10b981', '#3b82f6', '#f59e0b', '#ef4444', '#8b5cf6'][index % 5]} />
                  ))}
                </Pie>
                <RechartsTooltip />
              </PieChart>
            </ResponsiveContainer>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6"
          >
            <h3 className="text-lg font-semibold text-white mb-4">Top 10 Vendors by Value</h3>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={vendorPerformance} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                <XAxis type="number" stroke="#9ca3af" fontSize={12} />
                <YAxis dataKey="vendor" type="category" stroke="#9ca3af" fontSize={12} width={150} />
                <RechartsTooltip
                  contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                  labelStyle={{ color: '#fff' }}
                />
                <Bar dataKey="totalValue" fill="#06b6d4" name={`Total Value (${currencyInfo.code})`} />
              </BarChart>
            </ResponsiveContainer>
          </motion.div>
        </div>
      )}

      {/* Workflow View */}
      {viewMode === 'workflow' && (
        <div className="mb-6 bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6">
          <h3 className="text-lg font-semibold text-white mb-4">Purchase Order Workflow</h3>
          <div className="flex items-center justify-between">
            {['CREATED', 'PENDING_APPROVAL', 'APPROVED', 'CONFIRMED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'COMPLETED'].map((status, index) => (
              <div key={status} className="flex items-center flex-1">
                <div className="flex flex-col items-center flex-1">
                  <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 ${
                    index === 0 ? 'bg-cyan-500 border-cyan-500' :
                    index === 1 ? 'bg-yellow-500 border-yellow-500' :
                    index === 2 ? 'bg-green-500 border-green-500' :
                    'bg-gray-500 border-gray-500'
                  }`}>
                    <i className="ri-check-line text-white"></i>
                  </div>
                  <div className="text-xs text-white mt-2 text-center">{status.replace(/_/g, ' ')}</div>
                  <div className="text-xs text-[#9ca3af] mt-1">
                    {orders.filter(o => o.status === status).length}
                  </div>
                </div>
                {index < 6 && (
                  <div className={`h-0.5 flex-1 mx-2 ${
                    index < 2 ? 'bg-cyan-500' : 'bg-gray-500'
                  }`}></div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="mb-6 flex items-center gap-4 flex-wrap">
        <div className="relative flex-1 min-w-[300px] max-w-md">
          <i className="ri-search-line absolute left-3 top-1/2 -translate-y-1/2 text-[#9ca3af] text-sm"></i>
          <input
            type="text"
            placeholder="Search by PO Number, Vendor..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-white/5 border border-white/10 rounded-lg pl-10 pr-4 py-2.5 text-sm text-white placeholder-[#6b7280] focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 transition-all"
          />
        </div>
        <select
          value={selectedStatus}
          onChange={(e) => setSelectedStatus(e.target.value)}
          className="bg-white/5 border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 min-w-[180px]"
        >
          <option value="ALL">All Status</option>
          <option value="CREATED">Created</option>
          <option value="PENDING_APPROVAL">Pending Approval</option>
          <option value="APPROVED">Approved</option>
          <option value="CONFIRMED">Confirmed</option>
          <option value="PARTIALLY_RECEIVED">Partially Received</option>
          <option value="RECEIVED">Received</option>
          <option value="COMPLETED">Completed</option>
        </select>
        <select
          value={selectedVendor}
          onChange={(e) => setSelectedVendor(e.target.value)}
          className="bg-white/5 border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 min-w-[200px]"
        >
          <option value="ALL">All Vendors</option>
          {vendors.slice(0, 20).map(vendor => (
            <option key={vendor.vendorNumber} value={vendor.vendorNumber}>
              {vendor.vendorName}
            </option>
          ))}
        </select>
      </div>

      {/* Orders Table */}
      {viewMode === 'table' && (
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden">
          <div className="p-4 border-b border-white/10 flex items-center justify-between">
            <h3 className="text-lg font-semibold text-white">Purchase Orders</h3>
            <ExportButton
              data={filteredOrders.map(order => ({
                poNumber: order.poNumber,
                vendorName: order.vendorName,
                vendorNumber: order.vendorNumber,
                orderDate: format(new Date(order.orderDate), 'yyyy-MM-dd'),
                expectedDeliveryDate: format(new Date(order.expectedDeliveryDate), 'yyyy-MM-dd'),
                status: order.status,
                totalValue: order.totalValue,
                currency: order.currency,
                totalItems: order.totalItems,
                priority: (order as any).priority,
              }))}
              columns={[
                { key: 'poNumber', label: 'PO Number' },
                { key: 'vendorName', label: 'Vendor' },
                { key: 'orderDate', label: 'Order Date' },
                { key: 'expectedDeliveryDate', label: 'Expected Delivery' },
                { key: 'status', label: 'Status' },
                { key: 'totalValue', label: 'Total Value' },
                { key: 'totalItems', label: 'Items' },
              ]}
              filename="purchase-orders"
              title="Purchase Orders"
            />
          </div>
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-white/5 border-b border-white/10">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">PO Number</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Vendor</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Order Date</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Expected Delivery</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Status</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Total Value</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Progress</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/10">
                {filteredOrders.map((order, index) => {
                  const progress = order.receivedQuantity ? (order.receivedQuantity / order.totalQuantity) * 100 : 0
                  const daysToDelivery = order.expectedDeliveryDate ? differenceInDays(new Date(order.expectedDeliveryDate), new Date()) : null
                  return (
                    <motion.tr
                      key={order.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.02 }}
                      className="hover:bg-white/5 transition-colors"
                    >
                      <td className="px-6 py-4 whitespace-nowrap">
                        <Tooltip content={`PO Number: ${order.poNumber}`} position="right">
                          <span className="text-sm font-medium text-white font-mono cursor-help">
                            {order.poNumber}
                          </span>
                        </Tooltip>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div>
                          <div className="text-sm text-white font-medium">{order.vendorName}</div>
                          <div className="text-xs text-[#9ca3af] font-mono">{order.vendorNumber}</div>
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm text-white">
                          {format(new Date(order.orderDate), 'MMM dd, yyyy')}
                        </div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className={`text-sm font-medium ${
                          daysToDelivery !== null && daysToDelivery < 0 ? 'text-red-400' :
                          daysToDelivery !== null && daysToDelivery < 7 ? 'text-yellow-400' :
                          'text-white'
                        }`}>
                          {format(new Date(order.expectedDeliveryDate), 'MMM dd, yyyy')}
                        </div>
                        {daysToDelivery !== null && (
                          <div className="text-xs text-[#9ca3af]">
                            {daysToDelivery < 0 ? `${Math.abs(daysToDelivery)}d overdue` : `${daysToDelivery}d remaining`}
                          </div>
                        )}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <span className={`px-2 py-1 rounded text-xs font-medium ${
                          order.status === 'COMPLETED' ? 'bg-green-500/20 text-green-400 border border-green-500/30' :
                          order.status === 'APPROVED' || order.status === 'CONFIRMED' ? 'bg-blue-500/20 text-blue-400 border border-blue-500/30' :
                          order.status === 'PENDING_APPROVAL' ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/30' :
                          order.status === 'PARTIALLY_RECEIVED' ? 'bg-purple-500/20 text-purple-400 border border-purple-500/30' :
                          'bg-gray-500/20 text-gray-400 border border-gray-500/30'
                        }`}>
                          {order.status.replace(/_/g, ' ')}
                        </span>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <CurrencyDisplay amount={order.totalValue} size="sm" variant="default" />
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="w-24 bg-white/10 rounded-full h-2">
                          <div
                            className="bg-cyan-500 h-2 rounded-full transition-all"
                            style={{ width: `${Math.min(progress, 100)}%` }}
                          ></div>
                        </div>
                        <div className="text-xs text-[#9ca3af] mt-1">{progress.toFixed(0)}%</div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="flex items-center gap-2">
                          <QRCodeBadge
                            entityId={order.id}
                            entityType="purchase-order"
                            entityName={order.poNumber}
                            documentType="other"
                            documentUrl={`/purchase-orders?po=${order.poNumber}`}
                            module="procurement"
                            size="sm"
                          />
                          <Tooltip content="View Details" position="top">
                            <button
                              onClick={() => handleView(order)}
                              className="p-2 bg-cyan-600/20 text-cyan-400 border border-cyan-500/30 rounded hover:bg-cyan-600/30 transition-colors"
                            >
                              <i className="ri-eye-line"></i>
                            </button>
                          </Tooltip>
                          {order.status === 'PENDING_APPROVAL' && (
                            <Tooltip content="Approve Order" position="top">
                              <button
                                onClick={() => handleApproval(order)}
                                className="p-2 bg-green-600/20 text-green-400 border border-green-500/30 rounded hover:bg-green-600/30 transition-colors"
                              >
                                <i className="ri-check-line"></i>
                              </button>
                            </Tooltip>
                          )}
                          {['APPROVED', 'CONFIRMED', 'PARTIALLY_RECEIVED'].includes(order.status) && (
                            <Tooltip content="Receive Goods (Go to GR)" position="top">
                              <button
                                onClick={() => handleNavigateToGR(order)}
                                className="p-2 bg-blue-600/20 text-blue-400 border border-blue-500/30 rounded hover:bg-blue-600/30 transition-colors"
                              >
                                <i className="ri-inbox-line"></i>
                              </button>
                            </Tooltip>
                          )}
                          <Tooltip content="View Vendor" position="top">
                            <button
                              onClick={() => handleNavigateToVendor(order)}
                              className="p-2 bg-purple-600/20 text-purple-400 border border-purple-500/30 rounded hover:bg-purple-600/30 transition-colors"
                            >
                              <i className="ri-user-line"></i>
                            </button>
                          </Tooltip>
                        </div>
                      </td>
                    </motion.tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* View Details Modal */}
      <Modal
        isOpen={showViewModal}
        onClose={() => {
          setShowViewModal(false)
          setSelectedOrder(null)
        }}
        title={`Purchase Order Details - ${selectedOrder?.poNumber || ''}`}
        size="lg"
      >
        {selectedOrder && (
          <div className="space-y-4">
            {/* QR Code Section */}
            <div className="bg-white/5 rounded-lg p-4 border border-cyan-500/20">
              <UniversalQRGenerator
                entityId={selectedOrder.id}
                entityType="purchase-order"
                entityName={selectedOrder.poNumber}
                documentType="other"
                documentUrl={`/purchase-orders?po=${selectedOrder.poNumber}`}
                module="procurement"
                showAdvanced={false}
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs text-[#9ca3af] mb-1 block">PO Number</label>
                <div className="text-sm text-white font-mono">{selectedOrder.poNumber}</div>
              </div>
              <div>
                <label className="text-xs text-[#9ca3af] mb-1 block">Vendor</label>
                <div className="text-sm text-white">{selectedOrder.vendorName}</div>
                <div className="text-xs text-[#9ca3af] font-mono">{selectedOrder.vendorNumber}</div>
              </div>
              <div>
                <label className="text-xs text-[#9ca3af] mb-1 block">Order Date</label>
                <div className="text-sm text-white">{format(new Date(selectedOrder.orderDate), 'MMM dd, yyyy')}</div>
              </div>
              <div>
                <label className="text-xs text-[#9ca3af] mb-1 block">Expected Delivery</label>
                <div className="text-sm text-white">{format(new Date(selectedOrder.expectedDeliveryDate), 'MMM dd, yyyy')}</div>
              </div>
              <div>
                <label className="text-xs text-[#9ca3af] mb-1 block">Status</label>
                <span className={`px-2 py-1 rounded text-xs font-medium ${
                  selectedOrder.status === 'COMPLETED' ? 'bg-green-500/20 text-green-400' :
                  selectedOrder.status === 'APPROVED' ? 'bg-blue-500/20 text-blue-400' :
                  'bg-yellow-500/20 text-yellow-400'
                }`}>
                  {selectedOrder.status.replace(/_/g, ' ')}
                </span>
              </div>
              <div>
                <label className="text-xs text-[#9ca3af] mb-1 block">Total Value</label>
                <CurrencyDisplay amount={selectedOrder.totalValue} size="sm" variant="default" />
              </div>
            </div>
            <div className="pt-4 border-t border-white/10">
              <label className="text-xs text-[#9ca3af] mb-2 block">Order Items</label>
              <div className="space-y-2">
                {selectedOrder.items.map((item, idx) => (
                  <div key={idx} className="bg-white/5 rounded-lg p-3 flex items-center justify-between">
                    <div>
                      <button
                        onClick={() => router.push(`/inventory?material=${item.materialNumber}`)}
                        className="text-sm text-white font-mono hover:text-cyan-400 transition-colors cursor-pointer"
                      >
                        {item.materialNumber}
                      </button>
                      <div className="text-xs text-[#9ca3af]">Qty: {item.quantity.toFixed(2)} {item.unit}</div>
                    </div>
                    <CurrencyDisplay amount={item.price} size="sm" variant="default" />
                  </div>
                ))}
              </div>
            </div>
            <div className="pt-4 border-t border-white/10">
              <ModuleLinks links={getPurchaseOrderLinks(selectedOrder.poNumber)} />
            </div>
            <div className="flex items-center gap-3 pt-4 border-t border-white/10">
              <button
                onClick={() => handleNavigateToGR(selectedOrder)}
                className="flex-1 px-4 py-2 bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white rounded-lg transition-colors flex items-center justify-center gap-2"
              >
                <i className="ri-inbox-line"></i>
                Go to Goods Receipt
              </button>
              <button
                onClick={() => handleNavigateToVendor(selectedOrder)}
                className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white border border-white/10 rounded-lg transition-colors flex items-center gap-2"
              >
                <i className="ri-user-line"></i>
                View Vendor
              </button>
            </div>
          </div>
        )}
      </Modal>

      {/* Approval Modal */}
      <Modal
        isOpen={showApprovalModal}
        onClose={() => {
          setShowApprovalModal(false)
          setSelectedOrder(null)
        }}
        title={`Approve Purchase Order - ${selectedOrder?.poNumber || ''}`}
        size="md"
      >
        {selectedOrder && (
          <div className="space-y-4">
            <div className="bg-white/5 rounded-lg p-4">
              <div className="text-sm text-white mb-2">Order Value: <span className="font-medium"><CurrencyDisplay amount={selectedOrder.totalValue} size="sm" variant="highlight" /></span></div>
              <div className="text-sm text-white mb-2">Vendor: <span className="font-medium">{selectedOrder.vendorName}</span></div>
              <div className="text-sm text-white">Items: <span className="font-medium">{selectedOrder.totalItems}</span></div>
            </div>
            <div className="flex items-center gap-3 justify-end pt-4 border-t border-white/10">
              <button
                onClick={() => {
                  setShowApprovalModal(false)
                  setSelectedOrder(null)
                }}
                className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={approveOrder}
                className="px-4 py-2 bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 text-white rounded-lg transition-colors"
              >
                Approve Order
              </button>
            </div>
          </div>
        )}
      </Modal>

      {/* Receive Goods Modal */}
      <Modal
        isOpen={showReceiveModal}
        onClose={() => {
          setShowReceiveModal(false)
          setSelectedOrder(null)
        }}
        title={`Receive Goods - ${selectedOrder?.poNumber || ''}`}
        size="lg"
      >
        {selectedOrder && (
          <div className="space-y-4">
            <div className="bg-white/5 rounded-lg p-4">
              <div className="text-sm text-[#9ca3af] mb-1">Expected Quantity</div>
              <div className="text-lg text-white font-medium">{selectedOrder.totalQuantity.toFixed(2)}</div>
            </div>
            <div>
              <label className="text-xs text-[#9ca3af] mb-2 block">Received Quantity</label>
              <input
                type="number"
                max={selectedOrder.totalQuantity}
                className="w-full bg-white/5 border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
                placeholder="Enter received quantity"
              />
            </div>
            <div className="flex items-center gap-3 justify-end pt-4 border-t border-white/10">
              <button
                onClick={() => {
                  setShowReceiveModal(false)
                  setSelectedOrder(null)
                }}
                className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  handleNavigateToGR(selectedOrder)
                  setShowReceiveModal(false)
                  setSelectedOrder(null)
                }}
                className="px-4 py-2 bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white rounded-lg transition-colors"
              >
                Receive Goods
              </button>
            </div>
          </div>
        )}
      </Modal>
    </PageTemplate>
  )
}

/**
 * QHSE Custom Fields Management Page
 * Manage custom fields for QHSE entities
 */

'use client'

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { FiPlus, FiEdit, FiTrash2, FiSave, FiX, FiSettings, FiFileText, FiShield, FiUsers, FiActivity } from 'react-icons/fi'
import CrossModuleLinks from '@/components/qhse/CrossModuleLinks'

interface CustomField {
  id: string
  entityType: 'INCIDENT' | 'INSPECTION' | 'TRAINING' | 'ENVIRONMENTAL' | 'SAFETY' | 'REGULATORY' | 'ESG'
  fieldName: string
  fieldType: 'TEXT' | 'NUMBER' | 'DATE' | 'BOOLEAN' | 'SELECT' | 'MULTI_SELECT'
  label: string
  required: boolean
  options?: string[]
  defaultValue?: string | number | boolean
}

export default function QHSECustomFieldsPage() {
  const [fields, setFields] = useState<CustomField[]>([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'incident' | 'inspection' | 'training' | 'environmental' | 'safety' | 'regulatory' | 'esg'>('incident')
  const [editingField, setEditingField] = useState<CustomField | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)

  useEffect(() => {
    fetchFields()
  }, [activeTab])

  const fetchFields = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/qhse/custom-fields?entityType=${activeTab.toUpperCase()}`)
      const data = await response.json()
      
      if (data.success) {
        setFields(data.data || [])
      }
    } catch (err) {
      console.error('Error fetching custom fields:', err)
    } finally {
      setLoading(false)
    }
  }

  const handleDelete = async (fieldId: string) => {
    if (!confirm('Are you sure you want to delete this custom field?')) return
    
    try {
      const response = await fetch(`/api/qhse/custom-fields/${fieldId}`, {
        method: 'DELETE',
      })
      const data = await response.json()
      
      if (data.success) {
        fetchFields()
      }
    } catch (err) {
      console.error('Error deleting custom field:', err)
    }
  }

  const entityTypes = [
    { id: 'incident', label: 'Incidents', icon: FiActivity },
    { id: 'inspection', label: 'Inspections', icon: FiFileText },
    { id: 'training', label: 'Training', icon: FiUsers },
    { id: 'environmental', label: 'Environmental', icon: FiActivity },
    { id: 'safety', label: 'Safety', icon: FiShield },
    { id: 'regulatory', label: 'Regulatory', icon: FiFileText },
    { id: 'esg', label: 'ESG', icon: FiSettings },
  ]

  if (loading && fields.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading custom fields...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Custom Fields</h1>
          <p className="text-gray-600 mt-1">Manage custom fields for QHSE entities</p>
        </div>
        <button
          onClick={() => setShowAddForm(true)}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2"
        >
          <FiPlus className="w-4 h-4" />
          Add Custom Field
        </button>
      </div>

      {/* Tabs */}
      <div className="bg-white rounded-lg shadow">
        <div className="border-b border-gray-200">
          <nav className="flex -mb-px overflow-x-auto">
            {entityTypes.map((type) => {
              const Icon = type.icon
              const count = fields.filter(f => f.entityType === type.id.toUpperCase()).length
              return (
                <button
                  key={type.id}
                  onClick={() => setActiveTab(type.id as any)}
                  className={`flex items-center gap-2 px-6 py-4 border-b-2 font-medium text-sm whitespace-nowrap ${
                    activeTab === type.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  <Icon className="w-4 h-4" />
                  {type.label}
                  {count > 0 && (
                    <span className="ml-1 px-2 py-0.5 text-xs bg-blue-100 text-blue-800 rounded-full">
                      {count}
                    </span>
                  )}
                </button>
              )
            })}
          </nav>
        </div>

        <div className="p-6">
          {/* Fields List */}
          <div className="space-y-4">
            {fields.filter(f => f.entityType === activeTab.toUpperCase()).length === 0 ? (
              <div className="text-center py-12">
                <FiSettings className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-500 mb-4">No custom fields for {entityTypes.find(t => t.id === activeTab)?.label}</p>
                <button
                  onClick={() => setShowAddForm(true)}
                  className="text-blue-600 hover:text-blue-800"
                >
                  Add your first custom field
                </button>
              </div>
            ) : (
              fields
                .filter(f => f.entityType === activeTab.toUpperCase())
                .map((field) => (
                  <motion.div
                    key={field.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-gray-50 rounded-lg p-4 border border-gray-200"
                  >
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                          <h3 className="font-semibold text-gray-900">{field.label}</h3>
                          <span className={`px-2 py-1 text-xs rounded-full ${
                            field.required ? 'bg-red-100 text-red-800' : 'bg-gray-100 text-gray-800'
                          }`}>
                            {field.required ? 'Required' : 'Optional'}
                          </span>
                          <span className="px-2 py-1 text-xs bg-blue-100 text-blue-800 rounded-full">
                            {field.fieldType.replace(/_/g, ' ')}
                          </span>
                        </div>
                        <p className="text-sm text-gray-600">Field: {field.fieldName}</p>
                        {field.options && field.options.length > 0 && (
                          <p className="text-sm text-gray-500 mt-1">
                            Options: {field.options.join(', ')}
                          </p>
                        )}
                        {field.defaultValue !== undefined && (
                          <p className="text-sm text-gray-500 mt-1">
                            Default: {String(field.defaultValue)}
                          </p>
                        )}
                      </div>
                      <div className="flex gap-2">
                        <button
                          onClick={() => setEditingField(field)}
                          className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"
                        >
                          <FiEdit className="w-4 h-4" />
                        </button>
                        <button
                          onClick={() => handleDelete(field.id)}
                          className="p-2 text-red-600 hover:bg-red-50 rounded-lg"
                        >
                          <FiTrash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </motion.div>
                ))
            )}
          </div>
        </div>
      </div>

      {/* Add/Edit Form Modal */}
      {(showAddForm || editingField) && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white rounded-lg shadow-xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto"
          >
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold text-gray-900">
                {editingField ? 'Edit Custom Field' : 'Add Custom Field'}
              </h2>
              <button
                onClick={() => {
                  setShowAddForm(false)
                  setEditingField(null)
                }}
                className="p-2 hover:bg-gray-100 rounded-lg"
              >
                <FiX className="w-5 h-5" />
              </button>
            </div>
            <div className="space-y-4">
              <form
                onSubmit={async (e) => {
                  e.preventDefault()
                  const formData = new FormData(e.currentTarget)
                  const fieldData = {
                    entityType: (formData.get('entityType') as string).toUpperCase(),
                    fieldName: formData.get('fieldName') as string,
                    fieldType: formData.get('fieldType') as string,
                    label: formData.get('label') as string,
                    required: formData.get('required') === 'true',
                    options: formData.get('options')?.toString().split(',').filter(Boolean) || undefined,
                    defaultValue: formData.get('defaultValue')?.toString() || undefined,
                  }

                  try {
                    const url = editingField
                      ? `/api/qhse/custom-fields/${editingField.id}`
                      : '/api/qhse/custom-fields'
                    const method = editingField ? 'PUT' : 'POST'

                    const response = await fetch(url, {
                      method,
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify(fieldData),
                    })

                    const data = await response.json()
                    if (data.success) {
                      setShowAddForm(false)
                      setEditingField(null)
                      fetchFields()
                    } else {
                      alert(data.error || 'Failed to save custom field')
                    }
                  } catch (err) {
                    console.error('Error saving custom field:', err)
                    alert('Failed to save custom field')
                  }
                }}
                className="space-y-4"
              >
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Entity Type *
                  </label>
                  <select
                    name="entityType"
                    required
                    defaultValue={editingField?.entityType || activeTab}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="INCIDENT">Incident</option>
                    <option value="INSPECTION">Inspection</option>
                    <option value="TRAINING">Training</option>
                    <option value="ENVIRONMENTAL">Environmental</option>
                    <option value="SAFETY">Safety</option>
