/**
 * QHSE Incident Management Page - ENHANCED
 * Comprehensive incident reporting, investigation, and management
 * With tabs, search, filters, charts, and cross-module interconnections
 */

'use client'

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Link from 'next/link'
import { FiSearch, FiFilter, FiDownload, FiPlus, FiTrendingUp, FiTrendingDown, FiAlertTriangle, FiCheckCircle, FiClock, FiLink2, FiBarChart, FiCalendar } from 'react-icons/fi'
import type { Incident } from '@/types/qhse'
import CrossModuleLinks, { CrossModuleLink } from '@/components/qhse/CrossModuleLinks'
import { getQHSEIncidentLinks } from '@/utils/moduleInterconnectivity'
import UniversalQRGenerator from '@/components/qr/UniversalQRGenerator'
import QRCodeBadge from '@/components/qr/QRCodeBadge'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { PremiumLoader } from '@/components/loading'

function QHSEIncidentsPageContent() {
  const [incidents, setIncidents] = useState<Incident[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<'all' | 'open' | 'critical' | 'trends'>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [severityFilter, setSeverityFilter] = useState<string>('all')
  const [statusFilter, setStatusFilter] = useState<string>('all')
  const [showFilters, setShowFilters] = useState(false)
  const [selectedIncident, setSelectedIncident] = useState<Incident | null>(null)

  useEffect(() => {
    fetchIncidents()
  }, [activeTab, severityFilter, statusFilter])

  const fetchIncidents = async () => {
    try {
      setLoading(true)
      let url = '/api/qhse/incidents'
      const params = new URLSearchParams()

      if (activeTab === 'open') {
        params.append('status', 'REPORTED,UNDER_INVESTIGATION,INVESTIGATION_COMPLETE')
      } else if (activeTab === 'critical') {
        params.append('severity', 'CRITICAL,HIGH')
      }

      if (severityFilter !== 'all') {
        params.append('severity', severityFilter)
      }

      if (statusFilter !== 'all') {
        params.append('status', statusFilter)
      }

      if (params.toString()) {
        url += '?' + params.toString()
      }

      const response = await fetch(url)
      const data = await response.json()

      if (data.success) {
        let filtered = data.data || []

        // Apply search filter
        if (searchQuery) {
          filtered = filtered.filter((incident: Incident) =>
            incident.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            incident.incidentNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
            incident.description?.toLowerCase().includes(searchQuery.toLowerCase())
          )
        }

        setIncidents(filtered)
      } else {
        setError(data.error || 'Failed to load incidents')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load incidents')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (searchQuery !== undefined) {
      fetchIncidents()
    }
  }, [searchQuery])

  const getSeverityColor = (severity: Incident['severity']) => {
    switch (severity) {
      case 'CRITICAL': return 'bg-red-100 text-red-800 border-red-300'
      case 'HIGH': return 'bg-orange-100 text-orange-800 border-orange-300'
      case 'MEDIUM': return 'bg-yellow-100 text-yellow-800 border-yellow-300'
      case 'LOW': return 'bg-blue-100 text-blue-800 border-blue-300'
      default: return 'bg-gray-100 text-gray-800 border-gray-300'
    }
  }

  const getStatusColor = (status: Incident['status']) => {
    switch (status) {
      case 'REPORTED': return 'bg-blue-100 text-blue-800'
      case 'UNDER_INVESTIGATION': return 'bg-yellow-100 text-yellow-800'
      case 'INVESTIGATION_COMPLETE': return 'bg-purple-100 text-purple-800'
      case 'CORRECTIVE_ACTION_REQUIRED': return 'bg-orange-100 text-orange-800'
      case 'CLOSED': return 'bg-green-100 text-green-800'
      case 'ARCHIVED': return 'bg-gray-100 text-gray-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getCrossModuleLinks = (incident: Incident): CrossModuleLink[] => {
    const links = getQHSEIncidentLinks(incident.id, {
      materialNumber: incident.materialNumber,
      locationCode: incident.locationCode,
      employeeId: incident.reportedBy,
    })

    return links.map(link => ({
      label: link.label,
      href: link.href,
      description: link.description,
      icon: link.icon,
    }))
  }

  const stats = {
    total: incidents.length,
    open: incidents.filter(i => i.status !== 'CLOSED' && i.status !== 'ARCHIVED').length,
    critical: incidents.filter(i => i.severity === 'CRITICAL').length,
    underInvestigation: incidents.filter(i => i.status === 'UNDER_INVESTIGATION').length,
    closed: incidents.filter(i => i.status === 'CLOSED').length,
    bySeverity: {
      CRITICAL: incidents.filter(i => i.severity === 'CRITICAL').length,
      HIGH: incidents.filter(i => i.severity === 'HIGH').length,
      MEDIUM: incidents.filter(i => i.severity === 'MEDIUM').length,
      LOW: incidents.filter(i => i.severity === 'LOW').length,
    }
  }

  if (loading && incidents.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading incidents...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Incident Management</h1>
          <p className="text-gray-600 mt-1">Report, investigate, and manage safety incidents</p>
        </div>
        <div className="flex gap-2">
          <Link
            href="/qhse/incidents/new"
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2"
          >
            <FiPlus className="w-4 h-4" />
            Report New Incident
          </Link>
          <Link
            href="/qhse/bulk"
            className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 flex items-center gap-2"
          >
            Bulk Operations
          </Link>
          <button className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center gap-2">
            <FiDownload className="w-4 h-4" />
            Export
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Total</p>
              <p className="text-2xl font-bold text-gray-900 mt-1">{stats.total}</p>
            </div>
            <FiAlertTriangle className="w-8 h-8 text-blue-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-orange-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Open</p>
              <p className="text-2xl font-bold text-orange-600 mt-1">{stats.open}</p>
            </div>
            <FiClock className="w-8 h-8 text-orange-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-red-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Critical</p>
              <p className="text-2xl font-bold text-red-600 mt-1">{stats.critical}</p>
            </div>
            <FiAlertTriangle className="w-8 h-8 text-red-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-yellow-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Investigating</p>
              <p className="text-2xl font-bold text-yellow-600 mt-1">{stats.underInvestigation}</p>
            </div>
            <FiClock className="w-8 h-8 text-yellow-500" />
