                    </div>
                    <div className="flex justify-between text-sm">
                      <span>Medium:</span>
                      <span className="font-semibold text-yellow-600">{stats.bySeverity.MEDIUM}</span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span>Low:</span>
