                              View
                            </Link>
                          </div>
                        </td>
                      </motion.tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>

      {/* QR Code & Cross-Module Links */}
      {selectedIncident && (
        <div className="space-y-4">
          <div className="bg-white rounded-lg shadow p-6 border border-cyan-200">
