      {/* Default Cross-Module Links */}
      {!selectedIncident && (
        <CrossModuleLinks
          title="Quick Navigation"
          links={[
            { label: 'QHSE Dashboard', href: '/qhse/dashboard', icon: 'ri-dashboard-3-line', description: 'Overview' },
            { label: 'Inspections', href: '/qhse/inspections', icon: 'ri-clipboard-line', description: 'View inspections' },
