/**
 * QHSE Inspections & Audits Page - ENHANCED
 * Comprehensive inspection scheduling, conducting, and tracking
 * With tabs, calendar integration, checklist builder, and cross-module links
 */

'use client'

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Link from 'next/link'
import { FiSearch, FiFilter, FiDownload, FiPlus, FiCalendar, FiClipboard, FiCheckCircle, FiClock, FiAlertCircle, FiBarChart, FiLink2 } from 'react-icons/fi'
import type { Inspection } from '@/types/qhse'
import CrossModuleLinks, { CrossModuleLink } from '@/components/qhse/CrossModuleLinks'
import { getQHSEInspectionLinks } from '@/utils/moduleInterconnectivity'

export default function QHSEInspectionsPage() {
  const [inspections, setInspections] = useState<Inspection[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<'all' | 'scheduled' | 'completed' | 'overdue' | 'calendar'>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [typeFilter, setTypeFilter] = useState<string>('all')
  const [statusFilter, setStatusFilter] = useState<string>('all')
  const [showFilters, setShowFilters] = useState(false)
  const [selectedInspection, setSelectedInspection] = useState<Inspection | null>(null)

  useEffect(() => {
    fetchInspections()
  }, [activeTab, typeFilter, statusFilter])

  const fetchInspections = async () => {
    try {
      setLoading(true)
      let url = '/api/qhse/inspections'
      const params = new URLSearchParams()
      
      if (activeTab === 'scheduled') {
        params.append('status', 'SCHEDULED')
      } else if (activeTab === 'completed') {
        params.append('status', 'COMPLETED')
      } else if (activeTab === 'overdue') {
        params.append('status', 'OVERDUE')
      }
      
      if (typeFilter !== 'all') {
        params.append('type', typeFilter)
      }
      
      if (statusFilter !== 'all') {
        params.append('status', statusFilter)
      }
      
      if (params.toString()) {
        url += '?' + params.toString()
      }
      
      const response = await fetch(url)
      const data = await response.json()
      
      if (data.success) {
        let filtered = data.data || []
        
        if (searchQuery) {
          filtered = filtered.filter((inspection: Inspection) =>
            inspection.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            inspection.inspectionNumber.toLowerCase().includes(searchQuery.toLowerCase())
          )
        }
        
        setInspections(filtered)
      } else {
        setError(data.error || 'Failed to load inspections')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load inspections')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (searchQuery !== undefined) {
      fetchInspections()
    }
  }, [searchQuery])

  const getStatusColor = (status: Inspection['status']) => {
    switch (status) {
      case 'SCHEDULED': return 'bg-blue-100 text-blue-800'
      case 'IN_PROGRESS': return 'bg-yellow-100 text-yellow-800'
      case 'COMPLETED': return 'bg-green-100 text-green-800'
      case 'CANCELLED': return 'bg-gray-100 text-gray-800'
      case 'OVERDUE': return 'bg-red-100 text-red-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getCrossModuleLinks = (inspection: Inspection): CrossModuleLink[] => {
    const links = getQHSEInspectionLinks(inspection.id, {
      materialNumber: inspection.materialNumber,
      locationCode: inspection.locationCode,
    })
    
    return links.map(link => ({
      label: link.label,
      href: link.href,
      description: link.description,
      icon: link.icon,
    }))
  }

  const stats = {
    total: inspections.length,
    scheduled: inspections.filter(i => i.status === 'SCHEDULED').length,
    completed: inspections.filter(i => i.status === 'COMPLETED').length,
    overdue: inspections.filter(i => i.status === 'OVERDUE').length,
    inProgress: inspections.filter(i => i.status === 'IN_PROGRESS').length,
    avgCompliance: inspections.filter(i => i.complianceScore !== undefined).length > 0
      ? Math.round(
          inspections
            .filter(i => i.complianceScore !== undefined)
            .reduce((sum, i) => sum + (i.complianceScore || 0), 0) /
          inspections.filter(i => i.complianceScore !== undefined).length
        )
      : 0,
  }

  if (loading && inspections.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading inspections...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Inspections & Audits</h1>
          <p className="text-gray-600 mt-1">Schedule, conduct, and track inspections</p>
        </div>
        <div className="flex gap-2">
          <Link
            href="/qhse/inspections/new"
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2"
          >
            <FiPlus className="w-4 h-4" />
            Schedule Inspection
          </Link>
          <Link
            href="/qhse/calendar"
            className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 flex items-center gap-2"
          >
            <FiCalendar className="w-4 h-4" />
            Calendar View
          </Link>
          <button className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center gap-2">
            <FiDownload className="w-4 h-4" />
            Export
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Total</p>
              <p className="text-2xl font-bold text-gray-900 mt-1">{stats.total}</p>
            </div>
            <FiClipboard className="w-8 h-8 text-blue-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Scheduled</p>
              <p className="text-2xl font-bold text-blue-600 mt-1">{stats.scheduled}</p>
            </div>
            <FiCalendar className="w-8 h-8 text-blue-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-green-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Completed</p>
              <p className="text-2xl font-bold text-green-600 mt-1">{stats.completed}</p>
            </div>
            <FiCheckCircle className="w-8 h-8 text-green-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-red-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Overdue</p>
              <p className="text-2xl font-bold text-red-600 mt-1">{stats.overdue}</p>
            </div>
            <FiAlertCircle className="w-8 h-8 text-red-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-yellow-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">In Progress</p>
              <p className="text-2xl font-bold text-yellow-600 mt-1">{stats.inProgress}</p>
            </div>
            <FiClock className="w-8 h-8 text-yellow-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-purple-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Avg Compliance</p>
              <p className="text-2xl font-bold text-purple-600 mt-1">{stats.avgCompliance}%</p>
            </div>
            <FiBarChart className="w-8 h-8 text-purple-500" />
          </div>
        </motion.div>
      </div>

      {/* Tabs */}
      <div className="bg-white rounded-lg shadow">
        <div className="border-b border-gray-200">
          <nav className="flex -mb-px">
            {[
              { id: 'all', label: 'All Inspections', icon: FiBarChart },
              { id: 'scheduled', label: 'Scheduled', icon: FiCalendar },
              { id: 'completed', label: 'Completed', icon: FiCheckCircle },
              { id: 'overdue', label: 'Overdue', icon: FiAlertCircle },
              { id: 'calendar', label: 'Calendar View', icon: FiCalendar },
            ].map((tab) => {
              const Icon = tab.icon
              return (
                <button
                  key={tab.id}
                  onClick={() => {
                    if (tab.id === 'calendar') {
                      window.location.href = '/qhse/calendar'
                    } else {
                      setActiveTab(tab.id as any)
                    }
                  }}
                  className={`flex items-center gap-2 px-6 py-4 border-b-2 font-medium text-sm ${
                    activeTab === tab.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                </button>
              )
            })}
          </nav>
        </div>

        <div className="p-6">
          {/* Search and Filters */}
          <div className="flex gap-4 mb-6">
            <div className="flex-1 relative">
              <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search inspections by title, number, or type..."
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`px-4 py-2 rounded-lg flex items-center gap-2 ${
                showFilters ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700'
              }`}
            >
              <FiFilter className="w-4 h-4" />
              Filters
            </button>
          </div>

          {/* Advanced Filters */}
          <AnimatePresence>
            {showFilters && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="mb-6 p-4 bg-gray-50 rounded-lg border border-gray-200"
              >
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Type</label>
                    <select
                      value={typeFilter}
                      onChange={(e) => setTypeFilter(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    >
                      <option value="all">All Types</option>
                      <option value="SAFETY">Safety</option>
                      <option value="ENVIRONMENTAL">Environmental</option>
                      <option value="QUALITY">Quality</option>
                      <option value="COMPLIANCE">Compliance</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">Status</label>
                    <select
                      value={statusFilter}
                      onChange={(e) => setStatusFilter(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg"
                    >
                      <option value="all">All Statuses</option>
                      <option value="SCHEDULED">Scheduled</option>
                      <option value="IN_PROGRESS">In Progress</option>
                      <option value="COMPLETED">Completed</option>
                      <option value="OVERDUE">Overdue</option>
                    </select>
                  </div>
                  <div className="flex items-end">
                    <button
                      onClick={() => {
                        setTypeFilter('all')
                        setStatusFilter('all')
                        setSearchQuery('')
                      }}
                      className="w-full px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300"
                    >
                      Clear Filters
                    </button>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
              <p className="text-red-800">{error}</p>
            </div>
          )}

          {/* Inspections Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {inspections.length === 0 ? (
              <div className="col-span-full text-center py-12">
                <FiClipboard className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-500 mb-4">No inspections found</p>
                <Link
                  href="/qhse/inspections/new"
                  className="text-blue-600 hover:text-blue-800"
                >
                  Schedule your first inspection
                </Link>
              </div>
            ) : (
              inspections.map((inspection) => (
                <motion.div
                  key={inspection.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-white rounded-lg shadow border border-gray-200 p-6 hover:shadow-lg transition cursor-pointer"
                  onClick={() => setSelectedInspection(inspection)}
                >
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex-1">
                      <h3 className="text-lg font-semibold text-gray-900 mb-1">{inspection.title}</h3>
                      <p className="text-sm text-gray-500">{inspection.inspectionNumber}</p>
                    </div>
                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(inspection.status)}`}>
                      {inspection.status.replace(/_/g, ' ')}
                    </span>
                  </div>
                  
                  <div className="space-y-2 text-sm mb-4">
                    <div className="flex justify-between">
                      <span className="text-gray-500">Type:</span>
                      <span className="text-gray-900 font-medium">{inspection.type.replace(/_/g, ' ')}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-gray-500">Scheduled:</span>
                      <span className="text-gray-900">
                        {new Date(inspection.scheduledDate).toLocaleDateString()}
                      </span>
                    </div>
                    {inspection.complianceScore !== undefined && (
                      <div className="flex justify-between">
                        <span className="text-gray-500">Compliance:</span>
                        <span className={`font-semibold ${
                          inspection.complianceScore >= 90 ? 'text-green-600' :
                          inspection.complianceScore >= 70 ? 'text-yellow-600' : 'text-red-600'
                        }`}>
                          {inspection.complianceScore}%
                        </span>
                      </div>
                    )}
                    {inspection.totalFindings !== undefined && (
                      <div className="flex justify-between">
                        <span className="text-gray-500">Findings:</span>
                        <span className="text-gray-900">
                          {inspection.totalFindings} total
                          {inspection.criticalFindings ? (
                            <span className="text-red-600 ml-1">({inspection.criticalFindings} critical)</span>
                          ) : ''}
                        </span>
                      </div>
                    )}
                  </div>

                  <div className="pt-4 border-t flex items-center justify-between">
                    <Link
                      href={`/qhse/inspections/${inspection.id}`}
                      className="text-blue-600 hover:text-blue-900 text-sm font-medium flex items-center gap-1"
                      onClick={(e) => e.stopPropagation()}
                    >
                      View Details
                      <FiLink2 className="w-4 h-4" />
                    </Link>
                    {inspection.status === 'SCHEDULED' && (
                      <Link
                        href={`/qhse/calendar?inspection=${inspection.id}`}
                        className="text-purple-600 hover:text-purple-900 text-sm font-medium flex items-center gap-1"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <FiCalendar className="w-4 h-4" />
                        Calendar
                      </Link>
                    )}
                  </div>
                </motion.div>
              ))
            )}
          </div>
        </div>
      </div>

      {/* Cross-Module Links */}
      {selectedInspection && (
        <CrossModuleLinks
          title="Related Modules & Actions"
          links={getCrossModuleLinks(selectedInspection)}
        />
      )}

      {/* Default Cross-Module Links */}
      {!selectedInspection && (
        <CrossModuleLinks
          title="Quick Navigation"
          links={[
            { label: 'QHSE Dashboard', href: '/qhse/dashboard', icon: 'ri-dashboard-3-line', description: 'Overview' },
            { label: 'Calendar', href: '/qhse/calendar', icon: 'ri-calendar-line', description: 'View calendar' },
            { label: 'Incidents', href: '/qhse/incidents', icon: 'ri-error-warning-line', description: 'View incidents' },
            { label: 'Training', href: '/qhse/training', icon: 'ri-graduation-cap-line', description: 'Training records' },
            { label: 'Checklist Builder', href: '/qhse/inspections?tab=checklists', icon: 'ri-file-list-3-line', description: 'Manage checklists' },
            { label: 'Search', href: '/qhse/search', icon: 'ri-search-line', description: 'Advanced search' },
          ]}
        />
      )}
    </div>
  )
}

/**
 * QHSE Document Templates Management Page
 * Manage document templates for QHSE reports
 */

'use client'

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { FiPlus, FiEdit, FiTrash2, FiSave, FiX, FiFileText, FiDownload, FiCopy, FiSearch } from 'react-icons/fi'
import CrossModuleLinks from '@/components/qhse/CrossModuleLinks'

interface Template {
  id: string
  name: string
  type: 'INCIDENT_REPORT' | 'INSPECTION_REPORT' | 'AUDIT_REPORT' | 'TRAINING_CERTIFICATE' | 'ESG_REPORT' | 'CUSTOM'
  description?: string
  content: string
  variables?: string[]
  createdAt: string
  updatedAt: string
}

export default function QHSETemplatesPage() {
  const [templates, setTemplates] = useState<Template[]>([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'all' | 'incident' | 'inspection' | 'audit' | 'training' | 'esg' | 'custom'>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingTemplate, setEditingTemplate] = useState<Template | null>(null)

  useEffect(() => {
    fetchTemplates()
  }, [activeTab])

  const fetchTemplates = async () => {
    try {
      setLoading(true)
      const url = activeTab === 'all'
        ? '/api/qhse/templates'
        : `/api/qhse/templates?type=${activeTab.toUpperCase()}_REPORT`
      const response = await fetch(url)
      const data = await response.json()
      
      if (data.success) {
        setTemplates(data.data || [])
      }
    } catch (err) {
      console.error('Error fetching templates:', err)
    } finally {
      setLoading(false)
    }
  }

  const handleDelete = async (templateId: string) => {
    if (!confirm('Are you sure you want to delete this template?')) return
    
    try {
      const response = await fetch(`/api/qhse/templates/${templateId}`, {
        method: 'DELETE',
      })
      const data = await response.json()
      
      if (data.success) {
        fetchTemplates()
      }
    } catch (err) {
      console.error('Error deleting template:', err)
    }
  }

  const templateTypes = [
    { id: 'all', label: 'All Templates' },
    { id: 'incident', label: 'Incident Reports' },
    { id: 'inspection', label: 'Inspection Reports' },
    { id: 'audit', label: 'Audit Reports' },
    { id: 'training', label: 'Training Certificates' },
    { id: 'esg', label: 'ESG Reports' },
    { id: 'custom', label: 'Custom' },
  ]

  const filteredTemplates = templates.filter(t => {
    if (searchQuery) {
      return t.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
             t.description?.toLowerCase().includes(searchQuery.toLowerCase())
    }
    return true
  })

  if (loading && templates.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading templates...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Document Templates</h1>
          <p className="text-gray-600 mt-1">Manage document templates for QHSE reports</p>
        </div>
        <button
          onClick={() => setShowAddForm(true)}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2"
        >
          <FiPlus className="w-4 h-4" />
          Create Template
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Total Templates</p>
              <p className="text-2xl font-bold text-gray-900 mt-1">{templates.length}</p>
            </div>
            <FiFileText className="w-8 h-8 text-blue-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-red-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Incident Reports</p>
              <p className="text-2xl font-bold text-red-600 mt-1">
                {templates.filter(t => t.type === 'INCIDENT_REPORT').length}
              </p>
            </div>
            <FiFileText className="w-8 h-8 text-red-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-green-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Inspection Reports</p>
              <p className="text-2xl font-bold text-green-600 mt-1">
                {templates.filter(t => t.type === 'INSPECTION_REPORT').length}
              </p>
            </div>
            <FiFileText className="w-8 h-8 text-green-500" />
          </div>
        </motion.div>
        
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-purple-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Custom Templates</p>
              <p className="text-2xl font-bold text-purple-600 mt-1">
                {templates.filter(t => t.type === 'CUSTOM').length}
              </p>
            </div>
            <FiFileText className="w-8 h-8 text-purple-500" />
          </div>
        </motion.div>
      </div>

      {/* Tabs and Search */}
      <div className="bg-white rounded-lg shadow">
        <div className="border-b border-gray-200">
          <nav className="flex -mb-px overflow-x-auto">
            {templateTypes.map((type) => {
              const count = type.id === 'all'
                ? templates.length
                : templates.filter(t => t.type === `${type.id.toUpperCase()}_REPORT` || (type.id === 'custom' && t.type === 'CUSTOM')).length
              return (
                <button
                  key={type.id}
                  onClick={() => setActiveTab(type.id as any)}
                  className={`flex items-center gap-2 px-6 py-4 border-b-2 font-medium text-sm whitespace-nowrap ${
                    activeTab === type.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  {type.label}
                  {count > 0 && (
                    <span className="ml-1 px-2 py-0.5 text-xs bg-blue-100 text-blue-800 rounded-full">
                      {count}
                    </span>
                  )}
                </button>
              )
            })}
          </nav>
        </div>

        <div className="p-6">
          {/* Search */}
          <div className="mb-6">
            <div className="relative">
              <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search templates..."
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>

          {/* Templates Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredTemplates.length === 0 ? (
              <div className="col-span-full text-center py-12">
                <FiFileText className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-500 mb-4">No templates found</p>
                <button
                  onClick={() => setShowAddForm(true)}
                  className="text-blue-600 hover:text-blue-800"
                >
                  Create your first template
                </button>
              </div>
            ) : (
              filteredTemplates.map((template) => (
                <motion.div
                  key={template.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-gray-50 rounded-lg p-4 border border-gray-200 hover:shadow-md transition"
                >
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex-1">
                      <h3 className="font-semibold text-gray-900 mb-1">{template.name}</h3>
                      <span className="px-2 py-1 text-xs bg-blue-100 text-blue-800 rounded-full">
                        {template.type.replace(/_/g, ' ')}
                      </span>
                    </div>
                    <div className="flex gap-2">
                      <button
                        onClick={() => setEditingTemplate(template)}
                        className="p-1.5 text-blue-600 hover:bg-blue-50 rounded"
                      >
                        <FiEdit className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleDelete(template.id)}
                        className="p-1.5 text-red-600 hover:bg-red-50 rounded"
                      >
                        <FiTrash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                  {template.description && (
                    <p className="text-sm text-gray-600 mb-3">{template.description}</p>
                  )}
                  {template.variables && template.variables.length > 0 && (
                    <div className="mb-3">
                      <p className="text-xs text-gray-500 mb-1">Variables:</p>
                      <div className="flex flex-wrap gap-1">
                        {template.variables.map((variable) => (
                          <span
                            key={variable}
                            className="px-2 py-0.5 text-xs bg-gray-200 text-gray-700 rounded"
                          >
                            {variable}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}
                  <div className="flex gap-2 pt-3 border-t border-gray-200">
                    <button className="flex-1 px-3 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 flex items-center justify-center gap-1">
                      <FiDownload className="w-3 h-3" />
                      Use
                    </button>
                    <button className="px-3 py-1.5 text-sm border border-gray-300 rounded hover:bg-gray-50">
                      <FiCopy className="w-3 h-3" />
                    </button>
                  </div>
                  <p className="text-xs text-gray-500 mt-2">
                    Updated: {new Date(template.updatedAt).toLocaleDateString()}
                  </p>
                </motion.div>
              ))
            )}
          </div>
        </div>
      </div>

      {/* Add/Edit Form Modal */}
      {(showAddForm || editingTemplate) && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white rounded-lg shadow-xl p-6 w-full max-w-3xl max-h-[90vh] overflow-y-auto"
          >
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold text-gray-900">
                {editingTemplate ? 'Edit Template' : 'Create Template'}
              </h2>
              <button
                onClick={() => {
                  setShowAddForm(false)
                  setEditingTemplate(null)
                }}
                className="p-2 hover:bg-gray-100 rounded-lg"
              >
                <FiX className="w-5 h-5" />
              </button>
            </div>
            <div className="space-y-4">
              <form
                onSubmit={async (e) => {
                  e.preventDefault()
                  const formData = new FormData(e.currentTarget)
                  
                  const templateData = {
                    name: formData.get('name') as string,
                    type: formData.get('type') as string,
                    description: formData.get('description')?.toString() || undefined,
                    content: formData.get('content') as string,
                    variables: formData.get('variables')?.toString().split(',').filter(Boolean) || [],
                  }

                  try {
                    const url = editingTemplate
                      ? `/api/qhse/templates/${editingTemplate.id}`
                      : '/api/qhse/templates'
                    const method = editingTemplate ? 'PUT' : 'POST'

                    const response = await fetch(url, {
                      method,
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify(templateData),
                    })

                    const data = await response.json()
                    if (data.success) {
                      setShowAddForm(false)
                      setEditingTemplate(null)
                      fetchTemplates()
                    } else {
                      alert(data.error || 'Failed to save template')
                    }
                  } catch (err) {
                    console.error('Error saving template:', err)
                    alert('Failed to save template')
                  }
                }}
                className="space-y-4"
              >
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Template Name *
                  </label>
                  <input
                    type="text"
                    name="name"
                    required
                    defaultValue={editingTemplate?.name}
                    placeholder="e.g., Incident Report Template"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Template Type *
                  </label>
                  <select
                    name="type"
                    required
                    defaultValue={editingTemplate?.type || 'INCIDENT_REPORT'}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="INCIDENT_REPORT">Incident Report</option>
                    <option value="INSPECTION_REPORT">Inspection Report</option>
                    <option value="AUDIT_REPORT">Audit Report</option>
                    <option value="TRAINING_CERTIFICATE">Training Certificate</option>
                    <option value="ESG_REPORT">ESG Report</option>
                    <option value="CUSTOM">Custom</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Description
                  </label>
                  <textarea
                    name="description"
                    rows={2}
                    defaultValue={editingTemplate?.description}
                    placeholder="Template description..."
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Template Content *
                  </label>
                  <textarea
                    name="content"
                    required
                    rows={12}
                    defaultValue={editingTemplate?.content}
                    placeholder={`Template content with variables like {{variable_name}}

Example:
---
INCIDENT REPORT
Date: {{incident_date}}
Location: {{location}}
Description: {{description}}
Severity: {{severity}}
Status: {{status}}
---`}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 font-mono text-sm"
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    Use {{variable_name}} syntax for dynamic variables
                  </p>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Variables (Optional)
                  </label>
                  <input
                    type="text"
                    name="variables"
                    defaultValue={editingTemplate?.variables?.join(',')}
                    placeholder="incident_date, location, description, severity"
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    Comma-separated list of variable names (without {{}})
                  </p>
                </div>

                <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
                  <p className="text-sm text-blue-800 font-medium mb-1">💡 Template Tips:</p>
                  <ul className="text-xs text-blue-700 space-y-1 list-disc list-inside">
                    <li>Use {{variable_name}} for dynamic content</li>
                    <li>Variables will be replaced with actual data when generating documents</li>
                    <li>Common variables: incident_date, location, description, severity, status</li>
                    <li>You can use HTML formatting for rich text templates</li>
                  </ul>
                </div>

                <div className="flex justify-end gap-2 pt-4 border-t">
                  <button
                    type="button"
                    onClick={() => {
                      setShowAddForm(false)
                      setEditingTemplate(null)
                    }}
                    className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2"
                  >
                    <FiSave className="w-4 h-4" />
                    {editingTemplate ? 'Update' : 'Create'} Template
                  </button>
                </div>
              </form>
            </div>
          </motion.div>
        </div>
      )}

      {/* Cross-Module Links */}
      <CrossModuleLinks
        title="Quick Navigation"
        links={[
          { label: 'QHSE Dashboard', href: '/qhse/dashboard', icon: 'ri-dashboard-3-line', description: 'Overview' },
          { label: 'Incidents', href: '/qhse/incidents', icon: 'ri-error-warning-line', description: 'View incidents' },
          { label: 'Inspections', href: '/qhse/inspections', icon: 'ri-clipboard-line', description: 'View inspections' },
          { label: 'Regulatory', href: '/qhse/regulatory', icon: 'ri-file-list-3-line', description: 'Compliance tracking' },
          { label: 'Search', href: '/qhse/search', icon: 'ri-search-line', description: 'Advanced search' },
        ]}
      />
    </div>
  )
}

/**
 * QHSE Training & Compliance Page - ENHANCED
 * Comprehensive training program management and compliance tracking
 * With tabs, expiry alerts, compliance tracking, and cross-module links
 */

'use client'

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Link from 'next/link'
import { FiSearch, FiFilter, FiDownload, FiPlus, FiBookOpen, FiCheckCircle, FiClock, FiAlertTriangle, FiBarChart, FiCalendar, FiUser, FiTrendingUp } from 'react-icons/fi'
import type { TrainingProgram, TrainingRecord } from '@/types/qhse'
import CrossModuleLinks, { CrossModuleLink } from '@/components/qhse/CrossModuleLinks'
import { getQHSETrainingLinks } from '@/utils/moduleInterconnectivity'
import { PremiumLoader } from '@/components/loading'

export default function QHSETrainingPage() {
  const [programs, setPrograms] = useState<TrainingProgram[]>([])
  const [records, setRecords] = useState<TrainingRecord[]>([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'programs' | 'records' | 'compliance' | 'expiring'>('programs')
  const [searchQuery, setSearchQuery] = useState('')
  const [showFilters, setShowFilters] = useState(false)
  const [selectedRecord, setSelectedRecord] = useState<TrainingRecord | null>(null)

  useEffect(() => {
    fetchData()
  }, [activeTab])

  const fetchData = async () => {
    try {
      setLoading(true)

      if (activeTab === 'programs') {
        const response = await fetch('/api/qhse/training?type=programs')
        const data = await response.json()
        if (data.success) {
          setPrograms(data.data || [])
        }
      } else if (activeTab === 'records') {
        const response = await fetch('/api/qhse/training?type=records')
        const data = await response.json()
        if (data.success) {
          setRecords(data.data || [])
        }
      } else if (activeTab === 'expiring') {
        const response = await fetch('/api/qhse/training?type=records&filter=expiring')
        const data = await response.json()
        if (data.success) {
          setRecords(data.data || [])
        }
      } else {
        // Compliance tab - fetch both
        const [programsRes, recordsRes] = await Promise.all([
          fetch('/api/qhse/training?type=programs'),
          fetch('/api/qhse/training?type=records'),
        ])
        const programsData = await programsRes.json()
        const recordsData = await recordsRes.json()
        if (programsData.success) setPrograms(programsData.data || [])
        if (recordsData.success) setRecords(recordsData.data || [])
      }
    } catch (err) {
      console.error('Error fetching training data:', err)
    } finally {
      setLoading(false)
    }
  }

  const getStatusColor = (status: TrainingRecord['status']) => {
    switch (status) {
      case 'COMPLETED': return 'bg-green-100 text-green-800'
      case 'IN_PROGRESS': return 'bg-blue-100 text-blue-800'
      case 'NOT_STARTED': return 'bg-gray-100 text-gray-800'
      case 'EXPIRED': return 'bg-red-100 text-red-800'
      default: return 'bg-gray-100 text-gray-800'
    }
  }

  const getCrossModuleLinks = (record: TrainingRecord): CrossModuleLink[] => {
    const links = getQHSETrainingLinks(record.id, {
      employeeId: record.employeeId,
      programId: record.trainingProgramId,
    })

    return links.map(link => ({
      label: link.label,
      href: link.href,
      description: link.description,
      icon: link.icon,
    }))
  }

  const isExpiring = (record: TrainingRecord) => {
    if (!record.certificationExpiryDate) return false
    const expiry = new Date(record.certificationExpiryDate)
    const now = new Date()
    const daysUntilExpiry = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
    return daysUntilExpiry <= 30 && daysUntilExpiry > 0
  }

  const isExpired = (record: TrainingRecord) => {
    if (!record.certificationExpiryDate) return false
    return new Date(record.certificationExpiryDate) < new Date()
  }

  const stats = {
    totalPrograms: programs.length,
    totalRecords: records.length,
    completed: records.filter(r => r.status === 'COMPLETED').length,
    inProgress: records.filter(r => r.status === 'IN_PROGRESS').length,
    expired: records.filter(r => isExpired(r)).length,
    expiring: records.filter(r => isExpiring(r)).length,
    complianceRate: records.length > 0
      ? Math.round((records.filter(r => r.status === 'COMPLETED' && !isExpired(r)).length / records.length) * 100)
      : 0,
  }

  const filteredRecords = searchQuery
    ? records.filter(r =>
        r.employeeName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        r.trainingProgram?.name.toLowerCase().includes(searchQuery.toLowerCase())
      )
    : records

  const filteredPrograms = searchQuery
    ? programs.filter(p =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.programNumber.toLowerCase().includes(searchQuery.toLowerCase())
      )
    : programs

  if (loading && programs.length === 0 && records.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gradient-to-br from-[#0a0e1a] via-[#111827] to-[#0f172a]">
        <PremiumLoader 
          message="Loading training & compliance data..." 
          size="xl" 
          variant="default"
        />
      </div>
    )
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Training & Compliance</h1>
          <p className="text-gray-600 mt-1">Manage training programs and track compliance</p>
        </div>
        <div className="flex gap-2">
          <Link
            href="/qhse/training/new"
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2"
          >
            <FiPlus className="w-4 h-4" />
            Create Program
          </Link>
          <button className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center gap-2">
            <FiDownload className="w-4 h-4" />
            Export
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Programs</p>
              <p className="text-2xl font-bold text-gray-900 mt-1">{stats.totalPrograms}</p>
            </div>
            <FiBookOpen className="w-8 h-8 text-blue-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-green-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Completed</p>
              <p className="text-2xl font-bold text-green-600 mt-1">{stats.completed}</p>
            </div>
            <FiCheckCircle className="w-8 h-8 text-green-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-yellow-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">In Progress</p>
              <p className="text-2xl font-bold text-yellow-600 mt-1">{stats.inProgress}</p>
            </div>
            <FiClock className="w-8 h-8 text-yellow-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-red-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Expired</p>
              <p className="text-2xl font-bold text-red-600 mt-1">{stats.expired}</p>
            </div>
            <FiAlertTriangle className="w-8 h-8 text-red-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-orange-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Expiring</p>
              <p className="text-2xl font-bold text-orange-600 mt-1">{stats.expiring}</p>
            </div>
            <FiAlertTriangle className="w-8 h-8 text-orange-500" />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
          className="bg-white rounded-lg shadow p-4 border-l-4 border-purple-500"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-500">Compliance</p>
              <p className="text-2xl font-bold text-purple-600 mt-1">{stats.complianceRate}%</p>
            </div>
            <FiTrendingUp className="w-8 h-8 text-purple-500" />
          </div>
        </motion.div>
      </div>

      {/* Tabs */}
      <div className="bg-white rounded-lg shadow">
        <div className="border-b border-gray-200">
          <nav className="flex -mb-px">
            {[
              { id: 'programs', label: 'Training Programs', icon: FiBookOpen },
              { id: 'records', label: 'Training Records', icon: FiUser },
              { id: 'compliance', label: 'Compliance Overview', icon: FiBarChart },
              { id: 'expiring', label: 'Expiring Soon', icon: FiAlertTriangle },
            ].map((tab) => {
              const Icon = tab.icon
              const badge = tab.id === 'expiring' && stats.expiring > 0 ? stats.expiring : undefined
              return (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id as any)}
                  className={`flex items-center gap-2 px-6 py-4 border-b-2 font-medium text-sm relative ${
                    activeTab === tab.id
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  <Icon className="w-4 h-4" />
                  {tab.label}
                  {badge && (
                    <span className="ml-1 px-2 py-0.5 text-xs bg-red-100 text-red-800 rounded-full">
                      {badge}
                    </span>
                  )}
                </button>
              )
            })}
          </nav>
        </div>

        <div className="p-6">
          {/* Search */}
          <div className="mb-6">
            <div className="relative">
              <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder={
                  activeTab === 'programs'
                    ? 'Search programs by name or number...'
                    : 'Search records by employee or program...'
                }
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>

          {/* Programs Tab */}
          {activeTab === 'programs' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {filteredPrograms.length === 0 ? (
                <div className="col-span-full text-center py-12">
                  <FiBookOpen className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-500 mb-4">No training programs found</p>
                  <Link
                    href="/qhse/training/new"
                    className="text-blue-600 hover:text-blue-800"
                  >
                    Create your first program
                  </Link>
                </div>
              ) : (
                filteredPrograms.map((program) => (
                  <motion.div
                    key={program.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white rounded-lg shadow border border-gray-200 p-6 hover:shadow-lg transition"
                  >
                    <div className="flex justify-between items-start mb-4">
                      <div className="flex-1">
                        <h3 className="text-lg font-semibold text-gray-900 mb-1">{program.name}</h3>
                        <p className="text-sm text-gray-500">{program.programNumber}</p>
                      </div>
                      {program.isMandatory && (
                        <span className="px-2 py-1 text-xs font-semibold bg-red-100 text-red-800 rounded-full">
                          Mandatory
                        </span>
                      )}
                    </div>
                    <p className="text-sm text-gray-600 mb-4 line-clamp-2">{program.description}</p>
                    <div className="space-y-2 text-sm">
                      <div className="flex justify-between">
                        <span className="text-gray-500">Type:</span>
                        <span className="text-gray-900 font-medium">{program.type.replace(/_/g, ' ')}</span>
                      </div>
                      <div className="flex justify-between">
                        <span className="text-gray-500">Delivery:</span>
                        <span className="text-gray-900">{program.deliveryMethod.replace(/_/g, ' ')}</span>
                      </div>
                      {program.duration && (
                        <div className="flex justify-between">
                          <span className="text-gray-500">Duration:</span>
                          <span className="text-gray-900">{program.duration} minutes</span>
                        </div>
                      )}
                      {program.certificationValidityDays && (
                        <div className="flex justify-between">
                          <span className="text-gray-500">Valid for:</span>
                          <span className="text-gray-900">{program.certificationValidityDays} days</span>
                        </div>
                      )}
                    </div>
                  </motion.div>
                ))
              )}
            </div>
          )}

          {/* Records Tab */}
          {activeTab === 'records' && (
            <div className="bg-white rounded-lg shadow overflow-hidden">
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Employee</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Program</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Progress</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Due Date</th>
                      <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Expiry</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {filteredRecords.length === 0 ? (
                      <tr>
                        <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                          No training records found
                        </td>
                      </tr>
                    ) : (
                      filteredRecords.map((record) => (
                        <motion.tr
                          key={record.id}
                          initial={{ opacity: 0 }}
                          animate={{ opacity: 1 }}
                          className={`hover:bg-gray-50 cursor-pointer ${
                            isExpired(record) ? 'bg-red-50' : isExpiring(record) ? 'bg-orange-50' : ''
                          }`}
                          onClick={() => setSelectedRecord(record)}
                        >
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                            {record.employeeName || record.employeeId}
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-900">
                            {record.trainingProgram?.name || 'Unknown'}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap">
                            <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(record.status)}`}>
                              {record.status.replace(/_/g, ' ')}
                            </span>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            <div className="flex items-center gap-2">
                              <div className="w-16 bg-gray-200 rounded-full h-2">
                                <div
                                  className="bg-blue-600 h-2 rounded-full"
                                  style={{ width: `${record.progress || 0}%` }}
                                ></div>
                              </div>
                              <span>{record.progress || 0}%</span>
                            </div>
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                            {record.dueDate ? new Date(record.dueDate).toLocaleDateString() : 'N/A'}
                          </td>
                          <td className="px-6 py-4 whitespace-nowrap text-sm">
                            {record.certificationExpiryDate ? (
                              <span className={`font-semibold ${
                                isExpired(record) ? 'text-red-600' :
                                isExpiring(record) ? 'text-orange-600' : 'text-gray-900'
                              }`}>
                                {new Date(record.certificationExpiryDate).toLocaleDateString()}
                                {isExpired(record) && ' (Expired)'}
                                {isExpiring(record) && ' (Expiring Soon)'}
                              </span>
                            ) : 'N/A'}
                          </td>
                        </motion.tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Compliance Tab */}
          {activeTab === 'compliance' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-white rounded-lg shadow p-6">
                  <h3 className="text-sm font-medium text-gray-500">Total Programs</h3>
                  <p className="text-3xl font-bold text-gray-900 mt-2">{stats.totalPrograms}</p>
                </div>
                <div className="bg-white rounded-lg shadow p-6">
                  <h3 className="text-sm font-medium text-gray-500">Completed Records</h3>
                  <p className="text-3xl font-bold text-green-600 mt-2">{stats.completed}</p>
                </div>
                <div className="bg-white rounded-lg shadow p-6">
                  <h3 className="text-sm font-medium text-gray-500">Compliance Rate</h3>
                  <p className="text-3xl font-bold text-purple-600 mt-2">{stats.complianceRate}%</p>
                </div>
              </div>

              <div className="bg-white rounded-lg shadow p-6">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Compliance by Program</h3>
                <div className="space-y-4">
                  {programs.map((program) => {
                    const programRecords = records.filter(r => r.trainingProgramId === program.id)
                    const completed = programRecords.filter(r => r.status === 'COMPLETED' && !isExpired(r)).length
                    const rate = programRecords.length > 0 ? Math.round((completed / programRecords.length) * 100) : 0
                    return (
                      <div key={program.id} className="border-b border-gray-200 pb-4 last:border-0">
                        <div className="flex justify-between items-center mb-2">
                          <span className="font-medium text-gray-900">{program.name}</span>
                          <span className={`font-semibold ${
                            rate >= 90 ? 'text-green-600' :
                            rate >= 70 ? 'text-yellow-600' : 'text-red-600'
                          }`}>
                            {rate}%
                          </span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2">
                          <div
                            className={`h-2 rounded-full ${
                              rate >= 90 ? 'bg-green-600' :
                              rate >= 70 ? 'bg-yellow-600' : 'bg-red-600'
                            }`}
                            style={{ width: `${rate}%` }}
                          ></div>
                        </div>
                        <p className="text-xs text-gray-500 mt-1">
                          {completed} of {programRecords.length} completed
                        </p>
                      </div>
                    )
                  })}
                </div>
              </div>
            </div>
          )}

          {/* Expiring Tab */}
          {activeTab === 'expiring' && (
            <div className="space-y-4">
              {filteredRecords.filter(r => isExpiring(r) || isExpired(r)).length === 0 ? (
                <div className="text-center py-12">
                  <FiCheckCircle className="w-12 h-12 text-green-400 mx-auto mb-4" />
                  <p className="text-gray-500">No expiring or expired certifications</p>
                </div>
              ) : (
                filteredRecords
                  .filter(r => isExpiring(r) || isExpired(r))
                  .map((record) => (
                    <motion.div
                      key={record.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      className={`bg-white rounded-lg shadow border-l-4 p-6 ${
                        isExpired(record) ? 'border-red-500' : 'border-orange-500'
                      }`}
                    >
                      <div className="flex justify-between items-start">
                        <div className="flex-1">
                          <h3 className="text-lg font-semibold text-gray-900 mb-1">
                            {record.employeeName || record.employeeId}
                          </h3>
                          <p className="text-sm text-gray-600 mb-2">
                            {record.trainingProgram?.name || 'Unknown Program'}
                          </p>
                          <div className="flex items-center gap-4 text-sm">
                            <div>
                              <span className="text-gray-500">Expiry Date:</span>
                              <span className={`ml-2 font-semibold ${
                                isExpired(record) ? 'text-red-600' : 'text-orange-600'
                              }`}>
                                {record.certificationExpiryDate
                                  ? new Date(record.certificationExpiryDate).toLocaleDateString()
                                  : 'N/A'}
                              </span>
                            </div>
                            {record.certificationExpiryDate && (
                              <div>
                                <span className="text-gray-500">Days Remaining:</span>
                                <span className={`ml-2 font-semibold ${
                                  isExpired(record) ? 'text-red-600' : 'text-orange-600'
                                }`}>
                                  {isExpired(record)
                                    ? 'Expired'
                                    : Math.ceil(
                                        (new Date(record.certificationExpiryDate).getTime() - new Date().getTime()) /
                                          (1000 * 60 * 60 * 24)
                                      )}
                                </span>
                              </div>
                            )}
                          </div>
                        </div>
                        <span className={`px-3 py-1 text-sm font-semibold rounded-full ${
                          isExpired(record)
                            ? 'bg-red-100 text-red-800'
                            : 'bg-orange-100 text-orange-800'
                        }`}>
                          {isExpired(record) ? 'Expired' : 'Expiring Soon'}
                        </span>
                      </div>
                    </motion.div>
                  ))
              )}
            </div>
          )}
        </div>
      </div>

      {/* Cross-Module Links */}
      {selectedRecord && (
        <CrossModuleLinks
          title="Related Modules & Actions"
          links={getCrossModuleLinks(selectedRecord)}
        />
      )}

      {/* Default Cross-Module Links */}
      {!selectedRecord && (
        <CrossModuleLinks
          title="Quick Navigation"
          links={[
            { label: 'QHSE Dashboard', href: '/qhse/dashboard', icon: 'ri-dashboard-3-line', description: 'Overview' },
            { label: 'HR Module', href: '/hr/employees', icon: 'ri-user-line', description: 'Employee records' },
            { label: 'Incidents', href: '/qhse/incidents', icon: 'ri-error-warning-line', description: 'View incidents' },
            { label: 'Inspections', href: '/qhse/inspections', icon: 'ri-clipboard-line', description: 'View inspections' },
            { label: 'Calendar', href: '/qhse/calendar', icon: 'ri-calendar-line', description: 'View calendar' },
            { label: 'Search', href: '/qhse/search', icon: 'ri-search-line', description: 'Advanced search' },
          ]}
        />
      )}
    </div>
  )
}

/**
 * QR Code Module Demo & Visualization Page
 * Comprehensive demo of all QR code features with test data
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import UniversalQRGenerator from '@/components/qr/UniversalQRGenerator'
import QRCodeBadge from '@/components/qr/QRCodeBadge'
import QRScanner from '@/components/qr/QRScanner'
import { generateQRTestData, generateQRAnalyticsTestData, generateScanEventTestData } from '@/lib/utils/qrTestDataGenerator'
import { QRCodeData } from '@/types/qr'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer, LineChart, Line } from 'recharts'

export default function QRDemoPage() {
  const [testData, setTestData] = useState<any>(null)
  const [analytics, setAnalytics] = useState<any>(null)
  const [scanEvents, setScanEvents] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedQR, setSelectedQR] = useState<any>(null)
  const [activeTab, setActiveTab] = useState<'overview' | 'generator' | 'scanner' | 'templates' | 'bulk' | 'analytics'>('overview')

  useEffect(() => {
    loadTestData()
  }, [])

  const loadTestData = async () => {
    setLoading(true)
    try {
      const data = await generateQRTestData()
      const analyticsData = generateQRAnalyticsTestData()
      const events = generateScanEventTestData(50)

      setTestData(data)
      setAnalytics(analyticsData)
      setScanEvents(events)
    } catch (error) {
      console.error('Error loading test data:', error)
    } finally {
      setLoading(false)
    }
  }

  const COLORS = ['#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899']

  if (loading) {
    return (
      <PageTemplate title="QR Code Demo">
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="text-center">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500 mx-auto"></div>
            <p className="mt-4 text-gray-400">Loading QR code test data...</p>
          </div>
        </div>
      </PageTemplate>
    )
  }

  return (
    <PageTemplate title="QR Code Module - Demo & Visualization">
      <div className="space-y-6">
        {/* Header Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-gradient-to-br from-cyan-500/20 to-blue-600/20 border border-cyan-500/30 rounded-xl p-6"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-400 mb-1">Total QR Codes</p>
                <p className="text-3xl font-bold text-white">{testData?.qrCodes.length || 0}</p>
              </div>
              <i className="ri-qr-code-line text-4xl text-cyan-400"></i>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="bg-gradient-to-br from-green-500/20 to-emerald-600/20 border border-green-500/30 rounded-xl p-6"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-400 mb-1">Total Scans</p>
                <p className="text-3xl font-bold text-white">{analytics?.totalScans.toLocaleString() || 0}</p>
              </div>
              <i className="ri-scan-line text-4xl text-green-400"></i>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="bg-gradient-to-br from-purple-500/20 to-pink-600/20 border border-purple-500/30 rounded-xl p-6"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-400 mb-1">Templates</p>
                <p className="text-3xl font-bold text-white">{testData?.templates.length || 0}</p>
              </div>
              <i className="ri-file-list-line text-4xl text-purple-400"></i>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="bg-gradient-to-br from-orange-500/20 to-red-600/20 border border-orange-500/30 rounded-xl p-6"
