                        <p className="text-xl font-bold text-white">{op.totalItems}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-400 mb-1">Processed</p>
                        <p className="text-xl font-bold text-green-400">{op.processedItems}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-400 mb-1">Failed</p>
                        <p className="text-xl font-bold text-red-400">{op.failedItems}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-400 mb-1">Success Rate</p>
                        <p className="text-xl font-bold text-cyan-400">
