                      </div>
                    </div>
                    <div className="space-y-2">
                      {op.items.slice(0, 5).map((item: any, idx: number) => (
                        <div key={idx} className="flex items-center justify-between p-2 bg-gray-800 rounded text-sm">
                          <span className="text-gray-300 font-mono">{item.id}</span>
                          <span className={`px-2 py-1 rounded text-xs ${
                            item.status === 'success' ? 'bg-green-500/20 text-green-400' :
