// Helper functions
function getCategoryColor(category: string): string {
  switch (category) {
    case 'wms': return '#06b6d4'
    case 'hazalyze': return '#8b5cf6'
    case 'aivision': return '#10b981'
    case 'integration': return '#3b82f6'
    default: return '#06b6d4'
  }
}

function getCategoryGradient(category: string): string {
  switch (category) {
    case 'wms': return '#06b6d4, #0891b2'
    case 'hazalyze': return '#8b5cf6, #7c3aed'
    case 'aivision': return '#10b981, #059669'
    case 'integration': return '#3b82f6, #2563eb'
    default: return '#06b6d4, #0891b2'
  }
}

