              className={`px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm font-medium transition-colors flex items-center gap-1 sm:gap-2 min-h-[36px] ${
                viewMode === 'legacy'
                  ? 'bg-cyan-500 text-white'
