    </PageTemplate>
  )
}

'use client'

import { useState, useMemo, useEffect } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import Tooltip from '@/components/Tooltip'
import Modal from '@/components/Modal'
import { generateStockAlerts } from '@/utils/mockDataGenerators'
import { format } from 'date-fns'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer, LineChart, Line } from 'recharts'
import { realtimeSimulator, simulateKPIUpdates } from '@/utils/realtimeDataSimulator'

export default function StockAlerts() {
  const [alerts, setAlerts] = useState(() => generateStockAlerts(80))
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedAlertLevel, setSelectedAlertLevel] = useState<string>('ALL')
  const [selectedNeedsReorder, setSelectedNeedsReorder] = useState<string>('ALL')
  const [viewMode, setViewMode] = useState<'table' | 'grid' | 'analytics' | 'critical'>('table')
  const [selectedAlert, setSelectedAlert] = useState<any>(null)
  const [showViewModal, setShowViewModal] = useState(false)
  const [realTimeEnabled, setRealTimeEnabled] = useState(true)
  const [realTimeStats, setRealTimeStats] = useState({
    totalAlerts: 0,
    critical: 0,
    needsReorder: 0,
    valueAtRisk: 0,
  })

  const filteredAlerts = useMemo(() => {
    return alerts.filter((alert) => {
      const matchesSearch =
        alert.materialNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
        alert.materialDescription.toLowerCase().includes(searchQuery.toLowerCase()) ||
        alert.storageLocation.toLowerCase().includes(searchQuery.toLowerCase())
      const matchesAlertLevel = selectedAlertLevel === 'ALL' || alert.alertLevel === selectedAlertLevel
      const matchesNeedsReorder = selectedNeedsReorder === 'ALL' || 
        (selectedNeedsReorder === 'YES' && alert.needsReorder) ||
        (selectedNeedsReorder === 'NO' && !alert.needsReorder)
      return matchesSearch && matchesAlertLevel && matchesNeedsReorder
    })
  }, [alerts, searchQuery, selectedAlertLevel, selectedNeedsReorder])

  const criticalAlerts = useMemo(() => {
    return alerts.filter(a => a.alertLevel === 'CRITICAL' || a.needsReorder)
  }, [alerts])

  const totalValueAtRisk = useMemo(() => {
    return criticalAlerts.reduce((sum, a) => sum + (a.currentStock * 10), 0) // Assuming unit value
  }, [criticalAlerts])

  const alertLevelStats = useMemo(() => {
    const stats: Record<string, number> = {}
    alerts.forEach(alert => {
      stats[alert.alertLevel] = (stats[alert.alertLevel] || 0) + 1
    })
    return stats
  }, [alerts])

  const chartData = useMemo(() => {
    return Object.entries(alertLevelStats).map(([level, count]) => ({
      level,
      count,
    }))
  }, [alertLevelStats])

  const stockLevelData = useMemo(() => {
    return filteredAlerts.slice(0, 20).map(alert => ({
      material: alert.materialNumber.substring(0, 8),
      current: alert.currentStock,
      reorder: alert.reorderPoint,
      max: alert.maxStock,
    }))
  }, [filteredAlerts])

  const aggregateStats = useMemo(() => {
    return {
      totalAlerts: alerts.length,
      critical: alerts.filter(a => a.alertLevel === 'CRITICAL').length,
      needsReorder: alerts.filter(a => a.needsReorder).length,
      valueAtRisk: totalValueAtRisk,
    }
  }, [alerts.length, alerts, totalValueAtRisk])

  useEffect(() => {
    if (!realTimeEnabled) return

    const unsubscribe = realtimeSimulator.subscribe('stock-alerts-stats', (data: typeof realTimeStats) => {
      setRealTimeStats(data)
    })

    const stop = realtimeSimulator.start('stock-alerts-stats', () => ({
      totalAlerts: aggregateStats.totalAlerts,
      critical: simulateKPIUpdates(aggregateStats.critical, 0.1),
      needsReorder: simulateKPIUpdates(aggregateStats.needsReorder, 0.05),
      valueAtRisk: simulateKPIUpdates(aggregateStats.valueAtRisk, 0.02),
    }), 5000, true)

    return () => {
      unsubscribe()
      stop()
    }
  }, [realTimeEnabled, aggregateStats.totalAlerts, aggregateStats.critical, aggregateStats.needsReorder, aggregateStats.valueAtRisk])

  const stats = [
    {
      label: 'Total Alerts',
      value: realTimeEnabled ? realTimeStats.totalAlerts : aggregateStats.totalAlerts,
      icon: 'ri-alert-line',
      tooltip: 'Total stock alerts',
      trend: 'up' as const,
    },
    {
      label: 'Critical',
      value: realTimeEnabled ? realTimeStats.critical : aggregateStats.critical,
      icon: 'ri-error-warning-line',
      tooltip: 'Critical stock alerts requiring immediate action',
      trend: 'neutral' as const,
    },
    {
      label: 'Needs Reorder',
      value: realTimeEnabled ? realTimeStats.needsReorder : aggregateStats.needsReorder,
      icon: 'ri-shopping-cart-line',
      tooltip: 'Items that need reordering',
      trend: 'neutral' as const,
    },
    {
      label: 'Value at Risk',
      value: `AED ${(realTimeEnabled ? realTimeStats.valueAtRisk : aggregateStats.valueAtRisk).toLocaleString()}`,
      icon: 'ri-money-dollar-circle-line',
      tooltip: 'Total value of items at risk',
      trend: 'neutral' as const,
    },
  ]

  const COLORS = {
    CRITICAL: '#ef4444',
    HIGH: '#f59e0b',
    MEDIUM: '#eab308',
    LOW: '#10b981',
  }

  return (
    <PageTemplate
      title="Stock Alerts"
      description="Low stock warnings and reorder management - Monitor stock levels, set reorder points, and manage inventory alerts with automated notifications"
      icon="ri-alert-line"
      systemInfo={{
        sap: 'Stock Alerts - Material Requirements Planning (MRP), Reorder Point Management',
        oracle: 'Inventory Alerts - Reorder Point Management, Stock Warnings',
        manhattan: 'Stock Alerts - Automated Reorder Management, Inventory Warnings',
      }}
      examples={[
        'Monitor low stock levels with automated alerts',
        'Set and manage reorder points by material',
        'Track days of stock remaining',
        'Generate purchase requisitions automatically',
        'Monitor stock consumption patterns',
        'Manage safety stock levels',
      ]}
      stats={stats}
      actions={
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 bg-white/5 border border-white/10 rounded-lg p-1">
            {(['table', 'grid', 'analytics', 'critical'] as const).map((mode) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`px-3 py-1.5 rounded text-sm font-medium transition-colors ${
                  viewMode === mode
                    ? 'bg-cyan-500 text-white'
                    : 'text-[#9ca3af] hover:text-white'
                }`}
              >
                <i className={`ri-${mode === 'table' ? 'table-line' : mode === 'grid' ? 'grid-line' : mode === 'analytics' ? 'bar-chart-line' : 'alarm-line'} mr-1`}></i>
                {mode.charAt(0).toUpperCase() + mode.slice(1)}
              </button>
            ))}
          </div>
          <button
            onClick={() => setRealTimeEnabled(!realTimeEnabled)}
            className={`px-3 sm:px-4 py-2 rounded-lg text-xs sm:text-sm font-medium transition-colors ${
              realTimeEnabled
                ? 'bg-green-500/20 text-green-400 border border-green-500/30'
                : 'bg-white/5 text-[#9ca3af] border border-white/10'
            }`}
          >
            <i className={`ri-${realTimeEnabled ? 'radio-button-line' : 'checkbox-blank-circle-line'} mr-1`}></i>
            Real-time
          </button>
          <Tooltip content="Create Purchase Requisition" position="bottom">
            <button className="bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white px-6 py-3 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 shadow-lg shadow-cyan-500/20">
              <i className="ri-shopping-cart-line"></i>
              Create PR
            </button>
          </Tooltip>
        </div>
      }
    >
      {/* Filters */}
      <div className="mb-6 flex items-center gap-4 flex-wrap">
        <div className="relative flex-1 min-w-[300px] max-w-md">
          <i className="ri-search-line absolute left-3 top-1/2 -translate-y-1/2 text-[#9ca3af] text-sm"></i>
          <input
            type="text"
            placeholder="Search by Material, Location..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-white/5 border border-white/10 rounded-lg pl-10 pr-4 py-2.5 text-sm text-white placeholder-[#6b7280] focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 transition-all"
          />
        </div>
        <select
          value={selectedAlertLevel}
          onChange={(e) => setSelectedAlertLevel(e.target.value)}
          className="bg-white/5 border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 min-w-[180px]"
        >
          <option value="ALL">All Alert Levels</option>
          <option value="CRITICAL">Critical</option>
          <option value="HIGH">High</option>
          <option value="MEDIUM">Medium</option>
          <option value="LOW">Low</option>
        </select>
        <select
          value={selectedNeedsReorder}
          onChange={(e) => setSelectedNeedsReorder(e.target.value)}
          className="bg-white/5 border border-white/10 rounded-lg px-4 py-2.5 text-sm text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 min-w-[180px]"
        >
          <option value="ALL">All Items</option>
          <option value="YES">Needs Reorder</option>
          <option value="NO">OK</option>
        </select>
      </div>

      {/* View Modes */}
      {viewMode === 'table' && (
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-white/5 border-b border-white/10">
                <tr>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Material</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Location</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Current Stock</th>
                  <th className="px-6 py-4 text-left text-xs font-medium text-[#9ca3af] uppercase tracking-wider">Reorder Point</th>
