                </tr>
              </thead>
              <tbody className="divide-y divide-white/10">
                {filteredAlerts.map((alert, index) => (
                  <motion.tr
                    key={alert.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.01 }}
                    className={`hover:bg-white/5 transition-colors ${
                      alert.alertLevel === 'CRITICAL' ? 'bg-red-500/5' : alert.alertLevel === 'HIGH' ? 'bg-yellow-500/5' : ''
                    }`}
                  >
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div>
                        <div className="text-sm font-medium text-white font-mono">{alert.materialNumber}</div>
                        <div className="text-xs text-[#9ca3af]">{alert.materialDescription}</div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-white font-mono">{alert.storageLocation}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div
                        className={`text-sm font-medium ${
                          alert.currentStock < alert.reorderPoint
                            ? 'text-red-400'
                            : alert.currentStock < alert.reorderPoint * 1.5
                            ? 'text-yellow-400'
                            : 'text-white'
                        }`}
                      >
                        {alert.currentStock.toFixed(2)} {alert.unit}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm text-white">{alert.reorderPoint.toFixed(2)} {alert.unit}</div>
