                    <td className="px-6 py-4 whitespace-nowrap">
                      <div
                        className={`text-sm font-medium ${
                          alert.daysOfStock < 7
                            ? 'text-red-400'
                            : alert.daysOfStock < 14
                            ? 'text-yellow-400'
                            : 'text-white'
                        }`}
                      >
                        {alert.daysOfStock} days
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span
                        className={`px-2 py-1 rounded text-xs font-medium ${
                          alert.alertLevel === 'CRITICAL'
                            ? 'bg-red-500/20 text-red-400 border border-red-500/30'
                            : alert.alertLevel === 'HIGH'
                            ? 'bg-orange-500/20 text-orange-400 border border-orange-500/30'
                            : alert.alertLevel === 'MEDIUM'
                            ? 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/30'
                            : 'bg-green-500/20 text-green-400 border border-green-500/30'
                        }`}
                      >
                        {alert.alertLevel}
                      </span>
                      {alert.needsReorder && (
                        <div className="mt-1">
                          <i className="ri-shopping-cart-line text-red-400 text-xs"></i>
                          <span className="text-xs text-red-400 ml-1">Reorder</span>
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {alert.needsReorder && (
                        <div className="text-sm text-cyan-400 font-medium">
                          {alert.suggestedOrderQty.toFixed(0)} {alert.unit}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <button
                        onClick={() => {
                          setSelectedAlert(alert)
                          setShowViewModal(true)
                        }}
                        className="p-2 bg-cyan-600/20 text-cyan-400 border border-cyan-500/30 rounded hover:bg-cyan-600/30 transition-colors"
                      >
                        <i className="ri-eye-line"></i>
                      </button>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {viewMode === 'grid' && (
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredAlerts.map((alert, index) => (
