          </div>
        )}
      </Modal>
    </PageTemplate>
  )
}

'use client'

import { useState, useMemo, useEffect } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import Tooltip from '@/components/Tooltip'
import Modal from '@/components/Modal'
import { generateTasks } from '@/utils/mockDataGenerators'
import { format } from 'date-fns'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer } from 'recharts'
import { realtimeSimulator, simulateKPIUpdates } from '@/utils/realtimeDataSimulator'

export default function TaskManagement() {
  const [tasks, setTasks] = useState(() => generateTasks(100))
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedStatus, setSelectedStatus] = useState<string>('ALL')
  const [selectedTaskType, setSelectedTaskType] = useState<string>('ALL')
  const [selectedPriority, setSelectedPriority] = useState<string>('ALL')
  const [viewMode, setViewMode] = useState<'table' | 'grid' | 'analytics'>('table')
  const [selectedTask, setSelectedTask] = useState<any>(null)
  const [showViewModal, setShowViewModal] = useState(false)
  const [realTimeEnabled, setRealTimeEnabled] = useState(true)
  const [realTimeStats, setRealTimeStats] = useState({
    totalTasks: 0,
    pending: 0,
    inProgress: 0,
    completed: 0,
  })

  const filteredTasks = useMemo(() => {
    return tasks.filter((task) => {
      const matchesSearch =
        task.taskNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
        task.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        task.materialNumber?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        task.location.toLowerCase().includes(searchQuery.toLowerCase()) ||
        task.assignedToName?.toLowerCase().includes(searchQuery.toLowerCase())
      const matchesStatus = selectedStatus === 'ALL' || task.status === selectedStatus
      const matchesTaskType = selectedTaskType === 'ALL' || task.taskType === selectedTaskType
      const matchesPriority = selectedPriority === 'ALL' || task.priority === selectedPriority
      return matchesSearch && matchesStatus && matchesTaskType && matchesPriority
    })
  }, [tasks, searchQuery, selectedStatus, selectedTaskType, selectedPriority])

  const pendingTasks = useMemo(() => {
    return tasks.filter(t => t.status === 'PENDING' || t.status === 'ASSIGNED')
  }, [tasks])

  const statusStats = useMemo(() => {
    const stats: Record<string, number> = {}
    tasks.forEach(task => {
      stats[task.status] = (stats[task.status] || 0) + 1
    })
    return stats
  }, [tasks])

  const taskTypeStats = useMemo(() => {
    const stats: Record<string, number> = {}
    tasks.forEach(task => {
      stats[task.taskType] = (stats[task.taskType] || 0) + 1
    })
    return stats
  }, [tasks])

  const chartData = useMemo(() => {
    return Object.entries(statusStats).map(([status, count]) => ({
      status: status.replace(/_/g, ' '),
      count,
    }))
  }, [statusStats])

  const taskTypeData = useMemo(() => {
    return Object.entries(taskTypeStats).map(([type, count]) => ({
      type: type.replace(/_/g, ' '),
      count,
    }))
  }, [taskTypeStats])

  const aggregateStats = useMemo(() => {
    return {
      totalTasks: tasks.length,
      pending: pendingTasks.length,
      inProgress: tasks.filter(t => t.status === 'IN_PROGRESS').length,
      completed: tasks.filter(t => t.status === 'COMPLETED').length,
    }
  }, [tasks.length, pendingTasks.length, tasks])

  useEffect(() => {
    if (!realTimeEnabled) return

    const unsubscribe = realtimeSimulator.subscribe('task-management-stats', (data: typeof realTimeStats) => {
      setRealTimeStats(data)
    })

    const stop = realtimeSimulator.start('task-management-stats', () => ({
      totalTasks: aggregateStats.totalTasks,
      pending: simulateKPIUpdates(aggregateStats.pending, 0.1),
      inProgress: simulateKPIUpdates(aggregateStats.inProgress, 0.1),
      completed: simulateKPIUpdates(aggregateStats.completed, 0.05),
    }), 5000, true)

    return () => {
      unsubscribe()
      stop()
    }
  }, [realTimeEnabled, aggregateStats.totalTasks, aggregateStats.pending, aggregateStats.inProgress, aggregateStats.completed])

  const stats = [
    {
      label: 'Total Tasks',
      value: realTimeEnabled ? realTimeStats.totalTasks : aggregateStats.totalTasks,
      icon: 'ri-task-line',
      tooltip: 'Total warehouse tasks',
      trend: 'up' as const,
    },
    {
      label: 'Pending',
      value: realTimeEnabled ? realTimeStats.pending : aggregateStats.pending,
