/**
 * Edge Computing Page
 * 
 * Edge device management and offline capabilities
 * Modern, professional, sexy UI with full drill-down capabilities
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  Server,
  Cpu,
  Wifi,
  WifiOff,
  Zap,
  Settings,
  RefreshCw,
  Play,
  Pause,
  Download,
  Upload,
  Activity,
  AlertCircle,
  Filter,
  Search,
  Clock,
  CheckCircle,
  XCircle,
  AlertTriangle,
} from 'lucide-react'
import PageTemplate from '@/components/PageTemplate'
import type { EdgeDevice, EdgeApplication, EdgeDecision } from '@/lib/services/transportation'
import { logger } from '@/lib/services/observability/logger'
import { errorTrackingService } from '@/lib/services/observability/errorTracking'
import { apiFetch } from '@/utils/apiFetch'

export default function EdgeComputingPage() {
  const [devices, setDevices] = useState<EdgeDevice[]>([])
  const [selectedDevice, setSelectedDevice] = useState<EdgeDevice | null>(null)
  const [applications, setApplications] = useState<EdgeApplication[]>([])
  const [viewMode, setViewMode] = useState<'DEVICES' | 'APPLICATIONS' | 'DECISIONS'>('DEVICES')

  useEffect(() => {
    loadDevices()
  }, [])

  const loadDevices = async () => {
    try {
      const response = await apiFetch('/api/transportation/edge-computing')
      const data = await response.json()
      if (data.devices) {
        setDevices(data.devices)
        if (data.devices.length > 0 && !selectedDevice) {
          setSelectedDevice(data.devices[0])
          loadApplications(data.devices[0].id)
        }
      }
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error))
      logger.error('Error loading devices', err, {
        module: 'transportation',
        service: 'edge-computing',
      })
      errorTrackingService.captureException(err, {
        module: 'transportation',
        service: 'edge-computing',
      })
    }
  }

  const loadApplications = async (deviceId: string) => {
    try {
      const response = await apiFetch(`/api/transportation/edge-computing?deviceId=${deviceId}`)
      const data = await response.json()
      if (data.applications) {
        setApplications(data.applications)
      }
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error))
      logger.error('Error loading applications', err, {
        module: 'transportation',
        service: 'edge-computing',
      })
      errorTrackingService.captureException(err, {
        module: 'transportation',
        service: 'edge-computing',
      })
    }
  }

  const updateDeviceStatus = async (deviceId: string, status: EdgeDevice['status']) => {
    try {
      await apiFetch('/api/transportation/edge-computing', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'update-status',
          deviceId,
          status,
        }),
      })
      loadDevices()
    } catch (error) {
      const err = error instanceof Error ? error : new Error(String(error))
      logger.error('Error updating status', err, {
        module: 'transportation',
        service: 'edge-computing',
      })
      errorTrackingService.captureException(err, {
        module: 'transportation',
        service: 'edge-computing',
      })
    }
  }

  return (
    <PageTemplate
      title="Edge Computing"
      description="Edge device management with offline capabilities and local decision-making"
      icon="ri-server-line"
      stats={[
        { label: 'Devices', value: devices.length, icon: 'ri-server-line' },
        { label: 'Online', value: devices.filter((d) => d.status === 'ONLINE').length, icon: 'ri-wifi-line' },
        { label: 'Applications', value: applications.length, icon: 'ri-apps-line' },
        { label: 'Offline Capable', value: devices.filter((d) => d.status === 'OFFLINE').length, icon: 'ri-wifi-off-line' },
      ]}
      actions={
        <div className="flex items-center gap-3">
          <button className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition flex items-center gap-2">
            <Settings className="w-4 h-4" />
            Settings
          </button>
        </div>
      }
    >
      <div className="space-y-6">
        {/* View Mode Toggle */}
        <div className="flex items-center gap-2 bg-white dark:bg-gray-800 rounded-lg p-1 border border-gray-200 dark:border-gray-700">
          {[
            { id: 'DEVICES', label: 'Devices', icon: Server },
            { id: 'APPLICATIONS', label: 'Applications', icon: Cpu },
            { id: 'DECISIONS', label: 'Decisions', icon: Activity },
          ].map((mode) => (
            <button
              key={mode.id}
              onClick={() => setViewMode(mode.id as any)}
              className={`flex-1 px-4 py-2 rounded-md text-sm font-medium transition ${
                viewMode === mode.id
                  ? 'bg-blue-500 text-white shadow-lg'
                  : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
              }`}
            >
              <mode.icon className="w-4 h-4 inline mr-2" />
              {mode.label}
            </button>
          ))}
        </div>

        {/* Devices View */}
        {viewMode === 'DEVICES' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {devices.map((device) => (
              <DeviceCard
                key={device.id}
                device={device}
                onClick={() => {
                  setSelectedDevice(device)
                  loadApplications(device.id)
                }}
                onStatusChange={(status) => updateDeviceStatus(device.id, status)}
              />
            ))}
          </div>
        )}

        {/* Applications View */}
        {viewMode === 'APPLICATIONS' && selectedDevice && (
          <div className="space-y-4">
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
              <h3 className="text-xl font-bold mb-4">Applications on {selectedDevice.name}</h3>
              <div className="space-y-3">
                {applications.map((app) => (
                  <ApplicationCard key={app.id} application={app} />
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Decisions View */}
        {viewMode === 'DECISIONS' && <EdgeDecisionLog selectedDevice={selectedDevice} />}
      </div>
    </PageTemplate>
  )
}

function DeviceCard({
  device,
  onClick,
  onStatusChange,
}: {
  device: EdgeDevice
  onClick: () => void
  onStatusChange: (status: EdgeDevice['status']) => void
}) {
  return (
    <motion.div
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.98 }}
      className="bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700 p-6 cursor-pointer"
      onClick={onClick}
    >
      <div className="flex items-center justify-between mb-4">
        <div className="w-12 h-12 rounded-lg bg-gradient-to-br from-blue-500 to-purple-500 flex items-center justify-center">
          <Server className="w-6 h-6 text-white" />
        </div>
        <StatusBadge status={device.status} />
      </div>
      <h4 className="font-bold mb-2">{device.name}</h4>
      <p className="text-sm text-gray-500 mb-4">{device.type}</p>
      <div className="space-y-2 text-sm mb-4">
        <div className="flex items-center justify-between">
          <span className="text-gray-600 dark:text-gray-400">Capabilities</span>
          <span className="font-medium">{device.capabilities.length}</span>
        </div>
        <div className="flex items-center justify-between">
          <span className="text-gray-600 dark:text-gray-400">Last Seen</span>
          <span className="font-medium">{new Date(device.lastSeen).toLocaleTimeString()}</span>
        </div>
      </div>
      <div className="flex items-center gap-2 pt-4 border-t border-gray-200 dark:border-gray-700">
        {device.status === 'ONLINE' ? (
