        const coords = zone.geometry.coordinates as number[][]
        center = { lat: coords[0]?.[0] || 0, lng: coords[0]?.[1] || 0 }
      }
      return {
        id: zone.id,
        location: {
          address: zone.name,
          city: '',
          country: '',
          coordinates: center,
