            <label className="block text-sm font-medium mb-2">Select Model</label>
            <select
              value={selectedModel?.id || ''}
              onChange={(e) => {
                const model = models.find((m) => m.id === e.target.value)
                setSelectedModel(model || null)
              }}
              className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700"
            >
              {models.map((model) => (
                <option key={model.id} value={model.id}>
                  {model.name} ({model.nodes.length} nodes, {model.links.length} links)
                </option>
              ))}
            </select>
          </div>
        )}

        {/* View Mode Toggle */}
        <div className="flex items-center gap-2 bg-white dark:bg-gray-800 rounded-lg p-1 border border-gray-200 dark:border-gray-700">
          {[
            { id: 'VISUALIZATION', label: 'Visualization', icon: Network },
            { id: 'METRICS', label: 'Metrics', icon: BarChart3 },
            { id: 'OPTIMIZATION', label: 'Optimization', icon: Target },
          ].map((mode) => (
            <button
              key={mode.id}
              onClick={() => setViewMode(mode.id as any)}
              className={`flex-1 px-4 py-2 rounded-md text-sm font-medium transition ${
                viewMode === mode.id
                  ? 'bg-blue-500 text-white shadow-lg'
                  : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700'
              }`}
            >
              <mode.icon className="w-4 h-4 inline mr-2" />
              {mode.label}
            </button>
          ))}
        </div>

        {/* Content */}
        {viewMode === 'VISUALIZATION' && selectedModel && (
          <NetworkGraphVisualization
            model={selectedModel}
            onNodeClick={(node) => {
              logger.debug('Node clicked', undefined, {
                module: 'transportation',
                service: 'network-modeling',
                nodeId: node.id,
              })
            }}
            onLinkClick={(link) => {
              logger.debug('Link clicked', undefined, {
                module: 'transportation',
                service: 'network-modeling',
                linkId: link.id,
              })
            }}
          />
        )}

        {viewMode === 'METRICS' && selectedModel && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <MetricCard
              title="Total Cost"
              value={`$${selectedModel.nodes.reduce((sum, n) => sum + n.costs.fixed, 0).toLocaleString()}`}
              icon={TrendingUp}
              color="green"
            />
            <MetricCard
              title="Total Distance"
              value={`${selectedModel.links.reduce((sum, l) => sum + l.distance, 0).toLocaleString()} km`}
              icon={MapPin}
              color="blue"
            />
            <MetricCard
              title="Average Reliability"
              value={`${(selectedModel.links.reduce((sum, l) => sum + l.reliability, 0) / selectedModel.links.length).toFixed(1)}%`}
              icon={Target}
              color="purple"
            />
            <MetricCard
              title="Network Efficiency"
              value={optimizationResult?.metrics.networkEfficiency.toFixed(1) + '%' || 'N/A'}
              icon={Zap}
              color="orange"
            />
          </div>
        )}

        {viewMode === 'OPTIMIZATION' && optimizationResult && (
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-bold mb-6">Optimization Results</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
              <div>
                <label className="text-xs text-gray-500">Total Cost</label>
                <p className="text-2xl font-bold">${optimizationResult.metrics.totalCost.toLocaleString()}</p>
              </div>
              <div>
                <label className="text-xs text-gray-500">Total Distance</label>
                <p className="text-2xl font-bold">{optimizationResult.metrics.totalDistance.toLocaleString()} km</p>
              </div>
              <div>
                <label className="text-xs text-gray-500">Efficiency</label>
                <p className="text-2xl font-bold">{optimizationResult.metrics.networkEfficiency.toFixed(1)}%</p>
              </div>
              <div>
                <label className="text-xs text-gray-500">Coverage</label>
                <p className="text-2xl font-bold">{optimizationResult.metrics.coverage.toFixed(1)}%</p>
              </div>
            </div>

            {optimizationResult.recommendations.length > 0 && (
              <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-4 border border-blue-200 dark:border-blue-800">
                <h4 className="font-bold mb-2">Recommendations</h4>
                <ul className="space-y-1">
                  {optimizationResult.recommendations.map((rec, idx) => (
                    <li key={idx} className="text-sm">• {rec}</li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}
      </div>
    </PageTemplate>
  )
}

function MetricCard({ title, value, icon: Icon, color }: any) {
  const colorClasses = {
    green: 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800 text-green-600 dark:text-green-400',
    blue: 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-600 dark:text-blue-400',
    purple: 'bg-purple-50 dark:bg-purple-900/20 border-purple-200 dark:border-purple-800 text-purple-600 dark:text-purple-400',
    orange: 'bg-orange-50 dark:bg-orange-900/20 border-orange-200 dark:border-orange-800 text-orange-600 dark:text-orange-400',
  }

  return (
    <div className={`rounded-lg p-4 border ${colorClasses[color as keyof typeof colorClasses]}`}>
      <div className="flex items-center gap-2 mb-2">
        <Icon className="w-4 h-4" />
        <span className="text-sm font-medium">{title}</span>
      </div>
      <div className="text-2xl font-bold">{value}</div>
    </div>
  )
}

/**
 * Pricing Intelligence
 * 
 * Comprehensive pricing intelligence dashboard with market rates, trends, forecasts, and recommendations
 * Module: tms
 */

'use client'

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import { ErrorBoundary } from '@/components/ErrorBoundary'
import { PremiumLoader } from '@/components/loading'
import PricingIntelligencePanel from '@/components/transportation/PricingIntelligencePanel'
import { apiFetch } from '@/utils/apiFetch'
import type { PricingIntelligence, Location, TransportMode, ShipmentType } from '@/types/tms'
import { RiMoneyDollarCircleLine, RiMapPinLine, RiShipLine, RiCalendarLine } from 'react-icons/ri'

function TransportationPricingPageContent() {
  const [loading, setLoading] = useState(false)
  const [intelligence, setIntelligence] = useState<PricingIntelligence | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Form state
  const [origin, setOrigin] = useState<Location>({ city: 'Riyadh', country: 'Saudi Arabia', code: 'RUH' })
  const [destination, setDestination] = useState<Location>({ city: 'Jeddah', country: 'Saudi Arabia', code: 'JED' })
  const [mode, setMode] = useState<TransportMode>('ROAD')
  const [type, setType] = useState<ShipmentType>('FULL_TRUCKLOAD')
  const [weight, setWeight] = useState(1000)
  const [volume, setVolume] = useState(10)
  const [value, setValue] = useState(50000)

  const fetchPricingIntelligence = async () => {
    try {
      setLoading(true)
      setError(null)

      const response = await apiFetch('/api/transportation/pricing-intelligence', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          origin,
          destination,
          mode,
          type,
          cargo: {
            weight,
            volume,
            value,
            currency: 'SAR'
          }
        })
      })

      if (!response.ok) {
        throw new Error(`Failed to fetch pricing intelligence: ${response.statusText}`)
      }

      const data = await response.json()
      setIntelligence(data)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load pricing intelligence')
      console.error('Error fetching pricing intelligence:', err)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    // Auto-fetch on mount
    fetchPricingIntelligence()
  }, [])

  if (loading && !intelligence) {
    return (
      <PageTemplate 
        title="Pricing Intelligence" 
        description="Market rates, trends, forecasts, and recommendations"
        icon="ri-money-dollar-circle-line"
      >
        <div className="flex items-center justify-center min-h-[400px]">
          <PremiumLoader 
            message="Analyzing market rates..." 
            size="lg" 
            variant="default"
          />
        </div>
      </PageTemplate>
    )
  }

  return (
    <PageTemplate 
      title="Pricing Intelligence" 
      description="Market rates, trends, forecasts, and recommendations"
      icon="ri-money-dollar-circle-line"
    >
      <div className="space-y-6">
        {/* Search Form */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 shadow-sm"
        >
          <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <RiMoneyDollarCircleLine className="w-5 h-5" />
            Pricing Analysis Request
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Origin */}
            <div>
              <label className="block text-sm font-medium mb-2">Origin</label>
              <input
                type="text"
                value={origin.city}
                onChange={(e) => setOrigin({ ...origin, city: e.target.value })}
                placeholder="City"
                className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700"
              />
            </div>

            {/* Destination */}
            <div>
              <label className="block text-sm font-medium mb-2">Destination</label>
              <input
                type="text"
                value={destination.city}
                onChange={(e) => setDestination({ ...destination, city: e.target.value })}
                placeholder="City"
                className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700"
              />
            </div>

            {/* Mode */}
            <div>
              <label className="block text-sm font-medium mb-2">Transport Mode</label>
              <select
                value={mode}
                onChange={(e) => setMode(e.target.value as TransportMode)}
                className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700"
              >
                <option value="ROAD">Road</option>
                <option value="AIR">Air</option>
                <option value="SEA">Sea</option>
                <option value="RAIL">Rail</option>
              </select>
            </div>

            {/* Type */}
            <div>
              <label className="block text-sm font-medium mb-2">Shipment Type</label>
              <select
                value={type}
                onChange={(e) => setType(e.target.value as ShipmentType)}
                className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700"
              >
                <option value="FULL_TRUCKLOAD">Full Truckload</option>
                <option value="LESS_THAN_TRUCKLOAD">LTL</option>
                <option value="PARCEL">Parcel</option>
              </select>
            </div>

            {/* Weight */}
            <div>
              <label className="block text-sm font-medium mb-2">Weight (kg)</label>
              <input
                type="number"
                value={weight}
                onChange={(e) => setWeight(Number(e.target.value))}
                className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700"
              />
            </div>

            {/* Volume */}
            <div>
              <label className="block text-sm font-medium mb-2">Volume (m³)</label>
              <input
                type="number"
                value={volume}
                onChange={(e) => setVolume(Number(e.target.value))}
                className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700"
              />
            </div>

            {/* Value */}
            <div>
              <label className="block text-sm font-medium mb-2">Value (SAR)</label>
              <input
                type="number"
                value={value}
                onChange={(e) => setValue(Number(e.target.value))}
                className="w-full px-3 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700"
              />
            </div>

            {/* Analyze Button */}
            <div className="flex items-end">
              <button
                onClick={fetchPricingIntelligence}
                disabled={loading}
                className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {loading ? 'Analyzing...' : 'Analyze Pricing'}
              </button>
            </div>
          </div>
        </motion.div>

        {/* Error Message */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
            <p className="text-red-800 dark:text-red-200">{error}</p>
          </div>
        )}

        {/* Pricing Intelligence Panel */}
        {intelligence && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <PricingIntelligencePanel intelligence={intelligence} />
          </motion.div>
        )}

        {/* Empty State */}
        {!intelligence && !loading && !error && (
          <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700">
            <RiMoneyDollarCircleLine className="w-16 h-16 mx-auto text-gray-400 mb-4" />
            <p className="text-gray-600 dark:text-gray-400">
              Enter shipment details and click "Analyze Pricing" to get pricing intelligence
            </p>
          </div>
        )}
      </div>
    </PageTemplate>
  )
}

export default function TransportationPricingPage() {
  return (
    <ErrorBoundary
      fallback={
        <PageTemplate 
          title="Pricing Intelligence" 
          description="Market rates, trends, forecasts, and recommendations"
          icon="ri-money-dollar-circle-line"
        >
          <div className="text-center py-12">
            <p className="text-red-600">Something went wrong. Please refresh the page.</p>
          </div>
        </PageTemplate>
      }
    >
      <TransportationPricingPageContent />
    </ErrorBoundary>
  )
}

/**
