'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  RiBarChartLine,
  RiShieldCheckLine,
  RiAlertLine,
  RiFileTextLine,
  RiArrowUpLine,
  RiArrowDownLine,
  RiEyeLine,
  RiDownloadLine,
  RiTimeLine,
  RiMoneyDollarCircleLine,
  RiFileWarningLine,
  RiCheckboxCircleLine,
} from 'react-icons/ri'
import { BoardBrief, BoardSignal, AdversarialInsight, BoardRecommendation } from '@/types/truth-engine'

export default function TruthBoardBriefPage() {
  const [brief, setBrief] = useState<BoardBrief | null>(null)
  const [loading, setLoading] = useState(true)
  const [selectedSignal, setSelectedSignal] = useState<BoardSignal | null>(null)
  const [selectedInsight, setSelectedInsight] = useState<AdversarialInsight | null>(null)
  const [period, setPeriod] = useState({
    start: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    end: new Date().toISOString().split('T')[0],
  })

  useEffect(() => {
    loadBoardBrief()
  }, [period])

  const loadBoardBrief = async () => {
    try {
      setLoading(true)
      const response = await fetch(
        `/api/truth-engine/board-brief?tenantId=default&periodStart=${period.start}&periodEnd=${period.end}`
      )
      const data = await response.json()
      if (data.success) {
        setBrief(data.brief)
      }
    } catch (error) {
      console.error('Error loading board brief:', error)
    } finally {
      setLoading(false)
    }
  }

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'CRITICAL':
        return 'bg-red-500/20 border-red-500 text-red-400'
      case 'HIGH':
        return 'bg-orange-500/20 border-orange-500 text-orange-400'
      case 'MEDIUM':
        return 'bg-yellow-500/20 border-yellow-500 text-yellow-400'
      default:
        return 'bg-blue-500/20 border-blue-500 text-blue-400'
    }
  }

  const getSignalIcon = (type: string) => {
    switch (type) {
      case 'margin_mirage':
        return <RiMoneyDollarCircleLine className="text-yellow-500" />
      case 'detention_drift':
        return <RiTimeLine className="text-orange-500" />
      case 'compliance_debt':
        return <RiFileWarningLine className="text-red-500" />
      case 'term_creep':
        return <RiArrowUpLine className="text-purple-500" />
      default:
        return <RiAlertLine className="text-blue-500" />
    }
  }

  const getPersonaColor = (persona: string) => {
    switch (persona) {
      case 'regulator':
        return 'bg-blue-500/20 border-blue-500 text-blue-400'
      case 'cfo':
        return 'bg-green-500/20 border-green-500 text-green-400'
      case 'competitor':
        return 'bg-purple-500/20 border-purple-500 text-purple-400'
      case 'litigator':
        return 'bg-red-500/20 border-red-500 text-red-400'
      default:
        return 'bg-gray-500/20 border-gray-500 text-gray-400'
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 p-8">
        <div className="max-w-7xl mx-auto">
          <div className="animate-pulse space-y-4">
            <div className="h-8 bg-gray-700 rounded w-1/3"></div>
            <div className="h-64 bg-gray-700 rounded"></div>
          </div>
        </div>
      </div>
