                          <span className="text-gray-400 capitalize">{signal.trend}</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>

          {/* Adversarial Insights & Recommendations */}
          <div className="space-y-6">
            {/* Adversarial Insights */}
            <div>
              <h2 className="text-2xl font-bold text-white mb-4">Adversarial Insights</h2>
              <div className="space-y-3">
                {brief.adversarialInsights.map((insight, index) => (
                  <motion.div
                    key={insight.id}
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: index * 0.1 }}
                    className={`bg-gray-800/50 backdrop-blur-sm rounded-lg p-4 border ${getPersonaColor(insight.persona)} cursor-pointer hover:scale-[1.02] transition-all`}
                    onClick={() => setSelectedInsight(insight)}
                  >
                    <div className="flex items-start gap-3">
                      <div className="mt-1">
                        <RiShieldCheckLine />
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-xs font-semibold uppercase text-gray-400">
                            {insight.persona}
                          </span>
                          <span className={`px-2 py-1 rounded text-xs ${getSeverityColor(insight.severity)}`}>
                            {insight.severity}
                          </span>
                        </div>
                        <p className="text-white text-sm">{insight.insight}</p>
                        <div className="mt-2 flex items-center gap-2 text-xs text-gray-400">
                          <RiFileTextLine />
                          <span>{insight.evidenceRefs.length} Evidence</span>
                        </div>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>

            {/* Recommendations */}
            <div>
              <h2 className="text-2xl font-bold text-white mb-4">Recommendations</h2>
              <div className="space-y-3">
                {brief.recommendations.map((rec, index) => (
                  <motion.div
                    key={rec.id}
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: (brief.adversarialInsights.length + index) * 0.1 }}
                    className="bg-gray-800/50 backdrop-blur-sm rounded-lg p-4 border border-gray-700"
                  >
                    <div className="flex items-start gap-3">
                      <RiCheckboxCircleLine className="text-green-500 mt-1" />
                      <div className="flex-1">
                        <div className="flex items-center justify-between mb-1">
                          <h4 className="text-white font-semibold text-sm">{rec.title}</h4>
                          <span className={`px-2 py-1 rounded text-xs ${getSeverityColor(rec.priority)}`}>
                            {rec.priority}
                          </span>
                        </div>
                        <p className="text-gray-400 text-xs mb-2">{rec.description}</p>
                        <div className="flex items-center gap-4 text-xs text-gray-500">
                          <span>Impact: {rec.impact}</span>
                          <span>Effort: {rec.effort}</span>
                        </div>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
