 * Adapted for BlueDXP Platform (App Router)
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import PageTemplate from '@/components/PageTemplate'
import ModuleLinks from '@/components/ModuleLinks'
import { getISOIMSLinks } from '@/utils/moduleInterconnectivity'
import UserSelector from '@/components/ims/UserSelector'

interface User {
  id: string
  name: string
  email: string
  fullName: string
  enabled: boolean
  role: string
  department?: string
  designation?: string
  lastLogin?: string
  creation?: string
  modified?: string
}

export default function UserManagementPage() {
  const [users, setUsers] = useState<User[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)
  const [selectedUser, setSelectedUser] = useState<User | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [filterRole, setFilterRole] = useState('all')
  const [newUser, setNewUser] = useState({
    email: '',
    fullName: '',
    role: 'Employee',
    department: '',
    designation: ''
  })

  useEffect(() => {
    fetchUsers()
  }, [])

  const fetchUsers = async () => {
    try {
      const response = await fetch('/api/erpnext/users')
      if (response.ok) {
        const data = await response.json()
        const transformedUsers = (data.users || data.data || []).map((user: any) => ({
          id: user.name || user.email,
          name: user.name || user.email,
          email: user.email,
          fullName: user.full_name || user.fullName || user.email,
          enabled: user.enabled !== false,
          role: user.role_profile_name || user.role || 'Employee',
          department: user.department || '',
          designation: user.designation || '',
          lastLogin: user.last_login || '',
          creation: user.creation || '',
          modified: user.modified || ''
        }))
        setUsers(transformedUsers)
      } else {
        // Use mock data for now
        setUsers(generateMockUsers())
      }
    } catch (error) {
      console.error('Error fetching users:', error)
      setUsers(generateMockUsers())
    } finally {
      setLoading(false)
    }
  }

  const generateMockUsers = (): User[] => {
    return [
      {
        id: 'user-001',
        name: 'b.albayaty@scsflex.com',
        email: 'b.albayaty@scsflex.com',
        fullName: 'Bashir Albayaty',
        enabled: true,
        role: 'System Manager',
        department: 'IT',
        designation: 'Platform Manager',
        lastLogin: new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString(),
        creation: new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toISOString()
      },
      {
        id: 'user-002',
        name: 'admin@scsflex.com',
        email: 'admin@scsflex.com',
        fullName: 'Admin User',
        enabled: true,
        role: 'Administrator',
        department: 'Management',
        designation: 'System Administrator',
        lastLogin: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
      },
      {
        id: 'user-003',
        name: 'manager@scsflex.com',
        email: 'manager@scsflex.com',
        fullName: 'Operations Manager',
        enabled: true,
        role: 'Operations Manager',
        department: 'Operations',
        designation: 'Operations Manager',
        lastLogin: new Date(Date.now() - 5 * 60 * 60 * 1000).toISOString()
      }
    ]
  }

  const handleCreateUser = async () => {
    try {
      // In production, this would call ERPNext API
      const newUserData: User = {
        id: `user-${Date.now()}`,
        name: newUser.email,
        email: newUser.email,
        fullName: newUser.fullName,
        enabled: true,
        role: newUser.role,
        department: newUser.department,
        designation: newUser.designation,
        creation: new Date().toISOString()
      }
      
      setUsers([...users, newUserData])
      setShowCreateModal(false)
      setNewUser({
        email: '',
        fullName: '',
        role: 'Employee',
        department: '',
        designation: ''
      })
    } catch (error) {
      console.error('Error creating user:', error)
    }
  }

  const handleEditUser = async (user: User) => {
    try {
      // In production, this would call ERPNext API
      const updatedUsers = users.map(u => 
        u.id === user.id ? { ...u, ...user } : u
      )
      setUsers(updatedUsers)
      setShowEditModal(false)
      setSelectedUser(null)
    } catch (error) {
      console.error('Error updating user:', error)
    }
  }

  const handleToggleUser = async (user: User) => {
    try {
      const updatedUsers = users.map(u => 
        u.id === user.id ? { ...u, enabled: !u.enabled } : u
      )
      setUsers(updatedUsers)
    } catch (error) {
      console.error('Error toggling user:', error)
    }
  }

  const filteredUsers = users.filter(user => {
    const matchesSearch = 
      user.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      user.fullName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      user.role.toLowerCase().includes(searchQuery.toLowerCase())
    
    const matchesRole = filterRole === 'all' || user.role === filterRole
    
    return matchesSearch && matchesRole
  })

  const roles = Array.from(new Set(users.map(u => u.role)))

  return (
    <PageTemplate
      title="User Management"
      description="Manage system users, roles, and permissions. Track user activity and access control."
      icon="ri-user-settings-line"
      stats={[
        {
          label: 'Total Users',
          value: users.length,
          icon: 'ri-user-line'
        },
        {
          label: 'Active Users',
          value: users.filter(u => u.enabled).length,
          icon: 'ri-user-heart-line'
