                        >
                          <i className={user.enabled ? 'ri-user-unfollow-line' : 'ri-user-follow-line'}></i>
                        </button>
                      </div>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Create User Modal */}
      {showCreateModal && (
