'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import PageTemplate from '@/components/PageTemplate'
import { Route, ArrowRight, Clock, Package, Plus } from 'lucide-react'
import type { NetworkRoute } from '@/lib/services/warehouse-network'

export default function RoutesPage() {
  const router = useRouter()
  const [routes, setRoutes] = useState<NetworkRoute[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedNetwork, setSelectedNetwork] = useState<string>('network-1')

  useEffect(() => {
    loadRoutes()
  }, [selectedNetwork])

  const loadRoutes = async () => {
    setLoading(true)
    try {
      const response = await fetch(`/api/warehouse-network/routes?networkId=${selectedNetwork}`)
      const result = await response.json()
      if (result.success) {
        setRoutes(result.data)
      }
    } catch (error) {
      console.error('Failed to load routes:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <PageTemplate
      title="Network Routes"
      description="Manage routes between warehouse networks"
      icon="ri-route-line"
    >
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-bold text-slate-800">Network Routes</h2>
          <button
            onClick={() => router.push('/warehouse-network/routes/new')}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition flex items-center space-x-2"
          >
            <Plus className="w-4 h-4" />
            <span>Create Route</span>
          </button>
        </div>

        {loading ? (
          <div className="space-y-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="bg-white rounded-xl shadow-lg p-6 animate-pulse">
                <div className="h-4 bg-slate-200 rounded w-1/4 mb-4"></div>
                <div className="h-4 bg-slate-200 rounded w-1/2"></div>
              </div>
            ))}
          </div>
        ) : routes.length === 0 ? (
          <div className="bg-white rounded-xl shadow-lg p-12 text-center">
            <Route className="w-16 h-16 text-slate-300 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-slate-800 mb-2">No routes found</h3>
            <p className="text-slate-500 mb-6">Create routes to connect warehouses in your network</p>
            <button
              onClick={() => router.push('/warehouse-network/routes/new')}
              className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
            >
              Create Route
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {routes.map((route) => (
              <div
                key={route.id}
                className="bg-white rounded-xl shadow-lg p-6 hover:shadow-xl transition"
              >
