  useEffect(() => {
    loadWarehouseData()

    // Set up real-time IoT updates via polling (fallback)
    const interval = setInterval(() => {
      updateIoTData()
    }, 5000)

    // Try to connect to WebSocket for real-time updates
    if (typeof window !== 'undefined') {
      try {
        const wsUrl = process.env.NEXT_PUBLIC_WEBSOCKET_URL || 
                     (window.location.protocol === 'https:' ? 'wss:' : 'ws:') + 
                     '//' + window.location.host + '/api/realtime'

        const ws = new WebSocket(wsUrl)

        ws.onopen = () => {
          logger.info('WebSocket connected for warehouse updates', undefined, {
            module: 'warehouse',
            service: 'realtime',
            warehouseId,
          })
          setIsRealtimeConnected(true)

          // Subscribe to warehouse updates
          ws.send(JSON.stringify({
            type: 'subscribe',
            channel: `warehouse:${warehouseId}`
          }))
        }

        ws.onmessage = (event) => {
          try {
            const data = JSON.parse(event.data)
            if (data.type === 'warehouse_update' && data.warehouseId === warehouseId) {
              // Update warehouse data in real-time
              if (data.warehouse) {
                setWarehouse(data.warehouse)
              }
              if (data.sensors) {
                setSensors(data.sensors)
              }
            } else if (data.type === 'sensor_update' && data.warehouseId === warehouseId) {
              // Update specific sensor
              setSensors(prev => prev.map(s => 
                s.id === data.sensor.id ? { ...s, ...data.sensor } : s
              ))
            }
          } catch (error) {
            const err = error instanceof Error ? error : new Error(String(error))
            logger.error('Error parsing WebSocket message', err, {
              module: 'warehouse',
              service: 'realtime',
              warehouseId,
            })
            errorTrackingService.captureException(err, {
              module: 'warehouse',
              service: 'realtime',
            })
          }
        }

        ws.onerror = (error) => {
          const err = error instanceof Error ? error : new Error(String(error))
          logger.error('WebSocket error', err, {
            module: 'warehouse',
            service: 'realtime',
            warehouseId,
          })
          errorTrackingService.captureException(err, {
            module: 'warehouse',
            service: 'realtime',
          })
          setIsRealtimeConnected(false)
        }

        ws.onclose = () => {
          logger.info('WebSocket disconnected', undefined, {
            module: 'warehouse',
            service: 'realtime',
            warehouseId,
          })
          setIsRealtimeConnected(false)
        }

        return () => {
          ws.close()
          clearInterval(interval)
        }
      } catch (error) {
        logger.warn('WebSocket not available, using polling fallback', error instanceof Error ? error : new Error(String(error)), {
          module: 'warehouse',
          service: 'realtime',
          warehouseId,
        })
        return () => clearInterval(interval)
      }
    }

