/**
 * Google OAuth Callback Page
 */

'use client'

import { useEffect, useState } from 'react'
import { useSearchParams, useRouter } from 'next/navigation'

export default function GoogleCallbackPage() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const [status, setStatus] = useState<'processing' | 'success' | 'error'>('processing')
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    const code = searchParams.get('code')
    const errorParam = searchParams.get('error')

    if (errorParam) {
      setStatus('error')
      setError(errorParam)
      return
    }

    if (code) {
      handleCallback(code)
    }
  }, [searchParams])

  const handleCallback = async (code: string) => {
    try {
      const redirectUri = `${window.location.origin}/workspace/integrations/google/callback`
      const response = await fetch('/api/v1/workspace/integrations/google', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          code,
          redirectUri,
          scopes: [
            'https://www.googleapis.com/auth/calendar.readonly',
            'https://www.googleapis.com/auth/drive.readonly',
            'https://www.googleapis.com/auth/gmail.readonly',
            'https://www.googleapis.com/auth/tasks.readonly',
          ],
        }),
      })

      if (response.ok) {
        setStatus('success')
        setTimeout(() => {
          router.push('/workspace')
        }, 2000)
      } else {
        setStatus('error')
        setError('Failed to connect Google Workspace')
      }
    } catch (error) {
      setStatus('error')
      setError(error instanceof Error ? error.message : 'Unknown error')
    }
  }

  return (
    <div className="min-h-screen bg-[#111827] flex items-center justify-center">
      <div className="text-center">
        {status === 'processing' && (
          <>
            <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
            <p className="text-white">Connecting Google Workspace...</p>
          </>
        )}

        {status === 'success' && (
          <>
            <i className="ri-checkbox-circle-fill text-6xl text-green-400 mb-4"></i>
            <p className="text-white text-lg mb-2">Successfully Connected!</p>
            <p className="text-[#9ca3af]">Redirecting to workspace...</p>
          </>
        )}

        {status === 'error' && (
          <>
            <i className="ri-error-warning-fill text-6xl text-red-400 mb-4"></i>
            <p className="text-white text-lg mb-2">Connection Failed</p>
            <p className="text-[#9ca3af] mb-4">{error}</p>
            <button
              onClick={() => router.push('/workspace')}
              className="bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white px-6 py-3 rounded-lg text-sm font-medium transition-colors"
            >
              Go to Workspace
            </button>
          </>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useMemo, useRef, useCallback, memo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useAuth } from '@/contexts/AuthContext'
import { ModuleId, FeatureId } from '@/types/user'
import { JobStatusWidget } from '@/components/jobs/JobStatusWidget'

interface NavItem {
  name: string
  href?: string
  icon: string
  description?: string
  badge?: string | number
  comingSoon?: boolean
  children?: NavItem[]
  moduleId?: ModuleId
  featureId?: FeatureId
  requiredAccess?: 'full' | 'partial' | 'read_only'
}

interface EnhancedSidebarProps {
  navStructure: NavItem[]
  isDarkMode: boolean
  sidebarOpen: boolean
  setSidebarOpen: (open: boolean) => void
  expandedMenus: Set<string>
  setExpandedMenus: (menus: Set<string> | ((prev: Set<string>) => Set<string>)) => void
  filteredNavStructure: NavItem[]
  appMode: 'logistics' | 'hazalyze'
  setAppMode: (mode: 'logistics' | 'hazalyze') => void
}

const EnhancedSidebar = memo(function EnhancedSidebar({
  navStructure,
  isDarkMode,
  sidebarOpen,
  setSidebarOpen,
  expandedMenus,
  setExpandedMenus,
  filteredNavStructure,
  appMode,
  setAppMode,
}: EnhancedSidebarProps) {
  const pathname = usePathname()
  const { user } = useAuth()
  const [searchQuery, setSearchQuery] = useState('')
  const [isExpanded, setIsExpanded] = useState(true) // Full width expansion
  const [isWideMode, setIsWideMode] = useState(false) // Extra wide mode
  const [recentItems, setRecentItems] = useState<NavItem[]>([])
  const [favorites, setFavorites] = useState<Set<string>>(new Set())
  const [hoveredItem, setHoveredItem] = useState<string | null>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)

  // Load favorites from localStorage
  useEffect(() => {
    const savedFavorites = localStorage.getItem('nav-favorites')
    if (savedFavorites) {
      setFavorites(new Set(JSON.parse(savedFavorites)))
    }

    const savedRecent = localStorage.getItem('nav-recent')
    if (savedRecent) {
      setRecentItems(JSON.parse(savedRecent))
    }
  }, [])

  // Track recent items - DEBOUNCED to avoid blocking navigation
  useEffect(() => {
    const currentItem = findNavItemByPath(filteredNavStructure, pathname)
    if (currentItem && currentItem.href) {
      // Update state immediately for UI responsiveness (non-blocking)
      setRecentItems((prev) => {
        const filtered = prev.filter((item) => item.href !== currentItem.href)
        const updated = [currentItem, ...filtered].slice(0, 5)

        // Defer localStorage write to avoid blocking navigation
        // Use requestIdleCallback for better performance
        if (typeof requestIdleCallback !== 'undefined') {
          requestIdleCallback(() => {
            try {
              localStorage.setItem('nav-recent', JSON.stringify(updated))
            } catch (e) {
              // Ignore storage errors
            }
          })
        } else {
          setTimeout(() => {
            try {
              localStorage.setItem('nav-recent', JSON.stringify(updated))
            } catch (e) {
              // Ignore storage errors
            }
          }, 0)
        }

        return updated
      })
    }
  }, [pathname, filteredNavStructure]) // findNavItemByPath is stable (useCallback with empty deps)

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Cmd/Ctrl + K to focus search
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        searchInputRef.current?.focus()
      }
      // Escape to close search
      if (e.key === 'Escape' && searchQuery) {
        setSearchQuery('')
        searchInputRef.current?.blur()
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [searchQuery])

  // IMPROVED: Enhanced fuzzy search with scoring
  const calculateSearchScore = useCallback((text: string, query: string): number => {
    const lowerText = text.toLowerCase().trim()
    const lowerQuery = query.toLowerCase().trim()

    if (!lowerQuery) return 0

    // Exact match - highest score
    if (lowerText === lowerQuery) return 100

    // Starts with query - very high score
    if (lowerText.startsWith(lowerQuery)) return 90

    // Contains query as whole word - high score
    const words = lowerText.split(/\s+/)
    if (words.some(word => word.startsWith(lowerQuery))) return 80

    // Contains query anywhere - medium score
    if (lowerText.includes(lowerQuery)) return 70

    // Fuzzy match (characters in order) - lower score
    let textIndex = 0
    let matchCount = 0
    for (let i = 0; i < lowerQuery.length; i++) {
      const char = lowerQuery[i]
      const foundIndex = lowerText.indexOf(char, textIndex)
      if (foundIndex === -1) return 0
      textIndex = foundIndex + 1
      matchCount++
    }

    // Calculate score based on how close characters are
    const proximity = textIndex - matchCount
    return Math.max(30, 60 - proximity * 5)
  }, [])

  // IMPROVED: Flatten with parent context
  const flattenNavItemsWithContext = useCallback((items: NavItem[], parentPath: string[] = []): Array<NavItem & { parentPath: string[] }> => {
    const result: Array<NavItem & { parentPath: string[] }> = []
    items.forEach((item) => {
      if (item.href) {
        result.push({ ...item, parentPath })
      }
      if (item.children) {
        const newParentPath = item.href ? [...parentPath, item.name] : parentPath
        result.push(...flattenNavItemsWithContext(item.children, newParentPath))
      }
    })
    return result
  }, [])

  // OPTIMIZED: Memoized find function
  const findNavItemByPath = useCallback((items: NavItem[], path: string): NavItem | null => {
    for (const item of items) {
      if (item.href === path) return item
      if (item.children) {
        const found = findNavItemByPath(item.children, path)
        if (found) return found
      }
    }
    return null
  }, [])

  // IMPROVED: Enhanced search results with scoring and highlighting
  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return []

    const query = searchQuery.trim()
    const allItems = flattenNavItemsWithContext(filteredNavStructure)

    // Calculate scores for all items
    const scoredItems = allItems.map((item) => {
      const nameScore = calculateSearchScore(item.name, query)
      const descScore = item.description ? calculateSearchScore(item.description, query) : 0
      const hrefScore = item.href ? calculateSearchScore(item.href, query) : 0
      const parentScore = item.parentPath.length > 0
        ? item.parentPath.reduce((sum, parent) => sum + calculateSearchScore(parent, query), 0) / item.parentPath.length
        : 0

      // Weighted score: name is most important, then description, then href, then parent
      const totalScore = (nameScore * 0.5) + (descScore * 0.3) + (hrefScore * 0.1) + (parentScore * 0.1)

      return {
        item,
        score: totalScore,
        matchType: nameScore > 0 ? 'name' : descScore > 0 ? 'description' : 'other'
      }
    })

    // Filter items with score > 0 and sort by score
    return scoredItems
      .filter(({ score }) => score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 15) // Increased limit for better results
      .map(({ item }) => item)
  }, [searchQuery, filteredNavStructure, flattenNavItemsWithContext, calculateSearchScore])

  // OPTIMIZED: Memoized toggle functions
  const toggleMenu = useCallback((menuName: string) => {
    setExpandedMenus((prev) => {
      const newSet = new Set(prev)
      if (newSet.has(menuName)) {
        newSet.delete(menuName)
      } else {
        newSet.add(menuName)
      }
      return newSet
    })
  }, [])

  const toggleFavorite = useCallback((item: NavItem, e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()

    if (!item.href) return

    setFavorites((prev) => {
      const newSet = new Set(prev)
      if (newSet.has(item.href!)) {
        newSet.delete(item.href!)
      } else {
        newSet.add(item.href!)
      }
      localStorage.setItem('nav-favorites', JSON.stringify(Array.from(newSet)))
      return newSet
    })
  }, [])

  // OPTIMIZED: Memoized check functions
  const isActive = useCallback((href: string) => pathname === href, [pathname])
  const isMenuExpanded = useCallback((name: string) => expandedMenus.has(name), [expandedMenus])

  const hasActiveChild = useCallback((item: NavItem): boolean => {
    if (item.href && isActive(item.href)) return true
    if (item.children) {
      return item.children.some((child) => hasActiveChild(child))
    }
    return false
  }, [isActive])

  // Render nav item
  const renderNavItem = (item: NavItem, level: number = 0) => {
    const hasChildren = item.children && item.children.length > 0
    const isExpanded = isMenuExpanded(item.name)
    const active = item.href ? isActive(item.href) : false
    const hasActive = hasActiveChild(item)
    const isFavorite = item.href ? favorites.has(item.href) : false
    const indent = level * 20

    return (
      <div key={item.name} className="mb-1">
        {hasChildren ? (
          <>
            <motion.button
              onClick={() => toggleMenu(item.name)}
              onHoverStart={() => setHoveredItem(item.name)}
              onHoverEnd={() => setHoveredItem(null)}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all group relative overflow-hidden ${hasActive
                  ? `${isDarkMode ? 'bg-gradient-to-r from-blue-600/30 to-cyan-600/20 text-white' : 'bg-blue-50 text-blue-700'} border-l-4 border-blue-500`
                  : `${isDarkMode ? 'text-[#9ca3af] hover:bg-[#374151]/50 hover:text-white' : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'}`
                }`}
              style={{ paddingLeft: `${16 + indent}px` }}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
            >
              {/* Hover glow effect */}
              <motion.div
                className="absolute inset-0 bg-gradient-to-r from-blue-500/0 via-cyan-500/10 to-blue-500/0"
                initial={{ x: '-100%' }}
                animate={{ x: hoveredItem === item.name ? '100%' : '-100%' }}
                transition={{ duration: 0.6 }}
              />

              <div className="flex items-center gap-3 flex-1 min-w-0 relative z-10">
                <motion.div
                  animate={{ rotate: isExpanded ? 0 : -90 }}
                  transition={{ duration: 0.2 }}
                >
                  <i className={`${item.icon} text-lg flex-shrink-0 ${hasActive ? 'text-blue-400' : isDarkMode ? 'text-[#6b7280] group-hover:text-white' : 'text-gray-400 group-hover:text-gray-700'}`}></i>
                </motion.div>
                <div className="flex-1 min-w-0 text-left">
                  <div className={`text-sm font-semibold truncate ${hasActive ? (isDarkMode ? 'text-white' : 'text-blue-700') : isDarkMode ? 'text-[#9ca3af] group-hover:text-white' : 'text-gray-600 group-hover:text-gray-900'}`}>
                    {item.name}
                  </div>
                  {item.description && (
                    <div className={`text-xs mt-0.5 truncate ${hasActive ? (isDarkMode ? 'text-blue-200' : 'text-blue-500') : isDarkMode ? 'text-[#6b7280] group-hover:text-[#9ca3af]' : 'text-gray-400 group-hover:text-gray-500'}`}>
                      {item.description}
                    </div>
                  )}
                </div>
                {item.badge && (
                  <span className="px-2 py-0.5 bg-blue-600 text-white text-xs font-medium rounded-full flex-shrink-0 animate-pulse">
                    {item.badge}
                  </span>
                )}
              </div>
              <motion.i
                className={`ri-arrow-${isExpanded ? 'down' : 'right'}-s-line text-sm transition-transform flex-shrink-0 ml-2 relative z-10 ${hasActive ? 'text-blue-300' : isDarkMode ? 'text-[#6b7280] group-hover:text-white' : 'text-gray-400 group-hover:text-gray-700'
                  }`}
                animate={{ rotate: isExpanded ? 0 : -90 }}
                transition={{ duration: 0.2 }}
              ></motion.i>
            </motion.button>
            <AnimatePresence>
              {isExpanded && (
                <motion.div
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: 'auto', opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={{ duration: 0.3, ease: 'easeInOut' }}
                  className="overflow-hidden"
                >
                  <div className="pl-4 pt-1 space-y-1">
                    {item.children?.map((child) => renderNavItem(child, level + 1))}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </>
        ) : (
          <Link
            href={item.href || '#'}
            prefetch={true}
            onMouseEnter={() => setHoveredItem(item.href || '')}
            onMouseLeave={() => setHoveredItem(null)}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all group relative overflow-hidden ${active
                ? `${isDarkMode ? 'bg-gradient-to-r from-blue-600 to-cyan-600 text-white' : 'bg-blue-600 text-white'} shadow-lg shadow-blue-500/30`
                : `${isDarkMode ? 'text-[#9ca3af] hover:bg-[#374151]/50 hover:text-white' : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'}`
              }`}
            style={{ paddingLeft: `${16 + indent}px` }}
          >
            {/* Active indicator */}
            {active && (
              <motion.div
                className="absolute left-0 top-0 bottom-0 w-1 bg-white rounded-r-full"
                layoutId="activeIndicator"
                transition={{ type: 'spring', stiffness: 500, damping: 30 }}
              />
            )}

            {/* Hover glow */}
            <motion.div
              className="absolute inset-0 bg-gradient-to-r from-blue-500/0 via-cyan-500/10 to-blue-500/0"
              initial={{ x: '-100%' }}
              animate={{ x: hoveredItem === item.href ? '100%' : '-100%' }}
              transition={{ duration: 0.6 }}
            />

            <i className={`${item.icon} text-lg flex-shrink-0 relative z-10 ${active ? 'text-white' : isDarkMode ? 'text-[#6b7280] group-hover:text-white' : 'text-gray-400 group-hover:text-gray-700'}`}></i>
            <div className="flex-1 min-w-0 relative z-10">
              <div className={`text-sm font-medium truncate ${active ? 'text-white' : isDarkMode ? 'text-[#9ca3af] group-hover:text-white' : 'text-gray-600 group-hover:text-gray-900'}`}>
                {item.name}
