type ModuleListResponse = {
  success: boolean
  data: Array<{
    id: string
    name: string
    description?: string
    category?: string
    routes: Array<{ path: string; title: string; icon?: string }>
  }>
}

function collectHrefs(items: NavItem[]): Set<string> {
  const hrefs = new Set<string>()
  const walk = (arr: NavItem[]) => {
    for (const item of arr) {
      if (item.href) hrefs.add(item.href)
      if (item.children?.length) walk(item.children)
    }
  }
  walk(items)
  return hrefs
}

function normalizeIcon(icon?: string): string {
  if (!icon) return 'ri-file-line'
  return icon.startsWith('ri-') ? icon : 'ri-file-line'
}

function buildAutoModulesNav(
  modules: ModuleListResponse['data'],
  existingHrefs: Set<string>
): NavItem | null {
  console.log(`[Layout] buildAutoModulesNav: ${modules.length} modules, ${existingHrefs.size} existing hrefs`)
  console.log(`[Layout] Module IDs:`, modules.map(m => `${m.id} (${m.name})`).join(', '))

  if (modules.length === 0) {
    console.error('[Layout] ERROR: No modules received in buildAutoModulesNav!')
    return null
  }

  const moduleItems: NavItem[] = modules
    .slice()
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((m) => {
      const allRoutes = m.routes || []
      const filteredRoutes = allRoutes
        // Don't show dynamic routes in sidebar (not clickable without params)
        .filter((r) => !r.path.includes('['))
        // Show all routes, even if they exist in default nav (mark duplicates)
        .map((r) => ({
          name: r.title || r.path,
          href: r.path,
          icon: normalizeIcon(r.icon),
          description: existingHrefs.has(r.path) ? `${r.path} (also in main nav)` : r.path,
          moduleId: m.id as unknown as ModuleId,
          badge: existingHrefs.has(r.path) ? 'DUP' : undefined,
        }))

      if (allRoutes.length > 0 && filteredRoutes.length === 0) {
        console.log(`[Layout] Module "${m.name}" has ${allRoutes.length} routes but all are dynamic (contain '[')`)
      }

      return {
        name: m.name,
        icon: 'ri-apps-line',
        description: m.description || `${m.name} module`,
        badge: filteredRoutes.length > 0 ? 'AUTO' : filteredRoutes.length === 0 && allRoutes.length > 0 ? 'DYNAMIC' : 'NO_ROUTES',
        moduleId: m.id as unknown as ModuleId,
        children: filteredRoutes.length > 0 ? filteredRoutes : [
          // If no static routes, show a placeholder so module is still visible
          {
            name: 'No static routes available',
            href: '#',
            icon: 'ri-information-line',
            description: 'This module has no static routes (may have dynamic routes only)',
            moduleId: m.id as unknown as ModuleId,
            badge: 'INFO',
          }
        ],
      }
    })
    // Show ALL modules, even if they have no routes (so user knows they exist)
    // This is a development tool to see all registered modules
    // Only filter out if module is completely invalid
    .filter((m) => {
      // Keep all modules - don't filter based on routes
      // This allows developers to see all modules in the registry
      if (!m || !m.moduleId) {
        console.warn(`[Layout] Filtering out invalid module item:`, m)
        return false
      }
      return true
    })

  console.log(`[Layout] buildAutoModulesNav result: ${moduleItems.length} modules`)

  if (moduleItems.length === 0) {
    console.warn('[Layout] No modules to display in auto nav')
    return null
  }

  return {
    name: 'All Modules (Auto)',
    icon: 'ri-grid-line',
    description: 'Auto-generated from Module Registry - All registered modules',
    badge: 'DEV',
    children: moduleItems,
  }
}

export default function Layout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname()
  const { currentCustomer } = useCustomer()
  const [sidebarOpen, setSidebarOpen] = useState(false) // Start closed on mobile
  const [expandedMenus, setExpandedMenus] = useState<Set<string>>(new Set())
  const [isDarkMode, setIsDarkMode] = useState(true) // Default to dark mode
  const { user, tenant, isLoading, isHydrated } = useAuth()
  const [autoModules, setAutoModules] = useState<ModuleListResponse['data'] | null>(null)
  const [autoModulesError, setAutoModulesError] = useState<string | null>(null)

  // Auto-open sidebar on desktop, close on mobile
  // But respect user preference and showcase page requirements
  // OPTIMIZED: Defer localStorage operations to avoid blocking navigation
  useEffect(() => {
    const isShowcase = pathname === '/showcase'
    const isDesktop = window.innerWidth >= 1024

    if (isDesktop) {
      // On showcase page, always keep sidebar open
      if (isShowcase) {
        setSidebarOpen(true)
        // Defer localStorage write
        if (typeof requestIdleCallback !== 'undefined') {
          requestIdleCallback(() => {
            localStorage.setItem('sidebar-open', 'true')
          })
        } else {
          setTimeout(() => localStorage.setItem('sidebar-open', 'true'), 0)
        }
      } else {
        // On other pages, check localStorage first, then default to open
        const savedState = localStorage.getItem('sidebar-open')
        if (savedState !== null) {
          setSidebarOpen(savedState === 'true')
        } else {
          setSidebarOpen(true)
        }
      }
    } else {
      // On mobile, always start closed
      setSidebarOpen(false)
    }
  }, [pathname])

  // Handle resize - but don't override showcase page requirement
  // OPTIMIZED: Debounced resize handler to avoid excessive updates
  useEffect(() => {
    let resizeTimer: NodeJS.Timeout
    const handleResize = () => {
      clearTimeout(resizeTimer)
      resizeTimer = setTimeout(() => {
        const isDesktop = window.innerWidth >= 1024
        const isShowcase = pathname === '/showcase'

        if (isDesktop && isShowcase) {
          // Always keep open on showcase desktop
          setSidebarOpen(true)
          // Defer localStorage write
          if (typeof requestIdleCallback !== 'undefined') {
            requestIdleCallback(() => {
              localStorage.setItem('sidebar-open', 'true')
            })
          } else {
            setTimeout(() => localStorage.setItem('sidebar-open', 'true'), 0)
          }
        } else if (isDesktop) {
          // On other desktop pages, respect saved state
          const savedState = localStorage.getItem('sidebar-open')
          if (savedState !== null) {
            setSidebarOpen(savedState === 'true')
          }
        } else {
          // On mobile, close sidebar
          setSidebarOpen(false)
        }
      }, 150) // Debounce resize events
    }

    window.addEventListener('resize', handleResize)
    return () => {
      clearTimeout(resizeTimer)
      window.removeEventListener('resize', handleResize)
    }
  }, [pathname])

  // Load theme preference from localStorage
  useEffect(() => {
    const savedTheme = localStorage.getItem('hazalyze-theme')
    if (savedTheme) {
      setIsDarkMode(savedTheme === 'dark')
    }
  }, [])

  // Apply theme to document
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark')
      document.documentElement.classList.remove('light')
    } else {
      document.documentElement.classList.add('light')
      document.documentElement.classList.remove('dark')
    }
    localStorage.setItem('hazalyze-theme', isDarkMode ? 'dark' : 'light')
  }, [isDarkMode])

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode)
  }

  // Listen for theme toggle events from navigation bar
  useEffect(() => {
    const handleThemeToggle = () => {
      setIsDarkMode(!isDarkMode)
    }
    window.addEventListener('toggle-theme', handleThemeToggle)
    return () => window.removeEventListener('toggle-theme', handleThemeToggle)
  }, [isDarkMode])

  // Load enabled modules + routes (server-derived) so we can show *everything* during dev.
  // OPTIMIZED: Defer this fetch to avoid blocking initial render with improved caching
  useEffect(() => {
    let cancelled = false
    const cacheKey = 'bluedxp:modules:list:v2' // Bump version to clear old cache

    // Clear old cache versions on first load to ensure fresh data
    if (typeof window !== 'undefined') {
      try {
        ['bluedxp:modules:list:v1', 'bluedxp:modules:list'].forEach(oldKey => {
          sessionStorage.removeItem(oldKey)
        })
        console.log('[Layout] Cleared old module list cache')
      } catch {
        // ignore
      }
    }

    // Very short cache in development, longer in production
    // But always refresh to ensure we see all modules
    const cacheTtlMs = typeof window !== 'undefined' && window.location.hostname === 'localhost' 
      ? 30 * 1000  // 30 seconds in development (very short for debugging)
      : 5 * 60 * 1000 // 5 minutes in production

    const readCache = (): ModuleListResponse['data'] | null => {
      if (typeof window === 'undefined') return null
      try {
        const raw = sessionStorage.getItem(cacheKey)
        if (!raw) return null
        const parsed = JSON.parse(raw) as { ts?: unknown; data?: unknown }
        const ts = typeof parsed.ts === 'number' ? parsed.ts : 0
        if (!ts || Date.now() - ts > cacheTtlMs) {
          console.log('[Layout] Cache expired or invalid, will fetch fresh data')
          return null
        }
        if (!Array.isArray(parsed.data)) return null
        const cachedCount = (parsed.data as ModuleListResponse['data']).length
        console.log(`[Layout] Using cached module list: ${cachedCount} modules`)
        return parsed.data as ModuleListResponse['data']
      } catch {
        return null
      }
    }

    const writeCache = (data: ModuleListResponse['data']) => {
      if (typeof window === 'undefined') return
      try {
        sessionStorage.setItem(cacheKey, JSON.stringify({ ts: Date.now(), data }))
      } catch {
        // ignore storage quota errors
      }
    }

    const cached = readCache()
    if (cached) {
      setAutoModules(cached)
      setAutoModulesError(null)
      // If cache is still fresh, skip fetch entirely
      const cacheAge = Date.now() - (sessionStorage.getItem(cacheKey) ? JSON.parse(sessionStorage.getItem(cacheKey) || '{}').ts || 0 : 0)
      if (cacheAge < cacheTtlMs) {
        console.log(`[Layout] Cache is fresh (${Math.round(cacheAge / 1000)}s old), skipping fetch`)
        return // Skip fetch if cache is fresh
      }
    }

    // CRITICAL: Defer fetch to avoid blocking initial render
    // Use requestIdleCallback if available, otherwise setTimeout
    const fetchModules = async () => {
      if (cancelled) return
      const controller = new AbortController()
      try {
        // Force fresh fetch - no cache for module list to ensure we get latest
        const res = await fetch('/api/modules/list', { 
          credentials: 'include', 
          signal: controller.signal,
          cache: 'no-store', // Always fetch fresh
          headers: {
            'Cache-Control': 'no-cache, no-store, must-revalidate',
            'Pragma': 'no-cache',
          }
        })
        const json = (await res.json()) as ModuleListResponse
        if (cancelled) return

        console.log('[Layout] Module list response:', { 
          success: json?.success, 
          count: json?.data?.length,
          modules: json?.data?.map((m: { id: string; name: string; routes: unknown[] }) => ({
            id: m.id,
            name: m.name,
            routes: m.routes?.length || 0
          }))
        })

        if (json?.success && Array.isArray(json.data)) {
          console.log(`[Layout] Setting ${json.data.length} modules in auto nav`)
          console.log(`[Layout] Module names:`, json.data.map((m: { name: string; id: string }) => `${m.name} (${m.id})`).join(', '))
          if (json.data.length === 0) {
            console.error('[Layout] ERROR: API returned 0 modules! This indicates a registration issue.')
            console.error('[Layout] Check server logs for module registration errors')
          } else if (json.data.length === 1) {
            console.warn(`[Layout] WARNING: Only 1 module returned! Expected ${json.data.length}+ modules.`)
            console.warn(`[Layout] This might be a caching issue or module registration problem.`)
          }
          setAutoModules(json.data)
          setAutoModulesError(null)
          writeCache(json.data)
        } else {
          console.warn('[Layout] Module list response invalid:', json)
          // Only show an error if we don't already have cached data.
          if (!cached) {
            setAutoModules(null)
            setAutoModulesError('Module list unavailable')
          }
        }
      } catch (e) {
        if (cancelled) return
        // Don't log errors if we have cached data - it's not critical
        if (!cached) {
          console.error('[Layout] Failed to fetch modules:', e)
          setAutoModules(null)
          setAutoModulesError('Failed to load module list')
        }
      }
    }

    // Defer fetch to avoid blocking initial render - use longer delay if cache exists
    if (typeof requestIdleCallback !== 'undefined') {
      requestIdleCallback(fetchModules, { timeout: cached ? 5000 : 2000 })
    } else {
      setTimeout(fetchModules, cached ? 500 : 100) // Longer delay if we have cache
    }

    return () => {
      cancelled = true
    }
  }, [])

  const [appMode, setAppMode] = useState<'logistics' | 'hazalyze'>('logistics')

  // Load app mode from localStorage and handle URL-based mode switching
  // OPTIMIZED: Use useMemo to avoid unnecessary recalculations
  const detectedAppMode = useMemo(() => {
    if (pathname?.startsWith('/hazalyze') || pathname?.startsWith('/msds') || pathname?.startsWith('/qhse') || pathname?.startsWith('/iso-ims') || pathname?.startsWith('/chemical')) {
      return 'hazalyze' as const
    }
    return 'logistics' as const
  }, [pathname])

  useEffect(() => {
    // Only update if mode actually changed
    if (detectedAppMode !== appMode) {
      setAppMode(detectedAppMode)
    }
  }, [detectedAppMode, appMode])

  // Persist app mode changes - deferred to avoid blocking
  useEffect(() => {
    // Defer localStorage write to avoid blocking navigation
    if (typeof requestIdleCallback !== 'undefined') {
      requestIdleCallback(() => {
        localStorage.setItem('hazalyze-app-mode', appMode)
      })
    } else {
      setTimeout(() => {
        localStorage.setItem('hazalyze-app-mode', appMode)
      }, 0)
    }
  }, [appMode])

  // Load navigation structure - database-driven with fallback to default
  // Using useMemo to cache and only recalculate when dependencies change
  const navStructure: NavItem[] = useMemo(() => {
    // For now, use default structure (database integration can be added later)
    // The service supports database loading but we'll use default for UI/UX preservation
    const base = appMode === 'hazalyze' ? getHazalyzeNavigation() : getDefaultNavigationStructure()
    const existingHrefs = collectHrefs(base)

    console.log(`[Layout] Navigation structure (${appMode}): ${base.length} base items, ${existingHrefs.size} existing hrefs`)

    // Auto modules are added to both apps for now, or filtered if needed
    const autoNav = autoModules ? buildAutoModulesNav(autoModules, existingHrefs) : null
    if (!autoNav) {
      console.log('[Layout] No auto-generated nav, using base navigation only')
      return base
    }

    console.log(`[Layout] Adding auto-generated nav with ${autoNav.children?.length || 0} modules`)
    return [...base, autoNav]
  }, [autoModules, appMode]) // Include auto module routes during development

  // Filter navigation based on permissions
  const filteredNavStructure = useMemo(() => {
    if (!user) return navStructure
    return filterNavigationByPermissions(navStructure, user)
  }, [user, navStructure])

  const toggleMenu = (menuName: string) => {
    const newExpanded = new Set(expandedMenus)
    if (newExpanded.has(menuName)) {
      newExpanded.delete(menuName)
    } else {
      newExpanded.add(menuName)
    }
    setExpandedMenus(newExpanded)
  }

  const isActive = (href?: string) => {
    if (!href) return false
    if (href === '/') {
      return pathname === '/'
    }
    return pathname?.startsWith(href)
  }

  const isMenuExpanded = (menuName: string) => {
    return expandedMenus.has(menuName)
  }

  const hasActiveChild = (item: NavItem): boolean => {
    if (item.href && isActive(item.href)) return true
    if (item.children) {
      return item.children.some(child => hasActiveChild(child))
    }
    return false
  }

  const renderNavItem = (item: NavItem, level: number = 0) => {
    const hasChildren = item.children && item.children.length > 0
    const isExpanded = isMenuExpanded(item.name)
    const active = item.href ? isActive(item.href) : false
    const hasActive = hasActiveChild(item)
    const indent = level * 16

    return (
      <div key={item.name} className="mb-0.5">
        {hasChildren ? (
          <>
            <button
              onClick={() => toggleMenu(item.name)}
              className={`w-full flex items-center justify-between px-4 py-2.5 rounded-lg transition-all group ${hasActive
                ? `${isDarkMode ? 'bg-blue-600/20 text-white' : 'bg-blue-50 text-blue-700'} border-l-2 border-blue-500`
                : `${isDarkMode ? 'text-[#9ca3af] hover:bg-[#374151] hover:text-white' : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'}`
                }`}
              style={{ paddingLeft: `${16 + indent}px` }}
            >
              <div className="flex items-center gap-3 flex-1 min-w-0">
                <i className={`${item.icon} text-lg flex-shrink-0 ${hasActive ? 'text-blue-400' : isDarkMode ? 'text-[#6b7280] group-hover:text-white' : 'text-gray-400 group-hover:text-gray-700'}`}></i>
                <div className="flex-1 min-w-0 text-left">
                  <div className={`text-sm font-medium truncate ${hasActive ? (isDarkMode ? 'text-white' : 'text-blue-700') : isDarkMode ? 'text-[#9ca3af] group-hover:text-white' : 'text-gray-600 group-hover:text-gray-900'}`}>
                    {item.name}
                  </div>
                  {item.description && (
                    <div className={`text-xs mt-0.5 truncate ${hasActive ? (isDarkMode ? 'text-blue-200' : 'text-blue-500') : isDarkMode ? 'text-[#6b7280] group-hover:text-[#9ca3af]' : 'text-gray-400 group-hover:text-gray-500'}`}>
                      {item.description}
                    </div>
                  )}
                </div>
                {item.badge && (
                  <span className="px-2 py-0.5 bg-blue-600 text-white text-xs font-medium rounded-full flex-shrink-0">
                    {item.badge}
                  </span>
                )}
                {item.comingSoon && (
                  <span className="px-2 py-0.5 bg-amber-500/20 text-amber-400 text-xs font-medium rounded-full flex-shrink-0 border border-amber-500/30">
                    COMING SOON
                  </span>
                )}
              </div>
              <i
                className={`ri-arrow-${isExpanded ? 'down' : 'right'}-s-line text-sm transition-transform flex-shrink-0 ml-2 ${hasActive ? 'text-blue-300' : isDarkMode ? 'text-[#6b7280] group-hover:text-white' : 'text-gray-400 group-hover:text-gray-700'
                  }`}
              ></i>
            </button>
            <AnimatePresence>
              {isExpanded && (
                <motion.div
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: 'auto', opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={{ duration: 0.2 }}
                  className="overflow-hidden"
                >
                  <div className={`ml-4 border-l ${isDarkMode ? 'border-[#374151]' : 'border-gray-200'} pl-2 mt-0.5`}>
                    {item.children?.map((child) => renderNavItem(child, level + 1))}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </>
        ) : (
          <Link
            href={item.href || '#'}
            prefetch={active || level === 0 ? true : undefined} // Only prefetch active links or top-level items
            className={`flex items-center gap-3 px-4 py-2.5 rounded-lg transition-all group ${active
              ? `${isDarkMode ? 'bg-blue-600 text-white' : 'bg-blue-600 text-white'} shadow-lg`
              : `${isDarkMode ? 'text-[#9ca3af] hover:bg-[#374151] hover:text-white' : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900'}`
              }`}
            style={{ paddingLeft: `${16 + indent}px` }}
          >
            <i className={`${item.icon} text-lg flex-shrink-0 ${active ? 'text-white' : isDarkMode ? 'text-[#6b7280] group-hover:text-white' : 'text-gray-400 group-hover:text-gray-700'}`}></i>
            <div className="flex-1 min-w-0">
              <div className={`text-sm font-medium truncate ${active ? 'text-white' : isDarkMode ? 'text-[#9ca3af] group-hover:text-white' : 'text-gray-600 group-hover:text-gray-900'}`}>
                {item.name}
              </div>
              {item.description && (
                <div className={`text-xs mt-0.5 truncate ${active ? 'text-blue-100' : isDarkMode ? 'text-[#6b7280] group-hover:text-[#9ca3af]' : 'text-gray-400 group-hover:text-gray-500'}`}>
                  {item.description}
                </div>
              )}
            </div>
            {item.badge && (
              <span className={`px-2 py-0.5 text-xs font-medium rounded-full flex-shrink-0 ${active ? 'bg-white/20 text-white' : 'bg-blue-600 text-white'
                }`}>
                {item.badge}
              </span>
            )}
            {item.comingSoon && (
              <span className={`px-2 py-0.5 text-xs font-medium rounded-full flex-shrink-0 border ${active
                ? 'bg-amber-500/30 text-amber-300 border-amber-400/50'
                : 'bg-amber-500/20 text-amber-400 border-amber-500/30'
                }`}>
                COMING SOON
              </span>
            )}
          </Link>
        )}
      </div>
    )
  }

  // Auto-expand menus with active children on mount
  useEffect(() => {
    const initialExpanded = new Set<string>()
    navStructure.forEach(item => {
      if (hasActiveChild(item)) {
        initialExpanded.add(item.name)
      }
    })
    if (initialExpanded.size > 0) {
      setExpandedMenus(initialExpanded)
    }
  }, [pathname])

  // Skip layout for landing, login, home, premium, and ultimate pages
  if (pathname === '/landing' || pathname === '/login' || pathname === '/home' || pathname === '/premium' || pathname === '/ultimate' ||
    pathname?.startsWith('/bluedxp-')) {
    return <>{children}</>
  }

  // REMOVED: No more blocking loading screens!
  // The app will show content immediately and handle auth state per-page
  // This prevents the "stuck at 15%" issue

  // If not hydrated yet, show a minimal non-blocking loading indicator
  // but still render the main layout structure
  if (!isHydrated) {
    return (
      <div className="min-h-screen bg-[#111827] flex items-center justify-center">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto mb-3"></div>
          <div className="text-white/70 text-sm">Loading...</div>
        </div>
      </div>
    )
  }

  // If user isn't authenticated, redirect to login (don't show blocking screen)
  if (!user && !isLoading) {
    // Auto-redirect to login after hydration
    if (typeof window !== 'undefined') {
      window.location.href = '/login'
    }
    return (
      <div className="min-h-screen bg-[#111827] flex items-center justify-center">
        <div className="text-center">
          <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto mb-3"></div>
          <div className="text-white/70 text-sm">Redirecting to login...</div>
        </div>
      </div>
    )
  }

  return (
    <ViewContextProvider user={user}>
      <div className={`min-h-screen transition-colors duration-200 ${isDarkMode ? 'bg-[#111827]' : 'bg-gray-50'}`}>
        {/* Revolutionary Top Navigation */}
        <RevolutionaryTopNavigation
          isDarkMode={isDarkMode}
          onToggleSidebar={() => setSidebarOpen(!sidebarOpen)}
          sidebarOpen={sidebarOpen}
          navStructure={filteredNavStructure}
          user={user}
          tenant={tenant}
        />

        <div className="flex relative">
          {/* Mobile Overlay - Only on mobile, not on showcase desktop */}
          {sidebarOpen && pathname !== '/showcase' && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => {
                // Only close on mobile
                if (window.innerWidth < 1024) {
                  setSidebarOpen(false)
                }
              }}
              className="fixed inset-0 bg-black/50 z-40 lg:hidden"
            />
          )}

          {/* Enhanced 3D Navigation System */}
          <Enhanced3DSidebar
            navStructure={filteredNavStructure}
            isDarkMode={isDarkMode}
            sidebarOpen={sidebarOpen}
            setSidebarOpen={setSidebarOpen}
            user={user}
          />

          {/* Main Content */}
          <main className={`flex-1 ${isDarkMode ? 'bg-[#111827]' : 'bg-gray-50'} min-h-screen w-full overflow-x-hidden pt-28 transition-all duration-500`}
                style={{ marginLeft: sidebarOpen ? '320px' : '120px' }}>
            <div className="w-full max-w-full overflow-x-hidden p-4 sm:p-6 lg:p-8">
              {children}
            </div>
          </main>
        </div>

        {/* BlueDXP Copilot - AI Assistant */}
        <HazalyzeCopilot />

        {/* Keyboard Shortcuts Help */}
        <KeyboardShortcutsHelp />

        <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 8px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: ${isDarkMode ? '#1f2937' : '#f3f4f6'};
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: ${isDarkMode ? '#4b5563' : '#9ca3af'};
          border-radius: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: ${isDarkMode ? '#6b7280' : '#6b7280'};
        }
      `}</style>

        {/* Accessibility: Intelligent Toast Notifications */}
        <IntelligentToastContainer />

        {/* Real-time Notification Toasts */}
        <NotificationToastWrapper userId={user?.id} tenantId={tenant?.id || currentCustomer?.tenantId} />

        {/* Auto-generate demo notifications in development */}
        <NotificationAutoGenerator userId={user?.id} tenantId={tenant?.id || currentCustomer?.tenantId} />

        {/* Accessibility: Color Blind Filter SVGs */}
        <ColorBlindFilters />

        {/* Accessibility: Quick Access Floating Button */}
        <AccessibilityQuickAccess />

        {/* Skip Link for Keyboard Navigation */}
        <a
          href="#main-content"
          className="skip-link"
          tabIndex={0}
        >
          Skip to main content
        </a>

        {/* Screen Reader Announcements */}
        <div
          id="a11y-announcer"
          className="a11y-announcer"
          aria-live="polite"
          aria-atomic="true"
        />
      </div>
    </ViewContextProvider>
  )
}

/**
 * MSDS Upload Component
 * Upload and manage Material Safety Data Sheets
 * Migrated from chemcheck-ai/components/MSDSUpload.tsx
 * Adapted for BlueDXP Platform
 */

'use client'

import { useState, useCallback } from 'react'
import { motion } from 'framer-motion'

interface MSDSFile {
  id: string
  file: File
  name: string
  size: number
  type: string
  progress: number
  status: 'uploading' | 'success' | 'error'
  error?: string
  uploadedUrl?: string
}

interface MSDSUploadProps {
  onUploadComplete?: (files: MSDSFile[]) => void
  onUploadError?: (error: string) => void
  maxFiles?: number
  maxFileSize?: number // in MB
  acceptedTypes?: string[]
  autoUpload?: boolean
}

export default function MSDSUpload({
  onUploadComplete,
  onUploadError,
  maxFiles = 10,
  maxFileSize = 50,
  acceptedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx'],
  autoUpload = false
}: MSDSUploadProps) {
  const [files, setFiles] = useState<MSDSFile[]>([])
  const [isDragging, setIsDragging] = useState(false)
  const [uploading, setUploading] = useState(false)

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)

    const droppedFiles = Array.from(e.dataTransfer.files)
    handleFiles(droppedFiles)
  }, [])

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const selectedFiles = Array.from(e.target.files)
      handleFiles(selectedFiles)
    }
  }, [])

  const handleFiles = (newFiles: File[]) => {
    const validFiles = newFiles.filter(file => {
      // Check file type
      const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase()
      if (!acceptedTypes.includes(fileExtension)) {
        onUploadError?.(`File ${file.name} has invalid type. Accepted: ${acceptedTypes.join(', ')}`)
        return false
      }

      // Check file size
      const fileSizeMB = file.size / (1024 * 1024)
      if (fileSizeMB > maxFileSize) {
        onUploadError?.(`File ${file.name} exceeds maximum size of ${maxFileSize}MB`)
        return false
      }

      return true
    })

    const msdsFiles: MSDSFile[] = validFiles.map(file => ({
      id: `msds-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      file,
      name: file.name,
      size: file.size,
      type: file.type,
      progress: 0,
      status: 'uploading'
    }))

    const updatedFiles = [...files, ...msdsFiles].slice(0, maxFiles)
    setFiles(updatedFiles)

    if (autoUpload) {
      uploadFiles(msdsFiles)
    }
  }

  const uploadFiles = async (filesToUpload: MSDSFile[] = files) => {
    setUploading(true)

    const uploadPromises = filesToUpload.map(async (msdsFile) => {
      try {
        const formData = new FormData()
        formData.append('file', msdsFile.file)
        formData.append('type', 'MSDS')
        formData.append('name', msdsFile.name)

        // Simulate upload progress
        const xhr = new XMLHttpRequest()

        return new Promise<MSDSFile>((resolve, reject) => {
          xhr.upload.addEventListener('progress', (e) => {
            if (e.lengthComputable) {
              const progress = Math.round((e.loaded / e.total) * 100)
              setFiles(prev => prev.map(f => 
                f.id === msdsFile.id ? { ...f, progress } : f
              ))
            }
          })

          xhr.addEventListener('load', () => {
            if (xhr.status === 200) {
              const response = JSON.parse(xhr.responseText)
              const updatedFile: MSDSFile = {
                ...msdsFile,
                status: 'success',
                progress: 100,
                uploadedUrl: response.url || response.file_url
              }
              resolve(updatedFile)
            } else {
              reject(new Error(`Upload failed: ${xhr.statusText}`))
            }
          })

          xhr.addEventListener('error', () => {
            reject(new Error('Upload failed'))
          })

          // Try to upload to API
          xhr.open('POST', '/api/erpnext/save-msds')
          xhr.send(formData)
        })
      } catch (error: any) {
        return {
          ...msdsFile,
          status: 'error' as const,
          error: error.message || 'Upload failed'
        }
      }
    })

    try {
      const results = await Promise.all(uploadPromises)
      setFiles(prev => prev.map(f => {
        const result = results.find(r => r.id === f.id)
        return result || f
      }))
      onUploadComplete?.(results.filter(r => r.status === 'success'))
    } catch (error: any) {
      onUploadError?.(error.message || 'Upload failed')
    } finally {
      setUploading(false)
    }
  }

  const removeFile = (fileId: string) => {
    setFiles(files.filter(f => f.id !== fileId))
  }

  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return bytes + ' B'
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB'
    return (bytes / (1024 * 1024)).toFixed(2) + ' MB'
  }

  return (
    <div className="space-y-4">
      {/* Drop Zone */}
      <div
        onDragOver={(e) => {
          e.preventDefault()
          setIsDragging(true)
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        className={`border-2 border-dashed rounded-lg p-8 text-center transition-colors ${
          isDragging
            ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
            : 'border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-800'
        }`}
      >
        <i className="ri-file-upload-line text-4xl text-gray-400 dark:text-gray-500 mb-4"></i>
        <p className="text-gray-700 dark:text-gray-300 mb-2">
          Drag and drop MSDS files here, or{' '}
          <label className="text-blue-600 dark:text-blue-400 cursor-pointer hover:underline">
            browse
            <input
              type="file"
              multiple
              accept={acceptedTypes.join(',')}
              onChange={handleFileSelect}
              className="hidden"
            />
          </label>
        </p>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Accepted formats: {acceptedTypes.join(', ')} (Max {maxFileSize}MB per file)
        </p>
      </div>

      {/* Files List */}
      {files.length > 0 && (
        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Selected Files ({files.length}/{maxFiles})
            </h4>
            {!autoUpload && (
              <button
                onClick={() => uploadFiles()}
                disabled={uploading}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                <i className="ri-upload-cloud-line"></i>
                {uploading ? 'Uploading...' : 'Upload All'}
              </button>
            )}
          </div>

          <div className="space-y-2">
            {files.map((msdsFile) => (
              <motion.div
                key={msdsFile.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-4"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <i className="ri-file-text-line text-2xl text-blue-600 dark:text-blue-400"></i>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                        {msdsFile.name}
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {formatFileSize(msdsFile.size)}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    {msdsFile.status === 'uploading' && (
                      <div className="w-32">
                        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                          <div
                            className="bg-blue-600 h-2 rounded-full transition-all"
                            style={{ width: `${msdsFile.progress}%` }}
                          ></div>
                        </div>
                        <p className="text-xs text-gray-500 dark:text-gray-400 mt-1 text-center">
                          {msdsFile.progress}%
                        </p>
                      </div>
                    )}

                    {msdsFile.status === 'success' && (
                      <span className="px-2 py-1 text-xs font-medium rounded-full bg-green-100 dark:bg-green-900 text-green-800 dark:text-green-200 flex items-center gap-1">
                        <i className="ri-checkbox-circle-line"></i>
                        Uploaded
                      </span>
                    )}

                    {msdsFile.status === 'error' && (
                      <span className="px-2 py-1 text-xs font-medium rounded-full bg-red-100 dark:bg-red-900 text-red-800 dark:text-red-200 flex items-center gap-1">
                        <i className="ri-error-warning-line"></i>
                        Error
                      </span>
                    )}

                    <button
                      onClick={() => removeFile(msdsFile.id)}
                      className="text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-300"
                      title="Remove file"
                    >
                      <i className="ri-close-line text-xl"></i>
                    </button>
                  </div>
                </div>

                {msdsFile.error && (
                  <p className="mt-2 text-sm text-red-600 dark:text-red-400">{msdsFile.error}</p>
                )}

                {msdsFile.uploadedUrl && (
                  <a
                    href={msdsFile.uploadedUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="mt-2 text-sm text-blue-600 dark:text-blue-400 hover:underline flex items-center gap-1"
                  >
                    <i className="ri-external-link-line"></i>
                    View uploaded file
                  </a>
                )}
              </motion.div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useNotification } from '@/lib/services/notifications/useNotification'
import { Notification } from '@/lib/services/notifications/notificationService'
// Initialize event bus integration for real-time notifications
import '@/lib/services/notifications/eventBusIntegration'

interface NotificationCenterProps {
  userId?: string
  tenantId?: string
  maxVisible?: number
}

export default function NotificationCenter({ userId, tenantId, maxVisible = 5 }: NotificationCenterProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [hasError, setHasError] = useState(false)
  const [pulseAnimation, setPulseAnimation] = useState(false)
  const panelRef = useRef<HTMLDivElement>(null)
  const buttonRef = useRef<HTMLButtonElement>(null)

  // Hooks must be called unconditionally. If the underlying notification hook
  // can error, it should surface it via `notificationData.error` (handled below).
  const notificationData = useNotification({
    userId,
    tenantId,
    autoRefresh: true,
    refreshInterval: 30000,
  })

  // Handle errors from the hook
  useEffect(() => {
    if (notificationData?.error) {
      console.error('NotificationCenter: Notification service error', notificationData.error)
      setHasError(true)
    } else {
      setHasError(false)
    }
  }, [notificationData?.error])

  // Pulse animation when new notifications arrive
  useEffect(() => {
    if (notificationData?.unreadCount && notificationData.unreadCount > 0) {
      setPulseAnimation(true)
      const timer = setTimeout(() => setPulseAnimation(false), 2000)
      return () => clearTimeout(timer)
    }
  }, [notificationData?.unreadCount])

  // Safely extract values with defaults
  const notifications = notificationData?.notifications || []
  const unreadCount = notificationData?.unreadCount || 0
  const markAsRead = notificationData?.markAsRead || (async (_id: string) => {})
  const markAllAsRead = notificationData?.markAllAsRead || (async () => {})
  const dismiss = notificationData?.dismiss || (async (_id: string) => {})
  const clearAll = notificationData?.clearAll || (async () => {})

  // Filter out dismissed notifications (with error handling)
  const activeNotifications = (notifications || []).filter(n => n && !n.dismissed)
  const displayedNotifications = activeNotifications.slice(0, maxVisible)

  // Group notifications by priority/type for better organization
  const groupedNotifications = {
    critical: activeNotifications.filter(n => n.priority === 'critical' || n.type === 'error'),
    high: activeNotifications.filter(n => n.priority === 'high' || n.type === 'alert'),
    medium: activeNotifications.filter(n => !n.priority || n.priority === 'medium'),
    low: activeNotifications.filter(n => n.priority === 'low'),
  }

  const getTypeStyles = (type: Notification['type'], priority?: Notification['priority']) => {
    // Critical/Error notifications get special styling
    if (priority === 'critical' || type === 'error') {
      return 'bg-gradient-to-br from-red-500/30 to-red-600/20 border-red-500/50 text-red-300 shadow-lg shadow-red-500/20'
    }
    if (priority === 'high' || type === 'alert') {
      return 'bg-gradient-to-br from-orange-500/30 to-orange-600/20 border-orange-500/50 text-orange-300 shadow-lg shadow-orange-500/20'
    }

    switch (type) {
      case 'success':
        return 'bg-gradient-to-br from-green-500/30 to-emerald-600/20 border-green-500/50 text-green-300 shadow-lg shadow-green-500/20'
      case 'warning':
        return 'bg-gradient-to-br from-yellow-500/30 to-amber-600/20 border-yellow-500/50 text-yellow-300 shadow-lg shadow-yellow-500/20'
      default:
        return 'bg-gradient-to-br from-blue-500/30 to-cyan-600/20 border-blue-500/50 text-blue-300 shadow-lg shadow-blue-500/20'
    }
  }

  const getTypeIcon = (type: Notification['type']) => {
    switch (type) {
      case 'success':
        return 'ri-checkbox-circle-fill'
      case 'error':
        return 'ri-error-warning-fill'
      case 'warning':
        return 'ri-alert-fill'
      case 'alert':
        return 'ri-alarm-warning-fill'
      default:
        return 'ri-information-fill'
    }
  }

  const getPriorityBadge = (priority?: Notification['priority']) => {
    if (!priority || priority === 'medium') return null
    const colors = {
      critical: 'bg-red-500 text-white',
      high: 'bg-orange-500 text-white',
      low: 'bg-gray-500 text-white',
    }
    return (
      <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold uppercase ${colors[priority] || ''}`}>
        {priority}
      </span>
    )
  }

  const formatTime = (timestamp: Date | string) => {
    const date = new Date(timestamp)
    const now = new Date()
    const diff = now.getTime() - date.getTime()

    if (diff < 60000) return 'Just now'
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h ago`
    if (diff < 604800000) return `${Math.floor(diff / 86400000)}d ago`
    return date.toLocaleDateString()
  }

  const handleNotificationClick = useCallback((notification: Notification) => {
    if (!notification.read) {
      markAsRead(notification.id)
    }
    if (notification.actionUrl) {
      if (notification.actionUrl.startsWith('http')) {
        window.open(notification.actionUrl, '_blank')
      } else {
        window.location.href = notification.actionUrl
      }
    }
    // Don't auto-close - let user manually close if they want
  }, [markAsRead])

  // Close panel when clicking outside or pressing Escape
  useEffect(() => {
    if (!isOpen) return

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsOpen(false)
      }
    }

    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as Node
      if (
        panelRef.current &&
        buttonRef.current &&
        !panelRef.current.contains(target) &&
        !buttonRef.current.contains(target)
      ) {
        setIsOpen(false)
      }
    }

    document.addEventListener('keydown', handleEscape)
    // Use setTimeout to avoid immediate close on open
    setTimeout(() => {
      document.addEventListener('mousedown', handleClickOutside)
    }, 100)

    return () => {
      document.removeEventListener('keydown', handleEscape)
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [isOpen])

  return (
    <div className="relative">
      {/* Enhanced Notification Bell with Pulse Animation */}
      <motion.button
        ref={buttonRef}
        onClick={(e) => {
          e.stopPropagation()
          setIsOpen(!isOpen)
        }}
        className="relative p-2.5 rounded-xl hover:bg-white/10 transition-all duration-200 group"
        aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`}
        aria-expanded={isOpen}
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
      >
        <motion.div
          animate={pulseAnimation ? { scale: [1, 1.2, 1] } : {}}
          transition={{ duration: 0.5, repeat: pulseAnimation ? 2 : 0 }}
        >
          <i className="ri-notification-3-line text-xl text-gray-300 group-hover:text-white transition-colors"></i>
        </motion.div>

        {/* Enhanced Badge */}
        {unreadCount > 0 && (
          <motion.span
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            className="absolute -top-1 -right-1 bg-gradient-to-br from-red-500 to-red-600 text-white text-xs rounded-full w-6 h-6 flex items-center justify-center font-bold shadow-lg shadow-red-500/50 border-2 border-gray-900"
          >
            {unreadCount > 9 ? '9+' : unreadCount}
          </motion.span>
        )}

        {/* Error Indicator */}
        {hasError && (
          <span className="absolute -bottom-1 -right-1 w-2 h-2 bg-yellow-500 rounded-full border-2 border-gray-900"></span>
        )}
      </motion.button>

      {/* Enhanced Notification Panel */}
      <AnimatePresence mode="wait">
        {isOpen && (
          <>
            {/* Backdrop with blur - closes panel when clicked */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-[45] bg-black/20 backdrop-blur-sm"
              onClick={(e) => {
                e.stopPropagation()
                setIsOpen(false)
              }}
              onMouseDown={(e) => {
                // Prevent any interaction issues
                e.stopPropagation()
              }}
            />

            {/* Enhanced Panel */}
            <motion.div
              ref={panelRef}
              initial={{ opacity: 0, y: 10, scale: 0.95, x: 10 }}
              animate={{ opacity: 1, y: 0, scale: 1, x: 0 }}
              exit={{ opacity: 0, y: 10, scale: 0.95, x: 10 }}
              transition={{ 
                type: "spring",
                stiffness: 300,
                damping: 30
              }}
              className="fixed right-4 top-20 w-[420px] max-w-[calc(100vw-2rem)] bg-gradient-to-br from-gray-900 via-gray-900 to-gray-800 border border-gray-700/50 rounded-2xl shadow-2xl z-[50] overflow-hidden backdrop-blur-xl"
              onClick={(e) => {
                // Prevent clicks inside panel from closing it
                e.stopPropagation()
              }}
              onMouseDown={(e) => {
                e.stopPropagation()
              }}
            >
              {/* Enhanced Header with gradient */}
              <div className="px-5 py-4 bg-gradient-to-r from-gray-800/80 to-gray-800/40 border-b border-gray-700/50 backdrop-blur-sm">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="font-bold text-white text-lg flex items-center gap-2">
                    <i className="ri-notification-3-fill text-cyan-400"></i>
                    Notifications
                    {unreadCount > 0 && (
                      <motion.span
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        className="text-xs bg-gradient-to-r from-cyan-500 to-blue-600 text-white px-2.5 py-1 rounded-full font-bold shadow-lg shadow-cyan-500/30"
                      >
                        {unreadCount} new
                      </motion.span>
                    )}
                  </h3>
                  <div className="flex items-center gap-2">
                    {unreadCount > 0 && (
                      <button
                        onClick={() => markAllAsRead()}
                        className="text-xs text-gray-400 hover:text-cyan-400 transition-colors px-2 py-1 rounded-lg hover:bg-gray-700/50 font-medium"
                      >
                        Mark all read
                      </button>
                    )}
                    <button
                      onClick={() => clearAll()}
                      className="text-xs text-gray-400 hover:text-red-400 transition-colors px-2 py-1 rounded-lg hover:bg-gray-700/50 font-medium"
                    >
                      Clear all
                    </button>
                    <button
                      onClick={() => setIsOpen(false)}
                      className="p-1.5 text-gray-400 hover:text-white hover:bg-gray-700/50 rounded-lg transition-all"
                      aria-label="Close notifications"
                      title="Close"
                    >
                      <i className="ri-close-line text-lg"></i>
                    </button>
                  </div>
                </div>

                {/* Quick filter tabs */}
                {activeNotifications.length > 0 && (
                  <div className="flex gap-1 mt-2">
                    <span className="text-xs text-gray-500">
                      {activeNotifications.length} total
                    </span>
                    {groupedNotifications.critical.length > 0 && (
                      <span className="text-xs text-red-400">
                        • {groupedNotifications.critical.length} critical
                      </span>
                    )}
                  </div>
                )}
              </div>

              {/* Enhanced Notification List with smooth scrolling */}
              <div className="max-h-[500px] overflow-y-auto custom-scrollbar">
                {displayedNotifications.length === 0 ? (
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="px-5 py-12 text-center"
                  >
                    <div className="mx-auto w-16 h-16 rounded-full bg-gray-800/50 flex items-center justify-center mb-4">
                      <i className="ri-notification-off-line text-3xl text-gray-600"></i>
                    </div>
                    <p className="text-gray-400 font-medium">All caught up!</p>
                    <p className="text-xs text-gray-500 mt-1">No new notifications</p>
                  </motion.div>
                ) : (
                  <div className="divide-y divide-gray-800/50">
                    {displayedNotifications.map((notification, index) => (
                      <motion.div
                        key={notification.id}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: index * 0.05 }}
                        className={`px-5 py-4 hover:bg-gray-800/40 transition-all duration-200 cursor-pointer group ${
                          !notification.read ? 'bg-gradient-to-r from-gray-800/30 to-transparent border-l-2 border-cyan-500' : ''
                        }`}
                        onClick={() => handleNotificationClick(notification)}
                      >
                        <div className="flex items-start gap-3">
                          {/* Enhanced Icon with glow effect */}
                          <motion.div
                            whileHover={{ scale: 1.1, rotate: 5 }}
                            className={`p-2.5 rounded-xl border ${getTypeStyles(notification.type, notification.priority)} flex-shrink-0`}
                          >
                            <i className={`${notification.icon || getTypeIcon(notification.type)} text-lg`}></i>
                          </motion.div>

                          {/* Enhanced Content */}
                          <div className="flex-1 min-w-0">
                            <div className="flex items-start justify-between gap-2 mb-1">
                              {notification.title && (
                                <p className="font-semibold text-white text-sm leading-tight">
                                  {notification.title}
                                </p>
                              )}
                              {getPriorityBadge(notification.priority)}
                            </div>
                            <p className={`text-sm leading-relaxed ${notification.title ? 'text-gray-300' : 'text-white font-medium'}`}>
                              {notification.message}
                            </p>
                            {notification.details && (
                              <p className="text-xs text-gray-400 mt-1.5 line-clamp-2">
                                {notification.details}
                              </p>
                            )}
                            <div className="flex items-center gap-3 mt-2.5">
                              <span className="text-xs text-gray-500 flex items-center gap-1">
                                <i className="ri-time-line"></i>
                                {formatTime(notification.createdAt || new Date())}
                              </span>
                              {notification.category && (
                                <span className="text-xs bg-gray-700/50 text-gray-400 px-2 py-0.5 rounded-md border border-gray-600/50">
                                  {notification.category}
                                </span>
                              )}
                              {notification.source && (
                                <span className="text-xs text-gray-500">
                                  {notification.source}
                                </span>
                              )}
                              {!notification.read && (
                                <motion.span
                                  initial={{ scale: 0 }}
                                  animate={{ scale: 1 }}
                                  className="w-2 h-2 bg-cyan-400 rounded-full shadow-lg shadow-cyan-400/50"
                                ></motion.span>
                              )}
                            </div>

                            {/* Action Button */}
                            {notification.actionUrl && notification.actionLabel && (
                              <motion.button
                                whileHover={{ x: 3 }}
                                className="mt-2 text-xs text-cyan-400 hover:text-cyan-300 transition-colors font-medium flex items-center gap-1"
                                onClick={(e) => {
                                  e.stopPropagation()
                                  handleNotificationClick(notification)
                                }}
                              >
                                {notification.actionLabel}
                                <i className="ri-arrow-right-line"></i>
                              </motion.button>
                            )}
                          </div>

                          {/* Enhanced Actions */}
                          <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button
                              onClick={(e) => {
                                e.stopPropagation()
                                dismiss(notification.id)
                              }}
                              className="p-1.5 text-gray-500 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-all"
                              title="Dismiss"
                            >
                              <i className="ri-close-line"></i>
                            </button>
                            {!notification.read && (
                              <button
                                onClick={(e) => {
                                  e.stopPropagation()
                                  markAsRead(notification.id)
                                }}
                                className="p-1.5 text-gray-500 hover:text-cyan-400 hover:bg-cyan-500/10 rounded-lg transition-all"
                                title="Mark as read"
                              >
                                <i className="ri-check-line"></i>
                              </button>
                            )}
                          </div>
                        </div>
                      </motion.div>
                    ))}
                  </div>
                )}
              </div>

              {/* Enhanced Footer */}
              {activeNotifications.length > maxVisible && (
                <div className="px-5 py-3 bg-gradient-to-r from-gray-800/50 to-transparent border-t border-gray-700/50 text-center">
                  <button className="text-sm text-cyan-400 hover:text-cyan-300 transition-colors font-medium flex items-center justify-center gap-2 mx-auto">
                    View all {activeNotifications.length} notifications
                    <i className="ri-arrow-right-s-line"></i>
                  </button>
                </div>
              )}
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </div>
  )
}

// ============================================================================
// TOAST NOTIFICATIONS (Legacy - kept for compatibility)
// Note: Toast notifications are now handled by NotificationToastWrapper
// which uses a more subtle, less intrusive design
// ============================================================================

interface ToastProps {
  notification: Notification
  onDismiss: () => void
}

export function Toast({ notification, onDismiss }: ToastProps) {
  useEffect(() => {
    if (notification.duration && notification.duration > 0) {
      const timer = setTimeout(onDismiss, notification.duration)
      return () => clearTimeout(timer)
    }
  }, [notification.duration, onDismiss])

  const getTypeStyles = (type: Notification['type'], priority?: Notification['priority']) => {
    // Subtle styling
    if (priority === 'critical' || type === 'error') {
      return 'bg-gray-900/95 border border-red-500/30 text-red-100'
    }
    return 'bg-gray-900/95 border border-gray-700/50 text-gray-100'
  }

  return (
    <motion.div
      initial={{ opacity: 0, x: 100, scale: 0.9 }}
      animate={{ opacity: 1, x: 0, scale: 1 }}
      exit={{ opacity: 0, x: 100, scale: 0.9 }}
      className={`px-4 py-3 rounded-lg border backdrop-blur-xl shadow-xl ${getTypeStyles(notification.type, notification.priority)}`}
    >
      <div className="flex items-start gap-2.5">
        <i className={`ri-information-fill text-lg ${notification.priority === 'critical' ? 'text-red-400' : 'text-cyan-400'}`}></i>
        <div className="flex-1 min-w-0">
          {notification.title && (
            <p className="font-semibold text-sm text-white mb-0.5">{notification.title}</p>
          )}
          <p className="text-xs text-gray-300 line-clamp-2">{notification.message}</p>
        </div>
        <button
          onClick={onDismiss}
          className="p-1 hover:bg-white/10 rounded transition-colors text-gray-400 hover:text-white"
        >
          <i className="ri-close-line text-sm"></i>
        </button>
      </div>
    </motion.div>
  )
}

// ============================================================================
// TOAST CONTAINER (Legacy - kept for compatibility)
// ============================================================================

interface ToastContainerProps {
  notifications: Notification[]
  onDismiss: (id: string) => void
  position?: 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left' | 'top-center'
}

export function ToastContainer({ 
  notifications, 
  onDismiss, 
  position = 'top-right' 
}: ToastContainerProps) {
  const positionClasses = {
    'top-right': 'top-4 right-4',
    'top-left': 'top-4 left-4',
    'bottom-right': 'bottom-4 right-4',
    'bottom-left': 'bottom-4 left-4',
    'top-center': 'top-4 left-1/2 -translate-x-1/2',
  }

  return (
    <div className={`fixed ${positionClasses[position]} z-[60] flex flex-col gap-2 pointer-events-none max-w-sm`}>
      <AnimatePresence mode="popLayout">
        {notifications
          .filter(n => !n.dismissed && n.channel === 'in-app')
          .slice(0, 1) // Only show 1 at a time
          .map((notification) => (
            <div key={notification.id} className="pointer-events-auto">
              <Toast
                notification={notification}
                onDismiss={() => onDismiss(notification.id)}
              />
            </div>
          ))}
      </AnimatePresence>
    </div>
  )
}

