                                return { name: 'Picking Efficiency', desc: 'Time efficiency for picking process', type: 'internal' as 'internal' | 'customer' }
                              case 'kpi-qc-efficiency':
                                return { name: 'QC Efficiency', desc: 'Time efficiency for quality control process', type: 'internal' as 'internal' | 'customer' }
                              case 'kpi-dispatching-efficiency':
                                return { name: 'Dispatching Efficiency', desc: 'Time efficiency for dispatching process', type: 'internal' as 'internal' | 'customer' }
                              case 'kpi-total-processing-efficiency':
                                return { name: 'Total Processing Efficiency', desc: 'Overall processing time efficiency', type: 'internal' as 'internal' | 'customer' }
                              case 'kpi-damage':
                                return { name: 'Damage', desc: 'Percentage and count of damaged pallets', type: 'customer' as 'internal' | 'customer' }
                              case 'kpi-order-accuracy':
                                return { name: 'Order Accuracy', desc: 'Variance between expected and picked quantity', type: 'customer' as 'internal' | 'customer' }
                              default:
                                return { name: 'KPI', desc: 'Performance indicator', type: 'internal' as 'internal' | 'customer' }
