                                  isWarning ? 'bg-yellow-500/20 text-yellow-400 border-2 border-yellow-500/30' :
                                  'bg-red-500/20 text-red-400 border-2 border-red-500/30'
                                }`}>
                                  {kpi.status.toUpperCase()}
                                </span>
                              </div>

                              {/* Gauge Chart (Semi-Circle) */}
                              <div className="flex items-center justify-center mb-5">
                                <div className="relative w-32 h-16">
                                  <svg className="transform w-32 h-16" viewBox="0 0 100 50">
                                    {/* Background Arc */}
                                    <path
                                      d="M 10 40 A 40 40 0 0 1 90 40"
                                      fill="none"
                                      stroke="#111827"
                                      strokeWidth="8"
                                      strokeLinecap="round"
                                    />
                                    {/* Progress Arc */}
                                    <path
                                      d="M 10 40 A 40 40 0 0 1 90 40"
                                      fill="none"
                                      stroke={isMet ? '#10b981' : isWarning ? '#f59e0b' : '#ef4444'}
                                      strokeWidth="8"
                                      strokeLinecap="round"
                                      strokeDasharray={`${Math.PI * 40}`}
                                      strokeDashoffset={`${Math.PI * 40 * (1 - Math.min(Math.max(percentage, 0), 100) / 100)}`}
                                      className="transition-all duration-500"
                                    />
                                  </svg>
                                  <div className="absolute inset-0 flex items-center justify-center">
                                    <div className="text-center">
                                      <p className={`text-2xl font-bold ${
                                        isMet ? 'text-green-400' : isWarning ? 'text-yellow-400' : 'text-red-400'
                                      }`}>
                                        {Math.max(0, Math.min(percentage, 100)).toFixed(0)}%
                                      </p>
                                    </div>
                                  </div>
                                </div>
                              </div>

                              {/* Metrics with Comparison Bars */}
                              <div className="space-y-3 pt-5 border-t border-[#374151]">
                                <div>
