                                  </div>
                                  <div className="w-full h-2 bg-[#111827] rounded-full overflow-hidden">
                                    <div 
                                      className={`h-full transition-all duration-500 ${
                                        isMet ? 'bg-green-500' : isWarning ? 'bg-yellow-500' : 'bg-red-500'
                                      }`}
                                      style={{ width: `${Math.min((displayValue / displayTarget) * 100, 100)}%` }}
                                    />
                                  </div>
                                </div>
                                <div>
                                  <div className="flex items-center justify-between mb-1.5">
                                    <span className="text-xs font-semibold text-[#9ca3af]">Target</span>
