                            <thead className="bg-[#111827] border-b border-[#374151]">
                              <tr>
                                <th className="px-4 py-3 text-left text-xs font-bold text-[#9ca3af] uppercase tracking-wider">Timestamp</th>
                                <th className="px-4 py-3 text-left text-xs font-bold text-[#9ca3af] uppercase tracking-wider">User</th>
                                <th className="px-4 py-3 text-left text-xs font-bold text-[#9ca3af] uppercase tracking-wider">Field</th>
                                <th className="px-4 py-3 text-left text-xs font-bold text-[#9ca3af] uppercase tracking-wider">Change</th>
                                <th className="px-4 py-3 text-left text-xs font-bold text-[#9ca3af] uppercase tracking-wider">Reason</th>
                              </tr>
                            </thead>
