                                    )}
                                  </td>
                                  <td className="px-4 py-3 text-sm text-[#9ca3af]">
                                    {history.reason || 'N/A'}
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      </div>
                    </div>
