    warehouse: initialData?.warehouse || '',
    zone: initialData?.zone || '',
    aisle: initialData?.aisle || '',
    rack: initialData?.rack || '',
    level: initialData?.level || '',
    locationType: initialData?.locationType || 'Storage',
