'use client'

import { useState, useEffect, useRef, useMemo } from 'react'
import { motion } from 'framer-motion'
import { calculateVirtualScroll, VirtualScrollConfig } from '@/utils/performanceOptimization'

interface VirtualListProps<T> {
  items: T[]
  itemHeight: number
  containerHeight: number
  renderItem: (item: T, index: number) => React.ReactNode
  overscan?: number
  className?: string
}

/**
 * Virtual List Component
 * Renders only visible items for performance with large lists
 */
export default function VirtualList<T>({
  items,
  itemHeight,
  containerHeight,
  renderItem,
  overscan = 3,
  className = '',
}: VirtualListProps<T>) {
  const [scrollTop, setScrollTop] = useState(0)
  const scrollContainerRef = useRef<HTMLDivElement>(null)

  const config: VirtualScrollConfig = {
    itemHeight,
    containerHeight,
    overscan,
  }

  const virtualScroll = useMemo(() => {
    return calculateVirtualScroll(scrollTop, items.length, config)
  }, [scrollTop, items.length, itemHeight, containerHeight, overscan])

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop)
  }

  return (
    <div
      ref={scrollContainerRef}
      className={`overflow-auto ${className}`}
      style={{ height: containerHeight }}
      onScroll={handleScroll}
    >
      <div style={{ height: virtualScroll.totalHeight, position: 'relative' }}>
        <div style={{ transform: `translateY(${virtualScroll.offsetY}px)` }}>
          {virtualScroll.visibleItems.map((index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              style={{ height: itemHeight }}
            >
              {renderItem(items[index], index)}
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  )
}

/**
 * Warehouse Areas Manager Component
 * Manage warehouse zones, aisles, and areas
 * Migrated from chemcheck-ai/components/WarehouseAreasManager.tsx
 * Adapted for BlueDXP Platform
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'

interface WarehouseArea {
  id: string
  name: string
  type: 'Zone' | 'Aisle' | 'Section' | 'Area'
  parentId?: string
  warehouse: string
  description?: string
  capacity?: number
  currentUtilization?: number
  status: 'Active' | 'Inactive' | 'Maintenance'
  metadata?: Record<string, any>
}

interface WarehouseAreasManagerProps {
  warehouseId?: string
  onAreaSelect?: (area: WarehouseArea) => void
  onAreaCreate?: (area: Omit<WarehouseArea, 'id'>) => void
  onAreaUpdate?: (area: WarehouseArea) => void
  onAreaDelete?: (areaId: string) => void
}

export default function WarehouseAreasManager({
  warehouseId,
  onAreaSelect,
  onAreaCreate,
  onAreaUpdate,
  onAreaDelete
}: WarehouseAreasManagerProps) {
  const [areas, setAreas] = useState<WarehouseArea[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)
  const [selectedArea, setSelectedArea] = useState<WarehouseArea | null>(null)
  const [selectedType, setSelectedType] = useState<'Zone' | 'Aisle' | 'Section' | 'Area'>('Zone')
  const [warehouses, setWarehouses] = useState<Array<{ name: string; warehouse_name: string }>>([])
  const [newArea, setNewArea] = useState({
    name: '',
    type: 'Zone' as WarehouseArea['type'],
    warehouse: warehouseId || '',
    description: '',
    capacity: 0,
    status: 'Active' as WarehouseArea['status']
  })

  useEffect(() => {
    fetchWarehouses()
    fetchAreas()
  }, [warehouseId])

  const fetchWarehouses = async () => {
    try {
      const response = await fetch('/api/erpnext/warehouses')
      if (response.ok) {
        const data = await response.json()
        setWarehouses(data.warehouses || [])
        if (!warehouseId && data.warehouses?.length > 0) {
          setNewArea({ ...newArea, warehouse: data.warehouses[0].name })
        }
      }
    } catch (error) {
      console.error('Error fetching warehouses:', error)
    }
  }

  const fetchAreas = async () => {
    try {
      // In production, this would fetch from API
      // For now, use mock data
      setAreas(generateMockAreas())
      setLoading(false)
    } catch (error) {
      console.error('Error fetching areas:', error)
      setLoading(false)
    }
  }

  const generateMockAreas = (): WarehouseArea[] => {
    return [
      {
        id: 'area-001',
        name: 'Zone A',
        type: 'Zone',
        warehouse: warehouseId || 'WH-001',
        description: 'Main storage zone',
        capacity: 10000,
        currentUtilization: 7500,
        status: 'Active'
      },
      {
        id: 'area-002',
        name: 'Zone B',
        type: 'Zone',
        warehouse: warehouseId || 'WH-001',
        description: 'Secondary storage zone',
        capacity: 8000,
        currentUtilization: 6000,
        status: 'Active'
      },
      {
        id: 'area-003',
        name: 'Aisle 01',
        type: 'Aisle',
        parentId: 'area-001',
        warehouse: warehouseId || 'WH-001',
        description: 'Main aisle in Zone A',
        status: 'Active'
      }
    ]
  }

  const handleCreateArea = () => {
    const areaData: WarehouseArea = {
      id: `area-${Date.now()}`,
      ...newArea
    }
    setAreas([...areas, areaData])
    onAreaCreate?.(newArea)
    setShowCreateModal(false)
    setNewArea({
      name: '',
      type: 'Zone',
      warehouse: warehouseId || warehouses[0]?.name || '',
      description: '',
      capacity: 0,
      status: 'Active'
    })
  }

  const handleUpdateArea = () => {
    if (!selectedArea) return
    setAreas(areas.map(a => a.id === selectedArea.id ? selectedArea : a))
    onAreaUpdate?.(selectedArea)
    setShowEditModal(false)
    setSelectedArea(null)
  }

  const handleDeleteArea = (areaId: string) => {
    if (confirm('Are you sure you want to delete this area?')) {
      setAreas(areas.filter(a => a.id !== areaId))
      onAreaDelete?.(areaId)
    }
  }

  const filteredAreas = warehouseId 
    ? areas.filter(a => a.warehouse === warehouseId)
    : areas

  const groupedAreas = filteredAreas.reduce((acc, area) => {
    if (!acc[area.type]) {
      acc[area.type] = []
    }
    acc[area.type].push(area)
    return acc
  }, {} as Record<string, WarehouseArea[]>)

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Warehouse Areas</h3>
          <p className="text-sm text-gray-600 dark:text-gray-400">Manage zones, aisles, and sections</p>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors flex items-center gap-2"
        >
          <i className="ri-add-line"></i>
          Add Area
        </button>
      </div>

      {/* Filter by Type */}
      <div className="flex gap-2">
        {(['Zone', 'Aisle', 'Section', 'Area'] as const).map((type) => (
          <button
            key={type}
            onClick={() => setSelectedType(type)}
            className={`px-4 py-2 rounded-lg transition-colors ${
              selectedType === type
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
            }`}
          >
            {type}s ({groupedAreas[type]?.length || 0})
          </button>
        ))}
      </div>

      {/* Areas List */}
      {loading ? (
        <div className="text-center py-12">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">Loading areas...</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {(groupedAreas[selectedType] || []).map((area) => (
            <motion.div
              key={area.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-white dark:bg-gray-800 rounded-lg shadow p-6 hover:shadow-lg transition-shadow cursor-pointer"
              onClick={() => {
                setSelectedArea(area)
                onAreaSelect?.(area)
                setShowEditModal(true)
              }}
            >
              <div className="flex justify-between items-start mb-3">
                <div>
                  <h4 className="text-lg font-semibold text-gray-900 dark:text-gray-100">{area.name}</h4>
                  <p className="text-sm text-gray-600 dark:text-gray-400">{area.type}</p>
                </div>
                <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                  area.status === 'Active'
                    ? 'bg-green-100 dark:bg-green-900 text-green-800 dark:text-green-200'
                    : area.status === 'Maintenance'
                    ? 'bg-yellow-100 dark:bg-yellow-900 text-yellow-800 dark:text-yellow-200'
                    : 'bg-gray-100 dark:bg-gray-700 text-gray-800 dark:text-gray-200'
                }`}>
                  {area.status}
                </span>
              </div>
              
              {area.description && (
                <p className="text-sm text-gray-600 dark:text-gray-400 mb-3">{area.description}</p>
              )}
              
              {area.capacity && (
                <div className="mb-3">
                  <div className="flex justify-between text-sm mb-1">
                    <span className="text-gray-600 dark:text-gray-400">Utilization</span>
                    <span className="text-gray-900 dark:text-gray-100">
                      {area.currentUtilization || 0} / {area.capacity}
                    </span>
                  </div>
                  <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                    <div
                      className="bg-blue-600 h-2 rounded-full transition-all"
                      style={{ 
                        width: `${((area.currentUtilization || 0) / area.capacity) * 100}%` 
                      }}
                    ></div>
                  </div>
                </div>
              )}
              
              <div className="flex gap-2 mt-4">
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    setSelectedArea(area)
                    setShowEditModal(true)
                  }}
                  className="flex-1 px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm transition-colors"
                >
                  <i className="ri-edit-line mr-1"></i>
                  Edit
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    handleDeleteArea(area.id)
                  }}
                  className="px-3 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm transition-colors"
                >
                  <i className="ri-delete-bin-line"></i>
                </button>
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {/* Create Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-md w-full p-6"
          >
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Create New Area</h3>
              <button
                onClick={() => setShowCreateModal(false)}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <i className="ri-close-line text-xl"></i>
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Area Name *
                </label>
                <input
                  type="text"
                  value={newArea.name}
                  onChange={(e) => setNewArea({ ...newArea, name: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                  placeholder="e.g., Zone A, Aisle 01"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Type *
                </label>
                <select
                  value={newArea.type}
                  onChange={(e) => setNewArea({ ...newArea, type: e.target.value as WarehouseArea['type'] })}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="Zone">Zone</option>
                  <option value="Aisle">Aisle</option>
                  <option value="Section">Section</option>
                  <option value="Area">Area</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Warehouse *
                </label>
                <select
                  value={newArea.warehouse}
                  onChange={(e) => setNewArea({ ...newArea, warehouse: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="">Select Warehouse</option>
                  {warehouses.map((wh) => (
                    <option key={wh.name} value={wh.name}>
                      {wh.warehouse_name}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Description
                </label>
                <textarea
                  value={newArea.description}
                  onChange={(e) => setNewArea({ ...newArea, description: e.target.value })}
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                  placeholder="Area description..."
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Capacity (optional)
                </label>
                <input
                  type="number"
                  value={newArea.capacity}
                  onChange={(e) => setNewArea({ ...newArea, capacity: parseInt(e.target.value) || 0 })}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                  min="0"
                />
              </div>
            </div>
            <div className="mt-6 flex justify-end gap-3">
              <button
                onClick={() => setShowCreateModal(false)}
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
              >
                Cancel
              </button>
              <button
                onClick={handleCreateArea}
                disabled={!newArea.name || !newArea.warehouse}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Create Area
              </button>
            </div>
          </motion.div>
        </div>
      )}

      {/* Edit Modal */}
      {showEditModal && selectedArea && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white dark:bg-gray-800 rounded-lg shadow-xl max-w-md w-full p-6"
          >
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Edit Area</h3>
              <button
                onClick={() => {
                  setShowEditModal(false)
                  setSelectedArea(null)
                }}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <i className="ri-close-line text-xl"></i>
              </button>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Area Name
                </label>
                <input
                  type="text"
                  value={selectedArea.name}
                  onChange={(e) => setSelectedArea({ ...selectedArea, name: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status
                </label>
                <select
                  value={selectedArea.status}
                  onChange={(e) => setSelectedArea({ ...selectedArea, status: e.target.value as WarehouseArea['status'] })}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100"
                >
                  <option value="Active">Active</option>
                  <option value="Inactive">Inactive</option>
                  <option value="Maintenance">Maintenance</option>
                </select>
              </div>
            </div>
            <div className="mt-6 flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowEditModal(false)
                  setSelectedArea(null)
                }}
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700"
              >
                Cancel
              </button>
              <button
                onClick={handleUpdateArea}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg"
              >
                Save Changes
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  )
}

/**
 * ASN List Component
 * Displays a list of ASNs with filtering and sorting
 */

'use client'

import { useState, useEffect } from 'react'
import { Card, CardContent } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import type { ASN, ASNStatus, ASNListResponse } from '@/types/asn'
import {
  RiSearchLine,
  RiFilterLine,
  RiArrowRightLine,
  RiFileList3Line,
} from 'react-icons/ri'
import Link from 'next/link'

interface AsnListProps {
  initialData?: ASNListResponse
  onAsnClick?: (asn: ASN) => void
}

export function AsnList({ initialData, onAsnClick }: AsnListProps) {
  const [data, setData] = useState<ASNListResponse | null>(initialData || null)
  const [loading, setLoading] = useState(!initialData)
  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState<string>('all')
  const [page, setPage] = useState(1)

  useEffect(() => {
    if (!initialData) {
      loadAsns()
    }
  }, [page, statusFilter, search])

  const loadAsns = async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams({
        page: page.toString(),
        limit: '20',
      })

      if (statusFilter !== 'all') {
        params.append('status', statusFilter)
      }

      if (search) {
        params.append('search', search)
      }

      const response = await fetch(`/api/asn?${params.toString()}`)
      
      if (!response.ok) {
        throw new Error('Failed to load ASNs')
      }

      const asnData = await response.json()
      setData(asnData)
    } catch (error: any) {
      console.error('Error loading ASNs:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSearch = (value: string) => {
    setSearch(value)
    setPage(1) // Reset to first page on search
  }

  const getStatusColor = (status: ASNStatus) => {
    switch (status) {
      case 'completed':
        return 'bg-green-100 text-green-800'
      case 'exception':
        return 'bg-red-100 text-red-800'
      case 'receiving':
        return 'bg-blue-100 text-blue-800'
      case 'in_transit':
        return 'bg-purple-100 text-purple-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  if (loading && !data) {
    return <div className="text-center py-8">Loading ASNs...</div>
  }

  if (!data) {
    return <div className="text-center py-8">No ASNs found</div>
  }

  return (
    <div className="space-y-4">
      {/* Filters */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1 relative">
              <RiSearchLine className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search ASNs..."
                value={search}
                onChange={(e) => handleSearch(e.target.value)}
                className="pl-10"
              />
            </div>
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-full md:w-[200px]">
                <RiFilterLine className="h-4 w-4 mr-2" />
                <SelectValue placeholder="Filter by status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Statuses</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
                <SelectItem value="in_transit">In Transit</SelectItem>
                <SelectItem value="arrived">Arrived</SelectItem>
                <SelectItem value="receiving">Receiving</SelectItem>
                <SelectItem value="received">Received</SelectItem>
                <SelectItem value="exception">Exception</SelectItem>
                <SelectItem value="completed">Completed</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* ASN List */}
      <div className="space-y-2">
        {data.data.length === 0 ? (
          <Card>
            <CardContent className="py-12 text-center">
              <RiFileList3Line className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <p className="text-muted-foreground">No ASNs found</p>
            </CardContent>
          </Card>
        ) : (
          data.data.map((asn) => (
            <AsnListItem
              key={asn.id}
              asn={asn}
              onClick={() => onAsnClick?.(asn)}
              statusColor={getStatusColor(asn.status)}
            />
          ))
        )}
      </div>

      {/* Pagination */}
      {data.pagination.totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            Showing {((page - 1) * data.pagination.limit) + 1} to{' '}
            {Math.min(page * data.pagination.limit, data.pagination.total)} of{' '}
            {data.pagination.total} ASNs
          </p>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage(page - 1)}
              disabled={page === 1}
            >
              Previous
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage(page + 1)}
              disabled={page >= data.pagination.totalPages}
            >
              Next
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

function AsnListItem({
  asn,
  onClick,
  statusColor,
}: {
  asn: ASN
  onClick: () => void
  statusColor: string
}) {
  return (
    <Link href={`/asn/processing/${asn.id}`}>
      <Card className="cursor-pointer hover:bg-accent transition-colors" onClick={onClick}>
        <CardContent className="pt-6">
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <h3 className="font-semibold">{asn.asnNumber}</h3>
                <Badge className={statusColor}>
                  {asn.status.replace('_', ' ')}
                </Badge>
                {asn.priority === 'urgent' && (
                  <Badge variant="destructive">Urgent</Badge>
                )}
              </div>
              
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                <div>
                  <p className="text-muted-foreground">Supplier</p>
                  <p className="font-medium">{asn.supplierName}</p>
                </div>
                <div>
                  <p className="text-muted-foreground">Items</p>
                  <p className="font-medium">{asn.totalItems}</p>
                </div>
                <div>
                  <p className="text-muted-foreground">Value</p>
                  <p className="font-medium">
                    {new Intl.NumberFormat('en-US', {
                      style: 'currency',
                      currency: asn.currency || 'SAR',
                      minimumFractionDigits: 0,
                    }).format(asn.totalValue)}
                  </p>
                </div>
                <div>
                  <p className="text-muted-foreground">Expected</p>
                  <p className="font-medium">
                    {asn.expectedArrivalDate
                      ? new Date(asn.expectedArrivalDate).toLocaleDateString()
                      : 'N/A'}
                  </p>
                </div>
              </div>

              {asn.exceptions.length > 0 && (
                <div className="mt-3 flex items-center gap-2 text-sm text-red-600">
                  <RiFileList3Line className="h-4 w-4" />
                  <span>{asn.exceptions.length} exception(s)</span>
                </div>
              )}
            </div>

            <RiArrowRightLine className="h-5 w-5 text-muted-foreground ml-4" />
          </div>
        </CardContent>
      </Card>
    </Link>
  )
}

/**
 * ASN Processing Interface Component
 * Interactive interface for processing ASNs
 */

'use client'

import { useState, useEffect } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import type { ASN, ASNItem, ASNException } from '@/types/asn'
import {
  RiCheckboxCircleLine,
  RiCloseCircleLine,
  RiFileList3Line,
  RiAlertLine,
  RiSaveLine,
  RiSendPlaneLine,
} from 'react-icons/ri'

interface AsnProcessingInterfaceProps {
  asnId: string
  onUpdate?: (asn: ASN) => void
}

export function AsnProcessingInterface({ asnId, onUpdate }: AsnProcessingInterfaceProps) {
  const [asn, setAsn] = useState<ASN | null>(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [activeTab, setActiveTab] = useState('overview')

  useEffect(() => {
    loadAsn()
  }, [asnId])

  const loadAsn = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/asn/${asnId}?includeItems=true&includeExceptions=true&includeDocuments=true`)
      
      if (!response.ok) {
        throw new Error('Failed to load ASN')
      }

      const asnData = await response.json()
      setAsn(asnData)
    } catch (error: any) {
      console.error('Error loading ASN:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleStatusUpdate = async (newStatus: string) => {
    if (!asn) return

    try {
      setSaving(true)
      const response = await fetch(`/api/asn/${asnId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })

      if (!response.ok) {
        throw new Error('Failed to update status')
      }

      const updatedAsn = await response.json()
      setAsn(updatedAsn)
      onUpdate?.(updatedAsn)
    } catch (error: any) {
      console.error('Error updating status:', error)
    } finally {
      setSaving(false)
    }
  }

  const handleItemUpdate = async (itemId: string, receivedQuantity: number) => {
    if (!asn) return

    try {
      setSaving(true)
      const response = await fetch(`/api/asn/${asnId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          items: [{
            id: itemId,
            receivedQuantity,
            status: receivedQuantity > 0 ? 'received' : 'pending',
          }],
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to update item')
      }

      const updatedAsn = await response.json()
      setAsn(updatedAsn)
      onUpdate?.(updatedAsn)
    } catch (error: any) {
      console.error('Error updating item:', error)
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return <div className="text-center py-8">Loading ASN...</div>
  }

  if (!asn) {
    return <div className="text-center py-8">ASN not found</div>
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed':
        return 'bg-green-100 text-green-800'
      case 'exception':
        return 'bg-red-100 text-red-800'
      case 'receiving':
        return 'bg-blue-100 text-blue-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-2xl">{asn.asnNumber}</CardTitle>
              <p className="text-sm text-muted-foreground mt-1">
                {asn.supplierName} • {asn.warehouseName || asn.warehouseId}
              </p>
            </div>
            <div className="flex items-center gap-2">
              <Badge className={getStatusColor(asn.status)}>
                {asn.status.replace('_', ' ')}
              </Badge>
              {asn.priority === 'urgent' && (
                <Badge variant="destructive">Urgent</Badge>
              )}
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <Label className="text-xs text-muted-foreground">Total Items</Label>
              <p className="text-lg font-semibold">{asn.totalItems}</p>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Total Quantity</Label>
              <p className="text-lg font-semibold">{asn.totalQuantity}</p>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Total Value</Label>
              <p className="text-lg font-semibold">
                {new Intl.NumberFormat('en-US', {
                  style: 'currency',
                  currency: asn.currency || 'SAR',
                }).format(asn.totalValue)}
              </p>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Expected Arrival</Label>
              <p className="text-lg font-semibold">
                {asn.expectedArrivalDate
                  ? new Date(asn.expectedArrivalDate).toLocaleDateString()
                  : 'N/A'}
              </p>
            </div>
          </div>

          {/* Quick Actions */}
          <div className="flex gap-2 mt-4">
            {asn.status === 'pending' && (
              <Button
                onClick={() => handleStatusUpdate('receiving')}
                disabled={saving}
              >
                <RiCheckboxCircleLine className="h-4 w-4 mr-2" />
                Start Receiving
              </Button>
            )}
            {asn.status === 'receiving' && (
              <Button
                onClick={() => handleStatusUpdate('received')}
                disabled={saving}
              >
                <RiCheckboxCircleLine className="h-4 w-4 mr-2" />
                Mark as Received
              </Button>
            )}
            {asn.status === 'received' && (
              <Button
                onClick={() => handleStatusUpdate('completed')}
                disabled={saving}
              >
                <RiCheckboxCircleLine className="h-4 w-4 mr-2" />
                Complete
              </Button>
            )}
            {asn.exceptions.length > 0 && (
              <Button variant="outline" disabled={saving}>
                <RiAlertLine className="h-4 w-4 mr-2" />
                View Exceptions ({asn.exceptions.length})
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="items">
            Items ({asn.items.length})
          </TabsTrigger>
          <TabsTrigger value="exceptions">
            Exceptions ({asn.exceptions.length})
          </TabsTrigger>
          <TabsTrigger value="documents">
            Documents ({asn.documents.length})
          </TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>ASN Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>ASN Number</Label>
                  <p className="font-medium">{asn.asnNumber}</p>
                </div>
                <div>
                  <Label>Supplier</Label>
                  <p className="font-medium">{asn.supplierName}</p>
                </div>
                <div>
                  <Label>Warehouse</Label>
                  <p className="font-medium">{asn.warehouseName || asn.warehouseId}</p>
                </div>
                <div>
                  <Label>Status</Label>
                  <Badge className={getStatusColor(asn.status)}>
                    {asn.status.replace('_', ' ')}
                  </Badge>
                </div>
                <div>
                  <Label>Expected Arrival</Label>
                  <p className="font-medium">
                    {asn.expectedArrivalDate
                      ? new Date(asn.expectedArrivalDate).toLocaleString()
                      : 'N/A'}
                  </p>
                </div>
                <div>
                  <Label>Actual Arrival</Label>
                  <p className="font-medium">
                    {asn.actualArrivalDate
                      ? new Date(asn.actualArrivalDate).toLocaleString()
                      : 'Not arrived'}
                  </p>
                </div>
              </div>

              {asn.notes && (
                <div>
                  <Label>Notes</Label>
                  <p className="text-sm text-muted-foreground">{asn.notes}</p>
                </div>
              )}

              {/* Intelligence Metrics */}
              {(asn.predictedArrivalTime || asn.exceptionProbability !== undefined || asn.qualityScore) && (
                <div className="mt-4 pt-4 border-t">
                  <Label className="text-sm font-semibold">Intelligence Metrics</Label>
                  <div className="grid grid-cols-3 gap-4 mt-2">
                    {asn.predictedArrivalTime && (
                      <div>
                        <Label className="text-xs text-muted-foreground">Predicted Arrival</Label>
                        <p className="text-sm font-medium">
                          {new Date(asn.predictedArrivalTime).toLocaleString()}
                        </p>
                      </div>
                    )}
                    {asn.exceptionProbability !== undefined && (
                      <div>
                        <Label className="text-xs text-muted-foreground">Exception Risk</Label>
                        <p className="text-sm font-medium">
                          {(asn.exceptionProbability * 100).toFixed(1)}%
                        </p>
                      </div>
                    )}
                    {asn.qualityScore && (
                      <div>
                        <Label className="text-xs text-muted-foreground">Quality Score</Label>
                        <p className="text-sm font-medium">{asn.qualityScore.toFixed(1)}</p>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="items" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Items</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {asn.items.map((item) => (
                  <AsnItemCard
                    key={item.id}
                    item={item}
                    onUpdate={(receivedQuantity) => handleItemUpdate(item.id, receivedQuantity)}
                    disabled={saving}
                  />
                ))}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="exceptions" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Exceptions</CardTitle>
            </CardHeader>
            <CardContent>
              {asn.exceptions.length === 0 ? (
                <p className="text-center py-8 text-muted-foreground">
                  No exceptions
                </p>
              ) : (
                <div className="space-y-4">
                  {asn.exceptions.map((exception) => (
                    <ExceptionCard key={exception.id} exception={exception} />
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="documents" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Documents</CardTitle>
            </CardHeader>
            <CardContent>
              {asn.documents.length === 0 ? (
                <p className="text-center py-8 text-muted-foreground">
                  No documents
                </p>
              ) : (
                <div className="space-y-2">
                  {asn.documents.map((doc) => (
                    <a
                      key={doc.id}
                      href={doc.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center justify-between p-3 border rounded-lg hover:bg-accent"
                    >
                      <div className="flex items-center gap-2">
                        <RiFileList3Line className="h-4 w-4" />
                        <span className="font-medium">{doc.name}</span>
                      </div>
                      <Badge variant="outline">{doc.type}</Badge>
                    </a>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  )
}

function AsnItemCard({
  item,
  onUpdate,
  disabled,
}: {
  item: ASNItem
  onUpdate: (receivedQuantity: number) => void
  disabled: boolean
}) {
  const [receivedQty, setReceivedQty] = useState(item.receivedQuantity || 0)

  const handleSave = () => {
    onUpdate(receivedQty)
  }

  const isComplete = receivedQty >= item.quantity
  const isPartial = receivedQty > 0 && receivedQty < item.quantity

  return (
    <div className="p-4 border rounded-lg">
      <div className="flex items-start justify-between mb-3">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <p className="font-medium">{item.sku}</p>
            {isComplete && (
              <Badge className="bg-green-100 text-green-800">Complete</Badge>
            )}
            {isPartial && (
              <Badge className="bg-yellow-100 text-yellow-800">Partial</Badge>
            )}
          </div>
          <p className="text-sm text-muted-foreground">{item.description}</p>
        </div>
        <div className="text-right">
          <p className="text-sm font-medium">
            {new Intl.NumberFormat('en-US', {
              style: 'currency',
              currency: 'SAR',
            }).format(item.totalPrice)}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4">
        <div>
          <Label className="text-xs">Expected</Label>
          <Input value={item.quantity} disabled />
        </div>
        <div>
          <Label className="text-xs">Received</Label>
          <Input
            type="number"
            value={receivedQty}
            onChange={(e) => setReceivedQty(Number(e.target.value))}
            min={0}
            max={item.quantity}
            disabled={disabled}
          />
        </div>
        <div>
          <Label className="text-xs">Difference</Label>
          <Input
            value={item.quantity - receivedQty}
            disabled
            className={item.quantity - receivedQty !== 0 ? 'border-yellow-500' : ''}
          />
        </div>
      </div>

      <Button
        onClick={handleSave}
        disabled={disabled || receivedQty === item.receivedQuantity}
        className="mt-3"
        size="sm"
      >
        <RiSaveLine className="h-3 w-3 mr-2" />
        Save
      </Button>
    </div>
  )
}

function ExceptionCard({ exception }: { exception: ASNException }) {
  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical':
        return 'bg-red-100 text-red-800 border-red-300'
      case 'high':
        return 'bg-orange-100 text-orange-800 border-orange-300'
      case 'medium':
        return 'bg-yellow-100 text-yellow-800 border-yellow-300'
      default:
        return 'bg-gray-100 text-gray-800 border-gray-300'
    }
  }

  return (
    <div className={`p-4 border-2 rounded-lg ${getSeverityColor(exception.severity)}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
            <RiAlertLine className="h-4 w-4" />
            <p className="font-medium">{exception.type.replace('_', ' ')}</p>
            <Badge>{exception.severity}</Badge>
          </div>
          <p className="text-sm">{exception.description}</p>
        </div>
        <Badge variant="outline">{exception.status}</Badge>
      </div>

      {exception.aiSuggestedResolution && (
        <div className="mt-3 p-2 bg-white/50 rounded text-sm">
          <p className="font-medium mb-1">AI Suggested Resolution:</p>
          <p>{exception.aiSuggestedResolution}</p>
        </div>
      )}

      {exception.resolution && (
        <div className="mt-3 p-2 bg-white/50 rounded text-sm">
          <p className="font-medium mb-1">Resolution:</p>
          <p>{exception.resolution}</p>
        </div>
      )}

      <div className="mt-2 text-xs text-muted-foreground">
        Detected: {new Date(exception.detectedAt).toLocaleString()}
      </div>
    </div>
  )
}

/**
 * Executive Dashboard Component
 * High-level ASN metrics and insights for executives
 */

'use client'

import { useEffect, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { Skeleton } from '@/components/ui/skeleton'
import type { ExecutiveDashboardData } from '@/types/asn'
import {
  RiFileList3Line,
  RiTimeLine,
  RiAlertLine,
  RiMoneyDollarCircleLine,
  RiTrendingUpLine,
  RiTrendingDownLine,
} from 'react-icons/ri'

interface ExecutiveDashboardProps {
  tenantId?: string
  days?: number
}

export function ExecutiveDashboard({ tenantId, days = 30 }: ExecutiveDashboardProps) {
  const [data, setData] = useState<ExecutiveDashboardData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    loadDashboardData()
  }, [tenantId, days])

  const loadDashboardData = async () => {
    try {
      setLoading(true)
      const response = await fetch(
        `/api/asn/analytics/dashboard?type=executive&days=${days}`
      )
      
      if (!response.ok) {
        throw new Error('Failed to load dashboard data')
      }

      const dashboardData = await response.json()
      setData(dashboardData)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return <DashboardSkeleton />
  }

  if (error) {
    return (
      <Alert variant="destructive">
        <AlertTitle>Error</AlertTitle>
        <AlertDescription>{error}</AlertDescription>
      </Alert>
    )
  }

  if (!data) {
    return null
  }

  const { summary, trends, topSuppliers, recentExceptions, alerts } = data

  return (
    <div className="space-y-6">
      {/* Alerts */}
      {alerts.length > 0 && (
        <div className="space-y-2">
          {alerts.map((alert) => (
            <Alert
              key={alert.id}
              variant={alert.type === 'error' ? 'destructive' : 'default'}
            >
              <AlertTitle>{alert.title}</AlertTitle>
              <AlertDescription>{alert.message}</AlertDescription>
            </Alert>
          ))}
        </div>
      )}

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total ASNs</CardTitle>
            <RiFileList3Line className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summary.totalAsns}</div>
            <p className="text-xs text-muted-foreground">
              Last {days} days
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending</CardTitle>
            <RiTimeLine className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summary.pendingAsns}</div>
            <p className="text-xs text-muted-foreground">
              Awaiting arrival
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Exceptions</CardTitle>
            <RiAlertLine className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-destructive">
              {summary.exceptionAsns}
            </div>
            <p className="text-xs text-muted-foreground">
              Requiring attention
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Value</CardTitle>
            <RiMoneyDollarCircleLine className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {new Intl.NumberFormat('en-US', {
                style: 'currency',
                currency: 'SAR',
                minimumFractionDigits: 0,
              }).format(summary.totalValue)}
            </div>
            <p className="text-xs text-muted-foreground">
              Last {days} days
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Trends and Performance */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Top Suppliers */}
        <Card>
          <CardHeader>
            <CardTitle>Top Suppliers</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {topSuppliers.slice(0, 5).map((supplier) => (
                <div key={supplier.supplierId} className="flex items-center justify-between">
                  <div className="flex-1">
                    <p className="font-medium">{supplier.supplierName}</p>
                    <p className="text-sm text-muted-foreground">
                      {supplier.onTimeDeliveryRate * 100}% on-time
                    </p>
                  </div>
                  <div className="text-right">
                    <div className="font-bold">
                      {supplier.overallScore.toFixed(1)}
                    </div>
                    <div className="text-xs text-muted-foreground">Score</div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Recent Exceptions */}
        <Card>
          <CardHeader>
            <CardTitle>Recent Exceptions</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {recentExceptions.slice(0, 5).map((exception) => (
                <div key={exception.id} className="flex items-start justify-between">
                  <div className="flex-1">
                    <p className="font-medium text-sm">{exception.type}</p>
                    <p className="text-xs text-muted-foreground">
                      {exception.description}
                    </p>
                  </div>
                  <div className="text-right">
                    <span
                      className={`text-xs px-2 py-1 rounded ${
                        exception.severity === 'critical'
                          ? 'bg-red-100 text-red-800'
                          : exception.severity === 'high'
                          ? 'bg-orange-100 text-orange-800'
                          : 'bg-yellow-100 text-yellow-800'
                      }`}
                    >
                      {exception.severity}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

function DashboardSkeleton() {
  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {[1, 2, 3, 4].map((i) => (
          <Card key={i}>
            <CardHeader>
              <Skeleton className="h-4 w-24" />
            </CardHeader>
            <CardContent>
              <Skeleton className="h-8 w-16 mb-2" />
              <Skeleton className="h-3 w-32" />
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  )
}

/**
 * Camera-Based Barcode Scanner Component
 * Real-time barcode/QR code detection using device camera
 */

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

interface CameraScannerProps {
  onScan: (barcode: string) => void
  onClose: () => void
  isOpen: boolean
  scanType?: 'barcode' | 'qr' | 'both'
}

export default function CameraScanner({
  onScan,
  onClose,
  isOpen,
  scanType = 'both'
}: CameraScannerProps) {
  const videoRef = useRef<HTMLVideoElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [stream, setStream] = useState<MediaStream | null>(null)
  const [scanning, setScanning] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [lastScanned, setLastScanned] = useState<string | null>(null)
  const scanIntervalRef = useRef<NodeJS.Timeout | null>(null)

  useEffect(() => {
    if (isOpen) {
      startCamera()
    } else {
      stopCamera()
    }

    return () => {
      stopCamera()
    }
  }, [isOpen])

  const startCamera = async () => {
    try {
      setError(null)
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: 'environment', // Use back camera on mobile
          width: { ideal: 1280 },
          height: { ideal: 720 },
        }
      })

      setStream(mediaStream)
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream
        await videoRef.current.play()
        setScanning(true)
        startScanning()
      }
    } catch (err: any) {
      console.error('Camera error:', err)
      setError(err.message || 'Failed to access camera')
      setScanning(false)
    }
  }

  const stopCamera = async () => {
    // Stop QuaggaJS if running
    try {
      const { quaggaService } = await import('@/lib/services/barcode/quaggaService')
      await quaggaService.stopScanning()
    } catch (error) {
      // QuaggaJS not available, continue
    }

    if (stream) {
      stream.getTracks().forEach(track => track.stop())
      setStream(null)
    }
    if (scanIntervalRef.current) {
      clearInterval(scanIntervalRef.current)
      scanIntervalRef.current = null
    }
    setScanning(false)
  }

  const startScanning = async () => {
    // Try to use QuaggaJS for real-time scanning
    try {
      const { quaggaService } = await import('@/lib/services/barcode/quaggaService')

      if (videoRef.current) {
        const started = await quaggaService.startScanning(
          videoRef.current,
          (result) => {
            if (result.code && result.code !== lastScanned) {
              setLastScanned(result.code)
              onScan(result.code)
            }
          },
          {
            readers: scanType === 'qr' ? ['qr_reader'] : 
                     scanType === 'barcode' ? ['code_128_reader', 'ean_reader'] :
                     ['qr_reader', 'code_128_reader', 'ean_reader'],
          }
        )

        if (started) {
          // QuaggaJS is handling scanning
          return
        }
      }
    } catch (error) {
      console.log('QuaggaJS not available - using canvas fallback')
    }

    // Fallback: Canvas-based scanning (manual detection)
    scanIntervalRef.current = setInterval(() => {
      if (videoRef.current && canvasRef.current) {
        const video = videoRef.current
        const canvas = canvasRef.current
        const ctx = canvas.getContext('2d')

        if (ctx && video.readyState === video.HAVE_ENOUGH_DATA) {
          canvas.width = video.videoWidth
          canvas.height = video.videoHeight
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height)

          // Try to detect barcode/QR code
          detectBarcode(canvas)
        }
      }
    }, 500) // Scan every 500ms
  }

  const detectBarcode = async (canvas: HTMLCanvasElement) => {
    try {
      // Try to use QuaggaJS if available
      try {
        const { quaggaService } = await import('@/lib/services/barcode/quaggaService')

        const imageBlob = await new Promise<Blob>((resolve) => {
          canvas.toBlob((blob) => {
            if (blob) resolve(blob)
          }, 'image/png')
        })

        if (imageBlob) {
          const imageFile = new File([imageBlob], 'scan.png', { type: 'image/png' })
          const result = await quaggaService.scanFromImage(imageFile)

          if (result && result.code && result.code !== lastScanned) {
            setLastScanned(result.code)
            onScan(result.code)
          }
        }
      } catch (quaggaError) {
        // QuaggaJS not available, fall back to manual input
        console.log('QuaggaJS not available - using manual input')
      }
    } catch (error) {
      console.error('Barcode detection error:', error)
    }
  }

  if (!isOpen) return null

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-50 bg-black/90 flex items-center justify-center"
        onClick={onClose}
      >
        <motion.div
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.9, opacity: 0 }}
          className="bg-gray-900 rounded-xl p-6 max-w-md w-full mx-4"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-bold text-white">Scan Barcode/QR Code</h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-white transition"
            >
              <i className="ri-close-line text-2xl"></i>
            </button>
          </div>

          {error && (
            <div className="mb-4 p-3 rounded-lg bg-red-900/20 border border-red-500/30">
              <p className="text-sm text-red-400">{error}</p>
              <p className="text-xs text-gray-400 mt-1">
                Make sure camera permissions are granted
              </p>
            </div>
          )}

          <div className="relative mb-4">
            <video
              ref={videoRef}
              className="w-full rounded-lg bg-black"
              autoPlay
              playsInline
              muted
            />
            <canvas ref={canvasRef} className="hidden" />

            {/* Scanning overlay */}
            {scanning && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="border-2 border-cyan-400 rounded-lg w-64 h-64">
                  <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-cyan-400"></div>
                  <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-cyan-400"></div>
                  <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-cyan-400"></div>
                  <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-cyan-400"></div>
                </div>
              </div>
            )}
          </div>

          {lastScanned && (
            <div className="mb-4 p-3 rounded-lg bg-green-900/20 border border-green-500/30">
              <p className="text-sm text-green-400">Last scanned: {lastScanned}</p>
            </div>
          )}

          {/* Manual input fallback */}
          <div className="space-y-3">
            <p className="text-sm text-gray-400 text-center">
              Or enter barcode manually:
            </p>
            <input
              type="text"
              placeholder="Enter barcode/QR code"
              className="w-full px-4 py-2 rounded-lg bg-gray-800 border border-gray-700 text-white focus:border-cyan-500 outline-none"
              onKeyDown={(e) => {
                if (e.key === 'Enter' && e.currentTarget.value) {
                  onScan(e.currentTarget.value)
                  e.currentTarget.value = ''
                }
              }}
            />
          </div>

          <div className="mt-4 flex gap-2">
            <button
              onClick={stopCamera}
              className="flex-1 px-4 py-2 rounded-lg bg-gray-700 hover:bg-gray-600 text-white transition"
            >
              Stop Camera
            </button>
            <button
              onClick={onClose}
              className="flex-1 px-4 py-2 rounded-lg bg-cyan-500 hover:bg-cyan-600 text-white transition"
            >
              Close
            </button>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  )
}

/**
 * BIM AR/VR Tab Component
 * 
 * Full AR/VR support with immersive visualization sessions
 * Supports AR, VR, and mixed reality experiences
 */

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion } from 'framer-motion'
import { format } from 'date-fns'
import type { BIMARVRSession } from '@/types/bim-marketplace'
import { useNotifications } from '@/lib/utils/notifications'
import Modal from '@/components/Modal'
import { WebSocketService } from '@/lib/services/realtime/websocketService'

interface ARVRTabProps {
  modelId?: string
  onSessionStart?: (session: BIMARVRSession) => void
}

export default function ARVRTab({ modelId, onSessionStart }: ARVRTabProps) {
  const [sessions, setSessions] = useState<BIMARVRSession[]>([])
  const [selectedSession, setSelectedSession] = useState<BIMARVRSession | null>(null)
  const [loading, setLoading] = useState(true)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [showSessionModal, setShowSessionModal] = useState(false)
  const [isRealtimeConnected, setIsRealtimeConnected] = useState(false)
  const notifications = useNotifications()
  const wsRef = useRef<WebSocketService | null>(null)

  useEffect(() => {
    if (modelId) {
      loadSessions()
    }
  }, [modelId])

  // WebSocket connection for real-time AR/VR session updates
  useEffect(() => {
    if (typeof window === 'undefined') return

    const ws = new WebSocketService()
    wsRef.current = ws

    ws.connect()
      .then(() => {
        setIsRealtimeConnected(true)
        
        // Subscribe to AR/VR session updates
        ws.on('notification', (event) => {
          if (event.data.type === 'bim-ar-vr') {
            const { sessionId, action, data } = event.data
            
            if (action === 'participant-joined' || action === 'participant-left') {
              setSessions(prev => prev.map(s => 
                s.id === sessionId 
                  ? { ...s, participants: data.participants }
                  : s
              ))
              if (selectedSession?.id === sessionId) {
                setSelectedSession(prev => prev ? {
                  ...prev,
                  participants: data.participants
                } : null)
              }
            } else if (action === 'session-status-changed') {
              setSessions(prev => prev.map(s => 
                s.id === sessionId 
                  ? { ...s, status: data.status }
                  : s
              ))
              if (selectedSession?.id === sessionId) {
                setSelectedSession(prev => prev ? {
                  ...prev,
                  status: data.status
                } : null)
              }
            }
          }
        })
      })
      .catch((error) => {
        console.warn('WebSocket connection failed:', error)
        setIsRealtimeConnected(false)
      })

    return () => {
      ws.disconnect()
      setIsRealtimeConnected(false)
    }
  }, [selectedSession?.id])

  const loadSessions = async () => {
    setLoading(true)
    try {
      // In real app, fetch from AR/VR service
      const mockSessions: BIMARVRSession[] = []
      setSessions(mockSessions)
    } catch (error) {
      console.error('Error loading AR/VR sessions:', error)
      notifications.error('Error', 'Failed to load AR/VR sessions')
    } finally {
      setLoading(false)
    }
  }

  const handleCreateSession = async (sessionData: any) => {
    try {
      // In real app, create via AR/VR service
      notifications.success('Session Created', 'AR/VR session is ready')
      setShowCreateModal(false)
      loadSessions()
    } catch (error) {
      notifications.error('Error', 'Failed to create AR/VR session')
    }
  }

  const handleStartSession = async (sessionId: string) => {
    try {
      const session = sessions.find(s => s.id === sessionId)
      if (!session) return

      // Notify via WebSocket if connected
      if (wsRef.current?.isConnected()) {
        wsRef.current.send('notification', {
          type: 'bim-ar-vr',
          action: 'session-started',
          sessionId,
          userId: 'user-1',
        })
      }

      notifications.success('Session Starting', 'Preparing immersive experience...')
      onSessionStart?.(session)
    } catch (error) {
      notifications.error('Error', 'Failed to start AR/VR session')
    }
  }

  const sessionTypes = [
    {
      id: 'ar',
      label: 'Augmented Reality',
      icon: 'ri-smartphone-line',
      description: 'View BIM models in AR on your mobile device',
      color: 'blue',
    },
    {
      id: 'vr',
      label: 'Virtual Reality',
      icon: 'ri-vr-line',
      description: 'Immersive VR experience with VR headset',
      color: 'purple',
    },
    {
      id: 'mixed-reality',
      label: 'Mixed Reality',
      icon: 'ri-glasses-line',
      description: 'Combine AR and VR for mixed reality experience',
      color: 'cyan',
    },
  ]

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-500/20 text-green-400 border-green-500/30'
      case 'paused': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'
      case 'ended': return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
      default: return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
        <p className="text-gray-400 text-sm">Loading AR/VR sessions...</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">AR/VR Visualization</h2>
          <div className="flex items-center gap-2">
            <p className="text-gray-400 text-sm">Immersive AR and VR experiences for BIM models</p>
            {isRealtimeConnected && (
              <span className="px-2 py-1 bg-green-500/20 text-green-400 rounded text-xs flex items-center gap-1">
                <i className="ri-wifi-line"></i>
                Live
              </span>
            )}
          </div>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          disabled={!modelId}
          className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white text-sm font-medium transition-colors flex items-center gap-2"
        >
          <i className="ri-add-line"></i>
          New Session
        </button>
      </div>

      {/* Session Types Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {sessionTypes.map((type) => (
          <motion.div
            key={type.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            whileHover={{ y: -4 }}
            className={`bg-white/5 border border-white/10 rounded-xl p-6 hover:border-${type.color}-500/30 transition-all cursor-pointer`}
            onClick={() => {
              setShowCreateModal(true)
            }}
          >
            <div className={`w-12 h-12 rounded-lg bg-${type.color}-500/20 flex items-center justify-center mb-4`}>
              <i className={`${type.icon} text-${type.color}-400 text-2xl`}></i>
            </div>
            <h3 className="text-white font-semibold text-lg mb-2">{type.label}</h3>
            <p className="text-gray-400 text-sm">{type.description}</p>
          </motion.div>
        ))}
      </div>

      {/* Features */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Immersive Walkthrough', icon: 'ri-walk-line', color: 'cyan' },
          { label: 'Element Inspection', icon: 'ri-search-eye-line', color: 'blue' },
          { label: 'Measurement Tools', icon: 'ri-ruler-line', color: 'green' },
          { label: 'Annotation Support', icon: 'ri-edit-line', color: 'purple' },
          { label: 'Multi-User Support', icon: 'ri-team-line', color: 'orange' },
          { label: 'Export Screenshots', icon: 'ri-screenshot-line', color: 'yellow' },
          { label: 'Recording', icon: 'ri-record-circle-line', color: 'red' },
          { label: 'Share Experience', icon: 'ri-share-line', color: 'pink' },
        ].map((feature) => (
          <div
            key={feature.label}
            className="bg-white/5 border border-white/10 rounded-lg p-4 text-center"
          >
            <div className={`w-10 h-10 rounded-lg bg-${feature.color}-500/20 flex items-center justify-center mx-auto mb-2`}>
              <i className={`${feature.icon} text-${feature.color}-400`}></i>
            </div>
            <p className="text-white text-sm font-medium">{feature.label}</p>
          </div>
        ))}
      </div>

      {/* Recent Sessions */}
      {sessions.length > 0 && (
        <div>
          <h3 className="text-white font-semibold text-lg mb-4">Recent Sessions</h3>
          <div className="space-y-3">
            {sessions.map((session) => (
              <div
                key={session.id}
                className="bg-white/5 border border-white/10 rounded-lg p-4 hover:border-cyan-500/30 transition-all cursor-pointer"
                onClick={() => {
                  setSelectedSession(session)
                  setShowSessionModal(true)
                }}
              >
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <h4 className="text-white font-medium capitalize">{session.type} Session</h4>
                    <p className="text-gray-400 text-sm">{format(new Date(session.createdAt), 'MMM dd, yyyy HH:mm')}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-xs font-medium border ${getStatusColor(session.status)}`}>
                    {session.status}
                  </span>
                </div>
                <div className="flex items-center gap-4 text-sm text-gray-400 mb-3">
                  <div className="flex items-center gap-2">
                    <i className="ri-time-line"></i>
                    <span>{session.duration || 0} minutes</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <i className="ri-user-line"></i>
                    <span>{session.participants.length} participants</span>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      handleStartSession(session.id)
                    }}
                    className="flex-1 px-3 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white text-sm font-medium transition-colors"
                  >
                    <i className="ri-play-line mr-2"></i>
                    Start
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      setSelectedSession(session)
                      setShowSessionModal(true)
                    }}
                    className="px-3 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white text-sm transition-colors"
                  >
                    <i className="ri-eye-line"></i>
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {sessions.length === 0 && (
        <div className="text-center py-12 bg-white/5 border border-white/10 rounded-lg">
          <i className="ri-vr-line text-4xl text-gray-500 mb-4"></i>
          <p className="text-gray-400 mb-4">No AR/VR sessions yet</p>
          <button
            onClick={() => setShowCreateModal(true)}
            disabled={!modelId}
            className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white text-sm font-medium transition-colors"
          >
            Create Your First Session
          </button>
        </div>
      )}

      {/* Create Session Modal */}
      {showCreateModal && (
        <Modal
          isOpen={showCreateModal}
          onClose={() => setShowCreateModal(false)}
          title="Create AR/VR Session"
          size="lg"
        >
          <CreateARVRSessionForm
            modelId={modelId}
            onSubmit={handleCreateSession}
            onCancel={() => setShowCreateModal(false)}
          />
        </Modal>
      )}

      {/* Session Detail Modal */}
      {showSessionModal && selectedSession && (
        <Modal
          isOpen={showSessionModal}
          onClose={() => setShowSessionModal(false)}
          title={`${selectedSession.type.toUpperCase()} Session`}
          size="lg"
        >
          <ARVRSessionDetailView
            session={selectedSession}
            onStart={() => handleStartSession(selectedSession.id)}
          />
        </Modal>
      )}
    </div>
  )
}

// Create AR/VR Session Form Component
function CreateARVRSessionForm({ modelId, onSubmit, onCancel }: any) {
  const [formData, setFormData] = useState({
    type: 'ar' as 'ar' | 'vr' | 'mixed-reality',
    name: '',
    settings: {
      allowMultiUser: true,
      enableRecording: false,
      enableAnnotations: true,
      enableMeasurements: true,
      quality: 'high' as 'low' | 'medium' | 'high',
    },
    metadata: {},
  })

  return (
    <div className="space-y-6">
      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">Session Type</label>
        <select
          value={formData.type}
          onChange={(e) => setFormData(prev => ({ ...prev, type: e.target.value as any }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500/50"
        >
          <option value="ar">Augmented Reality (AR)</option>
          <option value="vr">Virtual Reality (VR)</option>
          <option value="mixed-reality">Mixed Reality</option>
        </select>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">
          Session Name <span className="text-red-400">*</span>
        </label>
        <input
          type="text"
          value={formData.name}
          onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500/50"
          placeholder="Enter session name"
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">Quality</label>
        <select
          value={formData.settings.quality}
          onChange={(e) => setFormData(prev => ({
            ...prev,
            settings: { ...prev.settings, quality: e.target.value as any },
          }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500/50"
        >
          <option value="low">Low (Faster)</option>
          <option value="medium">Medium (Balanced)</option>
          <option value="high">High (Best Quality)</option>
        </select>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-3">Session Settings</label>
        <div className="space-y-3">
          {Object.entries(formData.settings).filter(([key]) => key !== 'quality').map(([key, value]) => (
            <label key={key} className="flex items-center gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={value as boolean}
                onChange={(e) => setFormData(prev => ({
                  ...prev,
                  settings: { ...prev.settings, [key]: e.target.checked },
                }))}
                className="rounded text-cyan-500 focus:ring-cyan-500"
              />
              <span className="text-sm text-gray-300 capitalize">
                {key.replace(/([A-Z])/g, ' $1').trim()}
              </span>
            </label>
          ))}
        </div>
      </div>

      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button
          onClick={() => onSubmit({ ...formData, modelId, status: 'scheduled' })}
          disabled={!formData.name.trim()}
          className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-medium transition-colors"
        >
          Create Session
        </button>
        <button
          onClick={onCancel}
          className="flex-1 px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors"
        >
          Cancel
        </button>
      </div>
    </div>
  )
}

// AR/VR Session Detail View Component
function ARVRSessionDetailView({ session, onStart }: any) {
  return (
    <div className="space-y-6">
      {/* Session Info */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-sm text-gray-400">Type</label>
          <p className="text-white uppercase">{session.type}</p>
        </div>
        <div>
          <label className="text-sm text-gray-400">Status</label>
          <p className="text-white capitalize">{session.status}</p>
        </div>
        <div>
          <label className="text-sm text-gray-400">Created</label>
          <p className="text-white">{format(new Date(session.createdAt), 'MMM dd, yyyy HH:mm')}</p>
        </div>
        <div>
          <label className="text-sm text-gray-400">Duration</label>
          <p className="text-white">{session.duration || 0} minutes</p>
        </div>
      </div>

      {/* Participants */}
      {session.participants.length > 0 && (
        <div>
          <h4 className="text-white font-medium mb-3">Participants</h4>
          <div className="space-y-2">
            {session.participants.map((p: any) => (
              <div key={p.userId} className="flex items-center gap-3 p-2 bg-white/5 rounded-lg">
                <div className="w-8 h-8 rounded-full bg-cyan-500/20 flex items-center justify-center">
                  <i className="ri-user-line text-cyan-400"></i>
                </div>
                <div className="flex-1">
                  <p className="text-white text-sm">{p.userName}</p>
                  <p className="text-gray-400 text-xs">{p.deviceType}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Requirements */}
      <div>
        <h4 className="text-white font-medium mb-3">Requirements</h4>
        <div className="bg-white/5 rounded-lg p-4 border border-white/10 space-y-2 text-sm">
          {session.type === 'ar' && (
            <>
              <div className="flex items-center gap-2">
                <i className="ri-check-line text-green-400"></i>
                <span className="text-gray-300">Mobile device with AR support</span>
              </div>
              <div className="flex items-center gap-2">
                <i className="ri-check-line text-green-400"></i>
                <span className="text-gray-300">Camera access required</span>
              </div>
            </>
          )}
          {session.type === 'vr' && (
            <>
              <div className="flex items-center gap-2">
                <i className="ri-check-line text-green-400"></i>
                <span className="text-gray-300">VR headset (Oculus, HTC Vive, etc.)</span>
              </div>
              <div className="flex items-center gap-2">
                <i className="ri-check-line text-green-400"></i>
                <span className="text-gray-300">VR controllers</span>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Actions */}
      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button
          onClick={onStart}
          className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white font-medium transition-colors"
        >
          <i className="ri-play-line mr-2"></i>
          Start Session
        </button>
        <button className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors">
          <i className="ri-settings-3-line mr-2"></i>
          Settings
        </button>
      </div>
    </div>
  )
}

/**
 * BIM AI Analysis Tab Component
 * 
 * Full AI analysis UI with clash detection, code compliance, sustainability, cost estimation
 * Real-time analysis results with visualizations
 */

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { format } from 'date-fns'
import type { BIMAIAnalysis } from '@/types/bim-marketplace'
import { useNotifications } from '@/lib/utils/notifications'
import Modal from '@/components/Modal'
import { WebSocketService } from '@/lib/services/realtime/websocketService'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer } from 'recharts'

interface AnalysisTabProps {
  modelId?: string
  onAnalysisComplete?: (analysis: BIMAIAnalysis) => void
}

export default function AnalysisTab({ modelId, onAnalysisComplete }: AnalysisTabProps) {
  const [analyses, setAnalyses] = useState<BIMAIAnalysis[]>([])
  const [selectedAnalysis, setSelectedAnalysis] = useState<BIMAIAnalysis | null>(null)
  const [loading, setLoading] = useState(true)
  const [runningAnalysis, setRunningAnalysis] = useState<string | null>(null)
  const [showAnalysisModal, setShowAnalysisModal] = useState(false)
  const [showRunModal, setShowRunModal] = useState(false)
  const [selectedAnalysisType, setSelectedAnalysisType] = useState<string>('')
  const [isRealtimeConnected, setIsRealtimeConnected] = useState(false)
  const [analysisProgress, setAnalysisProgress] = useState<Record<string, number>>({})
  const notifications = useNotifications()
  const wsRef = useRef<WebSocketService | null>(null)

  useEffect(() => {
    if (modelId) {
      loadAnalyses()
    }
  }, [modelId])

  // WebSocket connection for real-time analysis progress
  useEffect(() => {
    if (typeof window === 'undefined') return

    const ws = new WebSocketService()
    wsRef.current = ws

    ws.connect()
      .then(() => {
        setIsRealtimeConnected(true)
        
        // Subscribe to analysis progress updates
        ws.on('notification', (event) => {
          if (event.data.type === 'bim-analysis') {
            const { analysisId, progress, status, result } = event.data
            
            if (progress !== undefined) {
              setAnalysisProgress(prev => ({ ...prev, [analysisId]: progress }))
            }
            
            if (status === 'completed' && result) {
              setAnalyses(prev => prev.map(a => 
                a.id === analysisId 
                  ? { ...a, status: 'completed', results: result, ...a }
                  : a
              ))
              setAnalysisProgress(prev => {
                const newProgress = { ...prev }
                delete newProgress[analysisId]
                return newProgress
              })
              notifications.success('Analysis Complete', `${result.type || 'Analysis'} completed successfully`)
            } else if (status === 'failed') {
              setAnalyses(prev => prev.map(a => 
                a.id === analysisId 
                  ? { ...a, status: 'failed' }
                  : a
              ))
              setAnalysisProgress(prev => {
                const newProgress = { ...prev }
                delete newProgress[analysisId]
                return newProgress
              })
              notifications.error('Analysis Failed', 'Analysis encountered an error')
            }
          }
        })
      })
      .catch((error) => {
        console.warn('WebSocket connection failed:', error)
        setIsRealtimeConnected(false)
      })

    return () => {
      ws.disconnect()
      setIsRealtimeConnected(false)
    }
  }, [notifications])

  const loadAnalyses = async () => {
    setLoading(true)
    try {
      // In real app, fetch from API
      // For now, use mock data
      const mockAnalyses: BIMAIAnalysis[] = []
      setAnalyses(mockAnalyses)
    } catch (error) {
      console.error('Error loading analyses:', error)
      notifications.error('Error', 'Failed to load analyses')
    } finally {
      setLoading(false)
    }
  }

  const handleRunAnalysis = async (analysisType: string, options: any = {}) => {
    if (!modelId) {
      notifications.error('Model Required', 'Please select a BIM model first')
      return
    }

    setRunningAnalysis(analysisType)
    setShowRunModal(false)

    try {
      const response = await fetch('/api/bim/analysis', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          modelId,
          analysisType,
          options,
        }),
      })

      const result = await response.json()

      if (result.success) {
        notifications.success('Analysis Complete', `${analysisType} analysis completed successfully`)
        setAnalyses(prev => [result.data, ...prev])
        setSelectedAnalysis(result.data)
        setShowAnalysisModal(true)
        onAnalysisComplete?.(result.data)
      } else {
        notifications.error('Analysis Failed', result.error || 'Could not complete analysis')
      }
    } catch (error) {
      notifications.error('Error', 'Failed to run analysis')
    } finally {
      setRunningAnalysis(null)
    }
  }

  const analysisTypes = [
    {
      id: 'clash-detection',
      label: 'Clash Detection',
      icon: 'ri-collision-line',
      description: 'Detect conflicts between different building systems',
      color: 'red',
    },
    {
      id: 'code-compliance',
      label: 'Code Compliance',
      icon: 'ri-file-check-line',
      description: 'Verify compliance with building codes and standards',
      color: 'blue',
    },
    {
      id: 'sustainability',
      label: 'Sustainability Analysis',
      icon: 'ri-leaf-line',
      description: 'Analyze environmental impact and energy efficiency',
      color: 'green',
    },
    {
      id: 'cost-estimation',
      label: 'Cost Estimation',
      icon: 'ri-money-dollar-circle-line',
      description: 'Estimate construction costs based on model data',
      color: 'yellow',
    },
    {
      id: 'safety-analysis',
      label: 'Safety Analysis',
      icon: 'ri-shield-check-line',
      description: 'Identify potential safety hazards and risks',
      color: 'orange',
    },
    {
      id: 'optimization',
      label: 'Design Optimization',
      icon: 'ri-lightbulb-line',
      description: 'AI-powered design recommendations and optimizations',
      color: 'purple',
    },
  ]

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'bg-green-500/20 text-green-400 border-green-500/30'
      case 'processing': return 'bg-blue-500/20 text-blue-400 border-blue-500/30'
      case 'failed': return 'bg-red-500/20 text-red-400 border-red-500/30'
      default: return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
        <p className="text-gray-400 text-sm">Loading analyses...</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
                  {/* Header */}
                  <div className="flex items-center justify-between">
                    <div>
                      <h2 className="text-2xl font-bold text-white mb-2">AI Analysis</h2>
                      <div className="flex items-center gap-2">
                        <p className="text-gray-400 text-sm">AI-powered analysis and insights for your BIM models</p>
                        {isRealtimeConnected && (
                          <span className="px-2 py-1 bg-green-500/20 text-green-400 rounded text-xs flex items-center gap-1">
                            <i className="ri-wifi-line"></i>
                            Live
                          </span>
                        )}
                      </div>
                    </div>
        <button
          onClick={() => setShowRunModal(true)}
          disabled={!modelId}
          className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white text-sm font-medium transition-colors flex items-center gap-2"
        >
          <i className="ri-play-line"></i>
          Run Analysis
        </button>
      </div>

      {/* Analysis Types Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {analysisTypes.map((type) => (
          <motion.div
            key={type.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            whileHover={{ y: -4 }}
            className={`bg-white/5 border border-white/10 rounded-xl p-6 hover:border-${type.color}-500/30 transition-all cursor-pointer ${
              runningAnalysis === type.id ? 'opacity-50' : ''
            }`}
            onClick={() => {
              setSelectedAnalysisType(type.id)
              setShowRunModal(true)
            }}
          >
            <div className={`w-12 h-12 rounded-lg bg-${type.color}-500/20 flex items-center justify-center mb-4`}>
              <i className={`${type.icon} text-${type.color}-400 text-2xl`}></i>
            </div>
            <h3 className="text-white font-semibold text-lg mb-2">{type.label}</h3>
            <p className="text-gray-400 text-sm mb-4">{type.description}</p>
                        {(runningAnalysis === type.id || analysisProgress[type.id] !== undefined) && (
                          <div className="flex items-center gap-2 text-sm text-blue-400">
                            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-400"></div>
                            <span>
                              {analysisProgress[type.id] !== undefined 
                                ? `Running... ${analysisProgress[type.id]}%`
                                : 'Running...'}
                            </span>
                          </div>
                        )}
          </motion.div>
        ))}
      </div>

      {/* Recent Analyses */}
      {analyses.length > 0 && (
        <div>
          <h3 className="text-white font-semibold text-lg mb-4">Recent Analyses</h3>
          <div className="space-y-3">
            {analyses.map((analysis) => (
              <div
                key={analysis.id}
                className="bg-white/5 border border-white/10 rounded-lg p-4 hover:border-cyan-500/30 transition-all cursor-pointer"
                onClick={() => {
                  setSelectedAnalysis(analysis)
                  setShowAnalysisModal(true)
                }}
              >
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <h4 className="text-white font-medium capitalize">{analysis.type.replace('-', ' ')}</h4>
                    <p className="text-gray-400 text-sm">{format(new Date(analysis.createdAt), 'MMM dd, yyyy HH:mm')}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-xs font-medium border ${getStatusColor(analysis.status)}`}>
                    {analysis.status}
                  </span>
                </div>
                {analysis.summary && (
                  <p className="text-gray-300 text-sm line-clamp-2">{analysis.summary}</p>
                )}
                {analysis.confidence && (
                  <div className="mt-3">
                    <div className="flex items-center justify-between text-xs text-gray-400 mb-1">
                      <span>Confidence</span>
                      <span>{(analysis.confidence * 100).toFixed(0)}%</span>
                    </div>
                    <div className="w-full bg-gray-700 rounded-full h-2">
                      <div
                        className="bg-cyan-500 h-2 rounded-full transition-all"
                        style={{ width: `${analysis.confidence * 100}%` }}
                      />
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Run Analysis Modal */}
      {showRunModal && (
        <Modal
          isOpen={showRunModal}
          onClose={() => setShowRunModal(false)}
          title={`Run ${analysisTypes.find(t => t.id === selectedAnalysisType)?.label || 'Analysis'}`}
          size="lg"
        >
          <RunAnalysisForm
            analysisType={selectedAnalysisType}
            onSubmit={(options) => {
              handleRunAnalysis(selectedAnalysisType, options)
            }}
            onCancel={() => setShowRunModal(false)}
          />
        </Modal>
      )}

      {/* Analysis Results Modal */}
      {showAnalysisModal && selectedAnalysis && (
        <Modal
          isOpen={showAnalysisModal}
          onClose={() => setShowAnalysisModal(false)}
          title={`${selectedAnalysis.type.replace('-', ' ').replace(/\b\w/g, l => l.toUpperCase())} Results`}
          size="xl"
        >
          <AnalysisResultsView analysis={selectedAnalysis} />
        </Modal>
      )}
    </div>
  )
}

// Run Analysis Form Component
function RunAnalysisForm({ analysisType, onSubmit, onCancel }: any) {
  const [options, setOptions] = useState<any>({})

  const getFormFields = () => {
    switch (analysisType) {
      case 'clash-detection':
        return (
          <>
            <div>
              <label className="block text-sm font-medium text-gray-300 mb-2">Tolerance (meters)</label>
              <input
                type="number"
                step="0.01"
                value={options.tolerance || 0.1}
                onChange={(e) => setOptions(prev => ({ ...prev, tolerance: parseFloat(e.target.value) }))}
                className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500/50"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-300 mb-2">Systems to Check</label>
              <div className="space-y-2">
                {['architectural', 'structural', 'mep', 'fire-safety'].map((system) => (
                  <label key={system} className="flex items-center gap-2 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={options.systems?.includes(system) || false}
                      onChange={(e) => {
                        const systems = options.systems || []
                        if (e.target.checked) {
                          setOptions(prev => ({ ...prev, systems: [...systems, system] }))
                        } else {
                          setOptions(prev => ({ ...prev, systems: systems.filter((s: string) => s !== system) }))
                        }
                      }}
                      className="rounded text-cyan-500 focus:ring-cyan-500"
                    />
                    <span className="text-sm text-gray-300 capitalize">{system.replace('-', ' ')}</span>
                  </label>
                ))}
              </div>
            </div>
          </>
        )
      case 'code-compliance':
        return (
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">Building Code Standard</label>
            <select
              value={options.standard || 'IBC'}
              onChange={(e) => setOptions(prev => ({ ...prev, standard: e.target.value }))}
              className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500/50"
            >
              <option value="IBC">International Building Code (IBC)</option>
              <option value="NFPA">NFPA Standards</option>
              <option value="ASHRAE">ASHRAE Standards</option>
              <option value="LEED">LEED Certification</option>
            </select>
          </div>
        )
      case 'sustainability':
        return (
          <div>
            <label className="block text-sm font-medium text-gray-300 mb-2">Analysis Focus</label>
            <div className="space-y-2">
              {['energy-efficiency', 'carbon-footprint', 'material-sustainability', 'water-usage'].map((focus) => (
                <label key={focus} className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={options.focusAreas?.includes(focus) || false}
                    onChange={(e) => {
                      const areas = options.focusAreas || []
                      if (e.target.checked) {
                        setOptions(prev => ({ ...prev, focusAreas: [...areas, focus] }))
                      } else {
                        setOptions(prev => ({ ...prev, focusAreas: areas.filter((a: string) => a !== focus) }))
                      }
                    }}
                    className="rounded text-cyan-500 focus:ring-cyan-500"
                  />
                  <span className="text-sm text-gray-300 capitalize">{focus.replace('-', ' ')}</span>
                </label>
              ))}
            </div>
          </div>
        )
      default:
        return null
    }
  }

  return (
    <div className="space-y-6">
      {getFormFields()}
      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button
          onClick={() => onSubmit(options)}
          className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white font-medium transition-colors"
        >
          Run Analysis
        </button>
        <button
          onClick={onCancel}
          className="flex-1 px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors"
        >
          Cancel
        </button>
      </div>
    </div>
  )
}

// Analysis Results View Component
function AnalysisResultsView({ analysis }: { analysis: BIMAIAnalysis }) {
  const renderResults = () => {
    switch (analysis.type) {
      case 'clash-detection':
        return (
          <div className="space-y-4">
            {analysis.results?.clashes && (
              <>
                <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-4">
                  <div className="flex items-center gap-2 mb-2">
                    <i className="ri-collision-line text-red-400"></i>
                    <h4 className="text-white font-medium">Clashes Detected</h4>
                  </div>
                  <p className="text-2xl font-bold text-red-400">{analysis.results.clashes.length}</p>
                </div>
                <div className="space-y-2 max-h-96 overflow-y-auto">
                  {analysis.results.clashes.map((clash: any, idx: number) => (
                    <div key={idx} className="p-3 bg-white/5 rounded-lg border border-white/10">
                      <div className="flex items-start justify-between mb-2">
                        <span className="text-white font-medium">Clash #{idx + 1}</span>
                        <span className={`px-2 py-1 rounded text-xs ${
                          clash.severity === 'critical' ? 'bg-red-500/20 text-red-400' :
                          clash.severity === 'high' ? 'bg-orange-500/20 text-orange-400' :
                          'bg-yellow-500/20 text-yellow-400'
                        }`}>
                          {clash.severity}
                        </span>
                      </div>
                      <p className="text-gray-300 text-sm">
                        {clash.element1} vs {clash.element2}
                      </p>
                      {clash.distance && (
                        <p className="text-gray-400 text-xs mt-1">
                          Distance: {clash.distance.toFixed(3)}m
                        </p>
                      )}
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>
        )
      case 'sustainability':
        return (
          <div className="space-y-4">
            {analysis.results?.metrics && (
              <div className="grid grid-cols-2 gap-4">
                {Object.entries(analysis.results.metrics).map(([key, value]: [string, any]) => (
                  <div key={key} className="bg-white/5 rounded-lg p-4 border border-white/10">
                    <label className="text-sm text-gray-400 capitalize mb-1 block">
                      {key.replace(/([A-Z])/g, ' $1').trim()}
                    </label>
                    <p className="text-2xl font-bold text-cyan-400">{value}</p>
                  </div>
                ))}
              </div>
            )}
            {analysis.results?.chartData && (
              <div className="bg-white/5 rounded-lg p-4 border border-white/10">
                <h4 className="text-white font-medium mb-4">Sustainability Metrics</h4>
                <ResponsiveContainer width="100%" height={300}>
                  <BarChart data={analysis.results.chartData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                    <XAxis dataKey="name" stroke="#9ca3af" />
                    <YAxis stroke="#9ca3af" />
                    <RechartsTooltip contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151' }} />
                    <Bar dataKey="value" fill="#06b6d4" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            )}
          </div>
        )
      case 'cost-estimation':
        return (
          <div className="space-y-4">
            {analysis.results?.totalCost && (
              <div className="bg-green-500/10 border border-green-500/30 rounded-lg p-6 text-center">
                <label className="text-sm text-gray-400 mb-2 block">Estimated Total Cost</label>
                <p className="text-4xl font-bold text-green-400">
                  ${analysis.results.totalCost.toLocaleString()}
                </p>
              </div>
            )}
            {analysis.results?.breakdown && (
              <div className="space-y-2">
                <h4 className="text-white font-medium mb-3">Cost Breakdown</h4>
                {Object.entries(analysis.results.breakdown).map(([category, amount]: [string, any]) => (
                  <div key={category} className="flex items-center justify-between p-3 bg-white/5 rounded-lg">
                    <span className="text-gray-300 capitalize">{category.replace(/([A-Z])/g, ' $1').trim()}</span>
                    <span className="text-white font-medium">${amount.toLocaleString()}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )
      default:
        return (
          <div className="space-y-4">
            {analysis.summary && (
              <div className="bg-white/5 rounded-lg p-4 border border-white/10">
                <h4 className="text-white font-medium mb-2">Summary</h4>
                <p className="text-gray-300 text-sm">{analysis.summary}</p>
              </div>
            )}
            {analysis.recommendations && analysis.recommendations.length > 0 && (
              <div>
                <h4 className="text-white font-medium mb-3">Recommendations</h4>
                <ul className="space-y-2">
                  {analysis.recommendations.map((rec: string, idx: number) => (
                    <li key={idx} className="flex items-start gap-2 p-3 bg-white/5 rounded-lg">
                      <i className="ri-lightbulb-line text-yellow-400 mt-0.5"></i>
                      <span className="text-gray-300 text-sm">{rec}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )
    }
  }

  return (
    <div className="space-y-6">
      {/* Analysis Info */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-sm text-gray-400">Status</label>
          <p className="text-white capitalize">{analysis.status}</p>
        </div>
        <div>
          <label className="text-sm text-gray-400">Created</label>
          <p className="text-white">{format(new Date(analysis.createdAt), 'MMM dd, yyyy HH:mm')}</p>
        </div>
        {analysis.confidence && (
          <div>
            <label className="text-sm text-gray-400">Confidence</label>
            <p className="text-white">{(analysis.confidence * 100).toFixed(0)}%</p>
          </div>
        )}
        {analysis.processingTime && (
          <div>
            <label className="text-sm text-gray-400">Processing Time</label>
            <p className="text-white">{analysis.processingTime}ms</p>
          </div>
        )}
      </div>

      {/* Results */}
      <div>
        <h4 className="text-white font-medium mb-4">Results</h4>
        {renderResults()}
      </div>

      {/* Actions */}
      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white font-medium transition-colors">
          <i className="ri-download-line mr-2"></i>
          Export Report
        </button>
        <button className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors">
          <i className="ri-share-line mr-2"></i>
          Share
        </button>
      </div>
    </div>
  )
}

/**
 * BIM Collaboration Tab Component
 * 
 * Full collaboration UI with sessions, participants, annotations, issues, and chat
 * Real-time collaboration with WebSocket integration
 */

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { format } from 'date-fns'
import type { BIMCollaborationSession, BIMAnnotation, BIMIssue } from '@/types/bim-marketplace'
import { useNotifications } from '@/lib/utils/notifications'
import Modal from '@/components/Modal'
import { WebSocketService } from '@/lib/services/realtime/websocketService'

interface CollaborationTabProps {
  modelId?: string
  onSessionSelect?: (session: BIMCollaborationSession) => void
  onCreateSession?: (session: Omit<BIMCollaborationSession, 'id' | 'createdAt' | 'updatedAt'>) => void
}

export default function CollaborationTab({ modelId, onSessionSelect, onCreateSession }: CollaborationTabProps) {
  const [sessions, setSessions] = useState<BIMCollaborationSession[]>([])
  const [selectedSession, setSelectedSession] = useState<BIMCollaborationSession | null>(null)
  const [loading, setLoading] = useState(true)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [showSessionModal, setShowSessionModal] = useState(false)
  const [activeTab, setActiveTab] = useState<'sessions' | 'annotations' | 'issues' | 'chat'>('sessions')
  const [chatMessage, setChatMessage] = useState('')
  const [isRealtimeConnected, setIsRealtimeConnected] = useState(false)
  const notifications = useNotifications()
  const chatEndRef = useRef<HTMLDivElement>(null)
  const wsRef = useRef<WebSocketService | null>(null)

  useEffect(() => {
    loadSessions()
  }, [modelId])

  // WebSocket connection for real-time collaboration
  useEffect(() => {
    if (typeof window === 'undefined') return

    const ws = new WebSocketService()
    wsRef.current = ws

    ws.connect()
      .then(() => {
        setIsRealtimeConnected(true)
        
        // Subscribe to collaboration events
        ws.on('notification', (event) => {
          if (event.data.type === 'bim-collaboration') {
            const { sessionId, action, data } = event.data
            
            if (action === 'chat-message') {
              setSessions(prev => prev.map(s => 
                s.id === sessionId 
                  ? { ...s, activities: [...s.activities, data] }
                  : s
              ))
              if (selectedSession?.id === sessionId) {
                setSelectedSession(prev => prev ? {
                  ...prev,
                  activities: [...prev.activities, data]
                } : null)
              }
            } else if (action === 'participant-joined' || action === 'participant-left') {
              setSessions(prev => prev.map(s => 
                s.id === sessionId 
                  ? { ...s, participants: data.participants }
                  : s
              ))
              if (selectedSession?.id === sessionId) {
                setSelectedSession(prev => prev ? {
                  ...prev,
                  participants: data.participants
                } : null)
              }
            } else if (action === 'annotation-added') {
              setSessions(prev => prev.map(s => 
                s.id === sessionId 
                  ? { ...s, annotations: [...s.annotations, data] }
                  : s
              ))
              if (selectedSession?.id === sessionId) {
                setSelectedSession(prev => prev ? {
                  ...prev,
                  annotations: [...prev.annotations, data]
                } : null)
              }
            } else if (action === 'issue-added' || action === 'issue-updated') {
              setSessions(prev => prev.map(s => 
                s.id === sessionId 
                  ? { ...s, issues: data.issues }
                  : s
              ))
              if (selectedSession?.id === sessionId) {
                setSelectedSession(prev => prev ? {
                  ...prev,
                  issues: data.issues
                } : null)
              }
            }
          }
        })
      })
      .catch((error) => {
        console.warn('WebSocket connection failed:', error)
        setIsRealtimeConnected(false)
      })

    return () => {
      ws.disconnect()
      setIsRealtimeConnected(false)
    }
  }, [selectedSession?.id])

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' })
    }
  }, [selectedSession?.activities])

  const loadSessions = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams()
      if (modelId) params.set('modelId', modelId)
      params.set('userId', 'user-1') // In real app, get from auth

      const response = await fetch(`/api/bim/collaboration/sessions?${params.toString()}`)
      const result = await response.json()

      if (result.success) {
        setSessions(result.data || [])
      } else {
        notifications.error('Failed to load sessions', result.error || 'Unknown error')
      }
    } catch (error) {
      console.error('Error loading sessions:', error)
      notifications.error('Error', 'Failed to load collaboration sessions')
    } finally {
      setLoading(false)
    }
  }

  const handleCreateSession = async (sessionData: any) => {
    try {
      const response = await fetch('/api/bim/collaboration/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          modelId: modelId || 'model-1',
          hostId: 'user-1',
          hostName: 'Current User',
          session: sessionData,
        }),
      })

      const result = await response.json()

      if (result.success) {
        notifications.success('Session Created', 'Collaboration session is ready')
        setShowCreateModal(false)
        loadSessions()
        onCreateSession?.(result.data)
      } else {
        notifications.error('Failed', result.error || 'Could not create session')
      }
    } catch (error) {
      notifications.error('Error', 'Failed to create collaboration session')
    }
  }

  const handleJoinSession = async (sessionId: string) => {
    try {
      const session = sessions.find(s => s.id === sessionId)
      if (!session) return

      // Join via WebSocket
      if (wsRef.current?.isConnected()) {
        wsRef.current.send('notification', {
          type: 'bim-collaboration',
          action: 'join-session',
          sessionId,
          userId: 'user-1',
          userName: 'Current User',
        })
      }

      notifications.success('Joined Session', 'You are now in the collaboration session')
      onSessionSelect?.(session)
    } catch (error) {
      notifications.error('Error', 'Failed to join session')
    }
  }

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedSession) return

    try {
      // In real app, send via WebSocket
      const newActivity = {
        id: `activity-${Date.now()}`,
        sessionId: selectedSession.id,
        userId: 'user-1',
        userName: 'Current User',
        type: 'chat',
        content: chatMessage,
        timestamp: new Date(),
        metadata: {},
      }

      setChatMessage('')
      notifications.success('Message Sent', 'Your message has been sent')
    } catch (error) {
      notifications.error('Error', 'Failed to send message')
    }
  }

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'bg-green-500/20 text-green-400 border-green-500/30'
      case 'scheduled': return 'bg-blue-500/20 text-blue-400 border-blue-500/30'
      case 'ended': return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
      default: return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
        <p className="text-gray-400 text-sm">Loading collaboration sessions...</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Collaboration Sessions</h2>
          <div className="flex items-center gap-2">
            <p className="text-gray-400 text-sm">Real-time collaboration on BIM models</p>
            {isRealtimeConnected ? (
              <span className="px-2 py-1 bg-green-500/20 text-green-400 rounded text-xs flex items-center gap-1">
                <i className="ri-wifi-line"></i>
                Connected
              </span>
            ) : (
              <span className="px-2 py-1 bg-gray-500/20 text-gray-400 rounded text-xs flex items-center gap-1">
                <i className="ri-wifi-off-line"></i>
                Offline
              </span>
            )}
          </div>
        </div>
        <button
          onClick={() => setShowCreateModal(true)}
          className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white text-sm font-medium transition-colors flex items-center gap-2"
        >
          <i className="ri-add-line"></i>
          New Session
        </button>
      </div>

      {/* Sessions List */}
      {sessions.length === 0 ? (
        <div className="text-center py-12 bg-white/5 border border-white/10 rounded-lg">
          <i className="ri-team-line text-4xl text-gray-500 mb-4"></i>
          <p className="text-gray-400 mb-4">No collaboration sessions found</p>
          <button
            onClick={() => setShowCreateModal(true)}
            className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white text-sm font-medium transition-colors"
          >
            Create Your First Session
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {sessions.map((session) => (
            <motion.div
              key={session.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-white/5 border border-white/10 rounded-xl p-4 hover:border-cyan-500/30 transition-all cursor-pointer"
              onClick={() => {
                setSelectedSession(session)
                setShowSessionModal(true)
              }}
            >
              <div className="flex items-start justify-between mb-3">
                <h3 className="text-white font-semibold text-lg">{session.name}</h3>
                <span className={`px-2 py-1 rounded text-xs font-medium border ${getStatusColor(session.status)}`}>
                  {session.status}
                </span>
              </div>

              <div className="space-y-2 text-sm text-gray-400 mb-4">
                <div className="flex items-center gap-2">
                  <i className="ri-user-line"></i>
                  <span>{session.participants.length} participants</span>
                </div>
                <div className="flex items-center gap-2">
                  <i className="ri-message-line"></i>
                  <span>{session.activities.filter(a => a.type === 'chat').length} messages</span>
                </div>
                <div className="flex items-center gap-2">
                  <i className="ri-edit-line"></i>
                  <span>{session.annotations.length} annotations</span>
                </div>
                <div className="flex items-center gap-2">
                  <i className="ri-alert-line"></i>
                  <span>{session.issues.length} issues</span>
                </div>
              </div>

              <div className="flex gap-2 pt-3 border-t border-white/10">
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    handleJoinSession(session.id)
                  }}
                  className="flex-1 px-3 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white text-sm font-medium transition-colors"
                >
                  <i className="ri-login-box-line mr-2"></i>
                  Join
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    setSelectedSession(session)
                    setShowSessionModal(true)
                  }}
                  className="px-3 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white text-sm transition-colors"
                >
                  <i className="ri-eye-line"></i>
                </button>
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {/* Create Session Modal */}
      {showCreateModal && (
        <Modal
          isOpen={showCreateModal}
          onClose={() => setShowCreateModal(false)}
          title="Create Collaboration Session"
          size="lg"
        >
          <CreateSessionForm
            modelId={modelId}
            onSubmit={(data) => {
              handleCreateSession(data)
            }}
            onCancel={() => setShowCreateModal(false)}
          />
        </Modal>
      )}

      {/* Session Detail Modal */}
      {showSessionModal && selectedSession && (
        <Modal
          isOpen={showSessionModal}
          onClose={() => setShowSessionModal(false)}
          title={selectedSession.name}
          size="xl"
        >
          <SessionDetailView
            session={selectedSession}
            activeTab={activeTab}
            onTabChange={setActiveTab}
            chatMessage={chatMessage}
            onChatMessageChange={setChatMessage}
            onSendMessage={handleSendMessage}
            chatEndRef={chatEndRef}
          />
        </Modal>
      )}
    </div>
  )
}

// Create Session Form Component
function CreateSessionForm({ modelId, onSubmit, onCancel }: any) {
  const [formData, setFormData] = useState({
    name: '',
    settings: {
      allowGuestAccess: true,
      requireApproval: false,
      recordingEnabled: true,
      chatEnabled: true,
      annotationsEnabled: true,
      measurementsEnabled: true,
      exportEnabled: true,
    },
    metadata: {},
  })

  return (
    <div className="space-y-6">
      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">
          Session Name <span className="text-red-400">*</span>
        </label>
        <input
          type="text"
          value={formData.name}
          onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500/50"
          placeholder="Enter session name"
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-3">Session Settings</label>
        <div className="space-y-3">
          {Object.entries(formData.settings).map(([key, value]) => (
            <label key={key} className="flex items-center gap-3 cursor-pointer">
              <input
                type="checkbox"
                checked={value as boolean}
                onChange={(e) => setFormData(prev => ({
                  ...prev,
                  settings: { ...prev.settings, [key]: e.target.checked },
                }))}
                className="rounded text-cyan-500 focus:ring-cyan-500"
              />
              <span className="text-sm text-gray-300 capitalize">
                {key.replace(/([A-Z])/g, ' $1').trim()}
              </span>
            </label>
          ))}
        </div>
      </div>

      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button
          onClick={() => onSubmit({ ...formData, modelId, status: 'scheduled' })}
          disabled={!formData.name.trim()}
          className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-medium transition-colors"
        >
          Create Session
        </button>
        <button
          onClick={onCancel}
          className="flex-1 px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors"
        >
          Cancel
        </button>
      </div>
    </div>
  )
}

// Session Detail View Component
function SessionDetailView({ session, activeTab, onTabChange, chatMessage, onChatMessageChange, onSendMessage, chatEndRef }: any) {
  return (
    <div className="space-y-4">
      {/* Tabs */}
      <div className="flex gap-2 border-b border-white/10">
        {[
          { id: 'sessions', label: 'Overview', icon: 'ri-information-line' },
          { id: 'annotations', label: 'Annotations', icon: 'ri-edit-line' },
          { id: 'issues', label: 'Issues', icon: 'ri-alert-line' },
          { id: 'chat', label: 'Chat', icon: 'ri-message-line' },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => onTabChange(tab.id)}
            className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 ${
              activeTab === tab.id
                ? 'border-cyan-500 text-cyan-400'
                : 'border-transparent text-gray-400 hover:text-white'
            }`}
          >
            <i className={`${tab.icon} mr-2`}></i>
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <AnimatePresence mode="wait">
        {activeTab === 'sessions' && (
          <motion.div
            key="overview"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-4"
          >
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-gray-400">Status</label>
                <p className="text-white capitalize">{session.status}</p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Participants</label>
                <p className="text-white">{session.participants.length}</p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Host</label>
                <p className="text-white">{session.hostName}</p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Created</label>
                <p className="text-white">{format(new Date(session.createdAt), 'MMM dd, yyyy HH:mm')}</p>
              </div>
            </div>

            <div>
              <label className="text-sm text-gray-400 mb-2 block">Participants</label>
              <div className="space-y-2">
                {session.participants.map((p: any) => (
                  <div key={p.userId} className="flex items-center gap-3 p-2 bg-white/5 rounded-lg">
                    <div className="w-8 h-8 rounded-full bg-cyan-500/20 flex items-center justify-center">
                      <i className="ri-user-line text-cyan-400"></i>
                    </div>
                    <div className="flex-1">
                      <p className="text-white text-sm">{p.userName}</p>
                      <p className="text-gray-400 text-xs">{p.role}</p>
                    </div>
                    {p.isActive && (
                      <span className="px-2 py-1 bg-green-500/20 text-green-400 rounded text-xs">Active</span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </motion.div>
        )}

        {activeTab === 'annotations' && (
          <motion.div
            key="annotations"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-3"
          >
            {session.annotations.length === 0 ? (
              <div className="text-center py-8 text-gray-400">
                <i className="ri-edit-line text-4xl mb-2"></i>
                <p>No annotations yet</p>
              </div>
            ) : (
              session.annotations.map((annotation: BIMAnnotation) => (
                <div key={annotation.id} className="p-3 bg-white/5 rounded-lg border border-white/10">
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <div className="w-6 h-6 rounded-full bg-cyan-500/20 flex items-center justify-center">
                        <i className="ri-edit-line text-cyan-400 text-xs"></i>
                      </div>
                      <span className="text-white text-sm font-medium">{annotation.userName}</span>
                    </div>
                    <span className="text-gray-400 text-xs">{format(new Date(annotation.createdAt), 'HH:mm')}</span>
                  </div>
                  <p className="text-gray-300 text-sm">{annotation.content}</p>
                  {annotation.position && (
                    <p className="text-gray-500 text-xs mt-2">
                      Position: ({annotation.position.x.toFixed(2)}, {annotation.position.y.toFixed(2)}, {annotation.position.z.toFixed(2)})
                    </p>
                  )}
                </div>
              ))
            )}
          </motion.div>
        )}

        {activeTab === 'issues' && (
          <motion.div
            key="issues"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="space-y-3"
          >
            {session.issues.length === 0 ? (
              <div className="text-center py-8 text-gray-400">
                <i className="ri-alert-line text-4xl mb-2"></i>
                <p>No issues reported</p>
              </div>
            ) : (
              session.issues.map((issue: BIMIssue) => (
                <div key={issue.id} className="p-4 bg-white/5 rounded-lg border border-white/10">
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <span className={`px-2 py-1 rounded text-xs font-medium ${
                        issue.severity === 'critical' ? 'bg-red-500/20 text-red-400' :
                        issue.severity === 'high' ? 'bg-orange-500/20 text-orange-400' :
                        issue.severity === 'medium' ? 'bg-yellow-500/20 text-yellow-400' :
                        'bg-blue-500/20 text-blue-400'
                      }`}>
                        {issue.severity}
                      </span>
                      <span className={`px-2 py-1 rounded text-xs font-medium ${
                        issue.status === 'resolved' ? 'bg-green-500/20 text-green-400' :
                        issue.status === 'in-progress' ? 'bg-blue-500/20 text-blue-400' :
                        'bg-gray-500/20 text-gray-400'
                      }`}>
                        {issue.status}
                      </span>
                    </div>
                    <span className="text-gray-400 text-xs">{format(new Date(issue.createdAt), 'MMM dd, HH:mm')}</span>
                  </div>
                  <h4 className="text-white font-medium mb-1">{issue.title}</h4>
                  <p className="text-gray-300 text-sm">{issue.description}</p>
                  {issue.assignedTo && (
                    <p className="text-gray-500 text-xs mt-2">
                      Assigned to: {issue.assignedTo}
                    </p>
                  )}
                </div>
              ))
            )}
          </motion.div>
        )}

        {activeTab === 'chat' && (
          <motion.div
            key="chat"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="flex flex-col h-[500px]"
          >
            {/* Chat Messages */}
            <div className="flex-1 overflow-y-auto space-y-3 mb-4 pr-2">
              {session.activities
                .filter((a: any) => a.type === 'chat')
                .map((activity: any) => (
                  <div
                    key={activity.id}
                    className={`flex gap-3 ${activity.userId === 'user-1' ? 'flex-row-reverse' : ''}`}
                  >
                    <div className="w-8 h-8 rounded-full bg-cyan-500/20 flex items-center justify-center flex-shrink-0">
                      <i className="ri-user-line text-cyan-400"></i>
                    </div>
                    <div className={`flex-1 ${activity.userId === 'user-1' ? 'text-right' : ''}`}>
                      <div className={`inline-block p-3 rounded-lg ${
                        activity.userId === 'user-1'
                          ? 'bg-cyan-500/20 text-white'
                          : 'bg-white/5 text-gray-300'
                      }`}>
                        <p className="text-sm">{activity.content}</p>
                        <p className="text-xs text-gray-500 mt-1">
                          {format(new Date(activity.timestamp), 'HH:mm')}
                        </p>
                      </div>
                    </div>
                  </div>
                ))}
              <div ref={chatEndRef} />
            </div>

            {/* Chat Input */}
            <div className="flex gap-2 pt-4 border-t border-white/10">
              <input
                type="text"
                value={chatMessage}
                onChange={(e) => onChatMessageChange(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && onSendMessage()}
                placeholder="Type a message..."
                className="flex-1 px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500/50"
              />
              <button
                onClick={onSendMessage}
                disabled={!chatMessage.trim()}
                className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white transition-colors"
              >
                <i className="ri-send-plane-line"></i>
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

/**
 * BIM Digital Twin Tab Component
 * 
 * Full digital twin integration with real-time sync, predictive simulations, and performance optimization
 */

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion } from 'framer-motion'
import { format } from 'date-fns'
import type { BIMDigitalTwinLink } from '@/types/bim-marketplace'
import { useNotifications } from '@/lib/utils/notifications'
import Modal from '@/components/Modal'
import { getDigitalTwinService } from '@/lib/services/facility/digitalTwin/digitalTwinService'
import { WebSocketService } from '@/lib/services/realtime/websocketService'

interface DigitalTwinTabProps {
  modelId?: string
  onTwinLink?: (twinId: string) => void
}

export default function DigitalTwinTab({ modelId, onTwinLink }: DigitalTwinTabProps) {
  const [twinLinks, setTwinLinks] = useState<BIMDigitalTwinLink[]>([])
  const [selectedTwin, setSelectedTwin] = useState<BIMDigitalTwinLink | null>(null)
  const [loading, setLoading] = useState(true)
  const [showLinkModal, setShowLinkModal] = useState(false)
  const [showTwinModal, setShowTwinModal] = useState(false)
  const [isRealtimeConnected, setIsRealtimeConnected] = useState(false)
  const notifications = useNotifications()
  const digitalTwinService = getDigitalTwinService()
  const wsRef = useRef<WebSocketService | null>(null)

  useEffect(() => {
    if (modelId) {
      loadTwinLinks()
    }
  }, [modelId])

  // WebSocket connection for real-time sync status
  useEffect(() => {
    if (typeof window === 'undefined') return

    const ws = new WebSocketService()
    wsRef.current = ws

    ws.connect()
      .then(() => {
        setIsRealtimeConnected(true)
        
        // Subscribe to digital twin sync updates
        ws.on('notification', (event) => {
          if (event.data.type === 'digital-twin-sync') {
            const { twinId, syncStatus, lastSyncAt } = event.data
            
            setTwinLinks(prev => prev.map(link => 
              link.twinId === twinId 
                ? { 
                    ...link, 
                    syncStatus, 
                    lastSyncAt: new Date(lastSyncAt) 
                  }
                : link
            ))
            
            if (selectedTwin?.twinId === twinId) {
              setSelectedTwin(prev => prev ? {
                ...prev,
                syncStatus,
                lastSyncAt: new Date(lastSyncAt)
              } : null)
            }
          }
        })
      })
      .catch((error) => {
        console.warn('WebSocket connection failed:', error)
        setIsRealtimeConnected(false)
      })

    return () => {
      ws.disconnect()
      setIsRealtimeConnected(false)
    }
  }, [selectedTwin?.twinId])

  const loadTwinLinks = async () => {
    setLoading(true)
    try {
      // In real app, fetch from Digital Twin service
      // For now, use mock data
      const mockLinks: BIMDigitalTwinLink[] = []
      setTwinLinks(mockLinks)
    } catch (error) {
      console.error('Error loading twin links:', error)
      notifications.error('Error', 'Failed to load digital twin links')
    } finally {
      setLoading(false)
    }
  }

  const handleLinkTwin = async (twinData: any) => {
    try {
      if (!modelId) {
        notifications.error('Model Required', 'Please select a BIM model first')
        return
      }

      // Create or link digital twin using DigitalTwinService
      try {
        const twin = await digitalTwinService.createDigitalTwin(modelId, {
          name: twinData.twinName,
          dataSources: (twinData.dataSources || []).map((ds: string) => ({
            type: 'iot' as const,
            sourceId: ds,
          })),
        })

        // Create link record
        const newLink: BIMDigitalTwinLink = {
          id: `link-${Date.now()}`,
          modelId,
          twinId: twin.id,
          twinName: twinData.twinName,
          twinType: twinData.twinType,
          syncStatus: 'synced',
          syncMode: twinData.syncMode,
          syncInterval: twinData.syncInterval,
          lastSyncAt: new Date(),
          dataSources: twinData.dataSources || [],
          metadata: twinData.metadata || {},
          tenantId: 'tenant-1',
          createdAt: new Date(),
          updatedAt: new Date(),
        }

        setTwinLinks(prev => [...prev, newLink])
        notifications.success('Twin Linked', 'BIM model successfully linked to digital twin')
        setShowLinkModal(false)
        onTwinLink?.(twin.id)
      } catch (serviceError) {
        // If service fails, create mock link for demo
        console.warn('DigitalTwinService not available, creating mock link:', serviceError)
        const newLink: BIMDigitalTwinLink = {
          id: `link-${Date.now()}`,
          modelId: modelId!,
          twinId: twinData.twinId || `twin-${Date.now()}`,
          twinName: twinData.twinName,
          twinType: twinData.twinType,
          syncStatus: 'synced',
          syncMode: twinData.syncMode,
          syncInterval: twinData.syncInterval,
          lastSyncAt: new Date(),
          dataSources: twinData.dataSources || [],
          metadata: twinData.metadata || {},
          tenantId: 'tenant-1',
          createdAt: new Date(),
          updatedAt: new Date(),
        }
        setTwinLinks(prev => [...prev, newLink])
        notifications.success('Twin Linked', 'BIM model successfully linked to digital twin')
        setShowLinkModal(false)
        onTwinLink?.(newLink.twinId)
      }
    } catch (error) {
      console.error('Error linking twin:', error)
      notifications.error('Error', 'Failed to link digital twin')
    }
  }

  const handleSync = async (twinId: string) => {
    try {
      // In real app, trigger sync via Digital Twin service
      notifications.success('Sync Started', 'Synchronizing BIM model with digital twin...')
    } catch (error) {
      notifications.error('Error', 'Failed to sync digital twin')
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
        <p className="text-gray-400 text-sm">Loading digital twins...</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Digital Twin Integration</h2>
          <div className="flex items-center gap-2">
            <p className="text-gray-400 text-sm">Connect BIM models to digital twins for real-time monitoring and simulation</p>
            {isRealtimeConnected && (
              <span className="px-2 py-1 bg-green-500/20 text-green-400 rounded text-xs flex items-center gap-1">
                <i className="ri-wifi-line"></i>
                Synced
              </span>
            )}
          </div>
        </div>
        <button
          onClick={() => setShowLinkModal(true)}
          disabled={!modelId}
          className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white text-sm font-medium transition-colors flex items-center gap-2"
        >
          <i className="ri-link-line"></i>
          Link Digital Twin
        </button>
      </div>

      {/* Features Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {[
          {
            id: 'real-time-sync',
            label: 'Real-Time Sync',
            icon: 'ri-refresh-line',
            description: 'Synchronize BIM model with live building data',
            color: 'cyan',
          },
          {
            id: 'predictive-simulation',
            label: 'Predictive Simulation',
            icon: 'ri-cpu-line',
            description: 'Run what-if scenarios and predictive analytics',
            color: 'purple',
          },
          {
            id: 'performance-optimization',
            label: 'Performance Optimization',
            icon: 'ri-speed-line',
            description: 'AI-powered recommendations for building performance',
            color: 'green',
          },
          {
            id: 'iot-integration',
            label: 'IoT Integration',
            icon: 'ri-sensor-line',
            description: 'Connect with IoT sensors and devices',
            color: 'blue',
          },
          {
            id: 'energy-analysis',
            label: 'Energy Analysis',
            icon: 'ri-flashlight-line',
            description: 'Monitor and optimize energy consumption',
            color: 'yellow',
          },
          {
            id: 'maintenance-prediction',
            label: 'Maintenance Prediction',
            icon: 'ri-tools-line',
            description: 'Predict maintenance needs and schedule',
            color: 'orange',
          },
        ].map((feature) => (
          <motion.div
            key={feature.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            whileHover={{ y: -4 }}
            className={`bg-white/5 border border-white/10 rounded-xl p-6 hover:border-${feature.color}-500/30 transition-all`}
          >
            <div className={`w-12 h-12 rounded-lg bg-${feature.color}-500/20 flex items-center justify-center mb-4`}>
              <i className={`${feature.icon} text-${feature.color}-400 text-2xl`}></i>
            </div>
            <h3 className="text-white font-semibold text-lg mb-2">{feature.label}</h3>
            <p className="text-gray-400 text-sm">{feature.description}</p>
          </motion.div>
        ))}
      </div>

      {/* Linked Twins */}
      {twinLinks.length > 0 && (
        <div>
          <h3 className="text-white font-semibold text-lg mb-4">Linked Digital Twins</h3>
          <div className="space-y-3">
            {twinLinks.map((link) => (
              <div
                key={link.id}
                className="bg-white/5 border border-white/10 rounded-lg p-4 hover:border-cyan-500/30 transition-all cursor-pointer"
                onClick={() => {
                  setSelectedTwin(link)
                  setShowTwinModal(true)
                }}
              >
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <h4 className="text-white font-medium">{link.twinName}</h4>
                    <p className="text-gray-400 text-sm">{link.twinType}</p>
                  </div>
                  <span className={`px-2 py-1 rounded text-xs font-medium ${
                    link.syncStatus === 'synced' ? 'bg-green-500/20 text-green-400' :
                    link.syncStatus === 'syncing' ? 'bg-blue-500/20 text-blue-400' :
                    'bg-gray-500/20 text-gray-400'
                  }`}>
                    {link.syncStatus}
                  </span>
                </div>
                <div className="flex items-center gap-4 text-sm text-gray-400">
                  <div className="flex items-center gap-2">
                    <i className="ri-time-line"></i>
                    <span>Last sync: {format(new Date(link.lastSyncAt), 'MMM dd, HH:mm')}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <i className="ri-database-line"></i>
                    <span>{link.dataSources.length} data sources</span>
                  </div>
                </div>
                <div className="flex gap-2 mt-3">
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      handleSync(link.twinId)
                    }}
                    className="px-3 py-1 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white text-sm transition-colors"
                  >
                    <i className="ri-refresh-line mr-2"></i>
                    Sync Now
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      setSelectedTwin(link)
                      setShowTwinModal(true)
                    }}
                    className="px-3 py-1 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white text-sm transition-colors"
                  >
                    <i className="ri-eye-line mr-2"></i>
                    View
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {twinLinks.length === 0 && (
        <div className="text-center py-12 bg-white/5 border border-white/10 rounded-lg">
          <i className="ri-cpu-line text-4xl text-gray-500 mb-4"></i>
          <p className="text-gray-400 mb-4">No digital twins linked</p>
          <button
            onClick={() => setShowLinkModal(true)}
            disabled={!modelId}
            className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white text-sm font-medium transition-colors"
          >
            Link Your First Digital Twin
          </button>
        </div>
      )}

      {/* Link Twin Modal */}
      {showLinkModal && (
        <Modal
          isOpen={showLinkModal}
          onClose={() => setShowLinkModal(false)}
          title="Link Digital Twin"
          size="lg"
        >
          <LinkTwinForm
            modelId={modelId}
            onSubmit={handleLinkTwin}
            onCancel={() => setShowLinkModal(false)}
          />
        </Modal>
      )}

      {/* Twin Detail Modal */}
      {showTwinModal && selectedTwin && (
        <Modal
          isOpen={showTwinModal}
          onClose={() => setShowTwinModal(false)}
          title={selectedTwin.twinName}
          size="xl"
        >
          <TwinDetailView twin={selectedTwin} onSync={() => handleSync(selectedTwin.twinId)} />
        </Modal>
      )}
    </div>
  )
}

// Link Twin Form Component
function LinkTwinForm({ modelId, onSubmit, onCancel }: any) {
  const [formData, setFormData] = useState({
    twinId: '',
    twinName: '',
    twinType: 'building' as 'building' | 'facility' | 'system' | 'component',
    syncMode: 'real-time' as 'real-time' | 'scheduled' | 'manual',
    syncInterval: 60,
    dataSources: [] as string[],
    metadata: {},
  })

  return (
    <div className="space-y-6">
      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">
          Digital Twin ID <span className="text-red-400">*</span>
        </label>
        <input
          type="text"
          value={formData.twinId}
          onChange={(e) => setFormData(prev => ({ ...prev, twinId: e.target.value }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500/50"
          placeholder="Enter digital twin ID"
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">
          Twin Name <span className="text-red-400">*</span>
        </label>
        <input
          type="text"
          value={formData.twinName}
          onChange={(e) => setFormData(prev => ({ ...prev, twinName: e.target.value }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500/50"
          placeholder="Enter twin name"
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">Twin Type</label>
        <select
          value={formData.twinType}
          onChange={(e) => setFormData(prev => ({ ...prev, twinType: e.target.value as any }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500/50"
        >
          <option value="building">Building</option>
          <option value="facility">Facility</option>
          <option value="system">System</option>
          <option value="component">Component</option>
        </select>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-300 mb-2">Sync Mode</label>
        <select
          value={formData.syncMode}
          onChange={(e) => setFormData(prev => ({ ...prev, syncMode: e.target.value as any }))}
          className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500/50"
        >
          <option value="real-time">Real-Time</option>
          <option value="scheduled">Scheduled</option>
          <option value="manual">Manual</option>
        </select>
      </div>

      {formData.syncMode === 'scheduled' && (
        <div>
          <label className="block text-sm font-medium text-gray-300 mb-2">Sync Interval (seconds)</label>
          <input
            type="number"
            value={formData.syncInterval}
            onChange={(e) => setFormData(prev => ({ ...prev, syncInterval: parseInt(e.target.value) }))}
            className="w-full px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500/50"
            min="10"
          />
        </div>
      )}

      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button
          onClick={() => onSubmit({ ...formData, modelId })}
          disabled={!formData.twinId.trim() || !formData.twinName.trim()}
          className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-medium transition-colors"
        >
          Link Twin
        </button>
        <button
          onClick={onCancel}
          className="flex-1 px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors"
        >
          Cancel
        </button>
      </div>
    </div>
  )
}

// Twin Detail View Component
function TwinDetailView({ twin, onSync }: any) {
  return (
    <div className="space-y-6">
      {/* Twin Info */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-sm text-gray-400">Twin Type</label>
          <p className="text-white capitalize">{twin.twinType}</p>
        </div>
        <div>
          <label className="text-sm text-gray-400">Sync Status</label>
          <p className="text-white capitalize">{twin.syncStatus}</p>
        </div>
        <div>
          <label className="text-sm text-gray-400">Last Sync</label>
          <p className="text-white">{format(new Date(twin.lastSyncAt), 'MMM dd, yyyy HH:mm:ss')}</p>
        </div>
        <div>
          <label className="text-sm text-gray-400">Data Sources</label>
          <p className="text-white">{twin.dataSources.length}</p>
        </div>
      </div>

      {/* Data Sources */}
      {twin.dataSources.length > 0 && (
        <div>
          <h4 className="text-white font-medium mb-3">Data Sources</h4>
          <div className="space-y-2">
            {twin.dataSources.map((source: string, idx: number) => (
              <div key={idx} className="p-3 bg-white/5 rounded-lg border border-white/10">
                <div className="flex items-center gap-2">
                  <i className="ri-database-line text-cyan-400"></i>
                  <span className="text-white text-sm">{source}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Sync Settings */}
      <div>
        <h4 className="text-white font-medium mb-3">Sync Settings</h4>
        <div className="bg-white/5 rounded-lg p-4 border border-white/10 space-y-2 text-sm">
          <div className="flex items-center justify-between">
            <span className="text-gray-400">Sync Mode</span>
            <span className="text-white capitalize">{twin.syncMode}</span>
          </div>
          {twin.syncInterval && (
            <div className="flex items-center justify-between">
              <span className="text-gray-400">Sync Interval</span>
              <span className="text-white">{twin.syncInterval} seconds</span>
            </div>
          )}
        </div>
      </div>

      {/* Actions */}
      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button
          onClick={onSync}
          className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white font-medium transition-colors"
        >
          <i className="ri-refresh-line mr-2"></i>
          Sync Now
        </button>
        <button className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors">
          <i className="ri-settings-3-line mr-2"></i>
          Settings
        </button>
      </div>
    </div>
  )
}

/**
 * BIM Marketplace Listing Detail Modal
 * 
 * Comprehensive listing detail view with all information, reviews, and booking
 */

'use client'

import { useState } from 'react'
import { motion } from 'framer-motion'
import { format } from 'date-fns'
import type { BIMMarketplaceListing } from '@/types/bim-marketplace'
import { useNotifications } from '@/lib/utils/notifications'
import Modal from '@/components/Modal'

interface MarketplaceListingModalProps {
  listing: BIMMarketplaceListing
  isOpen: boolean
  onClose: () => void
  onBook?: (listingId: string) => void
  onFavorite?: (listingId: string) => void
}

export default function MarketplaceListingModal({
  listing,
  isOpen,
  onClose,
  onBook,
  onFavorite,
}: MarketplaceListingModalProps) {
  const [activeTab, setActiveTab] = useState<'overview' | 'details' | 'reviews' | 'provider'>('overview')
  const [isFavorite, setIsFavorite] = useState(false)
  const [showPaymentModal, setShowPaymentModal] = useState(false)
  const [paymentMethod, setPaymentMethod] = useState<'mada' | 'visa' | 'mastercard' | 'apple_pay' | 'google_pay'>('mada')
  const [processingPayment, setProcessingPayment] = useState(false)
  const [paymentIntent, setPaymentIntent] = useState<any>(null)
  const notifications = useNotifications()

  const formatPrice = (pricing: BIMMarketplaceListing['pricing']) => {
    if (pricing.model === 'free') return 'Free'
    if (pricing.model === 'one-time' && pricing.amount) {
      return `${pricing.currency || 'USD'} ${pricing.amount.toFixed(2)}`
    }
    if (pricing.model === 'subscription' && pricing.amount) {
      return `${pricing.currency || 'USD'} ${pricing.amount.toFixed(2)}/${pricing.subscriptionPeriod || 'month'}`
    }
    if (pricing.model === 'usage-based' && pricing.usagePrice) {
      return `${pricing.currency || 'USD'} ${pricing.usagePrice.toFixed(2)}/${pricing.usageUnit || 'unit'}`
    }
    if (pricing.customQuote) return 'Custom Quote'
    return 'Price on request'
  }

  const handleBook = async () => {
    try {
      const response = await fetch('/api/bim/marketplace/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          listingId: listing.id,
          userId: 'user-1',
          userName: 'Current User',
          booking: {
            status: 'pending',
            startDate: new Date(),
            metadata: {},
          },
        }),
      })

      const result = await response.json()

      if (result.success) {
        notifications.success('Booking Created', 'Your booking request has been submitted')
        onBook?.(listing.id)
        if (result.paymentIntent) {
          notifications.info('Payment Required', 'Please complete payment to confirm booking')
        }
      } else {
        notifications.error('Booking Failed', result.error || 'Could not create booking')
      }
    } catch (error) {
      notifications.error('Error', 'Failed to create booking')
    }
  }

  const handleFavorite = () => {
    setIsFavorite(!isFavorite)
    onFavorite?.(listing.id)
    notifications.success(isFavorite ? 'Removed from Favorites' : 'Added to Favorites', '')
  }

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={listing.title}
      size="xl"
    >
      <div className="space-y-6">
        {/* Images Gallery */}
        {listing.images && listing.images.length > 0 && (
          <div className="grid grid-cols-2 gap-2">
            {listing.images.slice(0, 4).map((img, idx) => (
              <img
                key={idx}
                src={img}
                alt={`${listing.title} - ${idx + 1}`}
                className="w-full h-32 object-cover rounded-lg"
              />
            ))}
          </div>
        )}

        {/* Tabs */}
        <div className="flex gap-2 border-b border-white/10">
          {[
            { id: 'overview', label: 'Overview', icon: 'ri-information-line' },
            { id: 'details', label: 'Details', icon: 'ri-file-list-line' },
            { id: 'reviews', label: 'Reviews', icon: 'ri-star-line' },
            { id: 'provider', label: 'Provider', icon: 'ri-user-line' },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as any)}
              className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 ${
                activeTab === tab.id
                  ? 'border-cyan-500 text-cyan-400'
                  : 'border-transparent text-gray-400 hover:text-white'
              }`}
            >
              <i className={`${tab.icon} mr-2`}></i>
              {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        {activeTab === 'overview' && (
          <div className="space-y-4">
            <div>
              <h4 className="text-white font-medium mb-2">Description</h4>
              <p className="text-gray-300 text-sm">{listing.description}</p>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-gray-400">Category</label>
                <p className="text-white capitalize">{listing.category}</p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Type</label>
                <p className="text-white capitalize">{listing.type}</p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Rating</label>
                <div className="flex items-center gap-2">
                  <div className="flex items-center gap-1 text-yellow-400">
                    <i className="ri-star-fill"></i>
                    <span className="text-white">{listing.averageRating.toFixed(1)}</span>
                  </div>
                  <span className="text-gray-500 text-sm">({listing.reviewCount} reviews)</span>
                </div>
              </div>
              <div>
                <label className="text-sm text-gray-400">Price</label>
                <p className="text-white font-semibold text-lg">{formatPrice(listing.pricing)}</p>
              </div>
            </div>

            {/* Tags */}
            {listing.tags.length > 0 && (
              <div>
                <label className="text-sm text-gray-400 mb-2 block">Tags</label>
                <div className="flex flex-wrap gap-2">
                  {listing.tags.map((tag) => (
                    <span
                      key={tag}
                      className="px-3 py-1 bg-white/5 text-gray-300 rounded-lg text-sm"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'details' && (
          <div className="space-y-4">
            {/* Model-specific details */}
            {listing.type === 'model' && listing.modelData && (
              <div className="bg-white/5 rounded-lg p-4 border border-white/10">
                <h4 className="text-white font-medium mb-4">Model Details</h4>
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <label className="text-gray-400">Format</label>
                    <p className="text-white uppercase">{listing.modelData.fileFormat}</p>
                  </div>
                  <div>
                    <label className="text-gray-400">LOD</label>
                    <p className="text-white">{listing.modelData.lod}</p>
                  </div>
                  <div>
                    <label className="text-gray-400">Elements</label>
                    <p className="text-white">{listing.modelData.elements.toLocaleString()}</p>
                  </div>
                  <div>
                    <label className="text-gray-400">License</label>
                    <p className="text-white capitalize">{listing.modelData.license}</p>
                  </div>
                  {listing.modelData.area && (
                    <div>
                      <label className="text-gray-400">Area</label>
                      <p className="text-white">{listing.modelData.area.toLocaleString()} m²</p>
                    </div>
                  )}
                  {listing.modelData.floors && (
                    <div>
                      <label className="text-gray-400">Floors</label>
                      <p className="text-white">{listing.modelData.floors}</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Service-specific details */}
            {listing.type === 'service' && listing.serviceData && (
              <div className="bg-white/5 rounded-lg p-4 border border-white/10">
                <h4 className="text-white font-medium mb-4">Service Details</h4>
                <div className="space-y-3 text-sm">
                  <div>
                    <label className="text-gray-400">Service Type</label>
                    <p className="text-white capitalize">{listing.serviceData.serviceType}</p>
                  </div>
                  {listing.serviceData.deliverables && listing.serviceData.deliverables.length > 0 && (
                    <div>
                      <label className="text-gray-400 mb-2 block">Deliverables</label>
                      <ul className="list-disc list-inside text-white space-y-1">
                        {listing.serviceData.deliverables.map((item, idx) => (
                          <li key={idx}>{item}</li>
                        ))}
                      </ul>
                    </div>
                  )}
                  {listing.serviceData.duration && (
                    <div>
                      <label className="text-gray-400">Duration</label>
                      <p className="text-white">{listing.serviceData.duration}</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Compatible Software */}
            {listing.compatibleSoftware.length > 0 && (
              <div>
                <label className="text-sm text-gray-400 mb-2 block">Compatible Software</label>
                <div className="flex flex-wrap gap-2">
                  {listing.compatibleSoftware.map((software) => (
                    <span
                      key={software}
                      className="px-3 py-1 bg-cyan-500/20 text-cyan-400 rounded-lg text-sm"
                    >
                      {software}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'reviews' && (
          <div className="space-y-4">
            {listing.reviews.length === 0 ? (
              <div className="text-center py-8 text-gray-400">
                <i className="ri-star-line text-4xl mb-2"></i>
                <p>No reviews yet</p>
              </div>
            ) : (
              listing.reviews.map((review) => (
                <div key={review.id} className="p-4 bg-white/5 rounded-lg border border-white/10">
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex items-center gap-3">
                      {review.userAvatar ? (
                        <img
                          src={review.userAvatar}
                          alt={review.userName}
                          className="w-10 h-10 rounded-full"
                        />
                      ) : (
                        <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center">
                          <i className="ri-user-line text-cyan-400"></i>
                        </div>
                      )}
                      <div>
                        <p className="text-white font-medium">{review.userName}</p>
                        {review.verified && (
                          <span className="text-xs text-green-400 flex items-center gap-1">
                            <i className="ri-verified-badge-fill"></i>
                            Verified
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      {[...Array(5)].map((_, i) => (
                        <i
                          key={i}
                          className={`ri-star-${i < review.rating ? 'fill' : 'line'} text-yellow-400`}
                        ></i>
                      ))}
                    </div>
                  </div>
                  {review.title && (
                    <h5 className="text-white font-medium mb-1">{review.title}</h5>
                  )}
                  <p className="text-gray-300 text-sm mb-2">{review.comment}</p>
                  <div className="flex items-center gap-4 text-xs text-gray-500">
                    <span>{format(new Date(review.createdAt), 'MMM dd, yyyy')}</span>
                    {review.helpful > 0 && (
                      <span className="flex items-center gap-1">
                        <i className="ri-thumb-up-line"></i>
                        {review.helpful} helpful
                      </span>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activeTab === 'provider' && (
          <div className="space-y-4">
            <div className="flex items-center gap-4 p-4 bg-white/5 rounded-lg border border-white/10">
              {listing.providerVerified && (
                <div className="w-16 h-16 rounded-full bg-green-500/20 flex items-center justify-center">
                  <i className="ri-verified-badge-fill text-green-400 text-2xl"></i>
                </div>
              )}
              <div className="flex-1">
                <h4 className="text-white font-semibold text-lg">{listing.providerName}</h4>
                {listing.providerRating && (
                  <div className="flex items-center gap-2 mt-1">
                    <div className="flex items-center gap-1 text-yellow-400">
                      <i className="ri-star-fill"></i>
                      <span className="text-white">{listing.providerRating.toFixed(1)}</span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* Actions */}
        <div className="flex gap-3 pt-4 border-t border-white/10">
          <button
            onClick={handleBook}
            className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white font-medium transition-colors"
          >
            <i className="ri-shopping-cart-line mr-2"></i>
            Book Now
          </button>
          <button
            onClick={handleFavorite}
            className={`px-4 py-2 rounded-lg font-medium transition-colors ${
              isFavorite
                ? 'bg-red-500/20 border border-red-500/50 text-red-400'
                : 'bg-white/5 border border-white/10 text-white hover:bg-white/10'
            }`}
          >
            <i className={`ri-heart-${isFavorite ? 'fill' : 'line'} mr-2`}></i>
            Favorite
          </button>
          <button className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors">
            <i className="ri-share-line mr-2"></i>
            Share
          </button>
        </div>
      </div>

      {/* Payment Modal */}
      {showPaymentModal && paymentIntent && (
        <Modal
          isOpen={showPaymentModal}
          onClose={() => setShowPaymentModal(false)}
          title="Complete Payment"
          size="md"
        >
          <PaymentFlow
            paymentIntent={paymentIntent}
            listing={listing}
            paymentMethod={paymentMethod}
            onPaymentMethodChange={setPaymentMethod}
            processing={processingPayment}
            onProcessPayment={async () => {
              setProcessingPayment(true)
              try {
                // In real app, process payment via payment service
                await new Promise(resolve => setTimeout(resolve, 2000)) // Simulate payment
                notifications.success('Payment Successful', 'Your booking has been confirmed')
                setShowPaymentModal(false)
                onBook?.(listing.id)
              } catch (error) {
                notifications.error('Payment Failed', 'Could not process payment')
              } finally {
                setProcessingPayment(false)
              }
            }}
            onCancel={() => setShowPaymentModal(false)}
          />
        </Modal>
      )}
    </Modal>
  )
}

// Payment Flow Component
function PaymentFlow({ 
  paymentIntent, 
  listing, 
  paymentMethod, 
  onPaymentMethodChange, 
  processing, 
  onProcessPayment, 
  onCancel 
}: any) {
  const formatPrice = (pricing: BIMMarketplaceListing['pricing']) => {
    if (pricing.model === 'free') return 'Free'
    if (pricing.model === 'one-time' && pricing.amount) {
      return `${pricing.currency || 'USD'} ${pricing.amount.toFixed(2)}`
    }
    if (pricing.model === 'subscription' && pricing.amount) {
      return `${pricing.currency || 'USD'} ${pricing.amount.toFixed(2)}/${pricing.subscriptionPeriod || 'month'}`
    }
    if (pricing.model === 'usage-based' && pricing.usagePrice) {
      return `${pricing.currency || 'USD'} ${pricing.usagePrice.toFixed(2)}/${pricing.usageUnit || 'unit'}`
    }
    return 'Price on request'
  }

  return (
    <div className="space-y-6">
      {/* Payment Summary */}
      <div className="bg-white/5 rounded-lg p-4 border border-white/10">
        <h4 className="text-white font-medium mb-3">Payment Summary</h4>
        <div className="space-y-2 text-sm">
          <div className="flex items-center justify-between">
            <span className="text-gray-400">Item</span>
            <span className="text-white">{listing.title}</span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-gray-400">Amount</span>
            <span className="text-white font-semibold text-lg">{formatPrice(listing.pricing)}</span>
          </div>
        </div>
      </div>

      {/* Payment Method Selection */}
      <div>
        <label className="block text-sm font-medium text-gray-300 mb-3">Payment Method</label>
        <div className="grid grid-cols-2 gap-3">
          {[
            { id: 'mada', label: 'Mada', icon: 'ri-bank-card-line' },
            { id: 'visa', label: 'Visa', icon: 'ri-visa-line' },
            { id: 'mastercard', label: 'Mastercard', icon: 'ri-bank-card-2-line' },
            { id: 'apple_pay', label: 'Apple Pay', icon: 'ri-apple-line' },
            { id: 'google_pay', label: 'Google Pay', icon: 'ri-google-line' },
          ].map((method) => (
            <label
              key={method.id}
              className={`flex items-center gap-2 px-4 py-3 rounded-lg border cursor-pointer transition-all ${
                paymentMethod === method.id
                  ? 'bg-cyan-500/20 border-cyan-500/50 text-cyan-300'
                  : 'bg-white/5 border-white/10 text-gray-300 hover:bg-white/10'
              }`}
            >
              <input
                type="radio"
                name="paymentMethod"
                value={method.id}
                checked={paymentMethod === method.id}
                onChange={(e) => onPaymentMethodChange(e.target.value as any)}
                className="text-cyan-500 focus:ring-cyan-500"
              />
              <i className={method.icon}></i>
              <span className="text-sm">{method.label}</span>
            </label>
          ))}
        </div>
      </div>

      {/* Payment Actions */}
      <div className="flex gap-3 pt-4 border-t border-white/10">
        <button
          onClick={onProcessPayment}
          disabled={processing}
          className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-medium transition-colors flex items-center justify-center gap-2"
        >
          {processing ? (
            <>
              <i className="ri-loader-4-line animate-spin"></i>
              <span>Processing...</span>
            </>
          ) : (
            <>
              <i className="ri-check-line"></i>
              <span>Pay {formatPrice(listing.pricing)}</span>
            </>
          )}
        </button>
        <button
          onClick={onCancel}
          disabled={processing}
          className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-medium transition-colors"
        >
          Cancel
        </button>
      </div>

      <p className="text-xs text-gray-500 text-center">
        <i className="ri-shield-check-line mr-1"></i>
        Your payment is secure and encrypted
      </p>
    </div>
  )
}

/**
 * BIM Marketplace Tab Component
 * 
 * Full marketplace UI with listings, search, filters, and booking
 * Integrated with payment service and real-time updates
 */

'use client'

import { useState, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { format } from 'date-fns'
import type { BIMMarketplaceListing, BIMMarketplaceSearchFilters } from '@/types/bim-marketplace'
import { useNotifications } from '@/lib/utils/notifications'
import Modal from '@/components/Modal'

interface MarketplaceTabProps {
  onListingSelect?: (listing: BIMMarketplaceListing) => void
  onBookListing?: (listingId: string) => void
}

export default function MarketplaceTab({ onListingSelect, onBookListing }: MarketplaceTabProps) {
  const [listings, setListings] = useState<BIMMarketplaceListing[]>([])
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string>('all')
  const [selectedType, setSelectedType] = useState<string>('all')
  const [sortBy, setSortBy] = useState<'relevance' | 'price' | 'rating' | 'newest'>('relevance')
  const [selectedListing, setSelectedListing] = useState<BIMMarketplaceListing | null>(null)
  const [showListingModal, setShowListingModal] = useState(false)
  const notifications = useNotifications()

  useEffect(() => {
    loadListings()
  }, [selectedCategory, selectedType, sortBy, searchQuery])

  const loadListings = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams()
      if (searchQuery) params.set('query', searchQuery)
      if (selectedCategory !== 'all') params.set('category', selectedCategory)
      if (selectedType !== 'all') params.set('type', selectedType)
      params.set('sortBy', sortBy)

      const response = await fetch(`/api/bim/marketplace/listings?${params.toString()}`)
      const result = await response.json()

      if (result.success) {
        setListings(result.data || [])
      } else {
        notifications.error('Failed to load listings', result.error || 'Unknown error')
      }
    } catch (error) {
      console.error('Error loading listings:', error)
      notifications.error('Error', 'Failed to load marketplace listings')
    } finally {
      setLoading(false)
    }
  }

  const filteredListings = useMemo(() => {
    return listings.filter(listing => {
      if (searchQuery) {
        const query = searchQuery.toLowerCase()
        return (
          listing.title.toLowerCase().includes(query) ||
          listing.description.toLowerCase().includes(query) ||
          listing.tags.some(tag => tag.toLowerCase().includes(query))
        )
      }
      return true
    })
  }, [listings, searchQuery])

  const categories = [
    { id: 'all', label: 'All Categories', icon: 'ri-apps-line' },
    { id: 'architectural', label: 'Architectural', icon: 'ri-building-line' },
    { id: 'structural', label: 'Structural', icon: 'ri-stack-line' },
    { id: 'mep', label: 'MEP', icon: 'ri-tools-line' },
    { id: 'sustainability', label: 'Sustainability', icon: 'ri-leaf-line' },
    { id: 'digital-twin', label: 'Digital Twin', icon: 'ri-cpu-line' },
  ]

  const types = [
    { id: 'all', label: 'All Types', icon: 'ri-apps-2-line' },
    { id: 'model', label: 'Models', icon: 'ri-cube-3d-line' },
    { id: 'service', label: 'Services', icon: 'ri-service-line' },
    { id: 'professional', label: 'Professionals', icon: 'ri-user-star-line' },
    { id: 'tool', label: 'Tools', icon: 'ri-tools-fill' },
    { id: 'template', label: 'Templates', icon: 'ri-file-copy-line' },
  ]

  const formatPrice = (pricing: BIMMarketplaceListing['pricing']) => {
    if (pricing.model === 'free') return 'Free'
    if (pricing.model === 'one-time' && pricing.amount) {
      return `${pricing.currency || 'USD'} ${pricing.amount.toFixed(2)}`
    }
    if (pricing.model === 'subscription' && pricing.amount) {
      return `${pricing.currency || 'USD'} ${pricing.amount.toFixed(2)}/${pricing.subscriptionPeriod || 'month'}`
    }
    if (pricing.model === 'usage-based' && pricing.usagePrice) {
      return `${pricing.currency || 'USD'} ${pricing.usagePrice.toFixed(2)}/${pricing.usageUnit || 'unit'}`
    }
    if (pricing.customQuote) return 'Custom Quote'
    return 'Price on request'
  }

  const handleListingClick = (listing: BIMMarketplaceListing) => {
    setSelectedListing(listing)
    setShowListingModal(true)
    onListingSelect?.(listing)
  }

  const handleBookListing = async (listing: BIMMarketplaceListing) => {
    try {
      const response = await fetch('/api/bim/marketplace/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          listingId: listing.id,
          userId: 'user-1', // In real app, get from auth
          userName: 'Current User',
          booking: {
            status: 'pending',
            startDate: new Date(),
            metadata: {},
          },
        }),
      })

      const result = await response.json()

      if (result.success) {
        notifications.success('Booking Created', 'Your booking request has been submitted')
        onBookListing?.(listing.id)
        if (result.paymentIntent) {
          // Redirect to payment if required
          notifications.info('Payment Required', 'Please complete payment to confirm booking')
        }
      } else {
        notifications.error('Booking Failed', result.error || 'Could not create booking')
      }
    } catch (error) {
      notifications.error('Error', 'Failed to create booking')
    }
  }

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 space-y-4">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
        <p className="text-gray-400 text-sm">Loading marketplace...</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Search and Filters */}
      <div className="bg-white/5 border border-white/10 rounded-lg p-4">
        <div className="flex flex-col lg:flex-row gap-4">
          {/* Search */}
          <div className="flex-1">
            <div className="relative">
              <i className="ri-search-line absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search models, services, professionals..."
                className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-cyan-500/50 transition-colors"
              />
            </div>
          </div>

          {/* Category Filter */}
          <div className="flex gap-2 overflow-x-auto">
            {categories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setSelectedCategory(cat.id)}
                className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${
                  selectedCategory === cat.id
                    ? 'bg-cyan-500 text-white'
                    : 'bg-white/5 text-gray-300 hover:bg-white/10'
                }`}
              >
                <i className={`${cat.icon} mr-2`}></i>
                {cat.label}
              </button>
            ))}
          </div>

          {/* Type Filter */}
          <select
            value={selectedType}
            onChange={(e) => setSelectedType(e.target.value)}
            className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-sm focus:outline-none focus:border-cyan-500/50"
          >
            {types.map((type) => (
              <option key={type.id} value={type.id}>
                {type.label}
              </option>
            ))}
          </select>

          {/* Sort */}
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as any)}
            className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-sm focus:outline-none focus:border-cyan-500/50"
          >
            <option value="relevance">Relevance</option>
            <option value="price">Price</option>
            <option value="rating">Rating</option>
            <option value="newest">Newest</option>
          </select>
        </div>
      </div>

      {/* Listings Grid */}
      {filteredListings.length === 0 ? (
        <div className="text-center py-12">
          <i className="ri-inbox-line text-4xl text-gray-500 mb-4"></i>
          <p className="text-gray-400">No listings found</p>
          {searchQuery && (
            <button
              onClick={() => setSearchQuery('')}
              className="mt-4 px-4 py-2 bg-cyan-500/20 text-cyan-400 rounded-lg text-sm hover:bg-cyan-500/30 transition-colors"
            >
              Clear search
            </button>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredListings.map((listing) => (
            <motion.div
              key={listing.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              whileHover={{ y: -4 }}
              className="bg-white/5 border border-white/10 rounded-xl overflow-hidden hover:border-cyan-500/30 transition-all cursor-pointer group"
              onClick={() => handleListingClick(listing)}
            >
              {/* Image/Preview */}
              <div className="relative h-48 bg-gradient-to-br from-gray-800 to-gray-900">
                {listing.images && listing.images.length > 0 ? (
                  <img
                    src={listing.images[0]}
                    alt={listing.title}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <i className="ri-cube-3d-line text-6xl text-gray-600"></i>
                  </div>
                )}
                {listing.featured && (
                  <div className="absolute top-2 right-2 px-2 py-1 bg-yellow-500/90 text-yellow-900 rounded text-xs font-bold">
                    <i className="ri-star-fill mr-1"></i>
                    Featured
                  </div>
                )}
                {listing.verified && (
                  <div className="absolute top-2 left-2 px-2 py-1 bg-green-500/90 text-white rounded text-xs font-medium">
                    <i className="ri-verified-badge-fill mr-1"></i>
                    Verified
                  </div>
                )}
              </div>

              {/* Content */}
              <div className="p-4">
                <div className="flex items-start justify-between mb-2">
                  <h3 className="text-white font-semibold text-lg group-hover:text-cyan-400 transition-colors line-clamp-2">
                    {listing.title}
                  </h3>
                  <span className="px-2 py-1 bg-cyan-500/20 text-cyan-400 rounded text-xs font-medium capitalize">
                    {listing.type}
                  </span>
                </div>

                <p className="text-gray-400 text-sm mb-3 line-clamp-2">{listing.description}</p>

                <div className="flex items-center gap-4 mb-3 text-sm">
                  <div className="flex items-center gap-1 text-yellow-400">
                    <i className="ri-star-fill"></i>
                    <span className="text-white">{listing.averageRating.toFixed(1)}</span>
                    <span className="text-gray-500">({listing.reviewCount})</span>
                  </div>
                  {listing.providerVerified && (
                    <div className="flex items-center gap-1 text-green-400">
                      <i className="ri-verified-badge-fill"></i>
                      <span className="text-gray-300">{listing.providerName}</span>
                    </div>
                  )}
                </div>

                <div className="flex items-center justify-between pt-3 border-t border-white/10">
                  <div className="text-lg font-bold text-cyan-400">
                    {formatPrice(listing.pricing)}
                  </div>
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      handleBookListing(listing)
                    }}
                    className="px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white text-sm font-medium transition-colors"
                  >
                    <i className="ri-shopping-cart-line mr-2"></i>
                    Book
                  </button>
                </div>

                {/* Tags */}
                {listing.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-3">
                    {listing.tags.slice(0, 3).map((tag) => (
                      <span
                        key={tag}
                        className="px-2 py-1 bg-white/5 text-gray-400 rounded text-xs"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                )}
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {/* Listing Detail Modal */}
      {showListingModal && selectedListing && (
        <Modal
          isOpen={showListingModal}
          onClose={() => setShowListingModal(false)}
          title={selectedListing.title}
          size="xl"
        >
          <div className="space-y-6">
            {/* Images */}
            {selectedListing.images && selectedListing.images.length > 0 && (
              <div className="grid grid-cols-2 gap-2">
                {selectedListing.images.slice(0, 4).map((img, idx) => (
                  <img
                    key={idx}
                    src={img}
                    alt={`${selectedListing.title} - ${idx + 1}`}
                    className="w-full h-32 object-cover rounded-lg"
                  />
                ))}
              </div>
            )}

            {/* Description */}
            <div>
              <h4 className="text-white font-medium mb-2">Description</h4>
              <p className="text-gray-300 text-sm">{selectedListing.description}</p>
            </div>

            {/* Details */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-gray-400">Category</label>
                <p className="text-white capitalize">{selectedListing.category}</p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Provider</label>
                <p className="text-white">{selectedListing.providerName}</p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Rating</label>
                <p className="text-white">
                  {selectedListing.averageRating.toFixed(1)} ({selectedListing.reviewCount} reviews)
                </p>
              </div>
              <div>
                <label className="text-sm text-gray-400">Price</label>
                <p className="text-white font-semibold">{formatPrice(selectedListing.pricing)}</p>
              </div>
            </div>

            {/* Model-specific data */}
            {selectedListing.type === 'model' && selectedListing.modelData && (
              <div className="bg-white/5 rounded-lg p-4">
                <h4 className="text-white font-medium mb-3">Model Details</h4>
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <label className="text-gray-400">Format</label>
                    <p className="text-white uppercase">{selectedListing.modelData.fileFormat}</p>
                  </div>
                  <div>
                    <label className="text-gray-400">LOD</label>
                    <p className="text-white">{selectedListing.modelData.lod}</p>
                  </div>
                  <div>
                    <label className="text-gray-400">Elements</label>
                    <p className="text-white">{selectedListing.modelData.elements.toLocaleString()}</p>
                  </div>
                  <div>
                    <label className="text-gray-400">License</label>
                    <p className="text-white capitalize">{selectedListing.modelData.license}</p>
                  </div>
                </div>
              </div>
            )}

            {/* Actions */}
            <div className="flex gap-3 pt-4 border-t border-white/10">
              <button
                onClick={() => handleBookListing(selectedListing)}
                className="flex-1 px-4 py-2 bg-cyan-500 hover:bg-cyan-600 rounded-lg text-white font-medium transition-colors"
              >
                <i className="ri-shopping-cart-line mr-2"></i>
                Book Now
              </button>
              <button className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors">
                <i className="ri-heart-line mr-2"></i>
                Favorite
              </button>
              <button className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 rounded-lg text-white font-medium transition-colors">
                <i className="ri-share-line mr-2"></i>
                Share
              </button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  )
}

/**
 * Intelligent Chemical Insights Component
 * Display AI-powered insights and recommendations
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Chemical } from '@/types/chemical'
import { ChemicalInsight, ChemicalRecommendation } from '@/lib/services/chemical/intelligentChemicalService'

interface IntelligentInsightsProps {
  chemical: Chemical
}

export default function IntelligentInsights({ chemical }: IntelligentInsightsProps) {
  const [insights, setInsights] = useState<ChemicalInsight[]>([])
  const [recommendations, setRecommendations] = useState<ChemicalRecommendation[]>([])
  const [loading, setLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'insights' | 'recommendations'>('insights')

  useEffect(() => {
    loadIntelligence()
  }, [chemical.id])

  const loadIntelligence = async () => {
    setLoading(true)
    try {
      // Load insights
      const insightsRes = await fetch('/api/chemical/intelligence/insights', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chemicalId: chemical.id })
      })
      const insightsData = await insightsRes.json()
      if (insightsData.success) {
        setInsights(insightsData.insights)
      }

      // Load recommendations
      const recRes = await fetch('/api/chemical/intelligence/recommendations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chemicalId: chemical.id })
      })
      const recData = await recRes.json()
      if (recData.success) {
        setRecommendations(recData.recommendations)
      }
    } catch (error) {
      console.error('Error loading intelligence:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="space-y-6">
      {/* Tabs */}
      <div className="flex items-center gap-2 border-b border-gray-700">
        <button
          onClick={() => setActiveTab('insights')}
          className={`px-4 py-3 flex items-center gap-2 font-medium transition ${
            activeTab === 'insights'
              ? 'text-cyan-400 border-b-2 border-cyan-400'
              : 'text-gray-400 hover:text-gray-300'
          }`}
        >
          <i className="ri-lightbulb-line"></i>
          AI Insights ({insights.length})
        </button>
        <button
          onClick={() => setActiveTab('recommendations')}
          className={`px-4 py-3 flex items-center gap-2 font-medium transition ${
            activeTab === 'recommendations'
              ? 'text-cyan-400 border-b-2 border-cyan-400'
              : 'text-gray-400 hover:text-gray-300'
          }`}
        >
          <i className="ri-star-line"></i>
          Recommendations ({recommendations.length})
        </button>
      </div>

      {/* Content */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-cyan-500"></div>
        </div>
      ) : (
        <AnimatePresence mode="wait">
          {activeTab === 'insights' && (
            <motion.div
              key="insights"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="space-y-4"
            >
              {insights.length === 0 ? (
                <div className="text-center py-12 text-gray-400">
                  <i className="ri-lightbulb-line text-4xl mb-4"></i>
                  <p>No insights available</p>
                </div>
              ) : (
                insights.map((insight) => (
                  <div
                    key={insight.id}
                    className={`p-4 rounded-lg border ${
                      insight.severity === 'critical' ? 'bg-red-900/20 border-red-500/30' :
                      insight.severity === 'high' ? 'bg-orange-900/20 border-orange-500/30' :
                      insight.severity === 'medium' ? 'bg-yellow-900/20 border-yellow-500/30' :
                      'bg-blue-900/20 border-blue-500/30'
                    }`}
                  >
                    <div className="flex items-start justify-between mb-2">
                      <div className="flex-1">
                        <h4 className="font-semibold mb-1">{insight.title}</h4>
                        <p className="text-sm text-gray-300">{insight.description}</p>
                      </div>
                      <span className={`px-2 py-1 rounded text-xs ${
                        insight.severity === 'critical' ? 'bg-red-900/30 text-red-400' :
                        insight.severity === 'high' ? 'bg-orange-900/30 text-orange-400' :
                        insight.severity === 'medium' ? 'bg-yellow-900/30 text-yellow-400' :
                        'bg-blue-900/30 text-blue-400'
                      }`}>
                        {insight.severity}
                      </span>
                    </div>
                    {insight.recommendations.length > 0 && (
                      <div className="mt-3 pt-3 border-t border-gray-700">
                        <p className="text-xs font-semibold text-gray-400 mb-2">Recommendations:</p>
                        <ul className="space-y-1">
                          {insight.recommendations.map((rec, idx) => (
                            <li key={idx} className="text-xs text-gray-300 flex items-start gap-2">
                              <i className="ri-arrow-right-line text-cyan-400 mt-0.5"></i>
                              {rec}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                    {insight.impact && (
                      <div className="mt-3 pt-3 border-t border-gray-700">
                        <div className="flex items-center gap-4 text-xs">
                          {insight.impact.estimatedSavings && (
                            <span className="text-green-400">
                              <i className="ri-money-dollar-circle-line mr-1"></i>
                              Est. Savings: ${insight.impact.estimatedSavings.toLocaleString()}
                            </span>
                          )}
                          {insight.impact.riskReduction && (
                            <span className="text-blue-400">
                              <i className="ri-shield-line mr-1"></i>
                              Risk Reduction: {insight.impact.riskReduction}%
                            </span>
                          )}
                          {insight.impact.complianceImprovement && (
                            <span className="text-purple-400">
                              <i className="ri-checkbox-circle-line mr-1"></i>
                              Compliance: +{insight.impact.complianceImprovement}%
                            </span>
                          )}
                        </div>
                      </div>
                    )}
                    <div className="mt-2 text-xs text-gray-500">
                      Confidence: {insight.confidence}%
                    </div>
                  </div>
                ))
              )}
            </motion.div>
          )}

          {activeTab === 'recommendations' && (
            <motion.div
              key="recommendations"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="space-y-4"
            >
              {recommendations.length === 0 ? (
                <div className="text-center py-12 text-gray-400">
                  <i className="ri-star-line text-4xl mb-4"></i>
                  <p>No recommendations available</p>
                </div>
              ) : (
                recommendations.map((rec) => (
                  <div
                    key={rec.id}
                    className={`p-4 rounded-lg border ${
                      rec.priority === 'critical' ? 'bg-red-900/20 border-red-500/30' :
                      rec.priority === 'high' ? 'bg-orange-900/20 border-orange-500/30' :
                      rec.priority === 'medium' ? 'bg-yellow-900/20 border-yellow-500/30' :
                      'bg-blue-900/20 border-blue-500/30'
                    }`}
                  >
                    <div className="flex items-start justify-between mb-2">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <h4 className="font-semibold">{rec.title}</h4>
                          <span className={`px-2 py-0.5 rounded text-xs ${
                            rec.type === 'substitution' ? 'bg-green-900/30 text-green-400' :
                            rec.type === 'storage' ? 'bg-blue-900/30 text-blue-400' :
                            rec.type === 'compliance' ? 'bg-purple-900/30 text-purple-400' :
                            'bg-gray-700 text-gray-400'
                          }`}>
                            {rec.type}
                          </span>
                        </div>
                        <p className="text-sm text-gray-300 mb-2">{rec.description}</p>
                        <p className="text-xs text-gray-400 italic">{rec.reasoning}</p>
                      </div>
                      <span className={`px-2 py-1 rounded text-xs ${
                        rec.priority === 'critical' ? 'bg-red-900/30 text-red-400' :
                        rec.priority === 'high' ? 'bg-orange-900/30 text-orange-400' :
                        rec.priority === 'medium' ? 'bg-yellow-900/30 text-yellow-400' :
                        'bg-blue-900/30 text-blue-400'
                      }`}>
                        {rec.priority}
                      </span>
                    </div>

                    {rec.benefits.length > 0 && (
                      <div className="mt-3 pt-3 border-t border-gray-700">
                        <p className="text-xs font-semibold text-green-400 mb-2">Benefits:</p>
                        <ul className="space-y-1">
                          {rec.benefits.map((benefit, idx) => (
                            <li key={idx} className="text-xs text-gray-300 flex items-start gap-2">
                              <i className="ri-checkbox-circle-line text-green-400 mt-0.5"></i>
                              {benefit}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {rec.implementationSteps.length > 0 && (
                      <div className="mt-3 pt-3 border-t border-gray-700">
                        <p className="text-xs font-semibold text-cyan-400 mb-2">Implementation Steps:</p>
                        <ol className="space-y-1">
                          {rec.implementationSteps.map((step, idx) => (
                            <li key={idx} className="text-xs text-gray-300 flex items-start gap-2">
                              <span className="flex-shrink-0 w-5 h-5 rounded-full bg-cyan-900/30 text-cyan-400 flex items-center justify-center text-xs">
                                {idx + 1}
                              </span>
                              {step}
                            </li>
                          ))}
                        </ol>
                      </div>
                    )}

                    {(rec.estimatedCost || rec.estimatedSavings) && (
                      <div className="mt-3 pt-3 border-t border-gray-700 flex items-center gap-4 text-xs">
                        {rec.estimatedCost && (
                          <span className="text-red-400">
                            <i className="ri-money-dollar-circle-line mr-1"></i>
                            Est. Cost: ${rec.estimatedCost.toLocaleString()}
                          </span>
                        )}
                        {rec.estimatedSavings && (
                          <span className="text-green-400">
                            <i className="ri-money-dollar-circle-line mr-1"></i>
                            Est. Savings: ${rec.estimatedSavings.toLocaleString()}
                          </span>
                        )}
                      </div>
                    )}

                    <div className="mt-2 text-xs text-gray-500">
                      Confidence: {rec.confidence}%
                    </div>
                  </div>
                ))
              )}
            </motion.div>
          )}
        </AnimatePresence>
      )}
    </div>
  )
}

'use client'

/**
 * Compliance Calendar Component
 * Visual calendar view of compliance deadlines, renewals, and events
 */

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  ComplianceCalendarEvent,
  CalendarView,
} from '@/lib/services/compliance/complianceCalendarService'
import { complianceCalendarService } from '@/lib/services/compliance/complianceCalendarService'
import { complianceService } from '@/lib/services/compliance/complianceService'

interface ComplianceCalendarProps {
  tenantId: string
}

export default function ComplianceCalendar({ tenantId }: ComplianceCalendarProps) {
  const [view, setView] = useState<'MONTH' | 'WEEK' | 'DAY' | 'LIST'>('MONTH')
  const [currentDate, setCurrentDate] = useState(new Date())
  const [calendarView, setCalendarView] = useState<CalendarView | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadCalendar()
  }, [tenantId, view, currentDate])

  const loadCalendar = async () => {
    try {
      setLoading(true)
      
      // Get compliance records
      const records = complianceService.getRecordsByTenant(tenantId)
      
      // Generate calendar events
      complianceCalendarService.generateCalendarEvents(records)
      
      // Get calendar view
      const startDate = new Date(currentDate)
      if (view === 'MONTH') {
        startDate.setDate(1)
      } else if (view === 'WEEK') {
        const day = startDate.getDay()
        startDate.setDate(startDate.getDate() - day)
      }
      
      const calView = complianceCalendarService.getCalendarView(view, startDate)
      setCalendarView(calView)
    } catch (error) {
      console.error('Error loading calendar:', error)
    } finally {
      setLoading(false)
    }
  }

  const getEventColor = (event: ComplianceCalendarEvent) => {
    if (event.status === 'OVERDUE') return 'bg-red-500/20 border-red-500/50 text-red-400'
    if (event.status === 'DUE_SOON') return 'bg-orange-500/20 border-orange-500/50 text-orange-400'
    if (event.priority === 'CRITICAL') return 'bg-purple-500/20 border-purple-500/50 text-purple-400'
    return 'bg-cyan-500/20 border-cyan-500/50 text-cyan-400'
  }

  const getEventIcon = (type: ComplianceCalendarEvent['type']) => {
    switch (type) {
      case 'DEADLINE': return 'ri-time-line'
      case 'RENEWAL': return 'ri-refresh-line'
      case 'INSPECTION': return 'ri-search-line'
      case 'AUDIT': return 'ri-file-search-line'
      case 'REVIEW': return 'ri-eye-line'
      case 'SUBMISSION': return 'ri-upload-line'
      default: return 'ri-calendar-line'
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
      </div>
    )
  }

  if (!calendarView) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-400">No calendar events available</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">Compliance Calendar</h2>
          <p className="text-gray-400 mt-1">Track deadlines, renewals, and compliance events</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => {
              const newDate = new Date(currentDate)
              if (view === 'MONTH') {
                newDate.setMonth(newDate.getMonth() - 1)
              } else if (view === 'WEEK') {
                newDate.setDate(newDate.getDate() - 7)
              } else {
                newDate.setDate(newDate.getDate() - 1)
              }
              setCurrentDate(newDate)
            }}
            className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-white transition-colors"
          >
            <i className="ri-arrow-left-line"></i>
          </button>
          <button
            onClick={() => setCurrentDate(new Date())}
            className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-white transition-colors"
          >
            Today
          </button>
          <button
            onClick={() => {
              const newDate = new Date(currentDate)
              if (view === 'MONTH') {
                newDate.setMonth(newDate.getMonth() + 1)
              } else if (view === 'WEEK') {
                newDate.setDate(newDate.getDate() + 7)
              } else {
                newDate.setDate(newDate.getDate() + 1)
              }
              setCurrentDate(newDate)
            }}
            className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-white transition-colors"
          >
            <i className="ri-arrow-right-line"></i>
          </button>
        </div>
      </div>

      {/* View Selector */}
      <div className="flex gap-2 border-b border-white/10">
        {(['MONTH', 'WEEK', 'DAY', 'LIST'] as const).map((v) => (
          <button
            key={v}
            onClick={() => setView(v)}
            className={`px-4 py-2 border-b-2 transition-colors ${
              view === v
                ? 'border-cyan-500 text-cyan-400'
                : 'border-transparent text-gray-400 hover:text-white'
            }`}
          >
            {v}
          </button>
        ))}
      </div>

      {/* Summary */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4">
          <p className="text-sm text-gray-400">Total Events</p>
          <p className="text-2xl font-bold text-white">{calendarView.summary.totalEvents}</p>
        </div>
        <div className="bg-blue-500/20 backdrop-blur-xl border border-blue-500/30 rounded-xl p-4">
          <p className="text-sm text-gray-400">Upcoming</p>
          <p className="text-2xl font-bold text-blue-400">{calendarView.summary.upcoming}</p>
        </div>
        <div className="bg-orange-500/20 backdrop-blur-xl border border-orange-500/30 rounded-xl p-4">
          <p className="text-sm text-gray-400">Due Soon</p>
          <p className="text-2xl font-bold text-orange-400">{calendarView.summary.dueSoon}</p>
        </div>
        <div className="bg-red-500/20 backdrop-blur-xl border border-red-500/30 rounded-xl p-4">
          <p className="text-sm text-gray-400">Overdue</p>
          <p className="text-2xl font-bold text-red-400">{calendarView.summary.overdue}</p>
        </div>
        <div className="bg-green-500/20 backdrop-blur-xl border border-green-500/30 rounded-xl p-4">
          <p className="text-sm text-gray-400">Completed</p>
          <p className="text-2xl font-bold text-green-400">{calendarView.summary.completed}</p>
        </div>
      </div>

      {/* Events List */}
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
        <h3 className="text-lg font-semibold text-white mb-4">Upcoming Events</h3>
        <div className="space-y-3">
          {calendarView.events.slice(0, 20).map((event) => (
            <motion.div
              key={event.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              className={`p-4 rounded-lg border ${getEventColor(event)}`}
            >
              <div className="flex items-start justify-between">
                <div className="flex items-start gap-3 flex-1">
                  <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${getEventColor(event)}`}>
                    <i className={`${getEventIcon(event.type)} text-xl`}></i>
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <h4 className="text-white font-medium">{event.title}</h4>
                      <span className={`px-2 py-0.5 rounded text-xs ${
                        event.priority === 'CRITICAL' ? 'bg-red-500/30 text-red-300' :
                        event.priority === 'HIGH' ? 'bg-orange-500/30 text-orange-300' :
                        'bg-blue-500/30 text-blue-300'
                      }`}>
                        {event.priority}
                      </span>
                    </div>
                    <p className="text-sm text-gray-300 mb-2">{event.description}</p>
                    <div className="flex items-center gap-4 text-xs text-gray-400">
                      <span>
                        <i className="ri-calendar-line mr-1"></i>
                        {new Date(event.dueDate).toLocaleDateString()}
                      </span>
                      <span>
                        <i className="ri-time-line mr-1"></i>
                        {new Date(event.dueDate).toLocaleTimeString()}
                      </span>
                      {event.status === 'OVERDUE' && (
                        <span className="text-red-400 font-medium">OVERDUE</span>
                      )}
                      {event.status === 'DUE_SOON' && (
                        <span className="text-orange-400 font-medium">DUE SOON</span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { complianceService } from '@/lib/services/compliance/complianceService'
import { authorityHierarchyService } from '@/lib/services/compliance/authorityHierarchyService'
import { RegulatoryAuthorityNode } from '@/types/compliance-hierarchy'
import { ComplianceRecord } from '@/types/compliance'

interface ComplianceMapProps {
  tenantId: string
}

interface MapNode {
  id: string
  name: string
  authority: string
  complianceScore: number
  status: 'COMPLIANT' | 'NON_COMPLIANT' | 'AT_RISK'
  x: number
  y: number
  children: string[]
  parent?: string
}

export default function ComplianceMap({ tenantId }: ComplianceMapProps) {
  const [nodes, setNodes] = useState<MapNode[]>([])
  const [selectedNode, setSelectedNode] = useState<MapNode | null>(null)
  const [viewMode, setViewMode] = useState<'hierarchy' | 'network' | 'heatmap'>('hierarchy')
  const [records, setRecords] = useState<ComplianceRecord[]>([])

  useEffect(() => {
    loadData()
  }, [tenantId])

  const loadData = async () => {
    try {
      const allRecords = complianceService.getRecordsByTenant(tenantId)
      setRecords(allRecords)

      const authorities = authorityHierarchyService.getAllNodes()
      const mapNodes: MapNode[] = []

      // Create nodes for each authority
      authorities.forEach((auth, index) => {
        const authRecords = allRecords.filter(r => r.authority === auth.name)
        const compliant = authRecords.filter(r => r.status === 'COMPLIANT').length
        const total = authRecords.length
        const score = total > 0 ? (compliant / total) * 100 : 100

        const children = authorityHierarchyService.getChildren(auth.id).map(c => c.id)
        const parents = authorityHierarchyService.getParents(auth.id).map(p => p.id)

        mapNodes.push({
          id: auth.id,
          name: auth.name,
          authority: auth.name,
          complianceScore: score,
          status: score >= 90 ? 'COMPLIANT' : score >= 70 ? 'AT_RISK' : 'NON_COMPLIANT',
          x: (index % 4) * 200 + 100,
          y: Math.floor(index / 4) * 150 + 100,
          children,
          parent: parents[0],
        })
      })

      setNodes(mapNodes)
    } catch (error) {
      console.error('Error loading compliance map:', error)
    }
  }

  const getNodeColor = (node: MapNode) => {
    if (node.status === 'COMPLIANT') return 'bg-green-500'
    if (node.status === 'AT_RISK') return 'bg-yellow-500'
    return 'bg-red-500'
  }

  const getNodeSize = (node: MapNode) => {
    const baseSize = 40
    const scoreMultiplier = node.complianceScore / 100
    return baseSize + (scoreMultiplier * 20)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">Compliance Map</h2>
          <p className="text-gray-400 mt-1">Visual representation of compliance across authorities</p>
        </div>
        <div className="flex gap-2">
          {[
            { id: 'hierarchy', label: 'Hierarchy', icon: 'ri-node-tree' },
            { id: 'network', label: 'Network', icon: 'ri-share-line' },
            { id: 'heatmap', label: 'Heatmap', icon: 'ri-fire-line' },
          ].map((mode) => (
            <button
              key={mode.id}
              onClick={() => setViewMode(mode.id as any)}
              className={`px-4 py-2 rounded-lg transition-colors ${
                viewMode === mode.id
                  ? 'bg-cyan-500/20 border border-cyan-500/30 text-cyan-400'
                  : 'bg-white/5 border border-white/10 text-gray-400 hover:text-white'
              }`}
            >
              <i className={`${mode.icon} mr-2`}></i>
              {mode.label}
            </button>
          ))}
        </div>
      </div>

      {/* Map Canvas */}
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6 min-h-[600px] relative overflow-hidden">
        <svg width="100%" height="600" className="absolute inset-0">
          {/* Draw connections */}
          {viewMode === 'hierarchy' || viewMode === 'network' ? (
            nodes.map((node) =>
              node.children.map((childId) => {
                const child = nodes.find(n => n.id === childId)
                if (!child) return null
                return (
                  <line
                    key={`${node.id}-${childId}`}
                    x1={node.x}
                    y1={node.y}
                    x2={child.x}
                    y2={child.y}
                    stroke="rgba(255, 255, 255, 0.2)"
                    strokeWidth="2"
                  />
                )
              })
            )
          ) : null}

          {/* Draw nodes */}
          {nodes.map((node) => {
            const size = getNodeSize(node)
            const color = getNodeColor(node)
            return (
              <g key={node.id}>
                <circle
                  cx={node.x}
                  cy={node.y}
                  r={size / 2}
                  fill={color}
                  className="cursor-pointer hover:opacity-80 transition-opacity"
                  onClick={() => setSelectedNode(node)}
                />
                <text
                  x={node.x}
                  y={node.y + size / 2 + 15}
                  textAnchor="middle"
                  fill="white"
                  fontSize="12"
                  className="pointer-events-none"
                >
                  {node.name}
                </text>
                <text
                  x={node.x}
                  y={node.y + size / 2 + 30}
                  textAnchor="middle"
                  fill="rgba(255, 255, 255, 0.7)"
                  fontSize="10"
                  className="pointer-events-none"
                >
                  {node.complianceScore.toFixed(0)}%
                </text>
              </g>
            )
          })}
        </svg>

        {/* Heatmap Overlay */}
        {viewMode === 'heatmap' && (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="grid grid-cols-4 gap-4">
              {nodes.map((node) => (
                <div
                  key={node.id}
                  className={`p-4 rounded-lg cursor-pointer transition-transform hover:scale-105 ${
                    node.status === 'COMPLIANT'
                      ? 'bg-green-500/30 border border-green-500/50'
                      : node.status === 'AT_RISK'
                      ? 'bg-yellow-500/30 border border-yellow-500/50'
                      : 'bg-red-500/30 border border-red-500/50'
                  }`}
                  onClick={() => setSelectedNode(node)}
                >
                  <p className="text-white font-semibold text-sm">{node.name}</p>
                  <p className="text-gray-300 text-xs mt-1">{node.complianceScore.toFixed(0)}%</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Node Details Panel */}
      {selectedNode && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6"
        >
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xl font-semibold text-white">{selectedNode.name}</h3>
            <button
              onClick={() => setSelectedNode(null)}
              className="text-gray-400 hover:text-white"
            >
              <i className="ri-close-line text-2xl"></i>
            </button>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
            <div>
              <p className="text-sm text-gray-400">Compliance Score</p>
              <p className="text-2xl font-bold text-white">{selectedNode.complianceScore.toFixed(1)}%</p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Status</p>
              <p
                className={`text-lg font-semibold ${
                  selectedNode.status === 'COMPLIANT'
                    ? 'text-green-400'
                    : selectedNode.status === 'AT_RISK'
                    ? 'text-yellow-400'
                    : 'text-red-400'
                }`}
              >
                {selectedNode.status}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Total Records</p>
              <p className="text-2xl font-bold text-white">
                {records.filter(r => r.authority === selectedNode.authority).length}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Compliant</p>
              <p className="text-2xl font-bold text-green-400">
                {records.filter(
                  r => r.authority === selectedNode.authority && r.status === 'COMPLIANT'
                ).length}
              </p>
            </div>
          </div>

          <div className="mt-4">
            <h4 className="text-sm font-medium text-gray-400 mb-2">Related Records</h4>
            <div className="space-y-2">
              {records
                .filter(r => r.authority === selectedNode.authority)
                .slice(0, 5)
                .map((record) => (
                  <div
                    key={record.id}
                    className="flex items-center justify-between p-2 bg-white/5 rounded-lg"
                  >
                    <p className="text-sm text-white">{record.requirement}</p>
                    <span
                      className={`px-2 py-1 rounded text-xs ${
                        record.status === 'COMPLIANT'
                          ? 'bg-green-500/20 text-green-400'
                          : record.status === 'AT_RISK'
                          ? 'bg-yellow-500/20 text-yellow-400'
                          : 'bg-red-500/20 text-red-400'
                      }`}
                    >
                      {record.status}
                    </span>
                  </div>
                ))}
            </div>
          </div>
        </motion.div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  ComplianceReport,
  ReportType,
  complianceReportingService,
} from '@/lib/services/compliance/complianceReportingService'
import { complianceService } from '@/lib/services/compliance/complianceService'
import { intelligentComplianceEngine } from '@/lib/services/compliance/intelligentComplianceEngine'
import { authorityHierarchyService } from '@/lib/services/compliance/authorityHierarchyService'

interface ComplianceReportsProps {
  tenantId: string
}

export default function ComplianceReports({ tenantId }: ComplianceReportsProps) {
  const [selectedReportType, setSelectedReportType] = useState<ReportType>('OVERALL_COMPLIANCE')
  const [report, setReport] = useState<ComplianceReport | null>(null)
  const [loading, setLoading] = useState(false)
  const [exportFormat, setExportFormat] = useState<'PDF' | 'EXCEL' | 'CSV' | 'JSON'>('PDF')

  useEffect(() => {
    generateReport()
  }, [selectedReportType, tenantId])

  const generateReport = async () => {
    try {
      setLoading(true)
      const records = complianceService.getRecordsByTenant(tenantId)
      const dashboard = await complianceService.generateDashboard(tenantId)
      
      let newReport: ComplianceReport

      switch (selectedReportType) {
        case 'OVERALL_COMPLIANCE':
          newReport = complianceReportingService.generateOverallComplianceReport(
            tenantId,
            records
          )
          break
        case 'EXECUTIVE_SUMMARY':
          const allAuthorities = authorityHierarchyService.getAllNodes()
          const regulations = allAuthorities.flatMap(auth =>
            authorityHierarchyService.getRegulationsByAuthority(auth.id)
          )
          const riskPrediction = intelligentComplianceEngine.predictComplianceRisk(records, regulations)
          const recommendations = intelligentComplianceEngine.generateIntelligentRecommendations(records, regulations)
          newReport = complianceReportingService.generateExecutiveSummary(
            tenantId,
            dashboard,
            riskPrediction,
            recommendations
          )
          break
        case 'VIOLATION_ANALYSIS':
          const violations = records.flatMap(r => r.violations)
          newReport = complianceReportingService.generateViolationAnalysisReport(tenantId, violations)
          break
        default:
          newReport = complianceReportingService.generateOverallComplianceReport(tenantId, records)
      }

      setReport(newReport)
    } catch (error) {
      console.error('Error generating report:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleExport = () => {
    if (!report) return
    const exported = complianceReportingService.exportReport(report, {
      format: exportFormat,
      includeCharts: true,
      includeDetails: true,
      includeRecommendations: true,
    })
    // In real implementation, this would download the file
    console.log('Export:', exported)
    alert(`Report exported as ${exportFormat}`)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
      </div>
    )
  }

  if (!report) {
    return (
      <div className="text-center py-12 text-gray-400">
        <p>No report data available</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">Compliance Reports</h2>
          <p className="text-gray-400 mt-1">Generate comprehensive compliance reports and analytics</p>
        </div>
        <div className="flex gap-2">
          <select
            value={exportFormat}
            onChange={(e) => setExportFormat(e.target.value as any)}
            className="px-4 py-2 bg-white/5 border border-white/10 rounded-lg text-white focus:outline-none focus:border-cyan-500"
          >
            <option value="PDF">PDF</option>
            <option value="EXCEL">Excel</option>
            <option value="CSV">CSV</option>
            <option value="JSON">JSON</option>
          </select>
          <button
            onClick={handleExport}
            className="px-6 py-2 bg-cyan-500 hover:bg-cyan-600 text-white rounded-lg transition-colors"
          >
            <i className="ri-download-line mr-2"></i>
            Export
          </button>
        </div>
      </div>

      {/* Report Type Selector */}
      <div className="flex gap-2 border-b border-white/10">
        {[
          { id: 'OVERALL_COMPLIANCE', label: 'Overall Compliance', icon: 'ri-dashboard-line' },
          { id: 'EXECUTIVE_SUMMARY', label: 'Executive Summary', icon: 'ri-file-chart-line' },
          { id: 'VIOLATION_ANALYSIS', label: 'Violation Analysis', icon: 'ri-alert-line' },
          { id: 'AUDIT_READINESS', label: 'Audit Readiness', icon: 'ri-file-search-line' },
        ].map((type) => (
          <button
            key={type.id}
            onClick={() => setSelectedReportType(type.id as ReportType)}
            className={`px-4 py-2 border-b-2 transition-colors ${
              selectedReportType === type.id
                ? 'border-cyan-500 text-cyan-400'
                : 'border-transparent text-gray-400 hover:text-white'
            }`}
          >
            <i className={`${type.icon} mr-2`}></i>
            {type.label}
          </button>
        ))}
      </div>

      {/* Report Content */}
      <div className="space-y-6">
        {/* Summary Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4">
            <p className="text-sm text-gray-400">Compliance Score</p>
            <p className="text-2xl font-bold text-white mt-1">
              {report.summary.overallComplianceScore.toFixed(1)}%
            </p>
          </div>
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4">
            <p className="text-sm text-gray-400">Total Requirements</p>
            <p className="text-2xl font-bold text-white mt-1">{report.summary.totalRequirements}</p>
          </div>
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4">
            <p className="text-sm text-gray-400">Violations</p>
            <p className="text-2xl font-bold text-red-400 mt-1">{report.summary.totalViolations}</p>
          </div>
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4">
            <p className="text-sm text-gray-400">Risk Level</p>
            <p className="text-2xl font-bold text-orange-400 mt-1">{report.summary.riskLevel}</p>
          </div>
        </div>

        {/* Detailed Metrics */}
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
          <h3 className="text-lg font-semibold text-white mb-4">Compliance Metrics</h3>
          <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
            <div>
              <p className="text-sm text-gray-400">Compliant</p>
              <p className="text-xl font-bold text-green-400">{report.summary.compliantCount}</p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Non-Compliant</p>
              <p className="text-xl font-bold text-red-400">{report.summary.nonCompliantCount}</p>
            </div>
            <div>
              <p className="text-sm text-gray-400">At Risk</p>
              <p className="text-xl font-bold text-yellow-400">{report.summary.atRiskCount}</p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Critical Violations</p>
              <p className="text-xl font-bold text-red-400">{report.summary.criticalViolations}</p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Open Violations</p>
              <p className="text-xl font-bold text-orange-400">{report.summary.openViolations}</p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Resolved</p>
              <p className="text-xl font-bold text-green-400">{report.summary.resolvedViolations}</p>
            </div>
          </div>
        </div>

        {/* Recommendations */}
        {report.recommendations && report.recommendations.length > 0 && (
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
            <h3 className="text-lg font-semibold text-white mb-4">Recommendations</h3>
            <ul className="space-y-2">
              {report.recommendations.map((rec, index) => (
                <li key={index} className="text-sm text-gray-300 flex items-start gap-2">
                  <i className="ri-arrow-right-s-line text-cyan-400 mt-1"></i>
                  {rec}
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Report Metadata */}
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4">
          <div className="flex items-center justify-between text-sm text-gray-400">
            <span>Generated: {new Date(report.generatedAt).toLocaleString()}</span>
            <span>Period: {new Date(report.period.startDate).toLocaleDateString()} - {new Date(report.period.endDate).toLocaleDateString()}</span>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { complianceService } from '@/lib/services/compliance/complianceService'
import {
  complianceScoringService,
  ComplianceScore,
} from '@/lib/services/compliance/complianceScoringService'

interface ComplianceScoringProps {
  tenantId: string
}

export default function ComplianceScoring({ tenantId }: ComplianceScoringProps) {
  const [score, setScore] = useState<ComplianceScore | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadScore()
  }, [tenantId])

  const loadScore = async () => {
    try {
      setLoading(true)
      const records = complianceService.getRecordsByTenant(tenantId)
      const calculatedScore = complianceScoringService.calculateComplianceScore(records)
      setScore(calculatedScore)
    } catch (error) {
      console.error('Error loading compliance score:', error)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
      </div>
    )
  }

  if (!score) {
    return (
      <div className="text-center py-12 text-gray-400">
        <p>No scoring data available</p>
      </div>
    )
  }

  const getScoreColor = (value: number) => {
    if (value >= 90) return 'text-green-400'
    if (value >= 70) return 'text-yellow-400'
    if (value >= 50) return 'text-orange-400'
    return 'text-red-400'
  }

  const getScoreBgColor = (value: number) => {
    if (value >= 90) return 'bg-green-500'
    if (value >= 70) return 'bg-yellow-500'
    if (value >= 50) return 'bg-orange-500'
    return 'bg-red-500'
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">Compliance Scoring</h2>
          <p className="text-gray-400 mt-1">Advanced scoring algorithms and analysis</p>
        </div>
        <button
          onClick={loadScore}
          className="px-4 py-2 bg-cyan-500/20 hover:bg-cyan-500/30 border border-cyan-500/30 rounded-lg text-cyan-400 transition-colors"
        >
          <i className="ri-refresh-line mr-2"></i>
          Recalculate
        </button>
      </div>

      {/* Overall Score */}
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h3 className="text-lg font-semibold text-gray-400 mb-2">Overall Compliance Score</h3>
            <div className="flex items-baseline gap-3">
              <span className={`text-5xl font-bold ${getScoreColor(score.overall)}`}>
                {score.overall.toFixed(1)}
              </span>
              <span className="text-2xl text-gray-400">/ 100</span>
            </div>
          </div>
          <div className="text-right">
            <p className="text-sm text-gray-400 mb-1">Risk Level</p>
            <span
              className={`px-4 py-2 rounded-lg font-semibold ${
                score.riskLevel === 'LOW'
                  ? 'bg-green-500/20 text-green-400'
                  : score.riskLevel === 'MEDIUM'
                  ? 'bg-yellow-500/20 text-yellow-400'
                  : score.riskLevel === 'HIGH'
                  ? 'bg-orange-500/20 text-orange-400'
                  : 'bg-red-500/20 text-red-400'
              }`}
            >
              {score.riskLevel}
            </span>
          </div>
        </div>

        {/* Score Progress Bar */}
        <div className="relative h-4 bg-white/5 rounded-full overflow-hidden">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${score.overall}%` }}
            transition={{ duration: 1, ease: 'easeOut' }}
            className={`h-full ${getScoreBgColor(score.overall)}`}
          />
        </div>

        {/* Confidence */}
        <div className="mt-4 flex items-center gap-2">
          <span className="text-sm text-gray-400">Confidence:</span>
          <div className="flex-1 h-2 bg-white/5 rounded-full overflow-hidden">
            <div
              className="h-full bg-cyan-500"
              style={{ width: `${score.confidence * 100}%` }}
            />
          </div>
          <span className="text-sm text-gray-400">{(score.confidence * 100).toFixed(0)}%</span>
        </div>
      </div>

      {/* Score Factors */}
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
        <h3 className="text-lg font-semibold text-white mb-4">Score Breakdown</h3>
        <div className="space-y-4">
          {score.factors.map((factor, index) => (
            <div key={index} className="space-y-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <span className="text-sm font-medium text-white">{factor.name}</span>
                  <span className="text-xs text-gray-400">({(factor.weight * 100).toFixed(0)}% weight)</span>
                  <span
                    className={`text-xs px-2 py-1 rounded ${
                      factor.impact === 'POSITIVE'
                        ? 'bg-green-500/20 text-green-400'
                        : factor.impact === 'NEGATIVE'
                        ? 'bg-red-500/20 text-red-400'
                        : 'bg-gray-500/20 text-gray-400'
                    }`}
                  >
                    {factor.impact}
                  </span>
                </div>
                <span className={`text-sm font-semibold ${getScoreColor(factor.score)}`}>
                  {factor.score.toFixed(1)}
                </span>
              </div>
              <div className="relative h-2 bg-white/5 rounded-full overflow-hidden">
                <div
                  className={`h-full ${getScoreBgColor(factor.score)}`}
                  style={{ width: `${factor.score}%` }}
                />
              </div>
              <p className="text-xs text-gray-400">{factor.description}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Scores by Authority */}
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
        <h3 className="text-lg font-semibold text-white mb-4">Scores by Authority</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {Object.entries(score.byAuthority).map(([authority, authScore]) => (
            <div
              key={authority}
              className="p-4 bg-white/5 rounded-lg border border-white/10"
            >
              <p className="text-sm text-gray-400 mb-2">{authority}</p>
              <div className="flex items-center gap-2">
                <div className="flex-1 h-2 bg-white/5 rounded-full overflow-hidden">
                  <div
                    className={`h-full ${getScoreBgColor(authScore)}`}
                    style={{ width: `${authScore}%` }}
                  />
                </div>
                <span className={`text-sm font-semibold ${getScoreColor(authScore)}`}>
                  {authScore.toFixed(1)}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Scores by Category */}
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
        <h3 className="text-lg font-semibold text-white mb-4">Scores by Category</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {Object.entries(score.byCategory).map(([category, catScore]) => (
            <div
              key={category}
              className="p-4 bg-white/5 rounded-lg border border-white/10"
            >
              <p className="text-sm text-gray-400 mb-2">{category}</p>
              <div className="flex items-center gap-2">
                <div className="flex-1 h-2 bg-white/5 rounded-full overflow-hidden">
                  <div
                    className={`h-full ${getScoreBgColor(catScore)}`}
                    style={{ width: `${catScore}%` }}
                  />
                </div>
                <span className={`text-sm font-semibold ${getScoreColor(catScore)}`}>
                  {catScore.toFixed(1)}
                </span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Trend */}
      {score.trend && (
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
          <h3 className="text-lg font-semibold text-white mb-4">Trend Analysis</h3>
          <div className="flex items-center gap-4">
            <div>
              <p className="text-sm text-gray-400">Current</p>
              <p className={`text-2xl font-bold ${getScoreColor(score.trend.current)}`}>
                {score.trend.current.toFixed(1)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Previous</p>
              <p className="text-2xl font-bold text-gray-400">
                {score.trend.previous.toFixed(1)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Change</p>
              <p
                className={`text-2xl font-bold ${
                  score.trend.change > 0
                    ? 'text-green-400'
                    : score.trend.change < 0
                    ? 'text-red-400'
                    : 'text-gray-400'
                }`}
              >
                {score.trend.change > 0 ? '+' : ''}
                {score.trend.change.toFixed(1)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-400">Direction</p>
              <span
                className={`px-3 py-1 rounded-lg text-sm font-semibold ${
                  score.trend.direction === 'IMPROVING'
                    ? 'bg-green-500/20 text-green-400'
                    : score.trend.direction === 'DECLINING'
                    ? 'bg-red-500/20 text-red-400'
                    : 'bg-gray-500/20 text-gray-400'
                }`}
              >
                {score.trend.direction}
              </span>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  ComplianceDashboard,
  ComplianceRecord,
  ComplianceViolation,
  ComplianceFinding,
  ComplianceAction,
  RegulatoryAuthority,
  ComplianceCategory,
} from '@/types/compliance'
import { RegulatoryAuthorityNode } from '@/types/compliance-hierarchy'
import { complianceService } from '@/lib/services/compliance/complianceService'
import { authorityHierarchyService } from '@/lib/services/compliance/authorityHierarchyService'
import ComplianceOverview from './ComplianceOverview'
import ComplianceByCategory from './ComplianceByCategory'
import ComplianceByAuthority from './ComplianceByAuthority'
import ComplianceTrends from './ComplianceTrends'
import ComplianceAlerts from './ComplianceAlerts'
import ComplianceCalendar from './ComplianceCalendar'
import IntelligentRecommendations from './IntelligentRecommendations'
import RiskPrediction from './RiskPrediction'
import DocumentTemplates from './DocumentTemplates'
import ComplianceReports from './ComplianceReports'
import ComplianceMap from './ComplianceMap'
import ComplianceScoring from './ComplianceScoring'

interface EnhancedComplianceDashboardProps {
  tenantId: string
}

export default function EnhancedComplianceDashboard({
  tenantId,
}: EnhancedComplianceDashboardProps) {
  const [dashboard, setDashboard] = useState<ComplianceDashboard | null>(null)
  const [loading, setLoading] = useState(true)
  const [selectedView, setSelectedView] = useState<'overview' | 'authorities' | 'categories' | 'tools' | 'calendar' | 'intelligence' | 'templates' | 'reports' | 'map'>('overview')
  const [authorityHierarchy, setAuthorityHierarchy] = useState<RegulatoryAuthorityNode[]>([])
  const [selectedAuthority, setSelectedAuthority] = useState<string | null>(null)

  useEffect(() => {
    loadDashboard()
    loadAuthorityHierarchy()
  }, [tenantId])

  const loadDashboard = async () => {
    try {
      setLoading(true)
      const data = await complianceService.generateDashboard(tenantId)
      setDashboard(data)
    } catch (error) {
      console.error('Error loading dashboard:', error)
    } finally {
      setLoading(false)
    }
  }

  const loadAuthorityHierarchy = async () => {
    try {
      const roots = authorityHierarchyService.getRootNodes()
      setAuthorityHierarchy(roots)
    } catch (error) {
      console.error('Error loading authority hierarchy:', error)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-500"></div>
      </div>
    )
  }

  if (!dashboard) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-400">No compliance data available</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-white">Compliance Management</h1>
          <p className="text-gray-400 mt-1">Comprehensive compliance monitoring and management</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => loadDashboard()}
            className="px-4 py-2 bg-cyan-500/20 hover:bg-cyan-500/30 border border-cyan-500/30 rounded-lg text-cyan-400 transition-colors"
          >
            <i className="ri-refresh-line mr-2"></i>
            Refresh
          </button>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex gap-2 border-b border-white/10 overflow-x-auto">
        {[
          { id: 'overview', label: 'Overview', icon: 'ri-dashboard-line' },
          { id: 'authorities', label: 'Authorities', icon: 'ri-government-line' },
          { id: 'categories', label: 'Categories', icon: 'ri-folder-line' },
          { id: 'calendar', label: 'Calendar', icon: 'ri-calendar-line' },
          { id: 'intelligence', label: 'AI Intelligence', icon: 'ri-brain-line' },
          { id: 'tools', label: 'Tools', icon: 'ri-tools-line' },
          { id: 'templates', label: 'Templates', icon: 'ri-file-text-line' },
          { id: 'reports', label: 'Reports', icon: 'ri-file-chart-line' },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setSelectedView(tab.id as any)}
            className={`px-4 py-2 border-b-2 transition-colors ${
              selectedView === tab.id
                ? 'border-cyan-500 text-cyan-400'
                : 'border-transparent text-gray-400 hover:text-white'
            }`}
          >
            <i className={`${tab.icon} mr-2`}></i>
            {tab.label}
          </button>
        ))}
      </div>

      {/* Overview View */}
      {selectedView === 'overview' && (
        <div className="space-y-6">
          <ComplianceOverview dashboard={dashboard} />
          
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <ComplianceTrends trends={dashboard.complianceTrend} dashboard={dashboard} />
            <ComplianceAlerts alerts={dashboard.criticalAlerts} dashboard={dashboard} />
          </div>

          {/* Recent Activity */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
            <h2 className="text-xl font-semibold text-white mb-4">Recent Activity</h2>
            
            <div className="space-y-4">
              {/* Recent Violations */}
              {dashboard.recentViolations && dashboard.recentViolations.length > 0 && (
                <div>
                  <h3 className="text-sm font-medium text-gray-400 mb-2">Recent Violations</h3>
                  <div className="space-y-2">
                    {dashboard.recentViolations.slice(0, 5).map((violation) => (
                      <div
                        key={violation.id}
                        className="flex items-center justify-between p-3 bg-red-500/10 border border-red-500/20 rounded-lg"
                      >
                        <div>
                          <p className="text-white text-sm">{violation.description}</p>
                          <p className="text-xs text-gray-400 mt-1">
                            {new Date(violation.detectedAt).toLocaleDateString()}
                          </p>
                        </div>
                        <span
                          className={`px-2 py-1 rounded text-xs font-medium ${
                            violation.severity === 'CRITICAL'
                              ? 'bg-red-500/20 text-red-400'
                              : violation.severity === 'HIGH'
                              ? 'bg-orange-500/20 text-orange-400'
                              : 'bg-yellow-500/20 text-yellow-400'
                          }`}
                        >
                          {violation.severity}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Recent Findings */}
              {dashboard.recentFindings && dashboard.recentFindings.length > 0 && (
                <div>
                  <h3 className="text-sm font-medium text-gray-400 mb-2">Recent Findings</h3>
                  <div className="space-y-2">
                    {dashboard.recentFindings.slice(0, 5).map((finding) => (
                      <div
                        key={finding.id}
                        className="flex items-center justify-between p-3 bg-yellow-500/10 border border-yellow-500/20 rounded-lg"
                      >
                        <div>
                          <p className="text-white text-sm">{finding.description}</p>
                          <p className="text-xs text-gray-400 mt-1">
                            {finding.type} • {finding.severity}
                          </p>
                        </div>
                        <span
                          className={`px-2 py-1 rounded text-xs ${
                            finding.status === 'RESOLVED'
                              ? 'bg-green-500/20 text-green-400'
                              : 'bg-yellow-500/20 text-yellow-400'
                          }`}
                        >
                          {finding.status}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Pending Actions */}
              {dashboard.recentActions && dashboard.recentActions.length > 0 && (
                <div>
                  <h3 className="text-sm font-medium text-gray-400 mb-2">Pending Actions</h3>
                  <div className="space-y-2">
                    {dashboard.recentActions.slice(0, 5).map((action) => (
                      <div
                        key={action.id}
                        className="flex items-center justify-between p-3 bg-blue-500/10 border border-blue-500/20 rounded-lg"
                      >
                        <div>
                          <p className="text-white text-sm">{action.title}</p>
                          <p className="text-xs text-gray-400 mt-1">
                            {action.dueDate
                              ? `Due: ${new Date(action.dueDate).toLocaleDateString()}`
                              : 'No due date'}
                          </p>
                        </div>
                        <span
                          className={`px-2 py-1 rounded text-xs ${
                            action.status === 'COMPLETED'
                              ? 'bg-green-500/20 text-green-400'
                              : action.status === 'IN_PROGRESS'
                              ? 'bg-blue-500/20 text-blue-400'
                              : 'bg-gray-500/20 text-gray-400'
                          }`}
                        >
                          {action.status}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Authorities View */}
      {selectedView === 'authorities' && (
        <div className="space-y-6">
          <ComplianceByAuthority dashboard={dashboard} />
          
          {/* Authority Hierarchy */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
            <h2 className="text-xl font-semibold text-white mb-4">Regulatory Authority Hierarchy</h2>
            
            <div className="space-y-4">
              {authorityHierarchy.map((authority) => (
                <AuthorityHierarchyNode
                  key={authority.id}
                  authority={authority}
                  selected={selectedAuthority === authority.id}
                  onSelect={() => setSelectedAuthority(authority.id)}
                />
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Categories View */}
      {selectedView === 'categories' && (
        <ComplianceByCategory dashboard={dashboard} />
      )}

      {/* Calendar View */}
      {selectedView === 'calendar' && (
        <ComplianceCalendar tenantId={tenantId} />
      )}

      {/* Intelligence View */}
      {selectedView === 'intelligence' && (
        <div className="space-y-6">
          <ComplianceScoring tenantId={tenantId} />
          <RiskPrediction tenantId={tenantId} />
          <IntelligentRecommendations tenantId={tenantId} />
        </div>
      )}

      {/* Tools View */}
      {selectedView === 'tools' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <ToolCard
            title="Requirement Builder"
            description="Build custom compliance requirements"
            icon="ri-file-add-line"
            color="cyan"
            onClick={() => window.location.href = '/compliance/tools/requirement-builder'}
          />
          <ToolCard
            title="Compliance Checker"
            description="Perform comprehensive compliance checks"
            icon="ri-shield-check-line"
            color="green"
            onClick={() => {/* TODO: Navigate to compliance checker */}}
          />
          <ToolCard
            title="Document Manager"
            description="Manage compliance documents"
            icon="ri-folder-upload-line"
            color="blue"
            onClick={() => {/* TODO: Navigate to document manager */}}
          />
          <ToolCard
            title="Risk Analyzer"
            description="Analyze compliance risks"
            icon="ri-alert-line"
            color="orange"
            onClick={() => {/* TODO: Navigate to risk analyzer */}}
          />
          <ToolCard
            title="Local Knowledge"
            description="Browse local regulations and knowledge"
            icon="ri-book-open-line"
            color="purple"
            onClick={() => window.location.href = '/compliance/tools/knowledge'}
          />
          <ToolCard
            title="Compliance Calendar"
            description="View deadlines and renewals"
            icon="ri-calendar-line"
            color="indigo"
            onClick={() => setSelectedView('calendar')}
          />
          <ToolCard
            title="AI Intelligence"
            description="Risk prediction and recommendations"
            icon="ri-brain-line"
            color="pink"
            onClick={() => setSelectedView('intelligence')}
          />
          <ToolCard
            title="Compliance Simulator"
            description="Simulate compliance scenarios"
            icon="ri-flask-line"
            color="rose"
            onClick={() => {/* TODO: Navigate to simulator */}}
          />
          <ToolCard
            title="Compliance Map"
            description="Visual compliance mapping"
            icon="ri-map-line"
            color="teal"
            onClick={() => setSelectedView('map')}
          />
        </div>
      )}

      {/* Templates View */}
      {selectedView === 'templates' && (
        <DocumentTemplates />
      )}

      {/* Reports View */}
      {selectedView === 'reports' && (
        <ComplianceReports tenantId={tenantId} />
      )}

      {/* Map View */}
      {selectedView === 'map' && (
        <ComplianceMap tenantId={tenantId} />
      )}
    </div>
  )
}

// Authority Hierarchy Node Component
interface AuthorityHierarchyNodeProps {
  authority: RegulatoryAuthorityNode
  selected: boolean
  onSelect: () => void
}

function AuthorityHierarchyNode({
  authority,
  selected,
  onSelect,
}: AuthorityHierarchyNodeProps) {
  const [expanded, setExpanded] = useState(false)
  const children = authorityHierarchyService.getChildren(authority.id)

  return (
    <div>
      <div
        onClick={onSelect}
        className={`p-4 rounded-lg border cursor-pointer transition-colors ${
          selected
            ? 'bg-cyan-500/20 border-cyan-500/30'
            : 'bg-white/5 border-white/10 hover:bg-white/10'
        }`}
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            {children.length > 0 && (
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  setExpanded(!expanded)
                }}
                className="text-gray-400 hover:text-white"
              >
                <i className={`ri-arrow-${expanded ? 'down' : 'right'}-s-line`}></i>
              </button>
            )}
            <div>
              <h3 className="text-white font-medium">{authority.name}</h3>
              <p className="text-sm text-gray-400">{authority.code} • Level {authority.level}</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <span className="px-2 py-1 bg-cyan-500/20 text-cyan-400 rounded text-xs">
              {authority.type}
            </span>
            {authority.status === 'ACTIVE' && (
              <span className="w-2 h-2 bg-green-500 rounded-full"></span>
            )}
          </div>
        </div>
        {authority.description && (
          <p className="text-sm text-gray-400 mt-2">{authority.description}</p>
        )}
      </div>
      
      {expanded && children.length > 0 && (
        <div className="ml-8 mt-2 space-y-2">
          {children.map((child) => (
            <AuthorityHierarchyNode
              key={child.id}
              authority={child}
              selected={false}
              onSelect={() => {}}
            />
          ))}
        </div>
      )}
    </div>
  )
}

// Tool Card Component
interface ToolCardProps {
  title: string
  description: string
  icon: string
  color: string
  onClick: () => void
}

function ToolCard({ title, description, icon, color, onClick }: ToolCardProps) {
  const colorClasses = {
    cyan: 'bg-cyan-500/20 border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/30',
    green: 'bg-green-500/20 border-green-500/30 text-green-400 hover:bg-green-500/30',
    blue: 'bg-blue-500/20 border-blue-500/30 text-blue-400 hover:bg-blue-500/30',
    orange: 'bg-orange-500/20 border-orange-500/30 text-orange-400 hover:bg-orange-500/30',
    purple: 'bg-purple-500/20 border-purple-500/30 text-purple-400 hover:bg-purple-500/30',
    pink: 'bg-pink-500/20 border-pink-500/30 text-pink-400 hover:bg-pink-500/30',
  }

  return (
    <motion.div
      whileHover={{ scale: 1.02 }}
      whileTap={{ scale: 0.98 }}
      onClick={onClick}
      className={`p-6 rounded-xl border cursor-pointer transition-all ${colorClasses[color as keyof typeof colorClasses]}`}
    >
      <div className="flex items-start gap-4">
        <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${colorClasses[color as keyof typeof colorClasses]}`}>
          <i className={`${icon} text-2xl`}></i>
        </div>
        <div className="flex-1">
          <h3 className="text-lg font-semibold mb-1">{title}</h3>
          <p className="text-sm opacity-80">{description}</p>
        </div>
      </div>
    </motion.div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { IntelligentRecommendation } from '@/lib/services/compliance/intelligentComplianceEngine'
import { intelligentComplianceEngine } from '@/lib/services/compliance/intelligentComplianceEngine'
import { complianceService } from '@/lib/services/compliance/complianceService'
import { authorityHierarchyService } from '@/lib/services/compliance/authorityHierarchyService'

interface IntelligentRecommendationsProps {
  tenantId: string
}

export default function IntelligentRecommendations({ tenantId }: IntelligentRecommendationsProps) {
  const [recommendations, setRecommendations] = useState<IntelligentRecommendation[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadRecommendations()
  }, [tenantId])

  const loadRecommendations = async () => {
    try {
      setLoading(true)
      const records = complianceService.getRecordsByTenant(tenantId)
      const allAuthorities = authorityHierarchyService.getAllNodes()
      const regulations = allAuthorities.flatMap(auth =>
        authorityHierarchyService.getRegulationsByAuthority(auth.id)
      )
      
      const recs = intelligentComplianceEngine.generateIntelligentRecommendations(records, regulations)
      setRecommendations(recs)
    } catch (error) {
      console.error('Error loading recommendations:', error)
    } finally {
      setLoading(false)
    }
  }

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'CRITICAL': return 'bg-red-500/20 border-red-500/30 text-red-400'
      case 'HIGH': return 'bg-orange-500/20 border-orange-500/30 text-orange-400'
      case 'MEDIUM': return 'bg-yellow-500/20 border-yellow-500/30 text-yellow-400'
      default: return 'bg-blue-500/20 border-blue-500/30 text-blue-400'
    }
  }

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'AUTO_FIX': return 'ri-magic-line'
      case 'PREVENTIVE': return 'ri-shield-line'
      case 'IMPROVEMENT': return 'ri-arrow-up-line'
      case 'OPTIMIZATION': return 'ri-speed-up-line'
      default: return 'ri-lightbulb-line'
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[200px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-white flex items-center gap-2">
          <i className="ri-brain-line text-cyan-400"></i>
          AI-Powered Recommendations
        </h3>
        <button
          onClick={loadRecommendations}
          className="text-gray-400 hover:text-white transition-colors"
        >
          <i className="ri-refresh-line"></i>
        </button>
      </div>

      {recommendations.length === 0 ? (
        <div className="text-center py-8 text-gray-400">
          <i className="ri-checkbox-circle-line text-4xl mb-2 text-green-400"></i>
          <p>No recommendations at this time</p>
          <p className="text-sm mt-1">All compliance requirements are being met</p>
        </div>
      ) : (
        <div className="space-y-3">
          {recommendations.map((rec, index) => (
            <motion.div
              key={rec.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.1 }}
              className={`p-4 rounded-lg border ${getPriorityColor(rec.priority)}`}
            >
              <div className="flex items-start gap-3">
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${getPriorityColor(rec.priority)}`}>
                  <i className={`${getTypeIcon(rec.type)} text-xl`}></i>
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <h4 className="text-white font-medium">{rec.title}</h4>
                    <span className="px-2 py-0.5 rounded text-xs bg-white/10 text-white">
                      {rec.confidence}% confidence
                    </span>
                  </div>
                  <p className="text-sm text-gray-300 mb-3">{rec.description}</p>
                  
                  <div className="flex items-center gap-4 text-xs text-gray-400 mb-3">
                    <span>
                      <i className="ri-bar-chart-line mr-1"></i>
                      Impact: {rec.impact}
                    </span>
                    <span>
                      <i className="ri-tools-line mr-1"></i>
                      Effort: {rec.effort}
                    </span>
                    <span>
                      <i className="ri-star-line mr-1"></i>
                      Benefit: {rec.estimatedBenefit}
                    </span>
                  </div>

                  {rec.actions.length > 0 && (
                    <div className="mt-3">
                      <p className="text-xs text-gray-400 mb-2">Recommended Actions:</p>
                      <ul className="space-y-1">
                        {rec.actions.map((action, idx) => (
                          <li key={idx} className="text-xs text-gray-300 flex items-center gap-2">
                            <i className="ri-checkbox-blank-circle-line text-cyan-400"></i>
                            {action}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  <div className="mt-3 flex gap-2">
                    <button className="px-3 py-1.5 bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-400 text-xs rounded-lg transition-colors border border-cyan-500/30">
                      <i className="ri-check-line mr-1"></i>
                      Apply
                    </button>
                    <button className="px-3 py-1.5 bg-white/5 hover:bg-white/10 text-gray-400 text-xs rounded-lg transition-colors border border-white/10">
                      <i className="ri-eye-line mr-1"></i>
                      View Details
                    </button>
                  </div>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { RiskPrediction } from '@/lib/services/compliance/intelligentComplianceEngine'
import { intelligentComplianceEngine } from '@/lib/services/compliance/intelligentComplianceEngine'
import { complianceService } from '@/lib/services/compliance/complianceService'
import { authorityHierarchyService } from '@/lib/services/compliance/authorityHierarchyService'
import { RadialBarChart, RadialBar, ResponsiveContainer, Cell, Legend } from 'recharts'

interface RiskPredictionProps {
  tenantId: string
}

export default function RiskPrediction({ tenantId }: RiskPredictionProps) {
  const [prediction, setPrediction] = useState<RiskPrediction | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadRiskPrediction()
  }, [tenantId])

  const loadRiskPrediction = async () => {
    try {
      setLoading(true)
      const records = complianceService.getRecordsByTenant(tenantId)
      const allAuthorities = authorityHierarchyService.getAllNodes()
      const regulations = allAuthorities.flatMap(auth =>
        authorityHierarchyService.getRegulationsByAuthority(auth.id)
      )
      
      const pred = intelligentComplianceEngine.predictComplianceRisk(records, regulations)
      setPrediction(pred)
    } catch (error) {
      console.error('Error loading risk prediction:', error)
    } finally {
      setLoading(false)
    }
  }

  const getRiskColor = (risk: string) => {
    switch (risk) {
      case 'CRITICAL': return { bg: 'bg-red-500/20', border: 'border-red-500/50', text: 'text-red-400', fill: '#ef4444' }
      case 'HIGH': return { bg: 'bg-orange-500/20', border: 'border-orange-500/50', text: 'text-orange-400', fill: '#f97316' }
      case 'MEDIUM': return { bg: 'bg-yellow-500/20', border: 'border-yellow-500/50', text: 'text-yellow-400', fill: '#eab308' }
      default: return { bg: 'bg-green-500/20', border: 'border-green-500/50', text: 'text-green-400', fill: '#22c55e' }
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[300px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div>
      </div>
    )
  }

  if (!prediction) {
    return (
      <div className="text-center py-8 text-gray-400">
        <p>No risk prediction available</p>
      </div>
    )
  }

  const riskColor = getRiskColor(prediction.overallRisk)

  const chartData = [
    { name: 'Risk Score', value: prediction.riskScore, fill: riskColor.fill },
    { name: 'Remaining', value: 100 - prediction.riskScore, fill: 'rgba(255,255,255,0.1)' },
  ]

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-white flex items-center gap-2">
          <i className="ri-alert-line text-cyan-400"></i>
          AI Risk Prediction
        </h3>
        <button
          onClick={loadRiskPrediction}
          className="text-gray-400 hover:text-white transition-colors"
        >
          <i className="ri-refresh-line"></i>
        </button>
      </div>

      {/* Risk Score Visualization */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className={`${riskColor.bg} backdrop-blur-xl border ${riskColor.border} rounded-xl p-6`}>
          <div className="text-center">
            <h4 className="text-sm text-gray-400 mb-2">Overall Risk Level</h4>
            <div className="text-4xl font-bold mb-2" style={{ color: riskColor.fill }}>
              {prediction.overallRisk}
            </div>
            <div className="text-2xl font-semibold mb-4" style={{ color: riskColor.fill }}>
              {prediction.riskScore.toFixed(1)}%
            </div>
            <div className="text-xs text-gray-400">
              Confidence: {prediction.confidence}%
            </div>
          </div>
        </div>

        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
          <h4 className="text-sm text-gray-400 mb-4">Risk Score Breakdown</h4>
          <ResponsiveContainer width="100%" height={200}>
            <RadialBarChart
              cx="50%"
              cy="50%"
              innerRadius="60%"
              outerRadius="90%"
              data={chartData}
              startAngle={90}
              endAngle={-270}
            >
              <RadialBar dataKey="value" cornerRadius={10}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.fill} />
                ))}
              </RadialBar>
            </RadialBarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Risk Factors */}
      {prediction.riskFactors.length > 0 && (
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6">
          <h4 className="text-lg font-semibold text-white mb-4">Risk Factors</h4>
          <div className="space-y-3">
            {prediction.riskFactors.map((factor, index) => {
              const factorColor = getRiskColor(factor.severity)
