                  </div>
                  <p className="text-sm text-gray-300 mb-2">{violation.description}</p>
                  <div className="text-xs text-gray-400 mb-2">
                    Timeframe: {violation.timeframe}
                  </div>
                  {violation.preventionActions.length > 0 && (
                    <div className="mt-2">
                      <p className="text-xs text-gray-400 mb-1">Prevention Actions:</p>
                      <ul className="space-y-1">
                        {violation.preventionActions.map((action, idx) => (
                          <li key={idx} className="text-xs text-gray-300 flex items-center gap-2">
