  // Send message with attachment support
  const handleSend = useCallback(async (messageText?: string) => {
    const textToSend = messageText || input.trim()
    // Allow sending even if no text if there's an attachment
    if ((!textToSend && !activeAttachment) || isLoading) return

    // Create user message with attachment info
    const userMessage: CopilotMessage = {
      id: `msg-${Date.now()}`,
      role: 'user',
      content: activeAttachment
        ? `${textToSend || 'Analyze this file'}\n[Attachment: ${activeAttachment.name} (${(activeAttachment.size / 1024).toFixed(1)}KB)]`
        : textToSend,
      timestamp: new Date(),
    }

    setMessages(prev => [...prev, userMessage])
    const attachmentToSend = activeAttachment
    setInput('')
    setActiveAttachment(null) // Clear attachment after sending
    setIsLoading(true)
    setError(null)

    try {
      let response: Response

      // If there's an attachment, use FormData
      if (attachmentToSend) {
        const formData = new FormData()
        formData.append('file', attachmentToSend)
        formData.append('message', textToSend || 'Please analyze this file and provide insights.')
        formData.append('conversationId', conversationId || '')
        formData.append('context', JSON.stringify({
          moduleId: pathname?.split('/')[1],
          mode: mode,
        }))
        formData.append('options', JSON.stringify({
          useRAG: true,
          useMemory: true,
          useTools: true,
        }))

        response = await fetch('/api/copilot/chat/with-attachment', {
          method: 'POST',
          body: formData,
        })
      } else {
        // Use streaming if enabled, otherwise use regular endpoint
        let streamingSucceeded = false

        if (useStreaming) {
          try {
            // Streaming request
            response = await fetch('/api/copilot/chat/stream', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
              },
              body: JSON.stringify({
                conversationId,
                message: textToSend,
                context: {
                  moduleId: pathname?.split('/')[1],
                  mode: mode,
                },
                options: {
                  useRAG: true,
                  useMemory: true,
                  useTools: true,
                },
              } as CopilotRequest),
            })

            if (!response.ok) {
              throw new Error(`HTTP ${response.status}: ${response.statusText}`)
            }

            // Handle streaming response
            const reader = response.body?.getReader()
            const decoder = new TextDecoder()
            let fullContent = ''
            let metadata: any = null

            if (reader) {
              // Create assistant message placeholder
              const assistantMessageId = `msg-${Date.now()}`
              const assistantMessage: CopilotMessage = {
                id: assistantMessageId,
                role: 'assistant',
                content: '',
                timestamp: new Date(),
              }
              setMessages(prev => [...prev, assistantMessage])
              setStreamingContent('')

              while (true) {
                const { done, value } = await reader.read()
                if (done) break

                const chunk = decoder.decode(value, { stream: true })
                const lines = chunk.split('\n').filter(Boolean)

                for (const line of lines) {
                  try {
                    const data = JSON.parse(line)

                    if (data.type === 'chunk' && data.content) {
                      fullContent += data.content
                      setStreamingContent(fullContent)

                      // Update message in real-time
                      setMessages(prev => prev.map(msg =>
                        msg.id === assistantMessageId
                          ? { ...msg, content: fullContent }
                          : msg
                      ))
                    } else if (data.type === 'metadata') {
                      metadata = data.metadata
                    } else if (data.type === 'error') {
                      throw new Error(data.error || 'Streaming error')
                    }
                  } catch (e) {
                    // Skip invalid JSON
                  }
                }
              }

              // Finalize message
              setStreamingContent('')
              setMessages(prev => prev.map(msg =>
                msg.id === assistantMessageId
                  ? {
                    ...msg,
                    content: fullContent,
                    metadata: metadata ? {
                      confidence: metadata.confidence,
                      tokensUsed: metadata.tokensUsed,
                      processingTime: metadata.processingTime,
                    } : undefined,
                  }
                  : msg
              ))

              setIsLoading(false)
              setError(null)
              streamingSucceeded = true
            }
          } catch (streamError) {
            console.warn('[Copilot] Streaming failed, falling back to non-streaming:', streamError)
            // Fall through to non-streaming
          }
        }

        // Non-streaming fallback (only if streaming not used or failed)
        if (!streamingSucceeded) {
          response = await fetch('/api/copilot/chat', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              conversationId,
              message: textToSend,
              context: {
                moduleId: pathname?.split('/')[1],
                mode: mode,
              },
              options: {
                useRAG: true,
                useMemory: true,
                useTools: true,
              },
            } as CopilotRequest),
          })
        }
      }

      if (!response.ok) {
        let errorData: any = {}
        try {
          errorData = await response.json()
        } catch (e) {
          // If JSON parsing fails, try to get text
          const text = await response.text().catch(() => '')
          errorData = { error: text || `HTTP ${response.status}: ${response.statusText}` }
        }

        const errorMessage = errorData.error || errorData.details || errorData.message || `Failed to get response (${response.status})`
        console.error('[Copilot] API error:', {
          status: response.status,
          statusText: response.statusText,
          error: errorMessage,
          details: errorData,
          fullResponse: errorData,
        })

        // Create an error message that includes the actual error details
        const detailedError = new Error(errorMessage)
        ;(detailedError as any).response = response
        ;(detailedError as any).errorData = errorData
        throw detailedError
      }

      let data: CopilotResponse
      try {
        data = await response.json()
      } catch (jsonError) {
        console.error('[Copilot] Failed to parse JSON response:', jsonError)
        const text = await response.text().catch(() => '')
        throw new Error(`Invalid response from server: ${text.substring(0, 200)}`)
      }

      // Validate response structure
      if (!data || !data.message) {
        console.error('[Copilot] Invalid response structure:', data)
        throw new Error('Invalid response from server: missing message')
      }

      // Add attachment analysis info if present
      if (data.message.metadata?.attachmentAnalysis) {
        const analysis = data.message.metadata.attachmentAnalysis
        data.message.content = `📎 **File Analysis: ${analysis.filename}**\n\n${data.message.content}\n\n---\n**Analysis Summary:**\n- Type: ${analysis.type}\n- Size: ${(analysis.size / 1024).toFixed(1)}KB\n- Confidence: ${Math.round(analysis.confidence * 100)}%\n${analysis.extractedText ? `- Extracted ${analysis.extractedText.length} characters` : ''}`
      }

      // Store enhanced response data in message metadata for rendering
      try {
        if ('proactiveInsights' in data && data.proactiveInsights && Array.isArray(data.proactiveInsights)) {
          (data.message.metadata as any).proactiveInsights = data.proactiveInsights
        }
        if ('suggestedOptimizations' in data && data.suggestedOptimizations && Array.isArray(data.suggestedOptimizations)) {
          (data.message.metadata as any).suggestedOptimizations = data.suggestedOptimizations
        }
        if ('reasoning' in data && data.reasoning) {
          // Safely access reasoning - handle different structures
          if (typeof data.reasoning === 'object' && data.reasoning !== null) {
            if ('steps' in data.reasoning && Array.isArray(data.reasoning.steps)) {
              (data.message.metadata as any).reasoning = data.reasoning.steps
            } else if (Array.isArray(data.reasoning)) {
              // If reasoning itself is an array, use it directly
              (data.message.metadata as any).reasoning = data.reasoning
            }
            if ('confidenceBreakdown' in data.reasoning && data.reasoning.confidenceBreakdown) {
              (data.message.metadata as any).confidenceBreakdown = data.reasoning.confidenceBreakdown
            }
          }
        }
      } catch (metadataError) {
        console.warn('[Copilot] Failed to store enhanced metadata:', metadataError)
        // Continue without enhanced features - don't break the flow
      }

      setMessages(prev => [...prev, data.message])

      // Handle navigation and UI actions from tool outputs - ENHANCED
      if (data.message.metadata?.toolResults) {
        console.log('[Copilot] 🔧 Processing tool results:', {
          count: data.message.metadata.toolResults.length,
          results: data.message.metadata.toolResults.map(r => ({
            success: r.success,
            toolId: r.toolCallId,
            hasOutput: !!r.output,
            outputKeys: r.output ? Object.keys(r.output) : [],
          })),
        })

        for (const toolResult of data.message.metadata.toolResults) {
          if (toolResult.success && toolResult.output) {
            const output = toolResult.output as any

            // Handle navigation actions - ENHANCED WITH ERROR HANDLING
            if (output.action === 'navigate' && output.path) {
              console.log('[Copilot] ✅ Navigation requested:', {
                path: output.path,
                entityType: output.entityType,
                entityId: output.entityId,
              })

              // Use router.push with error handling
              try {
                setTimeout(() => {
                  router.push(output.path)
                  console.log('[Copilot] ✅ Successfully navigated to:', output.path)

                  // Show success message in chat
                  setMessages(prev => [...prev, {
                    id: `nav-${Date.now()}`,
                    role: 'assistant',
                    content: `✅ Navigated to ${output.path}`,
                    timestamp: new Date(),
                  }])
                }, 500) // Small delay for better UX
              } catch (navError: any) {
                console.error('[Copilot] ❌ Navigation error:', navError)
                // Fallback to window.location
                try {
                  window.location.href = output.path
                } catch (fallbackError) {
                  console.error('[Copilot] ❌ Fallback navigation also failed:', fallbackError)
                  setMessages(prev => [...prev, {
                    id: `nav-error-${Date.now()}`,
                    role: 'assistant',
                    content: `⚠️ Could not navigate to ${output.path}. Please navigate manually.`,
                    timestamp: new Date(),
                  }])
                }
              }
            }

            // Handle created items - auto-navigate if entityType and entityId are present
            if (output.entityType && output.entityId && !output.action) {
              console.log('[Copilot] 📦 Created entity detected:', {
                entityType: output.entityType,
                entityId: output.entityId,
                id: output.id,
              })

              // Determine navigation path based on entity type
              let viewPath: string | null = null
              if (output.entityType === 'ASN') {
                viewPath = `/warehouse/inbound?asnId=${output.entityId}`
              } else if (output.entityType === 'CAPA') {
                viewPath = `/iso-ims/capa/${output.entityId}`
              } else if (output.entityType === 'Proposal') {
                viewPath = `/proposals/rfq/${output.entityId}`
              }

              if (viewPath) {
                console.log('[Copilot] 🚀 Auto-navigating to created entity:', viewPath)
                setTimeout(() => {
                  try {
                    router.push(viewPath!)
                    setMessages(prev => [...prev, {
                      id: `auto-nav-${Date.now()}`,
                      role: 'assistant',
                      content: `✅ Opening ${output.entityType} ${output.id || output.entityId}`,
                      timestamp: new Date(),
                    }])
                  } catch (error) {
                    console.error('[Copilot] Auto-navigation error:', error)
                  }
                }, 1000) // Slightly longer delay for created items
              }
            }

            // Handle click actions
            if (output.action === 'click' && output.selector) {
              console.log('[Copilot] 🖱️ Click action requested:', output.selector)
              setTimeout(() => {
                // Try to find and click the element
                const element = document.querySelector(output.selector) as HTMLElement
                if (element) {
                  element.click()
                  console.log('[Copilot] ✅ Successfully clicked element:', output.selector)
                } else {
                  // Fallback: try to find by text content
                  const buttons = Array.from(document.querySelectorAll('button, a, [role="button"]'))
                  const match = buttons.find(el => 
                    el.textContent?.toLowerCase().includes(output.selector.toLowerCase()) ||
                    el.getAttribute('aria-label')?.toLowerCase().includes(output.selector.toLowerCase())
                  ) as HTMLElement
                  if (match) {
                    match.click()
                    console.log('[Copilot] ✅ Successfully clicked element by text:', output.selector)
                  } else {
                    console.warn('[Copilot] ⚠️ Could not find element to click:', output.selector)
                  }
                }
              }, 500)
            }
          } else if (!toolResult.success) {
            console.error('[Copilot] ❌ Tool execution failed:', {
              toolId: toolResult.toolCallId,
              error: toolResult.error,
            })
          }
        }
      }

      // Execute actions if present in content (legacy format)
      if (data.message.content.includes('[ACTION]') || data.message.content.includes('[CLICK') || data.message.content.includes('[NAVIGATE')) {
        executeAction(data.message.content)
      }

      if (data.message.metadata?.knowledgeUsed) {
        console.log('[Copilot] Used knowledge:', data.message.metadata.knowledgeUsed.length, 'entries')
      }
      if (!conversationId && data.message.id) {
        // Extract conversation ID from response if available
        setConversationId(data.message.id.split('-')[0]); // Simple extraction, adjust based on actual ID format
      }
    } catch (err: any) {
      console.error('[Copilot] Error:', err)
      console.error('[Copilot] Error type:', err?.constructor?.name)
      console.error('[Copilot] Error stack:', err?.stack)
      console.error('[Copilot] Full error object:', JSON.stringify(err, Object.getOwnPropertyNames(err)))

      // Extract error message from response if available
      let errorMsg = 'An error occurred'
      if (err?.response) {
        try {
          const errorData = await err.response.json().catch(() => ({}))
          errorMsg = errorData.details || errorData.message || errorData.error || errorMsg
        } catch {
          // If JSON parsing fails, use the error message
        }
      }

      if (err instanceof Error) {
        errorMsg = err.message
      } else if (err?.error) {
        errorMsg = err.error
      } else if (err?.details) {
        errorMsg = err.details
      } else if (err?.message) {
        errorMsg = err.message
      }

      // Check if it's a transient error that we should retry
      const isTransientError = errorMsg.includes('network') ||
        errorMsg.includes('fetch') ||
        errorMsg.includes('ECONNREFUSED') ||
        errorMsg.includes('timeout') ||
        errorMsg.includes('429')

      // Auto-retry transient errors (max 2 retries)
      if (isTransientError && retryCount < 2) {
        const newRetryCount = retryCount + 1
        setRetryCount(newRetryCount)
        setConnectionStatus('checking')
        setError(null) // Clear error during retry

        // Wait before retry (exponential backoff)
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, retryCount) * 1000))

        // Retry the request with the original message
        const retryMessage = messageText || textToSend
        if (retryMessage) {
          return handleSend(retryMessage)
        }
      }

      // Reset retry count on new message
      setRetryCount(0)
      setError(errorMsg)
      setConnectionStatus('offline')

      // Provide more helpful error messages based on error type
      let userFriendlyMessage = 'I\'m having trouble connecting right now. Please check your connection and try again in a moment.'
      let showRetryButton = true

      if (errorMsg.includes('verification failed') || errorMsg.includes('Request verification failed')) {
        userFriendlyMessage = 'Security verification failed. Please refresh the page and try again. If the issue persists, contact your administrator.'
        showRetryButton = false
      } else if (errorMsg.includes('API key') || errorMsg.includes('Missing') || errorMsg.includes('invalid') || errorMsg.includes('No valid')) {
        userFriendlyMessage = 'I need an API key to work properly. Please check your .env.local file has OPENAI_API_KEY or ANTHROPIC_API_KEY set with a valid key (not a placeholder).'
        showRetryButton = false
      } else if (errorMsg.includes('Rate limit') || errorMsg.includes('429') || errorMsg.includes('Rate limit exceeded')) {
        userFriendlyMessage = 'I\'m receiving too many requests right now. Please wait a moment and try again.'
        showRetryButton = true
      } else if (errorMsg.includes('network') || errorMsg.includes('fetch') || errorMsg.includes('ECONNREFUSED') || errorMsg.includes('Failed to fetch')) {
        userFriendlyMessage = 'I\'m having trouble connecting to the AI service. Please check your internet connection and try again.'
        showRetryButton = true
      } else if (errorMsg.includes('401') || errorMsg.includes('Unauthorized') || errorMsg.includes('authentication')) {
        userFriendlyMessage = 'Authentication failed. Please refresh the page and try again.'
        showRetryButton = false
      } else if (errorMsg.includes('403') || errorMsg.includes('Forbidden')) {
        userFriendlyMessage = 'You don\'t have permission to perform this action. Please contact your administrator.'
        showRetryButton = false
      } else if (errorMsg.includes('500') || errorMsg.includes('Internal Server Error')) {
        userFriendlyMessage = 'The server encountered an error. Please try again in a moment.'
        showRetryButton = true
      }

      // Don't add duplicate error messages (check last 2 messages to avoid duplicates)
      const recentMessages = messages.slice(-2)
      const isDuplicate = recentMessages.some(msg =>
        msg.role === 'assistant' &&
        msg.content.includes(userFriendlyMessage.substring(0, 50))
      )

      if (isDuplicate) {
        // Already showing this error, just update the error state
        console.log('[Copilot] Skipping duplicate error message')
        return
      }

      const errorMessage: CopilotMessage = {
        id: `msg-error-${Date.now()}`,
        role: 'assistant',
        content: userFriendlyMessage + (showRetryButton ? ' Click "Retry" below to try again.' : ''),
        timestamp: new Date(),
        metadata: {
          confidence: 0.5,
          canRetry: showRetryButton,
        },
      }
      setMessages(prev => [...prev, errorMessage])
    } finally {
      setIsLoading(false)
      setConnectionStatus('online')
    }
  }, [input, isLoading, conversationId, tenantId, userId, mode, pathname, executeAction, activeAttachment, retryCount])

