          </motion.div>
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="bg-white/5 border border-white/10 rounded-xl p-6"
          >
            <div className="text-sm text-[#9ca3af] mb-2">Avg Recall</div>
            <div className="text-3xl font-bold text-white mb-1">
              {aggregatedMetrics.avgRecall.toFixed(1)}%
            </div>
            <div className="text-sm text-green-400 flex items-center gap-1">
              <i className="ri-database-line"></i>
              {aggregatedMetrics.totalRequests.toLocaleString()} requests
            </div>
          </motion.div>
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="bg-white/5 border border-white/10 rounded-xl p-6"
          >
            <div className="text-sm text-[#9ca3af] mb-2">Avg F1 Score</div>
            <div className="text-3xl font-bold text-white mb-1">
              {aggregatedMetrics.avgF1Score.toFixed(1)}%
            </div>
            <div className="text-sm text-green-400 flex items-center gap-1">
              <i className="ri-token-swap-line"></i>
              {aggregatedMetrics.totalTokens.toLocaleString()} tokens
            </div>
          </motion.div>
        </div>

        {/* Empty state */}
        {models.length === 0 && !loading && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white/5 border border-white/10 rounded-xl p-12 text-center"
          >
            <i className="ri-brain-line text-6xl text-gray-500 mb-4"></i>
            <h3 className="text-xl font-semibold text-white mb-2">No ML Models Found</h3>
            <p className="text-[#9ca3af] mb-6">
              No machine learning models are currently registered. Register a model to see analytics.
            </p>
            <a
              href="/ml-registry"
              className="inline-block px-6 py-3 bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white rounded-lg text-sm font-medium transition-colors"
            >
              Go to ML Registry
            </a>
          </motion.div>
        )}

        {/* Performance History */}
        {models.length > 0 && (
          <>
            <div className="bg-white/5 border border-white/10 rounded-xl p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-white">Model Performance History</h3>
                <div className="flex items-center gap-2">
                  {(['7d', '30d', '90d'] as const).map((range) => (
                    <button
                      key={range}
                      onClick={() => setTimeRange(range)}
                      className={`px-3 py-1 rounded text-sm transition-colors ${
                        timeRange === range
                          ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                          : 'bg-white/5 text-[#9ca3af] border border-white/10 hover:bg-white/10'
                      }`}
                    >
                      {range}
                    </button>
                  ))}
                </div>
              </div>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={performanceHistory}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                  <XAxis dataKey="date" stroke="#9ca3af" fontSize={12} />
                  <YAxis stroke="#9ca3af" fontSize={12} domain={[0, 100]} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                    labelStyle={{ color: '#fff' }}
                  />
                  <Legend />
                  <Line type="monotone" dataKey="accuracy" stroke="#06b6d4" strokeWidth={2} name="Accuracy" />
                  <Line type="monotone" dataKey="precision" stroke="#10b981" strokeWidth={2} name="Precision" />
                  <Line type="monotone" dataKey="recall" stroke="#f59e0b" strokeWidth={2} name="Recall" />
                </LineChart>
              </ResponsiveContainer>
            </div>

            {/* Model Comparison & Feedback Analysis */}
            {modelPerformance.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-white/5 border border-white/10 rounded-xl p-6">
                  <h3 className="text-lg font-semibold text-white mb-4">Model Performance Comparison</h3>
                  <ResponsiveContainer width="100%" height={300}>
                    <BarChart data={modelPerformance}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                      <XAxis 
                        dataKey="model" 
                        stroke="#9ca3af" 
                        angle={-45} 
                        textAnchor="end" 
                        height={100}
                        fontSize={10}
                      />
                      <YAxis stroke="#9ca3af" fontSize={12} domain={[0, 100]} />
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                        labelStyle={{ color: '#fff' }}
                      />
                      <Legend />
                      <Bar dataKey="accuracy" fill="#06b6d4" name="Accuracy" />
                      <Bar dataKey="precision" fill="#10b981" name="Precision" />
                      <Bar dataKey="recall" fill="#f59e0b" name="Recall" />
                      <Bar dataKey="f1" fill="#8b5cf6" name="F1 Score" />
                    </BarChart>
                  </ResponsiveContainer>
                </div>

                <div className="bg-white/5 border border-white/10 rounded-xl p-6">
                  <h3 className="text-lg font-semibold text-white mb-4">Feedback Analysis</h3>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-green-500/20 border border-green-500/30 rounded-lg p-4">
                      <div className="text-sm text-[#9ca3af] mb-1">Positive Feedback</div>
                      <div className="text-2xl font-bold text-green-400">
                        {feedbackMetrics.positive.toLocaleString()}
                      </div>
                    </div>
                    <div className="bg-red-500/20 border border-red-500/30 rounded-lg p-4">
                      <div className="text-sm text-[#9ca3af] mb-1">Negative Feedback</div>
                      <div className="text-2xl font-bold text-red-400">
                        {feedbackMetrics.negative.toLocaleString()}
                      </div>
                    </div>
                    <div className="bg-blue-500/20 border border-blue-500/30 rounded-lg p-4">
                      <div className="text-sm text-[#9ca3af] mb-1">Total Interactions</div>
                      <div className="text-2xl font-bold text-blue-400">
                        {feedbackMetrics.totalRequests.toLocaleString()}
                      </div>
                    </div>
                    <div className="bg-purple-500/20 border border-purple-500/30 rounded-lg p-4">
                      <div className="text-sm text-[#9ca3af] mb-1">Knowledge Base Entries</div>
                      <div className="text-2xl font-bold text-purple-400">
                        {feedbackMetrics.knowledgeBaseEntries.toLocaleString()}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </ErrorBoundary>
  )
}

/**
 * Mind-Blowing Home Dashboard
 * 
 * Revolutionary design with:
 * - Floating 3D navigation menu (like showcase)
 * - Major modules (Hazalyze, Logistics) with expandable sections
 * - 3D icons with perspective effects
 * - Scroll-down expand functionality
 * - No user profile box (integrated seamlessly)
 * 
 * 4IR & 5IR Aligned • Integration-First • Connectivity-Centric
 */

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { useRouter } from 'next/navigation'
import { useAuth } from '@/contexts/AuthContext'
import { useCustomer } from '@/contexts/CustomerContext'
import Link from 'next/link'
import GlobalCommandPalette from '@/components/navigation/GlobalCommandPalette'

interface MajorModule {
  id: string
  name: string
  description: string
  icon: string
  color: string
  gradient: string
  borderColor: string
  iconColor: string
  href: string
  subModules: {
    name: string
    icon: string
    href: string
    description: string
  }[]
}

interface SystemStatus {
  integrity: number
  status: 'operational' | 'degraded' | 'maintenance'
}

const colorMap: Record<string, { bg: string; text: string; icon: string; glow: string; border: string; indicator: string }> = {
  emerald: { bg: 'bg-emerald-500/20', text: 'text-emerald-400', icon: 'text-emerald-400', glow: 'shadow-emerald-500/50', border: 'border-emerald-400/50', indicator: 'bg-emerald-400' },
  cyan: { bg: 'bg-cyan-500/20', text: 'text-cyan-400', icon: 'text-cyan-400', glow: 'shadow-cyan-500/50', border: 'border-cyan-400/50', indicator: 'bg-cyan-400' },
  blue: { bg: 'bg-blue-500/20', text: 'text-blue-400', icon: 'text-blue-400', glow: 'shadow-blue-500/50', border: 'border-blue-400/50', indicator: 'bg-blue-400' },
  indigo: { bg: 'bg-indigo-500/20', text: 'text-indigo-400', icon: 'text-indigo-400', glow: 'shadow-indigo-500/50', border: 'border-indigo-400/50', indicator: 'bg-indigo-400' },
  purple: { bg: 'bg-purple-500/20', text: 'text-purple-400', icon: 'text-purple-400', glow: 'shadow-purple-500/50', border: 'border-purple-400/50', indicator: 'bg-purple-400' },
  pink: { bg: 'bg-pink-500/20', text: 'text-pink-400', icon: 'text-pink-400', glow: 'shadow-pink-500/50', border: 'border-pink-400/50', indicator: 'bg-pink-400' },
}

export default function MindBlowingHomeDashboard() {
  const { user } = useAuth()
  const { currentCustomer } = useCustomer()
  const router = useRouter()
  const [commandPaletteOpen, setCommandPaletteOpen] = useState(false)
  const [expandedModule, setExpandedModule] = useState<string | null>(null)
  const [systemStatus, setSystemStatus] = useState<SystemStatus>({
    integrity: 99.8,
    status: 'operational',
  })
  const [scrollY, setScrollY] = useState(0)
  const containerRef = useRef<HTMLDivElement>(null)

  // Major modules with expandable sub-modules
  const majorModules: MajorModule[] = [
    {
      id: 'hazalyze',
      name: 'Hazalyze',
      description: 'AI-Powered Intelligence & Analytics',
      icon: 'ri-brain-line',
      color: 'emerald',
      gradient: 'from-emerald-500/20 to-teal-500/20',
      borderColor: 'border-emerald-500/30',
      iconColor: 'text-emerald-400',
      href: '/intelligence',
      subModules: [
        { name: 'AI Copilot', icon: 'ri-robot-line', href: '/agents/showcase', description: 'Intelligent AI Assistant' },
        { name: 'Analytics', icon: 'ri-bar-chart-box-line', href: '/intelligence/analytics', description: 'Advanced Analytics' },
        { name: 'Data Mining', icon: 'ri-database-2-line', href: '/intelligence/data-mining', description: 'Data Intelligence' },
        { name: 'Process Mining', icon: 'ri-flow-chart', href: '/intelligence/process-mining', description: 'Process Intelligence' },
      ],
    },
    {
      id: 'logistics',
      name: 'Logistics',
      description: 'End-to-End Supply Chain Management',
      icon: 'ri-truck-line',
      color: 'cyan',
      gradient: 'from-cyan-500/20 to-blue-500/20',
      borderColor: 'border-cyan-500/30',
      iconColor: 'text-cyan-400',
      href: '/transportation',
      subModules: [
        { name: 'Transportation', icon: 'ri-truck-line', href: '/transportation', description: 'Fleet & Routes' },
        { name: 'Warehouse', icon: 'ri-warehouse-line', href: '/wms', description: 'Inventory Management' },
        { name: 'Marketplace', icon: 'ri-store-3-line', href: '/marketplace', description: 'Service Marketplace' },
        { name: 'Tracking', icon: 'ri-map-pin-line', href: '/tracking', description: 'Real-time Tracking' },
      ],
    },
    {
      id: 'compliance',
      name: 'Compliance',
      description: 'Trade & Regulatory Compliance',
      icon: 'ri-shield-check-line',
      color: 'blue',
      gradient: 'from-blue-500/20 to-indigo-500/20',
      borderColor: 'border-blue-500/30',
      iconColor: 'text-blue-400',
      href: '/compliance',
      subModules: [
        { name: 'Trade Compliance', icon: 'ri-global-line', href: '/trade-compliance', description: 'International Trade' },
        { name: 'QHSE', icon: 'ri-shield-star-line', href: '/qhse', description: 'Quality, Health, Safety' },
        { name: 'ISO IMS', icon: 'ri-award-line', href: '/iso-ims', description: 'ISO Management' },
        { name: 'MSDS', icon: 'ri-file-list-3-line', href: '/msds', description: 'Material Safety' },
      ],
    },
    {
      id: 'operations',
      name: 'Operations',
      description: 'Operational Excellence & Automation',
      icon: 'ri-settings-3-line',
      color: 'purple',
      gradient: 'from-purple-500/20 to-pink-500/20',
      borderColor: 'border-purple-500/30',
      iconColor: 'text-purple-400',
      href: '/workspace',
      subModules: [
        { name: 'Workspace', icon: 'ri-layout-grid-line', href: '/workspace', description: 'Unified Workspace' },
        { name: 'Proposals', icon: 'ri-file-edit-line', href: '/proposals', description: 'RFQ & Proposals' },
        { name: 'MaaS', icon: 'ri-cloud-line', href: '/maas', description: 'Platform as a Service' },
        { name: 'Facility', icon: 'ri-building-line', href: '/facility', description: 'Facility Management' },
      ],
    },
  ]

  // Track scroll for expand effect
  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY)
    }
    window.addEventListener('scroll', handleScroll, { passive: true })
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setCommandPaletteOpen(true)
      }
      if (e.key === 'Escape' && commandPaletteOpen) {
        setCommandPaletteOpen(false)
      }
    }
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [commandPaletteOpen])

  // Fetch system status - DEFERRED to avoid blocking initial render
  useEffect(() => {
    // Defer API call to avoid blocking initial page load
    const fetchStatus = async () => {
      try {
        const response = await fetch('/api/system-health/status')
        if (response.ok) {
          const data = await response.json()
          setSystemStatus({
            integrity: data.overview?.systemHealthScore || 99.8,
            status: data.overview?.systemHealthScore > 95 ? 'operational' : 'degraded',
          })
        }
      } catch (error) {
        console.error('Failed to fetch system status:', error)
      }
    }

    // Use requestIdleCallback or setTimeout to defer the API call
    if (typeof requestIdleCallback !== 'undefined') {
      requestIdleCallback(() => {
        fetchStatus()
      }, { timeout: 2000 })
    } else {
      setTimeout(fetchStatus, 1000) // 1 second delay to let page render first
    }

    const interval = setInterval(fetchStatus, 30000)
    return () => clearInterval(interval)
  }, [])

  const toggleModule = (moduleId: string) => {
    setExpandedModule(expandedModule === moduleId ? null : moduleId)
  }

  return (
    <div 
      ref={containerRef}
      className="min-h-screen bg-gradient-to-br from-[#0a0e14] via-[#0f172a] to-[#1a1f2e] relative overflow-x-hidden"
    >
      {/* Floating Command Palette Trigger - Top Right */}
      <motion.button
        onClick={() => setCommandPaletteOpen(true)}
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        className="fixed top-4 right-4 z-[9999] p-3 bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl hover:border-cyan-500/50 transition-all shadow-lg"
        title="Command Palette (⌘K)"
      >
        <i className="ri-command-line text-cyan-400 text-xl"></i>
      </motion.button>

      {/* System Status Badge - Top Left */}
      <motion.div
        initial={{ opacity: 0, x: -20 }}
        animate={{ opacity: 1, x: 0 }}
        className={`fixed top-4 left-4 z-[9999] px-4 py-2 rounded-xl border backdrop-blur-xl ${
          systemStatus.status === 'operational'
            ? 'bg-green-500/20 border-green-500/30 text-green-400'
            : 'bg-yellow-500/20 border-yellow-500/30 text-yellow-400'
        }`}
      >
        <div className="flex items-center gap-2">
          <div className={`w-2 h-2 rounded-full ${systemStatus.status === 'operational' ? 'bg-green-400' : 'bg-yellow-400'} animate-pulse`}></div>
          <span className="text-sm font-medium">{systemStatus.integrity.toFixed(1)}%</span>
        </div>
      </motion.div>

      {/* Main Content - Scrollable with Expand Effect */}
      <div className="pt-20 pb-32 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto space-y-8">
          {/* Hero Section - Minimal, No User Box */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center py-12"
          >
            <motion.h1
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="text-4xl sm:text-5xl lg:text-6xl font-bold mb-4 bg-gradient-to-r from-cyan-400 via-blue-400 to-purple-400 bg-clip-text text-transparent"
            >
              BlueDXP Platform
            </motion.h1>
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
              className="text-lg sm:text-xl text-[#9ca3af] max-w-2xl mx-auto"
            >
              Enterprise Intelligence Operating System
            </motion.p>
          </motion.div>

          {/* Major Modules - Expandable Cards */}
          <div className="space-y-6">
            {majorModules.map((module, index) => {
              const isExpanded = expandedModule === module.id
              const colors = colorMap[module.color] || colorMap.cyan

              return (
                  <motion.div
                    key={module.id}
                    id={`module-${module.id}`}
                    initial={{ opacity: 0, y: 30 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.1 }}
                    className="relative"
                  >
                  {/* Main Module Card */}
                  <motion.div
                    onClick={() => toggleModule(module.id)}
                    className={`relative overflow-hidden rounded-2xl border-2 backdrop-blur-xl cursor-pointer transition-all ${
                      isExpanded
                        ? `${colors.bg} ${colors.border} shadow-2xl ${colors.glow}`
                        : 'bg-white/5 border-white/10 hover:border-white/20'
                    }`}
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    {/* Glow Effect */}
                    {isExpanded && (
                      <motion.div
                        className={`absolute inset-0 bg-gradient-to-br ${colors.glow.replace('shadow-', 'from-').replace('/50', '/10')} to-transparent blur-2xl`}
                        animate={{ opacity: [0.3, 0.6, 0.3] }}
                        transition={{ duration: 3, repeat: Infinity }}
                      />
                    )}

                    <div className="relative p-6 sm:p-8">
                      <div className="flex items-center justify-between">
                        {/* 3D Icon */}
                        <motion.div
                          className={`w-16 h-16 sm:w-20 sm:h-20 rounded-2xl bg-gradient-to-br ${module.gradient} border ${module.borderColor} flex items-center justify-center shadow-lg relative`}
                          whileHover={{ 
                            rotateY: 15, 
                            rotateX: 5, 
                            scale: 1.1,
                            z: 50
                          }}
                          transition={{ type: 'spring', stiffness: 300, damping: 20 }}
                          style={{ perspective: '1000px', transformStyle: 'preserve-3d' }}
                        >
                          <i className={`${module.icon} ${module.iconColor} text-3xl sm:text-4xl`}></i>
                          {/* 3D Shadow */}
                          <div className={`absolute inset-0 rounded-2xl ${colors.glow.replace('shadow-', 'bg-').replace('/50', '/20')} blur-xl -z-10`}></div>
                        </motion.div>

                        {/* Module Info */}
                        <div className="flex-1 ml-6 min-w-0">
                          <h2 className={`text-2xl sm:text-3xl font-bold mb-2 ${isExpanded ? colors.text : 'text-white'}`}>
                            {module.name}
                          </h2>
                          <p className={`text-sm sm:text-base ${isExpanded ? colors.text + '/80' : 'text-[#9ca3af]'}`}>
                            {module.description}
                          </p>
                        </div>

                        {/* Expand/Collapse Icon */}
                        <motion.div
                          animate={{ rotate: isExpanded ? 180 : 0 }}
                          className={`${module.iconColor} text-2xl`}
                        >
                          <i className="ri-arrow-down-s-line"></i>
                        </motion.div>
                      </div>

                      {/* Sub-Modules - Expandable */}
                      <AnimatePresence>
                        {isExpanded && (
                          <motion.div
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: 'auto', opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            transition={{ duration: 0.3 }}
                            className="mt-6 pt-6 border-t border-white/10 overflow-hidden"
                          >
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                              {module.subModules.map((subModule, subIndex) => (
                                <motion.div
                                  key={subModule.name}
                                  initial={{ opacity: 0, y: 20 }}
                                  animate={{ opacity: 1, y: 0 }}
                                  transition={{ delay: subIndex * 0.05 }}
                                  whileHover={{ scale: 1.05, y: -4 }}
                                >
                                  <Link
                                    href={subModule.href}
                                    className="block p-4 bg-white/5 border border-white/10 rounded-xl hover:border-cyan-500/50 hover:bg-white/10 transition-all group"
                                  >
                                    <div className={`w-10 h-10 rounded-lg bg-gradient-to-br ${module.gradient} border ${module.borderColor} flex items-center justify-center mb-3 group-hover:scale-110 transition-transform`}>
                                      <i className={`${subModule.icon} ${module.iconColor} text-lg`}></i>
                                    </div>
                                    <h3 className="text-sm font-semibold text-white mb-1">{subModule.name}</h3>
                                    <p className="text-xs text-[#9ca3af] line-clamp-2">{subModule.description}</p>
                                  </Link>
                                </motion.div>
                              ))}
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  </motion.div>
                </motion.div>
              )
            })}
          </div>
        </div>
      </div>

      {/* Floating 3D Navigation Menu - Right Side (Like Showcase) */}
      <FloatingModuleNavigation 
        modules={majorModules}
        expandedModule={expandedModule}
        onModuleClick={(moduleId) => {
          const module = majorModules.find(m => m.id === moduleId)
          if (module) {
            toggleModule(moduleId)
            // Scroll to module
            setTimeout(() => {
              const element = document.getElementById(`module-${moduleId}`)
              if (element) {
                element.scrollIntoView({ behavior: 'smooth', block: 'center' })
              }
            }, 100)
          }
        }}
      />

      {/* Global Command Palette */}
      <GlobalCommandPalette
        isOpen={commandPaletteOpen}
        onClose={() => setCommandPaletteOpen(false)}
      />
    </div>
  )
}

