interface QuantumHolographicWidgetProps {
  id: string;
  title: string;
  children: React.ReactNode;
  icon?: React.ReactNode;
  accentColor?: string; // e.g. #06b6d4
  isEditMode?: boolean;
}

export const QuantumHolographicWidget: React.FC<QuantumHolographicWidgetProps> = ({
