  // Export functionality
  const handleExport = useCallback(async (format: 'csv' | 'pdf' = 'csv') => {
    if (!warehouseId) return

    setIsExporting(true)
    try {
      if (format === 'csv') {
        // Export current layer data as CSV
        let data: any[] = []
        let filename = 'warehouse-dashboard'

        switch (currentLayer) {
          case 'orders':
            data = filteredOrders.map(o => ({
              'Order Number': o.orderNumber,
              'Customer': o.customer,
              'Status': o.status,
              'Priority': o.priority,
              'Items': o.items,
              'Value': o.value,
              'Created': o.createdAt.toISOString(),
              'Due Date': o.dueDate.toISOString(),
            }))
            filename = 'warehouse-orders'
            break
          case 'inventory':
            data = filteredInventory.map(i => ({
              'SKU': i.sku,
              'Name': i.name,
              'Category': i.category,
              'Quantity': i.quantity,
              'Available': i.availableQuantity,
              'Location': i.location,
              'Status': i.status,
              'Value': i.value,
            }))
            filename = 'warehouse-inventory'
            break
          case 'tasks':
            data = filteredTasks.map(t => ({
              'Task ID': t.id,
              'Type': t.type,
              'Status': t.status,
              'Priority': t.priority,
              'Location': t.location,
              'Items': t.items,
              'Worker': t.assignedWorker || 'Unassigned',
              'Created': t.createdAt.toISOString(),
              'Due Date': t.dueDate.toISOString(),
            }))
            filename = 'warehouse-tasks'
            break
        }

        if (data.length === 0) {
          alert('No data to export')
          return
        }

        // Convert to CSV
        const headers = Object.keys(data[0])
        const csvContent = [
          headers.join(','),
          ...data.map(row => headers.map(header => {
            const value = row[header]
            return typeof value === 'string' ? `"${value.replace(/"/g, '""')}"` : value
          }).join(','))
        ].join('\n')

        // Download
        const blob = new Blob([csvContent], { type: 'text/csv' })
        const url = window.URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = `${filename}-${new Date().toISOString().split('T')[0]}.csv`
        document.body.appendChild(a)
        a.click()
        document.body.removeChild(a)
        window.URL.revokeObjectURL(url)
      } else {
        // PDF export using HTML print
        const { exportToPDF } = await import('@/utils/exportUtils')
        await exportToPDF({
          data,
          filename,
          title: `Warehouse ${currentLayer} Report`,
          description: `Export of ${data.length} ${currentLayer} records`,
          columns: Object.keys(data[0] || {}).map(key => ({
            key,
            label: key.split(/(?=[A-Z])/).join(' ').replace(/^\w/, c => c.toUpperCase()),
            visible: true,
          })),
          companyName: 'Warehouse Management System',
          includeTimestamp: true,
        })
      }
    } catch (error) {
      console.error('Export error:', error)
      alert('Failed to export data')
