            key={currentLayer}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
            transition={{ duration: 0.3 }}
          >
            {renderCurrentLayer()}
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  )
}

