const UltimateConsolidatedDashboard: React.FC<UltimateConsolidatedDashboardProps> = ({
  tenantId = 'default',
  userId = 'anonymous',
  userRole = 'user',
  enabledModules = [],
  initialLayout = 'executive-overview',
  customizations = {},
  onLayoutChange,
  onWidgetAction
}) => {
  // Use system theme preference - match application theme
  const [isDark, setIsDark] = useState(true); // Default to dark to match app

  // 🎯 STATE MANAGEMENT
  const [currentLayout, setCurrentLayout] = useState<DashboardLayout | null>(null);
  const [customWidgets, setCustomWidgets] = useState<Widget[]>([]);
  const [filters, setFilters] = useState<DashboardFilters>({
    category: 'all',
    module: 'all',
    accessLevel: 'all',
    searchQuery: '',
    showHidden: false,
    dateRange: null
  });
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedWidget, setSelectedWidget] = useState<Widget | null>(null);
  const [showWidgetLibrary, setShowWidgetLibrary] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [currentTime, setCurrentTime] = useState<Date>(new Date());
  const [widgetData, setWidgetData] = useState<Record<string, any>>({});
  const [cyberVision, setCyberVision] = useState(true); // New premium mode

  // 🚀 INITIALIZATION
  useEffect(() => {
    loadDashboardLayout(initialLayout);
  }, [initialLayout, userRole, enabledModules]);

  // Real-time clock update
  useEffect(() => {
    const clockInterval = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    return () => clearInterval(clockInterval);
  }, []);

  // Real-time widget data updates - only if layout is loaded
  useEffect(() => {
    if (!currentLayout) return;

    const dataInterval = setInterval(() => {
      refreshAllWidgets();
    }, 30000); // Every 30 seconds

    return () => {
      clearInterval(dataInterval);
    };
  }, [currentLayout?.id]); // Only depend on layout ID, not the whole object

  const loadDashboardLayout = useCallback(async (layoutId: string) => {
    try {
      const layout = dashboardLayouts.find(l => 
        l.id === layoutId && 
        (l.userRole.includes(userRole) || l.userRole.includes('all')) &&
        (enabledModules.length === 0 || l.modules.some(m => enabledModules.includes(m)))
      ) || dashboardLayouts.find(l => l.isDefault);

      if (layout) {
        // Ensure all widgets have unique IDs and proper data
        const processedWidgets = layout.widgets
          .filter(widget => hasWidgetAccess(widget, userRole, enabledModules))
          .map((widget, index) => ({
            ...widget,
            id: widget.id || `${layout.id}-widget-${index}-${Date.now()}`,
            lastUpdated: new Date()
          }));

        setCurrentLayout({
          ...layout,
          widgets: processedWidgets
        });

        // Load initial widget data for all widgets
        const dataPromises = processedWidgets.map(async (widget) => {
          try {
            // For IoT widgets, fetch real data from IoT manager
            if (widget.module === 'iot' && widget.id.includes('iot')) {
              const devices = await iotManager.getDevices();
              const onlineCount = devices.filter(d => d.status.operational === 'online').length;
              const offlineCount = devices.filter(d => d.status.operational === 'offline').length;
              const maintenanceCount = devices.filter(d => d.status.operational === 'maintenance').length;

              if (widget.id.includes('devices-overview')) {
                return {
                  items: [
                    { label: 'Online Devices', value: onlineCount, status: 'operational' },
                    { label: 'Offline Devices', value: offlineCount, status: 'error' },
                    { label: 'In Maintenance', value: maintenanceCount, status: 'warning' }
                  ]
                };
              } else if (widget.id.includes('network-health')) {
                const analytics = await iotManager.getAnalytics({
                  start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
                  end: new Date()
                });
                return {
                  metrics: [
                    { label: 'Network Uptime', value: analytics.performance.averageUptime, max: 100 },
                    { label: 'Average Latency', value: Math.min(analytics.performance.networkLatency, 100), max: 100 },
                    { label: 'Data Throughput', value: Math.min(analytics.performance.dataTransmission / 10, 100), max: 100 }
                  ]
                };
              }
            }

            // For other widgets, use dashboard manager or widget's default data
            const data = await dashboardManager.getWidgetData(widget.id);
            return data || widget.data;
          } catch (error) {
            console.warn(`Failed to load data for widget ${widget.id}:`, error);
            return widget.data; // Fallback to default data
          }
        });

        const loadedData = await Promise.all(dataPromises);
        const dataMap: Record<string, any> = {};
        processedWidgets.forEach((widget, index) => {
          dataMap[widget.id] = loadedData[index];
        });

        setWidgetData(dataMap);
      }
    } catch (error) {
      console.error('Failed to load dashboard layout:', error);
    }
  }, [userRole, enabledModules]);

  const refreshAllWidgets = useCallback(async () => {
    if (!currentLayout) return;

    try {
      // Combine layout widgets and custom widgets
      const allWidgets = [...currentLayout.widgets, ...customWidgets];

      const dataPromises = allWidgets.map(async (widget) => {
        try {
          // For IoT widgets, fetch real data
          if (widget.module === 'iot' && widget.id.includes('iot')) {
            const devices = await iotManager.getDevices();
            const onlineCount = devices.filter(d => d.status.operational === 'online').length;
            const offlineCount = devices.filter(d => d.status.operational === 'offline').length;
            const maintenanceCount = devices.filter(d => d.status.operational === 'maintenance').length;

            if (widget.id.includes('devices-overview')) {
              return {
                items: [
                  { label: 'Online Devices', value: onlineCount, status: 'operational' },
                  { label: 'Offline Devices', value: offlineCount, status: 'error' },
                  { label: 'In Maintenance', value: maintenanceCount, status: 'warning' }
                ]
              };
            } else if (widget.id.includes('network-health')) {
              const analytics = await iotManager.getAnalytics({
                start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
                end: new Date()
              });
              return {
                metrics: [
                  { label: 'Network Uptime', value: analytics.performance.averageUptime, max: 100 },
                  { label: 'Average Latency', value: Math.min(analytics.performance.networkLatency, 100), max: 100 },
                  { label: 'Data Throughput', value: Math.min(analytics.performance.dataTransmission / 10, 100), max: 100 }
                ]
              };
            }
          }

          // For other widgets, use dashboard manager or widget's default data
          const data = await dashboardManager.getWidgetData(widget.id);
          return data || widget.data || {};
        } catch (error) {
          console.warn(`Failed to refresh widget ${widget.id}:`, error);
          return widget.data || {};
        }
      });

      const loadedData = await Promise.all(dataPromises);
      const dataMap: Record<string, any> = {};

      allWidgets.forEach((widget, index) => {
        dataMap[widget.id] = loadedData[index];
      });

      setWidgetData(prev => ({ ...prev, ...dataMap }));
    } catch (error) {
      console.error('Error refreshing widgets:', error);
    }
  }, [currentLayout?.id, customWidgets.length]); // Only depend on layout ID and widget count, not the whole objects

  const handleRefresh = async () => {
    setRefreshing(true);
    await refreshAllWidgets();
    setRefreshing(false);
  };

  // 🔐 ACCESS CONTROL
  const hasWidgetAccess = useCallback((widget: Widget, role: string, modules: string[]): boolean => {
    if (widget.accessLevel === 'all') return true;
    if (widget.accessLevel === 'admin' && ['admin', 'super_admin'].includes(role)) return true;
    if (widget.accessLevel === 'enterprise' && ['enterprise', 'admin', 'super_admin'].includes(role)) return true;
    if (widget.accessLevel === 'super_admin' && role === 'super_admin') return true;

    if (modules.length > 0 && !modules.includes(widget.module) && !modules.includes('all')) return false;

    return true;
  }, []);

  // 🎨 WIDGET RENDERING
  const renderWidget = useCallback((widget: Widget) => {
    const widgetDataValue = widgetData[widget.id] || widget.data;
    const isSelected = selectedWidget?.id === widget.id;

    // Check if we should use the Mind-Blowing Holographic style
    if (widgetDataValue?.style === 'holographic' || widget.id.includes('quantum') || widget.id.includes('cyber')) {
      return (
        <QuantumHolographicWidget
          id={widget.id}
          title={widget.title}
          icon={widget.icon}
          accentColor={widgetDataValue?.accentColor || (widget.gradient?.includes('cyan') ? '#06b6d4' : widget.gradient?.includes('purple') ? '#8b5cf6' : '#3b82f6')}
          isEditMode={isEditMode}
        >
          <div className="widget-content h-full">
            {renderWidgetContent(widget, widgetDataValue)}
          </div>
        </QuantumHolographicWidget>
      );
    }

    return (
      <PremiumWidget
        id={widget.id}
        title={widget.title}
        icon={widget.icon}
        gradient={widget.gradient}
        isEditMode={isEditMode}
        isSelected={isSelected}
        isRemovable={widget.isRemovable}
        lastUpdated={widget.lastUpdated}
        config={widget.config}
        onEdit={() => onWidgetAction?.('edit', widget)}
        onRemove={() => {
          const isCustomWidget = customWidgets.some(w => w.id === widget.id);
          if (isCustomWidget) {
            setCustomWidgets(prev => prev.filter(w => w.id !== widget.id));
          } else {
            onWidgetAction?.('remove', widget);
          }
        }}
        onClick={() => setSelectedWidget(widget)}
      >
        <div className="widget-content h-full">
          {renderWidgetContent(widget, widgetDataValue)}
        </div>
      </PremiumWidget>
    );
  }, [isEditMode, selectedWidget?.id, onWidgetAction, widgetData, customWidgets]);

  // 🎯 WIDGET CONTENT RENDERING
  const renderWidgetContent = (widget: Widget, data: any) => {
    switch (widget.type) {
      case 'metric':
        return (
          <div className="text-center">
            <div className="text-4xl font-bold mb-2">
              {typeof data.value === 'number' 
                ? data.value.toLocaleString() 
                : data.value}
            </div>
            {data.trend && (
              <div className={`text-sm flex items-center justify-center space-x-1 ${
                data.trend.startsWith('+') ? 'text-green-500' : 'text-red-500'
              }`}>
                {data.trend.startsWith('+') ? 
                  <FiTrendingUp className="w-4 h-4" /> : 
                  <FiTrendingDown className="w-4 h-4" />
                }
                <span>{data.trend} {data.period}</span>
              </div>
            )}
          </div>
        );

      case 'chart':
        return renderChartWidget(widget, data);

      case 'progress':
        if (data.style === 'liquid') {
          return (
            <div className="space-y-2">
              {data.metrics?.map((metric: any, index: number) => (
                <LiquidMetric
                  key={index}
                  label={metric.label}
                  value={metric.value}
                  max={metric.max}
                  color={metric.color}
                />
              ))}
            </div>
          );
        }
        return (
          <div className="space-y-3">
            {data.metrics?.map((metric: any, index: number) => (
              <div key={index}>
                <div className="flex justify-between text-sm mb-1">
                  <span>{metric.label}</span>
                  <span>{metric.value}%</span>
                </div>
                <div className="w-full bg-gray-700 rounded-full h-2">
                  <motion.div 
                    initial={{ width: 0 }}
                    animate={{ width: `${(metric.value / metric.max) * 100}%` }}
                    transition={{ duration: 1, delay: index * 0.1 }}
                    className="bg-gradient-to-r from-cyan-500 to-blue-600 h-2 rounded-full"
                  />
                </div>
              </div>
            ))}
          </div>
        );

      case 'status':
        return (
          <div className="space-y-2">
            {data.items?.map((item: any, index: number) => (
              <div key={index} className="flex items-center justify-between p-2 rounded bg-gray-700/50">
                <span className="font-medium text-white">{item.label}</span>
                <div className="flex items-center space-x-2">
                  <span className="text-lg font-bold text-white">{item.value}</span>
                  <span className={`w-2 h-2 rounded-full ${
                    item.status === 'operational' || item.status === 'success' ? 'bg-green-500' :
                    item.status === 'warning' ? 'bg-yellow-500' :
                    'bg-red-500'
                  }`} />
                </div>
              </div>
            ))}
          </div>
        );

      case 'ai-insight':
        return (
          <div className="space-y-4 relative">
            {/* AI Background Glow */}
            <div className="absolute -inset-4 bg-blue-500/5 blur-3xl rounded-full pointer-events-none animate-pulse-slow" />

            {data.insights?.map((insight: any, index: number) => (
              <motion.div 
                key={index}
                initial={{ opacity: 0, x: -20, scale: 0.95 }}
                animate={{ opacity: 1, x: 0, scale: 1 }}
                transition={{ delay: index * 0.1, type: 'spring' }}
                whileHover={{ scale: 1.02, x: 4 }}
                className={`relative p-4 rounded-2xl border backdrop-blur-md transition-all duration-300 ${
                  insight.priority === 'high' ? 'border-red-500/30 bg-red-500/5 shadow-[0_0_20px_rgba(239,68,68,0.1)]' :
                  insight.priority === 'medium' ? 'border-yellow-500/30 bg-yellow-500/5 shadow-[0_0_20px_rgba(234,179,8,0.1)]' :
                  'border-cyan-500/30 bg-cyan-500/5 shadow-[0_0_20px_rgba(6,182,212,0.1)]'
                }`}
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full animate-ping ${
                      insight.type === 'prediction' ? 'bg-blue-400' :
                      insight.type === 'optimization' ? 'bg-purple-400' :
                      'bg-orange-400'
                    }`} />
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                      insight.type === 'prediction' ? 'bg-blue-500/20 text-blue-400' :
                      insight.type === 'optimization' ? 'bg-purple-500/20 text-purple-400' :
                      'bg-orange-500/20 text-orange-400'
                    }`}>
                      {insight.type}
                    </span>
                  </div>
                  <span className="text-[10px] font-mono text-slate-500 bg-slate-800/50 px-2 py-0.5 rounded-full">
                    {Math.round(insight.confidence * 100)}% CONFIDENCE
                  </span>
                </div>
                <p className="text-sm text-slate-200 leading-relaxed font-medium">
                  {insight.text}
                </p>

                <div className="mt-4 flex items-center justify-between">
                  <div className="flex items-center gap-1.5 text-[10px] font-bold text-cyan-400/70 uppercase tracking-widest">
                    <FiZap className="w-3 h-3 animate-pulse" />
                    <span>Neural Engine Insight</span>
                  </div>
                  <motion.button
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                    className="text-[10px] text-slate-400 hover:text-white transition-colors underline decoration-dotted"
                  >
                    Details
                  </motion.button>
                </div>
              </motion.div>
            ))}
          </div>
        );

      case 'list':
        return (
          <div className="space-y-2">
            {data.items?.map((item: any, index: number) => (
              <div key={index} className="flex items-center justify-between p-2 rounded bg-gray-700/50">
                <span className="font-medium text-white">{item.title || item.name || item.label}</span>
                <span className={`px-2 py-1 rounded text-xs ${
                  item.severity === 'high' || item.status === 'error' ? 'bg-red-900 text-red-300' :
                  item.severity === 'medium' || item.status === 'warning' ? 'bg-yellow-900 text-yellow-300' :
                  'bg-green-900 text-green-300'
                }`}>
                  {item.severity || item.status || item.time}
                </span>
              </div>
            ))}
          </div>
        );

      case 'custom':
        if (data.visualization) {
          return (
            <div className="h-full w-full min-h-[200px] relative">
              <AdvancedVisualization 
                type={data.visualization} 
                data={data}
                width={400} 
                height={200}
              />
              <div className="absolute bottom-2 left-2 flex items-center gap-2 text-[10px] text-cyan-400 font-bold uppercase tracking-widest">
                <span className="w-2 h-2 rounded-full bg-cyan-400 animate-ping" />
                Live Engine Rendering
              </div>
            </div>
          );
        }
        return <div className="text-gray-400">Custom widget content</div>;

      default:
        return (
          <div className="h-24 flex items-center justify-center text-gray-400">
            <span className="text-gray-400">Widget content</span>
          </div>
        );
    }
  };

  // 📊 CHART WIDGET RENDERING
  const renderChartWidget = (widget: Widget, data: any) => {
    if (!data || !data.type) {
      return <div className="text-gray-400">No chart data</div>;
    }

    const chartHeight = widget.size === 'xl' ? 300 : widget.size === 'lg' ? 250 : 200;

    switch (data.type) {
      case 'line':
        return (
          <ResponsiveContainer width="100%" height={chartHeight}>
            <LineChart data={data.datasets[0].data.map((val: number, idx: number) => ({
              name: data.labels[idx],
              value: val
            }))}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis dataKey="name" stroke="#9ca3af" />
              <YAxis stroke="#9ca3af" />
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: '#1f2937',
                  border: '1px solid #374151',
                  borderRadius: '8px',
                  color: '#ffffff'
                }}
              />
              <Line 
                type="monotone" 
                dataKey="value" 
                stroke={data.datasets[0].borderColor || '#06b6d4'} 
                strokeWidth={2}
                dot={{ fill: data.datasets[0].borderColor || '#06b6d4' }}
              />
            </LineChart>
          </ResponsiveContainer>
        );

      case 'doughnut':
      case 'pie':
        if (!data.datasets || !data.datasets[0] || !data.labels) {
          return <div className="text-gray-400 text-center py-8">No chart data available</div>;
        }

        const pieData = data.datasets[0].data.map((val: number, idx: number) => ({
          name: data.labels[idx] || `Item ${idx + 1}`,
          value: val
        }));
        const COLORS = data.datasets[0].backgroundColor || ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

        return (
          <ResponsiveContainer width="100%" height={chartHeight}>
            <PieChart>
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                outerRadius={Math.min(chartHeight / 3, 80)}
                fill="#8884d8"
                dataKey="value"
              >
                {pieData.map((entry: any, index: number) => (
                  <Cell key={`cell-${index}`} fill={Array.isArray(COLORS) ? COLORS[index % COLORS.length] : COLORS} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        );

      case 'radar':
        const radarData = data.datasets[0].data.map((val: number, idx: number) => ({
          subject: data.labels[idx],
          value: val,
          fullMark: 100
        }));

        return (
          <ResponsiveContainer width="100%" height={chartHeight}>
            <RadarChart data={radarData}>
              <PolarGrid stroke="#374151" />
              <PolarAngleAxis 
                dataKey="subject" 
                tick={{ fill: '#9ca3af' }}
              />
              <PolarRadiusAxis 
                angle={90} 
                domain={[0, 100]}
                tick={{ fill: '#9ca3af' }}
              />
              <Radar
                name="Performance"
                dataKey="value"
                stroke={data.datasets[0].borderColor || '#06b6d4'}
                fill={data.datasets[0].backgroundColor || 'rgba(6, 182, 212, 0.2)'}
                fillOpacity={0.6}
              />
              <Tooltip />
            </RadarChart>
          </ResponsiveContainer>
        );

      default:
        return <div className="text-gray-400 text-center py-8">Chart type not supported</div>;
    }
  };

  // 📊 FILTERED WIDGETS
  const filteredWidgets = useMemo(() => {
    if (!currentLayout) return [];

    const allWidgets = [...currentLayout.widgets, ...customWidgets];

    return allWidgets.filter(widget => {
      if (filters.category !== 'all' && widget.category !== filters.category) return false;
      if (filters.module !== 'all' && widget.module !== filters.module) return false;
      if (filters.searchQuery && !widget.title.toLowerCase().includes(filters.searchQuery.toLowerCase())) return false;
      return true;
    });
  }, [currentLayout, filters, customWidgets]);

  if (!currentLayout) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <FiRefreshCw className="w-8 h-8 animate-spin mx-auto mb-4 text-blue-500" />
          <p className="text-lg font-medium">Loading Dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen transition-all duration-500 bg-gray-900 text-white`}>
      {/* 🎨 HEADER WITH GLASSMORPHISM */}
      <div className={`sticky top-0 z-50 backdrop-blur-xl border-b border-gray-700/50 shadow-lg bg-gray-900/90`}>
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <motion.div 
                whileHover={{ rotate: 360 }}
                transition={{ duration: 0.5 }}
                className="relative w-12 h-12 bg-gradient-to-r from-cyan-500 to-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-cyan-500/20"
              >
                <FiGrid className="w-6 h-6 text-white" />
                <div className="absolute inset-0 bg-gradient-to-r from-cyan-500 to-blue-600 rounded-xl blur opacity-30"></div>
              </motion.div>
              <div>
                <h1 className="text-2xl font-bold bg-gradient-to-r from-cyan-400 to-blue-500 bg-clip-text text-transparent">
                  {currentLayout.name}
                </h1>
                <p className="text-sm text-gray-400">
                  {currentLayout.description} • {currentTime.toLocaleTimeString()}
                </p>
              </div>
            </div>

            <div className="flex items-center space-x-3">
              <button
                onClick={handleRefresh}
                disabled={refreshing}
                className="px-4 py-2 rounded-lg transition-all duration-300 backdrop-blur-sm border border-gray-700/50 bg-gray-800/50 text-gray-300 hover:bg-gray-700/50 hover:scale-105"
              >
                <FiRefreshCw className={`w-4 h-4 mr-2 inline ${refreshing ? 'animate-spin' : ''}`} />
                Refresh
              </button>

              <button
                onClick={() => setIsEditMode(!isEditMode)}
                className={`px-4 py-2 rounded-lg transition-all duration-300 backdrop-blur-sm border ${
                  isEditMode 
                    ? 'bg-gradient-to-r from-cyan-500 to-blue-600 text-white border-cyan-400 shadow-lg scale-105' 
                    : 'bg-gray-800/50 text-gray-300 hover:bg-gray-700/50 border-gray-700/50 hover:scale-105'
                }`}
              >
                <FiEdit className="w-4 h-4 mr-2 inline" />
                {isEditMode ? 'Exit Edit' : 'Edit Mode'}
              </button>

              <button
                onClick={() => setShowWidgetLibrary(!showWidgetLibrary)}
                className="px-4 py-2 rounded-lg transition-all duration-300 backdrop-blur-sm border border-gray-700/50 bg-gray-800/50 text-gray-300 hover:bg-gray-700/50 hover:scale-105"
              >
                <FiPlus className="w-4 h-4 mr-2 inline" />
                Add Widget
              </button>

              <button
                onClick={() => setCyberVision(!cyberVision)}
                className={`px-4 py-2 rounded-lg transition-all duration-300 backdrop-blur-sm border ${
                  cyberVision 
                    ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/50 shadow-[0_0_15px_rgba(6,182,212,0.3)]' 
                    : 'bg-gray-800/50 text-gray-500 border-gray-700/50'
                }`}
              >
                <FiZap className={`w-4 h-4 mr-2 inline ${cyberVision ? 'animate-pulse' : ''}`} />
                CyberVision {cyberVision ? 'ON' : 'OFF'}
              </button>

              <button
                onClick={() => setIsDark(!isDark)}
                className="p-2 rounded-lg transition-all duration-300 backdrop-blur-sm border border-gray-700/50 bg-gray-800/50 text-gray-300 hover:bg-gray-700/50 hover:scale-105"
              >
                {isDark ? <FiSun className="w-4 h-4" /> : <FiMoon className="w-4 h-4" />}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* 📊 ENHANCED DASHBOARD GRID */}
      <div className="max-w-7xl mx-auto px-6 py-8 relative z-10">
        <div className="grid grid-cols-12 gap-6 auto-rows-min relative z-20" style={{ gridAutoRows: 'minmax(200px, auto)' }}>
          <AnimatePresence mode="popLayout">
            {filteredWidgets.map((widget) => {
              // Calculate grid position
              const gridColumnStart = widget.position.x + 1;
              const gridColumnEnd = widget.position.x + widget.position.w + 1;
              const gridRowStart = widget.position.y + 1;
              const gridRowEnd = widget.position.y + widget.position.h + 1;

              return (
                <div
                  key={widget.id}
                  style={{
                    gridColumn: `${gridColumnStart} / ${gridColumnEnd}`,
                    gridRow: `${gridRowStart} / ${gridRowEnd}`
                  }}
                >
                  {renderWidget(widget)}
                </div>
              );
            })}
          </AnimatePresence>
        </div>

        {/* 🚫 ENHANCED EMPTY STATE */}
        {filteredWidgets.length === 0 && (
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center py-16 col-span-12"
          >
            <div className="w-24 h-24 mx-auto mb-6 rounded-full flex items-center justify-center bg-gray-800/50 backdrop-blur-xl border border-gray-700/50">
              <FiGrid className="w-12 h-12 text-gray-400" />
            </div>
            <h3 className="text-2xl font-bold mb-2 bg-gradient-to-r from-cyan-400 to-blue-500 bg-clip-text text-transparent">
              No Widgets Available
            </h3>
            <p className="text-gray-400 mb-6 text-lg">
              Add widgets to customize your dashboard experience
            </p>
            <button
              onClick={() => setShowWidgetLibrary(true)}
              className="px-8 py-4 bg-gradient-to-r from-cyan-500 to-blue-600 text-white rounded-xl hover:scale-105 transition-all duration-300 shadow-lg hover:shadow-xl font-semibold"
            >
              Browse Widget Library
            </button>
          </motion.div>
        )}
      </div>

      {/* 🎨 WIDGET LIBRARY MODAL */}
      <AnimatePresence>
        {showWidgetLibrary && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm"
            onClick={() => setShowWidgetLibrary(false)}
            style={{ zIndex: 9999 }}
          >
            <motion.div
              initial={{ scale: 0.9, y: 20, opacity: 0 }}
              animate={{ scale: 1, y: 0, opacity: 1 }}
              exit={{ scale: 0.9, y: 20, opacity: 0 }}
              transition={{ type: "spring", stiffness: 300, damping: 30 }}
              className={`w-full max-w-4xl max-h-[90vh] rounded-2xl overflow-hidden backdrop-blur-xl border shadow-2xl ${
                isDark 
                  ? 'bg-gray-900/95 border-gray-700/50 text-white' 
                  : 'bg-white/95 border-gray-200/50 text-gray-900'
              }`}
              onClick={(e) => e.stopPropagation()}
              style={{ zIndex: 10000 }}
            >
              <div className={`p-6 border-b ${isDark ? 'border-gray-700/50' : 'border-gray-200/50'}`}>
                <div className="flex items-center justify-between">
                  <h3 className="text-2xl font-bold bg-gradient-to-r from-cyan-400 to-blue-500 bg-clip-text text-transparent">
                    Widget Library
                  </h3>
                  <button
                    onClick={() => setShowWidgetLibrary(false)}
                    className="p-2 rounded-lg transition-all duration-300 hover:scale-110 hover:bg-gray-700/50 text-gray-400 hover:text-white"
                  >
                    <FiX className="w-5 h-5" />
                  </button>
                </div>
              </div>

              <div className="p-6 max-h-96 overflow-y-auto">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {widgetLibrary.map(widget => (
                    <motion.div
                      key={widget.id}
                      whileHover={{ scale: 1.02, y: -2 }}
                      whileTap={{ scale: 0.98 }}
                      className="p-4 rounded-xl border border-gray-700/50 cursor-pointer transition-all duration-300 backdrop-blur-sm hover:shadow-xl bg-gray-800/40 hover:bg-gray-800/60 text-white"
                      onClick={(e) => {
                        e.preventDefault();
                        e.stopPropagation();

                        // Close modal immediately
                        setShowWidgetLibrary(false);

                        try {
                          const allWidgets = [...(currentLayout?.widgets || []), ...customWidgets];

                          // Simple position calculation - place at end of grid
                          let newX = 0;
                          let newY = 0;

                          if (allWidgets.length > 0) {
                            // Find bottom-most position
                            const maxY = Math.max(...allWidgets.map(w => w.position.y + w.position.h), 0);
                            newY = maxY;

                            // Check if there's space on the last row
                            const lastRowWidgets = allWidgets.filter(w => 
                              w.position.y <= maxY && w.position.y + w.position.h > maxY
                            );

                            if (lastRowWidgets.length > 0) {
                              const maxX = Math.max(...lastRowWidgets.map(w => w.position.x + w.position.w), 0);
                              if (maxX + widget.position.w <= 12) {
                                newX = maxX; // Place on same row
                              } else {
                                newX = 0; // New row
                              }
                            }
                          }

                          const widgetId = `${widget.id}-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
                          const newWidget: Widget = { 
                            ...widget, 
                            id: widgetId,
                            position: { ...widget.position, x: newX, y: newY },
                            lastUpdated: new Date()
                          };

                          // Initialize widget data
                          const widgetDataValue = widget.data || {};

                          // Update state - React will batch these
                          setCustomWidgets(prev => {
                            if (prev.some(w => w.id === widgetId)) {
                              return prev; // Prevent duplicates
                            }
                            return [...prev, newWidget];
                          });

                          setWidgetData(prev => {
                            if (prev[widgetId]) {
                              return prev; // Already exists
                            }
                            return { ...prev, [widgetId]: widgetDataValue };
                          });
                        } catch (error) {
                          console.error('Error adding widget:', error);
                        }
                      }}
                    >
                      <div className="flex items-center space-x-3 mb-3">
                        {widget.icon && (
                          <div className={`text-xl p-2 rounded-lg ${
                            widget.gradient 
                              ? `bg-gradient-to-r ${widget.gradient} text-white` 
                              : 'bg-gray-700 text-gray-300'
                          }`}>
                            {widget.icon}
                          </div>
                        )}
                        <h4 className="font-semibold text-lg">{widget.title}</h4>
                      </div>
                      <p className="text-sm text-gray-400 mb-2">
                        {widget.category} • {widget.module}
                      </p>
                      {widget.gradient && (
                        <div className={`w-full h-1 rounded-full bg-gradient-to-r ${widget.gradient}`} />
                      )}
                    </motion.div>
                  ))}
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

