/**
 * Control Manager UI
 * Manage controls registry (SOPs, Regulations, Iktva)
 * Integrates with existing controls registry service
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { controlsRegistry } from '@/lib/services/decision-core/controlsRegistry'
import type { Control } from '@/lib/services/decision-core/controlsRegistry'

export default function ControlManager() {
  const [controls, setControls] = useState<Control[]>([])
  const [selectedControl, setSelectedControl] = useState<Control | null>(null)
  const [isEditing, setIsEditing] = useState(false)
  const [showAddForm, setShowAddForm] = useState(false)
  const [filterType, setFilterType] = useState<string>('all')

  useEffect(() => {
    loadControls()
  }, [filterType])

  const loadControls = () => {
    const allControls = controlsRegistry.getAllControls()
    const filtered = filterType === 'all'
      ? allControls
      : allControls.filter(c => c.type === filterType)
    setControls(filtered)
  }

  const handleSave = (control: Partial<Control>) => {
    if (selectedControl) {
      // Update existing
      controlsRegistry.updateControl(selectedControl.id, control as Partial<Control>)
    } else {
      // Create new
      const newControl: Control = {
        id: `control-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
        name: control.name || '',
        type: control.type || 'CUSTOM',
        reference: control.reference || '',
        description: control.description,
        appliesToModules: control.appliesToModules || [],
        appliesToEntityTypes: control.appliesToEntityTypes || [],
        required: control.required ?? false,
        severity: control.severity || 'MEDIUM',
        isActive: control.isActive ?? true,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        ...control,
      }
      controlsRegistry.register(newControl)
    }
    loadControls()
    setSelectedControl(null)
    setIsEditing(false)
    setShowAddForm(false)
  }

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this control?')) {
      controlsRegistry.deleteControl(id)
      loadControls()
      if (selectedControl?.id === id) {
        setSelectedControl(null)
      }
    }
  }

  const controlTypes: Control['type'][] = ['SOP', 'REGULATION', 'IKTVA', 'INTERNAL_POLICY', 'CUSTOM']

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-white">Control Management</h2>
        <button
          onClick={() => {
            setShowAddForm(true)
            setSelectedControl(null)
            setIsEditing(true)
          }}
          className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors"
        >
          <i className="ri-add-line mr-2"></i>Add Control
        </button>
      </div>

      {/* Filters */}
      <div className="bg-gray-800 rounded-lg p-4 border border-gray-700">
        <div className="flex items-center gap-4">
          <label className="text-sm text-gray-400">Filter by Type:</label>
          <select
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
            className="bg-gray-700 text-white rounded-lg px-3 py-2 border border-gray-600 focus:border-blue-500 focus:outline-none"
          >
            <option value="all">All Types</option>
            {controlTypes.map(type => (
              <option key={type} value={type}>{type}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Controls List */}
        <div className="lg:col-span-1 space-y-3">
          {controls.map((control) => (
            <motion.div
              key={control.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className={`bg-gray-800 rounded-lg p-4 border-2 cursor-pointer transition-colors ${
                selectedControl?.id === control.id ? 'border-blue-500' : 'border-gray-700'
              }`}
              onClick={() => {
                setSelectedControl(control)
                setIsEditing(false)
                setShowAddForm(false)
              }}
            >
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2 py-1 rounded text-xs ${
                      control.type === 'SOP' ? 'bg-blue-500' :
                      control.type === 'REGULATION' ? 'bg-green-500' :
                      control.type === 'IKTVA' ? 'bg-purple-500' :
                      control.type === 'INTERNAL_POLICY' ? 'bg-orange-500' :
                      'bg-gray-500'
                    } text-white`}>
                      {control.type}
                    </span>
                    <span className={`px-2 py-1 rounded text-xs ${
                      control.severity === 'CRITICAL' ? 'bg-red-500' :
                      control.severity === 'HIGH' ? 'bg-orange-500' :
                      control.severity === 'MEDIUM' ? 'bg-yellow-500' :
                      'bg-gray-500'
                    } text-white`}>
                      {control.severity}
                    </span>
                    {!control.isActive && (
                      <span className="px-2 py-1 rounded text-xs bg-gray-600 text-gray-400">
                        Inactive
                      </span>
                    )}
                  </div>
                  <div className="text-white font-medium">{control.name}</div>
                  <div className="text-gray-400 text-sm mt-1">{control.reference}</div>
                  {control.description && (
                    <div className="text-gray-500 text-xs mt-1 line-clamp-2">{control.description}</div>
                  )}
                </div>
              </div>
            </motion.div>
          ))}
          {controls.length === 0 && (
            <div className="text-center py-8 text-gray-500">
              <i className="ri-shield-line text-4xl mb-2"></i>
              <p>No controls found</p>
            </div>
          )}
        </div>

        {/* Control Details/Editor */}
        <div className="lg:col-span-2">
          {(selectedControl || showAddForm) && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-gray-800 rounded-lg p-6 border border-gray-700"
            >
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-semibold text-white">
                  {showAddForm ? 'Add New Control' : isEditing ? 'Edit Control' : 'Control Details'}
                </h3>
                <div className="flex gap-2">
                  {!showAddForm && (
                    <>
                      <button
                        onClick={() => setIsEditing(!isEditing)}
                        className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors"
                      >
                        <i className={`ri-${isEditing ? 'save' : 'edit'}-line mr-2`}></i>
                        {isEditing ? 'Save' : 'Edit'}
                      </button>
                      {selectedControl && (
                        <button
                          onClick={() => handleDelete(selectedControl.id)}
                          className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors"
                        >
                          <i className="ri-delete-bin-line mr-2"></i>Delete
                        </button>
                      )}
                    </>
                  )}
                </div>
              </div>

              {isEditing || showAddForm ? (
                <ControlEditor
                  control={selectedControl || undefined}
                  onSave={handleSave}
                  onCancel={() => {
                    setIsEditing(false)
                    setShowAddForm(false)
                    setSelectedControl(null)
                  }}
                />
              ) : (
                <ControlDetails control={selectedControl!} />
              )}
            </motion.div>
          )}
        </div>
      </div>
    </div>
  )
}

function ControlDetails({ control }: { control: Control }) {
  return (
    <div className="space-y-4">
      <div>
        <label className="block text-sm text-gray-400 mb-1">Name</label>
        <div className="text-white">{control.name}</div>
      </div>
      <div>
        <label className="block text-sm text-gray-400 mb-1">Type</label>
        <div className="text-white">{control.type}</div>
      </div>
      <div>
        <label className="block text-sm text-gray-400 mb-1">Reference</label>
        <div className="text-white font-mono text-sm">{control.reference}</div>
      </div>
      {control.description && (
        <div>
          <label className="block text-sm text-gray-400 mb-1">Description</label>
          <div className="text-white">{control.description}</div>
        </div>
      )}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm text-gray-400 mb-1">Severity</label>
          <div className="text-white">{control.severity}</div>
        </div>
        <div>
          <label className="block text-sm text-gray-400 mb-1">Required</label>
          <div className="text-white">{control.required ? 'Yes' : 'No'}</div>
        </div>
      </div>
      <div>
        <label className="block text-sm text-gray-400 mb-1">Applies To Modules</label>
        <div className="text-white">
          {control.appliesToModules.length > 0 ? control.appliesToModules.join(', ') : 'All modules'}
        </div>
      </div>
      <div>
        <label className="block text-sm text-gray-400 mb-1">Applies To Entity Types</label>
        <div className="text-white">
          {control.appliesToEntityTypes.length > 0 ? control.appliesToEntityTypes.join(', ') : 'All entity types'}
        </div>
      </div>
      {control.iktvaTag && (
        <div>
          <label className="block text-sm text-gray-400 mb-1">Iktva Tag</label>
          <div className="text-white">{control.iktvaTag}</div>
        </div>
      )}
      {control.saudiRegulation && (
        <div>
          <label className="block text-sm text-gray-400 mb-1">Saudi Regulation</label>
          <div className="text-white">
            {control.saudiRegulation.authority} - {control.saudiRegulation.regulationCode}
          </div>
        </div>
      )}
    </div>
  )
}

function ControlEditor({
  control,
  onSave,
  onCancel,
}: {
  control?: Control
  onSave: (control: Partial<Control>) => void
  onCancel: () => void
}) {
  const [formData, setFormData] = useState<Partial<Control>>({
    name: control?.name || '',
    type: control?.type || 'CUSTOM',
    reference: control?.reference || '',
    description: control?.description || '',
    appliesToModules: control?.appliesToModules || [],
    appliesToEntityTypes: control?.appliesToEntityTypes || [],
    required: control?.required ?? false,
    severity: control?.severity || 'MEDIUM',
    isActive: control?.isActive ?? true,
  })

  return (
    <div className="space-y-4">
      <div>
        <label className="block text-sm text-gray-400 mb-2">Name *</label>
        <input
          type="text"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          className="w-full bg-gray-700 text-white rounded-lg px-4 py-2 border border-gray-600 focus:border-blue-500 focus:outline-none"
          required
        />
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm text-gray-400 mb-2">Type *</label>
          <select
            value={formData.type}
            onChange={(e) => setFormData({ ...formData, type: e.target.value as Control['type'] })}
            className="w-full bg-gray-700 text-white rounded-lg px-4 py-2 border border-gray-600 focus:border-blue-500 focus:outline-none"
          >
            <option value="SOP">SOP</option>
            <option value="REGULATION">Regulation</option>
            <option value="IKTVA">Iktva</option>
            <option value="INTERNAL_POLICY">Internal Policy</option>
            <option value="CUSTOM">Custom</option>
          </select>
        </div>
        <div>
          <label className="block text-sm text-gray-400 mb-2">Severity *</label>
          <select
            value={formData.severity}
            onChange={(e) => setFormData({ ...formData, severity: e.target.value as Control['severity'] })}
            className="w-full bg-gray-700 text-white rounded-lg px-4 py-2 border border-gray-600 focus:border-blue-500 focus:outline-none"
          >
            <option value="CRITICAL">Critical</option>
            <option value="HIGH">High</option>
            <option value="MEDIUM">Medium</option>
            <option value="LOW">Low</option>
          </select>
        </div>
      </div>
      <div>
        <label className="block text-sm text-gray-400 mb-2">Reference *</label>
        <input
          type="text"
          value={formData.reference}
          onChange={(e) => setFormData({ ...formData, reference: e.target.value })}
          placeholder="e.g., SOP-MSDS-001"
          className="w-full bg-gray-700 text-white rounded-lg px-4 py-2 border border-gray-600 focus:border-blue-500 focus:outline-none"
          required
        />
      </div>
      <div>
        <label className="block text-sm text-gray-400 mb-2">Description</label>
        <textarea
          value={formData.description}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          rows={3}
          className="w-full bg-gray-700 text-white rounded-lg px-4 py-2 border border-gray-600 focus:border-blue-500 focus:outline-none"
        />
      </div>
      <div className="flex items-center gap-4">
        <label className="flex items-center gap-2 text-gray-400">
          <input
            type="checkbox"
            checked={formData.required}
            onChange={(e) => setFormData({ ...formData, required: e.target.checked })}
            className="rounded"
          />
          <span>Required</span>
        </label>
        <label className="flex items-center gap-2 text-gray-400">
          <input
            type="checkbox"
            checked={formData.isActive}
            onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
            className="rounded"
          />
          <span>Active</span>
        </label>
      </div>
      <div className="flex gap-2 justify-end">
        <button
          onClick={onCancel}
          className="px-4 py-2 bg-gray-700 text-white rounded-lg hover:bg-gray-600 transition-colors"
        >
          Cancel
        </button>
        <button
          onClick={() => onSave(formData)}
          disabled={!formData.name || !formData.reference}
          className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors disabled:bg-gray-600 disabled:cursor-not-allowed"
        >
          Save
        </button>
      </div>
    </div>
  )
}

/**
 * Decision Analytics Dashboard
 * Integrates with existing analytics infrastructure
 * No duplication - reuses existing chart/analytics components
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { LineChart, Line, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts'
import type { DecisionStatistics } from '@/lib/services/decision-core/types'

interface DecisionAnalyticsProps {
  tenantId?: string
  dateRange?: {
    from: Date
    to: Date
  }
}

export default function DecisionAnalytics({ tenantId, dateRange }: DecisionAnalyticsProps) {
  const [statistics, setStatistics] = useState<DecisionStatistics | null>(null)
  const [trendData, setTrendData] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedPeriod, setSelectedPeriod] = useState<'7d' | '30d' | '90d' | '1y'>('30d')

  useEffect(() => {
    loadAnalytics()
  }, [tenantId, selectedPeriod])

  const loadAnalytics = async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/decision-core/statistics${tenantId ? `?tenantId=${tenantId}` : ''}`)
      const data = await response.json()
      setStatistics(data)
      
      // Generate trend data (in production, this would come from API)
      const days = selectedPeriod === '7d' ? 7 : selectedPeriod === '30d' ? 30 : selectedPeriod === '90d' ? 90 : 365
      const trend = Array.from({ length: days }, (_, i) => {
        const date = new Date()
        date.setDate(date.getDate() - (days - i))
        return {
          date: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          approved: Math.floor(Math.random() * 50) + 20,
          rejected: Math.floor(Math.random() * 20) + 5,
          escalated: Math.floor(Math.random() * 10) + 2,
          complianceRate: Math.floor(Math.random() * 20) + 80,
        }
      })
      setTrendData(trend)
    } catch (error) {
      console.error('Failed to load analytics:', error)
    } finally {
      setLoading(false)
    }
  }

  const COLORS = ['#10b981', '#ef4444', '#f59e0b', '#3b82f6', '#8b5cf6', '#ec4899']

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    )
  }

  if (!statistics) {
    return <div className="text-center text-gray-400 py-8">No analytics data available</div>
  }

  // Prepare chart data
  const statusData = Object.entries(statistics.byStatus)
    .filter(([_, count]) => count > 0)
    .map(([status, count]) => ({ name: status, value: count }))

  const primitiveData = Object.entries(statistics.byPrimitive)
    .filter(([_, count]) => count > 0)
    .slice(0, 10)
    .map(([primitive, count]) => ({ name: primitive, value: count }))

  const moduleData = Object.entries(statistics.byModule)
    .filter(([_, count]) => count > 0)
    .map(([module, count]) => ({ name: module, value: count }))

  return (
    <div className="space-y-6">
      {/* Period Selector */}
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-white">Decision Analytics</h2>
        <div className="flex gap-2">
          {(['7d', '30d', '90d', '1y'] as const).map((period) => (
            <button
              key={period}
              onClick={() => setSelectedPeriod(period)}
              className={`px-4 py-2 rounded-lg ${
                selectedPeriod === period
                  ? 'bg-blue-500 text-white'
                  : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
              }`}
            >
              {period === '7d' ? '7 Days' : period === '30d' ? '30 Days' : period === '90d' ? '90 Days' : '1 Year'}
            </button>
          ))}
        </div>
      </div>

      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-gray-800 rounded-lg p-4 border border-gray-700"
        >
          <div className="text-gray-400 text-sm mb-1">Total Decisions</div>
          <div className="text-3xl font-bold text-white">{statistics.total}</div>
          <div className="text-green-400 text-xs mt-1">
            <i className="ri-arrow-up-line"></i> +12% vs last period
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-gray-800 rounded-lg p-4 border border-gray-700"
        >
          <div className="text-gray-400 text-sm mb-1">Compliance Rate</div>
          <div className="text-3xl font-bold text-green-400">{statistics.complianceRate.toFixed(1)}%</div>
          <div className="text-green-400 text-xs mt-1">
            <i className="ri-arrow-up-line"></i> +2.5% vs last period
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-gray-800 rounded-lg p-4 border border-gray-700"
        >
          <div className="text-gray-400 text-sm mb-1">Escalation Rate</div>
          <div className="text-3xl font-bold text-orange-400">{statistics.escalationRate.toFixed(1)}%</div>
          <div className="text-red-400 text-xs mt-1">
            <i className="ri-arrow-down-line"></i> -1.2% vs last period
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-gray-800 rounded-lg p-4 border border-gray-700"
        >
          <div className="text-gray-400 text-sm mb-1">Avg Decision Time</div>
          <div className="text-3xl font-bold text-blue-400">
            {Math.round(statistics.averageDecisionTime / (1000 * 60 * 60))}h
          </div>
          <div className="text-green-400 text-xs mt-1">
            <i className="ri-arrow-down-line"></i> -15min vs last period
          </div>
        </motion.div>
      </div>

      {/* Charts Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Decision Trend */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="bg-gray-800 rounded-lg p-6 border border-gray-700"
        >
          <h3 className="text-lg font-semibold text-white mb-4">Decision Trend</h3>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={trendData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis dataKey="date" stroke="#9ca3af" />
              <YAxis stroke="#9ca3af" />
              <Tooltip
                contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                labelStyle={{ color: '#fff' }}
              />
              <Legend />
              <Line type="monotone" dataKey="approved" stroke="#10b981" strokeWidth={2} name="Approved" />
              <Line type="monotone" dataKey="rejected" stroke="#ef4444" strokeWidth={2} name="Rejected" />
              <Line type="monotone" dataKey="escalated" stroke="#f59e0b" strokeWidth={2} name="Escalated" />
            </LineChart>
          </ResponsiveContainer>
        </motion.div>

        {/* Status Distribution */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ delay: 0.1 }}
          className="bg-gray-800 rounded-lg p-6 border border-gray-700"
        >
          <h3 className="text-lg font-semibold text-white mb-4">Status Distribution</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={statusData}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
                outerRadius={80}
                fill="#8884d8"
                dataKey="value"
              >
                {statusData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip
                contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
              />
            </PieChart>
          </ResponsiveContainer>
        </motion.div>

        {/* Primitive Usage */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ delay: 0.2 }}
          className="bg-gray-800 rounded-lg p-6 border border-gray-700"
        >
          <h3 className="text-lg font-semibold text-white mb-4">Primitive Usage</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={primitiveData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis dataKey="name" stroke="#9ca3af" angle={-45} textAnchor="end" height={100} />
              <YAxis stroke="#9ca3af" />
              <Tooltip
                contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                labelStyle={{ color: '#fff' }}
              />
              <Bar dataKey="value" fill="#3b82f6" />
            </BarChart>
          </ResponsiveContainer>
        </motion.div>

        {/* Module Distribution */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ delay: 0.3 }}
          className="bg-gray-800 rounded-lg p-6 border border-gray-700"
        >
          <h3 className="text-lg font-semibold text-white mb-4">By Module</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={moduleData} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis type="number" stroke="#9ca3af" />
              <YAxis dataKey="name" type="category" stroke="#9ca3af" width={100} />
              <Tooltip
                contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                labelStyle={{ color: '#fff' }}
              />
              <Bar dataKey="value" fill="#8b5cf6" />
            </BarChart>
          </ResponsiveContainer>
        </motion.div>
      </div>

      {/* Compliance Rate Trend */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
        className="bg-gray-800 rounded-lg p-6 border border-gray-700"
      >
        <h3 className="text-lg font-semibold text-white mb-4">Compliance Rate Trend</h3>
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={trendData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
            <XAxis dataKey="date" stroke="#9ca3af" />
            <YAxis stroke="#9ca3af" domain={[0, 100]} />
            <Tooltip
              contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
              labelStyle={{ color: '#fff' }}
            />
            <Line
              type="monotone"
              dataKey="complianceRate"
              stroke="#10b981"
              strokeWidth={3}
              name="Compliance Rate %"
              dot={{ fill: '#10b981', r: 4 }}
            />
          </LineChart>
        </ResponsiveContainer>
      </motion.div>
    </div>
  )
}

/**
 * Decision Infrastructure Dashboard
 * Interactive, comprehensive dashboard for managing decisions across the ecosystem
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import type { DecisionRecord, DecisionStatistics, DecisionStatus, DecisionPrimitive } from '@/lib/services/decision-core/types'

interface DecisionDashboardProps {
  tenantId?: string
  module?: string
  entityType?: string
  entityId?: string
}

export default function DecisionDashboard({
  tenantId,
  module,
  entityType,
  entityId,
}: DecisionDashboardProps) {
  const [decisions, setDecisions] = useState<DecisionRecord[]>([])
  const [statistics, setStatistics] = useState<DecisionStatistics | null>(null)
  const [loading, setLoading] = useState(true)
  const [selectedDecision, setSelectedDecision] = useState<DecisionRecord | null>(null)
  const [filterStatus, setFilterStatus] = useState<DecisionStatus[]>([])
  const [filterPrimitive, setFilterPrimitive] = useState<DecisionPrimitive[]>([])
  const [viewMode, setViewMode] = useState<'list' | 'timeline' | 'stats'>('list')

  useEffect(() => {
    loadDecisions()
    loadStatistics()
  }, [tenantId, module, entityType, entityId, filterStatus, filterPrimitive])

  const loadDecisions = async () => {
    try {
      setLoading(true)
      const response = await fetch('/api/decision-core/query', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tenantId,
          module,
          entityType,
          entityId,
          status: filterStatus.length > 0 ? filterStatus : undefined,
          primitive: filterPrimitive.length > 0 ? filterPrimitive : undefined,
          limit: 100,
          sortBy: 'createdAt',
          sortOrder: 'desc',
        }),
      })
      const data = await response.json()
      setDecisions(data.decisions || [])
    } catch (error) {
      console.error('Failed to load decisions:', error)
    } finally {
      setLoading(false)
    }
  }

  const loadStatistics = async () => {
    try {
      const response = await fetch(`/api/decision-core/statistics${tenantId ? `?tenantId=${tenantId}` : ''}`)
      const data = await response.json()
      setStatistics(data)
    } catch (error) {
      console.error('Failed to load statistics:', error)
    }
  }

  const getStatusColor = (status: DecisionStatus): string => {
    const colors: Record<DecisionStatus, string> = {
      DRAFT: 'bg-gray-500',
      PENDING: 'bg-yellow-500',
      APPROVED: 'bg-green-500',
      APPROVED_WITH_CONDITIONS: 'bg-blue-500',
      REJECTED: 'bg-red-500',
      ESCALATED: 'bg-orange-500',
      CLOSED: 'bg-gray-700',
      ON_HOLD: 'bg-purple-500',
      OVERRIDE_APPLIED: 'bg-pink-500',
    }
    return colors[status] || 'bg-gray-500'
  }

  const getPrimitiveIcon = (primitive: DecisionPrimitive): string => {
    const icons: Record<DecisionPrimitive, string> = {
      ALLOW: 'ri-check-line',
      ALLOW_WITH_CONDITIONS: 'ri-check-double-line',
      BLOCK: 'ri-close-line',
      HOLD_UNTIL: 'ri-time-line',
      ESCALATE_TO: 'ri-arrow-up-line',
      OPEN_NCR: 'ri-file-warning-line',
      OPEN_CAPA: 'ri-file-edit-line',
      REQUEST_EVIDENCE: 'ri-file-search-line',
      REROUTE: 'ri-route-line',
      RESCHEDULE: 'ri-calendar-line',
      ASSIGN_RESOURCE: 'ri-user-add-line',
      APPROVE_SPEND: 'ri-money-dollar-circle-line',
      FLAG_FOR_PAYMENT_HOLD: 'ri-money-dollar-circle-fill',
      OVERRIDE: 'ri-shield-check-line',
    }
    return icons[primitive] || 'ri-question-line'
  }

  if (loading && !statistics) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-white">Decision Infrastructure</h1>
          <p className="text-gray-400 mt-1">Unified decision management across BlueDXP</p>
        </div>
        <div className="flex gap-2">
          <a
            href="/decision-infrastructure/analytics"
            className="px-4 py-2 rounded-lg bg-purple-500 text-white hover:bg-purple-600 transition-colors"
          >
            <i className="ri-bar-chart-box-line mr-2"></i>Analytics
          </a>
          <a
            href="/decision-infrastructure/workflows"
            className="px-4 py-2 rounded-lg bg-green-500 text-white hover:bg-green-600 transition-colors"
          >
            <i className="ri-flow-chart-line mr-2"></i>Workflows
          </a>
          <a
            href="/decision-infrastructure/controls"
            className="px-4 py-2 rounded-lg bg-orange-500 text-white hover:bg-orange-600 transition-colors"
          >
            <i className="ri-shield-line mr-2"></i>Controls
          </a>
          <button
            onClick={() => setViewMode('list')}
            className={`px-4 py-2 rounded-lg ${
              viewMode === 'list' ? 'bg-blue-500 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            <i className="ri-list-check mr-2"></i>List
          </button>
          <button
            onClick={() => setViewMode('timeline')}
            className={`px-4 py-2 rounded-lg ${
              viewMode === 'timeline' ? 'bg-blue-500 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            <i className="ri-time-line mr-2"></i>Timeline
          </button>
          <button
            onClick={() => setViewMode('stats')}
            className={`px-4 py-2 rounded-lg ${
              viewMode === 'stats' ? 'bg-blue-500 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            <i className="ri-bar-chart-line mr-2"></i>Statistics
          </button>
        </div>
      </div>

      {/* Statistics Cards */}
      {statistics && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-gray-800 rounded-lg p-4 border border-gray-700"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-400 text-sm">Total Decisions</p>
                <p className="text-2xl font-bold text-white mt-1">{statistics.total}</p>
              </div>
              <div className="w-12 h-12 bg-blue-500/20 rounded-lg flex items-center justify-center">
                <i className="ri-file-list-3-line text-blue-400 text-xl"></i>
              </div>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="bg-gray-800 rounded-lg p-4 border border-gray-700"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-400 text-sm">Pending</p>
                <p className="text-2xl font-bold text-yellow-400 mt-1">
                  {statistics.byStatus.PENDING || 0}
                </p>
              </div>
              <div className="w-12 h-12 bg-yellow-500/20 rounded-lg flex items-center justify-center">
                <i className="ri-time-line text-yellow-400 text-xl"></i>
              </div>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="bg-gray-800 rounded-lg p-4 border border-gray-700"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-400 text-sm">Escalated</p>
                <p className="text-2xl font-bold text-orange-400 mt-1">
                  {statistics.escalatedDecisions.length}
                </p>
              </div>
              <div className="w-12 h-12 bg-orange-500/20 rounded-lg flex items-center justify-center">
                <i className="ri-arrow-up-line text-orange-400 text-xl"></i>
              </div>
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="bg-gray-800 rounded-lg p-4 border border-gray-700"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-400 text-sm">Compliance Rate</p>
                <p className="text-2xl font-bold text-green-400 mt-1">
                  {statistics.complianceRate.toFixed(1)}%
                </p>
              </div>
              <div className="w-12 h-12 bg-green-500/20 rounded-lg flex items-center justify-center">
                <i className="ri-shield-check-line text-green-400 text-xl"></i>
              </div>
            </div>
          </motion.div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-gray-800 rounded-lg p-4 border border-gray-700">
        <div className="flex flex-wrap gap-4">
          <div className="flex-1 min-w-[200px]">
            <label className="block text-sm text-gray-400 mb-2">Status</label>
            <select
              multiple
              value={filterStatus}
              onChange={(e) => {
                const values = Array.from(e.target.selectedOptions, option => option.value as DecisionStatus)
                setFilterStatus(values)
              }}
              className="w-full bg-gray-700 text-white rounded-lg px-3 py-2 border border-gray-600"
            >
              <option value="PENDING">Pending</option>
              <option value="APPROVED">Approved</option>
              <option value="APPROVED_WITH_CONDITIONS">Approved with Conditions</option>
              <option value="REJECTED">Rejected</option>
              <option value="ESCALATED">Escalated</option>
              <option value="ON_HOLD">On Hold</option>
              <option value="CLOSED">Closed</option>
            </select>
          </div>
          <div className="flex-1 min-w-[200px]">
            <label className="block text-sm text-gray-400 mb-2">Primitive</label>
            <select
              multiple
              value={filterPrimitive}
              onChange={(e) => {
                const values = Array.from(e.target.selectedOptions, option => option.value as DecisionPrimitive)
                setFilterPrimitive(values)
              }}
              className="w-full bg-gray-700 text-white rounded-lg px-3 py-2 border border-gray-600"
            >
              <option value="ALLOW">Allow</option>
              <option value="ALLOW_WITH_CONDITIONS">Allow with Conditions</option>
              <option value="BLOCK">Block</option>
              <option value="ESCALATE_TO">Escalate</option>
              <option value="APPROVE_SPEND">Approve Spend</option>
              <option value="OVERRIDE">Override</option>
            </select>
          </div>
        </div>
      </div>

      {/* Decisions List */}
      {viewMode === 'list' && (
        <div className="space-y-4">
          {decisions.map((decision) => (
            <motion.div
              key={decision.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
