              className="bg-gray-800 rounded-lg p-4 border border-gray-700 cursor-pointer hover:border-blue-500 transition-colors"
            >
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className={`px-2 py-1 rounded text-xs font-medium ${getStatusColor(decision.status)} text-white`}>
                      {decision.status}
                    </span>
                    <i className={`${getPrimitiveIcon(decision.primitive)} text-gray-400`}></i>
                    <span className="text-sm text-gray-400">{decision.primitive}</span>
                    <span className="text-xs text-gray-500">•</span>
                    <span className="text-sm text-gray-400">{decision.module}</span>
                    <span className="text-xs text-gray-500">•</span>
                    <span className="text-sm text-gray-400">{decision.entityType}</span>
                  </div>
                  {decision.reason && (
                    <p className="text-white mb-2">{decision.reason}</p>
