                        facilityId: assetData.location?.facilityId || 'facility-1',
                        building: assetData.location?.building,
                        floor: assetData.location?.floor,
                        room: assetData.location?.room,
                        warehouseId: assetData.location?.warehouseId,
                        warehouseLocationCode: assetData.location?.warehouseLocationCode,
                        warehouseZoneId: assetData.location?.warehouseZoneId,
                      },
                      ownership: {
                        ownershipType: assetData.ownership?.ownershipType || 'owned',
                        ownerName: assetData.ownership?.ownerName,
                        ownerContact: assetData.ownership?.ownerEmail || assetData.ownership?.ownerPhone ? {
