                      },
                      financial: {
                        acquisitionCost: assetData.acquisitionCost || assetData.currentValue,
                        currentValue: assetData.currentValue,
                        depreciationMethod: assetData.depreciationMethod || 'straight-line',
                      },
                      maintenance: {
                        lastMaintenanceDate: assetData.lastMaintenanceDate ? new Date(assetData.lastMaintenanceDate) : undefined,
                        nextMaintenanceDate: assetData.nextMaintenanceDate ? new Date(assetData.nextMaintenanceDate) : undefined,
                        maintenanceFrequency: assetData.maintenanceFrequency ? parseInt(assetData.maintenanceFrequency) : undefined,
                      },
                      relationships: {
                        capaIds: assetData.capaIds || [],
                        workOrderIds: assetData.workOrderIds || [],
                      },
                      specifications: {
                        manufacturer: assetData.manufacturer,
                        model: assetData.model,
                        serialNumber: assetData.serialNumber,
                      },
                    }

                    const method = selectedAsset ? 'PUT' : 'POST'
                    const url = selectedAsset 
                      ? `/api/facility/assets`
                      : `/api/facility/assets`

                    const response = await fetch(url, {
                      method,
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify(selectedAsset ? { id: selectedAsset.id, ...serviceData } : serviceData),
                    })

                    if (response.ok) {
                      const result = await response.json()
                      if (result.success) {
                        // Refresh assets list
                        const refreshResponse = await fetch('/api/facility/assets?facilityId=facility-1')
                        if (refreshResponse.ok) {
                          const refreshResult = await refreshResponse.json()
                          if (refreshResult.success && refreshResult.data) {
                            const transformedAssets = refreshResult.data.map((asset: any) => ({
                              id: asset.id,
                              name: asset.name,
                              code: asset.code || asset.assetCode,
                              type: asset.type,
                              status: asset.status,
                              location: asset.location || { facilityId: asset.facilityId },
                              ownership: asset.ownership || { ownershipType: 'owned', maintenanceResponsibility: 'owner' },
                              currentValue: asset.financial?.currentValue || asset.currentValue || 0,
                              nextMaintenance: asset.maintenance?.nextMaintenanceDate ? new Date(asset.maintenance.nextMaintenanceDate) : undefined,
                              criticality: asset.criticality || 'medium',
                              capaIds: asset.relationships?.capaIds || [],
                              workOrderIds: asset.relationships?.workOrderIds || [],
                              manufacturer: asset.specifications?.manufacturer,
                              model: asset.specifications?.model,
                              serialNumber: asset.specifications?.serialNumber,
                            }))
                            setAssets(transformedAssets)
                          }
                        }
                        setShowAddModal(false)
                        setSelectedAsset(null)
                      }
                    } else {
                      alert('Failed to save asset')
                    }
                  } catch (error: any) {
                    console.error('Error saving asset:', error)
                    alert(`Error saving asset: ${error.message}`)
                  }
                }}
                onCancel={() => {
                  setShowAddModal(false)
                  setSelectedAsset(null)
                }}
