export default function SentinelDashboard() {
    const [nodes, setNodes, onNodesChange] = useNodesState([]);
    const [edges, setEdges, onEdgesChange] = useEdgesState([]);
    const [logs, setLogs] = useState<string[]>([]);
    const [systemHealth, setSystemHealth] = useState(100);
    const [impactAnalysis, setImpactAnalysis] = useState<ImpactedBatch[]>([]);
    const [viewMode, setViewMode] = useState<'2D' | '3D'>('2D');
    const [predictionHours, setPredictionHours] = useState(0);

    // Keep a clean set of SentinelNodes for the 3D view (ReactFlow nodes structure is different)
    const [rawNodes, setRawNodes] = useState<SentinelNode[]>(initialNodesData);

    // Initialize Graph
    useEffect(() => {
        sentinelEngine.resetGraph(initialNodesData, initialEdgesData);
        refreshGraphState(initialNodesData, initialEdgesData);
        addLog('System Initialized. All systems operational.');
    }, []);

    const refreshGraphState = (sNodes: SentinelNode[], sEdges: SentinelEdge[], failedIds: string[] = []) => {
        // Prepare ReactFlow Nodes
        const rfNodes: Node[] = sNodes.map((n, idx) => ({
            id: n.id,
            position: { x: 250 + (idx % 3) * 200, y: 100 + Math.floor(idx / 3) * 150 },
            data: { label: n.label, original: n },
            style: getNodeStyle(n.status, n.type),
            type: 'default'
        }));

        // Prepare ReactFlow Edges
        const rfEdges: Edge[] = sEdges.map(e => ({
            id: e.id,
            source: e.source,
            target: e.target,
            animated: !failedIds.includes(e.source), // Stop animation if source failed
            style: {
                stroke: failedIds.includes(e.source) ? '#ef4444' : '#0ea5e9',
                strokeWidth: 2,
                opacity: failedIds.includes(e.source) ? 0.3 : 1
            },
            markerEnd: { type: MarkerType.ArrowClosed, color: failedIds.includes(e.source) ? '#ef4444' : '#0ea5e9' },
        }));

        setNodes(rfNodes);
        setEdges(rfEdges);
        setRawNodes(sNodes);
    };

    const addLog = (msg: string) => {
        setLogs(prev => [msg, ...prev].slice(0, 50));
    };

    const handleSimulation = async (nodeId: string) => {
        if (!nodeId) return;

        // Simulate Failure
        const targetNode = rawNodes.find(n => n.id === nodeId);
        addLog(`USER COMMAND: Simulate failure on ${targetNode?.label || nodeId}...`);

        // Run Logic
        const result = sentinelEngine.simulateFailure(nodeId);

        // Update local state to reflect failure
        const updatedNodes = rawNodes.map(n => {
            if (result.impactedNodes.includes(n.id)) {
                return { ...n, status: 'FAILED' as NodeStatus, health: 0 };
            }
            return n;
        });

        // Refresh UI
        refreshGraphState(updatedNodes, initialEdgesData, result.impactedNodes);
        setSystemHealth(result.systemHealth);
        result.logs.forEach(l => addLog(l));

        // Calculate Inventory Impact
        const impacts = await InventoryImpactService.getImpactedInventory(result.impactedNodes);
        setImpactAnalysis(impacts);
        if (impacts.length > 0) {
            addLog(`CRITICAL: ${impacts.length} Inventory Batches at risk!`);

            // THE VOICE: Autonomous Alert
            addLog(`THE VOICE: Initiating WhatsApp Emergency Protocol...`);
            setTimeout(() => {
                addLog(`WHATSAPP SENT: "Alert! ${targetNode?.label} Failed. $${impacts.reduce((a, b) => a + b.projectedLoss, 0).toLocaleString()} loss imminent."`);
            }, 1500);
        }
    };

    const handlePrediction = (hours: number) => {
        setPredictionHours(hours);
        if (hours === 0) {
            // Reset to Now
            sentinelEngine.resetGraph(initialNodesData, initialEdgesData);
            refreshGraphState(initialNodesData, initialEdgesData);
            addLog('ORACLE: Returned to Present Time.');
            return;
        }

        const { nodes, logs } = sentinelEngine.predictState(hours);
        const failedIds = nodes.filter(n => n.status === 'FAILED').map(n => n.id);
        refreshGraphState(nodes, initialEdgesData, failedIds);
        logs.forEach(l => addLog(l));
    };

    const handleReset = () => {
        // Reload page or reset state
        window.location.reload();
    };

    return (
        <div className="flex bg-gray-900 text-white rounded-xl overflow-hidden border border-gray-800 shadow-2xl h-[90vh]">

            {/* Sidebar Controls */}
            <div className="w-80 bg-gray-950 border-r border-gray-800 flex flex-col shrink-0">
                <div className="p-6 border-b border-gray-800">
                    <h2 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-cyan-400 to-blue-500">
                        THE SENTINEL
                    </h2>
                    <p className="text-xs text-gray-500 mt-1 mb-6">Autonomous Facility Nervous System</p>

                    <div className="mb-6">
                        <div className="flex gap-2 p-1 bg-gray-900 rounded-lg border border-gray-800">
                            <button
                                onClick={() => setViewMode('2D')}
                                className={`flex-1 py-1.5 text-xs font-bold rounded ${viewMode === '2D' ? 'bg-cyan-500 text-black' : 'text-gray-400 hover:text-white'}`}
                            >
                                2D GRAPH
                            </button>
                            <button
                                onClick={() => setViewMode('3D')}
                                className={`flex-1 py-1.5 text-xs font-bold rounded ${viewMode === '3D' ? 'bg-cyan-500 text-black' : 'text-gray-400 hover:text-white'}`}
                            >
                                3D IMMERSIVE
                            </button>
                        </div>
                    </div>

                    <div className="mb-6">
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-sm text-gray-400">System Resilience</span>
                            <span className={`text-xl font-mono font-bold ${systemHealth > 80 ? 'text-green-400' : 'text-red-500'}`}>
                                {Math.round(systemHealth)}%
                            </span>
                        </div>
                        <div className="h-2 w-full bg-gray-800 rounded-full overflow-hidden">
                            <motion.div
                                className={`h-full ${systemHealth > 80 ? 'bg-green-500' : 'bg-red-500'}`}
                                initial={{ width: '100%' }}
                                animate={{ width: `${systemHealth}%` }}
                            />
                        </div>
                    </div>

                    <button
                        onClick={handleReset}
                        className="w-full py-2 bg-gray-800 hover:bg-gray-700 text-cyan-400 border border-gray-700 rounded-lg transition-all"
                    >
                        Reset Simulation
                    </button>

                    {/* THE ORACLE CONTROLS */}
                    <div className="mt-8 border-t border-gray-800 pt-6">
                        <div className="flex items-center gap-2 mb-2">
                            <i className="ri-pass-valid-line text-purple-400"></i>
                            <h3 className="text-sm font-bold text-purple-400">THE ORACLE</h3>
                        </div>
                        <p className="text-[10px] text-gray-400 mb-4">Predictive Time-Travel Simulation</p>

                        <div className="flex items-center justify-between text-xs text-gray-500 mb-2">
                            <span>NOW</span>
                            <span className="text-purple-400 font-mono">+{predictionHours}h</span>
                            <span>+48h</span>
                        </div>
                        <input
                            type="range"
                            min="0"
                            max="48"
                            step="1"
                            value={predictionHours}
                            onChange={(e) => handlePrediction(parseInt(e.target.value))}
                            className="w-full h-2 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                        />
                        {predictionHours > 0 && (
                            <div className="mt-2 text-[10px] text-purple-300 animate-pulse text-center">
                                PREDICTING FUTURE STATE
                            </div>
                        )}
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-2 font-mono text-xs">
                    <div className="text-gray-500 uppercase tracking-wider mb-2">Event Log</div>
                    <AnimatePresence>
                        {logs.map((log, i) => (
                            <motion.div
                                key={i}
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                className={`p-2 rounded border-l-2 ${log.includes('FAILURE') || log.includes('impacted') || log.includes('CRITICAL') ? 'border-red-500 bg-red-900/10 text-red-300' : 'border-cyan-500 bg-gray-800 text-gray-300'}`}
                            >
                                <span className="opacity-50 mr-2">[{new Date().toLocaleTimeString().split(' ')[0]}]</span>
                                {log}
                            </motion.div>
                        ))}
                    </AnimatePresence>
                </div>
            </div>

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col bg-black relative">

                {/* Visualization Area */}
                <div className="flex-1 relative border-b border-gray-800">
                    {viewMode === '2D' ? (
                        <ReactFlow
                            nodes={nodes}
                            edges={edges}
                            onNodesChange={onNodesChange}
                            onEdgesChange={onEdgesChange}
                            onNodeClick={(_, node) => handleSimulation(node.id)}
                            fitView
                            className="bg-gray-950"
                            maxZoom={1.5}
                            minZoom={0.5}
                        >
                            <Background color="#333" gap={20} />
                            <Controls className="bg-gray-800 border-gray-700 fill-white text-white" />
                            <MiniMap nodeColor="#0ea5e9" maskColor="rgba(0, 0, 0, 0.7)" className="bg-gray-900 border border-gray-800" />
                        </ReactFlow>
                    ) : (
                        <Facility3DScene
                            nodes={rawNodes}
                            onNodeClick={handleSimulation}
                        />
                    )}

                    {/* Overlay Hint */}
                    <div className="absolute top-4 right-4 bg-black/60 backdrop-blur border border-white/10 p-3 rounded-lg pointer-events-none">
                        <p className="text-xs text-cyan-400 font-bold">MODE: {viewMode}</p>
                        <p className="text-[10px] text-gray-400">Click objects to simulate failure</p>
                    </div>
                </div>

                {/* Impact Analysis Panel (Bottom) */}
                <AnimatePresence>
                    {impactAnalysis.length > 0 && (
                        <motion.div
                            initial={{ height: 0 }}
                            animate={{ height: 'auto' }}
                            exit={{ height: 0 }}
                            className="bg-red-950/20 border-t border-red-900/50 backdrop-blur-sm"
                        >
                            <div className="p-4">
                                <h3 className="text-red-400 font-bold mb-3 flex items-center gap-2">
                                    <i className="ri-alert-line animate-pulse"></i>
                                    INVENTORY IMPACT ASSESSMENT
                                    <span className="text-xs font-normal text-red-300 ml-2 bg-red-900/50 px-2 py-0.5 rounded">
                                        {impactAnalysis.length} Batches At Risk
                                    </span>
                                </h3>
                                <div className="overflow-x-auto">
                                    <table className="w-full text-left text-xs text-gray-300">
                                        <thead className="bg-red-900/30 text-red-200">
                                            <tr>
                                                <th className="p-2">Chemical Name</th>
                                                <th className="p-2">Location</th>
                                                <th className="p-2">SKU / Batch</th>
                                                <th className="p-2">Risk Level</th>
                                                <th className="p-2">Projected Loss</th>
                                                <th className="p-2">Time To Spoilage</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {impactAnalysis.map((item, idx) => (
                                                <tr key={idx} className="border-b border-red-900/20 hover:bg-red-900/10 transition-colors">
                                                    <td className="p-2 font-semibold text-white">{item.chemicalName}</td>
                                                    <td className="p-2">{item.location}</td>
                                                    <td className="p-2 font-mono">{item.sku}</td>
                                                    <td className="p-2">
                                                        <span className={`px-2 py-0.5 rounded font-bold ${item.riskLevel === 'CRITICAL' ? 'bg-red-600 text-white' : 'bg-amber-600 text-black'}`}>
                                                            {item.riskLevel}
                                                        </span>
                                                    </td>
                                                    <td className="p-2 text-red-400 font-mono">${item.projectedLoss.toLocaleString()}</td>
                                                    <td className="p-2">{item.timeToSpoilage} hrs</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
}

/**
 * Hierarchical Analytics Dashboard
 * 
 * Multi-layered breakdown visualization with:
 * - Interactive hierarchical tree
 * - Savings insights cards
 * - Drill-down capability
 * - Multi-dimensional views
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  BarChart,
  Bar,
  LineChart,
  Line,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Treemap,
} from 'recharts'
import type {
  HierarchicalBreakdown,
  SavingsInsight,
} from '@/lib/services/facility/utility-bills/hierarchicalAnalyticsService'

interface HierarchicalAnalyticsDashboardProps {
  facilityId?: string
  warehouseId?: string
  period?: { start: Date; end: Date }
}

export default function HierarchicalAnalyticsDashboard({
  facilityId,
  warehouseId,
  period,
}: HierarchicalAnalyticsDashboardProps) {
  const [breakdown, setBreakdown] = useState<HierarchicalBreakdown[]>([])
  const [savingsInsights, setSavingsInsights] = useState<SavingsInsight[]>([])
  const [selectedLevel, setSelectedLevel] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)
  const [viewMode, setViewMode] = useState<'tree' | 'savings' | 'comparison'>('tree')

  useEffect(() => {
    loadData()
  }, [facilityId, warehouseId, period])

  const loadData = async () => {
    setLoading(true)
    try {
      // Build hierarchical structure from warehouse data
      const structure = await buildHierarchicalStructure(facilityId, warehouseId)

      // Get breakdown
      const breakdownResponse = await fetch('/api/facility/utility-bills/hierarchical', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'breakdown',
          structure,
          period: period
            ? {
                start: period.start.toISOString(),
                end: period.end.toISOString(),
              }
            : undefined,
        }),
      })

      const breakdownData = await breakdownResponse.json()
      if (breakdownData.success) {
        setBreakdown(breakdownData.data)
      }

      // Get savings insights
      const savingsResponse = await fetch('/api/facility/utility-bills/hierarchical', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'savings',
          structure,
          period: period
            ? {
                start: period.start.toISOString(),
                end: period.end.toISOString(),
              }
            : undefined,
        }),
      })

      const savingsData = await savingsResponse.json()
      if (savingsData.success) {
        setSavingsInsights(savingsData.data)
      }
    } catch (error) {
      console.error('Error loading hierarchical analytics:', error)
    } finally {
      setLoading(false)
    }
  }

  const buildHierarchicalStructure = async (
    facilityId?: string,
    warehouseId?: string
  ): Promise<any[]> => {
    // This would fetch from WMS to build actual structure
    // For now, using sample structure based on your data
    return [
      {
        level: 'area',
        id: 'block-12',
        name: 'Block 12',
        code: 'BLK12',
        children: Array.from({ length: 13 }, (_, i) => ({
          level: 'warehouse',
          id: `wh-${i + 1}`,
          name: `Block 12 WH ${String(i + 1).padStart(2, '0')}`,
          code: `BLK12-WH${String(i + 1).padStart(2, '0')}`,
        })),
      },
      {
        level: 'area',
        id: 'block-14',
        name: 'Block 14',
        code: 'BLK14',
        children: [
          { level: 'warehouse', id: 'wh-26', name: 'Block 14 WH 26', code: 'BLK14-WH26' },
          { level: 'warehouse', id: 'wh-27', name: 'Block 14 WH 27', code: 'BLK14-WH27' },
        ],
      },
      {
        level: 'area',
        id: 'block-s22-4',
        name: 'Block S22-4',
        code: 'BLK-S22-4',
        children: Array.from({ length: 8 }, (_, i) => ({
          level: 'warehouse',
          id: `s22-wh-${i + 1}`,
          name: `Block S22-4 WH ${i + 1}`,
          code: `BLK-S22-4-WH${i + 1}`,
        })),
      },
    ]
  }

  const totalSavings = savingsInsights.reduce((sum, i) => sum + i.potentialSavings.amount, 0)
  const annualSavings = savingsInsights.reduce(
    (sum, i) => sum + (i.potentialSavings.annualSavings || 0),
    0
  )

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white dark:bg-gray-800 rounded-lg shadow p-6"
        >
          <div className="text-sm text-gray-600 dark:text-gray-400">Total Potential Savings</div>
          <div className="text-2xl font-bold text-green-600 mt-2">
            {totalSavings.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} SAR
          </div>
          <div className="text-xs text-gray-500 mt-1">Per month</div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white dark:bg-gray-800 rounded-lg shadow p-6"
        >
          <div className="text-sm text-gray-600 dark:text-gray-400">Annual Savings</div>
          <div className="text-2xl font-bold text-green-600 mt-2">
            {annualSavings.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} SAR
          </div>
          <div className="text-xs text-gray-500 mt-1">Projected</div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white dark:bg-gray-800 rounded-lg shadow p-6"
        >
          <div className="text-sm text-gray-600 dark:text-gray-400">Savings Opportunities</div>
          <div className="text-2xl font-bold text-blue-600 mt-2">{savingsInsights.length}</div>
          <div className="text-xs text-gray-500 mt-1">Insights identified</div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white dark:bg-gray-800 rounded-lg shadow p-6"
        >
          <div className="text-sm text-gray-600 dark:text-gray-400">Warehouses Analyzed</div>
          <div className="text-2xl font-bold text-purple-600 mt-2">
            {breakdown.reduce((sum, b) => sum + (b.children?.length || 0) + 1, 0)}
          </div>
          <div className="text-xs text-gray-500 mt-1">Across all levels</div>
        </motion.div>
      </div>

      {/* View Mode Tabs */}
      <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-4">
        <div className="flex space-x-2">
          <button
            onClick={() => setViewMode('tree')}
            className={`px-4 py-2 rounded-lg transition ${
              viewMode === 'tree'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300'
            }`}
          >
            Hierarchical Tree
          </button>
          <button
            onClick={() => setViewMode('savings')}
            className={`px-4 py-2 rounded-lg transition ${
              viewMode === 'savings'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300'
            }`}
          >
            Savings Insights
          </button>
          <button
            onClick={() => setViewMode('comparison')}
            className={`px-4 py-2 rounded-lg transition ${
              viewMode === 'comparison'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300'
            }`}
          >
            Comparison
          </button>
        </div>
      </div>

      {/* Hierarchical Tree View */}
      {viewMode === 'tree' && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
          <h3 className="text-xl font-bold mb-4">Hierarchical Breakdown</h3>
          <HierarchicalTreeView
            breakdown={breakdown}
            selectedLevel={selectedLevel}
            onSelectLevel={setSelectedLevel}
          />
        </div>
      )}

      {/* Savings Insights View */}
      {viewMode === 'savings' && (
        <div className="space-y-4">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <h3 className="text-xl font-bold mb-4">Top Savings Opportunities</h3>
            <div className="space-y-4">
              {savingsInsights.slice(0, 10).map((insight, index) => (
                <SavingsInsightCard key={insight.id} insight={insight} index={index} />
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Comparison View */}
      {viewMode === 'comparison' && (
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
          <h3 className="text-xl font-bold mb-4">Warehouse Comparison</h3>
          <ComparisonChart breakdown={breakdown} />
        </div>
      )}
    </div>
  )
}

function HierarchicalTreeView({
  breakdown,
  selectedLevel,
  onSelectLevel,
}: {
  breakdown: HierarchicalBreakdown[]
  selectedLevel: string | null
  onSelectLevel: (id: string | null) => void
}) {
  const renderNode = (node: HierarchicalBreakdown, level: number = 0) => {
    const isSelected = selectedLevel === node.id
    const hasChildren = node.children && node.children.length > 0

    return (
      <div key={node.id} className="ml-4">
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          onClick={() => onSelectLevel(isSelected ? null : node.id)}
          className={`p-4 rounded-lg border-2 cursor-pointer transition ${
            isSelected
              ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/20'
              : 'border-gray-200 dark:border-gray-700 hover:border-blue-300'
          }`}
        >
          <div className="flex items-center justify-between">
            <div>
              <div className="font-semibold text-lg">{node.name}</div>
              <div className="text-sm text-gray-600 dark:text-gray-400">
                {node.summary.totalBills} bills • {node.summary.totalAmount.toFixed(2)} SAR •{' '}
                {node.summary.totalConsumption.toFixed(0)} kWh
              </div>
              <div className="text-xs text-gray-500 mt-1">
                Efficiency: {node.summary.efficiency.toFixed(1)}% • Cost/Unit:{' '}
                {node.summary.costPerUnit.toFixed(3)} SAR
              </div>
            </div>
            <div className="text-right">
              <div className="text-sm font-semibold text-green-600">
                {node.savings.length} opportunities
              </div>
              {node.savings.length > 0 && (
                <div className="text-xs text-gray-500">
                  {node.savings
                    .reduce((sum, s) => sum + s.potentialSavings.amount, 0)
                    .toFixed(2)}{' '}
                  SAR/month
                </div>
              )}
            </div>
          </div>
        </motion.div>

        {hasChildren && (isSelected || level === 0) && (
          <div className="mt-2">
            {node.children!.map(child => renderNode(child, level + 1))}
          </div>
        )}
      </div>
    )
  }

  return <div className="space-y-2">{breakdown.map(node => renderNode(node))}</div>
}

function SavingsInsightCard({
  insight,
  index,
}: {
  insight: SavingsInsight
  index: number
}) {
  const priorityColors = {
    critical: 'bg-red-100 dark:bg-red-900/20 border-red-500',
    high: 'bg-orange-100 dark:bg-orange-900/20 border-orange-500',
    medium: 'bg-yellow-100 dark:bg-yellow-900/20 border-yellow-500',
    low: 'bg-blue-100 dark:bg-blue-900/20 border-blue-500',
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.1 }}
      className={`p-4 rounded-lg border-2 ${priorityColors[insight.recommendations[0]?.priority || 'low']}`}
    >
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-2">
            <span className="px-2 py-1 text-xs font-semibold rounded bg-blue-600 text-white">
              {insight.type.replace('-', ' ').toUpperCase()}
            </span>
            <span
              className={`px-2 py-1 text-xs font-semibold rounded ${
                insight.recommendations[0]?.priority === 'critical'
                  ? 'bg-red-600 text-white'
                  : insight.recommendations[0]?.priority === 'high'
                  ? 'bg-orange-600 text-white'
                  : 'bg-gray-600 text-white'
              }`}
            >
              {insight.recommendations[0]?.priority?.toUpperCase() || 'MEDIUM'}
            </span>
          </div>
          <h4 className="font-bold text-lg mb-1">{insight.title}</h4>
          <p className="text-sm text-gray-600 dark:text-gray-400 mb-3">{insight.description}</p>

          <div className="grid grid-cols-2 gap-4 mb-3">
            <div>
              <div className="text-xs text-gray-500">Potential Savings</div>
              <div className="text-lg font-bold text-green-600">
                {insight.potentialSavings.amount.toFixed(2)} SAR/month
              </div>
              {insight.potentialSavings.annualSavings && (
                <div className="text-xs text-gray-500">
                  {insight.potentialSavings.annualSavings.toFixed(2)} SAR/year
                </div>
              )}
            </div>
            <div>
              <div className="text-xs text-gray-500">Confidence</div>
              <div className="text-lg font-bold">{insight.confidence}%</div>
              {insight.estimatedROI && (
                <div className="text-xs text-gray-500">ROI: {insight.estimatedROI}%</div>
              )}
            </div>
          </div>

          {insight.recommendations.length > 0 && (
            <div className="mt-3">
              <div className="text-xs font-semibold text-gray-700 dark:text-gray-300 mb-2">
                Recommended Actions:
              </div>
              <ul className="list-disc list-inside space-y-1 text-sm">
                {insight.recommendations[0].implementationSteps.map((step, i) => (
                  <li key={i} className="text-gray-600 dark:text-gray-400">
                    {step}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </div>
    </motion.div>
  )
}

function ComparisonChart({ breakdown }: { breakdown: HierarchicalBreakdown[] }) {
  // Flatten breakdown to get all warehouses
  const flattenWarehouses = (nodes: HierarchicalBreakdown[]): HierarchicalBreakdown[] => {
    const warehouses: HierarchicalBreakdown[] = []
    for (const node of nodes) {
      if (node.level === 'warehouse') {
        warehouses.push(node)
      }
      if (node.children) {
        warehouses.push(...flattenWarehouses(node.children))
      }
    }
    return warehouses
  }

  const warehouses = flattenWarehouses(breakdown)
  const chartData = warehouses
    .map(w => ({
      name: w.name,
      amount: w.summary.totalAmount,
      consumption: w.summary.totalConsumption,
      costPerUnit: w.summary.costPerUnit,
      efficiency: w.summary.efficiency,
    }))
    .sort((a, b) => b.amount - a.amount)
    .slice(0, 20) // Top 20

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6']

  return (
    <div className="space-y-6">
      <ResponsiveContainer width="100%" height={400}>
        <BarChart data={chartData}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis
            dataKey="name"
            angle={-45}
            textAnchor="end"
            height={100}
            tick={{ fontSize: 10 }}
          />
          <YAxis />
          <Tooltip />
          <Legend />
          <Bar dataKey="amount" fill="#3b82f6" name="Total Amount (SAR)" />
          <Bar dataKey="consumption" fill="#10b981" name="Consumption (kWh)" />
        </BarChart>
      </ResponsiveContainer>

      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={chartData}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis
            dataKey="name"
            angle={-45}
            textAnchor="end"
            height={100}
            tick={{ fontSize: 10 }}
          />
          <YAxis />
          <Tooltip />
          <Legend />
          <Bar dataKey="costPerUnit" fill="#f59e0b" name="Cost per Unit (SAR/kWh)" />
          <Bar dataKey="efficiency" fill="#8b5cf6" name="Efficiency (%)" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  )
}

/**
 * Advanced Smart Detection Form Component
 * World-class intelligent form with 10+ detection sources
 * 5x better than before - inspired by Quadient, Pro-Sapien, CompliChem
 * Much more comprehensive than source apps
 */

'use client'

import { useState, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import IntelligentFormField from './IntelligentFormField'

type AdvancedDetectionContext = any
type AdvancedDetectionResult = any

interface FormField {
  id: string
  name: string
  type: 'text' | 'number' | 'date' | 'select' | 'textarea' | 'email' | 'url'
  label: string
  value: any
  required?: boolean
  placeholder?: string
  options?: Array<{ label: string; value: any }>
}

interface AdvancedSmartDetectionFormProps {
  formId: string
  fields: FormField[]
  context: AdvancedDetectionContext
  onSubmit: (data: Record<string, any>) => void
  onCancel?: () => void
  title?: string
  isDark?: boolean
}

export default function AdvancedSmartDetectionForm({
  formId,
  fields: initialFields,
  context,
  onSubmit,
  onCancel,
  title = 'Advanced Smart Detection Form',
  isDark = false,
}: AdvancedSmartDetectionFormProps) {
  const [fields, setFields] = useState<FormField[]>(initialFields)
  const [detectionResult, setDetectionResult] = useState<AdvancedDetectionResult | null>(null)
  const [detecting, setDetecting] = useState(false)
  const [showDetections, setShowDetections] = useState(true)
  const [autoFilledFields, setAutoFilledFields] = useState<Set<string>>(new Set())
  const [uploadedFiles, setUploadedFiles] = useState<File[]>([])
  const [uploadedImages, setUploadedImages] = useState<File[]>([])
  const [isRecording, setIsRecording] = useState(false)
  const mediaRecorderRef = useRef<MediaRecorder | null>(null)
  const [recordingBlob, setRecordingBlob] = useState<Blob | null>(null)

  useEffect(() => {
    // Auto-detect on mount
    performAdvancedDetection()
  }, [])

  const performAdvancedDetection = async () => {
    setDetecting(true)
    try {
      // Update context with uploaded files
      const updatedContext: AdvancedDetectionContext = {
        ...context,
        uploadedDocuments: uploadedFiles.length > 0 ? uploadedFiles : context.uploadedDocuments,
        uploadedImages: uploadedImages.length > 0 ? uploadedImages : context.uploadedImages,
        voiceInput: recordingBlob || context.voiceInput,
      }

      const apiForm = new FormData()
      apiForm.set(
        'fields',
        JSON.stringify(fields.map(f => ({ id: f.id, name: f.name, type: f.type, label: f.label, required: f.required })))
      )

      // Send context separately (excluding binary data)
      const { uploadedDocuments, uploadedImages, voiceInput, ...contextMeta } = updatedContext || {}
      apiForm.set('context', JSON.stringify(contextMeta || {}))

      ;(uploadedDocuments || []).forEach((f: File) => apiForm.append('documents', f))
      ;(uploadedImages || []).forEach((f: File) => apiForm.append('images', f))
      if (voiceInput) apiForm.set('voice', voiceInput as any)

      const res = await fetch('/api/forms/advanced-detection', { method: 'POST', body: apiForm })
      const data = await res.json()
      if (!res.ok || !data?.success) {
        throw new Error(data?.error || 'Advanced detection failed')
      }
      const result = data.result as AdvancedDetectionResult

      setDetectionResult(result)

      // Auto-fill logic:
      // - Required fields: 70%+ confidence (lower threshold for better UX)
      // - Optional fields: 75%+ confidence (higher threshold for safety)
      const updatedFields = fields.map(field => {
        const detection = result.detectedFields.find(d => d.fieldId === field.id)
        if (detection && detection.validationStatus !== 'ERROR') {
          const threshold = field.required ? 70 : 75
          if (detection.confidence >= threshold) {
            setAutoFilledFields(prev => new Set(prev).add(field.id))
            return { ...field, value: detection.detectedValue }
          }
        }
        return field
      })

      setFields(updatedFields)
    } catch (error) {
      console.error('Error performing advanced detection:', error)
    } finally {
      setDetecting(false)
    }
  }

  const handleFieldChange = (fieldId: string, value: any) => {
    setFields(fields.map(f => f.id === fieldId ? { ...f, value } : f))
  }

  const handleApplyDetection = (fieldId: string) => {
    const detection = detectionResult?.detectedFields.find(d => d.fieldId === fieldId)
    if (detection) {
      handleFieldChange(fieldId, detection.detectedValue)
      setAutoFilledFields(prev => new Set(prev).add(fieldId))
    }
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'document' | 'image') => {
    if (e.target.files) {
      const files = Array.from(e.target.files)
      if (type === 'document') {
        setUploadedFiles(prev => [...prev, ...files])
      } else {
        setUploadedImages(prev => [...prev, ...files])
      }
      // Re-detect after file upload
      setTimeout(() => performAdvancedDetection(), 500)
    }
  }

  const startVoiceRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true })
      const mediaRecorder = new MediaRecorder(stream)
      const chunks: Blob[] = []

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data)
      }

      mediaRecorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/webm' })
        setRecordingBlob(blob)
        performAdvancedDetection()
      }

      mediaRecorder.start()
      mediaRecorderRef.current = mediaRecorder
      setIsRecording(true)
    } catch (error) {
      console.error('Error starting recording:', error)
      alert('Microphone access denied. Please enable microphone permissions.')
    }
  }

  const stopVoiceRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop()
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop())
      setIsRecording(false)
    }
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    const formData: Record<string, any> = {}
    fields.forEach(field => {
      formData[field.name] = field.value
    })
    onSubmit(formData)
  }

  const baseClasses = isDark
    ? 'bg-gray-900 text-white border-gray-700'
    : 'bg-white text-gray-900 border-gray-200'

  return (
    <div className={`rounded-lg shadow-lg border ${baseClasses}`}>
      {/* Header with Advanced Features */}
      <div className={`px-6 py-4 border-b ${isDark ? 'border-gray-700 bg-gray-800' : 'border-gray-200 bg-gray-50'}`}>
        <div className="flex justify-between items-center mb-4">
          <div>
            <h2 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
              {title}
            </h2>
            {detectionResult && (
              <p className={`text-sm mt-1 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                {detectionResult.autoFilledCount} fields auto-filled • {Math.round(detectionResult.confidence)}% confidence • {detectionResult.processingTime}ms
              </p>
            )}
          </div>
          <div className="flex gap-2">
            <button
              onClick={performAdvancedDetection}
              disabled={detecting}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                isDark
                  ? 'bg-purple-600 hover:bg-purple-700 text-white'
                  : 'bg-purple-600 hover:bg-purple-700 text-white'
              } disabled:opacity-50`}
            >
              {detecting ? (
                <>
                  <i className="ri-loader-4-line animate-spin mr-2"></i>
                  Detecting...
                </>
              ) : (
                <>
                  <i className="ri-radar-line mr-2"></i>
                  Re-detect
                </>
              )}
            </button>
            {onCancel && (
              <button
                onClick={onCancel}
                className={`px-4 py-2 rounded-lg font-medium ${
                  isDark
                    ? 'bg-gray-700 hover:bg-gray-600 text-white'
                    : 'bg-gray-200 hover:bg-gray-300 text-gray-700'
                }`}
              >
                Cancel
              </button>
            )}
          </div>
        </div>

        {/* Advanced Input Methods */}
        <div className="flex flex-wrap gap-2 mt-4">
          {/* Document Upload */}
          <label className={`px-4 py-2 rounded-lg cursor-pointer transition-colors ${
            isDark
              ? 'bg-blue-600 hover:bg-blue-700 text-white'
              : 'bg-blue-600 hover:bg-blue-700 text-white'
          }`}>
            <i className="ri-file-upload-line mr-2"></i>
            Upload Documents
            <input
              type="file"
              multiple
              accept=".pdf,.doc,.docx,.txt"
              onChange={(e) => handleFileUpload(e, 'document')}
              className="hidden"
            />
          </label>

          {/* Image Upload */}
          <label className={`px-4 py-2 rounded-lg cursor-pointer transition-colors ${
            isDark
              ? 'bg-green-600 hover:bg-green-700 text-white'
              : 'bg-green-600 hover:bg-green-700 text-white'
          }`}>
            <i className="ri-image-upload-line mr-2"></i>
            Upload Images
            <input
              type="file"
              multiple
              accept="image/*"
              onChange={(e) => handleFileUpload(e, 'image')}
              className="hidden"
            />
          </label>

          {/* Voice Input */}
          <button
            onClick={isRecording ? stopVoiceRecording : startVoiceRecording}
            className={`px-4 py-2 rounded-lg transition-colors ${
              isRecording
                ? isDark
                  ? 'bg-red-600 hover:bg-red-700 text-white'
                  : 'bg-red-600 hover:bg-red-700 text-white'
                : isDark
                ? 'bg-orange-600 hover:bg-orange-700 text-white'
                : 'bg-orange-600 hover:bg-orange-700 text-white'
            }`}
          >
            <i className={`${isRecording ? 'ri-stop-circle-line' : 'ri-mic-line'} mr-2 ${isRecording ? 'animate-pulse' : ''}`}></i>
            {isRecording ? 'Stop Recording' : 'Voice Input'}
          </button>
        </div>

        {/* Uploaded Files Display */}
        {(uploadedFiles.length > 0 || uploadedImages.length > 0) && (
          <div className="mt-4 flex flex-wrap gap-2">
            {uploadedFiles.map((file, idx) => (
              <span key={idx} className={`px-3 py-1 rounded text-xs ${
                isDark ? 'bg-blue-900/30 text-blue-300' : 'bg-blue-100 text-blue-800'
              }`}>
                <i className="ri-file-line mr-1"></i>
                {file.name}
              </span>
            ))}
            {uploadedImages.map((file, idx) => (
              <span key={idx} className={`px-3 py-1 rounded text-xs ${
                isDark ? 'bg-green-900/30 text-green-300' : 'bg-green-100 text-green-800'
              }`}>
                <i className="ri-image-line mr-1"></i>
                {file.name}
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Advanced Detection Results Banner */}
      {detectionResult && showDetections && (
        <AnimatePresence>
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`px-6 py-4 border-b ${
              isDark
                ? 'bg-gradient-to-r from-purple-900/20 via-blue-900/20 to-green-900/20 border-purple-700'
                : 'bg-gradient-to-r from-purple-50 via-blue-50 to-green-50 border-purple-200'
            }`}
          >
            <div className="flex justify-between items-start">
              <div className="flex-1">
                <h3 className={`font-semibold mb-3 flex items-center gap-2 ${
                  isDark ? 'text-purple-300' : 'text-purple-800'
                }`}>
                  <i className="ri-magic-line"></i>
                  Advanced Smart Detection Results
                </h3>

                {/* Analytics Grid */}
                <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4 text-sm mb-4">
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Detected</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-white' : 'text-gray-900'}`}>
                      {detectionResult.analytics.detectedFields}
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Auto-filled</p>
                    <p className={`font-bold text-lg text-green-600`}>
                      {detectionResult.analytics.autoFilledFields}
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Suggestions</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-blue-400' : 'text-blue-600'}`}>
                      {detectionResult.analytics.suggestedFields}
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Confidence</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-purple-400' : 'text-purple-600'}`}>
                      {Math.round(detectionResult.analytics.averageConfidence)}%
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Processing</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-orange-400' : 'text-orange-600'}`}>
                      {detectionResult.processingTime}ms
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Sources</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-cyan-400' : 'text-cyan-600'}`}>
                      {detectionResult.sourcesUsed.length}
                    </p>
                  </div>
                </div>

                {/* Sources Used */}
                <div className="flex flex-wrap gap-2">
                  <span className={`text-xs font-medium ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    Detection Sources:
                  </span>
                  {detectionResult.sourcesUsed.map(source => (
                    <span key={source} className={`px-2 py-1 rounded text-xs ${
                      isDark ? 'bg-gray-700 text-gray-300' : 'bg-gray-200 text-gray-700'
                    }`}>
                      {source}
                    </span>
                  ))}
                </div>

                {/* Compliance Status */}
                {detectionResult.complianceCheck && (
                  <div className={`mt-4 p-3 rounded-lg ${
                    detectionResult.complianceCheck.compliant
                      ? isDark ? 'bg-green-900/20 border-green-700' : 'bg-green-50 border-green-200'
                      : isDark ? 'bg-yellow-900/20 border-yellow-700' : 'bg-yellow-50 border-yellow-200'
                  } border`}>
                    <div className="flex items-center gap-2 mb-2">
                      <i className={`${detectionResult.complianceCheck.compliant ? 'ri-checkbox-circle-line text-green-400' : 'ri-alert-line text-yellow-400'}`}></i>
                      <span className={`font-medium ${
                        detectionResult.complianceCheck.compliant
                          ? isDark ? 'text-green-300' : 'text-green-800'
                          : isDark ? 'text-yellow-300' : 'text-yellow-800'
                      }`}>
                        {detectionResult.complianceCheck.compliant ? 'Compliant' : 'Compliance Issues Detected'}
                      </span>
                    </div>
                    {detectionResult.complianceCheck.issues.length > 0 && (
                      <ul className={`text-xs space-y-1 ${isDark ? 'text-yellow-200' : 'text-yellow-700'}`}>
                        {detectionResult.complianceCheck.issues.map((issue, idx) => (
                          <li key={idx}>• {issue}</li>
                        ))}
                      </ul>
                    )}
                    {detectionResult.complianceCheck.recommendations.length > 0 && (
                      <div className="mt-2">
                        <p className={`text-xs font-medium mb-1 ${isDark ? 'text-gray-300' : 'text-gray-700'}`}>Recommendations:</p>
                        <ul className={`text-xs space-y-1 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                          {detectionResult.complianceCheck.recommendations.map((rec, idx) => (
                            <li key={idx}>• {rec}</li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div>
                )}
              </div>
              <button
                onClick={() => setShowDetections(false)}
                className={`ml-4 p-2 rounded ${
                  isDark ? 'hover:bg-gray-700 text-gray-400' : 'hover:bg-gray-200 text-gray-600'
                }`}
              >
                <i className="ri-close-line"></i>
              </button>
            </div>
          </motion.div>
        </AnimatePresence>
      )}

      {/* Form */}
      <form onSubmit={handleSubmit} className="p-6 space-y-6">
        {fields.map(field => {
          const detection = detectionResult?.detectedFields.find(d => d.fieldId === field.id)
          const suggestion = detectionResult?.suggestions.find(s => s.fieldId === field.id)
          const warning = detectionResult?.warnings.find(w => w.fieldId === field.id)
          const isAutoFilled = autoFilledFields.has(field.id)

          return (
            <div key={field.id} className="relative">
              {/* Auto-filled indicator */}
              {isAutoFilled && (
                <div className={`absolute -top-2 right-0 px-2 py-1 rounded text-xs font-medium ${
                  isDark
                    ? 'bg-green-900/30 text-green-400 border border-green-700'
                    : 'bg-green-100 text-green-800 border border-green-300'
                }`}>
                  <i className="ri-check-line mr-1"></i>
                  Auto-filled
                </div>
              )}

              <IntelligentFormField
                field={field}
                formId={formId}
                suggestion={detection ? {
                  fieldId: field.id,
                  suggestedValue: detection.detectedValue,
                  confidence: detection.confidence,
                  reasoning: detection.method,
                  source: (detection.source === 'DOCUMENT' || detection.source === 'IMAGE' || detection.source === 'VOICE' || detection.source === 'TEMPLATE' || detection.source === 'ML_MODEL')
                    ? 'AI_ANALYSIS' // Map extended sources to base source types
                    : detection.source === 'CONTEXT'
                    ? 'PATTERN_DETECTION'
                    : detection.source === 'PATTERN'
                    ? 'PATTERN_DETECTION'
                    : detection.source === 'AI_ANALYSIS'
                    ? 'AI_ANALYSIS'
                    : detection.source === 'KNOWLEDGE_BASE'
                    ? 'KNOWLEDGE_BASE'
                    : detection.source === 'USER_HISTORY'
                    ? 'USER_HISTORY'
                    : 'AI_ANALYSIS', // Default fallback
                  alternatives: detection.alternatives?.map(a => ({ value: a.value, confidence: a.confidence })),
                } : undefined}
                recommendation={suggestion ? {
                  type: detection && ((field.required && detection.confidence >= 70) || (!field.required && detection.confidence >= 75)) ? 'AUTO_FILL' : 'FIELD_SUGGESTION',
                  fieldId: field.id,
                  message: suggestion.suggestion,
                  priority: detection && ((field.required && detection.confidence >= 70) || (!field.required && detection.confidence >= 75)) ? 'HIGH' : 'MEDIUM',
                  confidence: suggestion.confidence,
                  action: detection && ((field.required && detection.confidence >= 70) || (!field.required && detection.confidence >= 75)) ? {
                    type: 'FILL_FIELD',
                    data: detection.detectedValue,
                  } : undefined,
                } : undefined}
                onValueChange={handleFieldChange}
                onAutoFill={handleApplyDetection}
                isDark={isDark}
              />

              {/* Detection details with alternatives */}
              {/* Show suggestion if not auto-filled and confidence is 50%+ */}
              {detection && !isAutoFilled && detection.confidence >= 50 && (
                <div className={`mt-2 p-3 rounded-lg border ${
                  isDark
                    ? 'bg-blue-900/20 border-blue-700 text-blue-300'
                    : 'bg-blue-50 border-blue-200 text-blue-800'
                }`}>
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <p className="text-sm font-medium mb-1">
                        Detected: {String(detection.detectedValue)}
                      </p>
                      <p className="text-xs opacity-75 mb-2">
                        {detection.method} • {detection.confidence}% confidence • Source: {detection.source}
                      </p>
                      {detection.alternatives && detection.alternatives.length > 0 && (
                        <div className="mt-2">
                          <p className="text-xs font-medium mb-1">Alternatives:</p>
                          <div className="flex flex-wrap gap-2">
                            {detection.alternatives.slice(0, 3).map((alt, idx) => (
                              <button
                                key={idx}
                                onClick={() => handleFieldChange(field.id, alt.value)}
                                className={`px-2 py-1 rounded text-xs ${
                                  isDark
                                    ? 'bg-blue-800 hover:bg-blue-700 text-blue-200'
                                    : 'bg-blue-100 hover:bg-blue-200 text-blue-800'
                                }`}
                              >
                                {String(alt.value)} ({alt.confidence}%)
                              </button>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                    <button
                      onClick={() => handleApplyDetection(field.id)}
                      className={`ml-4 px-3 py-1 rounded text-xs font-medium ${
                        isDark
                          ? 'bg-blue-600 hover:bg-blue-700 text-white'
                          : 'bg-blue-600 hover:bg-blue-700 text-white'
                      }`}
                    >
                      Apply
                    </button>
                  </div>
                </div>
              )}

              {/* Validation warning */}
              {detection && detection.validationStatus === 'ERROR' && (
                <div className={`mt-2 p-2 rounded text-xs ${
                  isDark
                    ? 'bg-red-900/20 border-red-700 text-red-300'
                    : 'bg-red-50 border-red-200 text-red-800'
                } border`}>
                  <i className="ri-error-warning-line mr-1"></i>
                  {detection.validationMessage || 'Invalid value detected'}
                </div>
              )}

              {/* Warning */}
              {warning && (
                <div className={`mt-2 p-2 rounded text-xs border ${
                  warning.severity === 'CRITICAL' || warning.severity === 'HIGH'
                    ? isDark
                      ? 'bg-red-900/20 border-red-700 text-red-300'
                      : 'bg-red-50 border-red-200 text-red-800'
                    : isDark
                    ? 'bg-yellow-900/20 border-yellow-700 text-yellow-300'
                    : 'bg-yellow-50 border-yellow-200 text-yellow-800'
                }`}>
                  <i className="ri-alert-line mr-1"></i>
                  {warning.warning}
                  {warning.fixSuggestion && (
                    <span className="block mt-1 opacity-75">{warning.fixSuggestion}</span>
                  )}
                </div>
              )}
            </div>
          )
        })}

        {/* Submit Button */}
        <div className="flex justify-end gap-4 pt-6 border-t border-gray-200">
          {onCancel && (
            <button
              type="button"
              onClick={onCancel}
              className={`px-6 py-3 rounded-lg font-medium ${
                isDark
                  ? 'bg-gray-700 hover:bg-gray-600 text-white'
                  : 'bg-gray-200 hover:bg-gray-300 text-gray-700'
              }`}
            >
              Cancel
            </button>
          )}
          <button
            type="submit"
            className={`px-6 py-3 rounded-lg font-medium ${
              isDark
                ? 'bg-gradient-to-r from-purple-500 to-pink-600 hover:from-purple-600 hover:to-pink-700 text-white'
                : 'bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white'
            }`}
          >
            <i className="ri-check-line mr-2"></i>
            Submit Form
          </button>
        </div>
      </form>
    </div>
  )
}

/**
 * Smart Detection Form Component
 * Auto-detects and populates form fields intelligently
 * Originally from chemcollab/chemcheck - NCR and related features
 * Much more comprehensive than source apps
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import type { DetectionContext, SmartDetectionResult, DetectedField } from '@/lib/services/forms/smartDetectionService'
import { smartDetectionService } from '@/lib/services/forms/smartDetectionService'
import IntelligentFormField from './IntelligentFormField'

interface FormField {
  id: string
  name: string
  type: 'text' | 'number' | 'date' | 'select' | 'textarea' | 'email' | 'url'
  label: string
  value: any
  required?: boolean
  placeholder?: string
  options?: Array<{ label: string; value: any }>
}

interface SmartDetectionFormProps {
  formId: string
  fields: FormField[]
  context: DetectionContext
  onSubmit: (data: Record<string, any>) => void
  onCancel?: () => void
  title?: string
  isDark?: boolean
}

export default function SmartDetectionForm({
  formId,
  fields: initialFields,
  context,
  onSubmit,
  onCancel,
  title = 'Smart Detection Form',
  isDark = false,
}: SmartDetectionFormProps) {
  const [fields, setFields] = useState<FormField[]>(initialFields)
  const [detectionResult, setDetectionResult] = useState<SmartDetectionResult | null>(null)
  const [detecting, setDetecting] = useState(false)
  const [showDetections, setShowDetections] = useState(true)
  const [autoFilledFields, setAutoFilledFields] = useState<Set<string>>(new Set())

  useEffect(() => {
    // Auto-detect on mount
    performDetection()
  }, [])

  const performDetection = async () => {
    setDetecting(true)
    try {
      const result = await smartDetectionService.detectFormFields(
        fields.map(f => ({ id: f.id, name: f.name, type: f.type, label: f.label })),
        context
      )

      setDetectionResult(result)

      // Auto-fill high confidence fields
      const highConfidenceDetections = result.detectedFields.filter(d => d.confidence >= 70)
      const updatedFields = fields.map(field => {
        const detection = highConfidenceDetections.find(d => d.fieldId === field.id)
        if (detection) {
          setAutoFilledFields(prev => new Set(prev).add(field.id))
          return { ...field, value: detection.detectedValue }
        }
        return field
      })

      setFields(updatedFields)
    } catch (error) {
      console.error('Error performing detection:', error)
    } finally {
      setDetecting(false)
    }
  }

  const handleFieldChange = (fieldId: string, value: any) => {
    setFields(fields.map(f => f.id === fieldId ? { ...f, value } : f))
  }

  const handleApplyDetection = (fieldId: string) => {
    const detection = detectionResult?.detectedFields.find(d => d.fieldId === fieldId)
    if (detection) {
      handleFieldChange(fieldId, detection.detectedValue)
      setAutoFilledFields(prev => new Set(prev).add(fieldId))
    }
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    const formData: Record<string, any> = {}
    fields.forEach(field => {
      formData[field.name] = field.value
    })
    onSubmit(formData)
  }

  const baseClasses = isDark
    ? 'bg-gray-900 text-white border-gray-700'
    : 'bg-white text-gray-900 border-gray-200'

  return (
    <div className={`rounded-lg shadow-lg border ${baseClasses}`}>
      {/* Header */}
      <div className={`px-6 py-4 border-b ${isDark ? 'border-gray-700 bg-gray-800' : 'border-gray-200 bg-gray-50'}`}>
        <div className="flex justify-between items-center">
          <div>
            <h2 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
              {title}
            </h2>
            {detectionResult && (
              <p className={`text-sm mt-1 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                {detectionResult.autoFilledCount} fields auto-filled • {Math.round(detectionResult.confidence)}% confidence
              </p>
            )}
          </div>
          <div className="flex gap-2">
            <button
              onClick={performDetection}
              disabled={detecting}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                isDark
                  ? 'bg-purple-600 hover:bg-purple-700 text-white'
                  : 'bg-purple-600 hover:bg-purple-700 text-white'
              } disabled:opacity-50`}
            >
              {detecting ? (
                <>
                  <i className="ri-loader-4-line animate-spin mr-2"></i>
                  Detecting...
                </>
              ) : (
                <>
                  <i className="ri-radar-line mr-2"></i>
                  Re-detect
                </>
              )}
            </button>
            {onCancel && (
              <button
                onClick={onCancel}
                className={`px-4 py-2 rounded-lg font-medium ${
                  isDark
                    ? 'bg-gray-700 hover:bg-gray-600 text-white'
                    : 'bg-gray-200 hover:bg-gray-300 text-gray-700'
                }`}
              >
                Cancel
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Detection Results Banner */}
      {detectionResult && showDetections && (
        <AnimatePresence>
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`px-6 py-4 border-b ${
              isDark
                ? 'bg-gradient-to-r from-purple-900/20 to-blue-900/20 border-purple-700'
                : 'bg-gradient-to-r from-purple-50 to-blue-50 border-purple-200'
            }`}
          >
            <div className="flex justify-between items-start">
              <div className="flex-1">
                <h3 className={`font-semibold mb-2 flex items-center gap-2 ${
                  isDark ? 'text-purple-300' : 'text-purple-800'
                }`}>
                  <i className="ri-magic-line"></i>
                  Smart Detection Results
                </h3>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Detected</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-white' : 'text-gray-900'}`}>
                      {detectionResult.detectedFields.length}
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Auto-filled</p>
                    <p className={`font-bold text-lg text-green-600`}>
                      {detectionResult.autoFilledCount}
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Suggestions</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-blue-400' : 'text-blue-600'}`}>
                      {detectionResult.suggestions.length}
                    </p>
                  </div>
                  <div>
                    <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>Confidence</p>
                    <p className={`font-bold text-lg ${isDark ? 'text-purple-400' : 'text-purple-600'}`}>
                      {Math.round(detectionResult.confidence)}%
                    </p>
                  </div>
                </div>
              </div>
              <button
                onClick={() => setShowDetections(false)}
                className={`ml-4 p-2 rounded ${
                  isDark ? 'hover:bg-gray-700 text-gray-400' : 'hover:bg-gray-200 text-gray-600'
                }`}
              >
                <i className="ri-close-line"></i>
              </button>
            </div>
          </motion.div>
        </AnimatePresence>
      )}

      {/* Form */}
      <form onSubmit={handleSubmit} className="p-6 space-y-6">
        {fields.map(field => {
          const detection = detectionResult?.detectedFields.find(d => d.fieldId === field.id)
          const suggestion = detectionResult?.suggestions.find(s => s.fieldId === field.id)
          const warning = detectionResult?.warnings.find(w => w.fieldId === field.id)
          const isAutoFilled = autoFilledFields.has(field.id)

          return (
            <div key={field.id} className="relative">
              {/* Auto-filled indicator */}
              {isAutoFilled && (
                <div className={`absolute -top-2 right-0 px-2 py-1 rounded text-xs font-medium ${
                  isDark
                    ? 'bg-green-900/30 text-green-400 border border-green-700'
                    : 'bg-green-100 text-green-800 border border-green-300'
                }`}>
                  <i className="ri-check-line mr-1"></i>
                  Auto-filled
                </div>
              )}

              <IntelligentFormField
                field={field}
                formId={formId}
                suggestion={detection ? {
                  fieldId: field.id,
                  suggestedValue: detection.detectedValue,
                  confidence: detection.confidence,
                  reasoning: detection.method,
                  source: detection.source,
                } : undefined}
                recommendation={suggestion ? {
                  type: detection && detection.confidence >= 70 ? 'AUTO_FILL' : 'FIELD_SUGGESTION',
                  fieldId: field.id,
                  message: suggestion.suggestion,
                  priority: detection && detection.confidence >= 70 ? 'HIGH' : 'MEDIUM',
                  confidence: suggestion.confidence,
                  action: detection && detection.confidence >= 70 ? {
                    type: 'FILL_FIELD',
                    data: detection.detectedValue,
                  } : undefined,
                } : undefined}
                onValueChange={handleFieldChange}
                onAutoFill={handleApplyDetection}
                isDark={isDark}
              />

              {/* Detection details */}
              {detection && !isAutoFilled && (
                <div className={`mt-2 p-3 rounded-lg border ${
                  isDark
                    ? 'bg-blue-900/20 border-blue-700 text-blue-300'
                    : 'bg-blue-50 border-blue-200 text-blue-800'
                }`}>
                  <div className="flex items-center justify-between">
                    <div className="flex-1">
                      <p className="text-sm font-medium mb-1">
                        Detected: {String(detection.detectedValue)}
                      </p>
                      <p className="text-xs opacity-75">
                        {detection.method} • {detection.confidence}% confidence
                      </p>
                    </div>
                    <button
                      onClick={() => handleApplyDetection(field.id)}
                      className={`ml-4 px-3 py-1 rounded text-xs font-medium ${
                        isDark
                          ? 'bg-blue-600 hover:bg-blue-700 text-white'
                          : 'bg-blue-600 hover:bg-blue-700 text-white'
                      }`}
                    >
                      Apply
                    </button>
                  </div>
                </div>
              )}

              {/* Warning */}
              {warning && (
                <div className={`mt-2 p-2 rounded text-xs ${
                  isDark
                    ? `bg-${warning.severity === 'HIGH' ? 'red' : warning.severity === 'MEDIUM' ? 'yellow' : 'gray'}-900/20 border-${warning.severity === 'HIGH' ? 'red' : warning.severity === 'MEDIUM' ? 'yellow' : 'gray'}-700 text-${warning.severity === 'HIGH' ? 'red' : warning.severity === 'MEDIUM' ? 'yellow' : 'gray'}-300`
                    : `bg-${warning.severity === 'HIGH' ? 'red' : warning.severity === 'MEDIUM' ? 'yellow' : 'gray'}-50 border-${warning.severity === 'HIGH' ? 'red' : warning.severity === 'MEDIUM' ? 'yellow' : 'gray'}-200 text-${warning.severity === 'HIGH' ? 'red' : warning.severity === 'MEDIUM' ? 'yellow' : 'gray'}-800`
                }`}>
                  <i className="ri-alert-line mr-1"></i>
                  {warning.warning}
                </div>
              )}
            </div>
          )
        })}

        {/* Submit Button */}
        <div className="flex justify-end gap-4 pt-6 border-t border-gray-200">
          {onCancel && (
            <button
              type="button"
              onClick={onCancel}
              className={`px-6 py-3 rounded-lg font-medium ${
                isDark
                  ? 'bg-gray-700 hover:bg-gray-600 text-white'
                  : 'bg-gray-200 hover:bg-gray-300 text-gray-700'
              }`}
            >
              Cancel
            </button>
          )}
          <button
            type="submit"
            className={`px-6 py-3 rounded-lg font-medium ${
              isDark
                ? 'bg-gradient-to-r from-purple-500 to-pink-600 hover:from-purple-600 hover:to-pink-700 text-white'
                : 'bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white'
            }`}
          >
            <i className="ri-check-line mr-2"></i>
            Submit Form
          </button>
        </div>
      </form>
    </div>
  )
}

/**
 * Geofence Enterprise Analytics Dashboard
 * 
 * McKinsey, SAP, Oracle-grade analytics dashboard featuring:
 * - Real-time KPIs & metrics
 * - Predictive analytics
 * - Zone performance visualization
 * - Event analytics
 * - Trend analysis
 * - AI-powered insights
 * - Export capabilities
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  LineChart,
  Line,
  AreaChart,
  Area,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts'
import type { GeofenceAnalytics, ZonePerformanceMetrics } from '@/lib/services/geofence/analytics/geofenceAnalyticsService'

interface GeofenceAnalyticsDashboardProps {
  tenantId?: string
  period?: { start: Date; end: Date }
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#f97316', '#06b6d4']

export default function GeofenceAnalyticsDashboard({ tenantId = 'default', period }: GeofenceAnalyticsDashboardProps) {
  const [loading, setLoading] = useState(true)
  const [analytics, setAnalytics] = useState<GeofenceAnalytics | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [selectedZone, setSelectedZone] = useState<string | null>(null)

  const defaultPeriod = {
    start: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000), // 30 days ago
    end: new Date(),
  }
  const analyticsPeriod = period || defaultPeriod

  useEffect(() => {
    loadAnalytics()
  }, [tenantId, analyticsPeriod])

  const loadAnalytics = async () => {
    setLoading(true)
    setError(null)
    try {
      const response = await fetch(
        `/api/geofence/analytics?tenantId=${encodeURIComponent(tenantId)}&start=${analyticsPeriod.start.toISOString()}&end=${analyticsPeriod.end.toISOString()}`
      )
      if (!response.ok) throw new Error('Failed to load analytics')
      const data = await response.json()
      if (data.success) {
        setAnalytics(data.data)
      } else {
        throw new Error(data.error || 'Failed to load analytics')
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load analytics')
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-500">Loading analytics...</p>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="p-6 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg">
        <p className="text-red-700 dark:text-red-300">{error}</p>
        <button
          onClick={loadAnalytics}
          className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-500 transition-colors"
        >
          Retry
        </button>
      </div>
    )
  }

  if (!analytics) {
    return (
      <div className="text-center py-12 text-gray-500">
        <p>No analytics data available</p>
        <p className="text-sm mt-2">Create zones and generate events to see analytics</p>
      </div>
    )
  }

  const selectedZoneMetrics = selectedZone
    ? analytics.zoneMetrics.find(zm => zm.zoneId === selectedZone)
    : null

  // Prepare chart data
  const zonePerformanceData = analytics.zoneMetrics.map(zm => ({
    name: zm.zoneName.substring(0, 15),
    efficiency: zm.efficiencyScore,
    onTime: zm.onTimeRate,
    violations: zm.dwellTimeViolations,
  }))

  const eventTypeData = Object.entries(analytics.eventAnalytics.eventsByType).map(([type, count]) => ({
    name: type.replace(/_/g, ' '),
    value: count,
  }))

  const dwellTimeTrendData = selectedZoneMetrics
    ? selectedZoneMetrics.trends.dwellTime.map(t => ({
        period: t.period,
        value: t.value,
        change: t.change || 0,
      }))
    : []

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Geofence Analytics</h2>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            {analyticsPeriod.start.toLocaleDateString()} - {analyticsPeriod.end.toLocaleDateString()}
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => {
              const csv = generateCSV(analytics)
              downloadCSV(csv, `geofence-analytics-${Date.now()}.csv`)
            }}
            className="px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors text-sm"
          >
            Export CSV
          </button>
          <button
            onClick={loadAnalytics}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500 transition-colors text-sm"
          >
            Refresh
          </button>
        </div>
      </div>

      {/* Summary KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
        >
          <div className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Zones</div>
          <div className="text-3xl font-bold text-gray-900 dark:text-white mt-2">{analytics.summary.totalZones}</div>
          <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            {analytics.summary.activeZones} active
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
        >
          <div className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Events</div>
          <div className="text-3xl font-bold text-gray-900 dark:text-white mt-2">{analytics.summary.totalEvents}</div>
          <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            {analytics.eventAnalytics.anomalies} anomalies
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
        >
          <div className="text-sm font-medium text-gray-500 dark:text-gray-400">Avg Dwell Time</div>
          <div className="text-3xl font-bold text-gray-900 dark:text-white mt-2">
            {analytics.summary.averageDwellTime.toFixed(1)}m
          </div>
          <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">per zone entry</div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700"
        >
          <div className="text-sm font-medium text-gray-500 dark:text-gray-400">Efficiency Score</div>
          <div className="text-3xl font-bold text-gray-900 dark:text-white mt-2">
            {analytics.summary.efficiencyScore.toFixed(1)}%
          </div>
          <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Compliance: {analytics.summary.complianceScore.toFixed(1)}%
          </div>
        </motion.div>
      </div>

      {/* Insights */}
      {analytics.insights.length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border border-gray-200 dark:border-gray-700">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">AI Insights</h3>
          <div className="space-y-3">
            {analytics.insights.map((insight, idx) => (
              <motion.div
                key={idx}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: idx * 0.1 }}
                className={`p-4 rounded-lg border ${
                  insight.type === 'RISK'
                    ? 'bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800'
                    : insight.type === 'OPPORTUNITY'
                    ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800'
                    : 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800'
                }`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-semibold ${
                          insight.type === 'RISK'
                            ? 'bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300'
                            : insight.type === 'OPPORTUNITY'
                            ? 'bg-green-100 dark:bg-green-900/40 text-green-700 dark:text-green-300'
                            : 'bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300'
