                    <th className="text-right py-2 px-4 text-gray-700 dark:text-gray-300">Entries</th>
                    <th className="text-right py-2 px-4 text-gray-700 dark:text-gray-300">Exits</th>
                    <th className="text-right py-2 px-4 text-gray-700 dark:text-gray-300">Avg Dwell</th>
