                      <td className="py-2 px-4 text-right text-gray-600 dark:text-gray-400">{zm.totalEntries}</td>
                      <td className="py-2 px-4 text-right text-gray-600 dark:text-gray-400">{zm.totalExits}</td>
                      <td className="py-2 px-4 text-right text-gray-600 dark:text-gray-400">
