/**
 * Generic Site Iframe Widget
 */
export function GenericSiteWidget({ integration }: IntegrationWidgetProps) {
  const config = integration.config as any
  const url = config.url || ''
  const iframeConfig = config.iframeConfig || {}

  if (!url) {
    return (
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6 flex items-center justify-center h-full">
        <p className="text-gray-400">No URL configured</p>
      </div>
    )
  }

  return (
    <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6 h-full flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
          <div className="bg-purple-500 p-2 rounded-lg text-white">
            <FiGlobe />
          </div>
          <div>
            <h3 className="font-semibold text-white">Embedded Site</h3>
            <p className="text-xs text-gray-400">{integration.name}</p>
          </div>
        </div>
        <a
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="p-2 hover:bg-white/10 rounded-lg transition-colors"
        >
          <FiExternalLink className="text-gray-400" />
        </a>
      </div>

      <div className="flex-1 rounded-lg overflow-hidden border border-white/10">
        <iframe
          src={url}
          className="w-full h-full border-0"
          style={{
            width: iframeConfig.width || '100%',
            height: iframeConfig.height || '100%',
            minHeight: '400px'
          }}
          allowFullScreen={iframeConfig.allowFullscreen !== false}
          sandbox={iframeConfig.sandbox?.join(' ') || 'allow-same-origin allow-scripts allow-forms'}
          title={integration.name}
        />
      </div>
    </div>
  )
}

/**
 * Integration Widget Router
 * Routes to appropriate widget based on integration type
 */
export function IntegrationWidget({ integration, onRefresh }: IntegrationWidgetProps) {
  switch (integration.type) {
    case 'LINKEDIN':
      return <LinkedInFeedWidget integration={integration} onRefresh={onRefresh} />
    case 'TELEGRAM':
      return <TelegramMessagesWidget integration={integration} onRefresh={onRefresh} />
    case 'WHATSAPP':
      return <TelegramMessagesWidget integration={integration} onRefresh={onRefresh} />
    case 'NEWS_SITE':
    case 'RSS_FEED':
      return <NewsFeedWidget integration={integration} onRefresh={onRefresh} />
    case 'GENERIC_SITE':
    case 'IFRAME_EMBED':
      return <GenericSiteWidget integration={integration} onRefresh={onRefresh} />
    default:
      return (
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-6 flex items-center justify-center h-full">
          <p className="text-gray-400">Widget not available for this integration type</p>
        </div>
      )
  }
}

/**
 * IoT Analytics Panel Component
 * Display analytics and insights for IoT devices
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import type { IoTDevice, IoTComprehensiveAnalytics } from '@/types/iot'
import { iotAnalyticsService } from '@/lib/services/iot/iotAnalyticsService'
import { AdvancedIoTManager } from '@/lib/services/iot/iotManager'

export default function IoTAnalyticsPanel() {
  const [analytics, setAnalytics] = useState<IoTComprehensiveAnalytics | null>(null)
  const [loading, setLoading] = useState(true)
  const [manager] = useState(() => new AdvancedIoTManager())

  useEffect(() => {
    loadAnalytics()
  }, [])

  const loadAnalytics = async () => {
    setLoading(true)
    try {
      const devices = await manager.getAllDevices()
      const comprehensiveAnalytics = await iotAnalyticsService.calculateComprehensiveAnalytics(devices)
      setAnalytics(comprehensiveAnalytics)
    } catch (error) {
      console.error('Error loading analytics:', error)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return <div className="text-center py-12 text-[#9ca3af]">Loading analytics...</div>
  }

  if (!analytics) {
    return <div className="text-center py-12 text-[#9ca3af]">No analytics data available</div>
  }

  return (
    <div className="space-y-6">
      {/* Overview Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white/5 border border-white/10 rounded-xl p-4"
        >
          <div className="text-sm text-[#9ca3af] mb-1">Total Devices</div>
          <div className="text-2xl font-bold text-white">{analytics.totalDevices}</div>
        </motion.div>
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white/5 border border-white/10 rounded-xl p-4"
        >
          <div className="text-sm text-[#9ca3af] mb-1">Online</div>
          <div className="text-2xl font-bold text-green-400">{analytics.onlineDevices}</div>
        </motion.div>
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white/5 border border-white/10 rounded-xl p-4"
        >
          <div className="text-sm text-[#9ca3af] mb-1">Network Health</div>
          <div className="text-2xl font-bold text-cyan-400">{analytics.networkHealth.toFixed(1)}%</div>
        </motion.div>
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white/5 border border-white/10 rounded-xl p-4"
        >
          <div className="text-sm text-[#9ca3af] mb-1">Avg Health</div>
          <div className="text-2xl font-bold text-white">{analytics.averageHealth.toFixed(1)}%</div>
        </motion.div>
      </div>

      {/* Trends */}
      <div className="bg-white/5 border border-white/10 rounded-xl p-6">
        <h3 className="text-lg font-semibold text-white mb-4">Trends</h3>
        <div className="space-y-3">
          {analytics.trends.map((trend, index) => (
            <div key={index} className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <span className="text-white capitalize">{trend.metric.replace('_', ' ')}</span>
                <span className={`px-2 py-1 rounded text-xs ${
                  trend.trend === 'improving' ? 'bg-green-500/20 text-green-400' :
                  trend.trend === 'declining' ? 'bg-red-500/20 text-red-400' :
                  'bg-amber-500/20 text-amber-400'
                }`}>
                  {trend.trend}
                </span>
              </div>
              <span className="text-[#9ca3af]">
                {trend.changeRate > 0 ? '+' : ''}{trend.changeRate.toFixed(1)}%
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* Performance Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white/5 border border-white/10 rounded-xl p-4">
          <div className="text-sm text-[#9ca3af] mb-2">Data Transmission</div>
          <div className="text-xl font-bold text-white">
            {(analytics.totalDataTransmission / 1000).toFixed(2)} Gbps
          </div>
        </div>
        <div className="bg-white/5 border border-white/10 rounded-xl p-4">
          <div className="text-sm text-[#9ca3af] mb-2">Avg Latency</div>
          <div className="text-xl font-bold text-white">{analytics.averageLatency.toFixed(1)} ms</div>
        </div>
        <div className="bg-white/5 border border-white/10 rounded-xl p-4">
          <div className="text-sm text-[#9ca3af] mb-2">Power Efficiency</div>
          <div className="text-xl font-bold text-green-400">{analytics.powerEfficiency}%</div>
        </div>
      </div>
    </div>
  )
}

/**
 * IoT Device Manager Component
 * Manage and display IoT devices
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import IoTDeviceCard from './IoTDeviceCard'
import type { IoTDevice } from '@/types/iot'
import { AdvancedIoTManager } from '@/lib/services/iot/iotManager'

interface IoTDeviceManagerProps {
  onDeviceSelect?: (device: IoTDevice) => void
}

export default function IoTDeviceManager({ onDeviceSelect }: IoTDeviceManagerProps) {
  const [devices, setDevices] = useState<IoTDevice[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<'all' | 'online' | 'offline'>('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [manager] = useState(() => new AdvancedIoTManager())

  useEffect(() => {
    loadDevices()
  }, [])

  const loadDevices = async () => {
    setLoading(true)
    try {
      const allDevices = await manager.getAllDevices()
      setDevices(allDevices)
    } catch (error) {
      console.error('Error loading devices:', error)
    } finally {
      setLoading(false)
    }
  }

  const filteredDevices = devices.filter(device => {
    const matchesFilter = filter === 'all' || 
      (filter === 'online' && device.status.operational === 'online') ||
      (filter === 'offline' && device.status.operational === 'offline')
    
    const matchesSearch = device.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      device.type.toLowerCase().includes(searchQuery.toLowerCase()) ||
      device.category.toLowerCase().includes(searchQuery.toLowerCase())

    return matchesFilter && matchesSearch
  })

  const handleDiscover = async () => {
    setLoading(true)
    try {
      const result = await manager.discoverDevices()
      await loadDevices()
    } catch (error) {
      console.error('Error discovering devices:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="space-y-4">
      {/* Header Actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3 flex-1">
          <div className="relative flex-1 max-w-md">
            <i className="ri-search-line absolute left-3 top-1/2 transform -translate-y-1/2 text-[#9ca3af]"></i>
            <input
              type="text"
              placeholder="Search devices..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-white/5 border border-white/10 rounded-lg text-sm text-white placeholder-[#6b7280] focus:outline-none focus:border-cyan-500"
            />
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setFilter('all')}
              className={`px-3 py-2 rounded-lg text-sm transition-colors ${
                filter === 'all' 
                  ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30' 
                  : 'bg-white/5 text-[#9ca3af] border border-white/10 hover:bg-white/10'
              }`}
            >
              All
            </button>
            <button
              onClick={() => setFilter('online')}
              className={`px-3 py-2 rounded-lg text-sm transition-colors ${
                filter === 'online' 
                  ? 'bg-green-500/20 text-green-400 border border-green-500/30' 
                  : 'bg-white/5 text-[#9ca3af] border border-white/10 hover:bg-white/10'
              }`}
            >
              Online
            </button>
            <button
              onClick={() => setFilter('offline')}
              className={`px-3 py-2 rounded-lg text-sm transition-colors ${
                filter === 'offline' 
                  ? 'bg-red-500/20 text-red-400 border border-red-500/30' 
                  : 'bg-white/5 text-[#9ca3af] border border-white/10 hover:bg-white/10'
              }`}
            >
              Offline
            </button>
          </div>
        </div>
        <button
          onClick={handleDiscover}
          disabled={loading}
          className="px-4 py-2 bg-gradient-to-r from-cyan-500 to-blue-600 hover:from-cyan-600 hover:to-blue-700 text-white rounded-lg text-sm font-medium flex items-center gap-2 transition-colors disabled:opacity-50"
        >
          <i className="ri-radar-line"></i>
          Discover Devices
        </button>
      </div>

      {/* Device Grid */}
      {loading ? (
        <div className="text-center py-12 text-[#9ca3af]">Loading devices...</div>
      ) : filteredDevices.length === 0 ? (
        <div className="text-center py-12 text-[#9ca3af]">
          <i className="ri-sensor-line text-4xl mb-3 opacity-50"></i>
          <p>No devices found</p>
          <p className="text-sm mt-2">Try adjusting your filters or discover new devices</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredDevices.map((device) => (
            <IoTDeviceCard
              key={device.id}
              device={device}
              onClick={() => onDeviceSelect?.(device)}
            />
          ))}
        </div>
      )}

      {/* Stats */}
      <div className="grid grid-cols-3 gap-4 mt-6">
        <div className="bg-white/5 border border-white/10 rounded-lg p-4">
          <div className="text-sm text-[#9ca3af] mb-1">Total Devices</div>
          <div className="text-2xl font-bold text-white">{devices.length}</div>
        </div>
        <div className="bg-white/5 border border-white/10 rounded-lg p-4">
          <div className="text-sm text-[#9ca3af] mb-1">Online</div>
          <div className="text-2xl font-bold text-green-400">
            {devices.filter(d => d.status.operational === 'online').length}
          </div>
        </div>
        <div className="bg-white/5 border border-white/10 rounded-lg p-4">
          <div className="text-sm text-[#9ca3af] mb-1">Offline</div>
          <div className="text-2xl font-bold text-red-400">
            {devices.filter(d => d.status.operational === 'offline').length}
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * IoT Network Map Component
 * Visualize IoT device network topology
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import type { IoTDevice } from '@/types/iot'
import { AdvancedIoTManager } from '@/lib/services/iot/iotManager'

export default function IoTNetworkMap() {
  const [devices, setDevices] = useState<IoTDevice[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedDevice, setSelectedDevice] = useState<IoTDevice | null>(null)
  const [manager] = useState(() => new AdvancedIoTManager())

  useEffect(() => {
    loadDevices()
  }, [])

  const loadDevices = async () => {
    setLoading(true)
    try {
      const allDevices = await manager.getAllDevices()
      setDevices(allDevices)
    } catch (error) {
      console.error('Error loading devices:', error)
    } finally {
      setLoading(false)
    }
  }

  const gateways = devices.filter(d => d.type === 'gateway')
  const sensors = devices.filter(d => d.type === 'sensor')
  const edgeDevices = devices.filter(d => d.type === 'edge_compute')

  if (loading) {
    return <div className="text-center py-12 text-[#9ca3af]">Loading network map...</div>
  }

  return (
    <div className="space-y-6">
      {/* Network Overview */}
      <div className="grid grid-cols-3 gap-4">
        <div className="bg-white/5 border border-white/10 rounded-xl p-4">
          <div className="text-sm text-[#9ca3af] mb-1">Gateways</div>
          <div className="text-2xl font-bold text-cyan-400">{gateways.length}</div>
        </div>
        <div className="bg-white/5 border border-white/10 rounded-xl p-4">
          <div className="text-sm text-[#9ca3af] mb-1">Sensors</div>
          <div className="text-2xl font-bold text-green-400">{sensors.length}</div>
        </div>
        <div className="bg-white/5 border border-white/10 rounded-xl p-4">
          <div className="text-sm text-[#9ca3af] mb-1">Edge Devices</div>
          <div className="text-2xl font-bold text-amber-400">{edgeDevices.length}</div>
        </div>
      </div>

      {/* Network Visualization */}
      <div className="bg-white/5 border border-white/10 rounded-xl p-6">
        <h3 className="text-lg font-semibold text-white mb-4">Network Topology</h3>
        <div className="relative min-h-[400px] bg-[#0a0a0f] rounded-lg p-8">
          {/* Gateways */}
          <div className="absolute top-4 left-1/2 transform -translate-x-1/2">
            {gateways.map((gateway, index) => (
              <motion.div
                key={gateway.id}
                initial={{ opacity: 0, scale: 0 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: index * 0.1 }}
                onClick={() => setSelectedDevice(gateway)}
                className={`absolute w-16 h-16 bg-gradient-to-br from-cyan-500 to-blue-600 rounded-full flex items-center justify-center cursor-pointer border-2 ${
                  selectedDevice?.id === gateway.id ? 'border-yellow-400' : 'border-transparent'
                }`}
                style={{
                  left: `${(index - gateways.length / 2) * 100}px`
                }}
              >
                <i className="ri-router-line text-white text-xl"></i>
              </motion.div>
            ))}
          </div>

          {/* Sensors */}
          <div className="absolute bottom-4 left-0 right-0">
            <div className="flex justify-center gap-4 flex-wrap">
              {sensors.slice(0, 10).map((sensor, index) => (
                <motion.div
                  key={sensor.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: index * 0.05 }}
                  onClick={() => setSelectedDevice(sensor)}
                  className={`w-12 h-12 bg-gradient-to-br from-green-500 to-emerald-600 rounded-full flex items-center justify-center cursor-pointer border-2 ${
                    selectedDevice?.id === sensor.id ? 'border-yellow-400' : 'border-transparent'
                  }`}
                >
                  <i className="ri-sensor-line text-white"></i>
                </motion.div>
              ))}
            </div>
          </div>

          {/* Connection Lines */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none">
            {gateways.map((gateway, gIndex) =>
              sensors.slice(0, 3).map((sensor, sIndex) => (
                <line
                  key={`${gateway.id}-${sensor.id}`}
                  x1={`${50 + (gIndex - gateways.length / 2) * 6.25}%`}
                  y1="10%"
                  x2={`${10 + sIndex * 10}%`}
                  y2="80%"
                  stroke="rgba(6, 182, 212, 0.3)"
                  strokeWidth="1"
                  strokeDasharray="4,4"
                />
              ))
            )}
          </svg>
        </div>
      </div>

      {/* Selected Device Info */}
      {selectedDevice && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white/5 border border-white/10 rounded-xl p-6"
        >
          <h4 className="text-lg font-semibold text-white mb-4">{selectedDevice.name}</h4>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <div className="text-sm text-[#9ca3af] mb-1">Type</div>
              <div className="text-white">{selectedDevice.type}</div>
            </div>
            <div>
              <div className="text-sm text-[#9ca3af] mb-1">Protocol</div>
              <div className="text-white capitalize">{selectedDevice.connectivity.protocol}</div>
            </div>
            <div>
              <div className="text-sm text-[#9ca3af] mb-1">Status</div>
              <div className="text-white capitalize">{selectedDevice.status.operational}</div>
            </div>
            <div>
              <div className="text-sm text-[#9ca3af] mb-1">Health</div>
              <div className="text-white">{selectedDevice.status.health}%</div>
            </div>
          </div>
        </motion.div>
      )}
    </div>
  )
}

/**
 * Job Notification Component
 * 
 * Shows toast notifications for job status changes
 */

'use client'

import { useEffect } from 'react'
import { useJob } from '@/hooks/useJob'
import { JobStatus } from '@/types/job'
import { PremiumNotification } from '@/components/PremiumNotificationEnhanced'

interface JobNotificationProps {
  jobId: string
  onDismiss?: () => void
}

export function JobNotification({ jobId, onDismiss }: JobNotificationProps) {
  const { job } = useJob(jobId, { pollInterval: 3000 })

  useEffect(() => {
    if (!job) return

    // Show notification on status changes
    const statusMessages: Record<JobStatus, { title: string; message: string; type: 'success' | 'error' | 'info' | 'warning' }> = {
      COMPLETED: {
        title: 'Job Completed',
        message: `${job.name} has completed successfully`,
        type: 'success',
      },
      FAILED: {
        title: 'Job Failed',
        message: `${job.name} failed: ${job.error?.message || 'Unknown error'}`,
        type: 'error',
      },
      CANCELLED: {
        title: 'Job Cancelled',
        message: `${job.name} was cancelled`,
        type: 'warning',
      },
      RUNNING: {
        title: 'Job Started',
        message: `${job.name} is now running`,
        type: 'info',
      },
      PENDING: {
        title: 'Job Queued',
        message: `${job.name} has been queued`,
        type: 'info',
      },
      QUEUED: {
        title: 'Job Queued',
        message: `${job.name} is in queue`,
        type: 'info',
      },
      PAUSED: {
        title: 'Job Paused',
        message: `${job.name} has been paused`,
        type: 'warning',
      },
      RETRYING: {
        title: 'Job Retrying',
        message: `${job.name} is retrying after failure`,
        type: 'warning',
      },
    }

    const config = statusMessages[job.status]
    if (config) {
      // Use PremiumNotification to show the notification
      // This will be handled by the notification system
    }
  }, [job?.status, job?.name, job?.error])

  return null // This component doesn't render anything, it just triggers notifications
}

