/**
 * Load 3D Visualizer Component
 * 
 * Interactive 3D visualization of load plans
 * Shows item placements, utilization, and optimization
 */

'use client'

import { useEffect, useRef, useState } from 'react'
import type { LoadPlan, ItemPlacement } from '@/types/load-design'

interface Load3DVisualizerProps {
  loadPlan: LoadPlan
  showLabels?: boolean
  showGrid?: boolean
  interactive?: boolean
  onItemClick?: (itemId: string) => void
}

export default function Load3DVisualizer({
  loadPlan,
  showLabels = true,
  showGrid = true,
  interactive = true,
  onItemClick,
}: Load3DVisualizerProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [selectedItem, setSelectedItem] = useState<string | null>(null)
  const [viewAngle, setViewAngle] = useState({ x: 45, y: 45, z: 0 })
  const [zoom, setZoom] = useState(1)

  useEffect(() => {
    if (!canvasRef.current) return

    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    // Set canvas size
    canvas.width = canvas.offsetWidth
    canvas.height = canvas.offsetHeight

    // Draw 3D visualization
    drawLoadPlan(ctx, canvas.width, canvas.height)
  }, [loadPlan, viewAngle, zoom, selectedItem])

  const drawLoadPlan = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number
  ) => {
    // Clear canvas
    ctx.clearRect(0, 0, width, height)

    const { vehicleSpec, itemPlacements } = loadPlan
    const dims = vehicleSpec.dimensions

    // Calculate scale
    const scale = Math.min(
      (width * 0.8) / dims.length,
      (height * 0.8) / Math.max(dims.width, dims.height)
    ) * zoom

    // Center point
    const centerX = width / 2
    const centerY = height / 2

    // Draw vehicle outline (isometric projection)
    drawVehicleOutline(ctx, centerX, centerY, dims, scale)

    // Draw grid if enabled
    if (showGrid) {
      drawGrid(ctx, centerX, centerY, dims, scale)
    }

    // Draw items
    itemPlacements.forEach((placement) => {
      const isSelected = selectedItem === placement.itemId
      drawItem(ctx, centerX, centerY, placement, dims, scale, isSelected)
    })

    // Draw labels if enabled
    if (showLabels) {
      drawLabels(ctx, centerX, centerY, itemPlacements, dims, scale)
    }

    // Draw utilization info
    drawUtilizationInfo(ctx, width, height, loadPlan.utilization)
  }

  const drawVehicleOutline = (
    ctx: CanvasRenderingContext2D,
    centerX: number,
    centerY: number,
    dims: { length: number; width: number; height: number },
    scale: number
  ) => {
    ctx.strokeStyle = '#4a5568'
    ctx.lineWidth = 2
    ctx.setLineDash([])

    // Draw isometric box
    const l = dims.length * scale
    const w = dims.width * scale
    const h = dims.height * scale

    // Front face
    ctx.beginPath()
    ctx.moveTo(centerX - l / 2, centerY - h / 2)
    ctx.lineTo(centerX - l / 2 + w * 0.5, centerY - h / 2 - w * 0.3)
    ctx.lineTo(centerX + l / 2 + w * 0.5, centerY - h / 2 - w * 0.3)
    ctx.lineTo(centerX + l / 2, centerY - h / 2)
    ctx.closePath()
    ctx.stroke()

    // Back face
    ctx.beginPath()
    ctx.moveTo(centerX - l / 2, centerY + h / 2)
    ctx.lineTo(centerX - l / 2 + w * 0.5, centerY + h / 2 - w * 0.3)
    ctx.lineTo(centerX + l / 2 + w * 0.5, centerY + h / 2 - w * 0.3)
    ctx.lineTo(centerX + l / 2, centerY + h / 2)
    ctx.closePath()
    ctx.stroke()

    // Connect corners
    ctx.beginPath()
    ctx.moveTo(centerX - l / 2, centerY - h / 2)
    ctx.lineTo(centerX - l / 2, centerY + h / 2)
    ctx.moveTo(centerX + l / 2, centerY - h / 2)
    ctx.lineTo(centerX + l / 2, centerY + h / 2)
    ctx.stroke()
  }

  const drawGrid = (
    ctx: CanvasRenderingContext2D,
    centerX: number,
    centerY: number,
    dims: { length: number; width: number; height: number },
    scale: number
  ) => {
    ctx.strokeStyle = '#718096'
    ctx.lineWidth = 1
    ctx.setLineDash([2, 2])

    const gridSize = 50 // cm
    const l = dims.length * scale
    const w = dims.width * scale

    // Draw grid lines
    for (let i = 0; i <= dims.length; i += gridSize) {
      const x = centerX - l / 2 + (i * scale)
      ctx.beginPath()
      ctx.moveTo(x, centerY - dims.height * scale / 2)
      ctx.lineTo(x, centerY + dims.height * scale / 2)
      ctx.stroke()
    }

    for (let i = 0; i <= dims.width; i += gridSize) {
      const y = centerY - dims.height * scale / 2 + (i * scale)
      ctx.beginPath()
      ctx.moveTo(centerX - l / 2, y)
      ctx.lineTo(centerX + l / 2, y)
      ctx.stroke()
    }
  }

  const drawItem = (
    ctx: CanvasRenderingContext2D,
    centerX: number,
    centerY: number,
    placement: ItemPlacement,
    vehicleDims: { length: number; width: number; height: number },
    scale: number,
    isSelected: boolean
  ) => {
    const { position, dimensions } = placement

    // Calculate position in canvas coordinates
    const x = centerX - vehicleDims.length * scale / 2 + position.x * scale
    const y = centerY - vehicleDims.height * scale / 2 + position.y * scale
    const z = position.z * scale

    const l = dimensions.length * scale
    const w = dimensions.width * scale
    const h = dimensions.height * scale

    // Draw item box (isometric)
    ctx.fillStyle = isSelected ? '#4299e1' : '#48bb78'
    ctx.strokeStyle = isSelected ? '#2b6cb0' : '#2f855a'
    ctx.lineWidth = isSelected ? 3 : 1
    ctx.globalAlpha = isSelected ? 0.9 : 0.7

    // Draw isometric box
    ctx.beginPath()
    // Front face
    ctx.moveTo(x, y - z)
    ctx.lineTo(x + w * 0.5, y - z - w * 0.3)
    ctx.lineTo(x + l + w * 0.5, y - z - w * 0.3)
    ctx.lineTo(x + l, y - z)
    ctx.closePath()
    ctx.fill()
    ctx.stroke()

    // Top face
    ctx.beginPath()
    ctx.moveTo(x, y - z)
    ctx.lineTo(x + w * 0.5, y - z - w * 0.3)
    ctx.lineTo(x + w * 0.5, y - z - h - w * 0.3)
    ctx.lineTo(x, y - z - h)
    ctx.closePath()
    ctx.fill()
    ctx.stroke()

    ctx.globalAlpha = 1
  }

  const drawLabels = (
    ctx: CanvasRenderingContext2D,
    centerX: number,
    centerY: number,
    placements: ItemPlacement[],
    vehicleDims: { length: number; width: number; height: number },
    scale: number
  ) => {
    ctx.fillStyle = '#1a202c'
    ctx.font = '10px sans-serif'
    ctx.textAlign = 'center'

    placements.forEach((placement) => {
      const x = centerX - vehicleDims.length * scale / 2 + placement.position.x * scale
      const y = centerY - vehicleDims.height * scale / 2 + placement.position.y * scale - placement.position.z * scale

      ctx.fillText(placement.itemId.substring(0, 8), x + placement.dimensions.length * scale / 2, y - 5)
    })
  }

  const drawUtilizationInfo = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    utilization: LoadPlan['utilization']
  ) => {
    const infoX = width - 200
    const infoY = 20

    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)'
    ctx.fillRect(infoX - 10, infoY - 10, 190, 100)

    ctx.fillStyle = '#fff'
    ctx.font = 'bold 12px sans-serif'
    ctx.textAlign = 'left'
    ctx.fillText('Utilization', infoX, infoY)

    ctx.font = '11px sans-serif'
    ctx.fillText(`Weight: ${utilization.weightPercent.toFixed(1)}%`, infoX, infoY + 20)
    ctx.fillText(`Volume: ${utilization.volumePercent.toFixed(1)}%`, infoX, infoY + 40)
    ctx.fillText(`Space: ${utilization.spaceEfficiency.toFixed(1)}%`, infoX, infoY + 60)
  }

  const handleItemClick = (event: React.MouseEvent<HTMLCanvasElement>) => {
    if (!interactive || !onItemClick) return

    const canvas = canvasRef.current
    if (!canvas) return

    const rect = canvas.getBoundingClientRect()
    const x = event.clientX - rect.left
    const y = event.clientY - rect.top

    // Find clicked item (simplified - would need proper hit testing)
    // For now, just toggle selection
    setSelectedItem(selectedItem ? null : loadPlan.itemPlacements[0]?.itemId || null)
  }

  return (
    <div className="w-full h-full relative">
      <canvas
        ref={canvasRef}
        className="w-full h-full border border-gray-300 rounded-lg"
        onClick={handleItemClick}
        style={{ cursor: interactive ? 'pointer' : 'default' }}
      />
      
      {/* Controls */}
      <div className="absolute top-4 left-4 bg-white/90 rounded-lg p-2 shadow-lg">
        <div className="flex flex-col gap-2">
          <label className="text-xs font-medium text-gray-700">
            Zoom: {zoom.toFixed(2)}
          </label>
          <input
            type="range"
            min="0.5"
            max="2"
            step="0.1"
            value={zoom}
            onChange={(e) => setZoom(parseFloat(e.target.value))}
            className="w-32"
          />
        </div>
      </div>

      {/* View Angle Controls */}
      <div className="absolute bottom-4 left-4 bg-white/90 rounded-lg p-2 shadow-lg">
        <div className="flex gap-2">
          <button
            onClick={() => setViewAngle({ x: 0, y: 0, z: 0 })}
            className="px-2 py-1 text-xs bg-blue-500 text-white rounded hover:bg-blue-600"
          >
            Front
          </button>
          <button
            onClick={() => setViewAngle({ x: 45, y: 45, z: 0 })}
            className="px-2 py-1 text-xs bg-blue-500 text-white rounded hover:bg-blue-600"
          >
            Isometric
          </button>
          <button
            onClick={() => setViewAngle({ x: 90, y: 0, z: 0 })}
            className="px-2 py-1 text-xs bg-blue-500 text-white rounded hover:bg-blue-600"
          >
            Top
          </button>
        </div>
      </div>
    </div>
  )
}

/**
 * Unified Map View Component
 * 
 * Platform-wide map component supporting:
 * - Google Maps
 * - Mapbox
 * - Route visualization
 * - Marker placement
 * - Interactive controls
 */

'use client'

import { useEffect, useRef, useState } from 'react'
import { mapsService } from '@/lib/services/maps/mapsService'
import type { Location, RouteResult } from '@/lib/services/maps/mapsService'

interface MapViewProps {
  center?: { lat: number; lng: number }
  zoom?: number
  markers?: Array<{
    id: string
    location: Location
    label?: string
    color?: string
    onClick?: () => void
  }>
  route?: RouteResult
  height?: string
  interactive?: boolean
  showControls?: boolean
}

export default function MapView({
  center,
  zoom = 10,
  markers = [],
  route,
  height = '400px',
  interactive = true,
  showControls = true,
}: MapViewProps) {
  const mapRef = useRef<HTMLDivElement>(null)
  const [map, setMap] = useState<any>(null)
  const [mapMarkers, setMapMarkers] = useState<any[]>([])
  const [mapRoute, setMapRoute] = useState<any>(null)

  useEffect(() => {
    if (!mapRef.current) return

    // Initialize map based on provider
    const initMap = async () => {
      const config = (mapsService as any).config
      
      if (config.provider === 'google' && (window as any).google) {
        initGoogleMap()
      } else if (config.provider === 'mapbox' && (window as any).mapboxgl) {
        initMapboxMap()
      } else {
        // Load map library
        if (config.provider === 'google') {
          loadGoogleMaps()
        } else {
          loadMapbox()
        }
      }
    }

    initMap()
  }, [])

  useEffect(() => {
    if (map && center) {
      updateMapCenter(center)
    }
  }, [map, center])

  useEffect(() => {
    if (map && markers.length > 0) {
      updateMarkers(markers)
    }
  }, [map, markers])

  useEffect(() => {
    if (map && route) {
      updateRoute(route)
    }
  }, [map, route])

  const loadGoogleMaps = () => {
    const script = document.createElement('script')
    script.src = `https://maps.googleapis.com/maps/api/js?key=${process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY}&libraries=places,directions`
    script.async = true
    script.defer = true
    script.onload = () => initGoogleMap()
    document.head.appendChild(script)
  }

  const loadMapbox = () => {
    const script = document.createElement('script')
    script.src = 'https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.js'
    script.async = true
    const link = document.createElement('link')
    link.href = 'https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.css'
    link.rel = 'stylesheet'
    document.head.appendChild(script)
    document.head.appendChild(link)
    script.onload = () => initMapboxMap()
  }

  const initGoogleMap = () => {
    if (!mapRef.current || !(window as any).google) return

    const googleMap = new (window as any).google.maps.Map(mapRef.current, {
      center: center || { lat: 24.7136, lng: 46.6753 }, // Default to Riyadh
      zoom,
      mapTypeControl: showControls,
      streetViewControl: showControls,
      fullscreenControl: showControls,
    })

    setMap(googleMap)
  }

  const initMapboxMap = () => {
    if (!mapRef.current || !(window as any).mapboxgl) return

    const mapboxMap = new (window as any).mapboxgl.Map({
      container: mapRef.current,
      style: 'mapbox://styles/mapbox/streets-v12',
      center: center ? [center.lng, center.lat] : [46.6753, 24.7136],
      zoom,
    })

    setMap(mapboxMap)
  }

  const updateMapCenter = (newCenter: { lat: number; lng: number }) => {
    if (!map) return

    const config = (mapsService as any).config
    if (config.provider === 'google') {
      map.setCenter(new (window as any).google.maps.LatLng(newCenter.lat, newCenter.lng))
    } else {
      map.setCenter([newCenter.lng, newCenter.lat])
    }
  }

  const updateMarkers = (newMarkers: MapViewProps['markers']) => {
    if (!map) return

    // Clear existing markers
    mapMarkers.forEach((marker) => {
      if (marker.setMap) marker.setMap(null)
      if (marker.remove) marker.remove()
    })

    const config = (mapsService as any).config
    const newMapMarkers: any[] = []

    newMarkers.forEach((markerData) => {
      if (!markerData.location.coordinates) return

      const { lat, lng } = markerData.location.coordinates

      if (config.provider === 'google') {
        const marker = new (window as any).google.maps.Marker({
          position: { lat, lng },
          map,
          label: markerData.label,
          title: markerData.location.address,
        })

        if (markerData.onClick) {
          marker.addListener('click', markerData.onClick)
        }

        newMapMarkers.push(marker)
      } else {
        const el = document.createElement('div')
        el.className = 'marker'
        el.style.width = '30px'
        el.style.height = '30px'
        el.style.borderRadius = '50%'
        el.style.backgroundColor = markerData.color || '#3b82f6'
        el.style.border = '2px solid white'
        el.style.cursor = 'pointer'

        const marker = new (window as any).mapboxgl.Marker(el)
          .setLngLat([lng, lat])
          .addTo(map)

        if (markerData.onClick) {
          el.addEventListener('click', markerData.onClick)
        }

        newMapMarkers.push(marker)
      }
    })

    setMapMarkers(newMapMarkers)
  }

  const updateRoute = (newRoute: RouteResult) => {
    if (!map || !newRoute.polyline) return

    // Clear existing route
    if (mapRoute) {
      if (mapRoute.setMap) mapRoute.setMap(null)
      if (mapRoute.remove) mapRoute.remove()
    }

    const config = (mapsService as any).config

    if (config.provider === 'google') {
      const directionsService = new (window as any).google.maps.DirectionsService()
      const directionsRenderer = new (window as any).google.maps.DirectionsRenderer()
      directionsRenderer.setMap(map)

      // Decode polyline and render
      const path = (window as any).google.maps.geometry.encoding.decodePath(newRoute.polyline)
      const routePolyline = new (window as any).google.maps.Polyline({
        path,
        geodesic: true,
        strokeColor: '#3b82f6',
        strokeOpacity: 1.0,
        strokeWeight: 3,
      })
      routePolyline.setMap(map)
      setMapRoute(routePolyline)
    } else {
      // Mapbox route rendering
      const geojson = JSON.parse(newRoute.polyline)
      if (map.getSource('route')) {
        map.getSource('route').setData(geojson)
      } else {
        map.addLayer({
          id: 'route',
          type: 'line',
          source: {
            type: 'geojson',
            data: geojson,
          },
          layout: {
            'line-join': 'round',
            'line-cap': 'round',
          },
          paint: {
            'line-color': '#3b82f6',
            'line-width': 3,
          },
        })
      }
    }
  }

  return (
    <div className="w-full rounded-lg overflow-hidden border border-gray-300" style={{ height }}>
      <div ref={mapRef} className="w-full h-full" />
      {!map && (
        <div className="absolute inset-0 flex items-center justify-center bg-gray-100">
          <div className="text-center">
            <i className="ri-map-pin-line text-4xl text-gray-400 mb-2"></i>
            <p className="text-gray-500">Loading map...</p>
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * Enhanced File Upload Component
 * Features: Drag-and-drop, preview, progress tracking, multiple files, image/document support
 */

'use client'

import { useState, useRef, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Upload, X, FileText, Image as ImageIcon, CheckCircle2, AlertCircle, Trash2, Eye } from 'lucide-react'

interface FileWithPreview extends File {
  preview?: string
  id: string
  uploadProgress?: number
  uploadStatus?: 'pending' | 'uploading' | 'success' | 'error'
}

interface EnhancedFileUploadProps {
  value?: FileWithPreview[]
  onChange: (files: FileWithPreview[]) => void
  accept?: string
  maxFiles?: number
  maxSizeMB?: number
  label?: string
  description?: string
  showPreview?: boolean
  onUpload?: (file: File) => Promise<string>
}

export default function EnhancedFileUpload({
  value = [],
  onChange,
  accept = '*/*',
  maxFiles = 10,
  maxSizeMB = 10,
  label = 'Upload Files',
  description = 'Drag and drop files here, or click to select',
  showPreview = true,
  onUpload,
}: EnhancedFileUploadProps) {
  const [files, setFiles] = useState<FileWithPreview[]>(value)
  const [isDragging, setIsDragging] = useState(false)
  const [previewFile, setPreviewFile] = useState<FileWithPreview | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const dropZoneRef = useRef<HTMLDivElement>(null)

  const generateId = () => Math.random().toString(36).substring(2, 15)

  const validateFile = (file: File): string | null => {
    if (file.size > maxSizeMB * 1024 * 1024) {
      return `File size exceeds ${maxSizeMB}MB limit`
    }
    if (files.length >= maxFiles) {
      return `Maximum ${maxFiles} files allowed`
    }
    return null
  }

  const createFilePreview = (file: File): FileWithPreview => {
    const fileWithPreview: FileWithPreview = Object.assign(file, {
      id: generateId(),
      uploadStatus: 'pending',
    })

    if (file.type.startsWith('image/')) {
      const reader = new FileReader()
      reader.onload = (e) => {
        fileWithPreview.preview = e.target?.result as string
        setFiles((prev) => prev.map((f) => (f.id === fileWithPreview.id ? fileWithPreview : f)))
      }
      reader.readAsDataURL(file)
    }

    return fileWithPreview
  }

  const handleFiles = useCallback(
    async (newFiles: FileList | File[]) => {
      const fileArray = Array.from(newFiles)
      const validFiles: FileWithPreview[] = []

      for (const file of fileArray) {
        const error = validateFile(file)
        if (error) {
          alert(error)
          continue
        }

        const fileWithPreview = createFilePreview(file)
        validFiles.push(fileWithPreview)

        // Auto-upload if onUpload is provided
        if (onUpload) {
          fileWithPreview.uploadStatus = 'uploading'
          fileWithPreview.uploadProgress = 0
          setFiles((prev) => [...prev, fileWithPreview])

          try {
            // Simulate upload progress
            const progressInterval = setInterval(() => {
              setFiles((prev) =>
                prev.map((f) =>
                  f.id === fileWithPreview.id
                    ? { ...f, uploadProgress: Math.min((f.uploadProgress || 0) + 10, 90) }
                    : f
                )
              )
            }, 200)

            const url = await onUpload(file)
            clearInterval(progressInterval)

            fileWithPreview.uploadStatus = 'success'
            fileWithPreview.uploadProgress = 100
            setFiles((prev) =>
              prev.map((f) => (f.id === fileWithPreview.id ? fileWithPreview : f))
            )
          } catch (error) {
            fileWithPreview.uploadStatus = 'error'
            setFiles((prev) =>
              prev.map((f) => (f.id === fileWithPreview.id ? fileWithPreview : f))
            )
            alert(`Failed to upload ${file.name}`)
          }
        }
      }

      if (!onUpload) {
        setFiles((prev) => [...prev, ...validFiles])
      }
      onChange([...files, ...validFiles])
    },
    [files, onChange, onUpload, maxFiles, maxSizeMB]
  )

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(false)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsDragging(false)

    const droppedFiles = e.dataTransfer.files
    if (droppedFiles.length > 0) {
      handleFiles(droppedFiles)
    }
  }

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      handleFiles(e.target.files)
    }
  }

  const handleRemove = (id: string) => {
    const updatedFiles = files.filter((f) => f.id !== id)
    setFiles(updatedFiles)
    onChange(updatedFiles)
  }

  const getFileIcon = (file: FileWithPreview) => {
    if (file.type.startsWith('image/')) {
      return <ImageIcon className="w-5 h-5 text-blue-500" />
    }
    return <FileText className="w-5 h-5 text-slate-500" />
  }

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i]
  }

  return (
    <div className="space-y-4">
      <div>
        <label className="block text-sm font-medium mb-2 text-slate-700 dark:text-slate-300">
          {label}
        </label>

        {/* Drop Zone */}
        <div
          ref={dropZoneRef}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
          className={`
            relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all
            ${
              isDragging
                ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
                : 'border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-800/50 hover:border-blue-400 hover:bg-slate-100 dark:hover:bg-slate-800'
            }
          `}
        >
          <input
            ref={fileInputRef}
            type="file"
            multiple
            accept={accept}
            onChange={handleFileSelect}
            className="hidden"
          />

          <motion.div
            animate={{ scale: isDragging ? 1.05 : 1 }}
            className="flex flex-col items-center gap-3"
          >
            <Upload
              className={`w-12 h-12 ${
                isDragging ? 'text-blue-500' : 'text-slate-400'
              }`}
            />
            <div>
              <p className="text-sm font-medium text-slate-700 dark:text-slate-300">
                {isDragging ? 'Drop files here' : description}
              </p>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                Max {maxFiles} files, {maxSizeMB}MB each
              </p>
            </div>
          </motion.div>
        </div>
      </div>

      {/* File List */}
      <AnimatePresence>
        {files.length > 0 && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="space-y-2"
          >
            {files.map((file) => (
              <motion.div
                key={file.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className="flex items-center gap-3 p-3 bg-white dark:bg-slate-700 rounded-lg border border-slate-200 dark:border-slate-600"
              >
                {getFileIcon(file)}
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-slate-900 dark:text-slate-100 truncate">
                    {file.name}
                  </p>
                  <div className="flex items-center gap-2 mt-1">
                    <p className="text-xs text-slate-500 dark:text-slate-400">
                      {formatFileSize(file.size)}
                    </p>
                    {file.uploadStatus === 'uploading' && (
                      <>
                        <div className="flex-1 h-1.5 bg-slate-200 dark:bg-slate-600 rounded-full overflow-hidden">
                          <motion.div
                            initial={{ width: 0 }}
                            animate={{ width: `${file.uploadProgress || 0}%` }}
                            className="h-full bg-blue-500"
                          />
                        </div>
                        <span className="text-xs text-slate-500">
                          {file.uploadProgress || 0}%
                        </span>
                      </>
                    )}
                    {file.uploadStatus === 'success' && (
                      <CheckCircle2 className="w-4 h-4 text-green-500" />
                    )}
                    {file.uploadStatus === 'error' && (
                      <AlertCircle className="w-4 h-4 text-red-500" />
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {showPreview && file.preview && (
                    <button
                      onClick={() => setPreviewFile(file)}
                      className="p-1.5 text-slate-500 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded"
                    >
                      <Eye className="w-4 h-4" />
                    </button>
                  )}
                  <button
                    onClick={() => handleRemove(file.id)}
                    className="p-1.5 text-slate-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </motion.div>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Preview Modal */}
      <AnimatePresence>
        {previewFile && previewFile.preview && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4"
            onClick={() => setPreviewFile(null)}
          >
            <motion.div
              initial={{ scale: 0.9 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0.9 }}
              onClick={(e) => e.stopPropagation()}
              className="relative max-w-4xl max-h-[90vh] bg-white dark:bg-slate-800 rounded-lg overflow-hidden"
            >
              <button
                onClick={() => setPreviewFile(null)}
                className="absolute top-4 right-4 z-10 p-2 bg-black/50 text-white rounded-full hover:bg-black/70"
              >
                <X className="w-5 h-5" />
              </button>
              <img
                src={previewFile.preview}
                alt={previewFile.name}
                className="w-full h-full object-contain"
              />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Heart } from 'lucide-react'

interface FavoriteButtonProps {
  userId: string
  listingId?: string
  providerId?: string
  size?: 'sm' | 'md' | 'lg'
  className?: string
}

export default function FavoriteButton({
  userId,
  listingId,
  providerId,
  size = 'md',
  className = '',
}: FavoriteButtonProps) {
  const [isFavorited, setIsFavorited] = useState(false)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    checkFavoriteStatus()
  }, [userId, listingId, providerId])

  const checkFavoriteStatus = async () => {
    if (!listingId && !providerId) return

    try {
      const type = listingId ? 'listing' : 'provider'
      const id = listingId || providerId
      const response = await fetch(`/api/marketplace/favorites?userId=${userId}&type=${type}&${type}Id=${id}`)
      const result = await response.json()
      if (result.success) {
        setIsFavorited(result.isFavorited || false)
      }
    } catch (error) {
      console.error('Failed to check favorite status:', error)
    }
  }

  const toggleFavorite = async () => {
    if (loading) return
    setLoading(true)

    try {
      const type = listingId ? 'listing' : 'provider'
      const id = listingId || providerId

      if (isFavorited) {
        // Remove from favorites
        const response = await fetch(`/api/marketplace/favorites?type=${type}&userId=${userId}&${type}Id=${id}`, {
          method: 'DELETE',
        })
        const result = await response.json()
        if (result.success) {
          setIsFavorited(false)
        }
      } else {
        // Add to favorites
        const response = await fetch('/api/marketplace/favorites', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            type,
            userId,
            [type === 'listing' ? 'listingId' : 'providerId']: id,
          }),
        })
        const result = await response.json()
        if (result.success) {
          setIsFavorited(true)
        }
      }
    } catch (error) {
      console.error('Failed to toggle favorite:', error)
    } finally {
      setLoading(false)
    }
  }

  const sizeClasses = {
    sm: 'w-5 h-5',
    md: 'w-6 h-6',
    lg: 'w-8 h-8',
  }

  return (
    <button
      onClick={toggleFavorite}
      disabled={loading}
      className={`${className} ${sizeClasses[size]} transition-all hover:scale-110 ${
        isFavorited
          ? 'text-red-500 fill-red-500'
          : 'text-slate-400 hover:text-red-500'
      }`}
      title={isFavorited ? 'Remove from favorites' : 'Add to favorites'}
    >
      <Heart className={`w-full h-full ${isFavorited ? 'fill-current' : ''}`} />
    </button>
  )
}

/**
 * Learning & Feedback Components
 * Comprehensive feedback collection, learning insights, and improvement metrics
 * World-class UX with full drill-downs
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Lightbulb, TrendingUp, AlertCircle, CheckCircle2, Target,
  BarChart3, Sparkles, Send, Star, MessageSquare, X,
  Download, Share2, RefreshCw, Activity, Zap
} from 'lucide-react'
import { learningFeedbackService } from '@/lib/services/marketplace/learningFeedbackService'
import {
  BarChart, Bar, LineChart, Line, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts'

interface LearningInsightsProps {
  requirementId?: string
  bookingId?: string
  matchedProviderId?: string
  matchedServiceId?: string
  onFeedbackSubmitted?: () => void
}

export default function LearningInsights({
  requirementId,
  bookingId,
  matchedProviderId,
  matchedServiceId,
  onFeedbackSubmitted,
}: LearningInsightsProps) {
  const [insights, setInsights] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [showFeedbackForm, setShowFeedbackForm] = useState(false)
  const [feedback, setFeedback] = useState({
    customerSatisfaction: 0,
    accuracy: 0,
    outcome: 'SUCCESS' as 'SUCCESS' | 'PARTIAL' | 'FAILURE',
    missingInformation: [] as string[],
    suggestions: '',
    notes: '',
  })

  useEffect(() => {
    if (requirementId) {
      loadInsights()
    }
  }, [requirementId])

  const loadInsights = async () => {
    setLoading(true)
    try {
      const result = await learningFeedbackService.getInsights(requirementId!)
      setInsights(result)
    } catch (error) {
      console.error('Failed to load insights:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleSubmitFeedback = async () => {
    if (!requirementId || !matchedProviderId || !matchedServiceId) return

    try {
      await learningFeedbackService.submitFeedback({
        requirementId,
        bookingId,
        matchedProviderId,
        matchedServiceId,
        customerSatisfaction: feedback.customerSatisfaction,
        accuracy: feedback.accuracy,
        outcome: feedback.outcome,
        missingInformation: feedback.missingInformation,
        suggestions: feedback.suggestions ? [feedback.suggestions] : [],
        notes: feedback.notes,
      })
      setShowFeedbackForm(false)
      setFeedback({
        customerSatisfaction: 0,
        accuracy: 0,
        outcome: 'SUCCESS',
        missingInformation: [],
        suggestions: '',
        notes: '',
      })
      await loadInsights()
      onFeedbackSubmitted?.()
    } catch (error) {
      console.error('Failed to submit feedback:', error)
    }
  }

  return (
    <div className="space-y-6">
      {/* Feedback Form Toggle */}
      {requirementId && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-xl border border-slate-200 dark:border-slate-700"
        >
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-2">
                Help Us Improve
              </h2>
              <p className="text-slate-600 dark:text-slate-400">
                Share your feedback to help us improve matching accuracy
              </p>
            </div>
            <button
              onClick={() => setShowFeedbackForm(!showFeedbackForm)}
              className="px-6 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-colors flex items-center gap-2"
            >
              <MessageSquare className="w-5 h-5" />
              {showFeedbackForm ? 'Close' : 'Submit Feedback'}
            </button>
          </div>
        </motion.div>
      )}

      {/* Feedback Form */}
      <AnimatePresence>
        {showFeedbackForm && (
          <FeedbackForm
            feedback={feedback}
            onFeedbackChange={setFeedback}
            onSubmit={handleSubmitFeedback}
            onClose={() => setShowFeedbackForm(false)}
          />
        )}
      </AnimatePresence>

      {/* Learning Insights */}
      {insights && (
        <>
          <InsightsOverviewSection insights={insights} />
          <MissingFieldsAnalysisSection analysis={insights.missingFieldsAnalysis} />
          <MatchingPatternsSection patterns={insights.matchingPatterns} />
          <SatisfactionPatternsSection patterns={insights.satisfactionPatterns} />
          <ImprovementMetricsSection metrics={insights.improvementMetrics} />
          <RecommendationsSection recommendations={insights.recommendations} />
        </>
      )}

      {loading && (
        <div className="text-center py-12">
          <RefreshCw className="w-12 h-12 text-blue-600 animate-spin mx-auto mb-4" />
          <p className="text-slate-600 dark:text-slate-400">Loading insights...</p>
        </div>
      )}
    </div>
  )
}

function FeedbackForm({
  feedback,
  onFeedbackChange,
  onSubmit,
  onClose,
}: {
  feedback: any
  onFeedbackChange: (f: any) => void
  onSubmit: () => void
  onClose: () => void
}) {
  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: 'auto' }}
      exit={{ opacity: 0, height: 0 }}
      className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-xl border border-slate-200 dark:border-slate-700"
    >
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-xl font-bold text-slate-900 dark:text-white">Feedback Form</h3>
        <button
          onClick={onClose}
          className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg transition-colors"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      <div className="space-y-6">
        {/* Satisfaction Rating */}
        <div>
          <label className="block text-sm font-medium mb-3 text-slate-700 dark:text-slate-300">
            Overall Satisfaction (1-5)
          </label>
          <div className="flex gap-2">
            {[1, 2, 3, 4, 5].map((rating) => (
              <button
                key={rating}
                onClick={() => onFeedbackChange({ ...feedback, customerSatisfaction: rating })}
                className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${
                  feedback.customerSatisfaction >= rating
                    ? 'bg-yellow-400 text-yellow-900'
                    : 'bg-slate-100 dark:bg-slate-700 text-slate-400'
                }`}
              >
                <Star className="w-6 h-6 fill-current" />
              </button>
            ))}
          </div>
        </div>

        {/* Accuracy Rating */}
        <div>
          <label className="block text-sm font-medium mb-3 text-slate-700 dark:text-slate-300">
            Match Accuracy (1-5)
          </label>
          <div className="flex gap-2">
            {[1, 2, 3, 4, 5].map((rating) => (
              <button
                key={rating}
                onClick={() => onFeedbackChange({ ...feedback, accuracy: rating })}
                className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${
                  feedback.accuracy >= rating
                    ? 'bg-blue-400 text-blue-900'
                    : 'bg-slate-100 dark:bg-slate-700 text-slate-400'
                }`}
              >
                <Target className="w-6 h-6" />
              </button>
            ))}
          </div>
        </div>

        {/* Outcome */}
        <div>
          <label className="block text-sm font-medium mb-2 text-slate-700 dark:text-slate-300">
            Outcome
          </label>
          <select
            value={feedback.outcome}
            onChange={(e) => onFeedbackChange({ ...feedback, outcome: e.target.value })}
            className="w-full px-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
          >
            <option value="SUCCESS">Success</option>
            <option value="PARTIAL">Partial Success</option>
            <option value="FAILURE">Failure</option>
          </select>
        </div>

        {/* Missing Information */}
        <div>
          <label className="block text-sm font-medium mb-2 text-slate-700 dark:text-slate-300">
            Missing Information (select all that apply)
