/**
 * Real-Time Price Estimation Calculator
 * Features: Dynamic pricing, cost breakdown, budget comparison
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { DollarSign, Calculator, TrendingUp, AlertCircle, CheckCircle2 } from 'lucide-react'
import { predictivePricingService } from '@/lib/services/marketplace/predictivePricingService'

interface PriceCalculatorProps {
  requirement: any
  category: string
  onPriceUpdate?: (price: { min: number; max: number; currency: string }) => void
}

export default function PriceCalculator({ requirement, category, onPriceUpdate }: PriceCalculatorProps) {
  const [estimatedPrice, setEstimatedPrice] = useState<{
    min: number
    max: number
    currency: string
    confidence: number
    breakdown?: any
  } | null>(null)
  const [isCalculating, setIsCalculating] = useState(false)
  const [factors, setFactors] = useState<string[]>([])

  useEffect(() => {
    calculatePrice()
  }, [requirement, category])

  const calculatePrice = async () => {
    setIsCalculating(true)
    try {
      // Use predictive pricing service
      const result = await predictivePricingService.estimatePrice({
        category,
        requirement: requirement as any,
      })

      setEstimatedPrice({
        min: result.priceRange.min,
        max: result.priceRange.max,
        currency: result.priceRange.currency || 'SAR',
        confidence: result.confidence || 75,
        breakdown: result.breakdown,
      })

      setFactors(result.factors || [])

      if (onPriceUpdate) {
        onPriceUpdate({
          min: result.priceRange.min,
          max: result.priceRange.max,
          currency: result.priceRange.currency || 'SAR',
        })
      }
    } catch (error) {
      console.error('Price calculation error:', error)
      // Fallback to manual calculation
      const fallbackPrice = calculateFallbackPrice()
      setEstimatedPrice(fallbackPrice)
      if (onPriceUpdate) {
        onPriceUpdate({
          min: fallbackPrice.min,
          max: fallbackPrice.max,
          currency: fallbackPrice.currency,
        })
      }
    } finally {
      setIsCalculating(false)
    }
  }

  const calculateFallbackPrice = () => {
    // Simple fallback calculation based on category
    const basePrices: Record<string, { min: number; max: number }> = {
      STORAGE: { min: 500, max: 5000 },
      TRANSPORTATION: { min: 1000, max: 10000 },
      FREIGHT: { min: 2000, max: 20000 },
      CONSULTING: { min: 5000, max: 50000 },
      MANPOWER: { min: 3000, max: 30000 },
      TRANSLATION: { min: 500, max: 5000 },
      CROSSDOCKING: { min: 1000, max: 10000 },
      WAREHOUSE_NETWORK: { min: 10000, max: 100000 },
    }

    const base = basePrices[category] || { min: 1000, max: 10000 }
    
    // Adjust based on duration, quantity, etc.
    let multiplier = 1
    if (requirement?.timeline?.duration) {
      multiplier *= Math.max(1, requirement.timeline.duration / 30)
    }
    if (requirement?.budget?.min && requirement?.budget?.max) {
      return {
        min: requirement.budget.min,
        max: requirement.budget.max,
        currency: requirement.budget.currency || 'SAR',
        confidence: 50,
      }
    }

    return {
      min: base.min * multiplier,
      max: base.max * multiplier,
      currency: 'SAR',
      confidence: 50,
    }
  }

  const formatCurrency = (amount: number, currency: string) => {
    return new Intl.NumberFormat('en-SA', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: 0,
    }).format(amount)
  }

  if (!estimatedPrice) {
    return (
      <div className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg border border-slate-200 dark:border-slate-600">
        <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
          <Calculator className="w-5 h-5" />
          <span className="text-sm">Fill in requirements to see price estimate</span>
        </div>
      </div>
    )
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="p-5 bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 rounded-xl border border-blue-200 dark:border-blue-800"
    >
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Calculator className="w-5 h-5 text-blue-600 dark:text-blue-400" />
          <h4 className="font-semibold text-slate-800 dark:text-slate-200">
            Estimated Price Range
          </h4>
        </div>
        {isCalculating && (
          <div className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-400">
            <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />
            Calculating...
          </div>
        )}
      </div>

      <div className="space-y-4">
        {/* Price Range */}
        <div className="flex items-baseline gap-3">
          <div className="flex-1">
            <p className="text-sm text-slate-600 dark:text-slate-400 mb-1">Minimum</p>
            <p className="text-2xl font-bold text-blue-600 dark:text-blue-400">
              {formatCurrency(estimatedPrice.min, estimatedPrice.currency)}
            </p>
          </div>
          <TrendingUp className="w-5 h-5 text-slate-400" />
          <div className="flex-1 text-right">
            <p className="text-sm text-slate-600 dark:text-slate-400 mb-1">Maximum</p>
            <p className="text-2xl font-bold text-indigo-600 dark:text-indigo-400">
              {formatCurrency(estimatedPrice.max, estimatedPrice.currency)}
            </p>
          </div>
        </div>

        {/* Confidence Score */}
        <div className="flex items-center gap-2">
          <div className="flex-1 h-2 bg-slate-200 dark:bg-slate-700 rounded-full overflow-hidden">
            <motion.div
              initial={{ width: 0 }}
              animate={{ width: `${estimatedPrice.confidence}%` }}
              className={`h-full ${
                estimatedPrice.confidence >= 75
                  ? 'bg-green-500'
                  : estimatedPrice.confidence >= 50
                  ? 'bg-yellow-500'
                  : 'bg-orange-500'
              }`}
            />
          </div>
          <span className="text-xs font-medium text-slate-600 dark:text-slate-400">
            {estimatedPrice.confidence}% confidence
          </span>
        </div>

        {/* Price Factors */}
        {factors.length > 0 && (
          <div className="pt-3 border-t border-blue-200 dark:border-blue-800">
            <p className="text-xs font-medium text-slate-600 dark:text-slate-400 mb-2">
              Price Factors:
            </p>
            <div className="flex flex-wrap gap-2">
              {factors.map((factor, idx) => (
                <span
                  key={idx}
                  className="px-2 py-1 text-xs bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-full border border-slate-200 dark:border-slate-600"
                >
                  {factor}
                </span>
              ))}
            </div>
          </div>
        )}

        {/* Breakdown */}
        {estimatedPrice.breakdown && (
          <div className="pt-3 border-t border-blue-200 dark:border-blue-800 space-y-2">
            <p className="text-xs font-medium text-slate-600 dark:text-slate-400 mb-2">
              Cost Breakdown:
            </p>
            {Object.entries(estimatedPrice.breakdown).map(([key, value]: [string, any]) => (
              <div key={key} className="flex justify-between text-sm">
                <span className="text-slate-600 dark:text-slate-400 capitalize">
                  {key.replace(/_/g, ' ')}
                </span>
                <span className="font-medium text-slate-800 dark:text-slate-200">
                  {formatCurrency(value, estimatedPrice.currency)}
                </span>
              </div>
            ))}
          </div>
        )}

        {/* Budget Comparison */}
        {requirement?.budget && (
          <div className="pt-3 border-t border-blue-200 dark:border-blue-800">
            {estimatedPrice.min >= (requirement.budget.min || 0) &&
            estimatedPrice.max <= (requirement.budget.max || Infinity) ? (
              <div className="flex items-center gap-2 text-green-600 dark:text-green-400">
                <CheckCircle2 className="w-4 h-4" />
                <span className="text-sm font-medium">Within budget range</span>
              </div>
            ) : (
              <div className="flex items-center gap-2 text-orange-600 dark:text-orange-400">
                <AlertCircle className="w-4 h-4" />
                <span className="text-sm font-medium">
                  May exceed budget - consider adjusting requirements
                </span>
              </div>
            )}
          </div>
        )}
      </div>
    </motion.div>
  )
}

/**
 * Real-Time Matching Preview Component
 * Shows live matching results as user fills the form
 */

'use client'

import { useState, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Sparkles, TrendingUp, Star, MapPin, Clock, DollarSign, CheckCircle2, AlertCircle } from 'lucide-react'
import { aiMatchingService } from '@/lib/services/marketplace/aiMatchingService'
import type { ServiceRequirement } from '@/types/marketplace-requirements'

interface RealtimeMatchingPreviewProps {
  requirement: Partial<ServiceRequirement>
  category: string
  onMatchSelect?: (matchId: string) => void
}

export default function RealtimeMatchingPreview({
  requirement,
  category,
  onMatchSelect,
}: RealtimeMatchingPreviewProps) {
  const [matches, setMatches] = useState<any[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null)
  const [debounceTimer, setDebounceTimer] = useState<NodeJS.Timeout | null>(null)

  const hasMinimumData = useMemo(() => {
    // Check if we have minimum data for matching
    return (
      requirement.category &&
      (requirement.location?.address || requirement.location?.city) &&
      requirement.timeline?.startDate
    )
  }, [requirement])

  useEffect(() => {
    if (!hasMinimumData) {
      setMatches([])
      return
    }

    // Debounce matching calls
    if (debounceTimer) {
      clearTimeout(debounceTimer)
    }

    const timer = setTimeout(() => {
      performMatching()
    }, 1000) // Wait 1 second after user stops typing

    setDebounceTimer(timer)

    return () => {
      if (debounceTimer) {
        clearTimeout(debounceTimer)
      }
    }
  }, [requirement, hasMinimumData])

  const performMatching = async () => {
    setIsLoading(true)
    try {
      const result = await aiMatchingService.findMatches(requirement as ServiceRequirement)
      setMatches(result.matches.slice(0, 5)) // Show top 5 matches
      setLastUpdate(new Date())
    } catch (error) {
      console.error('Matching error:', error)
      setMatches([])
    } finally {
      setIsLoading(false)
    }
  }

  const getMatchScoreColor = (score: number) => {
    if (score >= 80) return 'text-green-600 dark:text-green-400'
    if (score >= 60) return 'text-yellow-600 dark:text-yellow-400'
    return 'text-orange-600 dark:text-orange-400'
  }

  const getMatchScoreBg = (score: number) => {
    if (score >= 80) return 'bg-green-100 dark:bg-green-900/20'
    if (score >= 60) return 'bg-yellow-100 dark:bg-yellow-900/20'
    return 'bg-orange-100 dark:bg-orange-900/20'
  }

  if (!hasMinimumData) {
    return (
      <div className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg border border-slate-200 dark:border-slate-600">
        <div className="flex items-center gap-2 text-slate-600 dark:text-slate-400">
          <Sparkles className="w-5 h-5" />
          <span className="text-sm">
            Fill in location and timeline to see matching providers
          </span>
        </div>
      </div>
    )
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-4"
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Sparkles className="w-5 h-5 text-blue-600 dark:text-blue-400" />
          <h4 className="font-semibold text-slate-800 dark:text-slate-200">
            Live Matching Results
          </h4>
        </div>
        {lastUpdate && (
          <span className="text-xs text-slate-500 dark:text-slate-400">
            Updated {lastUpdate.toLocaleTimeString()}
          </span>
        )}
      </div>

      {isLoading ? (
        <div className="flex items-center justify-center py-8">
          <div className="flex flex-col items-center gap-3">
            <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
            <span className="text-sm text-slate-600 dark:text-slate-400">
              Finding best matches...
            </span>
          </div>
        </div>
      ) : matches.length === 0 ? (
        <div className="p-4 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg border border-yellow-200 dark:border-yellow-800">
          <div className="flex items-center gap-2 text-yellow-800 dark:text-yellow-300">
            <AlertCircle className="w-5 h-5" />
            <span className="text-sm">No matches found. Try adjusting your requirements.</span>
          </div>
        </div>
      ) : (
        <div className="space-y-3">
          {matches.map((match, idx) => (
            <motion.div
              key={match.id || idx}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: idx * 0.1 }}
              onClick={() => onMatchSelect?.(match.id)}
              className="p-4 bg-white dark:bg-slate-700 rounded-lg border border-slate-200 dark:border-slate-600 hover:border-blue-400 dark:hover:border-blue-600 hover:shadow-md cursor-pointer transition-all"
            >
              <div className="flex items-start justify-between gap-4">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-2">
                    <h5 className="font-semibold text-slate-900 dark:text-slate-100 truncate">
                      {match.providerName || match.name || 'Provider'}
                    </h5>
                    {match.rating && (
                      <div className="flex items-center gap-1">
                        <Star className="w-4 h-4 fill-yellow-400 text-yellow-400" />
                        <span className="text-sm text-slate-600 dark:text-slate-400">
                          {match.rating.toFixed(1)}
                        </span>
                      </div>
                    )}
                  </div>

                  <div className="space-y-1.5 text-sm text-slate-600 dark:text-slate-400">
                    {match.location && (
                      <div className="flex items-center gap-1.5">
                        <MapPin className="w-4 h-4" />
                        <span className="truncate">{match.location}</span>
                      </div>
                    )}
                    {match.priceRange && (
                      <div className="flex items-center gap-1.5">
                        <DollarSign className="w-4 h-4" />
                        <span>
                          {match.priceRange.min} - {match.priceRange.max} {match.priceRange.currency}
                        </span>
                      </div>
                    )}
                    {match.estimatedTime && (
                      <div className="flex items-center gap-1.5">
                        <Clock className="w-4 h-4" />
                        <span>{match.estimatedTime}</span>
                      </div>
                    )}
                  </div>

                  {match.reasons && match.reasons.length > 0 && (
                    <div className="mt-2 flex flex-wrap gap-1">
                      {match.reasons.slice(0, 3).map((reason: string, rIdx: number) => (
                        <span
                          key={rIdx}
                          className="px-2 py-0.5 text-xs bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 rounded"
                        >
                          {reason}
                        </span>
                      ))}
                    </div>
                  )}
                </div>

                <div className="flex flex-col items-end gap-2">
                  <div
                    className={`px-3 py-1.5 rounded-lg font-bold ${getMatchScoreBg(
                      match.matchScore || 0
                    )} ${getMatchScoreColor(match.matchScore || 0)}`}
                  >
                    {Math.round(match.matchScore || 0)}%
                  </div>
                  {match.verified && (
                    <div className="flex items-center gap-1 text-xs text-green-600 dark:text-green-400">
                      <CheckCircle2 className="w-3 h-3" />
                      <span>Verified</span>
                    </div>
                  )}
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      )}

      {matches.length > 0 && (
        <div className="pt-3 border-t border-slate-200 dark:border-slate-600">
          <button
            onClick={performMatching}
            className="w-full px-4 py-2 text-sm font-medium text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors"
          >
            View All Matches →
          </button>
        </div>
      )}
    </motion.div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Sparkles, TrendingUp, DollarSign, Clock, ArrowRight } from 'lucide-react'
import type { Recommendation } from '@/lib/services/marketplace/marketplaceRecommendationService'

interface RecommendationsPanelProps {
  userId: string
  limit?: number
}

export default function RecommendationsPanel({
  userId,
  limit = 5,
}: RecommendationsPanelProps) {
  const [recommendations, setRecommendations] = useState<Recommendation[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadRecommendations()
  }, [userId])

  const loadRecommendations = async () => {
    setLoading(true)
    try {
      const response = await fetch(`/api/marketplace/recommendations?userId=${userId}&limit=${limit}`)
      const result = await response.json()
      if (result.success) {
        setRecommendations(result.data.recommendations || [])
      }
    } catch (error) {
      console.error('Failed to load recommendations:', error)
    } finally {
      setLoading(false)
    }
  }

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'CRITICAL':
        return 'border-red-500 bg-red-50'
      case 'HIGH':
        return 'border-orange-500 bg-orange-50'
      case 'MEDIUM':
        return 'border-blue-500 bg-blue-50'
      default:
        return 'border-slate-300 bg-slate-50'
    }
  }

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'PRICING_OPTIMIZATION':
        return DollarSign
      case 'CAPACITY_PLANNING':
        return Clock
      case 'MARKET_DEMAND':
        return TrendingUp
      default:
        return Sparkles
    }
  }

  if (loading) {
    return (
      <div className="bg-white rounded-xl shadow-lg p-6">
        <div className="animate-pulse space-y-4">
          <div className="h-4 bg-slate-200 rounded w-1/2"></div>
          <div className="h-20 bg-slate-200 rounded"></div>
        </div>
      </div>
    )
  }

  if (recommendations.length === 0) {
    return null
  }

  return (
    <div className="bg-white rounded-xl shadow-lg p-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-slate-800 flex items-center space-x-2">
          <Sparkles className="w-5 h-5 text-blue-600" />
          <span>AI Recommendations</span>
        </h3>
        <span className="text-sm text-slate-500">{recommendations.length} suggestions</span>
      </div>

      <div className="space-y-4">
        {recommendations.map((rec) => {
          const Icon = getTypeIcon(rec.type)
          return (
            <div
              key={rec.id}
              className={`border rounded-lg p-4 ${getPriorityColor(rec.priority)}`}
            >
              <div className="flex items-start justify-between mb-2">
                <div className="flex items-start space-x-3 flex-1">
                  <Icon className="w-5 h-5 text-blue-600 mt-0.5" />
                  <div className="flex-1">
                    <h4 className="font-semibold text-slate-800 mb-1">{rec.title}</h4>
                    <p className="text-sm text-slate-600 mb-2">{rec.description}</p>
                    
                    {rec.impact.expectedImprovement && (
                      <div className="flex items-center space-x-4 text-xs text-slate-500 mb-2">
                        {rec.impact.expectedImprovement && (
                          <span>+{rec.impact.expectedImprovement}% improvement</span>
                        )}
                        {rec.impact.estimatedSavings && (
                          <span>Save {rec.impact.estimatedSavings} SAR</span>
                        )}
                        <span className="text-blue-600">Confidence: {rec.confidence}%</span>
                      </div>
                    )}

                    {rec.actions.length > 0 && (
                      <div className="mt-3">
                        <button className="text-sm text-blue-600 hover:text-blue-700 flex items-center space-x-1">
                          <span>View Actions</span>
                          <ArrowRight className="w-3 h-3" />
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

/**
 * Comprehensive Service Requirement Form
 * World-class form with smart detection, validation, and completeness tracking
 * Supports ALL service categories with full data collection
 */

'use client'

import { useState, useEffect, useCallback, lazy, Suspense } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  CheckCircle2, AlertCircle, Info, ChevronRight, ChevronDown,
  MapPin, Calendar, DollarSign, Package, Truck, Building2,
  Users, Languages, Network, FileText, Upload, Mic, Sparkles, Target,
  Save, RefreshCw, Keyboard, X
} from 'lucide-react'
import AdvancedSmartDetectionForm from '@/components/forms/AdvancedSmartDetectionForm'
import type { ServiceRequirement } from '@/types/marketplace-requirements'
import { aiMatchingService } from '@/lib/services/marketplace/aiMatchingService'
import SmartFieldSuggestions from './SmartFieldSuggestions'
import EnhancedLocationPicker from './EnhancedLocationPicker'
import TimelineVisualization from './TimelineVisualization'
import PriceCalculator from './PriceCalculator'
import EnhancedFileUpload from './EnhancedFileUpload'
import RealtimeMatchingPreview from './RealtimeMatchingPreview'
import {
  TransportationFields,
  FreightFields,
  ConsultingFields,
  ManpowerFields,
  TranslationFields,
  CrossDockingFields,
  WarehouseNetworkFields,
  TimelineFields,
  BudgetFields,
  RequirementsFields,
} from './ServiceRequirementFormFields'

const VoiceInput = lazy(() => import('./VoiceInput'))
const RichTextEditor = lazy(() => import('./RichTextEditor'))

interface ServiceRequirementFormProps {
  category: string
  onSubmit: (requirement: ServiceRequirement) => void
  onCancel?: () => void
  initialData?: Partial<ServiceRequirement>
}

export default function ServiceRequirementForm({
  category,
  onSubmit,
  onCancel,
  initialData,
}: ServiceRequirementFormProps) {
  const [step, setStep] = useState(1)
  const [requirement, setRequirement] = useState<Partial<ServiceRequirement>>(initialData || {
    category,
    urgency: 'MEDIUM',
    timeline: { flexible: false },
    location: { multipleLocations: false },
  })
  const [completeness, setCompleteness] = useState<{ score: number; missing: string[] }>({ score: 0, missing: [] })
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set(['basic']))
  const [showMatchingPreview, setShowMatchingPreview] = useState(false)
  const [matchingPreview, setMatchingPreview] = useState<any>(null)
  const [autoSaveStatus, setAutoSaveStatus] = useState<'saved' | 'saving' | 'error' | null>(null)
  const [lastSaved, setLastSaved] = useState<Date | null>(null)
  const [showKeyboardShortcuts, setShowKeyboardShortcuts] = useState(false)
  const [attachments, setAttachments] = useState<File[]>([])

  const calculateCompleteness = useCallback(async () => {
    try {
      const result = await aiMatchingService.findMatches(requirement as ServiceRequirement)
      setCompleteness({
        score: result.completeness.completeness,
        missing: result.completeness.missingFields,
      })
    } catch (error) {
      // Calculate manually if service unavailable
      const required = getRequiredFields(category)
      const filled = required.filter(field => hasField(requirement, field))
      setCompleteness({
        score: (filled.length / required.length) * 100,
        missing: required.filter(field => !hasField(requirement, field)),
      })
    }
  }, [requirement, category])

  // Auto-save functionality
  useEffect(() => {
    const autoSaveTimer = setTimeout(() => {
      if (Object.keys(requirement).length > 1) {
        saveToLocalStorage()
      }
    }, 2000) // Auto-save after 2 seconds of inactivity

    return () => clearTimeout(autoSaveTimer)
  }, [requirement])

  // Load from localStorage on mount
  useEffect(() => {
    loadFromLocalStorage()
  }, [category])

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl/Cmd + S to save
      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault()
        saveToLocalStorage()
      }
      // Ctrl/Cmd + ? to show shortcuts
      if ((e.ctrlKey || e.metaKey) && e.key === '/') {
        e.preventDefault()
        setShowKeyboardShortcuts((prev) => !prev)
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [])

  const saveToLocalStorage = useCallback(() => {
    try {
      setAutoSaveStatus('saving')
      const key = `marketplace_requirement_${category}_${new Date().toISOString().split('T')[0]}`
      localStorage.setItem(key, JSON.stringify(requirement))
      setAutoSaveStatus('saved')
      setLastSaved(new Date())
      setTimeout(() => setAutoSaveStatus(null), 2000)
    } catch (error) {
      console.error('Auto-save error:', error)
      setAutoSaveStatus('error')
    }
  }, [requirement, category])

  const loadFromLocalStorage = useCallback(() => {
    try {
      const key = `marketplace_requirement_${category}_${new Date().toISOString().split('T')[0]}`
      const saved = localStorage.getItem(key)
      if (saved) {
        const parsed = JSON.parse(saved)
        setRequirement((prev) => ({ ...prev, ...parsed }))
        setLastSaved(new Date())
      }
    } catch (error) {
      console.error('Load from localStorage error:', error)
    }
  }, [category])

  useEffect(() => {
    calculateCompleteness()
  }, [calculateCompleteness])

  const toggleSection = (section: string) => {
    setExpandedSections(prev => {
      const next = new Set(prev)
      if (next.has(section)) {
        next.delete(section)
      } else {
        next.add(section)
      }
      return next
    })
  }

  const handlePreviewMatching = async () => {
    setShowMatchingPreview(true)
    try {
      const result = await aiMatchingService.findMatches(requirement as ServiceRequirement)
      setMatchingPreview(result)
    } catch (error) {
      console.error('Preview matching failed:', error)
    }
  }

  const handleSubmit = () => {
    if (completeness.score >= 80) {
      onSubmit(requirement as ServiceRequirement)
    } else {
      alert(`Please complete more fields. Current completeness: ${Math.round(completeness.score)}%`)
    }
  }

  const renderCategorySpecificFields = () => {
    switch (category) {
      case 'STORAGE':
        return <StorageFields requirement={requirement} setRequirement={setRequirement} />
      case 'TRANSPORTATION':
        return <TransportationFields requirement={requirement} setRequirement={setRequirement} />
      case 'FREIGHT':
        return <FreightFields requirement={requirement} setRequirement={setRequirement} />
      case 'CONSULTING':
        return <ConsultingFields requirement={requirement} setRequirement={setRequirement} />
      case 'MANPOWER':
        return <ManpowerFields requirement={requirement} setRequirement={setRequirement} />
      case 'TRANSLATION':
        return <TranslationFields requirement={requirement} setRequirement={setRequirement} />
      case 'CROSSDOCKING':
        return <CrossDockingFields requirement={requirement} setRequirement={setRequirement} />
      case 'WAREHOUSE_NETWORK':
        return <WarehouseNetworkFields requirement={requirement} setRequirement={setRequirement} />
      default:
        return null
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-slate-900 dark:via-slate-800 dark:to-slate-900 p-4 md:p-8">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mb-8"
        >
          <h1 className="text-4xl font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent mb-4">
            Service Requirement Form
          </h1>
          <p className="text-slate-600 dark:text-slate-400">
            Complete all fields for accurate AI-powered matching
          </p>
        </motion.div>

        {/* Completeness Indicator */}
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="mb-6 bg-white dark:bg-slate-800 rounded-2xl shadow-xl p-6 border border-slate-200 dark:border-slate-700"
        >
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-3">
              <div className={`w-12 h-12 rounded-full flex items-center justify-center ${
                completeness.score >= 80 ? 'bg-green-100 dark:bg-green-900' :
                completeness.score >= 60 ? 'bg-yellow-100 dark:bg-yellow-900' :
                'bg-red-100 dark:bg-red-900'
              }`}>
                {completeness.score >= 80 ? (
                  <CheckCircle2 className="w-6 h-6 text-green-600 dark:text-green-400" />
                ) : (
                  <AlertCircle className="w-6 h-6 text-yellow-600 dark:text-yellow-400" />
                )}
              </div>
              <div>
                <h3 className="font-semibold text-lg">Completeness Score</h3>
                <p className="text-sm text-slate-600 dark:text-slate-400">
                  {completeness.score >= 80 ? 'Ready for matching' :
                   completeness.score >= 60 ? 'Almost ready' :
                   'More information needed'}
                </p>
              </div>
            </div>
            <div className="text-right">
              <div className="text-3xl font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">
                {Math.round(completeness.score)}%
              </div>
              <div className="w-48 h-2 bg-slate-200 dark:bg-slate-700 rounded-full mt-2 overflow-hidden">
                <motion.div
                  className={`h-full ${
                    completeness.score >= 80 ? 'bg-green-500' :
                    completeness.score >= 60 ? 'bg-yellow-500' :
                    'bg-red-500'
                  }`}
                  initial={{ width: 0 }}
                  animate={{ width: `${completeness.score}%` }}
                  transition={{ duration: 0.5 }}
                />
              </div>
            </div>
          </div>

          {completeness.missing.length > 0 && (
            <div className="mt-4 p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">
              <p className="text-sm font-medium mb-2 text-slate-700 dark:text-slate-300">
                Missing Fields:
              </p>
              <div className="flex flex-wrap gap-2">
                {completeness.missing.map(field => (
                  <span
                    key={field}
                    className="px-3 py-1 bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400 rounded-full text-xs font-medium"
                  >
                    {field}
                  </span>
                ))}
              </div>
            </div>
          )}
        </motion.div>

        {/* Form Sections */}
        <div className="space-y-4">
          {/* Basic Information */}
          <FormSection
            title="Basic Information"
            icon={FileText}
            expanded={expandedSections.has('basic')}
            onToggle={() => toggleSection('basic')}
            required
          >
            <div className="space-y-4">
              <BasicFields requirement={requirement} setRequirement={setRequirement} />
              <Suspense fallback={null}>
                <SmartFieldSuggestions
                  category={category}
                  currentFields={requirement}
                  onSuggestionAccept={(field, value) => {
                    setRequirement({ ...requirement, [field]: value })
                  }}
                />
              </Suspense>
            </div>
          </FormSection>

          {/* Category-Specific Fields */}
          <FormSection
            title={`${category} Specific Requirements`}
            icon={getCategoryIcon(category)}
            expanded={expandedSections.has('category')}
            onToggle={() => toggleSection('category')}
            required
          >
            {renderCategorySpecificFields()}
          </FormSection>

          {/* Location */}
          <FormSection
            title="Location Details"
            icon={MapPin}
            expanded={expandedSections.has('location')}
            onToggle={() => toggleSection('location')}
            required
          >
            <EnhancedLocationPicker
              value={requirement.location}
              onChange={(location) => setRequirement({ ...requirement, location })}
              label="Service Location"
              required
            />
          </FormSection>

          {/* Timeline */}
          <FormSection
            title="Timeline & Schedule"
            icon={Calendar}
            expanded={expandedSections.has('timeline')}
            onToggle={() => toggleSection('timeline')}
            required
          >
            <div className="space-y-4">
              <TimelineFields requirement={requirement} setRequirement={setRequirement} />
              <Suspense fallback={<div className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">Loading timeline...</div>}>
                <TimelineVisualization
                  timeline={requirement.timeline || {}}
                  onTimelineChange={(timeline) => setRequirement({ ...requirement, timeline })}
                />
              </Suspense>
            </div>
          </FormSection>

          {/* Budget with Price Calculator */}
          <FormSection
            title="Budget & Pricing"
            icon={DollarSign}
            expanded={expandedSections.has('budget')}
            onToggle={() => toggleSection('budget')}
          >
            <div className="space-y-4">
              <Suspense fallback={<div className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">Loading calculator...</div>}>
                <PriceCalculator
                  requirement={requirement}
                  category={category}
                  onPriceUpdate={(price) => {
                    setRequirement({
                      ...requirement,
                      budget: { ...requirement.budget, ...price },
                    })
                  }}
                />
              </Suspense>
              <BudgetFields requirement={requirement} setRequirement={setRequirement} />
            </div>
          </FormSection>

          {/* Special Requirements */}
          <FormSection
            title="Special Requirements & Compliance"
            icon={CheckCircle2}
            expanded={expandedSections.has('requirements')}
            onToggle={() => toggleSection('requirements')}
          >
            <RequirementsFields requirement={requirement} setRequirement={setRequirement} />
          </FormSection>

          {/* File Attachments */}
          <FormSection
            title="Supporting Documents & Files"
            icon={Upload}
            expanded={expandedSections.has('attachments')}
            onToggle={() => toggleSection('attachments')}
          >
            <Suspense fallback={<div className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">Loading upload...</div>}>
              <EnhancedFileUpload
                value={attachments as any}
                onChange={(files) => setAttachments(files)}
                accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png"
                maxFiles={10}
                maxSizeMB={10}
                label="Upload Supporting Documents"
                description="Upload contracts, specifications, photos, or other relevant documents"
                showPreview={true}
              />
            </Suspense>
          </FormSection>

          {/* Real-Time Matching Preview */}
          <FormSection
            title="Live Matching Preview"
            icon={Sparkles}
            expanded={expandedSections.has('matching')}
            onToggle={() => toggleSection('matching')}
          >
            <Suspense fallback={<div className="p-4 bg-slate-50 dark:bg-slate-700/50 rounded-lg">Loading matches...</div>}>
              <RealtimeMatchingPreview
                requirement={requirement}
                category={category}
                onMatchSelect={(matchId) => {
                  window.location.href = `/marketplace/matching/${matchId}`
                }}
              />
            </Suspense>
          </FormSection>
        </div>

        {/* Auto-Save Status */}
        <AnimatePresence>
          {autoSaveStatus && (
            <motion.div
              initial={{ opacity: 0, y: -10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="fixed bottom-4 right-4 z-50"
            >
              <div
                className={`px-4 py-2 rounded-lg shadow-lg flex items-center gap-2 ${
                  autoSaveStatus === 'saved'
                    ? 'bg-green-500 text-white'
                    : autoSaveStatus === 'saving'
                    ? 'bg-blue-500 text-white'
                    : 'bg-red-500 text-white'
                }`}
              >
                {autoSaveStatus === 'saved' && <CheckCircle2 className="w-4 h-4" />}
                {autoSaveStatus === 'saving' && <RefreshCw className="w-4 h-4 animate-spin" />}
                {autoSaveStatus === 'error' && <AlertCircle className="w-4 h-4" />}
                <span className="text-sm font-medium">
                  {autoSaveStatus === 'saved' && 'Auto-saved'}
                  {autoSaveStatus === 'saving' && 'Saving...'}
                  {autoSaveStatus === 'error' && 'Save failed'}
                </span>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Actions */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="mt-8 flex items-center justify-between"
        >
          <div className="flex items-center gap-4">
            {lastSaved && (
              <span className="text-xs text-slate-500 dark:text-slate-400">
                Last saved: {lastSaved.toLocaleTimeString()}
              </span>
            )}
            <button
              onClick={() => setShowKeyboardShortcuts(true)}
              className="p-2 text-slate-500 hover:text-slate-700 dark:hover:text-slate-300 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700"
              title="Keyboard Shortcuts (Ctrl+/)"
            >
              <Keyboard className="w-4 h-4" />
            </button>
            <button
              onClick={saveToLocalStorage}
              className="px-4 py-2 text-sm bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg font-medium hover:bg-slate-300 dark:hover:bg-slate-600 transition-colors flex items-center gap-2"
            >
              <Save className="w-4 h-4" />
              Save Draft
            </button>
          </div>

          <div className="flex gap-4">
            {onCancel && (
              <button
                onClick={onCancel}
                className="px-6 py-3 bg-slate-200 dark:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg font-medium hover:bg-slate-300 dark:hover:bg-slate-600 transition-colors"
              >
                Cancel
              </button>
            )}
            <button
              onClick={handlePreviewMatching}
              className="px-6 py-3 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 rounded-lg font-medium hover:bg-blue-200 dark:hover:bg-blue-900/50 transition-colors flex items-center gap-2"
            >
              <Sparkles className="w-4 h-4" />
              Preview Matching
            </button>
            <button
              onClick={handleSubmit}
              disabled={completeness.score < 80}
              className={`px-6 py-3 rounded-lg font-medium transition-all flex items-center gap-2 ${
                completeness.score >= 80
                  ? 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white hover:shadow-lg hover:scale-105'
                  : 'bg-slate-300 dark:bg-slate-700 text-slate-500 dark:text-slate-400 cursor-not-allowed'
              }`}
            >
            <CheckCircle2 className="w-4 h-4" />
            Submit & Find Matches
          </button>
          </div>
        </motion.div>

        {/* Matching Preview Modal */}
        <AnimatePresence>
          {showMatchingPreview && matchingPreview && (
            <MatchingPreviewModal
              result={matchingPreview}
              onClose={() => setShowMatchingPreview(false)}
            />
          )}
        </AnimatePresence>

        {/* Keyboard Shortcuts Modal */}
        <AnimatePresence>
          {showKeyboardShortcuts && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4"
              onClick={() => setShowKeyboardShortcuts(false)}
            >
              <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                exit={{ scale: 0.9, opacity: 0 }}
                onClick={(e) => e.stopPropagation()}
                className="bg-white dark:bg-slate-800 rounded-xl shadow-xl max-w-md w-full p-6"
              >
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-semibold text-slate-900 dark:text-slate-100 flex items-center gap-2">
                    <Keyboard className="w-5 h-5" />
                    Keyboard Shortcuts
                  </h3>
                  <button
                    onClick={() => setShowKeyboardShortcuts(false)}
                    className="p-1 text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                  >
                    <X className="w-5 h-5" />
                  </button>
                </div>
                <div className="space-y-3">
                  {[
                    { key: 'Ctrl/Cmd + S', desc: 'Save draft' },
                    { key: 'Ctrl/Cmd + /', desc: 'Show shortcuts' },
                    { key: 'Esc', desc: 'Close modals' },
                  ].map((shortcut, idx) => (
                    <div key={idx} className="flex items-center justify-between p-2 hover:bg-slate-50 dark:hover:bg-slate-700 rounded">
                      <span className="text-sm text-slate-600 dark:text-slate-400">
                        {shortcut.desc}
                      </span>
                      <kbd className="px-2 py-1 text-xs font-semibold bg-slate-100 dark:bg-slate-700 text-slate-800 dark:text-slate-200 rounded border border-slate-300 dark:border-slate-600">
                        {shortcut.key}
                      </kbd>
                    </div>
                  ))}
                </div>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

// Helper Components
function FormSection({
  title,
  icon: Icon,
  expanded,
  onToggle,
  required,
  children,
}: {
  title: string
  icon: any
  expanded: boolean
  onToggle: () => void
  required?: boolean
  children: React.ReactNode
}) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 overflow-hidden"
    >
      <button
        onClick={onToggle}
        className="w-full p-6 flex items-center justify-between hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors"
      >
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center">
            <Icon className="w-5 h-5 text-blue-600 dark:text-blue-400" />
          </div>
          <div className="text-left">
            <h3 className="font-semibold text-lg flex items-center gap-2">
              {title}
              {required && <span className="text-red-500 text-sm">*</span>}
            </h3>
          </div>
        </div>
        {expanded ? (
          <ChevronDown className="w-5 h-5 text-slate-400" />
        ) : (
          <ChevronRight className="w-5 h-5 text-slate-400" />
        )}
      </button>
      <AnimatePresence>
        {expanded && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3 }}
            className="overflow-hidden"
          >
            <div className="p-6 border-t border-slate-200 dark:border-slate-700">
              {children}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  )
}

