// COMPREHENSIVE FIELD COMPONENTS - FULL IMPLEMENTATIONS
// ============================================================================

function BasicFields({ requirement, setRequirement }: any) {
  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium mb-2 text-slate-700 dark:text-slate-300">
            Urgency <span className="text-red-500">*</span>
          </label>
          <select
            value={requirement.urgency || 'MEDIUM'}
            onChange={(e) => setRequirement({ ...requirement, urgency: e.target.value })}
            className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-slate-100 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
          >
            <option value="LOW">Low - No immediate rush</option>
            <option value="MEDIUM">Medium - Standard timeline</option>
            <option value="HIGH">High - Priority needed</option>
            <option value="URGENT">Urgent - Immediate attention</option>
          </select>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
            How urgent is your service requirement?
          </p>
        </div>

        <div>
          <div className="flex items-center justify-between mb-2">
            <label className="block text-sm font-medium text-slate-700 dark:text-slate-300">
              Notes / Additional Information
            </label>
            <Suspense fallback={null}>
              <VoiceInput
                onTranscript={(text) => {
                  setRequirement({ ...requirement, notes: (requirement.notes || '') + ' ' + text })
                }}
                language="en-US"
              />
            </Suspense>
          </div>
          <Suspense fallback={
            <textarea
              value={requirement.notes || ''}
              onChange={(e) => setRequirement({ ...requirement, notes: e.target.value })}
              rows={3}
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
              placeholder="Enter additional information..."
            />
          }>
            <RichTextEditor
              value={requirement.notes || ''}
              onChange={(value) => setRequirement({ ...requirement, notes: value })}
              placeholder="Enter detailed notes and additional information..."
              minHeight="150px"
            />
          </Suspense>
        </div>
      </div>
    </div>
  )
}

function StorageFields({ requirement, setRequirement }: any) {
  const req = requirement as any
  const storageReq = req as any

  return (
    <div className="space-y-6">
      {/* Service Type */}
      <div>
        <label className="block text-sm font-medium mb-2 text-slate-700 dark:text-slate-300">
          Storage Service Type <span className="text-red-500">*</span>
        </label>
        <select
          value={storageReq.serviceType || ''}
          onChange={(e) => setRequirement({ ...requirement, serviceType: e.target.value })}
          className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 focus:ring-2 focus:ring-blue-500"
        >
          <option value="">Select storage type...</option>
          <option value="GENERAL_STORAGE">General Storage</option>
          <option value="COLD_STORAGE">Cold Storage (Refrigerated)</option>
          <option value="HAZMAT_STORAGE">Hazmat Storage (Hazardous Materials)</option>
          <option value="BONDED_STORAGE">Bonded Storage (Customs)</option>
          <option value="BULK_STORAGE">Bulk Storage</option>
          <option value="RACK_STORAGE">Rack Storage</option>
          <option value="OPEN_YARD">Open Yard Storage</option>
          <option value="TEMPORARY_STORAGE">Temporary Storage</option>
          <option value="LONG_TERM_STORAGE">Long-Term Storage</option>
        </select>
      </div>

      {/* Capacity Requirements */}
      <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-5 border border-slate-200 dark:border-slate-600">
        <h4 className="font-semibold mb-4 text-slate-800 dark:text-slate-200 flex items-center gap-2">
          <Package className="w-4 h-4" />
          Capacity Requirements <span className="text-red-500">*</span>
        </h4>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium mb-2">Capacity Unit</label>
            <select
              value={storageReq.capacity?.unit || 'CUBIC_METERS'}
              onChange={(e) => setRequirement({
                ...requirement,
                capacity: { ...storageReq.capacity, unit: e.target.value }
              })}
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            >
              <option value="CUBIC_METERS">Cubic Meters (m³)</option>
              <option value="SQUARE_METERS">Square Meters (m²)</option>
              <option value="PALLETS">Pallets</option>
              <option value="TONS">Tons</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">Required Capacity</label>
            <input
              type="number"
              value={storageReq.capacity?.volume || storageReq.capacity?.area || storageReq.capacity?.pallets || storageReq.capacity?.weight || ''}
              onChange={(e) => {
                const unit = storageReq.capacity?.unit || 'CUBIC_METERS'
                const update: any = { ...storageReq.capacity, unit }
                if (unit === 'CUBIC_METERS') update.volume = Number(e.target.value)
                else if (unit === 'SQUARE_METERS') update.area = Number(e.target.value)
                else if (unit === 'PALLETS') update.pallets = Number(e.target.value)
                else if (unit === 'TONS') update.weight = Number(e.target.value)
                setRequirement({ ...requirement, capacity: update })
              }}
              placeholder="Enter capacity"
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            />
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={storageReq.capacity?.growthExpected || false}
              onChange={(e) => setRequirement({
                ...requirement,
                capacity: { ...storageReq.capacity, growthExpected: e.target.checked }
              })}
              className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
            />
            <span className="text-sm">Growth Expected (May need more capacity later)</span>
          </label>
          {storageReq.capacity?.growthExpected && (
            <div>
              <label className="block text-sm font-medium mb-2">Peak Capacity</label>
              <input
                type="number"
                value={storageReq.capacity?.peakCapacity || ''}
                onChange={(e) => setRequirement({
                  ...requirement,
                  capacity: { ...storageReq.capacity, peakCapacity: Number(e.target.value) }
                })}
                placeholder="Peak capacity needed"
                className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
              />
            </div>
          )}
        </div>
      </div>

      {/* Material Details */}
      <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-5 border border-slate-200 dark:border-slate-600">
        <h4 className="font-semibold mb-4 text-slate-800 dark:text-slate-200 flex items-center gap-2">
          <Package className="w-4 h-4" />
          Material Details
        </h4>
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Material Types</label>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
              {['Electronics', 'Food & Beverages', 'Chemicals', 'Textiles', 'Machinery', 'Pharmaceuticals', 'Automotive', 'Other'].map(type => (
                <label key={type} className="flex items-center gap-2 cursor-pointer p-2 hover:bg-slate-100 dark:hover:bg-slate-600 rounded">
                  <input
                    type="checkbox"
                    checked={storageReq.materials?.type?.includes(type) || false}
                    onChange={(e) => {
                      const types = storageReq.materials?.type || []
                      const newTypes = e.target.checked
                        ? [...types, type]
                        : types.filter((t: string) => t !== type)
                      setRequirement({
                        ...requirement,
                        materials: { ...storageReq.materials, type: newTypes }
                      })
                    }}
                    className="w-4 h-4 text-blue-600 rounded"
                  />
                  <span className="text-sm">{type}</span>
                </label>
              ))}
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-600">
              <input
                type="checkbox"
                checked={storageReq.materials?.hazardous || false}
                onChange={(e) => setRequirement({
                  ...requirement,
                  materials: { ...storageReq.materials, hazardous: e.target.checked }
                })}
                className="w-4 h-4 text-blue-600 rounded"
              />
              <span className="text-sm font-medium">Hazardous Materials</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-600">
              <input
                type="checkbox"
                checked={storageReq.materials?.temperatureControlled || false}
                onChange={(e) => setRequirement({
                  ...requirement,
                  materials: { ...storageReq.materials, temperatureControlled: e.target.checked }
                })}
                className="w-4 h-4 text-blue-600 rounded"
              />
              <span className="text-sm font-medium">Temperature Controlled</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer p-3 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-600">
              <input
                type="checkbox"
                checked={storageReq.materials?.humidityControlled || false}
                onChange={(e) => setRequirement({
                  ...requirement,
                  materials: { ...storageReq.materials, humidityControlled: e.target.checked }
                })}
                className="w-4 h-4 text-blue-600 rounded"
              />
              <span className="text-sm font-medium">Humidity Controlled</span>
            </label>
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">Special Handling Requirements</label>
            <textarea
              value={storageReq.materials?.specialHandling?.join(', ') || ''}
              onChange={(e) => setRequirement({
                ...requirement,
                materials: {
                  ...storageReq.materials,
                  specialHandling: e.target.value.split(',').map(s => s.trim()).filter(Boolean)
                }
              })}
              placeholder="e.g., Fragile handling, No stacking, Special packaging..."
              rows={2}
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            />
          </div>
        </div>
      </div>

      {/* Operational Requirements */}
      <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-5 border border-slate-200 dark:border-slate-600">
        <h4 className="font-semibold mb-4 text-slate-800 dark:text-slate-200 flex items-center gap-2">
          <Network className="w-4 h-4" />
          Operational Requirements
        </h4>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-4">
          {[
            { key: 'inventoryManagement', label: 'Inventory Management' },
            { key: 'realTimeTracking', label: 'Real-Time Tracking' },
            { key: 'reporting', label: 'Reporting' },
            { key: 'handling', label: 'Material Handling' },
            { key: 'packaging', label: 'Packaging' },
            { key: 'labeling', label: 'Labeling' },
          ].map(op => (
            <label key={op.key} className="flex items-center gap-2 cursor-pointer p-2 hover:bg-slate-100 dark:hover:bg-slate-600 rounded">
              <input
                type="checkbox"
                checked={storageReq.operations?.[op.key] || false}
                onChange={(e) => setRequirement({
                  ...requirement,
                  operations: { ...storageReq.operations, [op.key]: e.target.checked }
                })}
                className="w-4 h-4 text-blue-600 rounded"
              />
              <span className="text-sm">{op.label}</span>
            </label>
          ))}
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium mb-2">Access Hours</label>
            <select
              value={storageReq.operations?.accessHours || ''}
              onChange={(e) => setRequirement({
                ...requirement,
                operations: { ...storageReq.operations, accessHours: e.target.value }
              })}
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            >
              <option value="">Select access hours...</option>
              <option value="24/7">24/7 Access</option>
              <option value="Business Hours">Business Hours (8 AM - 6 PM)</option>
              <option value="Extended">Extended Hours (6 AM - 10 PM)</option>
              <option value="Weekdays">Weekdays Only</option>
              <option value="Custom">Custom Schedule</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">Security Level</label>
            <select
              value={storageReq.operations?.securityLevel || 'STANDARD'}
              onChange={(e) => setRequirement({
                ...requirement,
                operations: { ...storageReq.operations, securityLevel: e.target.value }
              })}
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            >
              <option value="STANDARD">Standard Security</option>
              <option value="HIGH">High Security</option>
              <option value="MAXIMUM">Maximum Security</option>
            </select>
          </div>
        </div>
      </div>

      {/* Service Level */}
      <div className="bg-slate-50 dark:bg-slate-700/50 rounded-xl p-5 border border-slate-200 dark:border-slate-600">
        <h4 className="font-semibold mb-4 text-slate-800 dark:text-slate-200 flex items-center gap-2">
          <Target className="w-4 h-4" />
          Service Level Requirements
        </h4>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium mb-2">Inbound Frequency</label>
            <select
              value={storageReq.serviceLevel?.inboundFrequency || ''}
              onChange={(e) => setRequirement({
                ...requirement,
                serviceLevel: { ...storageReq.serviceLevel, inboundFrequency: e.target.value }
              })}
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            >
              <option value="">Select frequency...</option>
              <option value="DAILY">Daily</option>
              <option value="WEEKLY">Weekly</option>
              <option value="ON_DEMAND">On Demand</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">Outbound Frequency</label>
            <select
              value={storageReq.serviceLevel?.outboundFrequency || ''}
              onChange={(e) => setRequirement({
                ...requirement,
                serviceLevel: { ...storageReq.serviceLevel, outboundFrequency: e.target.value }
              })}
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            >
              <option value="">Select frequency...</option>
              <option value="DAILY">Daily</option>
              <option value="WEEKLY">Weekly</option>
              <option value="ON_DEMAND">On Demand</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">Response Time (hours)</label>
            <input
              type="number"
              value={storageReq.serviceLevel?.responseTime || ''}
              onChange={(e) => setRequirement({
                ...requirement,
                serviceLevel: { ...storageReq.serviceLevel, responseTime: Number(e.target.value) }
              })}
              placeholder="e.g., 24"
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-2">Minimum Commitment (months)</label>
            <input
              type="number"
              value={storageReq.serviceLevel?.minimumCommitment || ''}
              onChange={(e) => setRequirement({
                ...requirement,
                serviceLevel: { ...storageReq.serviceLevel, minimumCommitment: Number(e.target.value) }
              })}
              placeholder="e.g., 6"
              className="w-full px-4 py-2.5 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700"
            />
          </div>
        </div>
      </div>
    </div>
  )
}

// All field components are now imported from ServiceRequirementFormFields.tsx

function MatchingPreviewModal({ result, onClose }: any) {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
      onClick={onClose}
    >
      <motion.div
        initial={{ scale: 0.9, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.9, opacity: 0 }}
        onClick={(e) => e.stopPropagation()}
        className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto"
      >
        <div className="p-6 border-b border-slate-200 dark:border-slate-700">
          <h2 className="text-2xl font-bold">Matching Preview</h2>
          <p className="text-slate-600 dark:text-slate-400">Top matches found</p>
        </div>
        <div className="p-6">
          {result.matches?.slice(0, 3).map((match: any, idx: number) => (
            <div key={idx} className="mb-4 p-4 border rounded-lg">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-semibold">{match.listing.title || 'Service'}</h3>
                  <p className="text-sm text-slate-600">Match Score: {match.matchScore}%</p>
                </div>
                <div className="text-right">
                  <div className="text-2xl font-bold text-blue-600">{match.matchScore}%</div>
                  <div className="text-sm text-slate-500">Confidence</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </motion.div>
    </motion.div>
  )
}

// Helper functions
function getCategoryIcon(category: string) {
  const icons: Record<string, any> = {
    STORAGE: Building2,
    TRANSPORTATION: Truck,
    FREIGHT: Package,
    CONSULTING: Users,
    MANPOWER: Users,
    TRANSLATION: Languages,
    CROSSDOCKING: Network,
    WAREHOUSE_NETWORK: Network,
  }
  return icons[category] || FileText
}

function getRequiredFields(category: string): string[] {
  const fields: Record<string, string[]> = {
    STORAGE: ['location', 'capacity', 'timeline'],
    TRANSPORTATION: ['route', 'cargo', 'timeline'],
    FREIGHT: ['route', 'cargo', 'timeline'],
    CONSULTING: ['project', 'consultant', 'serviceLevel'],
    MANPOWER: ['staff', 'employment', 'serviceLevel'],
    TRANSLATION: ['translation', 'serviceLevel'],
    CROSSDOCKING: ['facility', 'volume', 'operations'],
    WAREHOUSE_NETWORK: ['network', 'operations', 'capacity'],
  }
  return fields[category] || []
}

function hasField(obj: any, field: string): boolean {
  const parts = field.split('.')
  let current = obj
  for (const part of parts) {
    if (current && typeof current === 'object' && part in current) {
      current = current[part]
    } else {
      return false
    }
  }
  return current !== undefined && current !== null && current !== ''
}

/**
 * Smart Field Suggestions Component
 * AI-powered field suggestions based on user history and context
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Sparkles, X, Check, Lightbulb } from 'lucide-react'
import { knowledgeBaseService } from '@/lib/services/knowledge-base'

interface SmartFieldSuggestionsProps {
  category: string
  currentFields: Record<string, any>
  onSuggestionAccept: (field: string, value: any) => void
}

export default function SmartFieldSuggestions({
  category,
  currentFields,
  onSuggestionAccept,
}: SmartFieldSuggestionsProps) {
  const [suggestions, setSuggestions] = useState<Array<{
    field: string
    value: any
    reason: string
    confidence: number
  }>>([])
  const [isLoading, setIsLoading] = useState(false)

  useEffect(() => {
    loadSuggestions()
  }, [category, currentFields])

  const loadSuggestions = async () => {
    setIsLoading(true)
    try {
      // Use knowledge base to get suggestions based on similar requirements
      const similarRequirements = await knowledgeBaseService.search({
        query: `requirements for ${category} service`,
        limit: 5,
      })

      // Generate suggestions based on common patterns
      const generatedSuggestions = generateSuggestions(similarRequirements, currentFields)
      setSuggestions(generatedSuggestions)
    } catch (error) {
      console.error('Failed to load suggestions:', error)
      setSuggestions([])
    } finally {
      setIsLoading(false)
    }
  }

  const generateSuggestions = (similar: any[], current: Record<string, any>) => {
    const suggestions: Array<{
      field: string
      value: any
      reason: string
      confidence: number
    }> = []

    // Analyze common patterns
    const commonValues: Record<string, any> = {}

    similar.forEach((item) => {
      Object.keys(item).forEach((key) => {
        if (!current[key] && item[key]) {
          if (!commonValues[key]) {
            commonValues[key] = { value: item[key], count: 1 }
          } else {
            commonValues[key].count++
          }
        }
      })
    })

    // Generate suggestions for most common values
    Object.entries(commonValues).forEach(([field, data]: [string, any]) => {
      if (data.count >= 2) {
        suggestions.push({
          field,
          value: data.value,
          reason: `Commonly used in similar ${category} requirements`,
          confidence: Math.min(90, data.count * 20),
        })
      }
    })

    return suggestions.slice(0, 5) // Top 5 suggestions
  }

  const handleAccept = (suggestion: typeof suggestions[0]) => {
    onSuggestionAccept(suggestion.field, suggestion.value)
    setSuggestions((prev) => prev.filter((s) => s.field !== suggestion.field))
  }

  const handleDismiss = (field: string) => {
    setSuggestions((prev) => prev.filter((s) => s.field !== field))
  }

  if (suggestions.length === 0 && !isLoading) {
    return null
  }

  return (
    <AnimatePresence>
      {suggestions.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          className="p-4 bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 rounded-xl border border-blue-200 dark:border-blue-800"
        >
          <div className="flex items-center gap-2 mb-3">
            <Lightbulb className="w-5 h-5 text-blue-600 dark:text-blue-400" />
            <h4 className="font-semibold text-slate-800 dark:text-slate-200">
              Smart Suggestions
            </h4>
            <Sparkles className="w-4 h-4 text-blue-500" />
          </div>

          <div className="space-y-2">
            {suggestions.map((suggestion) => (
              <motion.div
                key={suggestion.field}
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                className="flex items-center justify-between p-3 bg-white dark:bg-slate-700 rounded-lg border border-blue-100 dark:border-blue-900/50"
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-sm font-medium text-slate-800 dark:text-slate-200 capitalize">
                      {suggestion.field.replace(/([A-Z])/g, ' $1').trim()}
                    </span>
                    <span className="text-xs text-slate-500 dark:text-slate-400">
                      {suggestion.confidence}% confidence
                    </span>
                  </div>
                  <p className="text-xs text-slate-600 dark:text-slate-400">
                    {suggestion.reason}
                  </p>
                  <p className="text-sm font-medium text-blue-600 dark:text-blue-400 mt-1">
                    {typeof suggestion.value === 'object'
                      ? JSON.stringify(suggestion.value)
                      : String(suggestion.value)}
                  </p>
                </div>
                <div className="flex items-center gap-2 ml-4">
                  <button
                    onClick={() => handleAccept(suggestion)}
                    className="p-1.5 text-green-600 hover:bg-green-50 dark:hover:bg-green-900/20 rounded"
                    title="Accept suggestion"
                  >
                    <Check className="w-4 h-4" />
                  </button>
                  <button
                    onClick={() => handleDismiss(suggestion.field)}
                    className="p-1.5 text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-600 rounded"
                    title="Dismiss"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              </motion.div>
            ))}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

/**
