  useEffect(() => {
    loadContract()
  }, [contractId])

  const loadContract = async () => {
    try {
      const response = await fetch(`/api/marketplace/contracts/${contractId}`)
      const result = await response.json()
      if (result.success) {
        setContract(result.data)
