                        className={`w-full pl-8 pr-8 py-1.5 bg-transparent ${
                          isDarkMode ? 'text-white placeholder-gray-500' : 'text-gray-900 placeholder-gray-400'
                        } outline-none text-xs`}
                      />
                      <button
                        onClick={() => {
                          setShowSearchBar(false)
                          setSearchQuery('')
