/**
 * Showcase Navigation Tabs
 * Beautiful, contextual navigation tabs for showcase page
 * Matches revolutionary navigation design
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { usePathname } from 'next/navigation'
import Link from 'next/link'
import { useShowcase } from '@/contexts/ShowcaseContext'

interface ShowcaseNavigationTabsProps {
  isDarkMode: boolean
}

export default function ShowcaseNavigationTabs({
  isDarkMode,
}: ShowcaseNavigationTabsProps) {
  const pathname = usePathname()
  const { activeSection, setActiveSection } = useShowcase()
  const [hoveredTab, setHoveredTab] = useState<string | null>(null)

  const showcaseTabs = [
    { id: 'hero', label: 'Hero', icon: 'ri-home-line', href: '/showcase#hero' },
    { id: 'orchestration', label: '3D System', icon: 'ri-stack-line', href: '/showcase#orchestration' },
    { id: 'metrics', label: 'Metrics', icon: 'ri-bar-chart-line', href: '/showcase#metrics' },
    { id: 'video', label: 'Videos', icon: 'ri-video-line', href: '/showcase#video' },
    { id: 'compliance', label: 'Compliance', icon: 'ri-shield-check-line', href: '/showcase#compliance' },
    { id: 'stakeholders', label: 'Stakeholders', icon: 'ri-user-line', href: '/showcase#stakeholders' },
    { id: 'aivision', label: 'AI Vision', icon: 'ri-eye-line', href: '/showcase#aivision' },
    { id: '3d', label: '3D Warehouse', icon: 'ri-warehouse-line', href: '/showcase#3d' },
    { id: 'workflow', label: 'Workflows', icon: 'ri-flow-chart', href: '/showcase#workflow' },
    { id: 'architecture', label: 'Architecture', icon: 'ri-node-tree', href: '/showcase#architecture' },
  ]

  // Scroll spy for active section
  useEffect(() => {
    const handleScroll = () => {
      const sections = showcaseTabs.map(tab => tab.id)
      const scrollPosition = window.scrollY + 200

      for (const sectionId of sections) {
        const element = document.getElementById(sectionId)
        if (element) {
          const { offsetTop, offsetHeight } = element
          if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
            setActiveSection(sectionId)
            break
          }
        }
      }
    }

    window.addEventListener('scroll', handleScroll, { passive: true })
    return () => window.removeEventListener('scroll', handleScroll)
  }, [setActiveSection, showcaseTabs, activeSection])

  const scrollToSection = (sectionId: string) => {
    const element = document.getElementById(sectionId)
    if (element) {
      const offset = 112 // Account for fixed nav height
      const elementPosition = element.getBoundingClientRect().top
      const offsetPosition = elementPosition + window.pageYOffset - offset

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      })
    }
  }

  if (pathname !== '/showcase') return null

  return (
    <div className={`flex items-center gap-1 overflow-x-auto custom-scrollbar flex-1 min-w-0 px-2`}>
      {showcaseTabs.map((tab) => {
        const active = activeSection === tab.id
        const isHovered = hoveredTab === tab.id

        return (
          <motion.div
            key={tab.id}
            onHoverStart={() => setHoveredTab(tab.id)}
            onHoverEnd={() => setHoveredTab(null)}
            className="relative flex-shrink-0"
          >
            <motion.button
              onClick={() => scrollToSection(tab.id)}
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              className={`flex items-center gap-2 px-3 sm:px-4 py-2 rounded-lg text-sm font-medium transition-all relative group ${
                active
                  ? isDarkMode
                    ? 'text-cyan-400'
                    : 'text-blue-600'
                  : isDarkMode
                    ? 'text-gray-400 hover:text-white'
                    : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              {/* Active indicator */}
              {active && (
                <motion.div
                  layoutId="activeShowcaseTab"
                  className={`absolute bottom-0 left-0 right-0 h-0.5 rounded-full ${
                    isDarkMode ? 'bg-cyan-400' : 'bg-blue-600'
                  }`}
                  transition={{ type: 'spring', stiffness: 500, damping: 30 }}
                />
              )}

              {/* Hover glow */}
              {isHovered && !active && (
                <motion.div
                  className={`absolute inset-0 rounded-lg ${
                    isDarkMode ? 'bg-gray-800/50' : 'bg-gray-100/50'
                  }`}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                />
              )}

              <i className={`${tab.icon} text-base flex-shrink-0 relative z-10`}></i>
              <span className="hidden sm:inline whitespace-nowrap relative z-10">{tab.label}</span>
            </motion.button>
          </motion.div>
        )
      })}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { getPickTasksAction, completePickTaskAction } from '@/app/actions/wms/outboundActions'
import { useAuth } from '@/contexts/AuthContext'
import type { PickTask } from '@prisma/client'

// Simple helper types if PickTask doesn't export nicely or has relations
type PickTaskWithRelations = PickTask & { shipment?: any }

export default function PickingInterface() {
    const { user } = useAuth()
    const [tasks, setTasks] = useState<PickTaskWithRelations[]>([])
    const [loading, setLoading] = useState(true)
    const [activeTask, setActiveTask] = useState<PickTaskWithRelations | null>(null)

    const [scanBin, setScanBin] = useState('')
    const [confirmQty, setConfirmQty] = useState(0)
    const [step, setStep] = useState<'LIST' | 'SCAN_BIN' | 'CONFIRM_QTY'>('LIST')

    // Load Tasks
    useEffect(() => {
        loadTasks()
    }, [])

    async function loadTasks() {
        setLoading(true)
        const res = await getPickTasksAction(user?.tenantId || 'tenant-1')
        if (res.success && res.data) {
            setTasks(res.data)
        }
        setLoading(false)
    }

    const startTask = (task: PickTaskWithRelations) => {
        setActiveTask(task)
        setScanBin('')
        setConfirmQty(task.quantity)
        setStep('SCAN_BIN')
    }

    const handleBinScan = (e: React.FormEvent) => {
        e.preventDefault()
        // Verify Bin
        if (activeTask && scanBin.trim().toUpperCase() === activeTask.fromBinId.toUpperCase()) {
            setStep('CONFIRM_QTY')
        } else {
            alert(`Invalid Bin! Go to ${activeTask?.fromBinId}`)
        }
    }

    const handleConfirmPick = async (e: React.FormEvent) => {
        e.preventDefault()
        if (!activeTask) return

        if (confirmQty > activeTask.quantity) {
            alert("Cannot pick more than requested!")
            return
        }

        setLoading(true)
        const res = await completePickTaskAction(activeTask.id, confirmQty, user?.id || 'picker-1')
        if (res.success) {
            // Success
            setActiveTask(null)
            setStep('LIST')
            loadTasks() // Refresh
        } else {
            alert("Error: " + res.error)
            setLoading(false)
        }
    }

    if (loading && tasks.length === 0) {
        return <div className="p-8 text-center text-gray-500">Loading Pick Tasks...</div>
    }

    return (
        <div className="min-h-screen bg-black text-white p-4 max-w-md mx-auto relative">
            {/* Header */}
            <header className="flex items-center justify-between mb-6 pb-4 border-b border-gray-800">
                <div>
                    <h1 className="text-xl font-bold">Picking</h1>
                    <p className="text-xs text-gray-400">Time: {new Date().toLocaleTimeString()}</p>
                </div>
                <div className="bg-blue-600/20 text-blue-400 px-3 py-1 rounded-full text-xs font-mono">
                    {tasks.length} Tasks
                </div>
            </header>

            {/* VIEW: TASK LIST */}
            {step === 'LIST' && (
                <div className="space-y-3">
                    {tasks.length === 0 ? (
                        <div className="text-center py-10 text-gray-500">
                            <i className="ri-check-double-line text-4xl mb-2 block"></i>
                            All caught up! No tasks.
                        </div>
                    ) : (
                        tasks.map(task => (
                            <motion.div
                                key={task.id}
                                layoutId={task.id}
                                onClick={() => startTask(task)}
                                className="bg-[#1f2937] border border-gray-700 p-4 rounded-xl active:bg-gray-700 cursor-pointer shadow-sm relative overflow-hidden"
                            >
                                {task.priority === 'HIGH' && <div className="absolute top-0 right-0 p-1 bg-red-500 md:rounded-bl-lg"></div>}
                                <div className="flex justify-between items-start mb-2">
                                    <div>
                                        <h3 className="font-mono text-cyan-400 font-bold text-lg">{task.fromBinId}</h3>
                                        <p className="text-xs text-gray-400">Source Bin</p>
                                    </div>
                                    <div className="text-right">
                                        <h3 className="font-mono text-white font-bold text-lg">{task.quantity} EA</h3>
                                        <p className="text-xs text-gray-400">Qty</p>
                                    </div>
                                </div>
                                <div className="bg-black/30 p-2 rounded flex items-center gap-3">
                                    <div className="w-8 h-8 bg-gray-600 rounded flex items-center justify-center text-xs">IMG</div>
                                    <div>
                                        <p className="text-sm font-medium">{task.sku}</p>
                                        <p className="text-xs text-gray-400 truncate w-40">Item Description...</p>
                                    </div>
                                </div>
                            </motion.div>
                        ))
                    )}
                </div>
            )}

            {/* VIEW: SCAN BIN */}
            {step === 'SCAN_BIN' && activeTask && (
                <div className="flex flex-col h-[80vh]">
                    <button onClick={() => setStep('LIST')} className="mb-4 text-gray-400 flex items-center gap-2">
                        <i className="ri-arrow-left-line"></i> Back to List
                    </button>

                    <div className="bg-[#1f2937] p-6 rounded-2xl border border-gray-700 flex-1 flex flex-col items-center justify-center text-center">
                        <h2 className="text-gray-400 text-sm mb-2">Go to Bin</h2>
                        <h1 className="text-5xl font-mono font-bold text-cyan-400 mb-8">{activeTask.fromBinId}</h1>

                        <p className="text-white mb-6 bg-blue-600/20 px-4 py-2 rounded-lg">
                            Item: <span className="font-bold">{activeTask.sku}</span>
                        </p>

                        <form onSubmit={handleBinScan} className="w-full">
                            <input
                                autoFocus
                                type="text"
                                value={scanBin}
                                onChange={e => setScanBin(e.target.value)}
                                placeholder="Scan Bin Barcode"
                                className="w-full bg-black border-2 border-cyan-500/50 rounded-xl px-4 py-4 text-center text-2xl font-mono text-white focus:outline-none focus:border-cyan-400"
                            />
                            <p className="text-xs text-gray-500 mt-4">Simulate: Type "{activeTask.fromBinId}"</p>
                        </form>
                    </div>
                </div>
            )}

            {/* VIEW: CONFIRM QTY */}
            {step === 'CONFIRM_QTY' && activeTask && (
                <div className="flex flex-col h-[80vh]">
                    <div className="mb-6">
                        <h1 className="text-2xl font-bold text-green-400 flex items-center gap-2">
                            <i className="ri-checkbox-circle-line"></i> Bin Verified
                        </h1>
                        <p className="text-gray-400">Pick {activeTask.sku}</p>
                    </div>

                    <div className="bg-[#1f2937] p-6 rounded-2xl border border-gray-700 flex-1">
                        <div className="flex justify-between items-center mb-8 border-b border-gray-700 pb-4">
                            <span className="text-gray-400">Required</span>
                            <span className="text-3xl font-bold">{activeTask.quantity}</span>
                        </div>

                        <form onSubmit={handleConfirmPick} className="space-y-6">
                            <div>
                                <label className="block text-sm text-gray-400 mb-2">Confirm Quantity</label>
                                <div className="flex items-center gap-4">
                                    <button type="button" onClick={() => setConfirmQty(q => Math.max(0, q - 1))} className="w-12 h-12 bg-gray-700 rounded-lg text-xl font-bold">-</button>
                                    <input
                                        type="number"
                                        value={confirmQty}
                                        onChange={e => setConfirmQty(Number(e.target.value))}
                                        className="flex-1 bg-black border border-gray-600 rounded-lg px-4 py-3 text-center text-2xl font-bold"
                                    />
                                    <button type="button" onClick={() => setConfirmQty(q => q + 1)} className="w-12 h-12 bg-gray-700 rounded-lg text-xl font-bold">+</button>
                                </div>
                            </div>

                            <button
                                type="submit"
                                disabled={loading}
                                className="w-full py-4 bg-green-600 hover:bg-green-500 text-white rounded-xl text-lg font-bold shadow-lg shadow-green-900/20"
                            >
                                {loading ? 'Confirming...' : 'Confirm & Complete'}
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    )
}

/**
 * Intelligent Permission Manager Component
 * 
 * World-class UI/UX for permission management with:
 * - Visual permission builder
 * - AI-powered recommendations
 * - Pros/cons analysis
 * - Risk warnings
 * - Approval workflow
 * - Conflict detection
 * - Best practice suggestions
 * 
 * Industry Standard: Enterprise Permission Management UX
 */

'use client'

import { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { User, HierarchicalPermission, ModuleId, FeatureId, TabId, Action } from '@/types/user'
import { permissionEngine, PermissionAnalysis, PermissionRecommendation, PermissionWarning } from '@/lib/services/auth/permissionEngine'
import { 
  RiShieldUserLine, 
  RiAlertLine, 
  RiCheckboxCircleLine, 
  RiCloseCircleLine,
  RiInformationLine,
  RiLockLine,
  RiEyeLine,
  RiEditLine,
  RiDeleteBinLine,
  RiSettings3Line,
  RiArrowRightLine,
  RiLightbulbLine,
  RiErrorWarningLine,
  RiCheckLine,
  RiCloseLine,
} from 'react-icons/ri'

interface IntelligentPermissionManagerProps {
  user: User
  onPermissionsChange: (permissions: HierarchicalPermission[]) => void
  mode?: 'view' | 'edit' | 'approve'
  showRecommendations?: boolean
  showWarnings?: boolean
  requireApproval?: boolean
}

export default function IntelligentPermissionManager({
  user,
  onPermissionsChange,
  mode = 'edit',
  showRecommendations = true,
  showWarnings = true,
  requireApproval = true,
}: IntelligentPermissionManagerProps) {
  const [permissions, setPermissions] = useState<HierarchicalPermission[]>(
    user.hierarchicalPermissions || []
  )
  const [analysis, setAnalysis] = useState<PermissionAnalysis | null>(null)
  const [selectedPermission, setSelectedPermission] = useState<HierarchicalPermission | null>(null)
  const [showBuilder, setShowBuilder] = useState(false)
  const [isAnalyzing, setIsAnalyzing] = useState(false)
  const [showApprovalModal, setShowApprovalModal] = useState(false)
  const [approvalReason, setApprovalReason] = useState('')

  // Analyze permissions when they change
  useEffect(() => {
    if (permissions.length > 0) {
      analyzePermissions()
    }
  }, [permissions])

  const analyzePermissions = async () => {
    setIsAnalyzing(true)
    try {
      const result = await permissionEngine.analyzePermissions(user, permissions)
      setAnalysis(result)
    } catch (error) {
      console.error('Permission analysis error:', error)
    } finally {
      setIsAnalyzing(false)
    }
  }

  const handleAddPermission = (permission: HierarchicalPermission) => {
    const newPermissions = [...permissions, permission]
    setPermissions(newPermissions)
    onPermissionsChange(newPermissions)
  }

  const handleRemovePermission = (index: number) => {
    const newPermissions = permissions.filter((_, i) => i !== index)
    setPermissions(newPermissions)
    onPermissionsChange(newPermissions)
  }

  const handleRequestApproval = () => {
    if (analysis?.requiresApproval) {
      setShowApprovalModal(true)
    }
  }

  const getRiskColor = (riskLevel: string) => {
    switch (riskLevel) {
      case 'CRITICAL': return 'text-red-400 bg-red-500/10 border-red-500/30'
      case 'HIGH': return 'text-orange-400 bg-orange-500/10 border-orange-500/30'
      case 'MEDIUM': return 'text-yellow-400 bg-yellow-500/10 border-yellow-500/30'
      case 'LOW': return 'text-green-400 bg-green-500/10 border-green-500/30'
      default: return 'text-gray-400 bg-gray-500/10 border-gray-500/30'
    }
  }

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'CRITICAL': return 'text-red-400'
      case 'HIGH': return 'text-orange-400'
      case 'MEDIUM': return 'text-yellow-400'
      case 'LOW': return 'text-blue-400'
      default: return 'text-gray-400'
    }
  }

  return (
    <div className="space-y-6">
      {/* Header with Risk Score */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-semibold text-white mb-2">Permission Management</h3>
          <p className="text-sm text-gray-400">Intelligent permission analysis and recommendations</p>
        </div>
        {analysis && (
          <div className="flex items-center gap-4">
            <div className="text-right">
              <div className="text-sm text-gray-400">Risk Score</div>
              <div className={`text-2xl font-bold ${analysis.riskScore >= 70 ? 'text-red-400' : analysis.riskScore >= 40 ? 'text-orange-400' : 'text-green-400'}`}>
                {analysis.riskScore}
              </div>
            </div>
            <div className="text-right">
              <div className="text-sm text-gray-400">Compliance</div>
              <div className={`text-2xl font-bold ${analysis.complianceScore >= 80 ? 'text-green-400' : analysis.complianceScore >= 60 ? 'text-yellow-400' : 'text-red-400'}`}>
                {analysis.complianceScore}%
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Warnings Banner */}
      {showWarnings && analysis && analysis.warnings.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-gradient-to-r from-orange-500/10 to-red-500/10 border border-orange-500/30 rounded-lg p-4"
        >
          <div className="flex items-start gap-3">
            <RiErrorWarningLine className="text-orange-400 text-xl mt-0.5" />
            <div className="flex-1">
              <h4 className="text-orange-400 font-semibold mb-2">Security Warnings</h4>
              <div className="space-y-2">
                {analysis.warnings.slice(0, 3).map((warning, idx) => (
                  <div key={idx} className="text-sm text-gray-300">
                    <span className={`font-medium ${getSeverityColor(warning.severity)}`}>
                      [{warning.severity}] {warning.type}:
                    </span>{' '}
                    {warning.message}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </motion.div>
      )}

      {/* Recommendations */}
      {showRecommendations && analysis && analysis.recommendations.length > 0 && (
        <div className="bg-white/5 border border-white/10 rounded-lg p-4">
          <div className="flex items-center gap-2 mb-4">
            <RiLightbulbLine className="text-yellow-400 text-xl" />
            <h4 className="text-white font-semibold">AI Recommendations</h4>
          </div>
          <div className="space-y-3">
            {analysis.recommendations.map((rec, idx) => (
              <PermissionRecommendationCard
                key={idx}
                recommendation={rec}
                onAdd={() => handleAddPermission(rec.permission)}
                onDismiss={() => {}}
              />
            ))}
          </div>
        </div>
      )}

      {/* Suggestions */}
      {analysis && analysis.suggestions.length > 0 && (
        <div className="bg-blue-500/10 border border-blue-500/30 rounded-lg p-4">
          <div className="flex items-center gap-2 mb-3">
            <RiInformationLine className="text-blue-400 text-xl" />
            <h4 className="text-blue-400 font-semibold">Best Practice Suggestions</h4>
          </div>
          <ul className="space-y-2">
            {analysis.suggestions.map((suggestion, idx) => (
              <li key={idx} className="text-sm text-gray-300 flex items-start gap-2">
                <RiCheckLine className="text-blue-400 mt-0.5 flex-shrink-0" />
                <span>{suggestion}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Current Permissions */}
      <div className="bg-white/5 border border-white/10 rounded-lg p-6">
        <div className="flex items-center justify-between mb-4">
          <h4 className="text-white font-semibold">Current Permissions</h4>
          {mode === 'edit' && (
            <button
              onClick={() => setShowBuilder(true)}
              className="px-4 py-2 bg-gradient-to-r from-blue-500 to-blue-600 text-white rounded-lg hover:from-blue-600 hover:to-blue-700 transition-all"
            >
              + Add Permission
            </button>
          )}
        </div>

        {permissions.length === 0 ? (
          <div className="text-center py-8 text-gray-400">
            <RiShieldUserLine className="text-4xl mx-auto mb-2 opacity-50" />
            <p>No permissions assigned</p>
          </div>
        ) : (
          <div className="space-y-3">
            {permissions.map((perm, idx) => (
              <PermissionCard
                key={idx}
                permission={perm}
                recommendation={analysis?.recommendations[idx]}
                onRemove={() => handleRemovePermission(idx)}
                mode={mode}
              />
            ))}
          </div>
        )}
      </div>

      {/* Approval Required */}
      {requireApproval && analysis?.requiresApproval && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="bg-gradient-to-r from-red-500/10 to-orange-500/10 border-2 border-red-500/50 rounded-lg p-6"
        >
          <div className="flex items-start gap-4">
            <RiLockLine className="text-red-400 text-2xl mt-1" />
            <div className="flex-1">
              <h4 className="text-red-400 font-semibold text-lg mb-2">Approval Required</h4>
              <p className="text-gray-300 mb-4">
                These permission changes require approval due to security implications.
              </p>
              <button
                onClick={handleRequestApproval}
                className="px-6 py-2 bg-red-500 hover:bg-red-600 text-white rounded-lg transition-all"
              >
                Request Approval
              </button>
            </div>
          </div>
        </motion.div>
      )}

      {/* Conflicts */}
      {analysis && analysis.conflicts.length > 0 && (
        <div className="bg-yellow-500/10 border border-yellow-500/30 rounded-lg p-4">
          <div className="flex items-center gap-2 mb-3">
            <RiAlertLine className="text-yellow-400 text-xl" />
            <h4 className="text-yellow-400 font-semibold">Permission Conflicts Detected</h4>
          </div>
          <div className="space-y-2">
            {analysis.conflicts.map((conflict, idx) => (
              <div key={idx} className="text-sm text-gray-300">
                <span className="font-medium text-yellow-400">{conflict.type}:</span> {conflict.description}
                <div className="text-xs text-gray-400 mt-1">{conflict.resolution}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Loading State */}
      {isAnalyzing && (
        <div className="text-center py-8">
          <div className="inline-block w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-gray-400 mt-2">Analyzing permissions...</p>
        </div>
      )}
    </div>
  )
}

// Permission Card Component
function PermissionCard({
  permission,
  recommendation,
  onRemove,
  mode,
}: {
  permission: HierarchicalPermission
  recommendation?: PermissionRecommendation
  onRemove: () => void
  mode: string
}) {
  return (
    <motion.div
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      className="bg-white/5 border border-white/10 rounded-lg p-4 hover:border-white/20 transition-all"
    >
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-2">
            <RiShieldUserLine className="text-blue-400" />
            <span className="font-semibold text-white">
              {permission.moduleId || 'General Access'}
            </span>
            {recommendation && (
              <span className={`px-2 py-0.5 rounded text-xs font-medium ${getRiskColor(recommendation.riskLevel)}`}>
                {recommendation.riskLevel}
              </span>
            )}
          </div>
          {permission.featureId && (
            <div className="text-sm text-gray-400 mb-1">
              Feature: {permission.featureId}
            </div>
          )}
          <div className="flex flex-wrap gap-2 mt-2">
            {permission.actions.map((action, idx) => (
              <span
                key={idx}
                className="px-2 py-1 bg-blue-500/20 text-blue-300 rounded text-xs"
              >
                {action}
              </span>
            ))}
          </div>
          <div className="text-xs text-gray-500 mt-2">
            Scope: {permission.scope}
          </div>
        </div>
        {mode === 'edit' && (
          <button
            onClick={onRemove}
            className="text-red-400 hover:text-red-300 transition-colors"
          >
            <RiCloseLine className="text-xl" />
          </button>
        )}
      </div>
    </motion.div>
  )
}

// Permission Recommendation Card
