          <div className="flex items-center gap-1 mb-2 text-green-400 text-sm font-medium">
            <RiCheckboxCircleLine />
            Pros
          </div>
          <ul className="space-y-1">
            {recommendation.pros.slice(0, 2).map((pro, idx) => (
              <li key={idx} className="text-xs text-gray-300 flex items-start gap-1">
                <RiCheckLine className="text-green-400 mt-0.5 flex-shrink-0" />
                {pro}
              </li>
            ))}
          </ul>
        </div>
        <div>
          <div className="flex items-center gap-1 mb-2 text-red-400 text-sm font-medium">
            <RiCloseCircleLine />
            Cons
          </div>
          <ul className="space-y-1">
            {recommendation.cons.slice(0, 2).map((con, idx) => (
              <li key={idx} className="text-xs text-gray-300 flex items-start gap-1">
                <RiCloseLine className="text-red-400 mt-0.5 flex-shrink-0" />
                {con}
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Actions */}
      <div className="flex items-center gap-2">
        <button
          onClick={onAdd}
          className="px-4 py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-lg text-sm transition-all"
        >
          Add Permission
        </button>
        {recommendation.requiresApproval && (
          <span className="text-xs text-orange-400 flex items-center gap-1">
            <RiLockLine />
            Requires Approval
          </span>
        )}
      </div>
    </motion.div>
  )
}

function getRiskColor(riskLevel: string): string {
  switch (riskLevel) {
    case 'CRITICAL': return 'text-red-400 bg-red-500/10 border-red-500/30'
    case 'HIGH': return 'text-orange-400 bg-orange-500/10 border-orange-500/30'
    case 'MEDIUM': return 'text-yellow-400 bg-yellow-500/10 border-yellow-500/30'
    case 'LOW': return 'text-green-400 bg-green-500/10 border-green-500/30'
    default: return 'text-gray-400 bg-gray-500/10 border-gray-500/30'
  }
}

function getSeverityColor(severity: string): string {
  switch (severity) {
    case 'CRITICAL': return 'text-red-400'
    case 'HIGH': return 'text-orange-400'
    case 'MEDIUM': return 'text-yellow-400'
    case 'LOW': return 'text-blue-400'
    default: return 'text-gray-400'
  }
}

/**
 * ✅ PERMISSION APPROVAL WORKFLOW UI
 * 
 * Beautiful approval interface:
 * - View pending approvals
 * - Approve/reject requests
 * - Approval chain visualization
 * - Comments and notes
 * - History tracking
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { useAuth } from '@/contexts/AuthContext'
import { permissionApprovalWorkflow } from '@/lib/services/permissions/permissionApprovalWorkflow'
import type { ApprovalRequest } from '@/lib/services/permissions/permissionApprovalWorkflow'

export default function PermissionApprovalWorkflowComponent() {
  const { user: currentUser } = useAuth()
  const [requests, setRequests] = useState<ApprovalRequest[]>([])
  const [pendingRequests, setPendingRequests] = useState<ApprovalRequest[]>([])
  const [selectedRequest, setSelectedRequest] = useState<ApprovalRequest | null>(null)
  const [loading, setLoading] = useState(true)
  const [comments, setComments] = useState('')

  useEffect(() => {
    loadRequests()
  }, [currentUser])

  const loadRequests = async () => {
    if (!currentUser) return

    setLoading(true)
    try {
      const [all, pending] = await Promise.all([
        permissionApprovalWorkflow.getAllRequests(),
        permissionApprovalWorkflow.getPendingRequestsForApprover(currentUser),
      ])
      setRequests(all)
      setPendingRequests(pending)
    } catch (error) {
      console.error('Failed to load requests:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleApprove = async (requestId: string) => {
    if (!currentUser) return

    try {
      await permissionApprovalWorkflow.approveRequest(requestId, currentUser, comments)
      setComments('')
      await loadRequests()
      if (selectedRequest?.id === requestId) {
        const updated = await permissionApprovalWorkflow.getAllRequests()
        const updatedRequest = updated.find(r => r.id === requestId)
        if (updatedRequest) setSelectedRequest(updatedRequest)
      }
    } catch (error) {
      console.error('Failed to approve:', error)
    }
  }

  const handleReject = async (requestId: string) => {
    if (!currentUser) return

    try {
      await permissionApprovalWorkflow.rejectRequest(requestId, currentUser, comments)
      setComments('')
      await loadRequests()
    } catch (error) {
      console.error('Failed to reject:', error)
    }
  }

  const getStatusColor = (status: string) => {
    const colors = {
      PENDING: 'bg-yellow-500/20 text-yellow-400',
      APPROVED: 'bg-green-500/20 text-green-400',
      REJECTED: 'bg-red-500/20 text-red-400',
      ESCALATED: 'bg-orange-500/20 text-orange-400',
      EXPIRED: 'bg-gray-500/20 text-gray-400',
    }
    return colors[status as keyof typeof colors] || colors.PENDING
  }

  const getUrgencyColor = (urgency: string) => {
    const colors = {
      LOW: 'text-gray-400',
      MEDIUM: 'text-blue-400',
      HIGH: 'text-orange-400',
      CRITICAL: 'text-red-400',
    }
    return colors[urgency as keyof typeof colors] || colors.MEDIUM
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white flex items-center justify-center">
        <div className="text-center">
          <i className="ri-loader-4-line text-6xl animate-spin text-cyan-400 mb-4"></i>
          <p className="text-gray-400">Loading approvals...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold mb-2 flex items-center gap-3">
            <i className="ri-checkbox-circle-line text-cyan-400"></i>
            Permission Approval Workflow
          </h1>
          <p className="text-gray-400">
            Review and approve permission change requests
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left: Pending Requests */}
          <div className="lg:col-span-1">
            <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-bold">Pending Approvals</h2>
                <span className="px-3 py-1 bg-yellow-500/20 text-yellow-400 rounded-full text-sm">
                  {pendingRequests.length}
                </span>
              </div>
              <div className="space-y-2 max-h-[600px] overflow-y-auto">
                {pendingRequests.length === 0 ? (
                  <div className="text-center py-8 text-gray-400">
                    <i className="ri-inbox-line text-4xl mb-2"></i>
                    <p>No pending approvals</p>
                  </div>
                ) : (
                  pendingRequests.map(request => (
                    <motion.div
                      key={request.id}
                      onClick={() => setSelectedRequest(request)}
                      className={`p-4 rounded-lg border cursor-pointer transition-all ${
                        selectedRequest?.id === request.id
                          ? 'bg-cyan-500/20 border-cyan-400'
                          : 'bg-white/5 border-white/10 hover:bg-white/10'
                      }`}
                      whileHover={{ scale: 1.02 }}
                      whileTap={{ scale: 0.98 }}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <div className="font-semibold text-sm">
                          {request.targetUser.name}
                        </div>
                        <span className={`px-2 py-1 rounded text-xs ${getUrgencyColor(request.urgency)}`}>
                          {request.urgency}
                        </span>
                      </div>
                      <div className="text-xs text-gray-400 mb-2">
                        {request.requestType} • {request.permissions.length} permission(s)
                      </div>
                      <div className="text-xs text-gray-500">
                        {new Date(request.createdAt).toLocaleDateString()}
                      </div>
                    </motion.div>
                  ))
                )}
              </div>
            </div>
          </div>

          {/* Middle: Request Details */}
          <div className="lg:col-span-1">
            {selectedRequest ? (
              <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
                <h2 className="text-xl font-bold mb-4">Request Details</h2>
                <div className="space-y-4">
                  <div>
                    <div className="text-sm text-gray-400 mb-1">Request Type</div>
                    <div className="font-semibold">{selectedRequest.requestType}</div>
                  </div>
                  <div>
                    <div className="text-sm text-gray-400 mb-1">Target User</div>
                    <div className="font-semibold">{selectedRequest.targetUser.name}</div>
                    <div className="text-xs text-gray-400">{selectedRequest.targetUser.email}</div>
                  </div>
                  <div>
                    <div className="text-sm text-gray-400 mb-1">Requested By</div>
                    <div className="font-semibold">{selectedRequest.requestedBy.name}</div>
                    <div className="text-xs text-gray-400">{selectedRequest.requestedBy.email}</div>
                  </div>
                  <div>
                    <div className="text-sm text-gray-400 mb-1">Reason</div>
                    <div className="text-sm">{selectedRequest.reason}</div>
                  </div>
                  <div>
                    <div className="text-sm text-gray-400 mb-2">Permissions</div>
                    <div className="space-y-1 max-h-32 overflow-y-auto">
                      {selectedRequest.permissions.map((perm, idx) => (
                        <div key={idx} className="p-2 bg-white/5 rounded text-xs font-mono">
                          {perm.moduleId}
                          {perm.featureId && ` → ${perm.featureId.split('.')[1]}`}
                          {perm.tabId && ` → ${perm.tabId.split('.').pop()}`}
                        </div>
                      ))}
                    </div>
                  </div>
                  <div>
                    <div className="text-sm text-gray-400 mb-2">Approval Chain</div>
                    <div className="space-y-2">
                      {selectedRequest.approvalChain.map((step, idx) => (
                        <div
                          key={idx}
                          className={`p-3 rounded-lg border ${
                            step.status === 'APPROVED'
                              ? 'bg-green-500/20 border-green-500/30'
                              : step.status === 'REJECTED'
                              ? 'bg-red-500/20 border-red-500/30'
                              : idx === selectedRequest.currentStep
                              ? 'bg-cyan-500/20 border-cyan-500/30'
                              : 'bg-white/5 border-white/10'
                          }`}
                        >
                          <div className="flex items-center justify-between mb-1">
                            <div className="text-sm font-semibold">
                              Step {step.stepNumber}: {step.approverRole}
                            </div>
                            <span className={`text-xs px-2 py-1 rounded ${
                              step.status === 'APPROVED'
                                ? 'bg-green-500/20 text-green-400'
                                : step.status === 'REJECTED'
                                ? 'bg-red-500/20 text-red-400'
                                : 'bg-yellow-500/20 text-yellow-400'
                            }`}>
                              {step.status}
                            </span>
                          </div>
                          {step.approvedBy && (
                            <div className="text-xs text-gray-400">
                              Approved by {step.approvedBy.name}
                            </div>
                          )}
                          {step.comments && (
                            <div className="text-xs text-gray-300 mt-1">{step.comments}</div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-12 text-center">
                <i className="ri-file-list-line text-6xl text-gray-600 mb-4"></i>
                <p className="text-gray-400">Select a request to view details</p>
              </div>
            )}
          </div>

          {/* Right: Actions */}
          <div className="lg:col-span-1">
            {selectedRequest && selectedRequest.status === 'PENDING' && (
              <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
                <h2 className="text-xl font-bold mb-4">Actions</h2>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm text-gray-400 mb-2">Comments</label>
                    <textarea
                      value={comments}
                      onChange={(e) => setComments(e.target.value)}
                      className="w-full px-4 py-2 bg-white/10 border border-white/20 rounded-lg resize-none"
                      rows={4}
                      placeholder="Add comments..."
                    />
                  </div>
                  <div className="flex gap-3">
                    <button
                      onClick={() => handleApprove(selectedRequest.id)}
                      className="flex-1 px-4 py-3 bg-green-500/20 text-green-400 rounded-lg hover:bg-green-500/30 font-semibold flex items-center justify-center gap-2"
                    >
                      <i className="ri-check-line"></i>
                      Approve
                    </button>
                    <button
                      onClick={() => handleReject(selectedRequest.id)}
                      className="flex-1 px-4 py-3 bg-red-500/20 text-red-400 rounded-lg hover:bg-red-500/30 font-semibold flex items-center justify-center gap-2"
                    >
                      <i className="ri-close-line"></i>
                      Reject
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* All Requests */}
            <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6 mt-6">
              <h2 className="text-xl font-bold mb-4">All Requests</h2>
              <div className="space-y-2 max-h-[400px] overflow-y-auto">
                {requests.slice(0, 10).map(request => (
                  <div
                    key={request.id}
                    onClick={() => setSelectedRequest(request)}
                    className={`p-3 rounded-lg border cursor-pointer transition-all ${
                      selectedRequest?.id === request.id
                        ? 'bg-cyan-500/20 border-cyan-400'
                        : 'bg-white/5 border-white/10 hover:bg-white/10'
                    }`}
                  >
                    <div className="flex items-center justify-between mb-1">
                      <div className="text-sm font-semibold">{request.targetUser.name}</div>
                      <span className={`px-2 py-1 rounded text-xs ${getStatusColor(request.status)}`}>
                        {request.status}
                      </span>
                    </div>
                    <div className="text-xs text-gray-400">
                      {request.requestType} • {new Date(request.createdAt).toLocaleDateString()}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * 📜 PERMISSION AUDIT TRAIL COMPONENT
 * 
 * Complete audit trail viewer:
 * - View all permission changes
 * - Filter by user, action, date range
 * - Rollback capability
 * - Export to CSV
 * - Real-time updates
 */

'use client'

import { useState, useEffect, useMemo } from 'react'
import { motion } from 'framer-motion'
import { useAuth } from '@/contexts/AuthContext'
import { permissionAuditTrail } from '@/lib/services/permissions/permissionAuditTrail'
import type { PermissionAuditLog, AuditQuery } from '@/lib/services/permissions/permissionAuditTrail'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer } from 'recharts'

export default function PermissionAuditTrailComponent() {
  const { user: currentUser } = useAuth()
  const [logs, setLogs] = useState<PermissionAuditLog[]>([])
  const [loading, setLoading] = useState(true)
  const [summary, setSummary] = useState<{
    totalChanges: number
    changesByAction: Record<string, number>
    changesByUser: Record<string, number>
    recentChanges: PermissionAuditLog[]
    topChangers: Array<{ userId: string; userName: string; count: number }>
  } | null>(null)

  // Filters
  const [filters, setFilters] = useState<AuditQuery>({
    limit: 100,
    offset: 0,
  })
  const [selectedAction, setSelectedAction] = useState<string>('all')
  const [dateRange, setDateRange] = useState<'7d' | '30d' | '90d' | 'all'>('30d')

  useEffect(() => {
    loadData()
  }, [filters, dateRange, selectedAction])

  const loadData = async () => {
    setLoading(true)
    try {
      // Apply date range
      const query: AuditQuery = { ...filters }
      if (dateRange !== 'all') {
        const days = dateRange === '7d' ? 7 : dateRange === '30d' ? 30 : 90
        query.startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000)
      }
      if (selectedAction !== 'all') {
        query.action = selectedAction as PermissionAuditLog['action']
      }

      const [logsData, summaryData] = await Promise.all([
        permissionAuditTrail.getAuditLogs(query),
        permissionAuditTrail.getAuditSummary(query),
      ])

      setLogs(logsData)
      setSummary(summaryData)
    } catch (error) {
      console.error('Failed to load audit logs:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleRollback = async (logId: string) => {
    if (!currentUser || !confirm('Are you sure you want to rollback this permission change?')) {
      return
    }

    try {
      await permissionAuditTrail.rollbackPermissionChange(logId, currentUser)
      await loadData()
      alert('Permission change rolled back successfully!')
    } catch (error) {
      console.error('Failed to rollback:', error)
      alert('Failed to rollback permission change')
    }
  }

  const handleExport = async () => {
    try {
      const csv = await permissionAuditTrail.exportAuditLogs(filters)
      const blob = new Blob([csv], { type: 'text/csv' })
      const url = window.URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `permission-audit-${new Date().toISOString().split('T')[0]}.csv`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      window.URL.revokeObjectURL(url)
    } catch (error) {
      console.error('Failed to export:', error)
      alert('Failed to export audit logs')
    }
  }

  // Chart data
  const actionChartData = useMemo(() => {
    if (!summary) return []
    return Object.entries(summary.changesByAction).map(([action, count]) => ({
      action,
      count,
    }))
  }, [summary])

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899']

  const actionColors: Record<string, string> = {
    CREATE: '#10b981',
    UPDATE: '#3b82f6',
    DELETE: '#ef4444',
    GRANT: '#10b981',
    REVOKE: '#f59e0b',
    MODIFY: '#8b5cf6',
    ROLLBACK: '#ec4899',
  }

  const formatDate = (date: Date) => {
    return new Intl.DateTimeFormat('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    }).format(date)
  }

  const formatPermission = (log: PermissionAuditLog) => {
    const parts = [log.permission.moduleId]
    if (log.permission.featureId) parts.push(log.permission.featureId)
    if (log.permission.tabId) parts.push(log.permission.tabId)
    return parts.join(' → ')
  }

  if (loading && !summary) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-400">Loading audit logs...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-white mb-2">Permission Audit Trail</h1>
          <p className="text-gray-400">Complete history of all permission changes</p>
        </div>
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={handleExport}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg flex items-center gap-2"
        >
          <i className="ri-download-2-line"></i>
          Export CSV
        </motion.button>
      </div>

      {/* Summary Cards */}
      {summary && (
        <div className="grid md:grid-cols-4 gap-4">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="p-6 rounded-xl bg-gradient-to-br from-blue-500/10 to-blue-600/10 border border-blue-500/30"
          >
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm text-gray-400">Total Changes</span>
              <i className="ri-file-list-line text-blue-400"></i>
            </div>
            <div className="text-3xl font-bold text-white">{summary.totalChanges.toLocaleString()}</div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="p-6 rounded-xl bg-gradient-to-br from-green-500/10 to-green-600/10 border border-green-500/30"
          >
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm text-gray-400">Unique Users</span>
              <i className="ri-user-line text-green-400"></i>
            </div>
            <div className="text-3xl font-bold text-white">{Object.keys(summary.changesByUser).length}</div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="p-6 rounded-xl bg-gradient-to-br from-purple-500/10 to-purple-600/10 border border-purple-500/30"
          >
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm text-gray-400">Action Types</span>
              <i className="ri-settings-3-line text-purple-400"></i>
            </div>
            <div className="text-3xl font-bold text-white">{Object.keys(summary.changesByAction).length}</div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="p-6 rounded-xl bg-gradient-to-br from-orange-500/10 to-orange-600/10 border border-orange-500/30"
          >
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm text-gray-400">Top Changers</span>
              <i className="ri-star-line text-orange-400"></i>
            </div>
            <div className="text-3xl font-bold text-white">{summary.topChangers.length}</div>
          </motion.div>
        </div>
      )}

      {/* Charts */}
      {summary && (
        <div className="grid md:grid-cols-2 gap-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="p-6 rounded-xl bg-gray-800/50 border border-gray-700"
          >
            <h3 className="text-lg font-semibold text-white mb-4">Changes by Action</h3>
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={actionChartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
                <XAxis dataKey="action" stroke="#9ca3af" />
                <YAxis stroke="#9ca3af" />
                <RechartsTooltip
                  contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                />
                <Bar dataKey="count" fill="#3b82f6" radius={[8, 8, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="p-6 rounded-xl bg-gray-800/50 border border-gray-700"
          >
            <h3 className="text-lg font-semibold text-white mb-4">Action Distribution</h3>
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={actionChartData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={({ action, percent }) => `${action}: ${(percent * 100).toFixed(0)}%`}
                  outerRadius={100}
                  fill="#8884d8"
                  dataKey="count"
                >
                  {actionChartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={actionColors[entry.action] || COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <RechartsTooltip
                  contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                />
              </PieChart>
            </ResponsiveContainer>
          </motion.div>
        </div>
      )}

      {/* Filters */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="p-6 rounded-xl bg-gray-800/50 border border-gray-700"
      >
        <h3 className="text-lg font-semibold text-white mb-4">Filters</h3>
        <div className="grid md:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm text-gray-400 mb-2">Date Range</label>
            <select
              value={dateRange}
              onChange={(e) => setDateRange(e.target.value as any)}
              className="w-full px-4 py-2 bg-gray-700 border border-gray-600 rounded-lg text-white"
            >
              <option value="7d">Last 7 days</option>
              <option value="30d">Last 30 days</option>
              <option value="90d">Last 90 days</option>
              <option value="all">All time</option>
            </select>
          </div>
          <div>
            <label className="block text-sm text-gray-400 mb-2">Action Type</label>
            <select
              value={selectedAction}
              onChange={(e) => setSelectedAction(e.target.value)}
              className="w-full px-4 py-2 bg-gray-700 border border-gray-600 rounded-lg text-white"
            >
              <option value="all">All Actions</option>
              <option value="CREATE">Create</option>
              <option value="UPDATE">Update</option>
              <option value="DELETE">Delete</option>
              <option value="GRANT">Grant</option>
              <option value="REVOKE">Revoke</option>
              <option value="MODIFY">Modify</option>
              <option value="ROLLBACK">Rollback</option>
            </select>
          </div>
          <div>
            <label className="block text-sm text-gray-400 mb-2">Results per page</label>
            <select
              value={filters.limit || 100}
              onChange={(e) => setFilters({ ...filters, limit: parseInt(e.target.value), offset: 0 })}
              className="w-full px-4 py-2 bg-gray-700 border border-gray-600 rounded-lg text-white"
            >
              <option value="50">50</option>
              <option value="100">100</option>
              <option value="200">200</option>
              <option value="500">500</option>
            </select>
          </div>
        </div>
      </motion.div>

      {/* Audit Logs Table */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="p-6 rounded-xl bg-gray-800/50 border border-gray-700"
      >
        <h3 className="text-lg font-semibold text-white mb-4">Audit Logs</h3>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-700">
                <th className="text-left py-3 px-4 text-sm font-semibold text-gray-400">Timestamp</th>
                <th className="text-left py-3 px-4 text-sm font-semibold text-gray-400">Action</th>
                <th className="text-left py-3 px-4 text-sm font-semibold text-gray-400">Target User</th>
                <th className="text-left py-3 px-4 text-sm font-semibold text-gray-400">Permission</th>
                <th className="text-left py-3 px-4 text-sm font-semibold text-gray-400">Changed By</th>
                <th className="text-left py-3 px-4 text-sm font-semibold text-gray-400">Reason</th>
                <th className="text-left py-3 px-4 text-sm font-semibold text-gray-400">Actions</th>
              </tr>
            </thead>
            <tbody>
              {logs.length === 0 ? (
                <tr>
                  <td colSpan={7} className="text-center py-8 text-gray-400">
                    No audit logs found
                  </td>
                </tr>
              ) : (
                logs.map((log) => (
                  <motion.tr
                    key={log.id}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="border-b border-gray-700/50 hover:bg-gray-700/30 transition-colors"
                  >
                    <td className="py-3 px-4 text-sm text-gray-300">{formatDate(log.timestamp)}</td>
                    <td className="py-3 px-4">
                      <span
                        className="px-2 py-1 rounded text-xs font-semibold"
                        style={{
                          backgroundColor: `${actionColors[log.action] || '#6b7280'}20`,
                          color: actionColors[log.action] || '#9ca3af',
                        }}
                      >
                        {log.action}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-sm text-gray-300">{log.userEmail}</td>
                    <td className="py-3 px-4 text-sm text-gray-300">{formatPermission(log)}</td>
                    <td className="py-3 px-4 text-sm text-gray-300">{log.changedByEmail}</td>
                    <td className="py-3 px-4 text-sm text-gray-400">{log.reason || '-'}</td>
                    <td className="py-3 px-4">
                      {log.previousPermission && (
                        <motion.button
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                          onClick={() => handleRollback(log.id)}
                          className="px-3 py-1 bg-orange-600 hover:bg-orange-700 text-white rounded text-xs"
                        >
                          <i className="ri-arrow-go-back-line mr-1"></i>
                          Rollback
                        </motion.button>
                      )}
                    </td>
                  </motion.tr>
                ))
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        {logs.length > 0 && (
          <div className="flex items-center justify-between mt-4">
            <p className="text-sm text-gray-400">
              Showing {filters.offset || 0 + 1} to {Math.min((filters.offset || 0) + (filters.limit || 100), logs.length)} of {logs.length} logs
            </p>
            <div className="flex gap-2">
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => setFilters({ ...filters, offset: Math.max(0, (filters.offset || 0) - (filters.limit || 100)) })}
                disabled={(filters.offset || 0) === 0}
                className="px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Previous
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => setFilters({ ...filters, offset: (filters.offset || 0) + (filters.limit || 100) })}
                disabled={logs.length < (filters.limit || 100)}
                className="px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Next
              </motion.button>
            </div>
          </div>
        )}
      </motion.div>
    </div>
  )
}

/**
 * 🌳 PERMISSION INHERITANCE VISUALIZER UI
 * 
 * Beautiful tree visualization:
 * - Interactive tree view
 * - Inheritance flow
 * - Conflict highlighting
 * - Expand/collapse
 * - Search and filter
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { useAuth } from '@/contexts/AuthContext'
import { userService } from '@/lib/services/user'
import { permissionInheritanceVisualizer } from '@/lib/services/permissions/permissionInheritanceVisualizer'
import type { User } from '@/types/user'
import type { InheritanceTree, InheritanceNode } from '@/lib/services/permissions/permissionInheritanceVisualizer'

export default function PermissionInheritanceVisualizerComponent() {
  const { user: currentUser } = useAuth()
  const [users, setUsers] = useState<User[]>([])
  const [selectedUser, setSelectedUser] = useState<User | null>(null)
  const [tree, setTree] = useState<InheritanceTree | null>(null)
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set(['root']))
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    loadUsers()
  }, [])

  useEffect(() => {
    if (selectedUser) {
      loadTree()
    }
  }, [selectedUser])

  const loadUsers = async () => {
    try {
      const data = await userService.getUsers({})
      setUsers(data)
    } catch (error) {
      console.error('Failed to load users:', error)
    }
  }

  const loadTree = async () => {
    if (!selectedUser) return

    setLoading(true)
    try {
      const result = await permissionInheritanceVisualizer.buildInheritanceTree(selectedUser)
      setTree(result)
    } catch (error) {
      console.error('Failed to build tree:', error)
    } finally {
      setLoading(false)
    }
  }

  const toggleNode = (nodeId: string) => {
    const newExpanded = new Set(expandedNodes)
    if (newExpanded.has(nodeId)) {
      newExpanded.delete(nodeId)
    } else {
      newExpanded.add(nodeId)
    }
    setExpandedNodes(newExpanded)
  }

  const getAccessColor = (access: string) => {
    const colors = {
      full: 'text-green-400',
      partial: 'text-yellow-400',
      read_only: 'text-blue-400',
      none: 'text-gray-400',
    }
    return colors[access as keyof typeof colors] || colors.none
  }

  const getSourceColor = (source: string) => {
    const colors = {
      EXPLICIT: 'bg-cyan-500/20 text-cyan-400',
      INHERITED: 'bg-gray-500/20 text-gray-400',
      OVERRIDDEN: 'bg-orange-500/20 text-orange-400',
    }
    return colors[source as keyof typeof colors] || colors.INHERITED
  }

  const renderNode = (node: InheritanceNode, level: number = 0): JSX.Element => {
    const isExpanded = expandedNodes.has(node.id)
    const hasChildren = node.children.length > 0

    return (
      <div key={node.id} className="mb-2">
        <div
          className={`flex items-center gap-2 p-3 rounded-lg border cursor-pointer transition-all ${
            node.source === 'EXPLICIT'
              ? 'bg-cyan-500/10 border-cyan-500/20'
              : 'bg-white/5 border-white/10'
          }`}
          style={{ marginLeft: `${level * 24}px` }}
          onClick={() => hasChildren && toggleNode(node.id)}
        >
          {hasChildren && (
            <i className={`ri-arrow-${isExpanded ? 'down' : 'right'}-s-line text-gray-400`}></i>
          )}
          {!hasChildren && <div className="w-4"></div>}
          
          <i className={`ri-${node.type === 'MODULE' ? 'apps' : node.type === 'FEATURE' ? 'function' : 'file'}-line text-cyan-400`}></i>
          
          <div className="flex-1">
            <div className="flex items-center gap-2">
              <span className="font-semibold">{node.name}</span>
              <span className={`text-xs px-2 py-1 rounded ${getSourceColor(node.source)}`}>
                {node.source}
              </span>
              <span className={`text-sm font-medium ${getAccessColor(node.access)}`}>
                {node.access}
              </span>
            </div>
          </div>
        </div>

        {isExpanded && hasChildren && (
          <div className="mt-1">
            {node.children.map(child => renderNode(child, level + 1))}
          </div>
        )}
      </div>
    )
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white flex items-center justify-center">
        <div className="text-center">
          <i className="ri-loader-4-line text-6xl animate-spin text-cyan-400 mb-4"></i>
          <p className="text-gray-400">Building inheritance tree...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-4xl font-bold mb-2 flex items-center gap-3">
            <i className="ri-node-tree text-cyan-400"></i>
            Permission Inheritance Visualizer
          </h1>
          <p className="text-gray-400">
            Visualize permission inheritance hierarchy
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Left: User Selection */}
          <div className="lg:col-span-1">
            <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
              <h2 className="text-xl font-bold mb-4">Select User</h2>
              <select
                value={selectedUser?.id || ''}
                onChange={(e) => {
                  const user = users.find(u => u.id === e.target.value)
                  setSelectedUser(user || null)
                }}
                className="w-full px-4 py-2 bg-white/10 border border-white/20 rounded-lg mb-4"
              >
                <option value="">Select a user...</option>
                {users.map(user => (
                  <option key={user.id} value={user.id}>
                    {user.name} ({user.role})
                  </option>
                ))}
              </select>

              {selectedUser && (
                <div className="p-4 bg-white/5 rounded-lg">
                  <div className="text-sm text-gray-400 mb-1">Total Permissions</div>
                  <div className="text-lg font-semibold">
                    {(selectedUser.hierarchicalPermissions || []).length}
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Right: Tree Visualization */}
          <div className="lg:col-span-3">
            {tree ? (
              <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-xl font-bold">Inheritance Tree</h2>
                  {tree.conflicts.length > 0 && (
                    <span className="px-3 py-1 bg-red-500/20 text-red-400 rounded-full text-sm">
                      {tree.conflicts.length} conflict(s)
                    </span>
                  )}
                </div>

                <div className="space-y-1 max-h-[700px] overflow-y-auto">
                  {tree.root.children.map(module => renderNode(module))}
                </div>

                {/* Conflicts */}
                {tree.conflicts.length > 0 && (
                  <div className="mt-6 pt-6 border-t border-white/10">
                    <h3 className="text-lg font-bold mb-4 text-red-400">Conflicts Detected</h3>
                    <div className="space-y-2">
                      {tree.conflicts.map((conflict, idx) => (
                        <div
                          key={idx}
                          className="p-4 bg-red-500/10 border border-red-500/20 rounded-lg"
                        >
                          <div className="font-semibold mb-1">{conflict.conflictType}</div>
                          <div className="text-sm text-gray-300">{conflict.description}</div>
                          <div className="text-xs text-gray-400 mt-1">
                            Node: {conflict.node.name} ({conflict.node.type})
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-12 text-center">
                <i className="ri-node-tree text-6xl text-gray-600 mb-4"></i>
                <p className="text-gray-400">Select a user to visualize inheritance tree</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * 🔥 PERMISSION USAGE HEATMAP VISUALIZATION
 * 
 * Beautiful heatmap showing:
 * - Time-based usage patterns
 * - Peak hours/days
 * - Usage intensity
 * - Success rates
 * - Interactive exploration
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { permissionUsageHeatmap } from '@/lib/services/permissions/permissionUsageHeatmap'
import type { HeatmapData, UsageAnalytics, UsagePattern } from '@/lib/services/permissions/permissionUsageHeatmap'

export default function PermissionUsageHeatmapComponent() {
  const [analytics, setAnalytics] = useState<UsageAnalytics | null>(null)
  const [loading, setLoading] = useState(true)
  const [timeRange, setTimeRange] = useState<'7d' | '30d' | '90d' | 'all'>('30d')
  const [selectedCell, setSelectedCell] = useState<HeatmapData | null>(null)

  useEffect(() => {
    loadAnalytics()
  }, [timeRange])

  const loadAnalytics = async () => {
    setLoading(true)
    try {
      const endDate = new Date()
      const startDate = new Date()
      
      switch (timeRange) {
        case '7d':
          startDate.setDate(endDate.getDate() - 7)
          break
        case '30d':
          startDate.setDate(endDate.getDate() - 30)
          break
        case '90d':
          startDate.setDate(endDate.getDate() - 90)
          break
        default:
          startDate.setFullYear(2020) // All time
      }

      const data = await permissionUsageHeatmap.getAnalytics({
        start: startDate,
        end: endDate,
      })
      setAnalytics(data)
    } catch (error) {
      console.error('Failed to load analytics:', error)
    } finally {
      setLoading(false)
    }
  }

  const getIntensityColor = (count: number, maxCount: number) => {
    if (count === 0) return 'bg-gray-900'
    const intensity = count / maxCount
    if (intensity > 0.8) return 'bg-red-500'
    if (intensity > 0.6) return 'bg-orange-500'
    if (intensity > 0.4) return 'bg-yellow-500'
    if (intensity > 0.2) return 'bg-green-500'
    return 'bg-blue-500'
  }

  const getMaxCount = (heatmap: HeatmapData[]) => {
    return Math.max(...heatmap.map(d => d.count), 1)
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white flex items-center justify-center">
        <div className="text-center">
          <i className="ri-loader-4-line text-6xl animate-spin text-cyan-400 mb-4"></i>
          <p className="text-gray-400">Loading heatmap...</p>
        </div>
      </div>
    )
  }

  if (!analytics) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white flex items-center justify-center">
        <div className="text-center">
          <i className="ri-fire-line text-6xl text-gray-600 mb-4"></i>
          <p className="text-gray-400">No usage data available</p>
        </div>
      </div>
    )
  }

  const maxCount = getMaxCount(analytics.heatmap)
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 text-white p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-4xl font-bold mb-2 flex items-center gap-3">
                <i className="ri-fire-line text-cyan-400"></i>
                Permission Usage Heatmap
              </h1>
              <p className="text-gray-400">Visualize permission usage patterns over time</p>
            </div>
            <select
              value={timeRange}
              onChange={(e) => setTimeRange(e.target.value as any)}
              className="px-4 py-2 bg-white/10 border border-white/20 rounded-lg"
            >
              <option value="7d">Last 7 days</option>
              <option value="30d">Last 30 days</option>
              <option value="90d">Last 90 days</option>
              <option value="all">All time</option>
            </select>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
            <div className="text-3xl font-bold text-cyan-400 mb-1">
              {analytics.totalAccesses.toLocaleString()}
            </div>
            <div className="text-sm text-gray-400">Total Accesses</div>
          </div>
          <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
            <div className="text-3xl font-bold text-blue-400 mb-1">
              {analytics.uniqueUsers}
            </div>
            <div className="text-sm text-gray-400">Unique Users</div>
          </div>
          <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
            <div className="text-3xl font-bold text-green-400 mb-1">
              {analytics.patterns.length}
            </div>
            <div className="text-sm text-gray-400">Usage Patterns</div>
          </div>
          <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
            <div className="text-3xl font-bold text-yellow-400 mb-1">
              {analytics.insights.length}
            </div>
            <div className="text-sm text-gray-400">Insights</div>
          </div>
        </div>

        {/* Heatmap */}
        <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6 mb-8">
          <h2 className="text-xl font-bold mb-4">Usage Heatmap</h2>
          <div className="overflow-x-auto">
            <div className="inline-block min-w-full">
              {/* Hour labels */}
              <div className="flex mb-2">
                <div className="w-16"></div>
                {Array.from({ length: 24 }, (_, i) => (
                  <div key={i} className="flex-1 text-center text-xs text-gray-400">
                    {i}
                  </div>
                ))}
              </div>
              {/* Heatmap grid */}
              {Array.from({ length: 7 }, (_, day) => (
                <div key={day} className="flex items-center mb-1">
                  <div className="w-16 text-sm text-gray-400">{dayNames[day]}</div>
                  {Array.from({ length: 24 }, (_, hour) => {
                    const cell = analytics.heatmap.find(
                      d => d.day === day && d.hour === hour
                    )
                    const count = cell?.count || 0
                    return (
                      <motion.div
                        key={hour}
                        className="flex-1 h-8 mx-0.5 rounded cursor-pointer hover:scale-110 transition-transform"
                        style={{
                          backgroundColor: count === 0 
                            ? '#1f2937' 
                            : `rgba(59, 130, 246, ${Math.min(1, count / maxCount)})`,
                        }}
                        onClick={() => setSelectedCell(cell || null)}
                        whileHover={{ scale: 1.1 }}
                        title={`${dayNames[day]} ${hour}:00 - ${count} accesses`}
                      />
                    )
                  })}
                </div>
              ))}
            </div>
          </div>
          {/* Legend */}
          <div className="mt-4 flex items-center gap-4">
            <span className="text-sm text-gray-400">Less</span>
            <div className="flex-1 h-4 bg-gradient-to-r from-gray-900 via-blue-500 to-red-500 rounded"></div>
            <span className="text-sm text-gray-400">More</span>
          </div>
        </div>

        {/* Selected Cell Info */}
        {selectedCell && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6 mb-8"
          >
            <h3 className="text-lg font-bold mb-4">Cell Details</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <div className="text-sm text-gray-400 mb-1">Day</div>
                <div className="font-semibold">{dayNames[selectedCell.day]}</div>
              </div>
              <div>
                <div className="text-sm text-gray-400 mb-1">Hour</div>
                <div className="font-semibold">{selectedCell.hour}:00</div>
              </div>
              <div>
                <div className="text-sm text-gray-400 mb-1">Accesses</div>
                <div className="font-semibold">{selectedCell.count}</div>
              </div>
              <div>
                <div className="text-sm text-gray-400 mb-1">Success Rate</div>
                <div className="font-semibold">{selectedCell.successRate.toFixed(1)}%</div>
              </div>
            </div>
          </motion.div>
        )}

        {/* Insights & Recommendations */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <i className="ri-lightbulb-line text-yellow-400"></i>
              Insights
            </h2>
            <div className="space-y-2">
              {analytics.insights.length === 0 ? (
                <p className="text-gray-400 text-sm">No insights available</p>
              ) : (
                analytics.insights.map((insight, idx) => (
                  <div key={idx} className="p-3 bg-white/5 rounded-lg text-sm">
                    {insight}
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="bg-white/5 backdrop-blur-xl rounded-xl border border-white/10 p-6">
            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
              <i className="ri-star-line text-cyan-400"></i>
              Recommendations
            </h2>
            <div className="space-y-2">
              {analytics.recommendations.length === 0 ? (
                <p className="text-gray-400 text-sm">No recommendations</p>
              ) : (
                analytics.recommendations.map((rec, idx) => (
                  <div key={idx} className="p-3 bg-white/5 rounded-lg text-sm">
                    {rec}
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { motion, AnimatePresence, useScroll, useTransform } from 'framer-motion'
import { User } from '@/types/user'

interface PremiumHeaderProps {
  language: 'en' | 'ar'
  setLanguage: (lang: 'en' | 'ar') => void
  user: User | null
  scrollY: number
}

export default function PremiumHeader({ language, setLanguage, user, scrollY }: PremiumHeaderProps) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [scrolled, setScrolled] = useState(false)
  const router = useRouter()
  const { scrollYProgress } = useScroll()
  const headerOpacity = useTransform(scrollYProgress, [0, 0.1], [0, 1])
  const headerBlur = useTransform(scrollYProgress, [0, 0.1], [0, 20])

  useEffect(() => {
    setScrolled(scrollY > 50)
  }, [scrollY])

  const translations = {
    en: {
      intelligence: 'Intelligence',
      operations: 'Operations',
      integration: 'Integration',
      governance: 'Governance',
      getStarted: 'Get Started',
      dashboard: 'Dashboard',
    },
    ar: {
      intelligence: 'الذكاء',
      operations: 'العمليات',
      integration: 'التكامل',
      governance: 'الحوكمة',
      getStarted: 'ابدأ الآن',
      dashboard: 'لوحة التحكم',
    },
  }

  const t = translations[language]

  return (
    <motion.header
      style={{
        opacity: headerOpacity,
        backdropFilter: `blur(${headerBlur}px)`,
      }}
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled
          ? 'bg-[#0a0a0f]/95 border-b border-[#05a4ff]/30 shadow-2xl shadow-[#05a4ff]/20'
          : 'bg-transparent'
      }`}
    >
      <div className="container mx-auto px-4 sm:px-6 lg:px-10">
        <nav className="flex items-center justify-between py-4">
          {/* Logo with 3D Effect */}
          <Link href="/premium" className="flex items-center group">
            <motion.div
              whileHover={{ scale: 1.1, rotateY: 5 }}
              whileTap={{ scale: 0.95 }}
              className="relative"
              style={{ transformStyle: 'preserve-3d' }}
            >
              <div className="absolute inset-0 bg-gradient-to-r from-[#05a4ff] to-[#00d4a8] blur-2xl opacity-50 group-hover:opacity-75 transition-opacity" />
              <div className="relative bg-gradient-to-br from-[#05a4ff]/30 to-[#00d4a8]/30 backdrop-blur-2xl border border-[#05a4ff]/40 rounded-2xl p-3 group-hover:border-[#05a4ff]/60 transition-all shadow-lg shadow-[#05a4ff]/20">
                <img 
                  src="/bluedxp-logo.svg" 
                  alt="BlueDXP" 
                  className="h-10 w-auto object-contain"
                />
              </div>
            </motion.div>
          </Link>

          {/* Desktop Navigation with Hover Effects */}
          <div className="hidden lg:flex items-center gap-10 flex-1 justify-center">
            {[
              { href: '#intelligence', label: t.intelligence },
              { href: '#operations', label: t.operations },
              { href: '#integration', label: t.integration },
              { href: '#governance', label: t.governance },
            ].map((item, index) => (
              <motion.a
                key={index}
                href={item.href}
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5, delay: index * 0.1 }}
                whileHover={{ scale: 1.1, y: -2 }}
                className="relative text-sm font-medium text-white/90 hover:text-[#05a4ff] transition-colors group"
              >
                {item.label}
                <motion.span
                  className="absolute bottom-0 left-0 h-0.5 bg-gradient-to-r from-[#05a4ff] to-[#00d4a8]"
                  initial={{ width: 0 }}
                  whileHover={{ width: '100%' }}
                  transition={{ duration: 0.3 }}
                />
              </motion.a>
            ))}
          </div>

          {/* Right Side Actions */}
          <div className="flex items-center gap-4">
            {/* Language Toggle with Glassmorphism */}
            <div className="hidden sm:flex gap-2 bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-1.5">
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => setLanguage('en')}
                className={`px-4 py-2 rounded-lg text-xs font-semibold transition-all ${
                  language === 'en'
                    ? 'bg-gradient-to-r from-[#05a4ff] to-[#0088d1] text-white shadow-lg shadow-[#05a4ff]/30'
                    : 'text-white/60 hover:text-white hover:bg-white/5'
                }`}
              >
                EN
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => setLanguage('ar')}
                className={`px-4 py-2 rounded-lg text-xs font-semibold transition-all ${
                  language === 'ar'
                    ? 'bg-gradient-to-r from-[#05a4ff] to-[#0088d1] text-white shadow-lg shadow-[#05a4ff]/30'
                    : 'text-white/60 hover:text-white hover:bg-white/5'
                }`}
              >
                العربية
              </motion.button>
            </div>

            {/* CTA Button with Glow Effect */}
            {user ? (
              <motion.button
                whileHover={{ scale: 1.05, boxShadow: '0 0 30px rgba(5, 164, 255, 0.5)' }}
                whileTap={{ scale: 0.95 }}
                onClick={() => router.push('/dashboard')}
                className="hidden sm:flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-[#05a4ff] to-[#0088d1] text-white font-semibold rounded-xl hover:from-[#0088d1] hover:to-[#006ea7] transition-all duration-300 shadow-xl shadow-[#05a4ff]/40 text-sm"
              >
                <i className="ri-dashboard-3-line"></i>
                {t.dashboard}
              </motion.button>
            ) : (
              <motion.button
                whileHover={{ scale: 1.05, boxShadow: '0 0 30px rgba(5, 164, 255, 0.5)' }}
                whileTap={{ scale: 0.95 }}
                onClick={() => router.push('/login')}
                className="hidden sm:flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-[#05a4ff] to-[#0088d1] text-white font-semibold rounded-xl hover:from-[#0088d1] hover:to-[#006ea7] transition-all duration-300 shadow-xl shadow-[#05a4ff]/40 text-sm"
              >
                <i className="ri-rocket-line"></i>
                {t.getStarted}
              </motion.button>
            )}

            {/* Mobile Menu Button */}
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="lg:hidden p-2 text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-colors"
            >
              <i className={`ri-${mobileMenuOpen ? 'close' : 'menu'}-line text-xl`}></i>
            </button>
          </div>
        </nav>

        {/* Mobile Menu */}
        <AnimatePresence>
          {mobileMenuOpen && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="lg:hidden border-t border-white/10 mt-4 pb-4"
            >
              <div className="flex flex-col gap-4 pt-4">
                {[
                  { href: '#intelligence', label: t.intelligence },
                  { href: '#operations', label: t.operations },
                  { href: '#integration', label: t.integration },
                  { href: '#governance', label: t.governance },
                ].map((item, index) => (
                  <motion.a
                    key={index}
                    href={item.href}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ duration: 0.3, delay: index * 0.1 }}
                    className="text-white/80 hover:text-[#05a4ff] transition-colors py-2"
                    onClick={() => setMobileMenuOpen(false)}
                  >
                    {item.label}
                  </motion.a>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.header>
  )
}

/**
 * Unified Process Lifecycle View
 * The ultimate component that shows lifecycle, workflow, process mining, and analytics together
 * Mind-blowing, layered, deep, and fully interactive
 */

'use client'

import { useState, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { processOrchestrator, getUnifiedProcessData } from '@/lib/services/process-lifecycle'
import LifecycleView from './lifecycle/LifecycleView'
import type { UnifiedProcessViewProps } from '@/types/process-lifecycle'
import ErrorBoundary from '@/components/ErrorBoundary'

export default function ProcessLifecycleView({
  entityId,
  entityType,
  showLifecycle = true,
  showWorkflow = true,
  showProcessMining = true,
  showAnalytics = true,
  showCrossModule = true,
  defaultView = 'unified',
  height = 800,
  enableRealTime = true,
  enablePredictive = true,
}: UnifiedProcessViewProps) {
  const [unifiedData, setUnifiedData] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [activeTab, setActiveTab] = useState<'lifecycle' | 'workflow' | 'mining' | 'analytics' | 'unified'>(defaultView as any)
  const [expandedLayers, setExpandedLayers] = useState<Set<string>>(new Set(['overview', 'details']))

  useEffect(() => {
    loadUnifiedData()
    
    if (enableRealTime) {
      const interval = setInterval(loadUnifiedData, 5000) // Update every 5 seconds
      return () => clearInterval(interval)
    }
  }, [entityId, entityType, enableRealTime])

  const loadUnifiedData = async () => {
    try {
      setLoading(true)
      setError(null)
      const data = await getUnifiedProcessData(entityId, entityType)
      setUnifiedData(data)
    } catch (err) {
      console.error('Error loading unified process data:', err)
      setError(err instanceof Error ? err.message : 'Failed to load process data')
    } finally {
      setLoading(false)
    }
  }

  const toggleLayer = (layer: string) => {
    setExpandedLayers(prev => {
      const newSet = new Set(prev)
      if (newSet.has(layer)) {
        newSet.delete(layer)
      } else {
        newSet.add(layer)
      }
      return newSet
    })
  }

  if (loading && !unifiedData) {
    return (
      <div className="flex items-center justify-center" style={{ height }}>
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-cyan-500 mx-auto mb-4"></div>
          <div className="text-[#9ca3af]">Loading unified process view...</div>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-6" style={{ height }}>
        <div className="flex items-center gap-3 text-red-400">
          <i className="ri-error-warning-line text-xl"></i>
          <div>
            <div className="font-semibold">Error Loading Process Data</div>
            <div className="text-sm text-red-300/80">{error}</div>
          </div>
        </div>
      </div>
    )
  }

  if (!unifiedData) {
    return (
      <div className="bg-white/5 border border-white/10 rounded-lg p-6" style={{ height }}>
        <div className="text-center text-[#9ca3af]">
          <i className="ri-information-line text-2xl mb-2"></i>
          <div>No process data found</div>
        </div>
      </div>
    )
  }

  return (
    <ErrorBoundary fallback={<div className="text-red-400 p-4">Error rendering process view</div>}>
      <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl overflow-hidden" style={{ minHeight: height }}>
        {/* Header with Tabs */}
        <div className="p-6 border-b border-white/10 bg-gradient-to-r from-cyan-500/10 to-blue-600/10">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-2xl font-bold text-white mb-1 flex items-center gap-2">
                <i className="ri-flow-chart-line text-cyan-400"></i>
                Process & Lifecycle View
              </h2>
              <p className="text-sm text-[#9ca3af]">
                {entityType.replace(/_/g, ' ')} • {entityId}
              </p>
            </div>
            <div className="flex items-center gap-2">
              {enableRealTime && (
                <div className="flex items-center gap-2 px-3 py-1.5 bg-green-500/20 text-green-400 rounded-lg border border-green-500/30">
                  <div className="w-2 h-2 rounded-full bg-green-400 animate-pulse"></div>
                  <span className="text-xs font-medium">Live</span>
                </div>
              )}
            </div>
          </div>

          {/* Tab Navigation */}
          <div className="flex items-center gap-2 bg-white/5 border border-white/10 rounded-lg p-1">
            {showLifecycle && (
