/**
 * Content Block Picker Component
 * Beautiful UI for browsing and inserting content blocks into proposals
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import type { ContentBlock } from '@/lib/services/proposals/contentBlockLibrary'

interface ContentBlockPickerProps {
  isOpen: boolean
  onClose: () => void
  onSelect: (block: ContentBlock) => void
  currentCategory?: string
}

export default function ContentBlockPicker({
  isOpen,
  onClose,
  onSelect,
  currentCategory,
}: ContentBlockPickerProps) {
  const [blocks, setBlocks] = useState<ContentBlock[]>([])
  const [filteredBlocks, setFilteredBlocks] = useState<ContentBlock[]>([])
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string>('ALL')
  const [selectedType, setSelectedType] = useState<string>('ALL')
  const [loading, setLoading] = useState(true)
  const [stats, setStats] = useState<any>(null)

  useEffect(() => {
    if (isOpen) {
      loadContentBlocks()
    }
  }, [isOpen])

  useEffect(() => {
    filterBlocks()
  }, [blocks, searchQuery, selectedCategory, selectedType])

  const loadContentBlocks = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams()
      if (selectedCategory !== 'ALL') params.append('category', selectedCategory)
      if (selectedType !== 'ALL') params.append('type', selectedType)
      if (searchQuery) params.append('q', searchQuery)
      params.append('status', 'APPROVED') // Only show approved blocks

      const res = await fetch(`/api/proposals/content-blocks?${params.toString()}`)
      const data = await res.json()
      
      if (data.success) {
        setBlocks(data.data.blocks || [])
        setStats(data.data.stats)
      }
    } catch (error) {
      console.error('Error loading content blocks:', error)
    } finally {
      setLoading(false)
    }
  }

  const filterBlocks = () => {
    let filtered = [...blocks]

    // Filter by search query
    if (searchQuery) {
      const query = searchQuery.toLowerCase()
      filtered = filtered.filter(
        block =>
          block.title.toLowerCase().includes(query) ||
          block.content.toLowerCase().includes(query) ||
          block.tags.some(tag => tag.toLowerCase().includes(query)) ||
          block.keywords.some(keyword => keyword.toLowerCase().includes(query))
      )
    }

    // Filter by category
    if (selectedCategory !== 'ALL') {
      filtered = filtered.filter(block => block.category === selectedCategory)
    }

    // Filter by type
    if (selectedType !== 'ALL') {
      filtered = filtered.filter(block => block.type === selectedType)
    }

    setFilteredBlocks(filtered)
  }

  const categories = ['ALL', ...Array.from(new Set(blocks.map(b => b.category)))]
  const types = ['ALL', 'TEXT', 'PRICING', 'TABLE', 'LIST', 'CUSTOM']

  const handleSelect = (block: ContentBlock) => {
    onSelect(block)
    onClose()
  }

  if (!isOpen) return null

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
        onClick={onClose}
      >
        <motion.div
          initial={{ scale: 0.9, y: 20 }}
          animate={{ scale: 1, y: 0 }}
          exit={{ scale: 0.9, y: 20 }}
          className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="p-6 border-b border-gray-200 dark:border-gray-700">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
                  Content Block Library
                </h2>
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                  Choose a reusable content block to insert into your proposal
                </p>
              </div>
              <button
                onClick={onClose}
                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
              >
                <i className="ri-close-line text-2xl text-gray-400" />
              </button>
            </div>

            {/* Search & Filters */}
            <div className="flex flex-col md:flex-row gap-3">
              <div className="flex-1 relative">
                <i className="ri-search-line absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input
                  type="text"
                  placeholder="Search content blocks..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
              >
                {categories.map(cat => (
                  <option key={cat} value={cat}>
                    {cat === 'ALL' ? 'All Categories' : cat.replace(/_/g, ' ')}
                  </option>
                ))}
              </select>
              <select
                value={selectedType}
                onChange={(e) => setSelectedType(e.target.value)}
                className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
              >
                {types.map(type => (
                  <option key={type} value={type}>
                    {type === 'ALL' ? 'All Types' : type}
                  </option>
                ))}
              </select>
            </div>

            {/* Stats */}
            {stats && (
              <div className="flex gap-4 mt-4 text-sm">
                <span className="text-gray-600 dark:text-gray-400">
                  <span className="font-semibold">{stats.totalBlocks || 0}</span> total blocks
                </span>
                <span className="text-gray-600 dark:text-gray-400">
                  <span className="font-semibold">{stats.approvedBlocks || 0}</span> approved
                </span>
                <span className="text-gray-600 dark:text-gray-400">
                  <span className="font-semibold">{filteredBlocks.length}</span> matching
                </span>
              </div>
            )}
          </div>

          {/* Content Blocks Grid */}
          <div className="flex-1 overflow-y-auto p-6">
            {loading ? (
              <div className="flex items-center justify-center py-12">
                <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-600 border-t-transparent"></div>
              </div>
            ) : filteredBlocks.length === 0 ? (
              <div className="text-center py-12">
                <i className="ri-file-search-line text-6xl text-gray-300 dark:text-gray-600 mb-4" />
                <p className="text-gray-500 dark:text-gray-400 mb-2">
                  No content blocks found
                </p>
                <p className="text-sm text-gray-400 dark:text-gray-500">
                  {searchQuery || selectedCategory !== 'ALL' || selectedType !== 'ALL'
                    ? 'Try adjusting your filters'
                    : 'Create your first content block to get started'}
                </p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {filteredBlocks.map((block) => (
                  <motion.div
                    key={block.id}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    whileHover={{ y: -2 }}
                    className="bg-gray-50 dark:bg-gray-700/50 rounded-xl p-4 border border-gray-200 dark:border-gray-600 hover:border-blue-300 dark:hover:border-blue-600 hover:shadow-lg transition-all cursor-pointer"
                    onClick={() => handleSelect(block)}
                  >
                    {/* Block Header */}
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <h3 className="font-semibold text-gray-900 dark:text-white">
                            {block.title}
                          </h3>
                          <span className="px-2 py-0.5 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 rounded text-xs font-medium">
                            {block.type}
                          </span>
                        </div>
                        <p className="text-xs text-gray-500 dark:text-gray-400">
                          {block.category.replace(/_/g, ' ')}
                        </p>
                      </div>
                      {block.status === 'APPROVED' && (
                        <span className="px-2 py-0.5 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 rounded text-xs">
                          Approved
                        </span>
                      )}
                    </div>

                    {/* Block Content Preview */}
                    <p className="text-sm text-gray-600 dark:text-gray-400 line-clamp-3 mb-3">
                      {block.content}
                    </p>

                    {/* Tags */}
                    {block.tags.length > 0 && (
                      <div className="flex flex-wrap gap-1 mb-3">
                        {block.tags.slice(0, 3).map((tag, index) => (
                          <span
                            key={index}
                            className="px-2 py-0.5 bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-300 rounded text-xs"
                          >
                            {tag}
                          </span>
                        ))}
                        {block.tags.length > 3 && (
                          <span className="px-2 py-0.5 bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-300 rounded text-xs">
                            +{block.tags.length - 3}
                          </span>
                        )}
                      </div>
                    )}

                    {/* Usage Stats */}
                    <div className="flex items-center justify-between text-xs text-gray-500 dark:text-gray-400 pt-3 border-t border-gray-200 dark:border-gray-600">
                      <span>
                        <i className="ri-file-copy-line mr-1" />
                        Used {block.usageCount} times
                      </span>
                      <span>
                        v{block.version}
                      </span>
                    </div>
                  </motion.div>
                ))}
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="p-6 border-t border-gray-200 dark:border-gray-700 flex items-center justify-between">
            <button
              onClick={onClose}
              className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
            >
              Cancel
            </button>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              Select a block to insert it into your proposal
            </p>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  )
}

/**
 * Proposal Collaboration Panel
 * 
 * Real-time collaboration features for proposals
 * Comments, mentions, version control
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

interface CollaborationComment {
  id: string
  userId: string
  userName: string
  userAvatar?: string
  content: string
  sectionId?: string
  mentions?: string[]
  createdAt: string
  updatedAt?: string
}

interface ProposalCollaborationPanelProps {
  proposalId: string
  currentUserId: string
  currentUserName: string
  onComment?: (comment: CollaborationComment) => void
  onMention?: (userId: string) => void
}

export default function ProposalCollaborationPanel({
  proposalId,
  currentUserId,
  currentUserName,
  onComment,
  onMention,
}: ProposalCollaborationPanelProps) {
  const [comments, setComments] = useState<CollaborationComment[]>([])
  const [newComment, setNewComment] = useState('')
  const [isTyping, setIsTyping] = useState(false)
  const [activeUsers, setActiveUsers] = useState<string[]>([])

  useEffect(() => {
    // Load comments
    loadComments()
    
    // Set up real-time updates (would use WebSocket in production)
    const interval = setInterval(() => {
      loadComments()
    }, 5000) // Poll every 5 seconds

    return () => clearInterval(interval)
  }, [proposalId])

  const loadComments = async () => {
    try {
      const response = await fetch(`/api/proposals/${proposalId}/comments`)
      const data = await response.json()
      
      if (data.success && data.comments) {
        setComments(data.comments)
      }
    } catch (error) {
      console.error('Error loading comments:', error)
    }
  }

  const handleSubmitComment = async () => {
    if (!newComment.trim()) return

    const comment: CollaborationComment = {
      id: `comment-${Date.now()}`,
      userId: currentUserId,
      userName: currentUserName,
      content: newComment,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    }

    try {
      const response = await fetch(`/api/proposals/${proposalId}/comments`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(comment),
      })

      const data = await response.json()
      
      if (data.success) {
        setComments([...comments, comment])
        setNewComment('')
        onComment?.(comment)
      }
    } catch (error) {
      console.error('Error submitting comment:', error)
    }
  }

  const handleMention = (userId: string) => {
    setNewComment(prev => `${prev}@${userId} `)
    onMention?.(userId)
  }

  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
          Collaboration
        </h3>
        <div className="flex items-center gap-2">
          {activeUsers.length > 0 && (
            <div className="flex -space-x-2">
              {activeUsers.slice(0, 3).map((userId, idx) => (
                <div
                  key={userId}
                  className="w-8 h-8 rounded-full bg-blue-500 border-2 border-white dark:border-gray-800 flex items-center justify-center text-white text-xs font-medium"
                  style={{ zIndex: 10 - idx }}
                >
                  {userId.charAt(0).toUpperCase()}
                </div>
              ))}
            </div>
          )}
          <span className="text-sm text-gray-500 dark:text-gray-400">
            {activeUsers.length} active
          </span>
        </div>
      </div>

      {/* Comments List */}
      <div className="space-y-4 mb-4 max-h-96 overflow-y-auto">
        <AnimatePresence>
          {comments.map((comment) => (
            <motion.div
              key={comment.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="p-3 bg-gray-50 dark:bg-gray-700 rounded-lg"
            >
              <div className="flex items-start gap-3">
                <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center text-white text-sm font-medium">
                  {comment.userName.charAt(0).toUpperCase()}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="font-medium text-gray-900 dark:text-white text-sm">
                      {comment.userName}
                    </span>
                    <span className="text-xs text-gray-500 dark:text-gray-400">
                      {new Date(comment.createdAt).toLocaleTimeString()}
                    </span>
                  </div>
                  <p className="text-sm text-gray-700 dark:text-gray-300">
                    {comment.content}
                  </p>
                </div>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>

        {comments.length === 0 && (
          <div className="text-center py-8 text-gray-500 dark:text-gray-400">
            <i className="ri-chat-3-line text-3xl mb-2" />
            <p className="text-sm">No comments yet</p>
            <p className="text-xs mt-1">Start the conversation</p>
          </div>
        )}
      </div>

      {/* Comment Input */}
      <div className="border-t border-gray-200 dark:border-gray-700 pt-4">
        <div className="flex gap-2">
          <input
            type="text"
            value={newComment}
            onChange={(e) => {
              setNewComment(e.target.value)
              setIsTyping(e.target.value.length > 0)
            }}
            onKeyPress={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault()
                handleSubmitComment()
              }
            }}
            placeholder="Add a comment... (Press Enter to send)"
            className="flex-1 px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
          <button
            onClick={handleSubmitComment}
            disabled={!newComment.trim()}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            <i className="ri-send-plane-line" />
          </button>
        </div>
        {isTyping && (
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-2">
            Press Enter to send
          </p>
        )}
      </div>
    </div>
  )
}

/**
 * Proposal Compliance Status Component
 * Displays compliance check/validation status with detailed breakdown
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'

// ============================================================================
// TYPES
// ============================================================================

interface ComplianceCheck {
  proposalId: string
  compliant: boolean
  complianceScore: number
  requirements: Array<{
    requirementId: string
    requirementCode: string
    requirementTitle: string
    compliant: boolean
    severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW'
    violations: string[]
    recommendations: string[]
  }>
  missingDocuments: string[]
  missingCertifications: string[]
  regulatoryGaps: string[]
  recommendations: string[]
  checkedAt: string
}

interface ComplianceValidation {
  proposalId: string
  validationStatus: 'COMPLIANT' | 'PARTIALLY_COMPLIANT' | 'NON_COMPLIANT' | 'PENDING'
  overallScore: number
  criticalIssues: number
  highPriorityIssues: number
  mediumPriorityIssues: number
  lowPriorityIssues: number
  autoApproved: boolean
  requiresManualReview: boolean
  validatedAt: string
}

interface ProposalComplianceStatusProps {
  proposalId: string
  className?: string
  showValidation?: boolean
}

// ============================================================================
// COMPONENT
// ============================================================================

export default function ProposalComplianceStatus({
  proposalId,
  className = '',
  showValidation = false,
}: ProposalComplianceStatusProps) {
  const [check, setCheck] = useState<ComplianceCheck | null>(null)
  const [validation, setValidation] = useState<ComplianceValidation | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)

  useEffect(() => {
    loadComplianceData()
  }, [proposalId, showValidation])

  const loadComplianceData = async () => {
    setLoading(true)
    try {
      // Load compliance check
      const checkRes = await fetch(`/api/proposals/${proposalId}/compliance?type=check`)
      if (checkRes.ok) {
        const checkData = await checkRes.json()
        setCheck(checkData)
      }

      // Load validation if requested
      if (showValidation) {
        const validationRes = await fetch(`/api/proposals/${proposalId}/compliance?type=validation`)
        if (validationRes.ok) {
          const validationData = await validationRes.json()
          setValidation(validationData)
        }
      }
    } catch (error) {
      console.error('Error loading compliance data:', error)
    } finally {
      setLoading(false)
    }
  }

  const triggerCheck = async () => {
    setRefreshing(true)
    try {
      const res = await fetch(`/api/proposals/${proposalId}/compliance`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'check' }),
      })
      if (res.ok) {
        const data = await res.json()
        setCheck(data)
      }
    } catch (error) {
      console.error('Error triggering compliance check:', error)
    } finally {
      setRefreshing(false)
    }
  }

  const triggerValidation = async () => {
    setRefreshing(true)
    try {
      const res = await fetch(`/api/proposals/${proposalId}/compliance`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'validation' }),
      })
      if (res.ok) {
        const data = await res.json()
        setValidation(data)
      }
    } catch (error) {
      console.error('Error triggering compliance validation:', error)
    } finally {
      setRefreshing(false)
    }
  }

  const getStatusColor = (status: string, score?: number) => {
    if (status === 'COMPLIANT' || (score !== undefined && score >= 95)) {
      return 'text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800'
    }
    if (status === 'PARTIALLY_COMPLIANT' || (score !== undefined && score >= 80)) {
      return 'text-yellow-600 dark:text-yellow-400 bg-yellow-50 dark:bg-yellow-900/20 border-yellow-200 dark:border-yellow-800'
    }
    if (status === 'NON_COMPLIANT' || (score !== undefined && score < 80)) {
      return 'text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800'
    }
    return 'text-gray-600 dark:text-gray-400 bg-gray-50 dark:bg-gray-700 border-gray-200 dark:border-gray-600'
  }

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'CRITICAL':
        return 'text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20'
      case 'HIGH':
        return 'text-orange-600 dark:text-orange-400 bg-orange-50 dark:bg-orange-900/20'
      case 'MEDIUM':
        return 'text-yellow-600 dark:text-yellow-400 bg-yellow-50 dark:bg-yellow-900/20'
      case 'LOW':
        return 'text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20'
      default:
        return 'text-gray-600 dark:text-gray-400 bg-gray-50 dark:bg-gray-700'
    }
  }

  if (loading) {
    return (
      <div className={`bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 ${className}`}>
        <div className="flex items-center justify-center h-32">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
        </div>
      </div>
    )
  }

  return (
    <div className={`bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            Compliance Status
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            Regulatory compliance check and validation
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={triggerCheck}
            disabled={refreshing}
            className="px-3 py-1.5 text-sm font-medium text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/30 disabled:opacity-50"
          >
            {refreshing ? 'Checking...' : 'Check Compliance'}
          </button>
          {showValidation && (
            <button
              onClick={triggerValidation}
              disabled={refreshing}
              className="px-3 py-1.5 text-sm font-medium text-purple-600 dark:text-purple-400 bg-purple-50 dark:bg-purple-900/20 rounded-lg hover:bg-purple-100 dark:hover:bg-purple-900/30 disabled:opacity-50"
            >
              Validate
            </button>
          )}
        </div>
      </div>

      {/* Validation Status (if available) */}
      {validation && (
        <div className={`mb-6 p-4 rounded-lg border ${getStatusColor(validation.validationStatus, validation.overallScore)}`}>
          <div className="flex items-center justify-between mb-3">
            <div>
              <p className="text-sm font-medium mb-1">Validation Status</p>
              <p className="text-2xl font-bold">{validation.validationStatus}</p>
            </div>
            <div className="text-right">
              <p className="text-sm font-medium mb-1">Overall Score</p>
              <p className="text-2xl font-bold">{validation.overallScore}%</p>
            </div>
          </div>
          <div className="grid grid-cols-4 gap-4 mt-4">
            <div>
              <p className="text-xs text-gray-600 dark:text-gray-400 mb-1">Critical</p>
              <p className="text-lg font-semibold text-red-600 dark:text-red-400">
                {validation.criticalIssues}
              </p>
            </div>
            <div>
              <p className="text-xs text-gray-600 dark:text-gray-400 mb-1">High</p>
              <p className="text-lg font-semibold text-orange-600 dark:text-orange-400">
                {validation.highPriorityIssues}
              </p>
            </div>
            <div>
              <p className="text-xs text-gray-600 dark:text-gray-400 mb-1">Medium</p>
              <p className="text-lg font-semibold text-yellow-600 dark:text-yellow-400">
                {validation.mediumPriorityIssues}
              </p>
            </div>
            <div>
              <p className="text-xs text-gray-600 dark:text-gray-400 mb-1">Low</p>
              <p className="text-lg font-semibold text-blue-600 dark:text-blue-400">
                {validation.lowPriorityIssues}
              </p>
            </div>
          </div>
          {validation.autoApproved && (
            <div className="mt-3 p-2 bg-green-100 dark:bg-green-900/30 rounded text-sm text-green-700 dark:text-green-300">
              ✓ Auto-approved (no manual review required)
            </div>
          )}
          {validation.requiresManualReview && (
            <div className="mt-3 p-2 bg-amber-100 dark:bg-amber-900/30 rounded text-sm text-amber-700 dark:text-amber-300">
              ⚠ Manual review required
            </div>
          )}
        </div>
      )}

      {/* Compliance Check Status */}
      {check ? (
        <div className="space-y-4">
          {/* Overall Status */}
          <div className={`p-4 rounded-lg border ${getStatusColor('', check.complianceScore)}`}>
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium mb-1">Compliance Score</p>
                <p className="text-3xl font-bold">{check.complianceScore}%</p>
              </div>
              <div className="text-right">
                <p className="text-sm font-medium mb-1">Status</p>
                <p className={`text-lg font-semibold ${check.compliant ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                  {check.compliant ? '✓ Compliant' : '✗ Non-Compliant'}
                </p>
              </div>
            </div>
          </div>

          {/* Requirements */}
          {check.requirements.length > 0 && (
            <div>
              <h4 className="text-sm font-semibold text-gray-900 dark:text-white mb-3">
                Requirements ({check.requirements.length})
              </h4>
              <div className="space-y-2">
                {check.requirements.map((req, index) => (
                  <motion.div
                    key={req.requirementId}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                    className={`p-3 rounded-lg border ${
                      req.compliant
                        ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800'
                        : 'bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800'
                    }`}
                  >
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <span className={`px-2 py-0.5 rounded text-xs font-medium ${getSeverityColor(req.severity)}`}>
                            {req.severity}
                          </span>
                          <span className="text-xs text-gray-500 dark:text-gray-400">
                            {req.requirementCode}
                          </span>
                        </div>
                        <p className="font-medium text-gray-900 dark:text-white text-sm">
                          {req.requirementTitle}
                        </p>
                        {!req.compliant && req.violations.length > 0 && (
                          <ul className="mt-2 text-xs text-red-600 dark:text-red-400 space-y-1">
                            {req.violations.map((violation, i) => (
                              <li key={i}>• {violation}</li>
                            ))}
                          </ul>
                        )}
                        {!req.compliant && req.recommendations.length > 0 && (
                          <div className="mt-2 p-2 bg-blue-50 dark:bg-blue-900/20 rounded text-xs">
                            <p className="font-medium text-blue-900 dark:text-blue-200 mb-1">
                              Recommendations:
                            </p>
                            <ul className="space-y-1 text-blue-800 dark:text-blue-300">
                              {req.recommendations.map((rec, i) => (
                                <li key={i}>• {rec}</li>
                              ))}
                            </ul>
                          </div>
                        )}
                      </div>
                      <div className="ml-4">
                        {req.compliant ? (
                          <i className="ri-checkbox-circle-fill text-green-600 dark:text-green-400 text-xl" />
                        ) : (
                          <i className="ri-close-circle-fill text-red-600 dark:text-red-400 text-xl" />
                        )}
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            </div>
          )}

          {/* Missing Items */}
          {(check.missingDocuments.length > 0 || check.missingCertifications.length > 0) && (
            <div>
              <h4 className="text-sm font-semibold text-gray-900 dark:text-white mb-3">
                Missing Items
              </h4>
              {check.missingDocuments.length > 0 && (
                <div className="mb-2 p-3 bg-amber-50 dark:bg-amber-900/20 rounded-lg border border-amber-200 dark:border-amber-800">
                  <p className="text-sm font-medium text-amber-900 dark:text-amber-200 mb-1">
                    Missing Documents:
                  </p>
                  <ul className="text-xs text-amber-800 dark:text-amber-300 space-y-1">
                    {check.missingDocuments.map((doc, i) => (
                      <li key={i}>• {doc}</li>
                    ))}
                  </ul>
                </div>
              )}
              {check.missingCertifications.length > 0 && (
                <div className="p-3 bg-amber-50 dark:bg-amber-900/20 rounded-lg border border-amber-200 dark:border-amber-800">
                  <p className="text-sm font-medium text-amber-900 dark:text-amber-200 mb-1">
                    Missing Certifications:
                  </p>
                  <ul className="text-xs text-amber-800 dark:text-amber-300 space-y-1">
                    {check.missingCertifications.map((cert, i) => (
                      <li key={i}>• {cert}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

          {/* Recommendations */}
          {check.recommendations.length > 0 && (
            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
              <h4 className="text-sm font-semibold text-blue-900 dark:text-blue-200 mb-2">
                General Recommendations
              </h4>
              <ul className="text-sm text-blue-800 dark:text-blue-300 space-y-1">
                {check.recommendations.map((rec, i) => (
                  <li key={i}>• {rec}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      ) : (
        <div className="text-center py-8">
          <i className="ri-file-shield-line text-4xl text-gray-400 dark:text-gray-600 mb-3" />
          <p className="text-sm text-gray-500 dark:text-gray-400">
            No compliance check performed yet
          </p>
          <button
            onClick={triggerCheck}
            className="mt-4 px-4 py-2 text-sm font-medium text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 rounded-lg hover:bg-blue-100 dark:hover:bg-blue-900/30"
          >
            Run Compliance Check
          </button>
        </div>
      )}
    </div>
  )
}

/**
 * Proposal Engagement Heatmap Component
 * Beautiful visualization of proposal engagement by section, time, and recipient
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Cell,
} from 'recharts'

// ============================================================================
// TYPES
// ============================================================================

interface SectionEngagement {
  sectionId: string
  sectionTitle: string
  viewCount: number
  averageTimeSpent: number
  uniqueViewers: number
  scrollDepth: number
  engagementScore: number
}

interface EngagementHeatmapData {
  proposalId: string
  sections: SectionEngagement[]
  overallEngagement: number
}

interface ProposalEngagementHeatmapProps {
  proposalId: string
  className?: string
}

// ============================================================================
// COMPONENT
// ============================================================================

export default function ProposalEngagementHeatmap({
  proposalId,
  className = '',
}: ProposalEngagementHeatmapProps) {
  const [data, setData] = useState<EngagementHeatmapData | null>(null)
  const [loading, setLoading] = useState(true)
  const [timeRange, setTimeRange] = useState<'7d' | '30d' | '90d' | 'all'>('30d')

  useEffect(() => {
    loadHeatmapData()
  }, [proposalId, timeRange])

  const loadHeatmapData = async () => {
    setLoading(true)
    try {
      const response = await fetch(`/api/proposals/${proposalId}/tracking/heatmap?range=${timeRange}`)
      if (response.ok) {
        const heatmapData = await response.json()
        setData(heatmapData)
      } else {
        // Fallback to mock data
        setData(generateMockData())
      }
    } catch (error) {
      console.error('Error loading heatmap data:', error)
      setData(generateMockData())
    } finally {
      setLoading(false)
    }
  }

  const generateMockData = (): EngagementHeatmapData => {
    return {
      proposalId,
      sections: [
        {
          sectionId: 'exec-summary',
          sectionTitle: 'Executive Summary',
          viewCount: 95,
          averageTimeSpent: 120,
          uniqueViewers: 8,
          scrollDepth: 92,
          engagementScore: 95,
        },
        {
          sectionId: 'services',
          sectionTitle: 'Services Overview',
          viewCount: 87,
          averageTimeSpent: 180,
          uniqueViewers: 7,
          scrollDepth: 88,
          engagementScore: 88,
        },
        {
          sectionId: 'pricing',
          sectionTitle: 'Pricing & Rates',
          viewCount: 82,
          averageTimeSpent: 240,
          uniqueViewers: 6,
          scrollDepth: 85,
          engagementScore: 85,
        },
        {
          sectionId: 'case-studies',
          sectionTitle: 'Case Studies',
          viewCount: 65,
          averageTimeSpent: 150,
          uniqueViewers: 5,
          scrollDepth: 72,
          engagementScore: 72,
        },
        {
          sectionId: 'terms',
          sectionTitle: 'Terms & Conditions',
          viewCount: 45,
          averageTimeSpent: 90,
          uniqueViewers: 4,
          scrollDepth: 58,
          engagementScore: 58,
        },
      ],
      overallEngagement: 80,
    }
  }

  const getIntensityColor = (score: number): string => {
    if (score >= 90) return '#10B981' // Green
    if (score >= 75) return '#3B82F6' // Blue
    if (score >= 60) return '#F59E0B' // Yellow
    if (score >= 40) return '#F97316' // Orange
    return '#EF4444' // Red
  }

  const formatTime = (seconds: number): string => {
    if (seconds < 60) return `${seconds}s`
    const minutes = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${minutes}m ${secs}s`
  }

  if (loading) {
    return (
      <div className={`bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 ${className}`}>
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
        </div>
      </div>
    )
  }

  if (!data) {
    return (
      <div className={`bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 ${className}`}>
        <p className="text-gray-500 dark:text-gray-400">No engagement data available</p>
      </div>
    )
  }

  return (
    <div className={`bg-white dark:bg-gray-800 rounded-xl p-6 border border-gray-200 dark:border-gray-700 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            Engagement Heatmap
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            Section-by-section engagement analysis
          </p>
        </div>
        <div className="flex items-center gap-2">
          {(['7d', '30d', '90d', 'all'] as const).map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`px-3 py-1 rounded-lg text-sm font-medium transition-colors ${
                timeRange === range
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              {range === 'all' ? 'All' : range.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      {/* Overall Engagement Score */}
      <div className="mb-6 p-4 bg-gradient-to-r from-blue-50 to-indigo-50 dark:from-blue-900/20 dark:to-indigo-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-gray-600 dark:text-gray-400">Overall Engagement Score</p>
            <p className="text-3xl font-bold text-gray-900 dark:text-white mt-1">
              {data.overallEngagement}%
            </p>
          </div>
          <div className="w-16 h-16 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center">
            <span className="text-2xl font-bold text-blue-600 dark:text-blue-400">
              {data.overallEngagement}
            </span>
          </div>
        </div>
      </div>

      {/* Heatmap Visualization */}
      <div className="space-y-4 mb-6">
        {data.sections.map((section, index) => (
          <motion.div
            key={section.sectionId}
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: index * 0.1 }}
            className="p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg"
          >
            <div className="flex items-center justify-between mb-3">
              <div className="flex-1">
                <h4 className="font-medium text-gray-900 dark:text-white">
                  {section.sectionTitle}
                </h4>
                <div className="flex items-center gap-4 mt-2 text-sm text-gray-600 dark:text-gray-400">
                  <span className="flex items-center gap-1">
                    <i className="ri-eye-line" />
                    {section.viewCount} views
                  </span>
                  <span className="flex items-center gap-1">
                    <i className="ri-time-line" />
                    {formatTime(section.averageTimeSpent)} avg
                  </span>
                  <span className="flex items-center gap-1">
                    <i className="ri-user-line" />
                    {section.uniqueViewers} viewers
                  </span>
                </div>
              </div>
              <div className="text-right">
                <div className="text-2xl font-bold" style={{ color: getIntensityColor(section.engagementScore) }}>
                  {section.engagementScore}%
                </div>
                <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                  Engagement
                </div>
              </div>
            </div>

            {/* Engagement Bar */}
            <div className="mt-3">
              <div className="flex items-center gap-2 mb-2">
                <div className="flex-1 h-3 bg-gray-200 dark:bg-gray-600 rounded-full overflow-hidden">
                  <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: `${section.engagementScore}%` }}
                    transition={{ duration: 0.5, delay: index * 0.1 }}
                    className="h-full rounded-full"
                    style={{ backgroundColor: getIntensityColor(section.engagementScore) }}
                  />
                </div>
                <span className="text-xs text-gray-500 dark:text-gray-400 w-12 text-right">
                  {section.scrollDepth}% scroll
                </span>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Chart Visualization */}
      <div className="mt-6">
        <h4 className="text-sm font-medium text-gray-900 dark:text-white mb-4">
          Engagement Comparison
        </h4>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={data.sections}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis 
              dataKey="sectionTitle" 
              angle={-45} 
              textAnchor="end" 
              height={100}
              tick={{ fontSize: 12 }}
            />
            <YAxis />
            <Tooltip 
              formatter={(value: number, name: string) => {
                if (name === 'engagementScore') return [`${value}%`, 'Engagement']
                if (name === 'averageTimeSpent') return [formatTime(value), 'Avg Time']
                return [value, name]
              }}
            />
            <Legend />
            <Bar dataKey="engagementScore" fill="#3B82F6" name="Engagement Score" />
            <Bar dataKey="viewCount" fill="#10B981" name="View Count" />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Insights */}
      <div className="mt-6 p-4 bg-amber-50 dark:bg-amber-900/20 rounded-lg border border-amber-200 dark:border-amber-800">
        <div className="flex items-start gap-3">
          <i className="ri-lightbulb-line text-amber-600 dark:text-amber-400 text-xl mt-1" />
          <div>
            <h4 className="font-medium text-amber-900 dark:text-amber-200 mb-1">
              Engagement Insights
            </h4>
            <ul className="text-sm text-amber-800 dark:text-amber-300 space-y-1">
              {data.sections
                .sort((a, b) => b.engagementScore - a.engagementScore)
                .slice(0, 2)
                .map((section) => (
                  <li key={section.sectionId}>
                    • <strong>{section.sectionTitle}</strong> has the highest engagement at {section.engagementScore}%
                  </li>
                ))}
              {data.sections
                .sort((a, b) => a.engagementScore - b.engagementScore)
                .slice(0, 1)
                .map((section) => (
                  <li key={section.sectionId}>
                    • <strong>{section.sectionTitle}</strong> needs improvement ({section.engagementScore}% engagement)
                  </li>
                ))}
            </ul>
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * Proposal Evidence & Liability Panel
 * Comprehensive view of proposal evidence, liability assessment, and contract status
 * Deep integration with Evidence Ledger, Liability Engine, and Contract Service
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Link from 'next/link'

interface ProposalEvidenceLiabilityPanelProps {
  proposalId: string
  tenantId?: string
}

export default function ProposalEvidenceLiabilityPanel({
  proposalId,
  tenantId = 'default',
}: ProposalEvidenceLiabilityPanelProps) {
  const [evidence, setEvidence] = useState<any>(null)
  const [liability, setLiability] = useState<any>(null)
  const [contract, setContract] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState<'evidence' | 'liability' | 'contract'>('evidence')

  useEffect(() => {
    loadAllData()
  }, [proposalId])

  const loadAllData = async () => {
    setLoading(true)
    try {
      // Load evidence lineage
      const evidenceRes = await fetch(`/api/proposals/${proposalId}/evidence?tenantId=${tenantId}`)
      const evidenceData = await evidenceRes.json()
      if (evidenceData.success) setEvidence(evidenceData.data)

      // Load liability assessment
      const liabilityRes = await fetch(`/api/proposals/${proposalId}/liability?tenantId=${tenantId}`)
      const liabilityData = await liabilityRes.json()
      if (liabilityData.success) setLiability(liabilityData.data)

      // Load contract status
      const contractRes = await fetch(`/api/proposals/${proposalId}/contract?tenantId=${tenantId}`)
      const contractData = await contractRes.json()
      if (contractData.success) setContract(contractData.data)
    } catch (error) {
      console.error('Error loading evidence/liability/contract data:', error)
    } finally {
      setLoading(false)
    }
  }

  const getRiskColor = (riskLevel: string) => {
    switch (riskLevel) {
      case 'LOW':
        return 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
      case 'MEDIUM':
        return 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400'
      case 'HIGH':
        return 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'
      case 'CRITICAL':
        return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
      default:
        return 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-400'
    }
  }

  if (loading) {
    return (
      <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6">
        <div className="animate-pulse space-y-4">
          <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-1/4"></div>
          <div className="h-20 bg-gray-200 dark:bg-gray-700 rounded"></div>
        </div>
      </div>
    )
  }

  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden">
      {/* Tabs */}
      <div className="border-b border-gray-200 dark:border-gray-700">
        <div className="flex">
          <button
            onClick={() => setActiveTab('evidence')}
            className={`flex-1 px-4 py-3 text-sm font-medium transition-colors ${
              activeTab === 'evidence'
                ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <i className="ri-file-shield-line mr-2" />
            Evidence
          </button>
          <button
            onClick={() => setActiveTab('liability')}
            className={`flex-1 px-4 py-3 text-sm font-medium transition-colors ${
              activeTab === 'liability'
                ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <i className="ri-shield-cross-line mr-2" />
            Liability & Risk
          </button>
          <button
            onClick={() => setActiveTab('contract')}
            className={`flex-1 px-4 py-3 text-sm font-medium transition-colors ${
              activeTab === 'contract'
                ? 'border-b-2 border-blue-600 text-blue-600 dark:text-blue-400'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <i className="ri-file-paper-line mr-2" />
            Contract
          </button>
        </div>
      </div>

      {/* Tab Content */}
      <div className="p-6">
        <AnimatePresence mode="wait">
          {activeTab === 'evidence' && (
            <motion.div
              key="evidence"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-4"
            >
              {evidence ? (
                <>
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                      Evidence Lineage
                    </h3>
                    <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                      evidence.integrity?.valid
                        ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
                        : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'
                    }`}>
                      <i className={`ri-${evidence.integrity?.valid ? 'check' : 'close'}-line mr-1`} />
                      {evidence.integrity?.valid ? 'Verified' : 'Invalid'}
                    </span>
                  </div>

                  <div className="space-y-3">
                    <div className="p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                          Evidence Chain
                        </span>
                        <span className="text-sm text-gray-500 dark:text-gray-400">
                          {evidence.evidenceChain?.length || 0} records
                        </span>
                      </div>
                      <div className="space-y-2">
                        {evidence.evidenceChain?.slice(0, 5).map((ev: any, index: number) => (
                          <div key={ev.id} className="flex items-center gap-2 text-sm">
                            <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                            <span className="text-gray-600 dark:text-gray-400">
                              {ev.metadata?.action || ev.type}
                            </span>
                            <span className="text-gray-400 dark:text-gray-500 text-xs">
                              {new Date(ev.timestamp).toLocaleDateString()}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                          Chain of Custody
                        </span>
                        <span className="text-sm text-gray-500 dark:text-gray-400">
                          {evidence.chainOfCustody?.length || 0} transfers
                        </span>
                      </div>
                      {evidence.chainOfCustody?.length > 0 ? (
                        <div className="space-y-2">
                          {evidence.chainOfCustody.map((custody: any, index: number) => (
                            <div key={index} className="text-sm text-gray-600 dark:text-gray-400">
                              <i className="ri-arrow-right-line mr-2" />
                              {custody.from} → {custody.to}
                              <span className="text-xs text-gray-400 ml-2">
                                {new Date(custody.timestamp).toLocaleDateString()}
                              </span>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <p className="text-sm text-gray-500 dark:text-gray-400">
                          No custody transfers recorded
                        </p>
                      )}
                    </div>

                    <Link
                      href={`/evidence?entityId=${proposalId}&entityType=Proposal`}
                      className="block text-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm"
                    >
                      <i className="ri-external-link-line mr-2" />
                      View Full Evidence Ledger
                    </Link>
                  </div>
                </>
              ) : (
                <div className="text-center py-8">
                  <i className="ri-file-shield-line text-4xl text-gray-300 dark:text-gray-600 mb-3" />
                  <p className="text-gray-500 dark:text-gray-400">No evidence recorded yet</p>
                </div>
              )}
            </motion.div>
          )}

          {activeTab === 'liability' && (
            <motion.div
              key="liability"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              className="space-y-4"
            >
              {liability ? (
                <>
                  <div className="flex items-center justify-between">
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                      Liability Assessment
                    </h3>
                    <span className={`px-3 py-1 rounded-full text-sm font-medium ${getRiskColor(liability.riskLevel)}`}>
                      {liability.riskLevel} Risk
                    </span>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg">
                      <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">Potential Exposure</p>
                      <p className="text-lg font-semibold text-gray-900 dark:text-white">
                        {new Intl.NumberFormat('en-US', {
                          style: 'currency',
                          currency: liability.liabilityExposure?.currency || 'SAR',
                        }).format(liability.liabilityExposure?.potentialExposure || 0)}
                      </p>
                    </div>
