                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-center text-gray-500 py-8">No business continuity plans found</p>
        )}
      </div>

      {/* Active Crises */}
      {crises.filter(c => c.status !== 'RESOLVED' && c.status !== 'CLOSED').length > 0 && (
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border-2 border-red-300 dark:border-red-700 p-6">
          <h3 className="text-lg font-semibold text-red-900 dark:text-red-100 flex items-center gap-2 mb-4">
            <FiAlertTriangle className="w-5 h-5 text-red-600" />
            Active Crises
          </h3>
          <div className="space-y-3">
            {crises.filter(c => c.status !== 'RESOLVED' && c.status !== 'CLOSED').map((crisis) => (
              <div key={crisis.id} className="p-4 bg-red-50 dark:bg-red-900/20 rounded-lg border border-red-200 dark:border-red-700">
                <div className="flex items-center justify-between">
                  <div>
                    <h4 className="font-semibold text-red-900 dark:text-red-100">{crisis.crisisType}</h4>
                    <p className="text-sm text-red-700 dark:text-red-300 mt-1">{crisis.description}</p>
                    <div className="flex items-center gap-4 mt-2 text-xs text-red-600 dark:text-red-400">
                      <span>Detected: {new Date(crisis.detectedDate).toLocaleDateString()}</span>
                      <span>Severity: {crisis.severity}</span>
                      {crisis.response.activated && (
                        <span className="font-medium">Response Activated</span>
                      )}
                    </div>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                    crisis.severity === 'CRITICAL' ? 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' :
                    'bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200'
                  }`}>
                    {crisis.status}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

