                  }`}>
                    {plan.status}
                  </span>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-center text-gray-500 py-8">No HACCP plans found</p>
        )}
      </div>
    </div>
  )
}

export default FoodSafetyDashboard

/**
 * QHSE Calendar Grid View
 * Interactive calendar with incidents, audits, training, and inspections
 * 
 * FEATURES:
 * - Month/Week/Day views
 * - Event categorization (incidents, audits, training, inspections)
 * - Color-coded by severity/type
 * - Drag-and-drop scheduling (future)
 * - Event details on click
 */

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

type EventType = 'INCIDENT' | 'AUDIT' | 'TRAINING' | 'INSPECTION' | 'MEETING'
type Severity = 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL'

interface QHSEEvent {
  id: string
  title: string
  type: EventType
  date: Date
  time?: string
  severity?: Severity
  status: 'SCHEDULED' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED'
  assignedTo?: string
  location?: string
  description?: string
}

interface QHSECalendarGridViewProps {
  tenantId?: string
  warehouseId?: string
  onEventClick?: (event: QHSEEvent) => void
}

export default function QHSECalendarGridView({
  tenantId = 'default',
  warehouseId,
  onEventClick,
}: QHSECalendarGridViewProps) {
  const [currentDate, setCurrentDate] = useState(new Date())
  const [view, setView] = useState<'month' | 'week' | 'day'>('month')
  const [events, setEvents] = useState<QHSEEvent[]>([])
  const [selectedEvent, setSelectedEvent] = useState<QHSEEvent | null>(null)

  useEffect(() => {
    loadEvents()
  }, [currentDate, view, tenantId, warehouseId])

  const loadEvents = async () => {
    // In production, fetch from QHSE service
    // For now, generate sample events
    const mockEvents: QHSEEvent[] = []
    const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate()

    for (let day = 1; day <= daysInMonth; day++) {
      // Random events throughout month
      if (Math.random() > 0.7) {
        const eventDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day)
        const eventTypes: EventType[] = ['INCIDENT', 'AUDIT', 'TRAINING', 'INSPECTION', 'MEETING']
        const type = eventTypes[Math.floor(Math.random() * eventTypes.length)]
        
        mockEvents.push({
          id: `evt-${day}`,
          title: `${type} - ${day}`,
          type,
          date: eventDate,
          time: `${Math.floor(Math.random() * 12) + 8}:00`,
          severity: type === 'INCIDENT' ? (['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'] as Severity[])[Math.floor(Math.random() * 4)] : undefined,
          status: eventDate < new Date() ? 'COMPLETED' : 'SCHEDULED',
          assignedTo: `Employee ${Math.floor(Math.random() * 10) + 1}`,
          location: warehouseId || 'Warehouse A',
        })
      }
    }

    setEvents(mockEvents)
  }

  const getDaysInMonth = () => {
    const year = currentDate.getFullYear()
    const month = currentDate.getMonth()
    const firstDay = new Date(year, month, 1)
    const lastDay = new Date(year, month + 1, 0)
    const daysInMonth = lastDay.getDate()
    const startingDayOfWeek = firstDay.getDay()

    return { daysInMonth, startingDayOfWeek }
  }

  const getEventsForDate = (date: Date) => {
    return events.filter(
      e =>
        e.date.getDate() === date.getDate() &&
        e.date.getMonth() === date.getMonth() &&
        e.date.getFullYear() === date.getFullYear()
    )
  }

  const getEventColor = (event: QHSEEvent) => {
    switch (event.type) {
      case 'INCIDENT':
        return event.severity === 'CRITICAL' || event.severity === 'HIGH'
          ? 'bg-red-100 border-red-500 text-red-700 dark:bg-red-900/30 dark:text-red-400'
          : 'bg-orange-100 border-orange-500 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'
      case 'AUDIT':
        return 'bg-purple-100 border-purple-500 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400'
      case 'TRAINING':
        return 'bg-blue-100 border-blue-500 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
      case 'INSPECTION':
        return 'bg-green-100 border-green-500 text-green-700 dark:bg-green-900/30 dark:text-green-400'
      case 'MEETING':
        return 'bg-gray-100 border-gray-500 text-gray-700 dark:bg-gray-700/30 dark:text-gray-400'
    }
  }

  const { daysInMonth, startingDayOfWeek } = getDaysInMonth()
  const monthName = currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })

  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <button
            onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1))}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
          >
            <i className="ri-arrow-left-s-line text-xl text-gray-600 dark:text-gray-400" />
          </button>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            {monthName}
          </h3>
          <button
            onClick={() => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1))}
            className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
          >
            <i className="ri-arrow-right-s-line text-xl text-gray-600 dark:text-gray-400" />
          </button>
        </div>

        <div className="flex items-center gap-2">
          {(['month', 'week', 'day'] as const).map((v) => (
            <button
              key={v}
              onClick={() => setView(v)}
              className={`px-3 py-1.5 text-sm rounded-lg font-medium transition-colors ${
                view === v
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              {v.charAt(0).toUpperCase() + v.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Calendar Grid */}
      <div className="grid grid-cols-7 gap-2">
        {/* Day Headers */}
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day) => (
          <div
            key={day}
            className="text-center text-sm font-semibold text-gray-600 dark:text-gray-400 py-2"
          >
            {day}
          </div>
        ))}

        {/* Empty cells for days before month starts */}
        {Array.from({ length: startingDayOfWeek }, (_, i) => (
          <div key={`empty-${i}`} className="aspect-square" />
        ))}

        {/* Calendar Days */}
        {Array.from({ length: daysInMonth }, (_, i) => {
          const day = i + 1
          const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day)
          const dayEvents = getEventsForDate(date)
          const isToday =
            date.getDate() === new Date().getDate() &&
            date.getMonth() === new Date().getMonth() &&
            date.getFullYear() === new Date().getFullYear()

          return (
            <motion.div
              key={day}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: i * 0.01 }}
              className={`aspect-square border-2 rounded-lg p-2 hover:shadow-lg transition-all cursor-pointer ${
                isToday
                  ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
                  : 'border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600'
              }`}
            >
              <div className="text-sm font-semibold text-gray-900 dark:text-white mb-1">
                {day}
              </div>
              <div className="space-y-1 overflow-y-auto max-h-20">
                {dayEvents.slice(0, 3).map((event) => (
                  <motion.div
                    key={event.id}
                    onClick={(e) => {
                      e.stopPropagation()
                      setSelectedEvent(event)
                      onEventClick?.(event)
                    }}
                    whileHover={{ scale: 1.05 }}
                    className={`text-xs px-2 py-1 rounded border-l-2 ${getEventColor(event)} cursor-pointer truncate`}
                    title={event.title}
                  >
                    {event.title}
                  </motion.div>
                ))}
                {dayEvents.length > 3 && (
                  <div className="text-xs text-gray-500 dark:text-gray-400 text-center">
                    +{dayEvents.length - 3} more
                  </div>
                )}
              </div>
            </motion.div>
          )
        })}
      </div>

      {/* Event Detail Modal */}
      <AnimatePresence>
        {selectedEvent && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
            onClick={() => setSelectedEvent(null)}
          >
            <motion.div
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 20 }}
              className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl p-6 max-w-md w-full"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-start justify-between mb-4">
                <div>
                  <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                    {selectedEvent.title}
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400">
                    {selectedEvent.date.toLocaleDateString()} {selectedEvent.time || ''}
                  </p>
                </div>
                <button
                  onClick={() => setSelectedEvent(null)}
                  className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"
                >
                  <i className="ri-close-line text-xl text-gray-400" />
                </button>
              </div>

              <div className="space-y-3 text-sm">
                <div className="flex items-center gap-2">
                  <span className="font-semibold text-gray-700 dark:text-gray-300">Type:</span>
                  <span className={`px-2 py-1 rounded ${getEventColor(selectedEvent)}`}>
                    {selectedEvent.type}
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="font-semibold text-gray-700 dark:text-gray-300">Status:</span>
                  <span className="text-gray-600 dark:text-gray-400">{selectedEvent.status}</span>
                </div>
                {selectedEvent.severity && (
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-gray-700 dark:text-gray-300">Severity:</span>
                    <span className="text-gray-600 dark:text-gray-400">{selectedEvent.severity}</span>
                  </div>
                )}
                {selectedEvent.assignedTo && (
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-gray-700 dark:text-gray-300">Assigned:</span>
                    <span className="text-gray-600 dark:text-gray-400">{selectedEvent.assignedTo}</span>
                  </div>
                )}
                {selectedEvent.location && (
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-gray-700 dark:text-gray-300">Location:</span>
                    <span className="text-gray-600 dark:text-gray-400">{selectedEvent.location}</span>
                  </div>
                )}
                {selectedEvent.description && (
                  <div>
                    <span className="font-semibold text-gray-700 dark:text-gray-300">Description:</span>
                    <p className="text-gray-600 dark:text-gray-400 mt-1">{selectedEvent.description}</p>
                  </div>
                )}
              </div>

              <div className="mt-6 flex gap-2">
                <button
                  onClick={() => setSelectedEvent(null)}
                  className="flex-1 px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                >
                  Close
                </button>
                <button
                  onClick={() => {
                    // Edit event
                    console.log('Edit event:', selectedEvent.id)
                  }}
                  className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                  Edit Event
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Legend */}
      <div className="mt-6 flex flex-wrap gap-4 text-xs">
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded bg-red-500" />
          <span className="text-gray-600 dark:text-gray-400">Incident</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded bg-purple-500" />
          <span className="text-gray-600 dark:text-gray-400">Audit</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded bg-blue-500" />
          <span className="text-gray-600 dark:text-gray-400">Training</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded bg-green-500" />
          <span className="text-gray-600 dark:text-gray-400">Inspection</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded bg-gray-500" />
          <span className="text-gray-600 dark:text-gray-400">Meeting</span>
        </div>
      </div>
    </div>
  )
}

/**
 * Enhanced QHSE Status Board Component
 * Comprehensive QHSE status visualization
 * Much more comprehensive than source apps
 */

'use client'

import { useEffect, useState } from 'react'
import type { QHSEDashboard } from '@/types/qhse'

interface QHSEStatusBoardProps {
  tenantId?: string
  customerId?: string
  warehouseId?: string
  autoRefresh?: boolean
}

export default function QHSEStatusBoard({
  tenantId,
  customerId,
  warehouseId,
  autoRefresh = true,
}: QHSEStatusBoardProps) {
  const [dashboard, setDashboard] = useState<QHSEDashboard | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    fetchDashboard()

    if (autoRefresh) {
      const interval = setInterval(fetchDashboard, 30000) // 30 seconds
      return () => clearInterval(interval)
    }
  }, [tenantId, customerId, warehouseId, autoRefresh])

  const fetchDashboard = async () => {
    try {
      const params = new URLSearchParams()
      if (tenantId) params.append('tenantId', tenantId)
      if (customerId) params.append('customerId', customerId)
      if (warehouseId) params.append('warehouseId', warehouseId)

      const response = await fetch(`/api/qhse/reports?type=dashboard&${params.toString()}`)
      const data = await response.json()

      if (data.success) {
        setDashboard(data.data)
      }
    } catch (error) {
      console.error('Error fetching QHSE dashboard:', error)
    } finally {
      setLoading(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
      </div>
    )
  }

  if (!dashboard) {
    return (
      <div className="p-4 text-center text-gray-500">
        No QHSE data available
      </div>
    )
  }

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      {/* Safety Metrics */}
      <div className="bg-white rounded-lg shadow p-4 border-l-4 border-red-500">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-xs text-gray-500">TRIR</p>
            <p className="text-2xl font-bold text-gray-900 mt-1">
              {dashboard.safety.trir.toFixed(2)}
            </p>
          </div>
          <i className="ri-shield-check-line text-3xl text-red-500 opacity-50"></i>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow p-4 border-l-4 border-orange-500">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-xs text-gray-500">LTIFR</p>
            <p className="text-2xl font-bold text-gray-900 mt-1">
              {dashboard.safety.ltifr.toFixed(2)}
            </p>
          </div>
          <i className="ri-error-warning-line text-3xl text-orange-500 opacity-50"></i>
        </div>
      </div>

      {/* Compliance */}
      <div className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-xs text-gray-500">Compliance</p>
            <p className="text-2xl font-bold text-blue-600 mt-1">
              {dashboard.compliance.overallScore}%
            </p>
          </div>
          <i className="ri-shield-star-line text-3xl text-blue-500 opacity-50"></i>
        </div>
      </div>

      {/* Environmental */}
      <div className="bg-white rounded-lg shadow p-4 border-l-4 border-green-500">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-xs text-gray-500">Recycling Rate</p>
            <p className="text-2xl font-bold text-green-600 mt-1">
              {dashboard.environmental.recyclingRate.toFixed(1)}%
            </p>
          </div>
          <i className="ri-leaf-line text-3xl text-green-500 opacity-50"></i>
        </div>
      </div>
    </div>
  )
}

/**
 * 🛡️ ENHANCED REAL-TIME QHSE DASHBOARD
 * Comprehensive Quality, Health, Safety & Environment monitoring
 * Integrated with BlueDXP platform ecosystem:
 * - Multi-tenant architecture (tenant > customer > warehouse)
 * - Knowledge base integration with proper segregation
 * - Event bus for real-time updates and cross-module integration
 * - View context for role-based filtering
 * - More comprehensive than chemcheck-analysis
 */

'use client'

import React, { useEffect, useState, useCallback, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  FiShield, FiAlertTriangle, FiCheckCircle, FiClock, FiTrendingUp, 
  FiTrendingDown, FiActivity, FiBarChart, FiPieChart, FiRefreshCw,
  FiEye, FiPlus, FiDownload, FiFilter, FiCalendar, FiUsers,
  FiTarget, FiZap, FiLayers, FiHeart, FiDroplet, FiAward,
  FiFileText, FiMail, FiPhone, FiMapPin, FiSend, FiDatabase,
  FiLink, FiCpu, FiGlobe, FiTrendingUp as FiTrendUp
} from 'react-icons/fi'
// ViewContext will be provided by the app layout
// For now, we'll make it optional
// import { useViewContext } from '@/contexts/ViewContextProvider'
import QHSERiskHeatmap from './QHSERiskHeatmap'
import QHSEGamificationPanel from './QHSEGamificationPanel'
import QHSEComplianceMap from './QHSEComplianceMap'
import QHSESmartAlerts from './QHSESmartAlerts'
import type { 
  QHSEDashboard, 
  Incident, 
  Inspection,
  TrainingRecord,
  EnvironmentalMetric,
  SafetyMetric
} from '@/types/qhse'

interface RealTimeQHSEDashboardProps {
  tenantId?: string
  customerId?: string
  warehouseId?: string
  autoRefresh?: boolean
  refreshInterval?: number
  showKnowledgeBaseInsights?: boolean
  showCrossModuleConnections?: boolean
  showGamification?: boolean
  showComplianceMap?: boolean
  showSmartAlerts?: boolean
}

interface DashboardMetrics {
  incidents: {
    total: number
    byCategory: Record<string, number>
    bySeverity: Record<string, number>
    byStatus: Record<string, number>
    trends: {
      daily: number[]
      weekly: number[]
      monthly: number[]
    }
  }
  safety: {
    ltir: number
    trir: number
    nearMisses: number
    daysWithoutIncident: number
    safetyTrainingCompliance: number
  }
  environmental: {
    spills: number
    emissions: number
    wasteGenerated: number
    recyclingRate: number
    energyConsumption: number
  }
  quality: {
    nonConformances: number
    customerComplaints: number
    correctionEffectiveness: number
    auditScore: number
  }
  compliance: {
    overallScore: number
    byStandard: Record<string, number>
    overdueActions: number
    upcomingAudits: number
  }
}

interface KnowledgeBaseInsight {
  id: string
  title: string
  description: string
  category: string
  relevance: number
  source: string
  relatedEntities: string[]
}

interface CrossModuleConnection {
  module: string
  type: string
  count: number
  items: Array<{
    id: string
    title: string
    link: string
  }>
}

const RealTimeQHSEDashboard: React.FC<RealTimeQHSEDashboardProps> = ({
  tenantId,
  customerId,
  warehouseId,
  autoRefresh = true,
  refreshInterval = 30000,
  showKnowledgeBaseInsights = true,
  showCrossModuleConnections = true,
  showGamification = true,
  showComplianceMap = true,
  showSmartAlerts = true,
}) => {
  // ViewContext integration - will be provided by app layout
  // const viewContext = useViewContext()
  const [dashboard, setDashboard] = useState<QHSEDashboard | null>(null)
  const [metrics, setMetrics] = useState<DashboardMetrics | null>(null)
  const [recentIncidents, setRecentIncidents] = useState<Incident[]>([])
  const [recentInspections, setRecentInspections] = useState<Inspection[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [initialLoadComplete, setInitialLoadComplete] = useState(false)
  const [lastUpdate, setLastUpdate] = useState(new Date())
  const [selectedTimeframe, setSelectedTimeframe] = useState<'day' | 'week' | 'month' | 'quarter' | 'year'>('month')
  const [showNewIncidentModal, setShowNewIncidentModal] = useState(false)
  const [knowledgeBaseInsights, setKnowledgeBaseInsights] = useState<KnowledgeBaseInsight[]>([])
  const [crossModuleConnections, setCrossModuleConnections] = useState<CrossModuleConnection[]>([])
  const [activeTab, setActiveTab] = useState<'overview' | 'incidents' | 'inspections' | 'training' | 'environmental' | 'compliance'>('overview')
  const [smartAlerts, setSmartAlerts] = useState<any[]>([])
  const [intelligentInsights, setIntelligentInsights] = useState<any>(null)
  const [loadError, setLoadError] = useState<string | null>(null)

  // Get effective context IDs
  // ViewContext integration will be added when app layout provides it
  const effectiveTenantId = tenantId // || viewContext?.context?.tenantId
  const effectiveCustomerId = customerId // || (viewContext?.context?.customerFilter?.type === 'SINGLE' 
    // ? viewContext.context.customerFilter.customerIds?.[0] 
    // : undefined)
  const effectiveWarehouseId = warehouseId // || (viewContext?.context?.warehouseFilter?.type === 'SINGLE'
    // ? viewContext.context.warehouseFilter.warehouseIds?.[0]
    // : undefined)

  // Helper function to fetch with timeout
  const fetchWithTimeout = async (url: string, timeout = 10000): Promise<Response> => {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), timeout)

    try {
      const response = await fetch(url, { signal: controller.signal })
      clearTimeout(timeoutId)
      return response
    } catch (error) {
      clearTimeout(timeoutId)
      if (error instanceof Error && error.name === 'AbortError') {
        throw new Error(`Request timeout: ${url}`)
      }
      throw error
    }
  }

  // Helper function to safely fetch and parse JSON
  const safeFetch = async (url: string | null, timeout = 10000): Promise<any> => {
    if (!url) return null

    try {
      const response = await fetchWithTimeout(url, timeout)
      if (!response.ok) {
        console.warn(`API call failed: ${url} - ${response.status}`)
        return { success: false, error: `HTTP ${response.status}` }
      }
      return await response.json()
    } catch (error) {
      console.error(`Error fetching ${url}:`, error)
      return { success: false, error: error instanceof Error ? error.message : 'Unknown error' }
    }
  }

  // Load dashboard data with individual error handling
  const loadDashboardData = useCallback(async () => {
    setIsLoading(true)
    setLoadError(null)

    try {
      const params = new URLSearchParams()
      if (effectiveTenantId) params.append('tenantId', effectiveTenantId)
      if (effectiveCustomerId) params.append('customerId', effectiveCustomerId)
      if (effectiveWarehouseId) params.append('warehouseId', effectiveWarehouseId)
      params.append('timeframe', selectedTimeframe)

      // Fetch all data in parallel, but handle each independently
      // This way one failure doesn't break everything
      const [
        dashboardData,
        incidentsData,
        inspectionsData,
        metricsData,
        insightsData,
        connectionsData,
        intelligentData,
        alertsData
      ] = await Promise.allSettled([
        safeFetch(`/api/qhse/reports?type=dashboard&${params.toString()}`),
        safeFetch(`/api/qhse/incidents?status=investigating&limit=5&${params.toString()}`),
        safeFetch(`/api/qhse/inspections?status=in_progress&limit=5&${params.toString()}`),
        safeFetch(`/api/qhse/metrics?${params.toString()}`),
        showKnowledgeBaseInsights ? safeFetch(`/api/knowledge-base/search?category=qhse&limit=5&${params.toString()}`) : Promise.resolve(null),
        showCrossModuleConnections ? safeFetch(`/api/qhse/cross-module-connections?${params.toString()}`) : Promise.resolve(null),
        safeFetch(`/api/qhse/intelligent?type=all&${params.toString()}`),
        showSmartAlerts ? safeFetch(`/api/qhse/alerts?${params.toString()}`) : Promise.resolve(null),
      ])

      // Process each result independently
      const processResult = (result: PromiseSettledResult<any>, setter: (data: any) => void) => {
        if (result.status === 'fulfilled' && result.value?.success) {
          setter(result.value.data)
        }
      }

      processResult(dashboardData, setDashboard)
      processResult(incidentsData, (data) => setRecentIncidents(data || []))
      processResult(inspectionsData, (data) => setRecentInspections(data || []))
      processResult(metricsData, setMetrics)
      processResult(insightsData, (data) => setKnowledgeBaseInsights(data || []))
      processResult(connectionsData, (data) => setCrossModuleConnections(data || []))
      processResult(intelligentData, setIntelligentInsights)
      processResult(alertsData, (data) => setSmartAlerts(data || []))

      // Check if we got at least some data
      const hasData = dashboardData.status === 'fulfilled' && dashboardData.value?.success ||
                     metricsData.status === 'fulfilled' && metricsData.value?.success

      if (!hasData && !initialLoadComplete) {
        setLoadError('Unable to load dashboard data. Some services may be unavailable.')
      }

      setLastUpdate(new Date())
      setInitialLoadComplete(true)
    } catch (error) {
      console.error('Failed to load QHSE dashboard data:', error)
      setLoadError(error instanceof Error ? error.message : 'Failed to load dashboard data')
    } finally {
      setIsLoading(false)
    }
  }, [effectiveTenantId, effectiveCustomerId, effectiveWarehouseId, selectedTimeframe, showKnowledgeBaseInsights, showCrossModuleConnections, initialLoadComplete])

  // Auto-refresh
  useEffect(() => {
    loadDashboardData()

    if (autoRefresh) {
      const interval = setInterval(loadDashboardData, refreshInterval)
      return () => clearInterval(interval)
    }
  }, [loadDashboardData, autoRefresh, refreshInterval])

  // Timeout for initial load - if it takes more than 15 seconds, show what we have
  useEffect(() => {
    if (!initialLoadComplete) {
      const timeout = setTimeout(() => {
        if (!dashboard && !metrics) {
          setLoadError('Loading is taking longer than expected. Some data may be unavailable.')
          setInitialLoadComplete(true)
        }
      }, 15000)

      return () => clearTimeout(timeout)
    }
  }, [initialLoadComplete, dashboard, metrics])

  // Subscribe to event bus for real-time updates
  useEffect(() => {
    if (typeof window === 'undefined') return

    const eventSource = new EventSource('/api/realtime/qhse-events')

    eventSource.onmessage = (event) => {
      const data = JSON.parse(event.data)

      // Handle real-time updates
      if (data.type === 'qhse.incident.created' || data.type === 'qhse.incident.updated') {
        loadDashboardData()
      } else if (data.type === 'qhse.inspection.completed') {
        loadDashboardData()
      } else if (data.type === 'qhse.metric.updated') {
        loadDashboardData()
      }
    }

    eventSource.onerror = (error) => {
      console.error('EventSource error:', error)
    }

    return () => {
      eventSource.close()
    }
  }, [loadDashboardData])

  const refreshData = useCallback(async () => {
    await loadDashboardData()
  }, [loadDashboardData])

  const getSeverityColor = (severity: string) => {
    switch (severity.toLowerCase()) {
      case 'critical': return 'text-red-600 bg-red-100 dark:text-red-300 dark:bg-red-900'
      case 'high': return 'text-orange-600 bg-orange-100 dark:text-orange-300 dark:bg-orange-900'
      case 'medium': return 'text-yellow-600 bg-yellow-100 dark:text-yellow-300 dark:bg-yellow-900'
      case 'low': return 'text-green-600 bg-green-100 dark:text-green-300 dark:bg-green-900'
      default: return 'text-gray-600 bg-gray-100 dark:text-gray-300 dark:bg-gray-900'
    }
  }

  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case 'reported': return 'text-blue-600 bg-blue-100 dark:text-blue-300 dark:bg-blue-900'
      case 'investigating':
      case 'under_investigation': return 'text-orange-600 bg-orange-100 dark:text-orange-300 dark:bg-orange-900'
      case 'resolved': return 'text-green-600 bg-green-100 dark:text-green-300 dark:bg-green-900'
      case 'closed': return 'text-gray-600 bg-gray-100 dark:text-gray-300 dark:bg-gray-900'
      default: return 'text-gray-600 bg-gray-100 dark:text-gray-300 dark:bg-gray-900'
    }
  }

  const getContextDescription = useMemo(() => {
    const parts: string[] = []
    if (effectiveCustomerId) parts.push(`Customer: ${effectiveCustomerId}`)
    if (effectiveWarehouseId) parts.push(`Warehouse: ${effectiveWarehouseId}`)
    if (effectiveTenantId) parts.push(`Tenant: ${effectiveTenantId}`)
    return parts.length > 0 ? parts.join(' • ') : 'All Data'
  }, [effectiveTenantId, effectiveCustomerId, effectiveWarehouseId])

  const displayMetrics = useMemo(() => metrics || {
    incidents: {
      total: dashboard?.safety.openIncidents || 0,
      byCategory: {},
      bySeverity: {},
      byStatus: {},
      trends: { daily: [], weekly: [], monthly: [] }
    },
    safety: {
      ltir: dashboard?.safety.ltifr || 0,
      trir: dashboard?.safety.trir || 0,
      nearMisses: dashboard?.safety.nearMisses || 0,
      daysWithoutIncident: 0,
      safetyTrainingCompliance: dashboard?.health.trainingCompletionRate || 0
    },
    environmental: {
      spills: 0,
      emissions: 0,
      wasteGenerated: dashboard?.environmental.wasteReduction || 0,
      recyclingRate: dashboard?.environmental.recyclingRate || 0,
      energyConsumption: dashboard?.environmental.energyConsumption || 0
    },
    quality: {
      nonConformances: dashboard?.quality.ncrCount || 0,
      customerComplaints: dashboard?.quality.customerComplaints || 0,
      correctionEffectiveness: 0,
      auditScore: 0
    },
    compliance: {
      overallScore: dashboard?.compliance.overallScore || 0,
      byStandard: {},
      overdueActions: dashboard?.compliance.openFindings || 0,
      upcomingAudits: dashboard?.compliance.upcomingAudits || 0
    }
  }, [metrics, dashboard])

  // Show loading only on initial load, not if we have partial data
  if (isLoading && !initialLoadComplete && !dashboard && !metrics) {
    return (
      <div className="flex items-center justify-center min-h-[600px]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">Loading QHSE Dashboard...</p>
          <p className="mt-2 text-sm text-gray-500 dark:text-gray-500">This may take a few moments</p>
        </div>
      </div>
    )
  }

  // Show error state if initial load failed completely
  if (!initialLoadComplete && loadError && !dashboard && !metrics) {
    return (
      <div className="flex items-center justify-center min-h-[600px]">
        <div className="text-center max-w-md">
          <FiAlertTriangle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-2">Unable to Load Dashboard</h3>
          <p className="text-gray-600 dark:text-gray-400 mb-4">{loadError}</p>
          <button
            onClick={() => {
              setInitialLoadComplete(false)
              setLoadError(null)
              loadDashboardData()
            }}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6 p-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-gray-100 flex items-center gap-3">
            <FiShield className="w-8 h-8 text-blue-600" />
            QHSE Dashboard
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            Real-time Quality, Health, Safety & Environment monitoring
          </p>
          {getContextDescription && (
            <p className="text-sm text-gray-500 dark:text-gray-500 mt-1 flex items-center gap-2">
              <FiDatabase className="w-4 h-4" />
              {getContextDescription}
            </p>
          )}
          {loadError && (
            <div className="mt-2 flex items-center gap-2 text-amber-600 dark:text-amber-400 text-sm">
              <FiAlertTriangle className="w-4 h-4" />
              <span>Some data may be unavailable</span>
            </div>
          )}
        </div>

        <div className="flex items-center space-x-4 flex-wrap">
          <select
            value={selectedTimeframe}
            onChange={(e) => setSelectedTimeframe(e.target.value as any)}
            className="text-sm border rounded-lg px-3 py-2 dark:bg-gray-700 dark:border-gray-600"
          >
            <option value="day">Today</option>
            <option value="week">This Week</option>
            <option value="month">This Month</option>
            <option value="quarter">This Quarter</option>
            <option value="year">This Year</option>
          </select>

          <motion.a
            href="/qhse/statistics"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="relative flex items-center space-x-2 px-4 py-2.5 bg-gradient-to-r from-purple-600 to-purple-700 text-white rounded-xl hover:from-purple-700 hover:to-purple-800 transition-all duration-300 shadow-lg shadow-purple-500/30 hover:shadow-purple-500/50 overflow-hidden group"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/20 to-white/0 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000" />
            <FiBarChart className="w-4 h-4 relative z-10" />
            <span className="relative z-10 font-medium">Statistics Board</span>
          </motion.a>

          <motion.button
            onClick={() => setShowNewIncidentModal(true)}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="relative flex items-center space-x-2 px-4 py-2.5 bg-gradient-to-r from-red-600 to-red-700 text-white rounded-xl hover:from-red-700 hover:to-red-800 transition-all duration-300 shadow-lg shadow-red-500/30 hover:shadow-red-500/50 overflow-hidden group"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/20 to-white/0 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000" />
            <FiAlertTriangle className="w-4 h-4 relative z-10" />
            <span className="relative z-10 font-medium">Report Incident</span>
          </motion.button>

          <motion.button
            onClick={refreshData}
            disabled={isLoading}
            whileHover={{ scale: isLoading ? 1 : 1.05 }}
            whileTap={{ scale: isLoading ? 1 : 0.95 }}
            className="relative flex items-center space-x-2 px-3 py-2.5 bg-white/5 backdrop-blur-sm border border-cyan-500/30 text-cyan-400 rounded-xl hover:bg-cyan-500/10 hover:border-cyan-500/50 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 shadow-lg shadow-cyan-500/10 hover:shadow-cyan-500/20 overflow-hidden group"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-cyan-500/0 via-cyan-500/10 to-cyan-500/0 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000" />
            <motion.div
              animate={{ rotate: isLoading ? 360 : 0 }}
              transition={{ duration: 1, repeat: isLoading ? Infinity : 0, ease: "linear" }}
            >
              <FiRefreshCw className="w-4 h-4 relative z-10" />
            </motion.div>
            <span className="relative z-10 font-medium">Refresh</span>
          </motion.button>

          <div className="text-sm text-gray-500 dark:text-gray-400 flex items-center gap-2">
            <FiClock className="w-4 h-4" />
            Updated: {lastUpdate.toLocaleTimeString()}
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200 dark:border-gray-700">
        <nav className="flex space-x-8">
          {(['overview', 'incidents', 'inspections', 'training', 'environmental', 'compliance'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === tab
                  ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400 dark:hover:text-gray-300'
              }`}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)}
            </button>
          ))}
        </nav>
      </div>

      {/* Key Metrics Cards - Enhanced with Glassmorphism */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <motion.div
          initial={{ opacity: 0, y: 20, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          whileHover={{ scale: 1.02, y: -4 }}
          transition={{ type: "spring", stiffness: 300, damping: 20 }}
          className="relative overflow-hidden bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-red-500/20 shadow-xl shadow-red-500/10 hover:border-red-500/40 transition-all duration-300 group"
        >
          {/* Animated gradient background */}
          <div className="absolute inset-0 bg-gradient-to-br from-red-500/10 via-red-600/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

          {/* Pulse effect for critical incidents */}
          {displayMetrics.incidents.bySeverity?.critical > 0 && (
            <motion.div
              className="absolute top-2 right-2 w-3 h-3 bg-red-500 rounded-full"
              animate={{ scale: [1, 1.5, 1], opacity: [1, 0.5, 1] }}
              transition={{ duration: 2, repeat: Infinity }}
            />
          )}

          <div className="relative flex items-center justify-between z-10">
            <div>
              <p className="text-red-400 text-sm font-medium mb-1">Total Incidents</p>
              <motion.p 
                className="text-4xl font-bold bg-gradient-to-r from-red-400 to-red-600 bg-clip-text text-transparent mt-1"
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ delay: 0.2, type: "spring" }}
              >
                {displayMetrics.incidents.total}
              </motion.p>
              <p className="text-xs text-gray-400 mt-2 flex items-center gap-2">
                <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                {displayMetrics.incidents.bySeverity?.critical || 0} critical, {displayMetrics.incidents.bySeverity?.high || 0} high
              </p>
            </div>
            <motion.div
              animate={{ rotate: [0, 10, -10, 0] }}
              transition={{ duration: 2, repeat: Infinity, repeatDelay: 3 }}
            >
              <FiAlertTriangle className="w-12 h-12 text-red-400 group-hover:text-red-300 transition-colors" />
            </motion.div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          whileHover={{ scale: 1.02, y: -4 }}
          transition={{ delay: 0.1, type: "spring", stiffness: 300, damping: 20 }}
          className="relative overflow-hidden bg-white/5 backdrop-blur-xl rounded-2xl p-6 border border-green-500/20 shadow-xl shadow-green-500/10 hover:border-green-500/40 transition-all duration-300 group"
        >
          {/* Animated gradient background */}
          <div className="absolute inset-0 bg-gradient-to-br from-green-500/10 via-green-600/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />

          <div className="relative flex items-center justify-between z-10">
            <div>
              <p className="text-green-400 text-sm font-medium mb-1">Days Without Incident</p>
              <motion.p 
                className="text-4xl font-bold bg-gradient-to-r from-green-400 to-green-600 bg-clip-text text-transparent mt-1"
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ delay: 0.3, type: "spring" }}
              >
                {displayMetrics.safety.daysWithoutIncident}
              </motion.p>
              <div className="mt-2 w-full bg-white/10 rounded-full h-2 overflow-hidden">
                <motion.div
                  className="h-full bg-gradient-to-r from-green-400 to-green-600 rounded-full"
                  initial={{ width: 0 }}
                  animate={{ width: `${Math.min((displayMetrics.safety.daysWithoutIncident / 90) * 100, 100)}%` }}
                  transition={{ delay: 0.5, duration: 1, ease: "easeOut" }}
