/**
 * Predictive Analytics Component
 * Advanced forecasting and risk prediction visualization
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  LineChart, Line, AreaChart, Area, BarChart, Bar,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  ComposedChart, ReferenceLine
} from 'recharts'
import { predictiveAnalyticsService } from '@/lib/services/trade-compliance/predictiveAnalyticsService'
import type { Forecast, RiskPrediction, OptimizationRecommendation } from '@/lib/services/trade-compliance/predictiveAnalyticsService'

export default function PredictiveAnalytics() {
  const [forecasts, setForecasts] = useState<Forecast[]>([])
  const [riskPredictions, setRiskPredictions] = useState<RiskPrediction[]>([])
  const [optimizations, setOptimizations] = useState<OptimizationRecommendation[]>([])
  const [loading, setLoading] = useState(true)
  const [timeframe, setTimeframe] = useState<'7D' | '30D' | '90D' | '1Y'>('30D')
  const [optimizationType, setOptimizationType] = useState<'cost' | 'time' | 'risk' | 'efficiency'>('cost')

  useEffect(() => {
    loadPredictiveData()
  }, [timeframe, optimizationType])

  const loadPredictiveData = async () => {
    setLoading(true)
    try {
      // Fetch historical data with timeout
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), 8000) // 8 second timeout

      try {
        const recordsRes = await fetch('/api/trade-compliance/records', { signal: controller.signal })
        clearTimeout(timeoutId)
        const recordsData = await recordsRes.json()
        const records = recordsData.success ? recordsData.records || [] : []

      // Generate historical data for forecasting
      const historicalData = generateHistoricalData(records)

      // Generate forecasts
      const forecastData = await predictiveAnalyticsService.forecastMetrics(historicalData, timeframe)
      setForecasts(forecastData)

      // Generate risk predictions
      const risks = await predictiveAnalyticsService.predictRisks(records)
      setRiskPredictions(risks)

        // Generate optimizations
        const opts = await predictiveAnalyticsService.optimize(records, optimizationType)
        setOptimizations(opts)
      } catch (fetchError: any) {
        clearTimeout(timeoutId)
        if (fetchError.name === 'AbortError') {
          console.error('Request timeout: Predictive analytics fetch took too long')
          // Set empty data to prevent infinite loading
          setForecasts([])
          setRiskPredictions([])
          setOptimizations([])
        } else {
          throw fetchError
        }
      }
    } catch (error) {
      console.error('Error loading predictive data:', error)
      // Set empty data on error
      setForecasts([])
      setRiskPredictions([])
      setOptimizations([])
    } finally {
      setLoading(false)
    }
  }

  const generateHistoricalData = (records: any[]) => {
    const days = timeframe === '7D' ? 7 : timeframe === '30D' ? 30 : timeframe === '90D' ? 90 : 365
    const data = []
    
    for (let i = days - 1; i >= 0; i--) {
      const date = new Date()
      date.setDate(date.getDate() - i)
      data.push({
        date: date.toISOString().split('T')[0],
        recordCount: Math.floor(records.length / days) + Math.floor(Math.random() * 5),
        avgComplianceScore: 75 + Math.random() * 20,
        totalCosts: (records.length * 100000 / days) + Math.random() * 50000,
      })
    }
    
    return data
  }

  const getRiskColor = (level: string) => {
    switch (level) {
      case 'critical': return 'text-red-400 bg-red-500/20'
      case 'high': return 'text-orange-400 bg-orange-500/20'
      case 'medium': return 'text-yellow-400 bg-yellow-500/20'
      default: return 'text-green-400 bg-green-500/20'
    }
  }

  const getTrendIcon = (trend: string) => {
    switch (trend) {
      case 'increasing': return 'ri-arrow-up-line text-green-400'
      case 'decreasing': return 'ri-arrow-down-line text-red-400'
      default: return 'ri-arrow-right-line text-[#9ca3af]'
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-[#9ca3af] text-sm">Loading predictive analytics...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Forecasts */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4 sm:p-6 hover:border-cyan-500/50 transition-all"
      >
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-white flex items-center gap-2">
            <i className="ri-line-chart-line text-cyan-400"></i>
            Forecasts
          </h3>
          <select
            value={timeframe}
            onChange={(e) => setTimeframe(e.target.value as any)}
            className="px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-sm text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
          >
            <option value="7D">7 Days</option>
            <option value="30D">30 Days</option>
            <option value="90D">90 Days</option>
            <option value="1Y">1 Year</option>
          </select>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          {forecasts.map((forecast, idx) => (
            <div key={idx} className="bg-white/5 border border-white/10 rounded-lg p-4 hover:border-cyan-500/50 transition-all">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-[#9ca3af]">{forecast.metric}</span>
                <i className={getTrendIcon(forecast.trend)}></i>
              </div>
              <div className="text-2xl font-bold text-white mb-1">
                {forecast.currentValue.toLocaleString()}
              </div>
              <div className="flex items-center gap-2 text-sm">
                <span className={forecast.changePercent > 0 ? 'text-green-400' : 'text-red-400'}>
                  {forecast.changePercent > 0 ? '+' : ''}{forecast.changePercent.toFixed(1)}%
                </span>
                <span className="text-[#9ca3af]">• {forecast.confidence * 100}% confidence</span>
              </div>
            </div>
          ))}
        </div>

        {/* Forecast Chart */}
        {forecasts.length > 0 && (
          <ResponsiveContainer width="100%" height={300}>
            <ComposedChart data={forecasts[0].forecastedValues}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis dataKey="date" stroke="#9ca3af" fontSize={12} />
              <YAxis yAxisId="left" stroke="#9ca3af" fontSize={12} />
              <YAxis yAxisId="right" orientation="right" stroke="#9ca3af" fontSize={12} />
              <Tooltip 
                contentStyle={{ 
                  backgroundColor: '#1f2937', 
                  border: '1px solid rgba(255, 255, 255, 0.1)',
                  borderRadius: '8px',
                  color: '#ffffff'
                }} 
              />
              <Legend wrapperStyle={{ color: '#9ca3af' }} />
              <Area
                yAxisId="left"
                type="monotone"
                dataKey="value"
                fill="#06b6d4"
                fillOpacity={0.3}
                stroke="#06b6d4"
                name="Forecasted Value"
              />
              <Line
                yAxisId="right"
                type="monotone"
                dataKey="confidence"
                stroke="#10b981"
                strokeWidth={2}
                name="Confidence"
              />
              <ReferenceLine yAxisId="left" y={forecasts[0].currentValue} stroke="#ef4444" strokeDasharray="5 5" label="Current" />
            </ComposedChart>
          </ResponsiveContainer>
        )}
      </motion.div>

      {/* Risk Predictions */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-xl p-4 sm:p-6 hover:border-cyan-500/50 transition-all"
      >
        <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
          <i className="ri-alert-line text-cyan-400"></i>
          Risk Predictions
        </h3>
        <div className="space-y-3">
          {riskPredictions.slice(0, 5).map((risk, idx) => (
            <div
              key={idx}
              className="border border-white/10 rounded-lg p-4 hover:border-red-500/30 transition-colors bg-white/5"
            >
              <div className="flex items-start justify-between mb-2">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`px-2 py-1 rounded text-xs font-medium ${getRiskColor(risk.riskLevel)}`}>
                      {risk.riskLevel.toUpperCase()}
                    </span>
                    <span className="text-sm font-medium text-white">{risk.riskType} Risk</span>
                    <span className="text-xs text-[#9ca3af]">• {risk.probability * 100}% probability</span>
                  </div>
                  <p className="text-sm text-[#9ca3af] mb-2">Record: {risk.recordId}</p>
                  <div className="text-xs text-[#9ca3af] mb-2">
                    <strong className="text-white">Factors:</strong> {risk.factors.join(', ')}
                  </div>
                  <div className="text-xs text-[#9ca3af]">
                    <strong className="text-white">Mitigation:</strong> {risk.mitigationStrategies.join('; ')}
                  </div>
                </div>
                <div className="text-right">
                  <div className="text-sm font-medium text-white">{risk.timeframe}</div>
                  <div className="text-xs text-[#9ca3af]">{risk.confidence * 100}% confidence</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </motion.div>

      {/* Optimization Recommendations */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="bg-green-500/10 border border-green-500/30 rounded-xl p-4 sm:p-6"
      >
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-white flex items-center gap-2">
            <i className="ri-lightbulb-line text-green-400"></i>
            Optimization Recommendations
          </h3>
          <select
            value={optimizationType}
            onChange={(e) => setOptimizationType(e.target.value as any)}
            className="px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-sm text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500"
          >
            <option value="cost">Cost</option>
            <option value="time">Time</option>
            <option value="risk">Risk</option>
            <option value="efficiency">Efficiency</option>
          </select>
        </div>
        
        <div className="space-y-4">
          {optimizations.map((opt, idx) => (
            <div
              key={idx}
              className="bg-white/5 border border-white/10 rounded-lg p-4 hover:border-green-500/50 transition-all"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex-1">
                  <h4 className="font-semibold text-white mb-1">{opt.type.toUpperCase()} Optimization</h4>
                  <p className="text-sm text-[#9ca3af] mb-2">{opt.method}</p>
                </div>
                <div className="text-right">
                  <div className="text-2xl font-bold text-green-400">{opt.improvement}%</div>
                  <div className="text-xs text-[#9ca3af]">Improvement</div>
                </div>
              </div>
              
              <div className="grid grid-cols-2 gap-4 mb-3">
                <div>
                  <div className="text-xs text-[#9ca3af] mb-1">Current</div>
                  <div className="text-lg font-semibold text-white">
                    {opt.currentValue.toLocaleString()}
                    {opt.type === 'cost' && ' SAR'}
                    {opt.type === 'time' && ' days'}
                  </div>
                </div>
                <div>
                  <div className="text-xs text-[#9ca3af] mb-1">Optimized</div>
                  <div className="text-lg font-semibold text-green-400">
                    {opt.optimizedValue.toLocaleString()}
                    {opt.type === 'cost' && ' SAR'}
                    {opt.type === 'time' && ' days'}
                  </div>
                </div>
              </div>

              {opt.estimatedSavings && (
                <div className="bg-green-500/20 border border-green-500/30 rounded p-2 mb-3">
                  <div className="text-sm font-medium text-green-400">
                    Estimated Savings: {opt.estimatedSavings.toLocaleString()} SAR
                  </div>
                </div>
              )}

              <div className="border-t border-white/10 pt-3">
                <div className="text-xs font-medium text-white mb-2">Implementation Steps:</div>
                <ul className="space-y-1">
                  {opt.steps.map((step, stepIdx) => (
                    <li key={stepIdx} className="text-xs text-[#9ca3af] flex items-start gap-2">
                      <i className="ri-checkbox-circle-line text-green-400 mt-0.5"></i>
                      {step}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          ))}
        </div>
      </motion.div>
    </div>
  )
}

/**
 * Network Graph Visualization Component
 * 
 * Interactive network graph for logistics network modeling
 * Modern, professional, sexy UI with full drill-down capabilities
 */

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Network,
  MapPin,
  Warehouse,
  Truck,
  Ship,
  Plane,
  Train,
  Zap,
  Settings,
  Maximize2,
  Minimize2,
  ZoomIn,
  ZoomOut,
  RotateCw,
  Filter,
  Search,
  X,
} from 'lucide-react'
import type { NetworkNode, NetworkLink, NetworkModel } from '@/lib/services/transportation'

interface NetworkGraphVisualizationProps {
  model: NetworkModel
  onNodeClick?: (node: NetworkNode) => void
  onLinkClick?: (link: NetworkLink) => void
  interactive?: boolean
}

export default function NetworkGraphVisualization({
  model,
  onNodeClick,
  onLinkClick,
  interactive = true,
}: NetworkGraphVisualizationProps) {
  const [selectedNode, setSelectedNode] = useState<NetworkNode | null>(null)
  const [selectedLink, setSelectedLink] = useState<NetworkLink | null>(null)
  const [zoom, setZoom] = useState(1)
  const [pan, setPan] = useState({ x: 0, y: 0 })
  const [isDragging, setIsDragging] = useState(false)
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 })
  const [filterType, setFilterType] = useState<string>('ALL')
  const [searchQuery, setSearchQuery] = useState('')
  const [isFullscreen, setIsFullscreen] = useState(false)
  const svgRef = useRef<SVGSVGElement>(null)

  // Filter nodes and links with safety check
  const filteredNodes = (model?.nodes || []).filter((node) => {
    if (filterType !== 'ALL' && node.type !== filterType) return false
    if (searchQuery && !node.name.toLowerCase().includes(searchQuery.toLowerCase())) return false
    return true
  })

  const filteredLinks = (model?.links || []).filter((link) => {
    return filteredNodes.some((n) => n.id === link.fromNodeId) &&
      filteredNodes.some((n) => n.id === link.toNodeId)
  })

  // Calculate node positions (simplified force-directed layout)
  const nodePositions = useRef<Map<string, { x: number; y: number }>>(new Map())

  useEffect(() => {
    if (!model) return
    // Initialize positions
    filteredNodes.forEach((node, idx) => {
      if (!nodePositions.current.has(node.id)) {
        const angle = (idx / filteredNodes.length) * 2 * Math.PI
        const radius = 200
        nodePositions.current.set(node.id, {
          x: Math.cos(angle) * radius + 400,
          y: Math.sin(angle) * radius + 300,
        })
      }
    })
  }, [filteredNodes])

  const handleNodeClick = (node: NetworkNode) => {
    setSelectedNode(node)
    setSelectedLink(null)
    if (onNodeClick) onNodeClick(node)
  }

  const handleLinkClick = (link: NetworkLink) => {
    setSelectedLink(link)
    setSelectedNode(null)
    if (onLinkClick) onLinkClick(link)
  }

  const handleZoom = (delta: number) => {
    setZoom((prev) => Math.max(0.5, Math.min(3, prev + delta)))
  }

  const handlePanStart = (e: React.MouseEvent) => {
    if (e.button === 0) {
      setIsDragging(true)
      setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y })
    }
  }

  const handlePanMove = (e: React.MouseEvent) => {
    if (isDragging) {
      setPan({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y,
      })
    }
  }

  const handlePanEnd = () => {
    setIsDragging(false)
  }

  const getNodeIcon = (type: NetworkNode['type']) => {
    switch (type) {
      case 'WAREHOUSE':
      case 'DISTRIBUTION_CENTER':
        return Warehouse
      case 'HUB':
        return Network
      case 'PORT':
        return Ship
      case 'AIRPORT':
        return Plane
      default:
        return MapPin
    }
  }

  const getNodeColor = (type: NetworkNode['type']) => {
    switch (type) {
      case 'WAREHOUSE':
        return 'bg-blue-500'
      case 'DISTRIBUTION_CENTER':
        return 'bg-green-500'
      case 'HUB':
        return 'bg-purple-500'
      case 'CROSS_DOCK':
        return 'bg-orange-500'
      case 'PORT':
        return 'bg-cyan-500'
      case 'AIRPORT':
        return 'bg-pink-500'
      default:
        return 'bg-gray-500'
    }
  }

  return (
    <div
      className={`bg-white dark:bg-gray-800 rounded-xl shadow-2xl border border-gray-200 dark:border-gray-700 ${
        isFullscreen ? 'fixed inset-4 z-50' : 'relative'
      }`}
    >
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-blue-500 to-purple-500 flex items-center justify-center">
            <Network className="w-5 h-5 text-white" />
          </div>
          <div>
            <h3 className="text-lg font-bold">{model?.name || 'Network Model'}</h3>
            <p className="text-sm text-gray-500">
              {filteredNodes.length} nodes • {filteredLinks.length} links
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search nodes..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 pr-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-sm"
            />
          </div>

          {/* Filter */}
          <select
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
            className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-sm"
          >
            <option value="ALL">All Types</option>
            <option value="WAREHOUSE">Warehouses</option>
            <option value="DISTRIBUTION_CENTER">DCs</option>
            <option value="HUB">Hubs</option>
            <option value="PORT">Ports</option>
            <option value="AIRPORT">Airports</option>
          </select>

          {/* Zoom Controls */}
          <div className="flex items-center gap-1 border border-gray-300 dark:border-gray-600 rounded-lg p-1">
            <button
              onClick={() => handleZoom(-0.1)}
              className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700"
            >
              <ZoomOut className="w-4 h-4" />
            </button>
            <span className="px-2 text-sm">{Math.round(zoom * 100)}%</span>
            <button
              onClick={() => handleZoom(0.1)}
              className="p-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700"
            >
              <ZoomIn className="w-4 h-4" />
            </button>
          </div>

          <button
            onClick={() => setIsFullscreen(!isFullscreen)}
            className="p-2 rounded-lg bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 transition"
          >
            {isFullscreen ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
          </button>
        </div>
      </div>

      {/* Graph Canvas */}
      <div className="relative h-[600px] overflow-hidden bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800">
        <svg
          ref={svgRef}
          className="w-full h-full cursor-move"
          onMouseDown={handlePanStart}
          onMouseMove={handlePanMove}
          onMouseUp={handlePanEnd}
          onMouseLeave={handlePanEnd}
        >
          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`}>
            {/* Links */}
            {filteredLinks.map((link) => {
              const fromNode = filteredNodes.find((n) => n.id === link.fromNodeId)
              const toNode = filteredNodes.find((n) => n.id === link.toNodeId)
              if (!fromNode || !toNode) return null

              const fromPos = nodePositions.current.get(fromNode.id) || { x: 0, y: 0 }
              const toPos = nodePositions.current.get(toNode.id) || { x: 0, y: 0 }

              return (
                <g key={link.id}>
                  <line
                    x1={fromPos.x}
                    y1={fromPos.y}
                    x2={toPos.x}
                    y2={toPos.y}
                    stroke={selectedLink?.id === link.id ? '#3b82f6' : '#94a3b8'}
                    strokeWidth={selectedLink?.id === link.id ? 3 : 2}
                    strokeDasharray={link.mode === 'RAIL' ? '5,5' : '0'}
                    onClick={() => handleLinkClick(link)}
                    className="cursor-pointer"
                  />
                  {/* Link label */}
                  <text
                    x={(fromPos.x + toPos.x) / 2}
                    y={(fromPos.y + toPos.y) / 2 - 5}
                    textAnchor="middle"
                    className="text-xs fill-gray-600 dark:fill-gray-400 pointer-events-none"
                  >
                    {link.distance}km
                  </text>
                </g>
              )
            })}

            {/* Nodes */}
            {filteredNodes.map((node) => {
              const pos = nodePositions.current.get(node.id) || { x: 0, y: 0 }
              const Icon = getNodeIcon(node.type)
              const isSelected = selectedNode?.id === node.id

              return (
                <g key={node.id}>
                  <circle
                    cx={pos.x}
                    cy={pos.y}
                    r={isSelected ? 25 : 20}
                    fill={isSelected ? '#3b82f6' : getNodeColor(node.type).replace('bg-', '#').replace('-500', '')}
                    stroke={isSelected ? '#1e40af' : '#fff'}
                    strokeWidth={isSelected ? 3 : 2}
                    onClick={() => handleNodeClick(node)}
                    className="cursor-pointer transition-all"
                  />
                  <foreignObject
                    x={pos.x - 60}
                    y={pos.y + 30}
                    width="120"
                    height="40"
                    className="pointer-events-none"
                  >
                    <div className="text-center">
                      <div className="text-xs font-medium text-gray-700 dark:text-gray-300 truncate">
                        {node.name}
                      </div>
                      <div className="text-xs text-gray-500">{node.type}</div>
                    </div>
                  </foreignObject>
                </g>
              )
            })}
          </g>
        </svg>
      </div>

      {/* Side Panel - Node/Link Details */}
      <AnimatePresence>
        {(selectedNode || selectedLink) && (
          <motion.div
            initial={{ x: 400 }}
            animate={{ x: 0 }}
            exit={{ x: 400 }}
            className="absolute right-0 top-0 bottom-0 w-96 bg-white dark:bg-gray-800 border-l border-gray-200 dark:border-gray-700 shadow-2xl overflow-y-auto"
          >
            <div className="p-6">
              <div className="flex items-center justify-between mb-4">
                <h4 className="text-lg font-bold">
                  {selectedNode ? 'Node Details' : 'Link Details'}
                </h4>
                <button
                  onClick={() => {
                    setSelectedNode(null)
                    setSelectedLink(null)
                  }}
                  className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              {selectedNode && (
                <div className="space-y-4">
                  <div>
                    <label className="text-xs text-gray-500">Name</label>
                    <p className="font-medium">{selectedNode.name}</p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Type</label>
                    <p className="font-medium">{selectedNode.type}</p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Location</label>
                    <p className="font-medium">
                      {selectedNode.location?.address?.city}, {selectedNode.location?.address?.country}
                    </p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Capacity</label>
                    <p className="font-medium">
                      Storage: {selectedNode.capacity?.storage}m³ • Throughput: {selectedNode.capacity?.throughput}/day
                    </p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Costs</label>
                    <p className="font-medium">
                      Fixed: ${selectedNode.costs?.fixed} • Variable: ${selectedNode.costs?.variable}/unit
                    </p>
                  </div>
                </div>
              )}

              {selectedLink && (
                <div className="space-y-4">
                  <div>
                    <label className="text-xs text-gray-500">Mode</label>
                    <p className="font-medium">{selectedLink.mode}</p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Distance</label>
                    <p className="font-medium">{selectedLink.distance} km</p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Transit Time</label>
                    <p className="font-medium">{selectedLink.transitTime} hours</p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Cost</label>
                    <p className="font-medium">${selectedLink.cost}/unit</p>
                  </div>
                  <div>
                    <label className="text-xs text-gray-500">Reliability</label>
                    <p className="font-medium">{selectedLink.reliability}%</p>
                  </div>
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

/**
 * Claims Visualization Component
 * Displays extracted claims with validation status
 */

'use client'

import { useEffect, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Loader2, FileText, CheckCircle2, XCircle, AlertCircle, Search } from 'lucide-react'
import type { ExtractedClaim } from '@/lib/services/truth-engine'

interface ClaimsVisualizationProps {
  tenantId: string
  entityType?: string
  entityId?: string
}

export function ClaimsVisualization({ tenantId, entityType, entityId }: ClaimsVisualizationProps) {
  const [claims, setClaims] = useState<ExtractedClaim[]>([])
  const [statistics, setStatistics] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [searchText, setSearchText] = useState('')

  const fetchClaims = async () => {
    if (!entityType || !entityId) {
      setError('Entity type and ID are required')
      return
    }

    setLoading(true)
    setError(null)

    try {
      const response = await fetch(
        `/api/truth-engine/claims?entityType=${entityType}&entityId=${entityId}`
      )
      if (!response.ok) throw new Error('Failed to fetch claims')

      const data = await response.json()
      setClaims(data.claims || [])
    } catch (err: any) {
      setError(err.message || 'Failed to load claims')
    } finally {
      setLoading(false)
    }
  }

  const fetchStatistics = async () => {
    setLoading(true)
    try {
      const response = await fetch('/api/truth-engine/claims?statistics=true')
      if (!response.ok) throw new Error('Failed to fetch statistics')

      const data = await response.json()
      setStatistics(data)
    } catch (err: any) {
      setError(err.message || 'Failed to load statistics')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (entityType && entityId) {
      fetchClaims()
    }
    fetchStatistics()
  }, [entityType, entityId])

  const filteredClaims = claims.filter(
    (claim) =>
      !searchText ||
      claim.text.toLowerCase().includes(searchText.toLowerCase()) ||
      claim.type.toLowerCase().includes(searchText.toLowerCase())
  )

  const getStatusIcon = (status?: string) => {
    switch (status) {
      case 'verified':
        return <CheckCircle2 className="h-4 w-4 text-green-500" />
      case 'disputed':
        return <XCircle className="h-4 w-4 text-red-500" />
      case 'false':
        return <XCircle className="h-4 w-4 text-destructive" />
      default:
        return <AlertCircle className="h-4 w-4 text-yellow-500" />
    }
  }

  const getStatusBadge = (status?: string) => {
    switch (status) {
      case 'verified':
        return <Badge variant="default" className="bg-green-500">Verified</Badge>
      case 'disputed':
        return <Badge variant="destructive">Disputed</Badge>
      case 'false':
        return <Badge variant="destructive">False</Badge>
      default:
        return <Badge variant="secondary">Unverified</Badge>
    }
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <FileText className="h-5 w-5" />
          Extracted Claims
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <Tabs defaultValue="claims" className="w-full">
          <TabsList>
            <TabsTrigger value="claims">Claims</TabsTrigger>
            <TabsTrigger value="statistics">Statistics</TabsTrigger>
          </TabsList>

          <TabsContent value="claims" className="space-y-4">
            {/* Search */}
            <div className="flex gap-2">
              <Input
                placeholder="Search claims..."
                value={searchText}
                onChange={(e) => setSearchText(e.target.value)}
              />
              {entityType && entityId && (
                <Button onClick={fetchClaims} disabled={loading} variant="outline">
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
                </Button>
              )}
            </div>

            {error && (
              <div className="p-4 bg-destructive/10 text-destructive rounded-md">{error}</div>
            )}

            {/* Claims List */}
            {loading ? (
              <div className="flex items-center justify-center h-64">
                <Loader2 className="h-8 w-8 animate-spin" />
              </div>
            ) : filteredClaims.length > 0 ? (
              <div className="space-y-3">
                {filteredClaims.map((claim) => (
                  <div
                    key={claim.id}
                    className="p-4 border rounded-lg hover:bg-muted transition-colors"
                  >
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1 space-y-2">
                        <div className="flex items-center gap-2">
                          {getStatusIcon(claim.verificationStatus)}
                          <span className="font-semibold">{claim.text}</span>
                        </div>
                        <div className="flex gap-2 flex-wrap">
                          <Badge variant="outline">{claim.type}</Badge>
                          {getStatusBadge(claim.verificationStatus)}
                          <Badge variant="secondary">
                            {Math.round(claim.confidence * 100)}% confidence
                          </Badge>
                        </div>
                        {claim.entities && claim.entities.length > 0 && (
                          <div className="text-sm text-muted-foreground">
                            Entities: {claim.entities.map((e) => e.text).join(', ')}
                          </div>
                        )}
                        {claim.evidenceLinks && claim.evidenceLinks.length > 0 && (
                          <div className="text-sm text-muted-foreground">
                            {claim.evidenceLinks.length} evidence link(s)
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center text-muted-foreground py-8">
                {entityType && entityId
                  ? 'No claims found for this entity.'
                  : 'Enter entity type and ID to view claims.'}
              </div>
            )}
          </TabsContent>

          <TabsContent value="statistics" className="space-y-4">
            {statistics ? (
              <div className="space-y-4">
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <Card>
                    <CardContent className="pt-6">
                      <div className="text-2xl font-bold">{statistics.total}</div>
                      <div className="text-sm text-muted-foreground">Total Claims</div>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardContent className="pt-6">
                      <div className="text-2xl font-bold">
                        {Math.round(statistics.averageConfidence * 100)}%
                      </div>
                      <div className="text-sm text-muted-foreground">Avg Confidence</div>
                    </CardContent>
                  </Card>
                </div>

                <div className="space-y-4">
                  <div>
                    <h4 className="font-semibold mb-2">By Type</h4>
                    <div className="space-y-2">
                      {Object.entries(statistics.byType || {}).map(([type, count]) => (
                        <div key={type} className="flex justify-between">
                          <span>{type}</span>
                          <Badge variant="outline">{count as number}</Badge>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div>
                    <h4 className="font-semibold mb-2">By Status</h4>
                    <div className="space-y-2">
                      {Object.entries(statistics.byStatus || {}).map(([status, count]) => (
                        <div key={status} className="flex justify-between">
                          <span>{status}</span>
                          <Badge variant="outline">{count as number}</Badge>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="flex items-center justify-center h-64">
                <Loader2 className="h-8 w-8 animate-spin" />
              </div>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}

/**
 * Knowledge Graph Visualization Component
 * Visualizes entity relationships and claims in an interactive graph
 */

'use client'

import { useEffect, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Badge } from '@/components/ui/badge'
import { Loader2, Network, Search, ZoomIn, ZoomOut } from 'lucide-react'
import type { KnowledgeGraphNode, KnowledgeGraphEdge } from '@/lib/services/truth-engine'

interface KnowledgeGraphVisualizationProps {
  tenantId: string
  initialEntityId?: string
  initialEntityType?: string
}

export function KnowledgeGraphVisualization({
  tenantId,
  initialEntityId,
  initialEntityType,
}: KnowledgeGraphVisualizationProps) {
  const [nodes, setNodes] = useState<KnowledgeGraphNode[]>([])
  const [edges, setEdges] = useState<KnowledgeGraphEdge[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [entityId, setEntityId] = useState(initialEntityId || '')
  const [entityType, setEntityType] = useState(initialEntityType || '')
  const [depth, setDepth] = useState(2)

  const fetchGraph = async () => {
    if (!entityId && !entityType) {
      setError('Please provide entityId or entityType')
      return
    }

    setLoading(true)
    setError(null)

    try {
      const params = new URLSearchParams({
        tenantId,
        depth: depth.toString(),
      })
      if (entityId) params.append('entityId', entityId)
      if (entityType) params.append('entityType', entityType)

      const response = await fetch(`/api/truth-engine/knowledge-graph?${params}`)
      if (!response.ok) throw new Error('Failed to fetch graph')

      const data = await response.json()
      setNodes(data.nodes || [])
      setEdges(data.edges || [])
    } catch (err: any) {
      setError(err.message || 'Failed to load graph')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (initialEntityId || initialEntityType) {
      fetchGraph()
    }
  }, [])

  const nodeTypes = Array.from(new Set(nodes.map((n) => n.type)))
  const edgeTypes = Array.from(new Set(edges.map((e) => e.type)))

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Network className="h-5 w-5" />
          Knowledge Graph
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Search Controls */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Input
            placeholder="Entity ID"
            value={entityId}
            onChange={(e) => setEntityId(e.target.value)}
          />
          <Input
            placeholder="Entity Type"
            value={entityType}
            onChange={(e) => setEntityType(e.target.value)}
          />
          <Select value={depth.toString()} onValueChange={(v) => setDepth(parseInt(v))}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="1">Depth 1</SelectItem>
              <SelectItem value="2">Depth 2</SelectItem>
              <SelectItem value="3">Depth 3</SelectItem>
              <SelectItem value="4">Depth 4</SelectItem>
              <SelectItem value="5">Depth 5</SelectItem>
            </SelectContent>
          </Select>
          <Button onClick={fetchGraph} disabled={loading}>
            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
            Search
          </Button>
        </div>

        {error && (
          <div className="p-4 bg-destructive/10 text-destructive rounded-md">{error}</div>
        )}

        {/* Graph Visualization */}
        {loading ? (
          <div className="flex items-center justify-center h-64">
            <Loader2 className="h-8 w-8 animate-spin" />
          </div>
        ) : nodes.length > 0 ? (
          <div className="space-y-4">
            {/* Graph Stats */}
            <div className="flex gap-4 flex-wrap">
              <Badge variant="outline">{nodes.length} Nodes</Badge>
              <Badge variant="outline">{edges.length} Edges</Badge>
              <Badge variant="outline">{nodeTypes.length} Node Types</Badge>
              <Badge variant="outline">{edgeTypes.length} Edge Types</Badge>
            </div>

            {/* Node Types Legend */}
            <div className="space-y-2">
              <h4 className="text-sm font-semibold">Node Types:</h4>
              <div className="flex gap-2 flex-wrap">
                {nodeTypes.map((type) => (
                  <Badge key={type} variant="secondary">
                    {type}
                  </Badge>
                ))}
              </div>
            </div>

            {/* Simple Graph Visualization (in production, use D3.js or vis.js) */}
            <div className="border rounded-lg p-4 bg-muted/50 min-h-[400px] overflow-auto">
              <div className="space-y-2">
                {nodes.map((node) => (
                  <div
                    key={node.id}
                    className="p-3 bg-background border rounded-md hover:bg-muted transition-colors"
                  >
                    <div className="flex items-center justify-between">
                      <div>
                        <div className="font-semibold">{node.label}</div>
                        <div className="text-sm text-muted-foreground">{node.type}</div>
                      </div>
                      {node.confidence !== undefined && (
                        <Badge variant={node.confidence > 0.7 ? 'default' : 'secondary'}>
                          {Math.round(node.confidence * 100)}%
                        </Badge>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Edges List */}
            {edges.length > 0 && (
              <div className="space-y-2">
                <h4 className="text-sm font-semibold">Relationships:</h4>
                <div className="space-y-1">
                  {edges.slice(0, 10).map((edge) => {
                    const sourceNode = nodes.find((n) => n.id === edge.source)
                    const targetNode = nodes.find((n) => n.id === edge.target)
                    return (
                      <div key={edge.id} className="text-sm p-2 bg-muted rounded">
                        <span className="font-semibold">{sourceNode?.label || edge.source}</span>
                        <span className="mx-2 text-muted-foreground">→</span>
                        <span className="font-semibold">{targetNode?.label || edge.target}</span>
                        <Badge variant="outline" className="ml-2">
                          {edge.type}
                        </Badge>
                      </div>
                    )
                  })}
                  {edges.length > 10 && (
                    <div className="text-sm text-muted-foreground">
                      ... and {edges.length - 10} more relationships
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        ) : (
          <div className="text-center text-muted-foreground py-8">
            No graph data. Enter entity ID or type and click Search.
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * Enhanced Truth Timeline Component
 * Advanced UI with export, filtering, and visualization
 */

'use client'

import { useState, useEffect } from 'react'
import { TruthTimeline, TruthEvent } from '@/types/truth-engine'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Calendar } from '@/components/ui/calendar'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { CalendarIcon, Download, Filter, Search, Eye, AlertTriangle, CheckCircle2 } from 'lucide-react'
import { format } from 'date-fns'

interface TruthTimelineEnhancedProps {
  entityType: string
  entityId: string
  initialTimeline?: TruthTimeline
}

export function TruthTimelineEnhanced({ entityType, entityId, initialTimeline }: TruthTimelineEnhancedProps) {
  const [timeline, setTimeline] = useState<TruthTimeline | null>(initialTimeline || null)
  const [loading, setLoading] = useState(!initialTimeline)
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedEventTypes, setSelectedEventTypes] = useState<string[]>([])
  const [dateFrom, setDateFrom] = useState<Date | undefined>()
  const [dateTo, setDateTo] = useState<Date | undefined>()
  const [minConfidence, setMinConfidence] = useState<number | undefined>()
  const [showDisputed, setShowDisputed] = useState(true)

  useEffect(() => {
    if (!initialTimeline) {
      loadTimeline()
    }
  }, [entityType, entityId])

  const loadTimeline = async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams({
        entityType,
        entityId,
        tenantId: 'current', // Would get from context
      })

      if (dateFrom) params.append('dateFrom', dateFrom.toISOString())
      if (dateTo) params.append('dateTo', dateTo.toISOString())
      if (minConfidence !== undefined) params.append('minConfidence', minConfidence.toString())
      if (selectedEventTypes.length > 0) params.append('eventTypes', selectedEventTypes.join(','))

      const response = await fetch(`/api/truth-engine/events?${params}`)
      const data = await response.json()

      if (data.success) {
        setTimeline(data.timeline)
      }
    } catch (error) {
      console.error('Error loading timeline:', error)
    } finally {
      setLoading(false)
    }
  }

  const exportTimeline = async (format: 'json' | 'csv' | 'pdf') => {
    if (!timeline) return

    try {
      const response = await fetch('/api/truth-engine/export', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          entityType,
          entityId,
          format,
          timeline,
        }),
      })

      const blob = await response.blob()
      const url = window.URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `truth-timeline-${entityType}-${entityId}.${format}`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      window.URL.revokeObjectURL(url)
    } catch (error) {
      console.error('Error exporting timeline:', error)
    }
  }

  const filteredEvents = timeline?.events.filter(event => {
    if (searchTerm && !event.eventType.toLowerCase().includes(searchTerm.toLowerCase()) &&
        !event.actor.name?.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false
    }

    if (selectedEventTypes.length > 0 && !selectedEventTypes.includes(event.eventType)) {
      return false
    }

    if (dateFrom && new Date(event.happenedAt) < dateFrom) {
      return false
    }

    if (dateTo && new Date(event.happenedAt) > dateTo) {
      return false
    }

    if (minConfidence !== undefined && event.confidenceScore < minConfidence) {
      return false
    }

    if (!showDisputed && event.status === 'disputed') {
      return false
    }

    return true
  }) || []

  const eventTypes = Array.from(new Set(timeline?.events.map(e => e.eventType) || []))

  if (loading) {
    return <div className="p-4">Loading timeline...</div>
  }

  if (!timeline) {
    return <div className="p-4">No timeline data available</div>
  }

  return (
    <div className="space-y-4">
      {/* Header with Export */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle>Truth Timeline: {entityType} {entityId}</CardTitle>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={() => exportTimeline('json')}>
                <Download className="h-4 w-4 mr-2" />
                Export JSON
              </Button>
              <Button variant="outline" size="sm" onClick={() => exportTimeline('csv')}>
                <Download className="h-4 w-4 mr-2" />
                Export CSV
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-4 mb-4">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search events..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <Select
              value={selectedEventTypes.join(',')}
              onValueChange={(value) => setSelectedEventTypes(value ? value.split(',') : [])}
            >
              <SelectTrigger className="w-[200px]">
                <SelectValue placeholder="Filter by type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">All Types</SelectItem>
                {eventTypes.map(type => (
                  <SelectItem key={type} value={type}>{type}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm">
                  <CalendarIcon className="h-4 w-4 mr-2" />
                  Date Range
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0">
                <Calendar
                  mode="range"
                  selected={{ from: dateFrom, to: dateTo }}
                  onSelect={(range) => {
                    setDateFrom(range?.from)
                    setDateTo(range?.to)
                  }}
                />
              </PopoverContent>
            </Popover>
            <Input
              type="number"
              placeholder="Min Confidence"
              value={minConfidence || ''}
              onChange={(e) => setMinConfidence(e.target.value ? parseFloat(e.target.value) : undefined)}
              className="w-[150px]"
              min="0"
              max="1"
              step="0.1"
            />
          </div>

          {/* Summary Stats */}
          <div className="grid grid-cols-4 gap-4 mb-4">
            <div className="text-center p-2 bg-muted rounded">
              <div className="text-2xl font-bold">{filteredEvents.length}</div>
              <div className="text-sm text-muted-foreground">Events</div>
            </div>
            <div className="text-center p-2 bg-muted rounded">
              <div className="text-2xl font-bold">{(timeline.confidenceScore * 100).toFixed(0)}%</div>
              <div className="text-sm text-muted-foreground">Confidence</div>
            </div>
            <div className="text-center p-2 bg-muted rounded">
              <div className="text-2xl font-bold">{timeline.evidence.length}</div>
              <div className="text-sm text-muted-foreground">Evidence Items</div>
            </div>
            <div className="text-center p-2 bg-muted rounded">
              <div className="text-2xl font-bold">{timeline.gaps.length}</div>
              <div className="text-sm text-muted-foreground">Gaps</div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Events Timeline */}
      <div className="space-y-2">
        {filteredEvents.map((event, index) => (
          <Card key={event.id} className="hover:bg-muted/50 transition-colors">
            <CardContent className="p-4">
              <div className="flex items-start gap-4">
                <div className="flex-shrink-0">
                  {event.status === 'disputed' ? (
                    <AlertTriangle className="h-5 w-5 text-yellow-500" />
                  ) : (
                    <CheckCircle2 className="h-5 w-5 text-green-500" />
                  )}
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <Badge variant="outline">{event.eventType}</Badge>
                    <span className="text-sm text-muted-foreground">
                      {format(new Date(event.happenedAt), 'PPpp')}
                    </span>
                    <Badge variant={event.confidenceScore >= 0.8 ? 'default' : 'secondary'}>
                      {(event.confidenceScore * 100).toFixed(0)}% confidence
                    </Badge>
                  </div>
                  <div className="text-sm mb-2">
                    <strong>{event.actor.name}</strong> ({event.actor.role})
                  </div>
                  {event.evidenceLinks.length > 0 && (
                    <div className="text-sm text-muted-foreground">
                      {event.evidenceLinks.length} evidence item(s)
                    </div>
                  )}
                </div>
                <Button variant="ghost" size="sm" onClick={() => window.open(`/truth-timeline/${entityType}/${entityId}?event=${event.id}`, '_blank')}>
                  <Eye className="h-4 w-4" />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Gaps */}
      {timeline.gaps.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Timeline Gaps</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {timeline.gaps.map(gap => (
                <div key={gap.id} className="p-3 bg-yellow-50 dark:bg-yellow-900/20 rounded border border-yellow-200 dark:border-yellow-800">
                  <div className="flex items-center gap-2 mb-1">
                    <AlertTriangle className="h-4 w-4 text-yellow-600" />
                    <Badge variant="outline" className={gap.severity === 'HIGH' ? 'border-red-500' : ''}>
                      {gap.severity}
                    </Badge>
                  </div>
                  <div className="text-sm font-medium mb-1">{gap.description}</div>
                  {gap.suggestedActions && gap.suggestedActions.length > 0 && (
                    <div className="text-sm text-muted-foreground">
                      <strong>Suggested:</strong> {gap.suggestedActions.join(', ')}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

'use client'

import { motion, useInView } from 'framer-motion'
import { useRef, useState, useEffect } from 'react'
import * as d3 from 'd3'

interface NetworkVisualizationProps {
  language: 'en' | 'ar'
}

export default function NetworkVisualization({ language }: NetworkVisualizationProps) {
  const ref = useRef(null)
  const svgRef = useRef<SVGSVGElement>(null)
  const isInView = useInView(ref, { once: true, margin: '-100px' })
  const [selectedNode, setSelectedNode] = useState<any>(null)
  const [activeView, setActiveView] = useState<'standard' | 'compliance' | 'bottlenecks' | 'digital-twin'>('standard')
  const [nodeConnections, setNodeConnections] = useState(0)

  const views = {
    standard: language === 'en' ? 'Standard Flow' : 'التدفق القياسي',
    compliance: language === 'en' ? 'Compliance Focus' : 'تركيز الامتثال',
    bottlenecks: language === 'en' ? 'Bottleneck Analysis' : 'تحليل الاختناقات',
    'digital-twin': language === 'en' ? 'Digital Twin' : 'التوأم الرقمي',
  }

  useEffect(() => {
    if (!svgRef.current || !isInView) return

    const width = svgRef.current.clientWidth
    const height = svgRef.current.clientHeight

    // Clear previous content
    d3.select(svgRef.current).selectAll('*').remove()

    const svg = d3.select(svgRef.current)
      .attr('width', width)
      .attr('height', height)

    // Create nodes
    const nodes = [
      { id: 'core', label: 'Bluedxp Core', group: 1, size: 30 },
      { id: 'wms', label: 'WMS', group: 2, size: 20 },
      { id: 'tms', label: 'TMS', group: 2, size: 20 },
      { id: 'qms', label: 'QMS', group: 2, size: 20 },
      { id: 'erp', label: 'ERP', group: 3, size: 15 },
      { id: 'ai', label: 'AI Engine', group: 1, size: 25 },
      { id: 'iot', label: 'IoT', group: 3, size: 15 },
      { id: 'analytics', label: 'Analytics', group: 2, size: 18 },
    ]

    const links = [
      { source: 'core', target: 'wms' },
      { source: 'core', target: 'tms' },
      { source: 'core', target: 'qms' },
      { source: 'core', target: 'ai' },
      { source: 'ai', target: 'analytics' },
      { source: 'wms', target: 'erp' },
      { source: 'tms', target: 'erp' },
      { source: 'qms', target: 'erp' },
      { source: 'wms', target: 'iot' },
      { source: 'tms', target: 'iot' },
    ]

    // Update node connections count when a node is selected
    if (selectedNode) {
      const count = links.filter((link: any) => 
        link.source.id === selectedNode.id || link.target.id === selectedNode.id
      ).length
      setNodeConnections(count)
    }

    const simulation = d3.forceSimulation(nodes as any)
      .force('link', d3.forceLink(links).id((d: any) => d.id).distance(100))
      .force('charge', d3.forceManyBody().strength(-300))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius((d: any) => d.size + 10))

    const colorScale = d3.scaleOrdinal()
      .domain([1, 2, 3])
      .range(['#05a4ff', '#00d4a8', '#8b5cf6'])

    // Draw links
    const link = svg.append('g')
      .selectAll('line')
      .data(links)
      .join('line')
      .attr('stroke', 'rgba(5, 164, 255, 0.3)')
      .attr('stroke-width', 2)

    // Draw nodes
    const node = svg.append('g')
      .selectAll('g')
      .data(nodes)
      .join('g')
      .call(d3.drag<any, any>()
        .on('start', dragstarted)
        .on('drag', dragged)
        .on('end', dragended) as any)

    node.append('circle')
      .attr('r', (d: any) => d.size)
      .attr('fill', (d: any) => colorScale(d.group) as string)
      .attr('stroke', '#fff')
      .attr('stroke-width', 3)
      .style('filter', 'drop-shadow(0 0 10px rgba(5, 164, 255, 0.5))')
      .style('cursor', 'pointer')
      .on('mouseover', function(event, d) {
        d3.select(this)
          .transition()
          .duration(200)
          .attr('r', (d: any) => d.size * 1.5)
          .style('filter', `drop-shadow(0 0 20px ${colorScale(d.group)})`)
      })
      .on('mouseout', function(event, d) {
        d3.select(this)
          .transition()
          .duration(200)
          .attr('r', (d: any) => d.size)
          .style('filter', 'drop-shadow(0 0 10px rgba(5, 164, 255, 0.5))')
      })
      .on('click', (event, d) => {
        setSelectedNode(d)
      })

    node.append('text')
      .text((d: any) => d.label)
      .attr('text-anchor', 'middle')
      .attr('dy', (d: any) => d.size + 20)
      .attr('fill', '#fff')
      .attr('font-size', '12px')
      .attr('font-weight', 'bold')

    function dragstarted(event: any) {
      if (!event.active) simulation.alphaTarget(0.3).restart()
      event.subject.fx = event.subject.x
      event.subject.fy = event.subject.y
    }

    function dragged(event: any) {
      event.subject.fx = event.x
      event.subject.fy = event.y
    }

    function dragended(event: any) {
      if (!event.active) simulation.alphaTarget(0)
      event.subject.fx = null
      event.subject.fy = null
    }

    simulation.on('tick', () => {
      link
        .attr('x1', (d: any) => d.source.x)
        .attr('y1', (d: any) => d.source.y)
        .attr('x2', (d: any) => d.target.x)
        .attr('y2', (d: any) => d.target.y)

      node.attr('transform', (d: any) => `translate(${d.x},${d.y})`)
    })

  }, [isInView])

  return (
    <section ref={ref} className="py-24 relative">
      <div className="container mx-auto px-4 sm:px-6 lg:px-10">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          animate={isInView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.6 }}
          className="text-center mb-16"
        >
          <h2 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-6">
            <span className="bg-gradient-to-r from-white via-[#05a4ff] to-[#00d4a8] bg-clip-text text-transparent">
              {language === 'en' ? 'Interactive Network Graph' : 'رسم بياني شبكي تفاعلي'}
            </span>
          </h2>
        </motion.div>

        <div className="flex justify-center gap-4 mb-8 flex-wrap">
          {Object.entries(views).map(([key, label]) => (
            <motion.button
              key={key}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={() => {
                setActiveView(key as typeof activeView)
                // Trigger graph re-render
                if (svgRef.current) {
                  const event = new Event('resize')
                  window.dispatchEvent(event)
                }
              }}
              className={`px-6 py-3 rounded-xl font-semibold transition-all ${
                activeView === key
                  ? 'bg-gradient-to-r from-[#05a4ff] to-[#0088d1] text-white shadow-xl shadow-[#05a4ff]/40'
                  : 'bg-white/5 border border-white/10 text-white/70 hover:bg-white/10'
              }`}
            >
              {label}
            </motion.button>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <div className="lg:col-span-3">
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={isInView ? { opacity: 1, scale: 1 } : {}}
              transition={{ duration: 0.8 }}
              className="bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-2xl border border-white/20 rounded-3xl overflow-hidden shadow-2xl"
              style={{ height: '600px' }}
            >
              <svg ref={svgRef} className="w-full h-full" />
            </motion.div>
          </div>

          {selectedNode && (
            <motion.div
              initial={{ opacity: 0, x: 30 }}
              animate={{ opacity: 1, x: 0 }}
              className="bg-gradient-to-br from-white/15 to-white/10 backdrop-blur-2xl border border-white/30 rounded-3xl p-6"
            >
              <h3 className="text-xl font-bold mb-4">{selectedNode.label}</h3>
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full bg-[#00d4a8]" />
                  <span className="text-sm text-white/80">Status: Online</span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full bg-[#05a4ff]" />
                  <span className="text-sm text-white/80">Connections: {nodeConnections}</span>
                </div>
              </div>
            </motion.div>
          )}
        </div>
      </div>
    </section>
  )
}

'use client'

import { motion, useInView } from 'framer-motion'
import { useRef, useState, useEffect } from 'react'

interface RealTimeDataFlowProps {
  language: 'en' | 'ar'
}

interface DataPacket {
  id: number
  x: number
  y: number
  targetX: number
  targetY: number
  color: string
  label: string
}

export default function RealTimeDataFlow({ language }: RealTimeDataFlowProps) {
  const ref = useRef(null)
  const isInView = useInView(ref, { once: true, margin: '-100px' })
  const [dataPackets, setDataPackets] = useState<DataPacket[]>([])

  const nodes = [
    { x: 10, y: 50, label: language === 'en' ? 'Source' : 'المصدر', color: '#05a4ff' },
    { x: 35, y: 25, label: language === 'en' ? 'Processing' : 'المعالجة', color: '#00d4a8' },
    { x: 35, y: 75, label: language === 'en' ? 'Validation' : 'التحقق', color: '#8b5cf6' },
    { x: 65, y: 50, label: language === 'en' ? 'AI Engine' : 'محرك الذكاء', color: '#f59e0b' },
    { x: 90, y: 50, label: language === 'en' ? 'Output' : 'المخرج', color: '#10b981' },
  ]

  useEffect(() => {
    const interval = setInterval(() => {
      setDataPackets(prev => {
        const updated = prev.map(packet => ({
          ...packet,
          x: packet.x + (packet.targetX - packet.x) * 0.1,
          y: packet.y + (packet.targetY - packet.y) * 0.1,
        })).filter(p => Math.abs(p.x - p.targetX) > 0.5)

        if (prev.length < 12) {
          const colors = ['#05a4ff', '#00d4a8', '#8b5cf6', '#f59e0b']
          updated.push({
            id: Date.now(),
            x: nodes[0].x,
            y: nodes[0].y,
            targetX: nodes[Math.floor(Math.random() * nodes.length)].x,
            targetY: nodes[Math.floor(Math.random() * nodes.length)].y,
            color: colors[Math.floor(Math.random() * colors.length)],
            label: 'Data',
          })
        }

        return updated
      })
    }, 500)

    return () => clearInterval(interval)
  }, [])

  return (
    <section ref={ref} className="py-24 relative">
      <div className="container mx-auto px-4 sm:px-6 lg:px-10">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          animate={isInView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.6 }}
          className="text-center mb-16"
        >
          <h2 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-6">
            <span className="bg-gradient-to-r from-white via-[#00d4a8] to-[#05a4ff] bg-clip-text text-transparent">
              {language === 'en' ? 'Real-Time Data Flow' : 'تدفق البيانات اللحظي'}
            </span>
          </h2>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={isInView ? { opacity: 1, scale: 1 } : {}}
          transition={{ duration: 0.8 }}
          className="relative bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-2xl border border-white/20 rounded-3xl overflow-hidden shadow-2xl"
          style={{ height: '600px' }}
        >
          <svg className="w-full h-full">
            {/* Nodes */}
            {nodes.map((node, index) => (
              <g key={index}>
                <motion.circle
                  cx={`${node.x}%`}
                  cy={`${node.y}%`}
                  r="40"
                  fill={`${node.color}40`}
                  stroke={node.color}
                  strokeWidth="3"
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ duration: 0.5, delay: index * 0.1 }}
                  style={{
                    filter: `drop-shadow(0 0 20px ${node.color})`,
                  }}
                />
                <text
                  x={`${node.x}%`}
                  y={`${node.y}%`}
                  textAnchor="middle"
                  dy=".3em"
                  fill="#fff"
                  fontSize="14"
                  fontWeight="bold"
                >
                  {node.label}
                </text>
              </g>
            ))}

            {/* Data packets */}
            {dataPackets.map((packet) => (
              <motion.circle
                key={packet.id}
                cx={`${packet.x}%`}
                cy={`${packet.y}%`}
                r="8"
                fill={packet.color}
                initial={{ scale: 0 }}
                animate={{ scale: [1, 1.3, 1] }}
                transition={{ duration: 1, repeat: Infinity }}
                style={{
                  filter: `drop-shadow(0 0 15px ${packet.color})`,
                }}
              />
            ))}

            {/* Connection lines */}
            {[[0,1], [0,2], [1,3], [2,3], [3,4]].map(([from, to], index) => (
              <motion.line
                key={index}
                x1={`${nodes[from].x}%`}
                y1={`${nodes[from].y}%`}
                x2={`${nodes[to].x}%`}
                y2={`${nodes[to].y}%`}
                stroke="rgba(5, 164, 255, 0.3)"
                strokeWidth="2"
                initial={{ pathLength: 0 }}
                animate={{ pathLength: 1 }}
                transition={{ duration: 1, delay: index * 0.2 }}
              />
            ))}
          </svg>

          <div className="absolute top-6 right-6 space-y-3">
            <div className="bg-[#0a0a0f]/90 backdrop-blur-xl border border-white/20 rounded-2xl p-4">
              <div className="text-xs text-white/60 mb-1">{language === 'en' ? 'Data Packets/sec' : 'حزم البيانات/ثانية'}</div>
              <div className="text-2xl font-bold text-[#00d4a8]">{dataPackets.length * 2}</div>
            </div>
            <div className="bg-[#0a0a0f]/90 backdrop-blur-xl border border-white/20 rounded-2xl p-4">
