            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  )
}

/**
 * AR Damage Visualizer Component
 * Augmented Reality overlay for damage visualization
 * Mind-blowing AR integration for damage assessment
 */

'use client'

import { useState, useRef, useEffect } from 'react'
import { motion } from 'framer-motion'

interface ARDamageVisualizerProps {
  imageUrl: string
  damageAnalysis?: {
    qualityIssues?: Array<{
      type: string
      severity: string
      location?: { x: number; y: number; width: number; height: number }
      confidence: number
    }>
    detectedObjects?: Array<{
      object: string
      confidence: number
      boundingBox?: { x: number; y: number; width: number; height: number }
    }>
  }
  onARInteraction?: (action: string, data: any) => void
}

export default function ARDamageVisualizer({
  imageUrl,
  damageAnalysis,
  onARInteraction,
}: ARDamageVisualizerProps) {
  const [arMode, setArMode] = useState<'overlay' | '3d' | 'annotations'>('overlay')
  const [selectedDamage, setSelectedDamage] = useState<number | null>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const imageRef = useRef<HTMLImageElement>(null)

  useEffect(() => {
    if (canvasRef.current && imageRef.current && damageAnalysis) {
      drawAROverlay()
    }
  }, [damageAnalysis, arMode, selectedDamage])

  const drawAROverlay = () => {
    const canvas = canvasRef.current
    const image = imageRef.current
    if (!canvas || !image) return

    const ctx = canvas.getContext('2d')
    if (!ctx) return

    // Set canvas size to match image
    canvas.width = image.width
    canvas.height = image.height

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height)

    // Draw damage overlays
    if (damageAnalysis?.qualityIssues) {
      damageAnalysis.qualityIssues.forEach((issue, idx) => {
        if (issue.location) {
          const { x, y, width, height } = issue.location

          // Color based on severity
          let color = '#3b82f6' // blue
          if (issue.severity === 'critical') color = '#ef4444' // red
          else if (issue.severity === 'high') color = '#f59e0b' // orange
          else if (issue.severity === 'medium') color = '#eab308' // yellow

          // Draw bounding box
          ctx.strokeStyle = color
          ctx.lineWidth = 3
          ctx.setLineDash([])
          ctx.strokeRect(x, y, width, height)

          // Draw semi-transparent fill
          ctx.fillStyle = color + '20'
          ctx.fillRect(x, y, width, height)

          // Draw label
          ctx.fillStyle = color
          ctx.font = 'bold 14px Arial'
          ctx.fillText(
            `${issue.type} (${issue.confidence}%)`,
            x,
            y - 5
          )

          // Highlight selected
          if (selectedDamage === idx) {
            ctx.strokeStyle = '#ffffff'
            ctx.lineWidth = 5
            ctx.setLineDash([10, 5])
            ctx.strokeRect(x - 5, y - 5, width + 10, height + 10)
          }
        }
      })
    }

    // Draw object detection overlays
    if (damageAnalysis?.detectedObjects && arMode === 'annotations') {
      damageAnalysis.detectedObjects.forEach((obj) => {
        if (obj.boundingBox) {
          const { x, y, width, height } = obj.boundingBox

          ctx.strokeStyle = '#10b981' // green
          ctx.lineWidth = 2
          ctx.setLineDash([5, 5])
          ctx.strokeRect(x, y, width, height)

          ctx.fillStyle = '#10b981'
          ctx.font = '12px Arial'
          ctx.fillText(
            `${obj.object} (${obj.confidence}%)`,
            x,
            y - 5
          )
        }
      })
    }
  }

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical':
        return 'bg-red-500'
      case 'high':
        return 'bg-orange-500'
      case 'medium':
        return 'bg-yellow-500'
      case 'low':
        return 'bg-blue-500'
      default:
        return 'bg-gray-500'
    }
  }

  return (
    <div className="space-y-4">
      {/* AR Mode Selector */}
      <div className="flex items-center gap-2 bg-white rounded-lg p-2 shadow">
        <button
          onClick={() => setArMode('overlay')}
          className={`px-4 py-2 rounded-lg transition-all ${
            arMode === 'overlay'
              ? 'bg-blue-600 text-white'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
        >
          <i className="ri-eye-line mr-2"></i>
          Overlay
        </button>
        <button
          onClick={() => setArMode('annotations')}
          className={`px-4 py-2 rounded-lg transition-all ${
            arMode === 'annotations'
              ? 'bg-blue-600 text-white'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
        >
          <i className="ri-file-list-3-line mr-2"></i>
          Annotations
        </button>
        <button
          onClick={() => setArMode('3d')}
          className={`px-4 py-2 rounded-lg transition-all ${
            arMode === '3d'
              ? 'bg-blue-600 text-white'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
        >
          <i className="ri-3d-line mr-2"></i>
          3D View
        </button>
      </div>

      {/* AR Visualization */}
      <div className="relative bg-gray-100 rounded-lg overflow-hidden">
        <img
          ref={imageRef}
          src={imageUrl}
          alt="Damage photo"
          className="w-full h-auto"
          onLoad={drawAROverlay}
        />
        <canvas
          ref={canvasRef}
          className="absolute top-0 left-0 w-full h-full pointer-events-none"
          style={{ imageRendering: 'pixelated' }}
        />
      </div>

      {/* Damage List */}
      {damageAnalysis?.qualityIssues && damageAnalysis.qualityIssues.length > 0 && (
        <div className="bg-white rounded-lg shadow-lg p-4">
          <h4 className="font-semibold mb-3">Detected Damage</h4>
          <div className="space-y-2">
            {damageAnalysis.qualityIssues.map((issue, idx) => (
              <motion.div
                key={idx}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: idx * 0.1 }}
                onClick={() => {
                  setSelectedDamage(idx)
                  onARInteraction?.('select', { issue, index: idx })
                }}
                className={`p-3 rounded-lg border-2 cursor-pointer transition-all ${
                  selectedDamage === idx
                    ? 'border-blue-500 bg-blue-50'
                    : 'border-gray-200 hover:border-gray-300'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className={`w-3 h-3 rounded-full ${getSeverityColor(issue.severity)}`}></div>
                    <div>
                      <p className="font-medium text-gray-900">{issue.type}</p>
                      <p className="text-sm text-gray-600 capitalize">{issue.severity} severity</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-semibold text-gray-900">{issue.confidence}%</p>
                    <p className="text-xs text-gray-500">Confidence</p>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      )}

      {/* AR Info */}
      <div className="bg-gradient-to-br from-purple-50 to-blue-50 rounded-lg p-4 border border-purple-200">
        <div className="flex items-center gap-2 mb-2">
          <i className="ri-augmented-reality-line text-purple-600 text-xl"></i>
          <h4 className="font-semibold text-gray-900">AR Mode Active</h4>
        </div>
        <p className="text-sm text-gray-600">
          Click on damage items in the list to highlight them in the AR overlay. 
          Use the mode selector to switch between overlay, annotations, and 3D views.
        </p>
      </div>
    </div>
  )
}

/**
 * 3D Damage Photo Viewer
 * Mind-blowing interactive 3D visualization of damage photos
 * Non-breaking: New component, doesn't affect existing code
 */

'use client'

import { useState, useRef, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { DamagePhoto } from '@/types/asn'

interface DamagePhotoViewer3DProps {
  photos: DamagePhoto[]
  damageAnalysis?: {
    qualityIssues?: Array<{
      type: string
      severity: string
      location?: { x: number; y: number; width: number; height: number }
      confidence: number
    }>
    detectedObjects?: Array<{
      object: string
      confidence: number
      boundingBox?: { x: number; y: number; width: number; height: number }
    }>
  }
  onPhotoChange?: (index: number) => void
  showAnnotations?: boolean
  showHeatmap?: boolean
}

export default function DamagePhotoViewer3D({
  photos,
  damageAnalysis,
  onPhotoChange,
  showAnnotations = true,
  showHeatmap = true,
}: DamagePhotoViewer3DProps) {
  const [currentIndex, setCurrentIndex] = useState(0)
  const [zoom, setZoom] = useState(1)
  const [rotation, setRotation] = useState({ x: 0, y: 0 })
  const [isDragging, setIsDragging] = useState(false)
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 })
  const canvasRef = useRef<HTMLCanvasElement>(null)

  const currentPhoto = photos[currentIndex]

  // Handle photo navigation
  const handlePrevious = () => {
    const newIndex = currentIndex > 0 ? currentIndex - 1 : photos.length - 1
    setCurrentIndex(newIndex)
    onPhotoChange?.(newIndex)
    resetView()
  }

  const handleNext = () => {
    const newIndex = currentIndex < photos.length - 1 ? currentIndex + 1 : 0
    setCurrentIndex(newIndex)
    onPhotoChange?.(newIndex)
    resetView()
  }

  const resetView = () => {
    setZoom(1)
    setRotation({ x: 0, y: 0 })
  }

  // Get severity color
  const getSeverityColor = (severity: string) => {
    switch (severity.toLowerCase()) {
      case 'critical':
        return 'rgba(220, 38, 38, 0.6)' // red
      case 'major':
        return 'rgba(239, 68, 68, 0.5)' // orange-red
      case 'moderate':
        return 'rgba(245, 158, 11, 0.4)' // yellow
      case 'minor':
        return 'rgba(34, 197, 94, 0.3)' // green
      default:
        return 'rgba(156, 163, 175, 0.3)' // gray
    }
  }

  return (
    <div className="relative w-full h-full bg-gradient-to-br from-gray-900 via-gray-800 to-gray-900 rounded-2xl overflow-hidden">
      {/* Main Viewer */}
      <div className="relative w-full h-full flex items-center justify-center">
        <AnimatePresence mode="wait">
          <motion.div
            key={currentIndex}
            initial={{ opacity: 0, scale: 0.9, rotateY: -15 }}
            animate={{ opacity: 1, scale: 1, rotateY: 0 }}
            exit={{ opacity: 0, scale: 0.9, rotateY: 15 }}
            transition={{ duration: 0.3 }}
            className="relative w-full h-full"
            style={{
              perspective: '1000px',
              transformStyle: 'preserve-3d',
            }}
          >
            {/* Photo Container with 3D Effect */}
            <motion.div
              className="relative w-full h-full"
              style={{
                transform: `
                  scale(${zoom})
                  rotateX(${rotation.x}deg)
                  rotateY(${rotation.y}deg)
                `,
                transformStyle: 'preserve-3d',
              }}
              drag
              dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
              onDragStart={() => setIsDragging(true)}
              onDragEnd={() => setIsDragging(false)}
            >
              {/* Photo */}
              <div className="relative w-full h-full rounded-xl overflow-hidden shadow-2xl">
                <img
                  src={currentPhoto.photoUrl}
                  alt={currentPhoto.caption || 'Damage photo'}
                  className="w-full h-full object-contain"
                  draggable={false}
                />

                {/* Heatmap Overlay */}
                {showHeatmap && damageAnalysis?.qualityIssues && (
                  <div className="absolute inset-0 pointer-events-none">
                    {damageAnalysis.qualityIssues.map((issue, idx) => (
                      <motion.div
                        key={idx}
                        initial={{ opacity: 0, scale: 0 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ delay: idx * 0.1 }}
                        className="absolute rounded-lg border-2 border-white/50"
                        style={{
                          left: `${issue.location?.x || 0}%`,
                          top: `${issue.location?.y || 0}%`,
                          width: `${issue.location?.width || 20}%`,
                          height: `${issue.location?.height || 20}%`,
                          backgroundColor: getSeverityColor(issue.severity),
                          boxShadow: `0 0 20px ${getSeverityColor(issue.severity)}`,
                        }}
                      >
                        <div className="absolute -top-8 left-0 bg-black/80 text-white px-2 py-1 rounded text-xs whitespace-nowrap">
                          {issue.type} ({issue.severity})
                        </div>
                      </motion.div>
                    ))}
                  </div>
                )}

                {/* Annotations */}
                {showAnnotations && damageAnalysis?.detectedObjects && (
                  <div className="absolute inset-0 pointer-events-none">
                    {damageAnalysis.detectedObjects.map((obj, idx) => (
                      <motion.div
                        key={idx}
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        transition={{ delay: idx * 0.05 }}
                        className="absolute"
                        style={{
                          left: `${obj.boundingBox?.x || 0}%`,
                          top: `${obj.boundingBox?.y || 0}%`,
                          width: `${obj.boundingBox?.width || 10}%`,
                          height: `${obj.boundingBox?.height || 10}%`,
                        }}
                      >
                        <div className="absolute inset-0 border-2 border-cyan-400 rounded">
                          <div className="absolute -top-6 left-0 bg-cyan-500/90 text-white px-2 py-1 rounded text-xs">
                            {obj.object} ({Math.round(obj.confidence)}%)
                          </div>
                        </div>
                      </motion.div>
                    ))}
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        </AnimatePresence>

        {/* Navigation Controls */}
        <div className="absolute inset-0 flex items-center justify-between pointer-events-none">
          <motion.button
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            onClick={handlePrevious}
            className="ml-4 p-3 bg-black/60 backdrop-blur-sm text-white rounded-full pointer-events-auto hover:bg-black/80 transition-colors"
          >
            <i className="ri-arrow-left-line text-2xl"></i>
          </motion.button>
          <motion.button
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            onClick={handleNext}
            className="mr-4 p-3 bg-black/60 backdrop-blur-sm text-white rounded-full pointer-events-auto hover:bg-black/80 transition-colors"
          >
            <i className="ri-arrow-right-line text-2xl"></i>
          </motion.button>
        </div>

        {/* Zoom Controls */}
        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-black/60 backdrop-blur-sm px-4 py-2 rounded-full pointer-events-auto">
          <button
            onClick={() => setZoom(Math.max(0.5, zoom - 0.1))}
            className="p-2 text-white hover:text-cyan-400 transition-colors"
          >
            <i className="ri-zoom-out-line"></i>
          </button>
          <span className="text-white text-sm min-w-[60px] text-center">
            {Math.round(zoom * 100)}%
          </span>
          <button
            onClick={() => setZoom(Math.min(3, zoom + 0.1))}
            className="p-2 text-white hover:text-cyan-400 transition-colors"
          >
            <i className="ri-zoom-in-line"></i>
          </button>
          <button
            onClick={resetView}
            className="p-2 text-white hover:text-cyan-400 transition-colors"
          >
            <i className="ri-refresh-line"></i>
          </button>
        </div>

        {/* Photo Counter */}
        <div className="absolute top-4 right-4 bg-black/60 backdrop-blur-sm text-white px-4 py-2 rounded-full text-sm">
          {currentIndex + 1} / {photos.length}
        </div>
      </div>

      {/* Thumbnail Strip */}
      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-4">
        <div className="flex gap-2 overflow-x-auto scrollbar-hide">
          {photos.map((photo, idx) => (
            <motion.button
              key={photo.id}
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={() => {
                setCurrentIndex(idx)
                onPhotoChange?.(idx)
                resetView()
              }}
              className={`flex-shrink-0 w-20 h-20 rounded-lg overflow-hidden border-2 transition-all ${
                idx === currentIndex
                  ? 'border-cyan-400 shadow-lg shadow-cyan-400/50'
                  : 'border-transparent opacity-60 hover:opacity-100'
              }`}
            >
              <img
                src={photo.thumbnailUrl || photo.photoUrl}
                alt={photo.caption || `Photo ${idx + 1}`}
                className="w-full h-full object-cover"
              />
            </motion.button>
          ))}
        </div>
      </div>

      {/* Analysis Summary */}
      {damageAnalysis && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="absolute top-4 left-4 bg-black/80 backdrop-blur-sm rounded-xl p-4 max-w-sm"
        >
          <h3 className="text-white font-semibold mb-2">AI Analysis</h3>
          <div className="space-y-2">
            {damageAnalysis.qualityIssues?.map((issue, idx) => (
              <div
                key={idx}
                className="flex items-center gap-2 text-sm"
              >
                <div
                  className="w-3 h-3 rounded-full"
                  style={{ backgroundColor: getSeverityColor(issue.severity) }}
                ></div>
                <span className="text-white/80">
                  {issue.type} - {issue.severity} ({Math.round(issue.confidence)}%)
                </span>
              </div>
            ))}
          </div>
        </motion.div>
      )}
    </div>
  )
}

/**
 * Learning Progress Tracker
 * Visual learning progress, pattern recognition stats, accuracy improvements
 * From UI/UX mocks - ensures all visualized features are implemented
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { LineChart, Line, AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts'

interface LearningProgressTrackerProps {
  tenantId?: string
  timeframe?: '7d' | '30d' | '90d' | 'all'
}

interface LearningMetrics {
  totalPatterns: number
  totalFeedback: number
  averageAccuracy: number
  accuracyImprovement: number
  patternsLearned: number
  rulesGenerated: number
  knowledgeBaseEntries: number
}

interface PatternStats {
  id: string
  name: string
  confidence: number
  accuracy: number
  occurrenceCount: number
  lastSeen: string
  trend: 'up' | 'down' | 'stable'
}

export default function LearningProgressTracker({
  tenantId,
  timeframe = '30d',
}: LearningProgressTrackerProps) {
  const [metrics, setMetrics] = useState<LearningMetrics | null>(null)
  const [patternStats, setPatternStats] = useState<PatternStats[]>([])
  const [accuracyHistory, setAccuracyHistory] = useState<Array<{ date: string; accuracy: number }>>([])
  const [ruleTimeline, setRuleTimeline] = useState<Array<{ date: string; rules: number }>>([])
  const [knowledgeGrowth, setKnowledgeGrowth] = useState<Array<{ date: string; entries: number }>>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadLearningData()
  }, [tenantId, timeframe])

  const loadLearningData = async () => {
    setLoading(true)
    try {
      // Fetch learning metrics
      const metricsRes = await fetch(`/api/ai/vision/learning/metrics?timeframe=${timeframe}&tenantId=${tenantId || ''}`)
      if (metricsRes.ok) {
        const data = await metricsRes.json()
        setMetrics(data.metrics)
        setPatternStats(data.patterns || [])
        setAccuracyHistory(data.accuracyHistory || [])
        setRuleTimeline(data.ruleTimeline || [])
        setKnowledgeGrowth(data.knowledgeGrowth || [])
      } else {
        // Fallback mock data for demonstration
        setMockData()
      }
    } catch (error) {
      console.error('Error loading learning data:', error)
      setMockData()
    } finally {
      setLoading(false)
    }
  }

  const setMockData = () => {
    setMetrics({
      totalPatterns: 45,
      totalFeedback: 128,
      averageAccuracy: 87.5,
      accuracyImprovement: 12.3,
      patternsLearned: 12,
      rulesGenerated: 8,
      knowledgeBaseEntries: 234,
    })

    setPatternStats([
      { id: '1', name: 'Corner Damage', confidence: 92, accuracy: 89, occurrenceCount: 45, lastSeen: '2025-01-15', trend: 'up' },
      { id: '2', name: 'Crush Damage', confidence: 88, accuracy: 85, occurrenceCount: 32, lastSeen: '2025-01-14', trend: 'up' },
      { id: '3', name: 'Water Damage', confidence: 85, accuracy: 82, occurrenceCount: 18, lastSeen: '2025-01-13', trend: 'stable' },
      { id: '4', name: 'Label Damage', confidence: 90, accuracy: 88, occurrenceCount: 28, lastSeen: '2025-01-12', trend: 'up' },
    ])

    // Generate historical data
    const days = timeframe === '7d' ? 7 : timeframe === '30d' ? 30 : 90
    const history = []
    const rules = []
    const knowledge = []
    
    for (let i = days; i >= 0; i--) {
      const date = new Date()
      date.setDate(date.getDate() - i)
      history.push({
        date: date.toISOString().split('T')[0],
        accuracy: 75 + Math.random() * 15 + (days - i) * 0.2,
      })
      rules.push({
        date: date.toISOString().split('T')[0],
        rules: Math.floor(Math.random() * 3) + (days - i) * 0.1,
      })
      knowledge.push({
        date: date.toISOString().split('T')[0],
        entries: 200 + Math.floor(Math.random() * 10) + (days - i) * 0.5,
      })
    }
    
    setAccuracyHistory(history)
    setRuleTimeline(rules)
    setKnowledgeGrowth(knowledge)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12">
        <i className="ri-loader-4-line animate-spin text-4xl text-blue-600"></i>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-bold text-gray-900">Self-Learning Progress</h3>
          <p className="text-sm text-gray-600">Pattern recognition, accuracy improvements, and knowledge growth</p>
        </div>
        <select
          value={timeframe}
          onChange={(e) => {
            const newTimeframe = e.target.value as any
            loadLearningData()
          }}
          className="px-4 py-2 border border-gray-300 rounded-lg"
        >
          <option value="7d">Last 7 Days</option>
          <option value="30d">Last 30 Days</option>
          <option value="90d">Last 90 Days</option>
          <option value="all">All Time</option>
        </select>
      </div>

      {/* Key Metrics */}
      {metrics && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-gradient-to-br from-blue-500 to-blue-600 rounded-lg p-6 text-white shadow-lg"
          >
            <div className="flex items-center justify-between mb-2">
              <i className="ri-brain-line text-2xl"></i>
              <span className="text-sm opacity-90">Patterns</span>
            </div>
            <div className="text-3xl font-bold">{metrics.totalPatterns}</div>
            <div className="text-sm opacity-90 mt-1">Learned</div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="bg-gradient-to-br from-green-500 to-green-600 rounded-lg p-6 text-white shadow-lg"
          >
            <div className="flex items-center justify-between mb-2">
              <i className="ri-target-line text-2xl"></i>
              <span className="text-sm opacity-90">Accuracy</span>
            </div>
            <div className="text-3xl font-bold">{metrics.averageAccuracy.toFixed(1)}%</div>
            <div className="text-sm opacity-90 mt-1">
              +{metrics.accuracyImprovement.toFixed(1)}% improvement
            </div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
            className="bg-gradient-to-br from-purple-500 to-purple-600 rounded-lg p-6 text-white shadow-lg"
          >
            <div className="flex items-center justify-between mb-2">
              <i className="ri-file-list-3-line text-2xl"></i>
              <span className="text-sm opacity-90">Rules</span>
            </div>
            <div className="text-3xl font-bold">{metrics.rulesGenerated}</div>
            <div className="text-sm opacity-90 mt-1">Auto-generated</div>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="bg-gradient-to-br from-orange-500 to-orange-600 rounded-lg p-6 text-white shadow-lg"
          >
            <div className="flex items-center justify-between mb-2">
              <i className="ri-database-2-line text-2xl"></i>
              <span className="text-sm opacity-90">Knowledge</span>
            </div>
            <div className="text-3xl font-bold">{metrics.knowledgeBaseEntries}</div>
            <div className="text-sm opacity-90 mt-1">Entries</div>
          </motion.div>
        </div>
      )}

      {/* Accuracy Improvements Over Time */}
      {accuracyHistory.length > 0 && (
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h4 className="text-lg font-semibold mb-4">Accuracy Improvements Over Time</h4>
          <ResponsiveContainer width="100%" height={300}>
            <AreaChart data={accuracyHistory}>
              <defs>
                <linearGradient id="colorAccuracy" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis domain={[0, 100]} />
              <Tooltip />
              <Area
                type="monotone"
                dataKey="accuracy"
                stroke="#3b82f6"
                fillOpacity={1}
                fill="url(#colorAccuracy)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Pattern Recognition Stats */}
      {patternStats.length > 0 && (
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h4 className="text-lg font-semibold mb-4">Pattern Recognition Stats</h4>
          <div className="space-y-3">
            {patternStats.map((pattern, idx) => (
              <motion.div
                key={pattern.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: idx * 0.1 }}
                className="p-4 bg-gray-50 rounded-lg"
              >
                <div className="flex items-center justify-between mb-2">
                  <div>
                    <h5 className="font-semibold text-gray-900">{pattern.name}</h5>
                    <p className="text-sm text-gray-600">
                      Seen {pattern.occurrenceCount} times • Last: {pattern.lastSeen}
                    </p>
                  </div>
                  <div className="text-right">
                    <div className="flex items-center gap-2">
                      <span className="text-lg font-bold text-gray-900">{pattern.accuracy}%</span>
                      {pattern.trend === 'up' && (
                        <i className="ri-arrow-up-line text-green-600"></i>
                      )}
                      {pattern.trend === 'down' && (
                        <i className="ri-arrow-down-line text-red-600"></i>
                      )}
                      {pattern.trend === 'stable' && (
                        <i className="ri-arrow-right-line text-gray-600"></i>
                      )}
                    </div>
                    <p className="text-xs text-gray-500">Accuracy</p>
                  </div>
                </div>
                <div className="flex items-center gap-4 mt-2">
                  <div className="flex-1">
                    <div className="flex items-center justify-between text-xs text-gray-600 mb-1">
                      <span>Confidence</span>
                      <span>{pattern.confidence}%</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-blue-600 h-2 rounded-full"
                        style={{ width: `${pattern.confidence}%` }}
                      ></div>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      )}

      {/* Rule Generation Timeline */}
      {ruleTimeline.length > 0 && (
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h4 className="text-lg font-semibold mb-4">Rule Generation Timeline</h4>
          <ResponsiveContainer width="100%" height={250}>
            <BarChart data={ruleTimeline}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="rules" fill="#8b5cf6" name="Rules Generated" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Knowledge Base Growth */}
      {knowledgeGrowth.length > 0 && (
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h4 className="text-lg font-semibold mb-4">Knowledge Base Growth</h4>
          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={knowledgeGrowth}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Line
                type="monotone"
                dataKey="entries"
                stroke="#f59e0b"
                strokeWidth={2}
                name="Knowledge Entries"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Learning Summary */}
      {metrics && (
        <div className="bg-gradient-to-br from-indigo-50 to-purple-50 rounded-lg shadow-lg p-6 border border-indigo-200">
          <h4 className="text-lg font-semibold mb-4 flex items-center gap-2">
            <i className="ri-lightbulb-line text-indigo-600"></i>
            Learning Summary
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <p className="text-sm text-gray-600 mb-2">Total Feedback Received</p>
              <p className="text-2xl font-bold text-gray-900">{metrics.totalFeedback}</p>
              <p className="text-xs text-gray-500 mt-1">Human corrections processed</p>
            </div>
            <div>
              <p className="text-sm text-gray-600 mb-2">New Patterns Learned</p>
              <p className="text-2xl font-bold text-gray-900">{metrics.patternsLearned}</p>
              <p className="text-xs text-gray-500 mt-1">In selected timeframe</p>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * Predictive Insights Dashboard
 * Mind-blowing predictive analytics visualization
 * Shows trends, forecasts, risks, and opportunities
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { LineChart, Line, AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts'

interface PredictiveInsightsDashboardProps {
  tenantId?: string
  timeframe?: '7d' | '30d' | '90d'
}

interface PredictiveInsight {
  id: string
  type: 'trend' | 'anomaly' | 'risk' | 'opportunity' | 'maintenance'
  title: string
  description: string
  confidence: number
  timeframe: string
  predictedValue?: number
  currentValue?: number
  trend: 'increasing' | 'decreasing' | 'stable' | 'volatile'
  severity: 'low' | 'medium' | 'high' | 'critical'
  recommendations: string[]
}

interface TrendForecast {
  metric: string
  currentValue: number
  forecastedValues: Array<{
    date: string
    value: number
    confidence: number
  }>
  trend: 'increasing' | 'decreasing' | 'stable'
  changeRate: number
  confidence: number
}

export default function PredictiveInsightsDashboard({
  tenantId,
  timeframe = '30d',
}: PredictiveInsightsDashboardProps) {
  const [insights, setInsights] = useState<PredictiveInsight[]>([])
  const [forecasts, setForecasts] = useState<TrendForecast[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedMetric, setSelectedMetric] = useState<string>('compliance')

  useEffect(() => {
    loadPredictiveData()
  }, [tenantId, timeframe])

  const loadPredictiveData = async () => {
    setLoading(true)
    try {
      // Load insights
      const insightsRes = await fetch(
        `/api/ai/vision/predictive/insights?timeframe=${timeframe}&tenantId=${tenantId || ''}`
      )
      if (insightsRes.ok) {
        const insightsData = await insightsRes.json()
        setInsights(insightsData.insights || [])
      }

      // Load forecasts
      const forecastsRes = await fetch(
        `/api/ai/vision/predictive/forecasts?metric=${selectedMetric}&tenantId=${tenantId || ''}`
      )
      if (forecastsRes.ok) {
        const forecastsData = await forecastsRes.json()
        setForecasts(forecastsData.forecasts || [])
      }
    } catch (error) {
      console.error('Error loading predictive data:', error)
    } finally {
      setLoading(false)
    }
  }

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical':
        return 'bg-red-500'
      case 'high':
        return 'bg-orange-500'
      case 'medium':
        return 'bg-yellow-500'
      case 'low':
        return 'bg-blue-500'
      default:
        return 'bg-gray-500'
    }
  }

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'trend':
        return 'ri-line-chart-line'
      case 'anomaly':
        return 'ri-alert-line'
      case 'risk':
        return 'ri-shield-cross-line'
      case 'opportunity':
        return 'ri-lightbulb-line'
      case 'maintenance':
        return 'ri-tools-line'
      default:
        return 'ri-information-line'
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center p-12">
        <i className="ri-loader-4-line animate-spin text-4xl text-blue-600"></i>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-bold text-gray-900">Predictive Insights</h3>
          <p className="text-sm text-gray-600">AI-powered predictions and trend forecasting</p>
        </div>
        <select
          value={timeframe}
          onChange={(e) => {
            const newTimeframe = e.target.value as any
            loadPredictiveData()
          }}
          className="px-4 py-2 border border-gray-300 rounded-lg"
        >
          <option value="7d">Last 7 Days</option>
          <option value="30d">Last 30 Days</option>
          <option value="90d">Last 90 Days</option>
        </select>
      </div>

      {/* Key Insights */}
      {insights.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {insights.slice(0, 6).map((insight, idx) => (
            <motion.div
              key={insight.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.1 }}
              className={`p-6 rounded-lg border-2 ${
                insight.severity === 'critical'
                  ? 'border-red-500 bg-red-50'
                  : insight.severity === 'high'
                  ? 'border-orange-500 bg-orange-50'
                  : insight.severity === 'medium'
                  ? 'border-yellow-500 bg-yellow-50'
                  : 'border-blue-500 bg-blue-50'
              }`}
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-full ${getSeverityColor(insight.severity)} flex items-center justify-center text-white`}>
                    <i className={`${getTypeIcon(insight.type)} text-lg`}></i>
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-900">{insight.title}</h4>
                    <p className="text-xs text-gray-600 capitalize">{insight.type}</p>
                  </div>
                </div>
                <div className="text-right">
                  <div className="text-sm font-semibold text-gray-900">{insight.confidence}%</div>
                  <div className="text-xs text-gray-500">Confidence</div>
                </div>
              </div>
              
              <p className="text-sm text-gray-700 mb-3">{insight.description}</p>
              
              {insight.currentValue !== undefined && insight.predictedValue !== undefined && (
                <div className="mb-3 p-2 bg-white rounded">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-gray-600">Current:</span>
                    <span className="font-semibold">{insight.currentValue.toFixed(1)}</span>
                    <span className="text-gray-600">→</span>
                    <span className="text-gray-600">Predicted:</span>
                    <span className="font-semibold">{insight.predictedValue.toFixed(1)}</span>
                  </div>
                </div>
              )}

              {insight.recommendations.length > 0 && (
                <div className="mt-3 pt-3 border-t border-gray-200">
                  <p className="text-xs font-medium text-gray-700 mb-2">Recommendations:</p>
                  <ul className="space-y-1">
                    {insight.recommendations.slice(0, 2).map((rec, i) => (
                      <li key={i} className="text-xs text-gray-600 flex items-start gap-2">
                        <i className="ri-checkbox-circle-line text-green-600 mt-0.5"></i>
                        <span>{rec}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </motion.div>
          ))}
        </div>
      )}

      {/* Trend Forecasts */}
      {forecasts.length > 0 && (
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h4 className="text-lg font-semibold mb-4">Trend Forecasts</h4>
          <div className="space-y-6">
            {forecasts.map((forecast, idx) => (
              <div key={idx}>
                <div className="flex items-center justify-between mb-4">
                  <div>
                    <h5 className="font-semibold text-gray-900 capitalize">{forecast.metric.replace('_', ' ')}</h5>
                    <p className="text-sm text-gray-600">
                      Current: {forecast.currentValue.toFixed(1)} • Trend: {forecast.trend} • Confidence: {forecast.confidence}%
                    </p>
                  </div>
                  <div className={`px-3 py-1 rounded-full text-sm font-medium ${
                    forecast.trend === 'increasing'
                      ? 'bg-green-100 text-green-800'
                      : forecast.trend === 'decreasing'
                      ? 'bg-red-100 text-red-800'
                      : 'bg-gray-100 text-gray-800'
                  }`}>
                    {forecast.changeRate.toFixed(1)}% change
                  </div>
                </div>
                <ResponsiveContainer width="100%" height={200}>
                  <AreaChart data={forecast.forecastedValues}>
                    <defs>
                      <linearGradient id={`color${idx}`} x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8} />
                        <stop offset="95%" stopColor="#3b82f6" stopOpacity={0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" />
                    <XAxis dataKey="date" />
                    <YAxis />
                    <Tooltip />
                    <Area
                      type="monotone"
                      dataKey="value"
                      stroke="#3b82f6"
                      fillOpacity={1}
                      fill={`url(#color${idx})`}
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            ))}
          </div>
        </div>
      )}

      {insights.length === 0 && forecasts.length === 0 && (
        <div className="text-center py-12 bg-gray-50 rounded-lg">
          <i className="ri-line-chart-line text-4xl text-gray-400 mb-3"></i>
          <p className="text-gray-600">No predictive insights available yet</p>
          <p className="text-sm text-gray-500 mt-1">More data needed for accurate predictions</p>
        </div>
      )}
    </div>
  )
}

/**
 * Vision Analysis Card Component
 * Beautiful card display for vision analysis results
 * From UI/UX mocks - ensures all visualized features are implemented
 */

'use client'

import { motion } from 'framer-motion'
import { useState } from 'react'

interface VisionAnalysisCardProps {
  analysis: {
    id: string
    analysisId: string
    imageUrl?: string
    thumbnailUrl?: string
    analysis: any
    complianceScore?: number
    isCompliant?: boolean
    totalIssues?: number
    criticalIssues?: number
    createdAt: string
    module?: string
  }
  onViewDetails?: (analysisId: string) => void
  onDelete?: (analysisId: string) => void
  compact?: boolean
}

export default function VisionAnalysisCard({
  analysis,
  onViewDetails,
  onDelete,
  compact = false,
}: VisionAnalysisCardProps) {
  const [imageError, setImageError] = useState(false)

  const safetyIssues = analysis.analysis?.safetyIssues || []
  const qualityIssues = analysis.analysis?.qualityIssues || []
  const complianceIssues = analysis.analysis?.complianceIssues || []

  const getSeverityColor = (severity: string) => {
    switch (severity?.toLowerCase()) {
      case 'critical':
        return 'bg-red-500'
      case 'high':
        return 'bg-orange-500'
      case 'medium':
        return 'bg-yellow-500'
      case 'low':
        return 'bg-blue-500'
      default:
        return 'bg-gray-500'
    }
  }

  const getComplianceColor = (score?: number) => {
    if (!score) return 'bg-gray-500'
    if (score >= 90) return 'bg-green-500'
    if (score >= 70) return 'bg-yellow-500'
    return 'bg-red-500'
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-white rounded-xl shadow-lg overflow-hidden hover:shadow-xl transition-shadow"
    >
      {/* Image Preview */}
      {analysis.thumbnailUrl && !imageError && (
        <div className="relative h-48 bg-gray-100">
          <img
            src={analysis.thumbnailUrl}
            alt="Analysis preview"
            className="w-full h-full object-cover"
            onError={() => setImageError(true)}
          />
          {analysis.complianceScore !== undefined && (
            <div className="absolute top-2 right-2">
              <div
                className={`px-3 py-1 rounded-full text-white text-sm font-semibold ${getComplianceColor(
                  analysis.complianceScore
                )}`}
              >
                {analysis.complianceScore}%
              </div>
            </div>
          )}
          {analysis.isCompliant === false && (
            <div className="absolute top-2 left-2">
              <div className="px-3 py-1 bg-red-500 rounded-full text-white text-sm font-semibold">
                Non-Compliant
              </div>
            </div>
          )}
        </div>
      )}

      {/* Content */}
      <div className="p-6">
        {/* Header */}
        <div className="flex items-start justify-between mb-4">
          <div className="flex-1">
            <h3 className="text-lg font-semibold text-gray-900 mb-1">
              {analysis.module ? analysis.module.toUpperCase() : 'Vision'} Analysis
            </h3>
            <p className="text-sm text-gray-500">
              {new Date(analysis.createdAt).toLocaleDateString()} • {new Date(analysis.createdAt).toLocaleTimeString()}
            </p>
          </div>
          {analysis.module && (
            <div className="px-2 py-1 bg-blue-100 text-blue-800 rounded text-xs font-medium">
              {analysis.module}
            </div>
          )}
        </div>

        {/* Issues Summary */}
        {!compact && (
          <div className="grid grid-cols-3 gap-3 mb-4">
            <div className="text-center p-3 bg-red-50 rounded-lg">
              <div className="text-2xl font-bold text-red-600">{safetyIssues.length}</div>
              <div className="text-xs text-red-700">Safety</div>
            </div>
            <div className="text-center p-3 bg-orange-50 rounded-lg">
              <div className="text-2xl font-bold text-orange-600">{qualityIssues.length}</div>
              <div className="text-xs text-orange-700">Quality</div>
            </div>
            <div className="text-center p-3 bg-yellow-50 rounded-lg">
              <div className="text-2xl font-bold text-yellow-600">{complianceIssues.length}</div>
              <div className="text-xs text-yellow-700">Compliance</div>
            </div>
          </div>
        )}

        {/* Critical Issues Badge */}
        {analysis.criticalIssues && analysis.criticalIssues > 0 && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center gap-2">
              <i className="ri-alert-line text-red-600"></i>
              <span className="text-sm font-semibold text-red-900">
                {analysis.criticalIssues} Critical Issue{analysis.criticalIssues > 1 ? 's' : ''} Detected
              </span>
            </div>
          </div>
        )}

        {/* Description Preview */}
        {!compact && analysis.analysis?.description && (
          <p className="text-sm text-gray-600 mb-4 line-clamp-2">
            {analysis.analysis.description.substring(0, 150)}
            {analysis.analysis.description.length > 150 ? '...' : ''}
          </p>
        )}

        {/* Actions */}
        <div className="flex items-center gap-2">
          {onViewDetails && (
            <button
              onClick={() => onViewDetails(analysis.analysisId)}
              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
            >
              <i className="ri-eye-line mr-2"></i>
              View Details
            </button>
          )}
          {onDelete && (
            <button
              onClick={() => onDelete(analysis.analysisId)}
              className="px-4 py-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors"
            >
              <i className="ri-delete-bin-line"></i>
            </button>
          )}
        </div>
      </div>
    </motion.div>
  )
}

/**
 * Compliance Tracker Component
 * Multi-jurisdiction compliance tracking and AI verification
 * BlueDXP Platform - 5IR Aligned
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { 
  regulatoryComplianceService,
  type ComplianceCheckResult,
  type AIComplianceVerification
} from '@/lib/services/wms/regulatoryComplianceService'
import type { StorageLocation } from '@/types/warehouseLocation'
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer } from 'recharts'

interface ComplianceTrackerProps {
  location: StorageLocation
  onRefresh?: () => void
}

export default function ComplianceTracker({ location, onRefresh }: ComplianceTrackerProps) {
  const [complianceResults, setComplianceResults] = useState<ComplianceCheckResult[]>([])
  const [aiVerification, setAiVerification] = useState<AIComplianceVerification | null>(null)
  const [overallScore, setOverallScore] = useState<number | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)

  useEffect(() => {
    fetchCompliance()
  }, [location.id])

  const fetchCompliance = async () => {
    try {
      setLoading(true)

      // Check all compliance
      const results = await regulatoryComplianceService.checkAllCompliance(location)
      setComplianceResults(results)

      // Get AI verification
      const aiVer = await regulatoryComplianceService.aiVerifyCompliance(location)
      setAiVerification(aiVer)

      // Get overall score
      const score = await regulatoryComplianceService.calculateOverallComplianceScore(location)
      setOverallScore(score)
    } catch (error) {
      console.error('Error fetching compliance:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleRefresh = async () => {
    setRefreshing(true)
    await fetchCompliance()
    setRefreshing(false)
    onRefresh?.()
  }

  const chartData = complianceResults.map(result => ({
    authority: result.authorityId.split('-')[1] || result.authorityId,
    score: result.complianceScore,
    compliant: result.compliant ? 1 : 0
  }))

  if (loading) {
    return (
      <div className="text-center py-12">
        <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div>
        <p className="mt-4 text-gray-400">Loading compliance data...</p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xl font-bold text-white flex items-center gap-2">
            <i className="ri-shield-check-line text-cyan-400"></i>
            Compliance Tracker
          </h3>
          <p className="text-sm text-gray-400">Multi-jurisdiction compliance monitoring</p>
        </div>
        <button
          onClick={handleRefresh}
          disabled={refreshing}
          className="px-4 py-2 rounded-lg bg-white/5 border border-white/10 hover:border-cyan-500/50 hover:bg-cyan-500/10 transition flex items-center gap-2 text-white disabled:opacity-50"
        >
          {refreshing ? (
            <>
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-cyan-400"></div>
              Refreshing...
            </>
          ) : (
            <>
              <i className="ri-refresh-line"></i>
              Refresh
            </>
          )}
        </button>
      </div>

      {/* Overall Score */}
      {overallScore !== null && (
        <div className="p-6 rounded-xl bg-gradient-to-r from-cyan-500/10 to-blue-500/10 border border-cyan-500/20">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h4 className="text-lg font-semibold text-white">Overall Compliance Score</h4>
              <p className="text-sm text-gray-400">Average across all regulatory authorities</p>
            </div>
            <div className="text-right">
              <div className={`text-4xl font-bold ${
                overallScore >= 90 ? 'text-green-400' :
                overallScore >= 70 ? 'text-yellow-400' :
                'text-red-400'
              }`}>
                {overallScore}%
              </div>
              <div className="text-xs text-gray-400 mt-1">
                {complianceResults.length} authorities checked
              </div>
            </div>
          </div>
          <div className="w-full bg-white/10 rounded-full h-3">
            <div
              className={`h-3 rounded-full transition-all ${
                overallScore >= 90 ? 'bg-green-500' :
                overallScore >= 70 ? 'bg-yellow-500' :
                'bg-red-500'
              }`}
              style={{ width: `${overallScore}%` }}
            />
          </div>
        </div>
      )}

      {/* AI Verification */}
      {aiVerification && (
        <div className="p-6 rounded-xl bg-white/5 border border-white/10">
          <div className="flex items-center gap-3 mb-4">
            <i className="ri-cpu-line text-2xl text-cyan-400"></i>
            <div>
              <h4 className="text-lg font-semibold text-white">AI Compliance Verification (5IR)</h4>
              <p className="text-sm text-gray-400">Powered by AI - Verified on {new Date(aiVerification.verificationDate).toLocaleDateString()}</p>
            </div>
            <span className={`ml-auto px-3 py-1 rounded text-sm font-medium ${
              aiVerification.overallCompliant
                ? 'bg-green-500/20 text-green-400'
                : 'bg-red-500/20 text-red-400'
            }`}>
              {aiVerification.overallCompliant ? 'Compliant' : 'Non-Compliant'}
            </span>
          </div>

          <div className="grid md:grid-cols-2 gap-4 mb-4">
            {Object.entries(aiVerification.details).map(([category, data]: [string, any]) => (
              <div key={category} className="p-4 rounded-lg bg-white/5 border border-white/10">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium text-gray-300 capitalize">{category}</span>
                  <span className={`px-2 py-1 rounded text-xs ${
                    data.compliant ? 'bg-green-500/20 text-green-400' : 'bg-red-500/20 text-red-400'
                  }`}>
                    {data.compliant ? 'Compliant' : 'Non-Compliant'}
                  </span>
                </div>
                <div className="text-2xl font-bold text-white mb-1">{data.score}%</div>
                <div className="w-full bg-white/10 rounded-full h-1.5">
                  <div
                    className={`h-1.5 rounded-full ${
                      data.score >= 90 ? 'bg-green-500' :
                      data.score >= 70 ? 'bg-yellow-500' :
                      'bg-red-500'
                    }`}
                    style={{ width: `${data.score}%` }}
                  />
                </div>
                {data.issues.length > 0 && (
                  <div className="mt-2">
                    {data.issues.map((issue: string, idx: number) => (
                      <p key={idx} className="text-xs text-red-400">• {issue}</p>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>

          {aiVerification.recommendations.length > 0 && (
            <div className="mt-4 p-4 rounded-lg bg-cyan-500/10 border border-cyan-500/20">
              <p className="text-sm font-medium text-cyan-400 mb-2">AI Recommendations:</p>
              <ul className="space-y-1">
                {aiVerification.recommendations.map((rec, idx) => (
                  <li key={idx} className="text-sm text-gray-300 flex items-start gap-2">
                    <i className="ri-arrow-right-s-line text-cyan-400 mt-0.5"></i>
                    {rec}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}

      {/* Authority Compliance Results */}
      <div>
        <h4 className="text-lg font-semibold text-white mb-4">Authority Compliance Results</h4>
        <div className="space-y-4">
          {complianceResults.map((result, index) => (
            <motion.div
              key={result.authorityId}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
              className={`p-4 rounded-xl border ${
                result.compliant
                  ? 'bg-green-500/10 border-green-500/20'
                  : 'bg-red-500/10 border-red-500/20'
              }`}
            >
              <div className="flex items-center justify-between mb-3">
                <div>
                  <h5 className="font-semibold text-white">{result.authorityId}</h5>
                  <p className="text-xs text-gray-400">
                    Last checked: {new Date(result.lastCheck).toLocaleDateString()}
                  </p>
                </div>
                <div className="text-right">
                  <div className={`text-2xl font-bold ${
                    result.compliant ? 'text-green-400' : 'text-red-400'
                  }`}>
                    {result.complianceScore}%
                  </div>
                  <span className={`px-2 py-1 rounded text-xs ${
                    result.compliant
                      ? 'bg-green-500/20 text-green-400'
                      : 'bg-red-500/20 text-red-400'
                  }`}>
                    {result.compliant ? 'Compliant' : 'Non-Compliant'}
                  </span>
                </div>
              </div>

              <div className="w-full bg-white/10 rounded-full h-2 mb-3">
                <div
                  className={`h-2 rounded-full ${
                    result.complianceScore >= 90 ? 'bg-green-500' :
                    result.complianceScore >= 70 ? 'bg-yellow-500' :
                    'bg-red-500'
                  }`}
                  style={{ width: `${result.complianceScore}%` }}
                />
              </div>

              {result.passedRequirements.length > 0 && (
                <div className="mb-3">
                  <p className="text-xs font-medium text-green-400 mb-1">Passed Requirements:</p>
                  <div className="flex flex-wrap gap-1">
                    {result.passedRequirements.map((req, idx) => (
                      <span key={idx} className="px-2 py-0.5 rounded text-xs bg-green-500/20 text-green-400">
                        ✓ {req}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {result.failedRequirements.length > 0 && (
                <div className="mb-3">
                  <p className="text-xs font-medium text-red-400 mb-1">Failed Requirements:</p>
                  <div className="flex flex-wrap gap-1">
                    {result.failedRequirements.map((req, idx) => (
                      <span key={idx} className="px-2 py-0.5 rounded text-xs bg-red-500/20 text-red-400">
                        ✗ {req}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {result.warnings.length > 0 && (
                <div className="mb-3">
                  <p className="text-xs font-medium text-yellow-400 mb-1">Warnings:</p>
                  <ul className="space-y-1">
                    {result.warnings.map((warning, idx) => (
                      <li key={idx} className="text-xs text-gray-300 flex items-start gap-2">
                        <i className="ri-alert-line text-yellow-400 mt-0.5"></i>
                        {warning}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {result.recommendations.length > 0 && (
                <div>
                  <p className="text-xs font-medium text-cyan-400 mb-1">Recommendations:</p>
                  <ul className="space-y-1">
                    {result.recommendations.map((rec, idx) => (
                      <li key={idx} className="text-xs text-gray-300 flex items-start gap-2">
                        <i className="ri-arrow-right-s-line text-cyan-400 mt-0.5"></i>
                        {rec}
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              <div className="mt-3 pt-3 border-t border-white/10">
                <p className="text-xs text-gray-400">
                  Next check: {new Date(result.nextCheck).toLocaleDateString()}
                </p>
              </div>
            </motion.div>
          ))}
        </div>
      </div>

      {/* Compliance Chart */}
      {chartData.length > 0 && (
        <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6">
          <h4 className="text-lg font-semibold text-white mb-4">Compliance Score by Authority</h4>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#374151" />
              <XAxis dataKey="authority" stroke="#9ca3af" fontSize={10} angle={-45} textAnchor="end" height={80} />
              <YAxis stroke="#9ca3af" fontSize={12} />
              <RechartsTooltip
                contentStyle={{ backgroundColor: '#1f2937', border: '1px solid #374151', borderRadius: '8px' }}
                labelStyle={{ color: '#fff' }}
              />
              <Bar dataKey="score" fill="#06b6d4" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  )
}

/**
 * Fire Safety Configuration Component
 * Comprehensive fire suppression system configuration and recommendations
 * BlueDXP Platform - 4IR & 5IR Aligned
 */

'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import Modal from '@/components/Modal'
import Tooltip from '@/components/Tooltip'
import { fireSafetyService, type FireSuppressionSystemSpec } from '@/lib/services/wms/fireSafetyService'
import type { FireSuppressionSystemType } from '@/types/warehouseLocation'
import { ALL_HAZARD_CLASSES } from '@/types/warehouseLocation'

interface FireSafetyConfigProps {
  locationId?: string
  currentSystem?: FireSuppressionSystemType
  hazardClasses: string[]
  areaSize: number
  onSystemSelect?: (system: FireSuppressionSystemType) => void
  onClose?: () => void
}

export default function FireSafetyConfig({
  locationId,
  currentSystem,
  hazardClasses,
  areaSize,
  onSystemSelect,
  onClose
}: FireSafetyConfigProps) {
  const [selectedSystem, setSelectedSystem] = useState<FireSuppressionSystemType | null>(currentSystem || null)
  const [recommendedSystems, setRecommendedSystems] = useState<FireSuppressionSystemType[]>([])
  const [systemSpecs, setSystemSpecs] = useState<FireSuppressionSystemSpec | null>(null)
  const [complianceCheck, setComplianceCheck] = useState<any>(null)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (hazardClasses.length > 0) {
      const recommendations = fireSafetyService.getRecommendedSystem(hazardClasses, areaSize)
      setRecommendedSystems(recommendations)
    }
  }, [hazardClasses, areaSize])

  useEffect(() => {
    if (selectedSystem) {
      const spec = fireSafetyService.getSystemSpecs(selectedSystem)
      setSystemSpecs(spec)

      if (locationId) {
        checkCompliance()
      }
    }
  }, [selectedSystem, locationId, hazardClasses])

  const checkCompliance = async () => {
    if (!selectedSystem || !locationId) return

    try {
      setLoading(true)
      const response = await fetch(`/api/wms/fire-safety?action=compliance&locationId=${locationId}`)
      const data = await response.json()
      if (data.success) {
        setComplianceCheck(data.data)
      }
    } catch (error) {
      console.error('Error checking compliance:', error)
    } finally {
      setLoading(false)
    }
  }

  const allSystems: FireSuppressionSystemType[] = [
    'Sprinkler System with FM-200',
    'CO2 System',
    'Foam System',
    'Dry Chemical System',
    'Water Sprinkler System',
    'Gas Suppression (FM-200)',
    'Gas Suppression (Novec 1230)',
    'Inert Gas System (IG-541)',
    'Pre-Action Sprinkler System',
    'Deluge System',
    'Foam-Water Sprinkler System',
    'Multiple Systems (Combined)',
    'None'
  ]

  const handleSystemSelect = (system: FireSuppressionSystemType) => {
    setSelectedSystem(system)
    onSystemSelect?.(system)
  }

  const content = (
    <div className="space-y-6">
      {/* Recommended Systems */}
      {recommendedSystems.length > 0 && (
        <div className="p-4 rounded-xl bg-cyan-500/10 border border-cyan-500/20">
          <div className="flex items-center gap-2 mb-3">
            <i className="ri-lightbulb-line text-cyan-400"></i>
            <h4 className="font-semibold text-cyan-400">Recommended Systems</h4>
          </div>
          <div className="flex flex-wrap gap-2">
            {recommendedSystems.map(system => (
              <button
                key={system}
                onClick={() => handleSystemSelect(system)}
                className={`px-3 py-1.5 rounded-lg text-sm transition ${
                  selectedSystem === system
                    ? 'bg-cyan-500 text-white'
                    : 'bg-white/5 text-gray-300 hover:bg-white/10'
                }`}
              >
                {system}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* System Selection */}
      <div>
        <label className="block text-sm font-medium text-gray-300 mb-3">
          Fire Suppression System <span className="text-red-400">*</span>
        </label>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-h-96 overflow-y-auto">
          {allSystems.map(system => {
            const spec = fireSafetyService.getSystemSpecs(system)
            const isRecommended = recommendedSystems.includes(system)
            const isCompatible = spec ? hazardClasses.every(hc => spec.suitableFor.includes(hc)) : false

            return (
              <button
                key={system}
                onClick={() => handleSystemSelect(system)}
                className={`p-4 rounded-lg border text-left transition ${
                  selectedSystem === system
                    ? 'bg-cyan-500/20 border-cyan-500'
                    : 'bg-white/5 border-white/10 hover:border-cyan-500/50'
                }`}
              >
                <div className="flex items-start justify-between mb-2">
                  <span className="font-medium text-white">{system}</span>
                  {isRecommended && (
                    <span className="px-2 py-0.5 rounded text-xs bg-green-500/20 text-green-400">
                      Recommended
                    </span>
                  )}
                </div>
                {spec && (
                  <div className="space-y-1 text-xs text-gray-400">
                    <div>Coverage: {spec.coverageArea.toLocaleString()} m²</div>
                    <div>Agent: {spec.agent}</div>
                    <div>Standards: {spec.certificationStandards.join(', ')}</div>
                    {!isCompatible && hazardClasses.length > 0 && (
                      <div className="text-yellow-400">⚠ May not cover all hazard classes</div>
                    )}
                  </div>
                )}
              </button>
            )
          })}
        </div>
      </div>

      {/* Selected System Details */}
      {selectedSystem && systemSpecs && (
        <div className="p-4 rounded-xl bg-white/5 border border-white/10">
          <h4 className="font-semibold text-white mb-3">System Specifications</h4>
          <div className="grid grid-cols-2 gap-4 text-sm">
            <div>
              <span className="text-gray-400">Description:</span>
              <p className="text-white mt-1">{systemSpecs.description}</p>
            </div>
            <div>
              <span className="text-gray-400">Coverage Area:</span>
              <p className="text-white mt-1">{systemSpecs.coverageArea.toLocaleString()} m²</p>
            </div>
            <div>
              <span className="text-gray-400">Activation Type:</span>
              <p className="text-white mt-1">{systemSpecs.activationType}</p>
            </div>
            <div>
              <span className="text-gray-400">Agent:</span>
              <p className="text-white mt-1">{systemSpecs.agent}</p>
            </div>
            <div>
              <span className="text-gray-400">Environmental Impact:</span>
              <p className="text-white mt-1">{systemSpecs.environmentalImpact}</p>
            </div>
            <div>
              <span className="text-gray-400">Maintenance:</span>
              <p className="text-white mt-1">{systemSpecs.maintenanceFrequency}</p>
            </div>
            <div className="col-span-2">
              <span className="text-gray-400">Suitable For:</span>
              <div className="flex flex-wrap gap-2 mt-1">
                {systemSpecs.suitableFor.map(hc => (
                  <span key={hc} className="px-2 py-1 rounded text-xs bg-cyan-500/10 text-cyan-400">
                    {hc}
                  </span>
                ))}
              </div>
            </div>
            <div className="col-span-2">
              <span className="text-gray-400">Certification Standards:</span>
              <div className="flex flex-wrap gap-2 mt-1">
                {systemSpecs.certificationStandards.map(std => (
                  <span key={std} className="px-2 py-1 rounded text-xs bg-blue-500/10 text-blue-400">
                    {std}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Compliance Check */}
      {complianceCheck && (
        <div className={`p-4 rounded-xl border ${
          complianceCheck.compliant
            ? 'bg-green-500/10 border-green-500/20'
            : 'bg-red-500/10 border-red-500/20'
        }`}>
          <div className="flex items-center justify-between mb-3">
            <h4 className="font-semibold text-white">Compliance Check</h4>
            <span className={`px-3 py-1 rounded text-sm font-medium ${
              complianceCheck.compliant
                ? 'bg-green-500/20 text-green-400'
                : 'bg-red-500/20 text-red-400'
            }`}>
              {complianceCheck.compliant ? 'Compliant' : 'Non-Compliant'}
            </span>
          </div>
          <div className="mb-3">
            <div className="flex items-center justify-between mb-1">
              <span className="text-sm text-gray-400">Compliance Score</span>
              <span className="text-lg font-bold text-white">{complianceCheck.complianceScore}%</span>
            </div>
            <div className="w-full bg-white/10 rounded-full h-2">
              <div
                className={`h-2 rounded-full ${
                  complianceCheck.complianceScore >= 90 ? 'bg-green-500' :
                  complianceCheck.complianceScore >= 70 ? 'bg-yellow-500' :
                  'bg-red-500'
                }`}
                style={{ width: `${complianceCheck.complianceScore}%` }}
              />
            </div>
          </div>
          {complianceCheck.issues.length > 0 && (
            <div className="mb-3">
              <p className="text-sm font-medium text-red-400 mb-2">Issues:</p>
              <ul className="space-y-1">
                {complianceCheck.issues.map((issue: string, idx: number) => (
                  <li key={idx} className="text-sm text-gray-300 flex items-start gap-2">
                    <i className="ri-close-circle-line text-red-400 mt-0.5"></i>
                    {issue}
                  </li>
                ))}
              </ul>
            </div>
          )}
          {complianceCheck.recommendations.length > 0 && (
            <div>
              <p className="text-sm font-medium text-cyan-400 mb-2">Recommendations:</p>
              <ul className="space-y-1">
                {complianceCheck.recommendations.map((rec: string, idx: number) => (
                  <li key={idx} className="text-sm text-gray-300 flex items-start gap-2">
                    <i className="ri-arrow-right-s-line text-cyan-400 mt-0.5"></i>
                    {rec}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}

      {/* Hazard Class Compatibility */}
      {hazardClasses.length > 0 && selectedSystem && systemSpecs && (
        <div className="p-4 rounded-xl bg-white/5 border border-white/10">
          <h4 className="font-semibold text-white mb-3">Hazard Class Compatibility</h4>
          <div className="space-y-2">
            {hazardClasses.map(hc => {
              const isCompatible = systemSpecs.suitableFor.includes(hc)
              return (
                <div key={hc} className="flex items-center justify-between p-2 rounded bg-white/5">
                  <span className="text-sm text-white">{hc}</span>
                  {isCompatible ? (
                    <span className="px-2 py-1 rounded text-xs bg-green-500/20 text-green-400">
                      <i className="ri-check-line mr-1"></i>
                      Compatible
                    </span>
                  ) : (
                    <span className="px-2 py-1 rounded text-xs bg-red-500/20 text-red-400">
                      <i className="ri-close-line mr-1"></i>
                      Not Compatible
                    </span>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )

  if (onClose) {
    return (
      <Modal
        isOpen={true}
        onClose={onClose}
        title="Fire Safety Configuration"
        size="xl"
      >
        {content}
      </Modal>
    )
  }

  return <div>{content}</div>
}

