                              <span>{rec}</span>
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </motion.div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'

interface Alert {
  id: string
  type: 'warning' | 'error' | 'info' | 'success'
  title: string
  message: string
  timestamp: Date
  priority: 'low' | 'medium' | 'high' | 'critical'
  actionUrl?: string
}

interface WarehouseAlertsProps {
  warehouseId: string
}

export default function WarehouseAlerts({ warehouseId }: WarehouseAlertsProps) {
  const [alerts, setAlerts] = useState<Alert[]>([])
  const [isExpanded, setIsExpanded] = useState(false)

  useEffect(() => {
    // Load alerts
    loadAlerts()
    
    // Set up real-time alert updates
    const interval = setInterval(loadAlerts, 10000) // Check every 10 seconds
    
    return () => clearInterval(interval)
  }, [warehouseId])

  const loadAlerts = async () => {
    try {
      const response = await fetch(`/api/warehouse/${warehouseId}/alerts`)
      if (response.ok) {
        const data = await response.json()
        setAlerts(data.alerts || [])
      }
    } catch (error) {
      // Mock alerts for demo
      setAlerts([
        {
          id: 'alert-001',
          type: 'warning',
          title: 'High Utilization',
          message: 'Zone A utilization is above 90%',
          timestamp: new Date(),
          priority: 'high',
          actionUrl: `/warehouses/${warehouseId}/zones/zone-a`
        },
        {
          id: 'alert-002',
          type: 'info',
          title: 'Maintenance Scheduled',
          message: 'Forklift A1 maintenance due in 2 days',
          timestamp: new Date(Date.now() - 3600000),
          priority: 'medium',
          actionUrl: `/warehouses/${warehouseId}?tab=operations`
        },
        {
          id: 'alert-003',
          type: 'success',
          title: 'Cycle Count Complete',
          message: 'Zone B cycle count completed with 99.8% accuracy',
          timestamp: new Date(Date.now() - 7200000),
          priority: 'low'
        }
      ])
    }
  }

  const getAlertColor = (type: string) => {
    switch (type) {
      case 'error': return 'bg-red-500/20 text-red-400 border-red-500/30'
      case 'warning': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'
      case 'info': return 'bg-blue-500/20 text-blue-400 border-blue-500/30'
      case 'success': return 'bg-green-500/20 text-green-400 border-green-500/30'
      default: return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
    }
  }

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'critical': return 'ri-alarm-warning-line text-red-400'
      case 'high': return 'ri-error-warning-line text-orange-400'
      case 'medium': return 'ri-information-line text-yellow-400'
      default: return 'ri-checkbox-circle-line text-blue-400'
    }
  }

  const criticalAlerts = alerts.filter(a => a.priority === 'critical' || a.priority === 'high')
  const displayAlerts = isExpanded ? alerts : alerts.slice(0, 3)

  if (alerts.length === 0) {
    return null
  }

  return (
    <div className="space-y-4">
      {criticalAlerts.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          className="p-4 rounded-xl bg-red-500/10 border-2 border-red-500/30"
        >
          <div className="flex items-center space-x-2 mb-2">
            <i className="ri-alarm-warning-line text-red-400 text-xl"></i>
            <h4 className="text-white font-semibold">Critical Alerts ({criticalAlerts.length})</h4>
          </div>
          <div className="space-y-2">
            {criticalAlerts.map((alert) => (
              <div key={alert.id} className="p-3 rounded-lg bg-red-500/20 border border-red-500/30">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center space-x-2 mb-1">
                      <i className={getPriorityIcon(alert.priority)}></i>
                      <span className="text-white font-medium">{alert.title}</span>
                    </div>
                    <p className="text-sm text-white/70">{alert.message}</p>
                    <p className="text-xs text-white/50 mt-1">
                      {new Date(alert.timestamp).toLocaleString()}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      )}

      <div className="p-4 rounded-xl bg-white/5 border border-white/10">
        <div className="flex items-center justify-between mb-3">
          <h4 className="text-white font-semibold flex items-center space-x-2">
            <i className="ri-notification-line text-cyan-400"></i>
            <span>Recent Alerts ({alerts.length})</span>
          </h4>
          {alerts.length > 3 && (
            <button
              onClick={() => setIsExpanded(!isExpanded)}
              className="text-sm text-cyan-400 hover:text-cyan-300"
            >
              {isExpanded ? 'Show Less' : 'Show All'}
            </button>
          )}
        </div>
        <AnimatePresence>
          <div className="space-y-2">
            {displayAlerts.map((alert) => (
              <motion.div
                key={alert.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className={`p-3 rounded-lg border ${getAlertColor(alert.type)}`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center space-x-2 mb-1">
                      <i className={getPriorityIcon(alert.priority)}></i>
                      <span className="font-medium">{alert.title}</span>
                    </div>
                    <p className="text-sm opacity-80">{alert.message}</p>
                    <p className="text-xs opacity-60 mt-1">
                      {new Date(alert.timestamp).toLocaleString()}
                    </p>
                  </div>
                  {alert.actionUrl && (
                    <a
                      href={alert.actionUrl}
                      className="ml-2 px-2 py-1 text-xs bg-white/10 rounded hover:bg-white/20 transition-colors"
                    >
                      View
                    </a>
                  )}
                </div>
              </motion.div>
            ))}
          </div>
        </AnimatePresence>
      </div>
    </div>
  )
}

/**
 * Comprehensive Warehouse Areas Manager Component
 * Migrated from chemcheck-ai with full BlueDXP integration
 * World's Most Comprehensive Warehouse Area/Zone Management
 * BlueDXP Platform - 4IR & 5IR Aligned • Fully Interactive
 */

'use client'

import { useState, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import Modal from '@/components/Modal'
import Tooltip from '@/components/Tooltip'
import { listAreasAction, createAreaAction, updateAreaAction, deleteAreaAction, getAreaStatisticsAction } from '@/app/actions/wms/areaActions'
import type { AreaStatistics } from '@/lib/services/wms/areaService'
import { ALL_HAZARD_CLASSES } from '@/types/warehouseLocation'
import type { WarehouseArea, WarehouseAreaRequest } from '@/types/warehouseArea'
import { BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip, Legend, ResponsiveContainer } from 'recharts'

interface WarehouseAreasManagerProps {
  warehouseId?: string // Optional - allows standalone areas
  warehouseName?: string
  tenantId?: string
  customerId?: string
  onAreaSelect?: (area: WarehouseArea) => void
  allowStandalone?: boolean // Allow creating areas without warehouse
  linkedModuleId?: string // For cross-module integration
  linkedEntityId?: string // For cross-module integration
}

export default function WarehouseAreasManager({
  warehouseId,
  warehouseName,
  tenantId,
  customerId,
  onAreaSelect,
  allowStandalone = true, // ✅ Default to allowing standalone areas
  linkedModuleId,
  linkedEntityId
}: WarehouseAreasManagerProps) {
  const [areas, setAreas] = useState<WarehouseArea[]>([])
  const [loading, setLoading] = useState(true)
  const [statistics, setStatistics] = useState<AreaStatistics | null>(null)
  const [showCreateModal, setShowCreateModal] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)
  const [showDetailsModal, setShowDetailsModal] = useState(false)
  const [showImportModal, setShowImportModal] = useState(false)
  const [selectedArea, setSelectedArea] = useState<WarehouseArea | null>(null)
  const [uploading, setUploading] = useState(false)
  const [viewMode, setViewMode] = useState<'grid' | 'table' | 'analytics'>('grid')
  const [filterZone, setFilterZone] = useState<string>('ALL')
  const [searchQuery, setSearchQuery] = useState('')

  const [areaFormData, setAreaFormData] = useState<Partial<WarehouseAreaRequest>>({
    areaCode: '',
    areaName: '',
    zone: '',
    warehouseId,
    capacity: 0,
    currentStock: 0,
    allowedHazards: [],
    restrictions: '',
    temperatureZone: '', // Added temp zone
    active: true
  })

  // Fetch areas
  useEffect(() => {
    fetchAreas()
    if (warehouseId) {
      fetchStatistics()
    }
  }, [warehouseId, linkedModuleId, linkedEntityId])

  const fetchAreas = async () => {
    setLoading(true)
    try {
      const filters: Record<string, string | boolean | undefined> = {
        warehouseId: warehouseId || (allowStandalone ? undefined : ''),
        linkedModuleId,
        linkedEntityId,
        tenantId, // Add tenantId and customerId to filters
        customerId
      }

      const [areasRes, statsRes] = await Promise.all([
        listAreasAction(filters),
        warehouseId ? getAreaStatisticsAction(warehouseId) : Promise.resolve({ success: true, data: null }) // Only fetch stats if warehouseId exists
      ])

      if (areasRes.success && areasRes.data) {
        setAreas(areasRes.data)
      } else {
        console.error('Failed to load areas:', areasRes.error)
      }

      if (statsRes.success && statsRes.data) {
        setStatistics(statsRes.data)
      }
    } catch (error) {
      console.error('Error loading areas:', error)
    } finally {
      setLoading(false)
    }
  }

  // Removed misplaced loadAreas definition and merged logic into fetchAreas
  // maintain previous fetchStatistics separately if needed or just use above






  // Filtered areas
  const filteredAreas = useMemo(() => {
    return areas.filter(area => {
      const matchesSearch = searchQuery === '' ||
        area.areaCode.toLowerCase().includes(searchQuery.toLowerCase()) ||
        area.areaName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        area.zone.toLowerCase().includes(searchQuery.toLowerCase())
      const matchesZone = filterZone === 'ALL' || area.zone === filterZone
      return matchesSearch && matchesZone
    })
  }, [areas, searchQuery, filterZone])

  // Zones list
  const zones = useMemo(() => {
    return Array.from(new Set(areas.map(a => a.zone))).sort()
  }, [areas])

  // Analytics data
  const analyticsData = useMemo(() => {
    return filteredAreas.map(area => ({
      area: area.areaCode,
      utilization: area.utilizationPercentage || 0,
      capacity: area.capacity,
      stock: area.currentStock
    }))
  }, [filteredAreas])

  const zoneDistribution = useMemo(() => {
    const distribution: Record<string, number> = {}
    areas.forEach(area => {
      distribution[area.zone] = (distribution[area.zone] || 0) + 1
    })
    return Object.entries(distribution).map(([zone, count]) => ({ zone, count }))
  }, [areas])

  // Handle create area
  const handleCreateArea = async () => {
    try {
      // ✅ Comprehensive validation
      if (!areaFormData.areaCode || !areaFormData.areaName || !areaFormData.zone) {
        alert('Please fill in all required fields: Area Code, Area Name, and Zone')
        return
      }

      // ✅ Validate warehouse requirement
      if (!warehouseId && !allowStandalone) {
        alert('Warehouse is required. Please select a warehouse or enable standalone areas.')
        return
      }

      const newArea = await warehouseAreaService.createArea({
        areaCode: areaFormData.areaCode,
        areaName: areaFormData.areaName,
        zone: areaFormData.zone,
        warehouseId: warehouseId || undefined, // ✅ Optional - allows standalone
        capacity: areaFormData.capacity || 0,
        currentStock: areaFormData.currentStock || 0,
        allowedHazards: areaFormData.allowedHazards || [],
        restrictions: areaFormData.restrictions || '',
        temperatureZone: areaFormData.temperatureZone || undefined,
        active: areaFormData.active !== undefined ? areaFormData.active : true,
        linkedModuleId: linkedModuleId || areaFormData.linkedModuleId,
        linkedEntityId: linkedEntityId || areaFormData.linkedEntityId,
        linkedEntityType: areaFormData.linkedEntityType
      })

      setAreas([...areas, newArea])
      await fetchStatistics()
      setShowCreateModal(false)
      resetForm()
    } catch (error) {
      console.error('Error creating area:', error)
      alert('Failed to create area')
    }
  }

  // Handle update area
  const handleUpdateArea = async () => {
    if (!selectedArea) return

    try {
      const res = await updateAreaAction(selectedArea.id, {
        areaName: areaFormData.areaName!,
        areaCode: areaFormData.areaCode!,
        zone: areaFormData.zone!,
        capacity: areaFormData.capacity || 0,
        currentStock: areaFormData.currentStock || 0,
        allowedHazards: areaFormData.allowedHazards || [],
        restrictions: areaFormData.restrictions || '',
        temperatureZone: areaFormData.temperatureZone || undefined,
        active: areaFormData.active !== undefined ? areaFormData.active : true
      })

      if (res.success && res.data) {
        setAreas(areas.map(a => a.id === selectedArea.id ? res.data! : a))
        loadAreas()
      } else {
        alert('Failed to update area: ' + res.error)
      }
      setShowEditModal(false)
      setSelectedArea(null)
      resetForm()
    } catch (error) {
      console.error('Error updating area:', error)
      alert('Failed to update area')
    }
  }

  // Handle delete area
  const handleDeleteArea = async (id: string) => {
    if (confirm('Are you sure you want to delete this area?')) {
      const res = await deleteAreaAction(id)
      if (res.success) {
        setAreas(areas.filter(a => a.id !== id))
        if (selectedArea?.id === id) setSelectedArea(null)
        loadAreas()
      } else {
        alert('Failed to delete area: ' + res.error)
      }
    }
  }

  // Handle import
  const handleFileImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setUploading(true)

    try {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('warehouseId', warehouseId)
      formData.append('import', 'true')

      // Read CSV file
      const text = await file.text()
      const lines = text.split('\n').filter(line => line.trim())
      const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''))

      const importData = lines.slice(1).map(line => {
        const values = line.split(',').map(v => v.trim().replace(/"/g, ''))
        const data: Record<string, string> = {}
        headers.forEach((header, idx) => {
          data[header] = values[idx] || ''
        })
        return {
          areaCode: data['Area Code'] || data.areaCode || '',
          areaName: data['Area Name'] || data.areaName || '',
          zone: data.Zone || data.zone || '',
          capacity: parseFloat(data.Capacity || data.capacity || '0'),
          currentStock: parseFloat(data['Current Stock'] || data.currentStock || '0'),
          allowedHazards: (data['Allowed Hazards'] || data.allowedHazards || '').split(';').map((s: string) => s.trim()).filter(Boolean),
          restrictions: data.Restrictions || data.restrictions || ''
        }
      })

      const importedAreas = await warehouseAreaService.importAreas(warehouseId, importData)
      setAreas([...areas, ...importedAreas])
      await fetchStatistics()
      setShowImportModal(false)
      alert(`Successfully imported ${importedAreas.length} areas!`)
    } catch (error) {
      console.error('Import error:', error)
      alert('Import failed. Please check your file format.')
    } finally {
      setUploading(false)
    }
  }

  // Handle export
  const handleExport = async () => {
    try {
      const exportData = await warehouseAreaService.exportAreas({ warehouseId })

      const headers = ['Area Code', 'Area Name', 'Zone', 'Capacity', 'Current Stock', 'Usage %', 'Allowed Hazards', 'Restrictions']
      const csvRows = [
        headers.join(','),
        ...exportData.map(row => [
          row.areaCode,
          row.areaName,
          row.zone,
          row.capacity,
          row.currentStock,
          row.usagePercentage,
          `"${row.allowedHazards}"`,
          `"${row.restrictions}"`
        ].join(','))
      ]

      const csv = csvRows.join('\n')
      const blob = new Blob([csv], { type: 'text/csv' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `${warehouseName.replace(/\s+/g, '-')}-areas-${new Date().toISOString().split('T')[0]}.csv`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
    } catch (error) {
      console.error('Export error:', error)
      alert('Failed to export areas')
    }
  }

  // Reset form
  const resetForm = () => {
    setAreaFormData({
      areaCode: '',
      areaName: '',
      zone: '',
      warehouseId,
      capacity: 0,
      currentStock: 0,
      allowedHazards: [],
      restrictions: '',
      active: true
    })
  }

  // Open edit modal
  const openEditModal = (area: WarehouseArea) => {
    setSelectedArea(area)
    setAreaFormData({
      areaCode: area.areaCode,
      areaName: area.areaName,
      zone: area.zone,
      warehouseId: area.warehouseId,
      capacity: area.capacity,
      currentStock: area.currentStock,
      allowedHazards: area.allowedHazards,
      restrictions: area.restrictions,
      temperatureZone: area.temperatureZone || '',
      active: area.active
    })
    setShowEditModal(true)
  }

  const COLORS = ['#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899']

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-xl font-bold flex items-center gap-2 text-white">
            <i className="ri-grid-line text-cyan-400"></i>
            Warehouse Areas & Zones
          </h3>
          <p className="text-sm text-gray-400">
            {warehouseName
              ? `Physical storage locations in ${warehouseName}`
              : allowStandalone
                ? 'Standalone areas and zones (not linked to a warehouse)'
                : 'Select a warehouse to manage areas'}
          </p>
          {linkedModuleId && (
            <p className="text-xs text-cyan-400 mt-1">
              Linked to {linkedModuleId} module
            </p>
          )}
        </div>

        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={() => setShowImportModal(true)}
            className="px-4 py-2 rounded-lg bg-white/5 border border-white/10 hover:border-cyan-500/50 hover:bg-cyan-500/10 transition flex items-center gap-2 text-white"
          >
            <i className="ri-upload-line"></i>
            <span className="hidden sm:inline">Import</span>
          </button>

          <button
            type="button"
            onClick={handleExport}
            className="px-4 py-2 rounded-lg bg-white/5 border border-white/10 hover:border-green-500/50 hover:bg-green-500/10 transition flex items-center gap-2 text-white"
          >
            <i className="ri-download-line"></i>
            <span className="hidden sm:inline">Export</span>
          </button>

          <button
            type="button"
            onClick={() => {
              resetForm()
              setShowCreateModal(true)
            }}
            className="px-4 py-2 rounded-lg bg-gradient-to-r from-cyan-500 to-blue-600 font-semibold flex items-center gap-2 hover:shadow-lg hover:shadow-cyan-500/50 transition text-white"
          >
            <i className="ri-add-line"></i>
            <span className="hidden sm:inline">Add Area</span>
            <span className="sm:hidden">Add</span>
          </button>
        </div>
      </div>

      {/* Statistics Cards */}
      {statistics && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="p-4 rounded-xl bg-white/5 border border-white/10">
            <div className="text-sm text-gray-400 mb-1">Total Areas</div>
            <div className="text-2xl font-bold text-white">{statistics.totalAreas}</div>
          </div>
          <div className="p-4 rounded-xl bg-white/5 border border-white/10">
            <div className="text-sm text-gray-400 mb-1">Active Areas</div>
            <div className="text-2xl font-bold text-green-400">{statistics.activeAreas}</div>
          </div>
          <div className="p-4 rounded-xl bg-white/5 border border-white/10">
            <div className="text-sm text-gray-400 mb-1">Total Capacity</div>
            <div className="text-2xl font-bold text-cyan-400">{statistics.totalCapacity.toLocaleString()}</div>
          </div>
          <div className="p-4 rounded-xl bg-white/5 border border-white/10">
            <div className="text-sm text-gray-400 mb-1">Avg Utilization</div>
            <div className="text-2xl font-bold text-yellow-400">{statistics.averageUtilization.toFixed(1)}%</div>
          </div>
        </div>
      )}

      {/* Filters and View Toggle */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
        <div className="relative flex-1 min-w-[200px]">
          <i className="ri-search-line absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
          <input
            type="text"
            placeholder="Search areas..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 rounded-lg bg-white/5 border border-white/10 focus:border-cyan-500/50 outline-none text-white placeholder-gray-500"
          />
        </div>

        <select
