                <div className="flex items-center justify-between">
                  <span className="text-white font-medium">{activity}</span>
                  <span className="text-xs text-red-400">Bottleneck</span>
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      )}

      {/* Optimization Recommendations */}
      {optimization && optimization.recommendations.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="p-6 rounded-xl bg-white/5 backdrop-blur-xl border border-white/10"
        >
          <h3 className="text-lg font-semibold text-white mb-4">Optimization Recommendations</h3>
          <div className="space-y-3">
            {optimization.recommendations.map((rec, idx) => (
              <div
                key={idx}
                className={`p-4 rounded-lg border ${
                  rec.priority === 'HIGH' ? 'bg-red-500/10 border-red-500/20' :
                  rec.priority === 'MEDIUM' ? 'bg-yellow-500/10 border-yellow-500/20' :
                  'bg-blue-500/10 border-blue-500/20'
                }`}
              >
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <div className="text-white font-medium mb-1">{rec.activity}</div>
                    <div className="text-sm text-[#9ca3af] mb-2">{rec.issue}</div>
                    <div className="text-sm text-cyan-400">{rec.recommendation}</div>
                  </div>
                  <span className={`px-2 py-1 rounded text-xs ${
                    rec.priority === 'HIGH' ? 'bg-red-500/20 text-red-400' :
