'use client'

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts'
import type { DemandForecast, InventoryOptimization, ABCXYZClassification } from '@/lib/services/wms/aiAnalyticsService'
import { format } from 'date-fns'

interface AIAnalyticsDashboardProps {
  skuId: string
  skuCode: string
}

const COLORS = ['#06b6d4', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899']

export default function AIAnalyticsDashboard({ skuId, skuCode }: AIAnalyticsDashboardProps) {
  const [loading, setLoading] = useState(true)
  const [forecast, setForecast] = useState<DemandForecast | null>(null)
  const [optimization, setOptimization] = useState<InventoryOptimization | null>(null)
  const [classification, setClassification] = useState<ABCXYZClassification | null>(null)
  const [safetyStock, setSafetyStock] = useState<any>(null)
  const [reorderPoint, setReorderPoint] = useState<any>(null)
  const [selectedPeriod, setSelectedPeriod] = useState<'DAILY' | 'WEEKLY' | 'MONTHLY' | 'QUARTERLY'>('MONTHLY')
  const [applyingOptimization, setApplyingOptimization] = useState(false)

  useEffect(() => {
    loadAnalytics()
  }, [skuId, selectedPeriod])

  const loadAnalytics = async () => {
    setLoading(true)
    try {
      const response = await fetch(`/api/wms/sku/analytics?skuId=${skuId}&type=all`)
      const result = await response.json()

      if (result.success && result.data) {
        setForecast(result.data.forecast || null)
        setOptimization(result.data.optimization || null)
        setClassification(result.data.classification || null)
        setSafetyStock(result.data.safetyStock || null)
        setReorderPoint(result.data.reorderPoint || null)
      }
    } catch (error) {
      console.error('Error loading analytics:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleApplyOptimization = async () => {
    if (!optimization) return

    setApplyingOptimization(true)
    try {
      const response = await fetch('/api/wms/sku/analytics/apply', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          skuId,
          optimization,
          safetyStock,
          reorderPoint,
        }),
      })

      const result = await response.json()

      if (result.success) {
        alert(`Optimization applied successfully!\n\nApplied:\n${result.data.appliedRecommendations.join('\n')}`)
        await loadAnalytics() // Reload to show updated values
      } else {
        alert(`Failed to apply optimization: ${result.error}`)
      }
    } catch (error) {
      console.error('Error applying optimization:', error)
      alert('Error applying optimization')
    } finally {
      setApplyingOptimization(false)
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-cyan-600 mx-auto"></div>
          <p className="mt-4 text-gray-400">Loading AI analytics...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">AI Analytics Dashboard</h2>
          <p className="text-gray-400">SKU: {skuCode}</p>
        </div>
        <div className="flex items-center gap-2">
          <select
            value={selectedPeriod}
            onChange={(e) => setSelectedPeriod(e.target.value as any)}
            className="bg-white/5 border border-white/10 rounded-lg px-4 py-2 text-sm text-white"
          >
            <option value="DAILY">Daily</option>
            <option value="WEEKLY">Weekly</option>
            <option value="MONTHLY">Monthly</option>
            <option value="QUARTERLY">Quarterly</option>
          </select>
          <button
            onClick={loadAnalytics}
            className="px-4 py-2 bg-cyan-600 hover:bg-cyan-700 rounded-lg text-white text-sm font-medium"
          >
            <i className="ri-refresh-line mr-1"></i>
            Refresh
          </button>
        </div>
      </div>

      {/* Demand Forecast */}
      {forecast && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6"
        >
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-white">Demand Forecast</h3>
            <div className="flex items-center gap-2">
              <span className="px-3 py-1 rounded text-xs font-medium bg-cyan-500/20 text-cyan-400">
                {forecast.forecastPeriod}
              </span>
              <span className="px-3 py-1 rounded text-xs font-medium bg-blue-500/20 text-blue-400">
