                  optimization.recommendedAction === 'INCREASE' ? 'bg-green-500/20 border-green-500/30' :
                  optimization.recommendedAction === 'DECREASE' ? 'bg-red-500/20 border-red-500/30' :
                  'bg-cyan-500/20 border-cyan-500/30'
                }`}>
                  <div className="text-xs mb-1" style={{
                    color: optimization.recommendedAction === 'INCREASE' ? '#4ade80' :
                           optimization.recommendedAction === 'DECREASE' ? '#f87171' : '#06b6d4'
