                    <div className="text-sm text-white">{reorderPoint.currentReorderPoint}</div>
                  </div>
                  <div className="p-2 bg-purple-500/20 rounded-lg border border-purple-500/30">
                    <div className="text-xs text-purple-400 mb-1">Recommended</div>
                    <div className="text-sm font-semibold text-purple-400">{reorderPoint.recommendedReorderPoint}</div>
                  </div>
                </div>
                <div className="text-xs text-gray-400">
                  Method: {reorderPoint.calculationMethod}
