class VisionDatabaseService {
  /**
   * Create vision analysis
   */
  async createAnalysis(data: VisionAnalysisCreate) {
    try {
      const analysis = await prisma.visionAnalysis.create({
        data: {
          analysisId: data.analysisId,
          tenantId: data.tenantId,
          userId: data.userId,
          imageUrl: data.imageUrl,
          thumbnailUrl: data.thumbnailUrl,
          fileUrl: data.fileUrl,
          fileName: data.fileName,
          fileSize: data.fileSize,
          mimeType: data.mimeType,
          imageSize: data.imageSize as any,
          analysis: data.analysis as any,
          analysisMode: data.analysisMode,
          provider: data.provider,
          model: data.model,
          processingTime: data.processingTime,
          context: data.context,
          module: data.module,
          moduleContext: data.moduleContext as any,
          totalIssues: data.totalIssues || 0,
          criticalIssues: data.criticalIssues || 0,
          complianceScore: data.complianceScore,
          isCompliant: data.isCompliant ?? true,
          relatedRecordId: data.relatedRecordId,
          relatedRecordType: data.relatedRecordType,
          metadata: data.metadata as any,
          tags: data.tags || [],
        },
      })

      // Emit events
      await eventBus.publish({
        type: 'ai.vision.analysis.created',
        aggregateId: analysis.id,
        aggregateType: 'VisionAnalysis',
        payload: {
          analysisId: analysis.analysisId,
          tenantId: analysis.tenantId,
          module: analysis.module,
          totalIssues: analysis.totalIssues,
          isCompliant: analysis.isCompliant,
        },
        metadata: {
          userId: data.userId,
          timestamp: new Date().toISOString(),
        },
      })

      // Publish analysis completed event
      await visionEventIntegration.publishAnalysisCompleted(
        analysis.analysisId,
        analysis.tenantId || '',
        {
          totalIssues: analysis.totalIssues,
          criticalIssues: analysis.criticalIssues,
          isCompliant: analysis.isCompliant,
          module: analysis.module,
        }
      )

      // Check for compliance violations
      if (analysis.analysis && typeof analysis.analysis === 'object') {
        const analysisData = analysis.analysis as any
        if (analysisData.complianceIssues && Array.isArray(analysisData.complianceIssues) && analysisData.complianceIssues.length > 0) {
          await visionEventIntegration.publishComplianceViolation(
            analysis.analysisId,
            analysis.tenantId || '',
            analysisData.complianceIssues
          )
        }
      }

      // Create history entry
      await this.createHistory({
        analysisId: analysis.id,
        tenantId: data.tenantId,
        userId: data.userId,
        action: 'created',
        metadata: { source: 'api' },
      })

      return analysis
    } catch (error) {
      console.error('Error creating vision analysis:', error)
      throw error
    }
  }

  /**
   * Get vision analysis by ID
   */
  async getAnalysisById(id: string, tenantId?: string) {
    try {
      const analysis = await prisma.visionAnalysis.findFirst({
        where: {
          OR: [
            { id },
            { analysisId: id },
          ],
          ...(tenantId ? { tenantId } : {}),
        },
        include: {
          patterns: {
            take: 10,
            orderBy: { lastSeen: 'desc' },
          },
          feedback: {
            take: 5,
            orderBy: { createdAt: 'desc' },
          },
          history: {
            take: 20,
            orderBy: { createdAt: 'desc' },
          },
        },
      })

      return analysis
    } catch (error) {
      console.error('Error getting vision analysis:', error)
      throw error
    }
  }

  /**
   * Get vision analysis by analysisId
   */
  async getAnalysisByAnalysisId(analysisId: string, tenantId?: string) {
    return this.getAnalysisById(analysisId, tenantId)
  }

  /**
   * List vision analyses with filters
   */
  async listAnalyses(options: {
    tenantId?: string
    userId?: string
    module?: string
    relatedRecordType?: string
    isCompliant?: boolean
    limit?: number
    offset?: number
    orderBy?: 'createdAt' | 'updatedAt' | 'totalIssues'
    order?: 'asc' | 'desc'
  }) {
    try {
      const {
        tenantId,
        userId,
        module,
        relatedRecordType,
        isCompliant,
        limit = 50,
        offset = 0,
        orderBy = 'createdAt',
        order = 'desc',
      } = options

      const analyses = await prisma.visionAnalysis.findMany({
        where: {
          ...(tenantId ? { tenantId } : {}),
          ...(userId ? { userId } : {}),
          ...(module ? { module } : {}),
          ...(relatedRecordType ? { relatedRecordType } : {}),
          ...(isCompliant !== undefined ? { isCompliant } : {}),
        },
        take: limit,
        skip: offset,
        orderBy: {
          [orderBy]: order,
        },
        include: {
          patterns: {
            take: 3,
            orderBy: { lastSeen: 'desc' },
          },
        },
      })

      const total = await prisma.visionAnalysis.count({
        where: {
          ...(tenantId ? { tenantId } : {}),
          ...(userId ? { userId } : {}),
          ...(module ? { module } : {}),
          ...(relatedRecordType ? { relatedRecordType } : {}),
          ...(isCompliant !== undefined ? { isCompliant } : {}),
        },
      })

      return {
        analyses,
        total,
        limit,
        offset,
      }
    } catch (error) {
      console.error('Error listing vision analyses:', error)
      throw error
    }
  }

  /**
   * Update vision analysis
   */
  async updateAnalysis(id: string, data: VisionAnalysisUpdate, tenantId?: string, userId?: string) {
    try {
      const existing = await prisma.visionAnalysis.findFirst({
        where: {
          OR: [
            { id },
            { analysisId: id },
          ],
          ...(tenantId ? { tenantId } : {}),
        },
      })

      if (!existing) {
        throw new Error('Vision analysis not found')
      }

      const previousState = {
        analysis: existing.analysis,
        totalIssues: existing.totalIssues,
        criticalIssues: existing.criticalIssues,
        complianceScore: existing.complianceScore,
        isCompliant: existing.isCompliant,
      }

      const analysis = await prisma.visionAnalysis.update({
        where: { id: existing.id },
        data: {
          ...(data.analysis !== undefined ? { analysis: data.analysis as any } : {}),
          ...(data.totalIssues !== undefined ? { totalIssues: data.totalIssues } : {}),
          ...(data.criticalIssues !== undefined ? { criticalIssues: data.criticalIssues } : {}),
          ...(data.complianceScore !== undefined ? { complianceScore: data.complianceScore } : {}),
          ...(data.isCompliant !== undefined ? { isCompliant: data.isCompliant } : {}),
          ...(data.metadata !== undefined ? { metadata: data.metadata as any } : {}),
          ...(data.tags !== undefined ? { tags: data.tags } : {}),
        },
      })

      // Emit event
      await eventBus.publish({
        type: 'ai.vision.analysis.updated',
        aggregateId: analysis.id,
        aggregateType: 'VisionAnalysis',
        payload: {
          analysisId: analysis.analysisId,
          tenantId: analysis.tenantId,
          changes: data,
        },
        metadata: {
          userId,
          timestamp: new Date().toISOString(),
        },
      })

      // Create history entry
      await this.createHistory({
        analysisId: analysis.id,
        tenantId: tenantId || existing.tenantId || undefined,
        userId,
        action: 'updated',
        changes: data,
        previousState,
        metadata: { source: 'api' },
      })

      return analysis
    } catch (error) {
      console.error('Error updating vision analysis:', error)
      throw error
    }
  }

  /**
   * Delete vision analysis
   */
  async deleteAnalysis(id: string, tenantId?: string, userId?: string) {
    try {
      const existing = await prisma.visionAnalysis.findFirst({
        where: {
          OR: [
            { id },
            { analysisId: id },
          ],
          ...(tenantId ? { tenantId } : {}),
        },
      })

      if (!existing) {
        throw new Error('Vision analysis not found')
      }

      await prisma.visionAnalysis.delete({
        where: { id: existing.id },
      })

      // Emit event
      await eventBus.publish({
        type: 'ai.vision.analysis.deleted',
        aggregateId: existing.id,
        aggregateType: 'VisionAnalysis',
        payload: {
          analysisId: existing.analysisId,
          tenantId: existing.tenantId,
        },
        metadata: {
          userId,
          timestamp: new Date().toISOString(),
        },
      })

      return { success: true }
    } catch (error) {
      console.error('Error deleting vision analysis:', error)
      throw error
    }
  }

