  /**
   * Get analytics/metrics
   */
  async getMetrics(options: {
    tenantId?: string
    startDate?: Date
    endDate?: Date
    period?: 'daily' | 'weekly' | 'monthly'
  }) {
    try {
      const { tenantId, startDate, endDate, period = 'daily' } = options

      // Get analyses in date range
      const analyses = await prisma.visionAnalysis.findMany({
        where: {
          ...(tenantId ? { tenantId } : {}),
          ...(startDate || endDate
            ? {
                createdAt: {
                  ...(startDate ? { gte: startDate } : {}),
                  ...(endDate ? { lte: endDate } : {}),
                },
              }
            : {}),
        },
        select: {
          totalIssues: true,
          criticalIssues: true,
          complianceScore: true,
          isCompliant: true,
          processingTime: true,
          module: true,
          analysisMode: true,
          createdAt: true,
        },
      })

      // Calculate metrics
      const totalAnalyses = analyses.length
      const totalIssues = analyses.reduce((sum, a) => sum + a.totalIssues, 0)
      const criticalIssues = analyses.reduce((sum, a) => sum + a.criticalIssues, 0)
      const averageScore =
        analyses.filter((a) => a.complianceScore !== null).length > 0
          ? analyses
              .filter((a) => a.complianceScore !== null)
              .reduce((sum, a) => sum + (a.complianceScore || 0), 0) /
            analyses.filter((a) => a.complianceScore !== null).length
          : null
      const averageTime =
        analyses.filter((a) => a.processingTime !== null).length > 0
          ? analyses
              .filter((a) => a.processingTime !== null)
              .reduce((sum, a) => sum + (a.processingTime || 0), 0) /
            analyses.filter((a) => a.processingTime !== null).length
          : null

      // By module
      const byModule: Record<string, { count: number; issues: number }> = {}
      analyses.forEach((a) => {
        const module = a.module || 'unknown'
        if (!byModule[module]) {
          byModule[module] = { count: 0, issues: 0 }
        }
        byModule[module].count++
        byModule[module].issues += a.totalIssues
      })

      // By analysis type
      const byAnalysisType: Record<string, number> = {}
      analyses.forEach((a) => {
        const type = a.analysisMode || 'standard'
        byAnalysisType[type] = (byAnalysisType[type] || 0) + 1
      })

      return {
        totalAnalyses,
        totalIssues,
        criticalIssues,
        averageScore: averageScore ? Number(averageScore.toFixed(2)) : null,
        averageTime: averageTime ? Math.round(averageTime) : null,
        totalProcessingTime: analyses.reduce((sum, a) => sum + (a.processingTime || 0), 0),
        byModule,
        byAnalysisType,
      }
    } catch (error) {
      console.error('Error getting vision metrics:', error)
      throw error
    }
  }
}

