/**
 * AWS SES Email Adapter
 * 
 * Amazon Simple Email Service (SES) adapter
 * Requires AWS credentials (via environment variables or IAM role)
 * 
 * Note: @aws-sdk/client-ses package must be installed separately:
 * npm install @aws-sdk/client-ses
 */

import type { EmailMessage, EmailSendResult } from '../../types'
import { EmailAdapterBase } from '../base/EmailAdapterBase'

// Lazy load AWS SDK - only import if package is installed
// Using require() to avoid webpack static analysis
let SESClient: any = null
let SendEmailCommand: any = null
function loadAWSSES() {
  if (SESClient) return { SESClient, SendEmailCommand }
  try {
    // Use require() to avoid webpack static analysis
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const awsSes = require('@aws-sdk/client-ses')
    SESClient = awsSes.SESClient
    SendEmailCommand = awsSes.SendEmailCommand
    return { SESClient, SendEmailCommand }
  } catch (error) {
    throw new Error(
      'AWS SES package not installed. Install it with: npm install @aws-sdk/client-ses'
    )
  }
}

export interface AWSSESConfig {
  region?: string
  accessKeyId?: string
  secretAccessKey?: string
  from?: {
    email: string
    name?: string
  }
}

export class AWSSESAdapter extends EmailAdapterBase {
  readonly id = 'aws-ses'
  readonly name = 'AWS SES'
  readonly provider = 'AWS_SES' as const

  private client: SESClient | null = null

  constructor(config?: Record<string, any>) {
    super(config)
    this.initializeClient()
  }

  private initializeClient(): void {
    const config: AWSSESConfig = this.config as AWSSESConfig

    const { SESClient: SESClientClass } = loadAWSSES()
    this.client = new SESClientClass({
      region: config.region || process.env.AWS_REGION || 'us-east-1',
      credentials: config.accessKeyId && config.secretAccessKey
        ? {
            accessKeyId: config.accessKeyId,
            secretAccessKey: config.secretAccessKey,
          }
        : undefined, // Will use IAM role or environment variables
    })
  }

  async testConnection(): Promise<{ success: boolean; message: string }> {
    try {
      try {
        if (!this.client) {
          this.initializeClient()
        }

        if (!this.client) {
          return { success: false, message: 'Failed to initialize AWS SES client' }
        }

        return { success: true, message: 'AWS SES client initialized' }
      } catch (error) {
        if (error instanceof Error && error.message.includes('not installed')) {
          return { success: false, message: error.message }
        }
        throw error
      }
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'AWS SES connection failed',
      }
    }
  }

  async sendEmail(message: EmailMessage): Promise<EmailSendResult> {
    try {
      try {
        if (!this.client) {
          this.initializeClient()
        }

        if (!this.client) {
          return {
            success: false,
            error: 'AWS SES client not initialized',
            errorCode: 'CLIENT_NOT_INITIALIZED',
          }
        }
      } catch (error) {
        if (error instanceof Error && error.message.includes('not installed')) {
          return {
            success: false,
            error: error.message,
            errorCode: 'PACKAGE_NOT_INSTALLED',
          }
        }
        throw error
      }

      const { SendEmailCommand: SendEmailCommandClass } = loadAWSSES()

      const fromAddress = message.from || this.config.from || {
        email: process.env.AWS_SES_FROM_EMAIL || 'noreply@example.com',
        name: 'BlueDXP Platform',
      }

      const toAddresses = this.normalizeAddresses(message.to).map(addr => addr.email)
      const ccAddresses = message.cc ? this.normalizeAddresses(message.cc).map(addr => addr.email) : undefined
      const bccAddresses = message.bcc ? this.normalizeAddresses(message.bcc).map(addr => addr.email) : undefined

      // If we have HTML or attachments, we need to use SendRawEmailCommand
      // For simple text/HTML emails, we can use SendEmailCommand
      if (message.attachments && message.attachments.length > 0) {
        // For attachments, we'd need to construct a raw email
        // This is a simplified version - full implementation would use nodemailer to create raw email
        return {
          success: false,
          error: 'Attachments not yet supported in AWS SES adapter',
          errorCode: 'FEATURE_NOT_IMPLEMENTED',
        }
      }

      const command = new SendEmailCommandClass({
        Source: fromAddress.name 
          ? `${fromAddress.name} <${fromAddress.email}>`
          : fromAddress.email,
        Destination: {
          ToAddresses: toAddresses,
          CcAddresses: ccAddresses,
          BccAddresses: bccAddresses,
        },
        Message: {
          Subject: {
            Data: message.subject,
            Charset: 'UTF-8',
          },
          Body: {
            ...(message.htmlBody ? {
              Html: {
                Data: message.htmlBody,
                Charset: 'UTF-8',
              },
            } : {}),
            ...(message.textBody ? {
              Text: {
                Data: message.textBody,
                Charset: 'UTF-8',
              },
            } : {}),
          },
        },
        ReplyToAddresses: message.replyTo ? [message.replyTo.email] : undefined,
        Tags: [
          ...(message.moduleId ? [{ Name: 'ModuleId', Value: message.moduleId }] : []),
          ...(message.entityId ? [{ Name: 'EntityId', Value: message.entityId }] : []),
          ...(message.entityType ? [{ Name: 'EntityType', Value: message.entityType }] : []),
          { Name: 'TenantId', Value: message.tenantId },
          ...(message.tags?.map(tag => ({ Name: 'Tag', Value: tag })) || []),
        ],
      })

      const response = await this.client.send(command)

      return {
        success: true,
        messageId: response.MessageId,
        provider: 'AWS_SES',
        providerResponse: response,
      }
    } catch (error: any) {
      return {
        success: false,
        error: error.message || 'Failed to send email via AWS SES',
        errorCode: error.name || 'SEND_FAILED',
        provider: 'AWS_SES',
        providerResponse: error,
      }
    }
  }

  async updateConfig(config: Partial<Record<string, any>>): Promise<void> {
    await super.updateConfig(config)
    this.client = null // Reset client to reinitialize with new config
  }
}

/**
 * SendGrid Email Adapter
 * 
 * SendGrid email provider adapter
 * Requires SENDGRID_API_KEY environment variable
 * 
 * Note: @sendgrid/mail package must be installed separately:
 * npm install @sendgrid/mail
 */

import type { EmailMessage, EmailSendResult } from '../../types'
import { EmailAdapterBase } from '../base/EmailAdapterBase'

// Lazy load SendGrid - only import if package is installed
// Using require() to avoid webpack static analysis
let sgMail: any = null
async function loadSendGrid() {
  if (sgMail) return sgMail
  try {
    // Use require() to avoid webpack static analysis
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    sgMail = require('@sendgrid/mail')
    return sgMail
  } catch (error) {
    throw new Error(
      'SendGrid package not installed. Install it with: npm install @sendgrid/mail'
    )
  }
}

export interface SendGridConfig {
  apiKey: string
  from?: {
    email: string
    name?: string
  }
}

export class SendGridAdapter extends EmailAdapterBase {
  readonly id = 'sendgrid'
  readonly name = 'SendGrid'
  readonly provider = 'SENDGRID' as const

  private apiKey: string | null = null

  constructor(config?: Record<string, any>) {
    super(config)
    if (config?.apiKey) {
      this.apiKey = config.apiKey
    } else if (process.env.SENDGRID_API_KEY) {
      this.apiKey = process.env.SENDGRID_API_KEY
    }
  }

  private ensureInitialized(): void {
    if (!this.apiKey) {
      throw new Error('SendGrid API key not configured')
    }
    loadSendGrid()
    sgMail.setApiKey(this.apiKey)
  }

  async testConnection(): Promise<{ success: boolean; message: string }> {
    try {
      if (!this.apiKey) {
        return { success: false, message: 'SendGrid API key not provided' }
      }

      try {
        loadSendGrid()
        // SendGrid doesn't have a direct test endpoint, so we'll just verify the API key is set
        return { success: true, message: 'SendGrid API key configured' }
      } catch (error) {
        return {
          success: false,
          message: error instanceof Error ? error.message : 'SendGrid package not installed',
        }
      }
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'SendGrid connection failed',
      }
    }
  }

  async sendEmail(message: EmailMessage): Promise<EmailSendResult> {
    try {
      this.ensureInitialized()

      const fromAddress = message.from || this.config.from || {
        email: process.env.SENDGRID_FROM_EMAIL || 'noreply@example.com',
        name: 'BlueDXP Platform',
      }

      const msg = {
        from: fromAddress,
        to: this.normalizeAddresses(message.to),
        cc: message.cc ? this.normalizeAddresses(message.cc) : undefined,
        bcc: message.bcc ? this.normalizeAddresses(message.bcc) : undefined,
        replyTo: message.replyTo,
        subject: message.subject,
        html: message.htmlBody,
        text: message.textBody,
        attachments: message.attachments?.map(att => ({
          content: typeof att.content === 'string' 
            ? att.content 
            : att.content.toString('base64'),
          filename: att.filename,
          type: att.contentType,
          contentId: att.contentId,
          disposition: att.disposition || 'attachment',
        })),
        customArgs: {
          moduleId: message.moduleId || '',
          entityId: message.entityId || '',
          entityType: message.entityType || '',
          tenantId: message.tenantId,
          ...(message.tags ? { tags: message.tags.join(',') } : {}),
        },
        trackingSettings: {
          clickTracking: {
            enable: message.trackingEnabled ?? true,
          },
          openTracking: {
            enable: message.trackingEnabled ?? true,
          },
        },
        mailSettings: {
          unsubscribe: message.unsubscribeUrl ? {
            enable: true,
            text: 'Unsubscribe',
            html: `<a href="${message.unsubscribeUrl}">Unsubscribe</a>`,
          } : undefined,
        },
      }

      const [response] = await sgMail.send(msg)

      return {
        success: true,
        messageId: response.headers['x-message-id'] || `sg-${Date.now()}`,
        provider: 'SENDGRID',
        providerResponse: response,
      }
    } catch (error: any) {
      return {
        success: false,
        error: error.response?.body?.errors?.[0]?.message || error.message || 'Failed to send email',
        errorCode: error.code || 'SEND_FAILED',
        provider: 'SENDGRID',
        providerResponse: error.response,
      }
    }
  }

  async getEmailStatus(messageId: string): Promise<import('../../types').EmailStatusUpdate | null> {
    // SendGrid provides webhook-based status updates
    // This would need to be implemented with webhook handlers
    // For now, return null as status tracking requires webhook setup
    return null
  }

  async updateConfig(config: Partial<Record<string, any>>): Promise<void> {
    await super.updateConfig(config)
    if (config.apiKey) {
      this.apiKey = config.apiKey as string
    }
  }
}

/**
 * SMTP Email Adapter
 * 
 * Standard SMTP email adapter using nodemailer
 * Supports any SMTP server (Gmail, Outlook, custom SMTP, etc.)
 * 
 * Note: nodemailer package must be installed separately:
 * npm install nodemailer
 */

import type { Transporter } from 'nodemailer'
import type { EmailMessage, EmailSendResult } from '../../types'
import { EmailAdapterBase } from '../base/EmailAdapterBase'

// Lazy load nodemailer - only import if package is installed
// Using require() to avoid webpack static analysis
// Only load on server side (nodemailer uses Node.js fs module)
let nodemailer: any = null
function loadNodemailer() {
  // Only load on server side
  if (typeof window !== 'undefined') {
    throw new Error('nodemailer can only be used on the server side')
  }

  if (nodemailer) return nodemailer
  try {
    // Use require() to avoid webpack static analysis
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    nodemailer = require('nodemailer')
    return nodemailer
  } catch (error) {
    throw new Error(
      'nodemailer package not installed. Install it with: npm install nodemailer'
    )
  }
}

export interface SMTPConfig {
  host: string
  port: number
  secure?: boolean // true for 465, false for other ports
  auth: {
    user: string
    pass: string
  }
  from?: {
    email: string
    name?: string
  }
  tls?: {
    rejectUnauthorized?: boolean
  }
}

export class SMTPAdapter extends EmailAdapterBase {
  readonly id = 'smtp'
  readonly name = 'SMTP'
  readonly provider = 'SMTP' as const

  private transporter: Transporter | null = null
  private smtpConfig: SMTPConfig | null = null

  constructor(config?: Record<string, any>) {
    super(config)
    if (config) {
      this.smtpConfig = config as SMTPConfig
      this.initializeTransporter()
    }
  }

  private initializeTransporter(): void {
    if (!this.smtpConfig) return

    loadNodemailer()
    this.transporter = nodemailer.createTransport({
      host: this.smtpConfig.host,
      port: this.smtpConfig.port,
      secure: this.smtpConfig.secure ?? (this.smtpConfig.port === 465),
      auth: {
        user: this.smtpConfig.auth.user,
        pass: this.smtpConfig.auth.pass,
      },
      tls: this.smtpConfig.tls,
    })
  }

  async testConnection(): Promise<{ success: boolean; message: string }> {
    try {
      if (!this.smtpConfig) {
        return { success: false, message: 'SMTP configuration not provided' }
      }

      try {
        if (!this.transporter) {
          this.initializeTransporter()
        }

        if (!this.transporter) {
          return { success: false, message: 'Failed to initialize SMTP transporter' }
        }

        await this.transporter.verify()
        return { success: true, message: 'SMTP connection successful' }
      } catch (error) {
        if (error instanceof Error && error.message.includes('not installed')) {
          return { success: false, message: error.message }
        }
        return {
          success: false,
          message: error instanceof Error ? error.message : 'SMTP connection failed',
        }
      }
    } catch (error) {
      return {
        success: false,
        message: error instanceof Error ? error.message : 'SMTP connection failed',
      }
    }
  }

  async sendEmail(message: EmailMessage): Promise<EmailSendResult> {
    try {
      if (!this.smtpConfig) {
        return {
          success: false,
          error: 'SMTP configuration not provided',
          errorCode: 'CONFIG_MISSING',
        }
      }

      try {
        if (!this.transporter) {
          this.initializeTransporter()
        }

        if (!this.transporter) {
          return {
            success: false,
            error: 'Failed to initialize SMTP transporter',
            errorCode: 'INIT_FAILED',
          }
        }
      } catch (error) {
        if (error instanceof Error && error.message.includes('not installed')) {
          return {
            success: false,
            error: error.message,
            errorCode: 'PACKAGE_NOT_INSTALLED',
          }
        }
        throw error
      }

      // Use default from if not provided in message
      const fromAddress = message.from || this.smtpConfig?.from || {
        email: this.smtpConfig?.auth.user || 'noreply@example.com',
        name: 'BlueDXP Platform',
      }

      const mailOptions = {
        from: this.formatAddresses([fromAddress]),
        to: this.formatAddresses(this.normalizeAddresses(message.to)),
        cc: message.cc ? this.formatAddresses(this.normalizeAddresses(message.cc)) : undefined,
        bcc: message.bcc ? this.formatAddresses(this.normalizeAddresses(message.bcc)) : undefined,
        replyTo: message.replyTo ? this.formatAddresses([message.replyTo]) : undefined,
        subject: message.subject,
        html: message.htmlBody,
        text: message.textBody,
        attachments: message.attachments?.map(att => ({
          filename: att.filename,
          content: att.content,
          contentType: att.contentType,
          cid: att.contentId,
          contentDisposition: att.disposition || 'attachment',
        })),
        headers: {
          'X-Module-ID': message.moduleId || '',
          'X-Entity-ID': message.entityId || '',
          'X-Entity-Type': message.entityType || '',
          'X-Tenant-ID': message.tenantId,
          ...(message.tags ? { 'X-Tags': message.tags.join(',') } : {}),
        },
      }

      const info = await this.transporter.sendMail(mailOptions)

      return {
        success: true,
        messageId: info.messageId,
        provider: 'SMTP',
        providerResponse: info,
      }
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to send email',
        errorCode: 'SEND_FAILED',
        provider: 'SMTP',
        providerResponse: error,
      }
    }
  }

  async updateConfig(config: Partial<Record<string, any>>): Promise<void> {
    await super.updateConfig(config)
    this.smtpConfig = { ...this.smtpConfig, ...config } as SMTPConfig
    this.transporter = null // Reset transporter to reinitialize with new config
  }
}

/**
 * Analytics Aggregation Service
 * 
 * Aggregates analytics from all modules into unified view
 */

import type { UnifiedAnalytics, ModuleAnalytics, CrossModuleAnalytics } from '@/types/intelligence-analytics'
import { eventStore } from '@/lib/services/event-store'

export class AnalyticsAggregationService {
  private static instance: AnalyticsAggregationService
  private isInitialized = false

  private constructor() {}

  static getInstance(): AnalyticsAggregationService {
    if (!AnalyticsAggregationService.instance) {
      AnalyticsAggregationService.instance = new AnalyticsAggregationService()
    }
    return AnalyticsAggregationService.instance
  }

  /**
   * Initialize the analytics service
   */
  async initialize(tenantId: string): Promise<void> {
    if (this.isInitialized) {
      return
    }

    console.log('📊 Initializing Analytics Aggregation Service...')
    this.isInitialized = true
    console.log('✅ Analytics Aggregation Service initialized')
  }

  /**
   * Aggregate analytics
   */
  async aggregate(request: {
    tenantId: string
    moduleIds?: string[]
    timeRange?: { start: Date | string; end: Date | string }
  }): Promise<UnifiedAnalytics> {
    const { tenantId, moduleIds = [], timeRange } = request

    const timeRangeFinal = timeRange || {
      start: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000),
      end: new Date(),
    }

    // Get module analytics
    const moduleAnalytics = await this.getModuleAnalytics(tenantId, moduleIds, timeRangeFinal)

    // Get cross-module analytics
    const crossModuleAnalytics = await this.getCrossModuleAnalytics(tenantId, moduleIds, timeRangeFinal)

    // Calculate aggregated metrics
    const aggregatedMetrics = this.calculateAggregatedMetrics(moduleAnalytics)

    // Generate insights
    const insights = await this.generateInsights(moduleAnalytics, crossModuleAnalytics)

    // Analyze trends
    const trends = await this.analyzeTrends(tenantId, moduleIds, timeRangeFinal)

    return {
      id: `analytics-${tenantId}-${Date.now()}`,
      timeRange: timeRangeFinal,
      moduleAnalytics,
      crossModuleAnalytics,
      aggregatedMetrics,
      insights,
      trends,
      tenantId,
      generatedAt: new Date(),
    }
  }

  /**
   * Get module analytics
   */
  private async getModuleAnalytics(
    tenantId: string,
    moduleIds: string[],
    timeRange: { start: Date | string; end: Date | string }
  ): Promise<Record<string, ModuleAnalytics>> {
    const analytics: Record<string, ModuleAnalytics> = {}

    // Get events for each module
    const events = await eventStore.getEventsByTimeRange(
      new Date(timeRange.start).getTime(),
      new Date(timeRange.end).getTime()
    )

    const moduleEvents = new Map<string, any[]>()
    for (const event of events) {
      if (event.metadata?.tenantId === tenantId) {
        const module = this.extractModule(event.type)
        if (moduleIds.length === 0 || moduleIds.includes(module)) {
          if (!moduleEvents.has(module)) {
            moduleEvents.set(module, [])
          }
          moduleEvents.get(module)!.push(event)
        }
      }
    }

    // Create analytics for each module
    for (const [module, moduleEventList] of moduleEvents.entries()) {
      analytics[module] = {
        moduleId: module,
        metrics: {
          totalEvents: moduleEventList.length,
          errorEvents: moduleEventList.filter(e => e.type.toLowerCase().includes('error')).length,
          successRate: ((moduleEventList.length - moduleEventList.filter(e => e.type.toLowerCase().includes('error')).length) / moduleEventList.length) * 100,
        },
        trends: [],
        insights: [],
        anomalies: [],
        performance: {
          score: 75,
          trend: 'STABLE',
        },
      }
    }

    return analytics
  }

  /**
   * Get cross-module analytics
   */
  private async getCrossModuleAnalytics(
    tenantId: string,
    moduleIds: string[],
    timeRange: { start: Date | string; end: Date | string }
  ): Promise<CrossModuleAnalytics> {
    return {
      correlations: [],
      patterns: [],
      bottlenecks: [],
      optimizationOpportunities: [],
    }
  }

  /**
   * Calculate aggregated metrics
   */
  private calculateAggregatedMetrics(moduleAnalytics: Record<string, ModuleAnalytics>): any {
    const modules = Object.values(moduleAnalytics)
    return {
      totalEvents: modules.reduce((sum, m) => sum + m.metrics.totalEvents, 0),
      totalIssues: modules.reduce((sum, m) => sum + m.metrics.errorEvents, 0),
      averageResolutionTime: 24, // TODO: Calculate
      complianceRate: 85, // TODO: Calculate
      efficiency: modules.reduce((sum, m) => sum + m.performance.score, 0) / modules.length,
      cost: 0, // TODO: Calculate
      savings: 0, // TODO: Calculate
    }
  }

  /**
   * Generate insights
   */
  private async generateInsights(
    moduleAnalytics: Record<string, ModuleAnalytics>,
    crossModuleAnalytics: CrossModuleAnalytics
  ): Promise<any[]> {
    const insights: any[] = []

    // Generate insights from module analytics
    for (const [moduleId, analytics] of Object.entries(moduleAnalytics)) {
      if (analytics.metrics.errorEvents > 10) {
        insights.push({
          id: `insight-${moduleId}-errors`,
          type: 'RISK',
          title: `High Error Rate in ${moduleId}`,
          description: `${analytics.metrics.errorEvents} errors detected in ${moduleId} module`,
          impact: 'HIGH',
          confidence: 85,
          affectedModules: [moduleId],
          recommendations: ['Investigate root cause', 'Review error logs'],
        })
      }
    }

    return insights
  }

  /**
   * Analyze trends
   */
  private async analyzeTrends(
    tenantId: string,
    moduleIds: string[],
    timeRange: { start: Date | string; end: Date | string }
  ): Promise<any[]> {
    // Simple trend analysis
    return []
  }

  /**
   * Extract module from event type
   */
  private extractModule(eventType: string): string {
    const parts = eventType.split('.')
    return parts[0] || 'unknown'
  }
}

