        type: pattern.pattern === 'increasing' ? 'OPPORTUNITY' : pattern.pattern === 'decreasing' ? 'RISK' : 'TREND',
        title: `${pattern.pattern.charAt(0).toUpperCase() + pattern.pattern.slice(1)} Trend Detected`,
