/**
 * React hook for keyboard shortcuts
 */
export function useKeyboardShortcut(
  key: string,
  action: () => void,
  options?: {
    ctrl?: boolean
    shift?: boolean
    alt?: boolean
    meta?: boolean
    description?: string
    category?: KeyboardShortcut['category']
    enabled?: boolean
  }
) {
  if (typeof window === 'undefined') return

  const { useEffect } = require('react')

  useEffect(() => {
    if (options?.enabled === false) return

    const shortcut: KeyboardShortcut = {
      key,
      ctrl: options?.ctrl,
      shift: options?.shift,
      alt: options?.alt,
      meta: options?.meta,
      action,
      description: options?.description || `Shortcut: ${key}`,
      category: options?.category || 'actions',
    }

    const unregister = keyboardShortcuts.register(shortcut)

    return () => {
      unregister()
    }
  }, [key, action, options?.ctrl, options?.shift, options?.alt, options?.meta, options?.enabled])
}

export default keyboardShortcuts

/**
 * Performance Utilities
 * Memoization and optimization helpers
 */

import { useMemo, useCallback } from 'react'

/**
 * Memoize expensive calculations
 */
export function useMemoizedCalculation<T>(
  calculation: () => T,
  dependencies: React.DependencyList
): T {
  return useMemo(calculation, dependencies)
}

/**
 * Memoize callback functions
 */
export function useMemoizedCallback<T extends (...args: any[]) => any>(
  callback: T,
  dependencies: React.DependencyList
): T {
  return useCallback(callback, dependencies) as T
}

/**
 * Debounce function for performance
 */
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout | null = null
  
  return function executedFunction(...args: Parameters<T>) {
    const later = () => {
      timeout = null
      func(...args)
    }
    
    if (timeout) clearTimeout(timeout)
    timeout = setTimeout(later, wait)
  }
}

/**
 * Throttle function for performance
 */
export function throttle<T extends (...args: any[]) => any>(
  func: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle: boolean = false
  
  return function executedFunction(...args: Parameters<T>) {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => {
        inThrottle = false
      }, limit)
    }
  }
}
